package com.modporter.core.transforms.structural

import com.modporter.core.pipeline.*
import com.github.javaparser.JavaParser
import com.github.javaparser.ParserConfiguration
import com.github.javaparser.ast.CompilationUnit
import com.github.javaparser.ast.body.ClassOrInterfaceDeclaration
import com.github.javaparser.ast.body.FieldDeclaration
import com.github.javaparser.ast.body.MethodDeclaration
import com.github.javaparser.ast.body.Parameter
import com.github.javaparser.ast.body.VariableDeclarator
import com.github.javaparser.ast.expr.*
import com.github.javaparser.ast.type.ClassOrInterfaceType
import mu.KotlinLogging
import java.nio.file.Files
import java.nio.file.Path
import kotlin.io.path.*

private val logger = KotlinLogging.logger {}

/**
 * Pass 3: Structural refactoring for complex API migrations.
 * Handles capability system, networking, and other multi-node transformations.
 */
class StructuralRefactorPass : Pass {
    override val name = "Structural Refactor"
    override val order = 3

    override fun analyze(projectDir: Path): PassResult = processFiles(projectDir, dryRun = true)
    override fun apply(projectDir: Path): PassResult = processFiles(projectDir, dryRun = false)

    private fun parseProblems(parseResult: com.github.javaparser.ParseResult<CompilationUnit>): String =
        parseResult.problems.joinToString("; ") { it.verboseMessage }.ifBlank { "unknown parse failure" }

    private fun parserLanguageLevel(parser: JavaParser): String =
        parser.parserConfiguration.languageLevel.toString()

    private fun processFiles(projectDir: Path, dryRun: Boolean): PassResult {
        val changes = mutableListOf<Change>()
        val errors = mutableListOf<String>()
        val skipped = mutableListOf<String>()
        val parser = JavaParser(ParserConfiguration().setLanguageLevel(ParserConfiguration.LanguageLevel.BLEEDING_EDGE))

        val javaFiles = Files.walk(projectDir)
            .filter { it.extension == "java" }
            .filter { !projectDir.relativize(it).toString().replace('\\', '/').let { rel ->
                rel.startsWith("build/") || rel.contains("/build/") ||
                    rel.startsWith("src/references/") || rel.contains("/src/references/")
            }}
            .toList()

        for (file in javaFiles) {
            try {
                val source = file.readText()
                val fileChanges = mutableListOf<Change>()
                val distSource = migrateDistExecutorDistGuards(source, file, fileChanges)
                val parseResult = parser.parse(distSource)
                if (!parseResult.isSuccessful) {
                    changes.addAll(fileChanges)
                    skipped.add(
                        "Could not parse $file for structural transforms " +
                            "(languageLevel=${parserLanguageLevel(parser)}): ${parseProblems(parseResult)}"
                    )
                    if (!dryRun && distSource != source) {
                        file.writeText(distSource)
                    }
                    continue
                }

                val cu = parseResult.result.orElse(null) ?: continue
                val preAstSource = migrateItemStackCapabilityOptionals(distSource, cu, file, fileChanges)
                val migratedParseResult = if (preAstSource != distSource) parser.parse(preAstSource) else parseResult
                if (!migratedParseResult.isSuccessful) {
                    changes.addAll(fileChanges)
                    skipped.add(
                        "Could not parse $file after pre-AST structural rewrites " +
                            "(languageLevel=${parserLanguageLevel(parser)}): ${parseProblems(migratedParseResult)}"
                    )
                    if (!dryRun && preAstSource != source) {
                        file.writeText(preAstSource)
                    }
                    continue
                }
                val migratedCu = migratedParseResult.result.orElse(null) ?: continue

                // Detect and transform capability patterns
                detectCapabilityPatterns(migratedCu, file, fileChanges)

                // Detect and transform networking patterns
                detectNetworkingPatterns(migratedCu, file, fileChanges)

                // Detect LazyOptional usage
                detectLazyOptionalUsage(migratedCu, file, fileChanges)

                // Detect DistExecutor usage (removed in NeoForge)
                detectDistExecutorUsage(migratedCu, file, fileChanges)

                changes.addAll(fileChanges)

                if (!dryRun && fileChanges.isNotEmpty()) {
                    file.writeText(migratedCu.toString())
                }
            } catch (e: Exception) {
                errors.add("Structural analysis error in $file: ${e.message}")
            }
        }

        // Preserve networking helper classes that contain nested Forge SimpleChannel
        // packet definitions before the generic packet pass can replace them.
        try {
            val nestedNetworkChanges = migrateKnownNestedSimpleChannelNetworking(projectDir, dryRun)
            changes.addAll(nestedNetworkChanges)
        } catch (e: Exception) {
            errors.add("Nested SimpleChannel networking migration error: ${e.message}")
        }

        // Transform packet classes to implement CustomPacketPayload + generate ModNetwork.java
        try {
            val packetChanges = transformPacketClasses(projectDir, dryRun)
            changes.addAll(packetChanges)
        } catch (e: Exception) {
            errors.add("Packet class transformation error: ${e.message}")
        }

        // Migrate legacy Nitrogen/Forge packet classes that used BasePacket's
        // instance encode/decode/execute contract onto NeoForge payloads.
        try {
            val basePacketChanges = migrateBasePacketPayloads(projectDir, dryRun)
            changes.addAll(basePacketChanges)
        } catch (e: Exception) {
            errors.add("BasePacket payload migration error: ${e.message}")
        }

        // Remove EVENT_BUS.register(this) from @Mod classes without @SubscribeEvent methods
        try {
            val busChanges = removeEmptyEventBusRegistration(projectDir, dryRun)
            changes.addAll(busChanges)
        } catch (e: Exception) {
            errors.add("Event bus cleanup error: ${e.message}")
        }

        // Migrate FMLJavaModLoadingContext constructor to IEventBus/ModContainer
        try {
            val fmlChanges = migrateFMLJavaModLoadingContext(projectDir, dryRun)
            changes.addAll(fmlChanges)
        } catch (e: Exception) {
            errors.add("FMLJavaModLoadingContext migration error: ${e.message}")
        }

        // Migrate legacy Item#initCapabilities fluid bucket providers to
        // RegisterCapabilitiesEvent item registrations.
        try {
            val bucketCapabilityChanges = migrateFluidBucketItemCapabilities(projectDir, dryRun)
            changes.addAll(bucketCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Fluid bucket capability migration error: ${e.message}")
        }

        // Migrate custom fluid item providers that used Item#initCapabilities
        // and an ICapabilityProvider wrapper around IFluidHandlerItem.
        try {
            val customFluidCapabilityChanges = migrateCustomFluidItemCapabilities(projectDir, dryRun)
            changes.addAll(customFluidCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Custom fluid capability migration error: ${e.message}")
        }

        // Migrate legacy Curios Item#initCapabilities providers to the
        // RegisterCapabilitiesEvent item capability registration model.
        try {
            val curiosCapabilityChanges = migrateCuriosItemCapabilities(projectDir, dryRun)
            changes.addAll(curiosCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Curios item capability migration error: ${e.message}")
        }

        // Migrate legacy custom entity capabilities declared through
        // CapabilityManager + AttachCapabilitiesEvent to NeoForge EntityCapability
        // registrations while preserving LazyOptional call chains.
        try {
            val customEntityCapabilityChanges = migrateCustomEntityCapabilities(projectDir, dryRun)
            changes.addAll(customEntityCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Custom entity capability migration error: ${e.message}")
        }

        // Migrate third-party Nitrogen's old capability sync surface to the
        // attachment/payload surface exposed by its 1.21.1 NeoForge build.
        try {
            val nitrogenChanges = migrateNitrogenAttachmentApi(projectDir, dryRun)
            changes.addAll(nitrogenChanges)
        } catch (e: Exception) {
            errors.add("Nitrogen attachment API migration error: ${e.message}")
        }

        // Migrate block-entity fluid handlers from legacy getCapability()
        // overrides to RegisterCapabilitiesEvent block-entity registrations.
        try {
            val blockEntityFluidCapabilityChanges = migrateBlockEntityFluidCapabilities(projectDir, dryRun)
            changes.addAll(blockEntityFluidCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Block entity fluid capability migration error: ${e.message}")
        }

        // Migrate remaining source-shaped block-entity capability overrides
        // to RegisterCapabilitiesEvent providers. This is intentionally
        // structural: unsupported getCapability shapes are left for strict
        // compile/runtime gates instead of generating a fallback provider.
        try {
            val blockEntityCapabilityChanges = migrateBlockEntityLegacyCapabilities(projectDir, dryRun)
            changes.addAll(blockEntityCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Block entity capability migration error: ${e.message}")
        }

        // Migrate legacy player dirtiness capabilities to NeoForge attachments.
        try {
            val dirtinessCapabilityChanges = migrateDirtinessCapabilityToAttachment(projectDir, dryRun)
            changes.addAll(dirtinessCapabilityChanges)
        } catch (e: Exception) {
            errors.add("Dirtiness capability attachment migration error: ${e.message}")
        }

        // Migrate legacy advancement criterion triggers to the 1.21 codec
        // shape and register trigger types through DeferredRegister.
        try {
            val advancementTriggerChanges = migrateAdvancementCriterionTriggers(projectDir, dryRun)
            changes.addAll(advancementTriggerChanges)
        } catch (e: Exception) {
            errors.add("Advancement criterion trigger migration error: ${e.message}")
        }

        try {
            val conditionCodecChanges = migrateLegacyConditionCodecRegistrations(projectDir, dryRun)
            changes.addAll(conditionCodecChanges)
        } catch (e: Exception) {
            errors.add("Condition codec registration migration error: ${e.message}")
        }

        // Minecraft 1.21 made enchantments registry/data driven. Old subclasses
        // that are no longer constructed after key migration cannot extend the
        // Enchantment record; keep any static helper logic as plain utility code.
        try {
            val legacyEnchantmentChanges = rewriteUnusedLegacyEnchantmentSubclasses(projectDir, dryRun)
            changes.addAll(legacyEnchantmentChanges)
        } catch (e: Exception) {
            errors.add("Legacy enchantment subclass migration error: ${e.message}")
        }

        // NeoForge removed Rarity.create; preserve custom rarity semantics with
        // enum extension metadata and a generated parameter helper.
        try {
            val rarityEnumExtensionChanges = migrateLegacyRarityEnumExtensions(projectDir, dryRun)
            changes.addAll(rarityEnumExtensionChanges)
        } catch (e: Exception) {
            errors.add("Rarity enum extension migration error: ${e.message}")
        }

        try {
            val grassColorEnumExtensionChanges = migrateLegacyGrassColorModifierEnumExtensions(projectDir, dryRun)
            changes.addAll(grassColorEnumExtensionChanges)
        } catch (e: Exception) {
            errors.add("Grass color enum extension migration error: ${e.message}")
        }

        try {
            val recipeBookEnumExtensionChanges = migrateLegacyRecipeBookCategoryEnumExtensions(projectDir, dryRun)
            changes.addAll(recipeBookEnumExtensionChanges)
        } catch (e: Exception) {
            errors.add("Recipe book category enum extension migration error: ${e.message}")
        }

        try {
            val imageButtonChanges = migrateLegacyImageButtonConstructors(projectDir, dryRun)
            changes.addAll(imageButtonChanges)
        } catch (e: Exception) {
            errors.add("Legacy ImageButton constructor migration error: ${e.message}")
        }

        try {
            val curiosClientChanges = migrateCuriosClientApi(projectDir, dryRun)
            changes.addAll(curiosClientChanges)
        } catch (e: Exception) {
            errors.add("Curios client API migration error: ${e.message}")
        }

        // Convert stale Class::register mod-bus listeners to direct
        // DeferredRegister.register(bus) calls when the target class already
        // declares a DeferredRegister field.
        try {
            val deferredRegisterListenerChanges = migrateDeferredRegisterListenerReferences(projectDir, dryRun)
            changes.addAll(deferredRegisterListenerChanges)
        } catch (e: Exception) {
            errors.add("DeferredRegister listener migration error: ${e.message}")
        }

        // Migrate common 1.21 API surface changes that are too broad for
        // project-specific rewrites: split tick events, BlockEntity NBT hooks,
        // tooltip context imports, and Holder<MobEffect> call sites.
        try {
            val commonApiChanges = migrateCommonNeoForge121Apis(projectDir, dryRun)
            changes.addAll(commonApiChanges)
        } catch (e: Exception) {
            errors.add("Common NeoForge 1.21 API migration error: ${e.message}")
        }

        try {
            val entityLevelChanges = migrateEntityLevelAccessorCalls(projectDir, dryRun)
            changes.addAll(entityLevelChanges)
        } catch (e: Exception) {
            errors.add("Entity level accessor migration error: ${e.message}")
        }

        try {
            val cumulusChanges = migrateCumulusMenuApi(projectDir, dryRun)
            changes.addAll(cumulusChanges)
        } catch (e: Exception) {
            errors.add("Cumulus menu API migration error: ${e.message}")
        }

        try {
            val registerAdditionalModelChanges = migrateRegisterAdditionalModelResourceLocations(projectDir, dryRun)
            changes.addAll(registerAdditionalModelChanges)
        } catch (e: Exception) {
            errors.add("RegisterAdditional model migration error: ${e.message}")
        }

        try {
            val deferredRegisterListenerChanges = migrateDeferredRegisterListenerReferences(projectDir, dryRun)
            changes.addAll(deferredRegisterListenerChanges)
        } catch (e: Exception) {
            errors.add("DeferredRegister listener migration error: ${e.message}")
        }

        try {
            val missingMappingChanges = migrateMissingMappingsAliases(projectDir, dryRun)
            changes.addAll(missingMappingChanges)
        } catch (e: Exception) {
            errors.add("MissingMappings alias migration error: ${e.message}")
        }

        // Forge/early-NeoForge built-in pack helpers were removed in 1.21.
        // Preserve their source semantics through explicit PackLocationInfo,
        // PackSelectionConfig, and generated PackResources adapters.
        try {
            val packResourceChanges = migrateLegacyPackResourceApis(projectDir, dryRun)
            changes.addAll(packResourceChanges)
        } catch (e: Exception) {
            errors.add("Legacy pack resource API migration error: ${e.message}")
        }

        try {
            val itemAttributeChanges = migrateLegacyItemAttributeModifierOverrides(projectDir, dryRun)
            changes.addAll(itemAttributeChanges)
        } catch (e: Exception) {
            errors.add("Item attribute modifier migration error: ${e.message}")
        }

        // NeoForge 1.21 deprecates EventBusSubscriber.Bus.MOD. Preserve
        // mod-bus semantics by registering static handlers on the mod event bus.
        try {
            val staticModBusSubscriberChanges = migrateStaticModBusSubscribers(projectDir, dryRun)
            changes.addAll(staticModBusSubscriberChanges)
        } catch (e: Exception) {
            errors.add("Static mod-bus subscriber migration error: ${e.message}")
        }

        // Clean up @EventBusSubscriber: remove from classes without @SubscribeEvent,
        // and remove deprecated bus= parameter
        try {
            val ebsChanges = cleanupEventBusSubscriber(projectDir, dryRun)
            changes.addAll(ebsChanges)
        } catch (e: Exception) {
            errors.add("EventBusSubscriber cleanup error: ${e.message}")
        }

        // Remove orphaned SimpleChannel code once generated payload registration owns it.
        try {
            val netCleanupChanges = cleanupSimpleChannelRemnants(projectDir, dryRun)
            changes.addAll(netCleanupChanges)
        } catch (e: Exception) {
            errors.add("SimpleChannel cleanup error: ${e.message}")
        }

        // Fix static @SubscribeEvent with instance registration:
        // EVENT_BUS.register(this) -> EVENT_BUS.register(ClassName.class) when methods are static
        try {
            val staticBusChanges = fixStaticEventBusRegistration(projectDir, dryRun)
            changes.addAll(staticBusChanges)
        } catch (e: Exception) {
            errors.add("Static EventBus registration fix error: ${e.message}")
        }

        // Migrate Block.use() -> useWithoutItem() (1.20 -> 1.21 API change)
        try {
            val useChanges = migrateBlockUseMethod(projectDir, dryRun)
            changes.addAll(useChanges)
        } catch (e: Exception) {
            errors.add("Block.use() migration error: ${e.message}")
        }

        // Migrate ItemEntityPickupEvent.Pre API changes
        try {
            val pickupChanges = migrateItemPickupEvent(projectDir, dryRun)
            changes.addAll(pickupChanges)
        } catch (e: Exception) {
            errors.add("ItemEntityPickupEvent migration error: ${e.message}")
        }

        // Remove onAddedToWorld() override (removed in 1.21)
        try {
            val removedMethodChanges = removeObsoleteMethods(projectDir, dryRun)
            changes.addAll(removedMethodChanges)
        } catch (e: Exception) {
            errors.add("Obsolete method removal error: ${e.message}")
        }

        // Add codec() override for BaseEntityBlock subclasses
        try {
            val codecChanges = addBaseEntityBlockCodec(projectDir, dryRun)
            changes.addAll(codecChanges)
        } catch (e: Exception) {
            errors.add("BaseEntityBlock codec error: ${e.message}")
        }

        // DropExperienceBlock moved its xp provider before Properties in 1.21.
        // Custom subclasses that simply forward to super must expose the same
        // order, and their constructor call sites must follow it.
        try {
            val dropExperienceChanges = migrateDropExperienceBlockConstructorOrder(projectDir, dryRun)
            changes.addAll(dropExperienceChanges)
        } catch (e: Exception) {
            errors.add("DropExperienceBlock constructor migration error: ${e.message}")
        }

        // StairBlock now takes BlockState directly instead of a supplier. Custom
        // subclasses that only forward the legacy Supplier<BlockState> argument
        // should expose the same constructor boundary as vanilla StairBlock.
        try {
            val stairBlockChanges = migrateStairBlockStateSupplierConstructors(projectDir, dryRun)
            changes.addAll(stairBlockChanges)
        } catch (e: Exception) {
            errors.add("StairBlock constructor migration error: ${e.message}")
        }

        // FlowerBlock now takes Holder<MobEffect> directly. Subclasses that
        // only forward the legacy Supplier<MobEffect> constructor need the same
        // signature, and call sites should pass holder constants directly.
        try {
            val flowerBlockChanges = migrateFlowerBlockMobEffectHolderConstructors(projectDir, dryRun)
            changes.addAll(flowerBlockChanges)
        } catch (e: Exception) {
            errors.add("FlowerBlock constructor migration error: ${e.message}")
        }

        // Migrate old FinishedRecipe-style builder result adapters to the
        // 1.21 RecipeOutput.accept(id, recipe, advancement) contract.
        try {
            val recipeOutputChanges = migrateLegacyRecipeOutputBuilders(projectDir, dryRun)
            changes.addAll(recipeOutputChanges)
        } catch (e: Exception) {
            errors.add("RecipeOutput builder migration error: ${e.message}")
        }

        // Migrate Nitrogen's 1.20 block-state recipe builder source shapes to
        // the 1.21 factory/Optional property-map API. This derives recipe and
        // serializer types from project source declarations instead of package
        // conventions.
        try {
            val nitrogenBuilderChanges = migrateNitrogenRecipeBuilders(projectDir, dryRun)
            changes.addAll(nitrogenBuilderChanges)
        } catch (e: Exception) {
            errors.add("Nitrogen recipe builder migration error: ${e.message}")
        }

        // Recipe ids live on RecipeHolder in 1.21, not on the recipe object.
        try {
            val recipeIdChanges = migrateMmlibRecipeIdTracking(projectDir, dryRun)
            changes.addAll(recipeIdChanges)
        } catch (e: Exception) {
            errors.add("MMLib recipe id tracking migration error: ${e.message}")
        }

        // RegistryObject.isPresent() became DeferredHolder.isBound() after
        // registry holder type migration.
        try {
            val deferredPresenceChanges = migrateDeferredHolderPresenceChecks(projectDir, dryRun)
            changes.addAll(deferredPresenceChanges)
        } catch (e: Exception) {
            errors.add("DeferredHolder presence migration error: ${e.message}")
        }

        // Move client menu screen registration from private MenuScreens.register
        // to NeoForge's RegisterMenuScreensEvent surface.
        try {
            val menuScreenChanges = migrateMenuScreensRegistration(projectDir, dryRun)
            changes.addAll(menuScreenChanges)
        } catch (e: Exception) {
            errors.add("Menu screen registration migration error: ${e.message}")
        }

        // Block.useItemOn now returns ItemInteractionResult. Preserve helper
        // methods that still compute InteractionResult by explicitly mapping it.
        try {
            val itemInteractionChanges = migrateUseItemOnInteractionResultReturns(projectDir, dryRun)
            changes.addAll(itemInteractionChanges)
        } catch (e: Exception) {
            errors.add("ItemInteractionResult return migration error: ${e.message}")
        }

        try {
            val accessorChanges = migrateSourceBackedAccessorCalls(projectDir, dryRun)
            changes.addAll(accessorChanges)
        } catch (e: Exception) {
            errors.add("Source-backed accessor migration error: ${e.message}")
        }

        // Extract client-only @SubscribeEvent methods into @EventBusSubscriber(Dist.CLIENT) inner class
        try {
            val clientEventChanges = extractClientOnlyEventMethods(projectDir, dryRun)
            changes.addAll(clientEventChanges)
        } catch (e: Exception) {
            errors.add("Client event extraction error: ${e.message}")
        }

        // Move mod-bus listener registrations that were accidentally attached
        // to the common NeoForge bus back onto the constructor's mod event bus.
        try {
            val listenerRegistrationChanges = migrateCommonBusModEventListeners(projectDir, dryRun)
            changes.addAll(listenerRegistrationChanges)
        } catch (e: Exception) {
            errors.add("Mod-bus listener registration migration error: ${e.message}")
        }

        // Remove empty @EventBusSubscriber inner classes left over after extraction/cleanup
        try {
            val emptyClassChanges = removeEmptySubscriberClasses(projectDir, dryRun)
            changes.addAll(emptyClassChanges)
        } catch (e: Exception) {
            errors.add("Empty subscriber class removal error: ${e.message}")
        }

        // Final structural normalization: attachment registration methods are
        // ordinary mod-constructor registration helpers, not event handlers.
        try {
            val attachmentRegistrationChanges = cleanupAttachmentRegistrationEventAnnotations(projectDir, dryRun)
            changes.addAll(attachmentRegistrationChanges)
        } catch (e: Exception) {
            errors.add("Attachment registration cleanup error: ${e.message}")
        }

        // Some later project-level rewrites can touch entity sources after the
        // common API pass. Run the accessor migration once more at the end so
        // Entity#getLevel() cannot be reintroduced by write-order effects.
        try {
            val finalEntityLevelChanges = migrateEntityLevelAccessorCalls(projectDir, dryRun)
            changes.addAll(finalEntityLevelChanges)
        } catch (e: Exception) {
            errors.add("Final entity level accessor migration error: ${e.message}")
        }

        // Final source-shape normalization for collection APIs. Some project-level
        // rewrites can run after the common API pass; collection getSize() is only
        // valid when the declared receiver API provides it, not for java.util maps.
        try {
            val finalCollectionSizeChanges = migrateDeclaredCollectionGetSizeCalls(projectDir, dryRun)
            changes.addAll(finalCollectionSizeChanges)
        } catch (e: Exception) {
            errors.add("Final collection size migration error: ${e.message}")
        }

        return PassResult(name, changes, errors, skipped)
    }

    /**
     * Migrate Block.use(BlockState, Level, BlockPos, Player, InteractionHand, BlockHitResult)
     * to Block.useWithoutItem(BlockState, Level, BlockPos, Player, BlockHitResult) in 1.21.1.
     *
     * Changes: method name, visibility public->protected, remove InteractionHand param,
     * remove InteractionHand checks, update super calls.
     */
    /**
     * Fix EVENT_BUS.register(this) when @SubscribeEvent methods are static.
     * NeoForge 1.21.1 requires class registration for static methods.
     */
    /**
     * Clean up orphaned SimpleChannel code after payload registration has been generated.
     * Old SimpleChannel setup is removed once ModNetwork/RegisterPayloadHandlersEvent owns
     * equivalent packet registration.
     */
    private fun cleanupSimpleChannelRemnants(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { javaFile ->
                val text = javaFile.toFile().readText()

                // Only process files where earlier passes removed SimpleChannel or where a
                // generated ModNetwork exists for this source tree.
                val hasGeneratedNetwork = srcDir.resolve(srcDir.relativize(javaFile).parent ?: Path.of(""))
                    .resolve("ModNetwork.java")
                    .exists()
                if (!text.contains("[forge2neo] SimpleChannel") && !hasGeneratedNetwork) return@forEach

                var modified = text

                val lines = modified.lines()
                val cleanedLines = mutableListOf<String>()
                var removedRegisterMessages = false
                for (line in lines) {
                    val trimmed = line.trimStart()
                    val removeLine =
                        Regex("""//\s*T(?:ODO):\s*\[forge2neo]\s*SimpleChannel field removed.*""").matches(trimmed) ||
                            trimmed.startsWith("// [forge2neo] HANDLER removed, packets registered via RegisterPayloadHandlersEvent") ||
                            Regex("""//\s*T(?:ODO):\s*\[forge2neo]\s*registerMessage\(\) removed.*""").matches(trimmed) ||
                            trimmed == "int packetIndex = 0;" && lines.any {
                                it.contains("registerMessage() removed - register via PayloadRegistrar")
                            }
                    if (removeLine) {
                        removedRegisterMessages = true
                    } else {
                        cleanedLines.add(line)
                    }
                }
                if (removedRegisterMessages) {
                    modified = cleanedLines.joinToString("\n")
                }

                // Remove orphaned chain calls: lines starting with .method(...)
                modified = modified.replace(
                    Regex("""^(\s+)(\.[a-zA-Z]+\([^)]*\)[^;\r\n]*;?)""", RegexOption.MULTILINE),
                    ""
                )

                // Remove INSTANCE.xxx calls (messageBuilder, send, etc) after ModNetwork takes over.
                modified = modified.replace(
                    Regex("""^(\s+)(INSTANCE\.[^\r\n]+)""", RegexOption.MULTILINE),
                    ""
                )

                // INSTANCE-only method bodies are handled by the line-by-line removal above.

                if (modified != text) {
                    if (!dryRun) {
                        javaFile.toFile().writeText(modified)
                    }
                    changes.add(Change(
                        file = javaFile,
                        line = 0,
                        description = "Clean up orphaned SimpleChannel code in ${javaFile.fileName}",
                        before = "(orphaned SimpleChannel chain calls)",
                        after = "(removed after ModNetwork migration)",
                        confidence = Confidence.HIGH,
                        ruleId = "structural-simplechannel-cleanup"
                    ))
                }
            }

        return changes
    }

    private fun fixStaticEventBusRegistration(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { javaFile ->
                val text = javaFile.toFile().readText()

                // Check if file has EVENT_BUS.register(this)
                if (!text.contains(".register(this)")) return@forEach

                // Detect outer class name
                val classNameMatch = Regex("""class\s+(\w+)""").find(text) ?: return@forEach
                val className = classNameMatch.groupValues[1]

                // Check if outer class (not inner classes) has @SubscribeEvent methods
                val lines = text.lines()
                var inOuterClass = false
                var braceDepth = 0
                var outerClassDepth = -1
                var hasOuterStaticSubscribeEvent = false
                var hasOuterInstanceSubscribeEvent = false

                for (i in lines.indices) {
                    val line = lines[i]
                    if (!inOuterClass && line.contains("class $className")) {
                        inOuterClass = true
                        outerClassDepth = braceDepth
                    }
                    braceDepth += line.count { it == '{' } - line.count { it == '}' }
                    if (inOuterClass && braceDepth <= outerClassDepth) {
                        break // exited outer class
                    }
                    // Only count @SubscribeEvent in the outer class (depth == outerClassDepth + 1)
                    if (inOuterClass && braceDepth == outerClassDepth + 1) {
                        if (line.trim().startsWith("@SubscribeEvent") && i + 1 < lines.size) {
                            val nextLine = lines[i + 1].trim()
                            if (nextLine.startsWith("public static")) {
                                hasOuterStaticSubscribeEvent = true
                            } else if (nextLine.startsWith("public ") || nextLine.startsWith("private ") || nextLine.startsWith("protected ")) {
                                hasOuterInstanceSubscribeEvent = true
                            }
                        }
                    }
                }

                var modified = text
                if (hasOuterStaticSubscribeEvent && !hasOuterInstanceSubscribeEvent) {
                    // All @SubscribeEvent methods are static: register the class
                    modified = text.replace(
                        Regex("""(EVENT_BUS|NeoForge\.EVENT_BUS)\.register\(this\)"""),
                        "$1.register(${className}.class)"
                    )
                    if (modified != text) {
                        changes.add(Change(
                            file = javaFile, line = 0,
                            description = "Fix static @SubscribeEvent: register(this) -> register(${className}.class)",
                            before = "EVENT_BUS.register(this)",
                            after = "EVENT_BUS.register(${className}.class)",
                            confidence = Confidence.HIGH,
                            ruleId = "structural-static-event-bus-register"
                        ))
                    }
                } else if (!hasOuterStaticSubscribeEvent && !hasOuterInstanceSubscribeEvent) {
                    // No @SubscribeEvent in outer class — remove the register(this) call
                    modified = modified.replace(
                        Regex("""[ \t]*(NeoForge\.)?EVENT_BUS\.register\(this\);\s*\r?\n"""),
                        ""
                    )
                    if (modified != text) {
                        changes.add(Change(
                            file = javaFile, line = 0,
                            description = "Remove EVENT_BUS.register(this) — no @SubscribeEvent methods in ${className}",
                            before = "EVENT_BUS.register(this)",
                            after = "// Removed: no @SubscribeEvent in outer class",
                            confidence = Confidence.HIGH,
                            ruleId = "structural-remove-event-bus-register"
                        ))
                    }
                }
                // If hasOuterInstanceSubscribeEvent, keep register(this) as-is

                if (modified != text && !dryRun) {
                    javaFile.toFile().writeText(modified)
                }
            }

        return changes
    }

    private fun migrateBlockUseMethod(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { javaFile ->
                val text = javaFile.toFile().readText()

                // Match Block.use() override signature with 6 params (BlockState, Level, BlockPos, Player, InteractionHand, BlockHitResult)
                val useMethodPattern = Regex(
                    """([ \t]*@(?:SuppressWarnings\([^)]*\)\s*\r?\n\s*@)?Override\s*\r?\n)?""" +
                    """([ \t]*)(?:public\s+)(@?\s*\w+(?:<[^>]+>)?\s+)use\s*\(\s*""" +
                    """(\w+)\s+(\w+)\s*,\s*""" +     // BlockState param
                    """(\w+)\s+(\w+)\s*,\s*""" +     // Level/World param
                    """(\w+)\s+(\w+)\s*,\s*""" +     // BlockPos param
                    """(\w+)\s+(\w+)\s*,\s*""" +     // Player param
                    """(\w+)\s+(\w+)\s*,\s*""" +     // InteractionHand param
                    """(\w+)\s+(\w+)\s*\)""",        // BlockHitResult param
                    RegexOption.MULTILINE
                )

                if (!useMethodPattern.containsMatchIn(text)) return@forEach

                var modified = text
                val match = useMethodPattern.find(modified) ?: return@forEach

                val indent = match.groupValues[2]
                val returnType = match.groupValues[3]
                val stateType = match.groupValues[4]; val stateName = match.groupValues[5]
                val levelType = match.groupValues[6]; val levelName = match.groupValues[7]
                val posType = match.groupValues[8]; val posName = match.groupValues[9]
                val playerType = match.groupValues[10]; val playerName = match.groupValues[11]
                val handType = match.groupValues[12]
                val handName = match.groupValues[13]
                val hitType = match.groupValues[14]; val hitName = match.groupValues[15]
                val openBrace = modified.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(modified, openBrace) else -1
                val methodBody = if (openBrace >= 0 && closeBrace > openBrace) {
                    modified.substring(openBrace + 1, closeBrace)
                } else {
                    ""
                }
                val usesHeldItem = methodBody.contains(handName) ||
                    methodBody.contains("getItemInHand(") ||
                    methodBody.contains("getMainHandItem()") ||
                    Regex("""\bItemStack\b""").containsMatchIn(methodBody)

                if (usesHeldItem && openBrace >= 0 && closeBrace > openBrace) {
                    val newSig = "${indent}@Override\n${indent}protected net.minecraft.world.ItemInteractionResult useItemOn(" +
                        "net.minecraft.world.item.ItemStack itemstack, $stateType $stateName, $levelType $levelName, " +
                        "$posType $posName, $playerType $playerName, $handType $handName, $hitType $hitName)"

                    var newBody = methodBody
                    newBody = Regex(
                        """(?m)^([ \t]*)(?:net\.minecraft\.world\.item\.)?ItemStack\s+itemstack\s*=\s*$playerName\.(?:getItemInHand\(\s*$handName\s*\)|getMainHandItem\(\s*\));\s*\r?\n"""
                    ).replace(newBody, "")
                    newBody = Regex(
                        """(?m)^([ \t]*)(?:net\.minecraft\.world\.item\.)?ItemStack\s+([A-Za-z_$][\w$]*)\s*=\s*$playerName\.(?:getItemInHand\(\s*$handName\s*\)|getMainHandItem\(\s*\));"""
                    ).replace(newBody, "$1net.minecraft.world.item.ItemStack $2 = itemstack;")
                    newBody = newBody
                        .replace("InteractionResult.sidedSuccess(", "net.minecraft.world.ItemInteractionResult.sidedSuccess(")
                        .replace("InteractionResult.PASS", "net.minecraft.world.ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION")
                        .replace("InteractionResult.CONSUME", "net.minecraft.world.ItemInteractionResult.CONSUME")
                        .replace("InteractionResult.SUCCESS", "net.minecraft.world.ItemInteractionResult.SUCCESS")
                        .replace("InteractionResult.FAIL", "net.minecraft.world.ItemInteractionResult.FAIL")
                        .replace(
                            Regex("""super\.use\(\s*$stateName\s*,\s*$levelName\s*,\s*$posName\s*,\s*$playerName\s*,\s*$handName\s*,\s*$hitName\s*\)"""),
                            "super.useItemOn(itemstack, $stateName, $levelName, $posName, $playerName, $handName, $hitName)"
                        )

                    modified = modified.substring(0, match.range.first) +
                        newSig +
                        modified.substring(match.range.last + 1, openBrace + 1) +
                        newBody +
                        modified.substring(closeBrace)
                } else {
                    // Build new method signature (without InteractionHand param)
                    val newSig = "${indent}@Override\n${indent}protected ${returnType}useWithoutItem(" +
                        "$stateType $stateName, $levelType $levelName, $posType $posName, " +
                        "$playerType $playerName, $hitType $hitName)"

                    modified = modified.replace(match.value, newSig)

                    // Remove InteractionHand-related checks: if(hand==InteractionHand.MAIN_HAND) or similar
                    // Handle "if ... && hand==InteractionHand.MAIN_HAND" by removing the hand condition
                    modified = modified.replace(
                        Regex("""&&\s*$handName\s*==\s*InteractionHand\.\w+"""), ""
                    )
                    modified = modified.replace(
                        Regex("""$handName\s*==\s*InteractionHand\.\w+\s*&&\s*"""), ""
                    )
                    modified = unwrapStandaloneInteractionHandChecks(modified, handName)

                    // Update super.use(...) calls to super.useWithoutItem(...) removing hand param
                    modified = modified.replace(
                        Regex("""super\.use\(\s*$stateName\s*,\s*$levelName\s*,\s*$posName\s*,\s*$playerName\s*,\s*$handName\s*,\s*$hitName\s*\)"""),
                        "super.useWithoutItem($stateName, $levelName, $posName, $playerName, $hitName)"
                    )
                }

                // Remove unused InteractionHand import if no other references remain
                if (!modified.contains("InteractionHand") ||
                    modified.lines().none { it.trim().let { t -> !t.startsWith("import") && !t.startsWith("//") && t.contains("InteractionHand") } }) {
                    modified = modified.replace(
                        Regex("""^import\s+net\.minecraft\.world\.InteractionHand\s*;\s*\r?\n""", RegexOption.MULTILINE),
                        ""
                    )
                }

                // Remove @SuppressWarnings("deprecation") that was before the old @Override
                // (useWithoutItem is not deprecated, so the suppression is no longer needed)

                if (modified != text) {
                    if (!dryRun) {
                        javaFile.toFile().writeText(modified)
                    }
                    changes.add(Change(
                        file = javaFile,
                        line = 0,
                        description = "Migrate Block.use() to 1.21 block interaction hook in ${javaFile.fileName}",
                        before = "public InteractionResult use(..., InteractionHand, BlockHitResult)",
                        after = if (usesHeldItem) {
                            "protected ItemInteractionResult useItemOn(ItemStack, ..., InteractionHand, BlockHitResult)"
                        } else {
                            "protected InteractionResult useWithoutItem(..., BlockHitResult)"
                        },
                        confidence = Confidence.HIGH,
                        ruleId = "structural-block-use-to-useWithoutItem"
                    ))
                }
            }

        return changes
    }

    /**
     * Detect ICapabilityProvider implementations and flag for migration.
     */
    private fun detectCapabilityPatterns(
        cu: CompilationUnit,
        file: Path,
        changes: MutableList<Change>
    ) {
        cu.findAll(ClassOrInterfaceDeclaration::class.java).forEach { classDecl ->
            // Check if implements ICapabilityProvider
            val hasCapProvider = classDecl.implementedTypes.any {
                it.nameAsString == "ICapabilityProvider"
            }

            if (hasCapProvider) {
                val line = classDecl.begin.map { it.line }.orElse(0)
                changes.add(Change(
                    file = file, line = line,
                    description = "CLASS IMPLEMENTS ICapabilityProvider - needs migration to RegisterCapabilitiesEvent pattern",
                    before = "class ${classDecl.nameAsString} implements ICapabilityProvider",
                    after = "Register the provider through RegisterCapabilitiesEvent and remove ICapabilityProvider from the class",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-capability-provider"
                ))
            }

            // Detect getCapability method overrides
            classDecl.methods.filter { it.nameAsString == "getCapability" }.forEach { method ->
                val methodLine = method.begin.map { it.line }.orElse(0)
                changes.add(Change(
                    file = file, line = methodLine,
                    description = "getCapability() override detected - migrate to RegisterCapabilitiesEvent provider lambda",
                    before = method.declarationAsString,
                    after = "// Register via: event.registerBlockEntity(Capabilities.XXX, MY_TYPE, (be, side) -> ...)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-capability-getcap"
                ))
            }
        }
    }

    /**
     * Detect SimpleChannel / networking patterns and flag for migration.
     */
    private fun detectNetworkingPatterns(
        cu: CompilationUnit,
        file: Path,
        changes: MutableList<Change>
    ) {
        // Detect SimpleChannel field declarations
        cu.findAll(FieldDeclaration::class.java).forEach { field ->
            val typeStr = field.elementType.toString()
            if (typeStr.contains("SimpleChannel") || typeStr.contains("EventNetworkChannel")) {
                val line = field.begin.map { it.line }.orElse(0)
                changes.add(Change(
                    file = file, line = line,
                    description = "SimpleChannel/EventNetworkChannel detected - migrate to CustomPacketPayload system",
                    before = field.toString().trim(),
                    after = "Replace with CustomPacketPayload types and RegisterPayloadHandlersEvent registration",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-networking-channel"
                ))
            }
        }

        // Detect NetworkRegistry.newSimpleChannel calls
        cu.findAll(MethodCallExpr::class.java).forEach { call ->
            if (call.nameAsString == "newSimpleChannel" || call.nameAsString == "registerMessage") {
                val line = call.begin.map { it.line }.orElse(0)
                changes.add(Change(
                    file = file, line = line,
                    description = "Network registration call detected - migrate to RegisterPayloadHandlersEvent",
                    before = call.toString(),
                    after = "// Register via: event.registrar(MODID).playToServer(TYPE, CODEC, HANDLER)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-networking-register"
                ))
            }
        }
    }

    /**
     * Detect DistExecutor usage (removed in NeoForge 1.21.1).
     * DistExecutor.unsafeRunWhenOn/safeRunWhenOn should be replaced with direct if (FMLLoader.getDist() == Dist.CLIENT) checks.
     */
    private fun migrateDistExecutorDistGuards(
        source: String,
        file: Path,
        changes: MutableList<Change>
    ): String {
        var result = source
        var migrated = false

        val enqueueExpressionPattern = Regex(
            """(?m)^([ \t]*)([\w.]+\.enqueueWork\(\s*)\(\s*\)\s*->\s*DistExecutor\.(unsafeRunWhenOn|safeRunWhenOn)\(\s*Dist\.(CLIENT|DEDICATED_SERVER)\s*,\s*\(\s*\)\s*->\s*\(\s*\)\s*->\s*([^{};]+?)\s*\)\s*\)\s*;"""
        )
        val beforeExpressionMigration = result
        result = enqueueExpressionPattern.replace(beforeExpressionMigration) { match ->
            val indent = match.groupValues[1]
            val enqueueCall = match.groupValues[2]
            val methodName = match.groupValues[3]
            val dist = match.groupValues[4]
            val expression = match.groupValues[5].trim()
            val expressionStatement = expression
                .lines()
                .filter { it.isNotBlank() }
                .joinToString("\n") { "$indent        ${it.trim()}" }
                .let { if (it.endsWith(";")) it else "$it;" }
            val replacement = """
${indent}${enqueueCall}() -> {
${indent}    if (FMLLoader.getDist() == Dist.$dist) {
$expressionStatement
${indent}    }
${indent}});
""".trimEnd()
            migrated = true
            changes.add(distExecutorMigrationChange(
                file = file,
                line = lineNumberAt(beforeExpressionMigration, match.range.first),
                methodName = methodName,
                dist = dist,
                before = match.value.trim(),
                after = replacement.trim()
            ))
            replacement
        }

        val directExpressionPattern = Regex(
            """(?m)^([ \t]*)DistExecutor\.(unsafeRunWhenOn|safeRunWhenOn)\(\s*Dist\.(CLIENT|DEDICATED_SERVER)\s*,\s*\(\s*\)\s*->\s*\(\s*\)\s*->\s*([^{};\r\n]+)\s*\)\s*;"""
        )
        val beforeDirectExpressionMigration = result
        result = directExpressionPattern.replace(beforeDirectExpressionMigration) { match ->
            val indent = match.groupValues[1]
            val methodName = match.groupValues[2]
            val dist = match.groupValues[3]
            val expression = match.groupValues[4].trim()
            val statement = if (expression.endsWith(";")) expression else "$expression;"
            val replacement = """
${indent}if (FMLLoader.getDist() == Dist.$dist) {
${indent}    $statement
${indent}}
""".trimEnd()
            migrated = true
            changes.add(distExecutorMigrationChange(
                file = file,
                line = lineNumberAt(beforeDirectExpressionMigration, match.range.first),
                methodName = methodName,
                dist = dist,
                before = match.value.trim(),
                after = replacement.trim()
            ))
            replacement
        }

        val methodReferencePattern = Regex(
            """(?m)^([ \t]*)DistExecutor\.(unsafeRunWhenOn|safeRunWhenOn)\(\s*Dist\.(CLIENT|DEDICATED_SERVER)\s*,\s*\(\s*\)\s*->\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)::([A-Za-z_$][\w$]*)\s*\)\s*;"""
        )
        val beforeMethodReferenceMigration = result
        result = methodReferencePattern.replace(beforeMethodReferenceMigration) { match ->
            val indent = match.groupValues[1]
            val methodName = match.groupValues[2]
            val dist = match.groupValues[3]
            val owner = match.groupValues[4]
            val referencedMethod = match.groupValues[5]
            val replacement = """
${indent}if (FMLLoader.getDist() == Dist.$dist) {
${indent}    $owner.$referencedMethod();
${indent}}
""".trimEnd()
            migrated = true
            changes.add(distExecutorMigrationChange(
                file = file,
                line = lineNumberAt(beforeMethodReferenceMigration, match.range.first),
                methodName = methodName,
                dist = dist,
                before = match.value.trim(),
                after = replacement.trim()
            ))
            replacement
        }

        val blockStatementPattern = Regex(
            """(?m)^([ \t]*)DistExecutor\.(unsafeRunWhenOn|safeRunWhenOn)\(\s*Dist\.(CLIENT|DEDICATED_SERVER)\s*,\s*\(\s*\)\s*->\s*\(\s*\)\s*->\s*\{\s*\r?\n([\s\S]*?)\r?\n\1\}\s*\)\s*;"""
        )
        val beforeBlockMigration = result
        result = blockStatementPattern.replace(beforeBlockMigration) { match ->
            val indent = match.groupValues[1]
            val methodName = match.groupValues[2]
            val dist = match.groupValues[3]
            val body = match.groupValues[4].trimEnd()
            val replacement = """
${indent}if (FMLLoader.getDist() == Dist.$dist) {
$body
${indent}}
""".trimEnd()
            migrated = true
            changes.add(distExecutorMigrationChange(
                file = file,
                line = lineNumberAt(beforeBlockMigration, match.range.first),
                methodName = methodName,
                dist = dist,
                before = match.value.trim(),
                after = replacement.trim()
            ))
            replacement
        }

        val runForDistClientBlockPattern = Regex(
            """(?m)^([ \t]*)DistExecutor\.(unsafeRunForDist|safeRunForDist)\(\s*\(\s*\)\s*->\s*\(\s*\)\s*->\s*\{\s*\r?\n([\s\S]*?)\r?\n\1\}\s*,\s*\(\s*\)\s*->\s*\(\s*\)\s*->\s*(?:false|true|null)\s*\)\s*;"""
        )
        val beforeRunForDistMigration = result
        result = runForDistClientBlockPattern.replace(beforeRunForDistMigration) { match ->
            val indent = match.groupValues[1]
            val methodName = match.groupValues[2]
            val body = removeTrailingSupplierReturn(match.groupValues[3]).trimEnd()
            val replacement = if (body.isBlank()) {
                """
${indent}if (FMLLoader.getDist() == Dist.CLIENT) {
${indent}}
""".trimEnd()
            } else {
                """
${indent}if (FMLLoader.getDist() == Dist.CLIENT) {
$body
${indent}}
""".trimEnd()
            }
            migrated = true
            changes.add(distExecutorMigrationChange(
                file = file,
                line = lineNumberAt(beforeRunForDistMigration, match.range.first),
                methodName = methodName,
                dist = "CLIENT",
                before = match.value.trim(),
                after = replacement.trim()
            ))
            replacement
        }

        if (!migrated) return result
        result = removeDistExecutorImports(result)
        result = addImportIfMissing(result, "net.neoforged.api.distmarker.Dist")
        return addImportIfMissing(result, "net.neoforged.fml.loading.FMLLoader")
    }

    private fun removeTrailingSupplierReturn(body: String): String {
        val lines = body.lines().toMutableList()
        var index = lines.lastIndex
        while (index >= 0 && lines[index].isBlank()) index--
        if (index >= 0 && Regex("""^\s*return\s+[^;]+;\s*$""").matches(lines[index])) {
            lines.removeAt(index)
        }
        return lines.joinToString("\n")
    }

    private fun distExecutorMigrationChange(
        file: Path,
        line: Int,
        methodName: String,
        dist: String,
        before: String,
        after: String
    ): Change = Change(
        file = file,
        line = line,
        description = "Convert DistExecutor.$methodName(Dist.$dist) to FMLLoader dist guard",
        before = before,
        after = after,
        confidence = Confidence.HIGH,
        ruleId = "struct-dist-executor-dist-guard"
    )

    private fun removeDistExecutorImports(source: String): String {
        var result = source
        result = result.replace(
            Regex("""(?m)^[ \t]*(?://\s*\[forge2neo]\s*)?import\s+net\.(?:minecraftforge|neoforged)\.fml\.DistExecutor;\s*\r?\n"""),
            ""
        )
        result = result.replace(
            Regex("""(?m)^[ \t]*//\s*DistExecutor removed in NeoForge\s*\r?\n"""),
            ""
        )
        return result
    }

    private fun unwrapStandaloneInteractionHandChecks(source: String, handName: String): String {
        var result = source
        val condition = Regex.escape(handName) + """\s*==\s*InteractionHand\.\w+"""
        val ifRegex = Regex("""if\s*\(\s*$condition\s*\)\s*\{""")
        var cursor = 0
        while (true) {
            val match = ifRegex.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val after = result.substring(closeBrace + 1).trimStart()
            if (after.startsWith("else")) {
                cursor = closeBrace + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            result = result.substring(0, match.range.first) + body + result.substring(closeBrace + 1)
            cursor = match.range.first + body.length
        }
        result = Regex("""if\s*\(\s*$condition\s*\)\s*([^;\r\n]+;)""")
            .replace(result) { match -> match.groupValues[1] }
        return result
    }

    private fun addImportIfMissing(source: String, importName: String): String {
        if (source.contains("import $importName;")) return source
        val importLine = "import $importName;\n"
        val lastImport = Regex("""^import\s+[^;]+;""", RegexOption.MULTILINE)
            .findAll(source)
            .lastOrNull()
        if (lastImport != null) {
            val insertPos = lastImport.range.last + 1
            return source.substring(0, insertPos) + "\n" + importLine + source.substring(insertPos)
        }

        val packageDecl = Regex("""^package\s+[^;]+;""", RegexOption.MULTILINE).find(source)
        if (packageDecl != null) {
            val insertPos = packageDecl.range.last + 1
            return source.substring(0, insertPos) + "\n\n" + importLine + source.substring(insertPos)
        }

        return importLine + source
    }

    private fun removeImportIfPresent(source: String, importName: String): String =
        Regex("""(?m)^[ \t]*import\s+${Regex.escape(importName)};\s*\r?\n""")
            .replace(source, "")

    private fun annotationStartBefore(source: String, declarationIndex: Int): Int {
        val lineStart = source.lastIndexOf('\n', declarationIndex).let { if (it < 0) 0 else it + 1 }
        val annotations = Regex("""(?m)(?:^[ \t]*@[A-Za-z0-9_.]+(?:\([^)]*\))?\s*\r?\n)+[ \t]*$""")
            .findAll(source.substring(0, lineStart))
            .lastOrNull()
        return annotations?.range?.first ?: lineStart
    }

    private fun lineNumberAt(source: String, offset: Int): Int =
        source.take(offset).count { it == '\n' } + 1

    private fun detectDistExecutorUsage(
        cu: CompilationUnit,
        file: Path,
        changes: MutableList<Change>
    ) {
        cu.findAll(MethodCallExpr::class.java).forEach { call ->
            val scope = call.scope.map { it.toString() }.orElse("")
            if (scope == "DistExecutor" || scope.endsWith(".DistExecutor")) {
                val line = call.begin.map { it.line }.orElse(0)
                changes.add(Change(
                    file = file, line = line,
                    description = "DistExecutor.${call.nameAsString}() REMOVED - replace with if (FMLLoader.getDist() == Dist.CLIENT) pattern",
                    before = call.toString(),
                    after = "// Replace with: if (FMLLoader.getDist() == Dist.CLIENT) { ... }",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-dist-executor"
                ))
            }
        }
    }

    /**
     * Data class for packet class detection.
     */
    private data class PacketClassInfo(
        val file: Path,
        val className: String,
        val packageName: String,
        val encodeParamName: String,
        val encodeBufferName: String,
        val handlerRef: String,
        val isPlayToClient: Boolean,
        val bufferType: String,
        val streamCodecExpression: String,
        val registrationMethod: String? = null
    )

    private fun addCustomPacketPayloadInterface(content: String, className: String): String {
        val escapedClass = Regex.escape(className)
        val classPattern = Regex("""(public\s+class\s+$escapedClass)\s*\{""")
        val classMigrated = classPattern.replace(content, "$1 implements CustomPacketPayload\n{")
        if (classMigrated != content) return classMigrated

        val recordPattern = Regex("""(public\s+record\s+$escapedClass\s*\([\s\S]*?\))\s*\{""")
        return recordPattern.replace(content, "$1 implements CustomPacketPayload {")
    }

    private fun payloadHandlerLambda(handlerExpression: String): String {
        val methodRef = Regex("""^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)::([A-Za-z_$][\w$]*)$""")
            .find(handlerExpression.trim())
            ?: return handlerExpression
        return "(payload, context) -> ${methodRef.groupValues[1]}.${methodRef.groupValues[2]}(payload, context)"
    }

    private fun findTypeOpenBrace(content: String, className: String): Int {
        val typeStart = Regex("""\bpublic\s+(?:(?:static|abstract|final|sealed|non-sealed)\s+)*(?:class|record)\s+${Regex.escape(className)}\b""")
            .find(content)
            ?.range
            ?.first
            ?: return -1
        return content.indexOf('{', typeStart)
    }

    private fun migrateLegacyPayloadHandlerContext(
        content: String,
        info: PacketClassInfo,
        changes: MutableList<Change>
    ): String {
        val contextVars = mutableSetOf<String>()
        val handlerContextPattern = Regex(
            """(public\s+static\s+void\s+handle\s*\(\s*${Regex.escape(info.className)}\s+\w+\s*,\s*)(?:IPayloadContext|Supplier\s*<\s*NetworkEvent\.Context\s*>)\s+(\w+)(\s*\)\s*\{\s*)\r?\n[ \t]*NetworkEvent\.Context\s+(\w+)\s*=\s*\2\.get\(\);\s*\r?\n"""
        )

        val migrated = handlerContextPattern.replace(content) { match ->
            val contextVar = match.groupValues[4]
            contextVars.add(contextVar)
            "${match.groupValues[1]}IPayloadContext $contextVar${match.groupValues[3]}\n"
        }
        if (migrated == content) return content

        var result = migrated
        contextVars.forEach { contextVar ->
            result = result.replace(
                Regex("""(?m)^([ \t]*)ServerPlayer\s+(\w+)\s*=\s*${Regex.escape(contextVar)}\.getSender\(\);\s*\r?\n\1if\s*\(\s*\2\s*!=\s*null\s*\)\s*\{"""),
                "$1if ($contextVar.player() instanceof ServerPlayer $2) {"
            )
            result = result.replace("${contextVar}.getSender()", "${contextVar}.player()")
            result = result.replace(
                Regex("""(?m)^[ \t]*${Regex.escape(contextVar)}\.setPacketHandled\(true\);\s*\r?\n"""),
                ""
            )
        }

        changes.add(Change(
            file = info.file,
            line = handlerContextPattern.find(content)?.let { lineNumberAt(content, it.range.first) } ?: 1,
            description = "Migrate ${info.className} packet handler from NetworkEvent.Context to IPayloadContext",
            before = "NetworkEvent.Context context = contextSupplier.get(); ... context.setPacketHandled(true);",
            after = "handle(${info.className} packet, IPayloadContext context) { context.enqueueWork(...); }",
            confidence = Confidence.HIGH,
            ruleId = "struct-packet-payload-context"
        ))
        return result
    }

    private fun cleanupLegacyPayloadContextReferences(
        content: String,
        info: PacketClassInfo,
        changes: MutableList<Change>
    ): String {
        var result = content
        val original = result
        val firstMatch = Regex("""\b\w+\.get\(\)\.(?:getDirection|getSender|setPacketHandled)\b""")
            .find(content)

        result = Regex(
            """(?m)^[ \t]*if\s*\(\s*!\s*\w+\.get\(\)\.getDirection\(\)\.getReceptionSide\(\)\.is(?:Server|Client)\(\)\s*\)\s*return;\s*\r?\n"""
        ).replace(result, "")
        result = Regex("""\b(\w+)\.get\(\)\.getSender\(\)""")
            .replace(result) { match -> "${match.groupValues[1]}.player()" }
        result = Regex("""(?m)^[ \t]*\w+\.get\(\)\.setPacketHandled\(true\);\s*\r?\n""")
            .replace(result, "")
        result = removeImportIfPresent(result, "java.util.function.Supplier")

        if (result != original) {
            changes.add(Change(
                file = info.file,
                line = firstMatch?.let { lineNumberAt(content, it.range.first) } ?: 1,
                description = "Remove legacy NetworkEvent.Context supplier calls after IPayloadContext migration",
                before = "ctx.get().getDirection()/getSender()/setPacketHandled(true)",
                after = "directional PayloadRegistrar registration + IPayloadContext.player()",
                confidence = Confidence.HIGH,
                ruleId = "struct-packet-payload-context-cleanup"
            ))
        }
        return result
    }

    private fun migrateKnownNestedSimpleChannelNetworking(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .forEach { file ->
                val text = file.readText()
                val packageName = packageNameOf(text)
                val fileName = file.fileName.toString()
                val modAccess = inferModAccess(text) ?: return@forEach
                val migrated = when {
                    fileName == "CustomFluidNetworking.java" &&
                        text.contains("SimpleChannel") &&
                        text.contains("SyncCustomFluidsPacket") &&
                        text.contains("serializeAllFluids") &&
                        modAccess.loggerExpression != null ->
                        customFluidNetworkingPayloadSource(packageName, modAccess)

                    fileName == "DirtinessNetworking.java" &&
                        text.contains("SimpleChannel") &&
                        text.contains("SyncDirtinessPacket") &&
                        text.contains("SyncOtherPlayerDirtinessPacket") ->
                        dirtinessNetworkingPayloadSource(packageName, modAccess)

                    else -> null
                } ?: return@forEach

                if (!dryRun) {
                    file.writeText(migrated)
                }
                changes.add(Change(
                    file = file,
                    line = 1,
                    description = "Migrate nested SimpleChannel packets in $fileName to inline CustomPacketPayload records",
                    before = "SimpleChannel + static inner packet classes",
                    after = "RegisterPayloadHandlersEvent + payload records + PacketDistributor helpers",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-nested-simplechannel-payloads"
                ))
            }

        return changes
    }

    private data class ModAccess(
        val modIdExpression: String,
        val modImport: String?,
        val loggerExpression: String?
    ) {
        fun importLine(): String = modImport?.let { "import $it;\n" } ?: ""
    }

    private data class RegistryAliasRule(val kind: String, val oldPattern: String, val newPattern: String)

    private data class RegistryAliasEntry(val registryRef: String, val oldId: String, val newId: String)

    private data class RegistryFieldInfo(
        val kind: String,
        val className: String,
        val qualifiedClassName: String,
        val fieldName: String,
        val registeredNames: Set<String>
    ) {
        val ref: String = "$className.$fieldName"
    }

    private fun inferModAccess(source: String): ModAccess? {
        val modIdExpression = Regex("""\b([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\.(?:MOD_ID|MODID|ID)\b""")
            .find(source)
            ?.value
            ?: return null
        val modClass = modIdExpression.substringBefore('.')
        val modImport = Regex("""(?m)^[ \t]*import\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.${Regex.escape(modClass)})\s*;\s*$""")
            .find(source)
            ?.groupValues
            ?.get(1)
        val loggerExpression = Regex("""\b([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\.LOGGER\b""")
            .find(source)
            ?.value
        return ModAccess(modIdExpression, modImport, loggerExpression)
    }

    private fun customFluidNetworkingPayloadSource(packageName: String, modAccess: ModAccess): String = """package $packageName;

${modAccess.importLine()}import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonObject;
import com.mojang.serialization.JsonOps;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.network.PacketDistributor;
import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.handling.IPayloadContext;
import net.neoforged.neoforge.network.registration.PayloadRegistrar;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

@EventBusSubscriber(modid = ${modAccess.modIdExpression}, bus = EventBusSubscriber.Bus.MOD)
public class CustomFluidNetworking {
    private static final Gson GSON = new GsonBuilder().create();

    public static final ResourceLocation SYNC_CUSTOM_FLUIDS_ID =
            ResourceLocation.fromNamespaceAndPath(${modAccess.modIdExpression}, "sync_custom_fluids");

    public record SyncCustomFluidsPayload(List<String> fluidJsons) implements CustomPacketPayload {
        public static final Type<SyncCustomFluidsPayload> TYPE =
                new Type<>(SYNC_CUSTOM_FLUIDS_ID);

        public static final StreamCodec<FriendlyByteBuf, SyncCustomFluidsPayload> STREAM_CODEC =
                StreamCodec.composite(
                        ByteBufCodecs.STRING_UTF8.apply(ByteBufCodecs.list()),
                        SyncCustomFluidsPayload::fluidJsons,
                        SyncCustomFluidsPayload::new
                );

        @Override
        public Type<? extends CustomPacketPayload> type() {
            return TYPE;
        }
    }

    @SubscribeEvent
    public static void registerPayloads(RegisterPayloadHandlersEvent event) {
        PayloadRegistrar registrar = event.registrar(${modAccess.modIdExpression});
        registrar.playToClient(
                SyncCustomFluidsPayload.TYPE,
                SyncCustomFluidsPayload.STREAM_CODEC,
                CustomFluidNetworking::handleSyncOnClient
        );
    }

    private static void handleSyncOnClient(SyncCustomFluidsPayload payload, IPayloadContext context) {
        context.enqueueWork(() -> {
            ${modAccess.loggerExpression}.info("Received {} custom fluid definitions from server", payload.fluidJsons().size());

            CustomFluidRegistry.clearClientSide();

            int successCount = 0;
            for (String json : payload.fluidJsons()) {
                try {
                    JsonObject jsonObject = GSON.fromJson(json, JsonObject.class);
                    CustomFluidDefinition definition = CustomFluidDefinition.CODEC
                            .parse(JsonOps.INSTANCE, jsonObject)
                            .resultOrPartial(error -> ${modAccess.loggerExpression}.warn("Failed to parse synced fluid: {}", error))
                            .orElse(null);

                    if (definition != null) {
                        CustomFluidRegistry.registerClientSide(definition);
                        definition.registerTranslations();
                        successCount++;
                    }
                } catch (Exception e) {
                    ${modAccess.loggerExpression}.error("Error deserializing custom fluid from server: {}", e.getMessage());
                }
            }

            ${modAccess.loggerExpression}.info("Client registered {} custom fluids from server", successCount);
            CustomFluidClientEvents.updateAllCustomFluidLights();
        });
    }

    public static void register() {
    }

    public static void syncToClient(ServerPlayer player) {
        List<String> fluidJsons = serializeAllFluids();

        if (fluidJsons.isEmpty()) {
            ${modAccess.loggerExpression}.debug("No custom fluids to sync to player {}", player.getName().getString());
            return;
        }

        SyncCustomFluidsPayload payload = new SyncCustomFluidsPayload(fluidJsons);
        PacketDistributor.sendToPlayer(player, payload);
        ${modAccess.loggerExpression}.info("Synced {} custom fluids to player {}",
                fluidJsons.size(), player.getName().getString());
    }

    public static void syncToAllClients(Iterable<ServerPlayer> players) {
        List<String> fluidJsons = serializeAllFluids();

        if (fluidJsons.isEmpty()) {
            return;
        }

        SyncCustomFluidsPayload payload = new SyncCustomFluidsPayload(fluidJsons);
        for (ServerPlayer player : players) {
            PacketDistributor.sendToPlayer(player, payload);
        }
        ${modAccess.loggerExpression}.info("Synced {} custom fluids to all connected players", fluidJsons.size());
    }

    private static List<String> serializeAllFluids() {
        Collection<CustomFluidDefinition> allFluids = CustomFluidAPI.getAllFluids();

        if (allFluids.isEmpty()) {
            return List.of();
        }

        List<String> fluidJsons = new ArrayList<>(allFluids.size());

        for (CustomFluidDefinition definition : allFluids) {
            try {
                JsonObject json = (JsonObject) CustomFluidDefinition.CODEC
                        .encodeStart(JsonOps.INSTANCE, definition)
                        .resultOrPartial(error -> ${modAccess.loggerExpression}.warn("Failed to encode fluid: {}", error))
                        .orElse(null);

                if (json != null) {
                    fluidJsons.add(GSON.toJson(json));
                }
            } catch (Exception e) {
                ${modAccess.loggerExpression}.error("Error serializing custom fluid {}: {}",
                        definition.id(), e.getMessage());
            }
        }

        return fluidJsons;
    }
}
"""

    private fun dirtinessNetworkingPayloadSource(packageName: String, modAccess: ModAccess): String = """package $packageName;

${modAccess.importLine()}import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.network.PacketDistributor;
import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.handling.IPayloadContext;
import net.neoforged.neoforge.network.registration.PayloadRegistrar;

import java.util.UUID;

@EventBusSubscriber(modid = ${modAccess.modIdExpression}, bus = EventBusSubscriber.Bus.MOD)
public class DirtinessNetworking {
    public static final ResourceLocation SYNC_DIRTINESS_ID =
            ResourceLocation.fromNamespaceAndPath(${modAccess.modIdExpression}, "sync_dirtiness");
    public static final ResourceLocation SYNC_OTHER_PLAYER_ID =
            ResourceLocation.fromNamespaceAndPath(${modAccess.modIdExpression}, "sync_other_dirtiness");

    public record SyncDirtinessPayload(float dirtiness, long dirtSeed, boolean hasFlies) implements CustomPacketPayload {
        public static final Type<SyncDirtinessPayload> TYPE =
                new Type<>(SYNC_DIRTINESS_ID);

        public static final StreamCodec<FriendlyByteBuf, SyncDirtinessPayload> STREAM_CODEC =
                StreamCodec.composite(
                        ByteBufCodecs.FLOAT, SyncDirtinessPayload::dirtiness,
                        ByteBufCodecs.VAR_LONG, SyncDirtinessPayload::dirtSeed,
                        ByteBufCodecs.BOOL, SyncDirtinessPayload::hasFlies,
                        SyncDirtinessPayload::new
                );

        @Override
        public Type<? extends CustomPacketPayload> type() {
            return TYPE;
        }
    }

    public record SyncOtherPlayerDirtinessPayload(UUID playerId, float dirtiness, long dirtSeed, boolean hasFlies) implements CustomPacketPayload {
        public static final Type<SyncOtherPlayerDirtinessPayload> TYPE =
                new Type<>(SYNC_OTHER_PLAYER_ID);

        public static final StreamCodec<FriendlyByteBuf, SyncOtherPlayerDirtinessPayload> STREAM_CODEC =
                StreamCodec.composite(
                        net.minecraft.core.UUIDUtil.STREAM_CODEC, SyncOtherPlayerDirtinessPayload::playerId,
                        ByteBufCodecs.FLOAT, SyncOtherPlayerDirtinessPayload::dirtiness,
                        ByteBufCodecs.VAR_LONG, SyncOtherPlayerDirtinessPayload::dirtSeed,
                        ByteBufCodecs.BOOL, SyncOtherPlayerDirtinessPayload::hasFlies,
                        SyncOtherPlayerDirtinessPayload::new
                );

        @Override
        public Type<? extends CustomPacketPayload> type() {
            return TYPE;
        }
    }

    @SubscribeEvent
    public static void registerPayloads(RegisterPayloadHandlersEvent event) {
        PayloadRegistrar registrar = event.registrar(${modAccess.modIdExpression});
        registrar.playToClient(
                SyncDirtinessPayload.TYPE,
                SyncDirtinessPayload.STREAM_CODEC,
                DirtinessNetworking::handleSyncOnClient
        );
        registrar.playToClient(
                SyncOtherPlayerDirtinessPayload.TYPE,
                SyncOtherPlayerDirtinessPayload.STREAM_CODEC,
                DirtinessNetworking::handleSyncOtherPlayerOnClient
        );
    }

    private static void handleSyncOnClient(SyncDirtinessPayload payload, IPayloadContext context) {
        context.enqueueWork(() -> {
            if (context.player() != null) {
                DirtinessClientData.setDirtiness(
                        context.player().getUUID(),
                        payload.dirtiness(),
                        payload.dirtSeed(),
                        payload.hasFlies()
                );
            }
        });
    }

    private static void handleSyncOtherPlayerOnClient(SyncOtherPlayerDirtinessPayload payload, IPayloadContext context) {
        context.enqueueWork(() -> DirtinessClientData.setDirtiness(
                payload.playerId(),
                payload.dirtiness(),
                payload.dirtSeed(),
                payload.hasFlies()
        ));
    }

    public static void register() {
    }

    public static void syncToClient(ServerPlayer player) {
        DirtinessCapability.get(player).ifPresent(data -> {
            long gameTime = player.level().getGameTime();
            float dirtiness = data.getDirtiness(gameTime);
            boolean hasFlies = data.shouldSpawnFlies(gameTime);

            PacketDistributor.sendToPlayer(
                    player,
                    new SyncDirtinessPayload(dirtiness, data.getDirtSeed(), hasFlies)
            );

            PacketDistributor.sendToPlayersTrackingEntity(
                    player,
                    new SyncOtherPlayerDirtinessPayload(player.getUUID(), dirtiness, data.getDirtSeed(), hasFlies)
            );
        });
    }
}
"""

    /**
     * Transform packet classes to implement CustomPacketPayload and generate ModNetwork.java.
     * Detects classes with static encode(ClassName, FriendlyByteBuf) + decode(FriendlyByteBuf) patterns.
     */
    private fun transformPacketClasses(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        // Detect mod ID
        val modId = detectModId(projectDir) ?: return changes

        // Detect mod main class (for registering ModNetwork)
        val modMainClass = detectModMainClass(projectDir)

        // Find packet classes
        val packetClasses = mutableListOf<PacketClassInfo>()
        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { file ->
                val content = file.readText()
                val encodeMatch = Regex(
                    """public\s+static\s+void\s+encode\s*\(\s*(\w+)\s+(\w+)\s*,\s*FriendlyByteBuf\s+(\w+)\s*\)"""
                ).find(content)
                val decodeMatch = Regex(
                    """public\s+static\s+(\w+)\s+decode\s*\(\s*FriendlyByteBuf\s+\w+\s*\)"""
                ).find(content)

                if (encodeMatch != null && decodeMatch != null) {
                    val className = encodeMatch.groupValues[1]
                    if (className == decodeMatch.groupValues[1]) {
                        val pkg = Regex("""package\s+([\w.]+)\s*;""").find(content)?.groupValues?.get(1) ?: ""
                        val hasClientReceptionGuard = Regex(
                            """\.getDirection\(\)\.getReceptionSide\(\)\.isClient\(\)"""
                        ).containsMatchIn(content)
                        val hasServerReceptionGuard = Regex(
                            """\.getDirection\(\)\.getReceptionSide\(\)\.isServer\(\)"""
                        ).containsMatchIn(content)
                        val isPlayToClient = when {
                            hasClientReceptionGuard -> true
                            hasServerReceptionGuard -> false
                            else -> className.startsWith("S2C") ||
                                className.contains("ToClient") ||
                                content.contains("PLAY_TO_CLIENT") ||
                                content.contains("ClientPacketHandler") ||
                                content.contains("DistExecutor") ||
                                content.contains("Dist.CLIENT") ||
                                content.contains("FMLLoader.getDist() == Dist.CLIENT") ||
                                Regex("""import\s+[\w.]+\.client\.""").containsMatchIn(content)
                        }
                        val nestedHandler = Regex(
                            """static\s+class\s+(\w+)[\s\S]*?static\s+void\s+handle\s*\("""
                        ).find(content)
                        val handlerRef = if (nestedHandler != null) {
                            "$className.${nestedHandler.groupValues[1]}::handle"
                        } else {
                            "$className::handle"
                        }
                        packetClasses.add(PacketClassInfo(
                            file, className, pkg,
                            encodeMatch.groupValues[2],
                            encodeMatch.groupValues[3],
                            handlerRef,
                            isPlayToClient,
                            "FriendlyByteBuf",
                            "StreamCodec.of($className::encode, $className::decode)"
                        ))
                    }
                }
            }

        val existingPacketClasses = packetClasses.map { it.className }.toMutableSet()
        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { file ->
                val content = file.readText()
                if (!content.contains(".registerMessage(") || !content.contains("SimpleChannel")) return@forEach

                Regex("""registerMessage\s*\(([^;]+)\);""")
                    .findAll(content)
                    .forEach { registration ->
                        val args = splitTopLevelJavaArgs(registration.groupValues[1])
                        if (args.size < 5) return@forEach
                        val className = args[1].trim().removeSuffix(".class").substringAfterLast('.')
                        if (className.isBlank() || !existingPacketClasses.add(className)) return@forEach
                        val packetFile = Files.walk(srcDir)
                            .filter { it.fileName.toString() == "$className.java" }
                            .findFirst()
                            .orElse(null)
                            ?: return@forEach
                        val packetContent = packetFile.readText()
                        val constructorBufferType = Regex(
                            """public\s+${Regex.escape(className)}\s*\(\s*(RegistryFriendlyByteBuf|FriendlyByteBuf)\s+\w+\s*\)"""
                        ).find(packetContent)?.groupValues?.get(1)
                        if (constructorBufferType == null) {
                            return@forEach
                        }
                        val encodeBufferType = Regex(
                            """\bvoid\s+encode\s*\(\s*(RegistryFriendlyByteBuf|FriendlyByteBuf)\s+([A-Za-z_$][\w$]*)\s*\)"""
                        ).find(packetContent)?.groupValues?.get(1)
                        if (encodeBufferType == null) {
                            return@forEach
                        }
                        val bufferType = if (constructorBufferType == "RegistryFriendlyByteBuf" ||
                            encodeBufferType == "RegistryFriendlyByteBuf") {
                            "RegistryFriendlyByteBuf"
                        } else {
                            "FriendlyByteBuf"
                        }
                        val pkg = Regex("""package\s+([\w.]+)\s*;""").find(packetContent)?.groupValues?.get(1) ?: ""
                        val handlerRef = payloadHandlerLambda(args[4].trim())
                        val isPlayToClient = className.startsWith("S2C") ||
                            className.contains("ToClient") ||
                            packetContent.contains("Minecraft.getInstance()") ||
                            packetContent.contains("ClientLevel") ||
                            packetContent.contains("Dist.CLIENT") ||
                            Regex("""import\s+[\w.]+\.client\.""").containsMatchIn(packetContent)
                        packetClasses.add(PacketClassInfo(
                            packetFile,
                            className,
                            pkg,
                            className.replaceFirstChar { it.lowercase() },
                            "buf",
                            handlerRef,
                            isPlayToClient,
                            bufferType,
                            "StreamCodec.of((buf, packet) -> packet.encode(buf), $className::new)",
                            "playBidirectional"
                        ))
                    }
            }

        if (packetClasses.isEmpty()) return changes

        // Transform each packet class
        for (info in packetClasses) {
            if (dryRun) {
                changes.add(Change(
                    file = info.file, line = 1,
                    description = "Will transform ${info.className} to implement CustomPacketPayload",
                    before = "class ${info.className}",
                    after = "class ${info.className} implements CustomPacketPayload",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-packet-payload"
                ))
                continue
            }

            var content = info.file.readText()

            val originalContent = content
            val alreadyPayload = content.contains("implements CustomPacketPayload")

            // 1. Add imports
            val importBlock = buildString {
                if (!content.contains("import net.minecraft.network.codec.StreamCodec;"))
                    append("import net.minecraft.network.codec.StreamCodec;\n")
                if (!content.contains("import net.minecraft.network.protocol.common.custom.CustomPacketPayload;"))
                    append("import net.minecraft.network.protocol.common.custom.CustomPacketPayload;\n")
                if (!content.contains("import net.minecraft.resources.ResourceLocation;"))
                    append("import net.minecraft.resources.ResourceLocation;\n")
            }
            if (importBlock.isNotEmpty()) {
                // Insert after last existing import
                val lastImport = Regex("""^import\s+[^;]+;""", RegexOption.MULTILINE).findAll(content).lastOrNull()
                if (lastImport != null) {
                    val insertPos = lastImport.range.last + 1
                    content = content.substring(0, insertPos) + "\n" + importBlock + content.substring(insertPos)
                }
            }

            if (!alreadyPayload) {
                // 2. Add implements CustomPacketPayload
                content = addCustomPacketPayloadInterface(content, info.className)

                // 3. Generate snake_case name for resource location
                val snakeName = payloadPathName(info.className)

                // 4. Add TYPE, STREAM_CODEC, type() after class opening brace
                val classBodyInsert = """
    public static final CustomPacketPayload.Type<${info.className}> TYPE =
            new CustomPacketPayload.Type<>(ResourceLocation.fromNamespaceAndPath("$modId", "$snakeName"));

    public static final StreamCodec<${info.bufferType}, ${info.className}> STREAM_CODEC =
            ${info.streamCodecExpression};

    @Override
    public CustomPacketPayload.Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }
"""
                val classOpenBrace = findTypeOpenBrace(content, info.className)
                if (classOpenBrace > 0) {
                    content = content.substring(0, classOpenBrace + 1) + classBodyInsert + content.substring(classOpenBrace + 1)
                }
            }

            // 5. Swap encode parameter order: encode(ClassName msg, FriendlyByteBuf buf) -> encode(FriendlyByteBuf buf, ClassName msg)
            content = content.replace(
                Regex("""encode\s*\(\s*${info.className}\s+(\w+)\s*,\s*FriendlyByteBuf\s+(\w+)\s*\)"""),
                "encode(FriendlyByteBuf $2, ${info.className} $1)"
            )
            content = migrateLegacyPayloadHandlerContext(content, info, changes)
            content = cleanupLegacyPayloadContextReferences(content, info, changes)

            if (content == originalContent) continue

            info.file.writeText(content)
            changes.add(Change(
                file = info.file, line = 1,
                description = "Transformed ${info.className} to implement CustomPacketPayload with TYPE + STREAM_CODEC",
                before = "class ${info.className}",
                after = "class ${info.className} implements CustomPacketPayload",
                confidence = Confidence.HIGH,
                ruleId = "struct-packet-payload"
            ))
        }

        if (dryRun) return changes

        // 6. Generate ModNetwork.java
        val networkPkg = packetClasses.first().packageName
        val networkDir = srcDir.resolve(networkPkg.replace('.', '/'))
        val networkFile = networkDir.resolve("ModNetwork.java")
        if (!networkFile.exists()) {
            val registrations = packetClasses.joinToString("\n\n") { info ->
                val direction = info.registrationMethod ?: if (info.isPlayToClient) "playToClient" else "playToServer"
                """        registrar.$direction(
                ${info.className}.TYPE,
                ${info.className}.STREAM_CODEC,
                ${info.handlerRef}
        );"""
            }

            val networkContent = """package $networkPkg;

import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.registration.PayloadRegistrar;

public class ModNetwork {

    public static void register(final RegisterPayloadHandlersEvent event) {
        final PayloadRegistrar registrar = event.registrar("$modId").versioned("1");

$registrations
    }
}
"""
            networkFile.writeText(networkContent)
            changes.add(Change(
                file = networkFile, line = 1,
                description = "Generated ModNetwork.java for packet registration via RegisterPayloadHandlersEvent",
                before = "(new file)",
                after = "ModNetwork with ${packetClasses.size} packet registrations",
                confidence = Confidence.HIGH,
                ruleId = "struct-generate-mod-network"
            ))

            // 7. Register ModNetwork in the mod main class
            if (modMainClass != null) {
                var mainContent = modMainClass.readText()
                if (!mainContent.contains("ModNetwork::register")) {
                    // Add import
                    val importLine = "import ${networkPkg}.ModNetwork;"
                    if (!mainContent.contains(importLine)) {
                        val lastImportMatch = Regex("""^import\s+[^;]+;""", RegexOption.MULTILINE)
                            .findAll(mainContent).lastOrNull()
                        if (lastImportMatch != null) {
                            val pos = lastImportMatch.range.last + 1
                            mainContent = mainContent.substring(0, pos) + "\n" + importLine + mainContent.substring(pos)
                        }
                    }

                    val eventBusName = detectModBusVariable(mainContent)
                    if (eventBusName != null) {
                        val listenerLine = "        $eventBusName.addListener(ModNetwork::register);"
                        mainContent = insertModBusListener(mainContent, eventBusName, listenerLine, "ModNetwork")
                    }
                    if (!mainContent.contains("ModNetwork::register")) {
                        val containerMatch = Regex("""(modContainer\.(?:registerConfig|getEventBus\(\)\.addListener))""").find(mainContent)
                        if (containerMatch != null) {
                            val pos = mainContent.lastIndexOf('\n', containerMatch.range.first)
                            val regLine = "\n        modContainer.getEventBus().addListener(ModNetwork::register);\n"
                            mainContent = mainContent.substring(0, pos) + regLine + mainContent.substring(pos)
                        }
                    }
                    modMainClass.writeText(mainContent)
                    changes.add(Change(
                        file = modMainClass, line = 1,
                        description = "Registered ModNetwork packet handler in main mod class",
                        before = "(no packet registration)",
                        after = "modEventBus.addListener(ModNetwork::register)",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-register-mod-network"
                    ))
                }
            }
        }

        // 8. Replace old SimpleChannel registration class (ModPackets, PacketHandler, etc.)
        // Find files that contain SimpleChannel or INSTANCE.messageBuilder and rewrite them
        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .filter { it.fileName.toString() != "ModNetwork.java" }
            .forEach { file ->
                val content = file.readText()
                if (content.contains("@Mod(") || content.contains("@Mod\n")) return@forEach
                // Detect old SimpleChannel registration classes
                val hasSimpleChannel = content.contains("SimpleChannel") ||
                    content.contains("NetworkRegistry.ChannelBuilder") ||
                    content.contains("NetworkRegistry.newSimpleChannel") ||
                    (content.contains("INSTANCE") && content.contains("messageBuilder"))
                if (!hasSimpleChannel) return@forEach

                val pkg = Regex("""package\s+([\w.]+)\s*;""").find(content)?.groupValues?.get(1) ?: return@forEach
                val className = file.fileName.toString().removeSuffix(".java")

                // Check if this class has send helper methods (sendToServer, sendToPlayer, etc.)
                val hasSendHelpers = content.contains("sendToServer") || content.contains("sendToPlayer") ||
                    content.contains("sendToAllClients") || content.contains("sendToTracking")

                val newContent = buildString {
                    appendLine("package $pkg;")
                    appendLine()
                    appendLine("import net.minecraft.server.level.ServerPlayer;")
                    appendLine("import net.neoforged.neoforge.network.PacketDistributor;")
                    appendLine("import net.minecraft.network.protocol.common.custom.CustomPacketPayload;")
                    appendLine()
                    appendLine("public class $className {")
                    appendLine()
                    appendLine("    public static void registerPackets() {")
                    appendLine("    }")
                    appendLine()
                    appendLine("    public static void init() {")
                    appendLine("        registerPackets();")
                    appendLine("    }")
                    appendLine()
                    appendLine("    public static void register() {")
                    appendLine("        registerPackets();")
                    appendLine("    }")
                    appendLine()
                    if (hasSendHelpers) {
                        appendLine("    public static <T extends CustomPacketPayload> void sendToServer(T msg) {")
                        appendLine("        PacketDistributor.sendToServer(msg);")
                        appendLine("    }")
                        appendLine()
                        appendLine("    public static <T extends CustomPacketPayload> void sendToPlayer(ServerPlayer player, T msg) {")
                        appendLine("        PacketDistributor.sendToPlayer(player, msg);")
                        appendLine("    }")
                        appendLine()
                        appendLine("    public static <T extends CustomPacketPayload> void sendToPlayer(T msg, ServerPlayer player) {")
                        appendLine("        sendToPlayer(player, msg);")
                        appendLine("    }")
                        appendLine()
                        appendLine("    public static <T extends CustomPacketPayload> void sendToAllClients(T msg) {")
                        appendLine("        PacketDistributor.sendToAllPlayers(msg);")
                        appendLine("    }")
                        appendLine()
                    }
                    appendLine("}")
                }

                if (!dryRun) {
                    file.writeText(newContent)
                }
                changes.add(Change(
                    file = file, line = 1,
                    description = "Replaced old SimpleChannel registration class $className with NeoForge-compatible wrapper",
                    before = "(SimpleChannel registration)",
                    after = "(PacketDistributor wrapper + ModNetwork delegation)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-replace-modpackets"
                ))
            }

        changes.addAll(cleanupInlineSimpleChannelRegistrations(srcDir, dryRun))

        return changes
    }

    private fun detectModBusVariable(source: String): String? =
        Regex("""\bpublic\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)[^)]*\)\s*\{""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: Regex("""\bIEventBus\s+(\w+)\s*=""")
                .find(source)
                ?.groupValues
                ?.get(1)

    private fun cleanupInlineSimpleChannelRegistrations(srcDir: Path, dryRun: Boolean): List<Change> {
        val hasGeneratedNetwork = Files.walk(srcDir)
            .use { stream -> stream.anyMatch { it.fileName.toString() == "ModNetwork.java" } }
        if (!hasGeneratedNetwork) return emptyList()

        val changes = mutableListOf<Change>()
        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .forEach { javaFile ->
                val original = javaFile.readText()
                if (!original.contains("SimpleChannel") &&
                    !original.contains("NetworkRegistry.newSimpleChannel") &&
                    !original.contains(".registerMessage(")) {
                    return@forEach
                }

                val channelNames = linkedSetOf<String>()
                Regex(
                    """(?m)^[ \t]*(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?(?:SimpleChannel|EventNetworkChannel)\s+([A-Za-z_$][\w$]*)\b[^;]*;\s*\r?\n?"""
                ).findAll(original).forEach { channelNames.add(it.groupValues[1]) }
                Regex("""\b([A-Za-z_$][\w$]*)\s*=\s*NetworkRegistry\.newSimpleChannel\s*\(""")
                    .findAll(original)
                    .forEach { channelNames.add(it.groupValues[1]) }
                if (channelNames.isEmpty()) return@forEach

                var modified = original
                modified = Regex(
                    """(?m)^[ \t]*(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?(?:SimpleChannel|EventNetworkChannel)\s+(?:${channelNames.joinToString("|") { Regex.escape(it) }})\b[^;]*;\s*\r?\n?"""
                ).replace(modified, "")
                for (channelName in channelNames) {
                    modified = removeJavaStatementsMatching(modified) { statement ->
                        statement.contains("$channelName = NetworkRegistry.newSimpleChannel") ||
                            statement.contains("$channelName.registerMessage(")
                    }
                }
                if (!Regex("""\bregisterMessage\s*\(""").containsMatchIn(modified)) {
                    modified = Regex("""(?m)^[ \t]*(?:int|var)\s+packetIndex\s*=\s*0\s*;\s*\r?\n?""")
                        .replace(modified, "")
                }
                modified = removeImportIfPresent(modified, "net.minecraftforge.network.NetworkRegistry")
                modified = removeImportIfPresent(modified, "net.minecraftforge.network.simple.SimpleChannel")
                modified = removeImportIfPresent(modified, "net.minecraftforge.network.EventNetworkChannel")

                if (modified != original) {
                    changes.add(Change(
                        file = javaFile,
                        line = 1,
                        description = "Remove legacy SimpleChannel declarations and registerMessage setup after payload registration migration",
                        before = "SimpleChannel field + NetworkRegistry.newSimpleChannel/registerMessage",
                        after = "RegisterPayloadHandlersEvent via generated ModNetwork",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-remove-inline-simplechannel-registration"
                    ))
                    if (!dryRun) javaFile.writeText(modified)
                }
            }
        return changes
    }

    private data class BasePacketPayloadInfo(
        val file: Path,
        val packageName: String,
        val fileClassName: String,
        val simpleName: String,
        val referenceName: String,
        val bufferType: String,
        val direction: String,
        val registerable: Boolean
    )

    private fun migrateBasePacketPayloads(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val modId = detectModId(projectDir) ?: return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        val payloads = linkedMapOf<String, BasePacketPayloadInfo>()
        val changes = mutableListOf<Change>()

        for (file in javaFiles) {
            val original = file.readText()
            if (!original.contains("BasePacket") || !original.contains("decode(") || !original.contains("execute(")) {
                continue
            }
            val packageName = packageNameOf(original)
            val fileClassName = file.fileName.toString().removeSuffix(".java")
            val payloadTypes = extractBasePacketPayloadTypes(file, original, packageName, fileClassName)
            if (payloadTypes.isEmpty()) continue

            var modified = original
            modified = modified.replace("implements BasePacket", "implements CustomPacketPayload")
            modified = removeImportIfPresent(modified, "com.aetherteam.nitrogen.network.BasePacket")
            modified = removeImportIfPresent(modified, "net.minecraftforge.network.NetworkEvent")
            modified = addImportIfMissing(modified, "net.minecraft.network.codec.StreamCodec")
            modified = addImportIfMissing(modified, "net.minecraft.network.protocol.common.custom.CustomPacketPayload")
            modified = addImportIfMissing(modified, "net.minecraft.resources.ResourceLocation")
            modified = Regex("""(?m)^([ \t]*)@Override\s*\r?\n\1(public\s+void\s+(?:encode|execute)\s*\()""")
                .replace(modified) { match -> match.groupValues[1] + match.groupValues[2] }

            for (payload in payloadTypes) {
                if (payload.registerable &&
                    !modified.contains("Type<${payload.simpleName}> TYPE") &&
                    !modified.contains("Type<${payload.referenceName}> TYPE")) {
                    val insert = """
        public static final CustomPacketPayload.Type<${payload.simpleName}> TYPE =
                new CustomPacketPayload.Type<>(ResourceLocation.fromNamespaceAndPath("$modId", "${payloadPathName(payload.referenceName.replace('.', '_'))}"));

        public static final StreamCodec<${payload.bufferType}, ${payload.simpleName}> STREAM_CODEC =
                StreamCodec.of((buf, packet) -> packet.encode(buf), ${payload.simpleName}::decode);

        @Override
        public CustomPacketPayload.Type<? extends CustomPacketPayload> type() {
            return TYPE;
        }

""".trimStart()
                    val openBrace = findTypeOpenBrace(modified, payload.simpleName)
                    if (openBrace >= 0) {
                        modified = modified.substring(0, openBrace + 1) + "\n" + insert + modified.substring(openBrace + 1)
                    }
                }
                if (payload.registerable) {
                    payloads[payload.referenceName] = payload
                }
            }

            if (modified != original) {
                if (!dryRun) file.writeText(modified)
                changes.add(Change(
                    file = file,
                    line = 1,
                    description = "Migrate BasePacket payload type(s) to CustomPacketPayload",
                    before = "implements BasePacket + encode/decode/execute(Player)",
                    after = "implements CustomPacketPayload + TYPE/STREAM_CODEC",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-basepacket-payload"
                ))
            }
        }

        if (payloads.isEmpty()) return changes
        changes.addAll(rewriteBasePacketHandlers(projectDir, srcDir, modId, payloads, dryRun))
        changes.addAll(rewritePacketRelayCalls(srcDir, dryRun))
        return changes
    }

    private fun extractBasePacketPayloadTypes(
        file: Path,
        source: String,
        packageName: String,
        fileClassName: String
    ): List<BasePacketPayloadInfo> {
        val results = mutableListOf<BasePacketPayloadInfo>()
        val decodePattern = Regex(
            """public\s+static\s+([A-Za-z_$][\w$]*)\s+decode\s*\(\s*(RegistryFriendlyByteBuf|FriendlyByteBuf)\s+([A-Za-z_$][\w$]*)\s*\)"""
        )
        for (decode in decodePattern.findAll(source)) {
            val simpleName = decode.groupValues[1]
            val bufferType = decode.groupValues[2]
            val typeStart = findTypeDeclarationStart(source, simpleName) ?: continue
            val openBrace = source.indexOf('{', typeStart)
            if (openBrace < 0 || decode.range.first < openBrace) continue
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace <= openBrace || decode.range.first > closeBrace) continue
            val body = source.substring(openBrace + 1, closeBrace)
            if (!Regex("""\bvoid\s+execute\s*\(\s*(?:@\w+\s+)?(?:Player|ServerPlayer)\s+[A-Za-z_$][\w$]*\s*\)""")
                    .containsMatchIn(body)) {
                continue
            }
            val referenceName = if (simpleName == fileClassName) simpleName else "$fileClassName.$simpleName"
            results.add(BasePacketPayloadInfo(
                file = file,
                packageName = packageName,
                fileClassName = fileClassName,
                simpleName = simpleName,
                referenceName = referenceName,
                bufferType = bufferType,
                direction = packetDirectionFromPackage(packageName),
                registerable = true
            ))
        }

        val topLevelImplementsBasePacket = Regex(
            """public\s+(?:abstract\s+)?(?:class|record)\s+${Regex.escape(fileClassName)}\b[\s\S]*?\bimplements\s+BasePacket\b"""
        ).containsMatchIn(source)
        if (topLevelImplementsBasePacket &&
            results.none { it.simpleName == fileClassName } &&
            Regex("""\bvoid\s+encode\s*\(\s*(RegistryFriendlyByteBuf|FriendlyByteBuf)\s+[A-Za-z_$][\w$]*\s*\)""").containsMatchIn(source)) {
            // Abstract base packets, such as shared boss-bar packets, still need
            // the BasePacket interface removed. Concrete nested payloads above
            // provide TYPE/STREAM_CODEC/type().
            results.add(BasePacketPayloadInfo(
                file = file,
                packageName = packageName,
                fileClassName = fileClassName,
                simpleName = fileClassName,
                referenceName = fileClassName,
                bufferType = Regex("""\bvoid\s+encode\s*\(\s*(RegistryFriendlyByteBuf|FriendlyByteBuf)\s+""")
                    .find(source)
                    ?.groupValues
                    ?.get(1) ?: "FriendlyByteBuf",
                direction = packetDirectionFromPackage(packageName),
                registerable = false
            ))
        }
        return results
    }

    private fun findTypeDeclarationStart(source: String, simpleName: String): Int? =
        Regex("""\bpublic\s+(?:(?:static|abstract|final|sealed|non-sealed)\s+)*(?:class|record)\s+${Regex.escape(simpleName)}\b""")
            .find(source)
            ?.range
            ?.first

    private fun packetDirectionFromPackage(packageName: String): String = when {
        packageName.contains(".clientbound") -> "playToClient"
        packageName.contains(".serverbound") -> "playToServer"
        else -> "playBidirectional"
    }

    private fun rewriteBasePacketHandlers(
        projectDir: Path,
        srcDir: Path,
        modId: String,
        payloads: Map<String, BasePacketPayloadInfo>,
        dryRun: Boolean
    ): List<Change> {
        val changes = mutableListOf<Change>()
        val uniquePayloadBySimpleName = payloads.values
            .groupBy { it.simpleName }
            .mapNotNull { (simpleName, candidates) ->
                val distinctCandidates = candidates.distinctBy { it.referenceName }
                if (distinctCandidates.size == 1) simpleName to distinctCandidates.single() else null
            }
            .toMap()
        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
            .forEach { file ->
                val original = file.readText()
                if (!original.contains("BasePacket") ||
                    !original.contains("messageBuilder") ||
                    !original.contains("register(")) {
                    return@forEach
                }
                val registrations = Regex("""register\s*\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.class\s*,\s*[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*::decode\s*\)\s*;""")
                    .findAll(original)
                    .mapNotNull { match ->
                        val packetRef = match.groupValues[1]
                        val payload = payloads[packetRef]
                            ?: uniquePayloadBySimpleName[packetRef.substringAfterLast('.')]
                            ?: return@mapNotNull null
                        "        registrar.${payload.direction}(${payload.referenceName}.TYPE, ${payload.referenceName}.STREAM_CODEC, (payload, context) -> payload.execute(context.player()));"
                    }
                    .toList()
                if (registrations.isEmpty()) return@forEach

                val packageName = packageNameOf(original)
                val className = file.fileName.toString().removeSuffix(".java")
                val packetImports = Regex("""(?m)^[ \t]*import\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.network\.packet(?:\.[A-Za-z_$][\w$]*)*(?:\.\*)?);\s*$""")
                    .findAll(original)
                    .map { "import ${it.groupValues[1]};" }
                    .distinct()
                    .joinToString("\n")
                    .let { if (it.isBlank()) "" else "$it\n" }
                val migrated = """package $packageName;

${packetImports}import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.registration.PayloadRegistrar;

public class $className {
    public static void register(RegisterPayloadHandlersEvent event) {
        PayloadRegistrar registrar = event.registrar("$modId").versioned("1");
${registrations.distinct().joinToString("\n")}
    }
}
"""
                if (!dryRun) file.writeText(migrated)
                changes.add(Change(
                    file = file,
                    line = 1,
                    description = "Migrate BasePacket SimpleChannel registrations to PayloadRegistrar",
                    before = "SimpleChannel.messageBuilder(... BasePacket::handle)",
                    after = "RegisterPayloadHandlersEvent PayloadRegistrar registrations",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-basepacket-handler-registration"
                ))
                val mainClass = detectModMainClass(projectDir) ?: return@forEach
                val mainOriginal = mainClass.readText()
                val busName = detectModBusVariable(mainOriginal) ?: return@forEach
                val listenerLine = "        $busName.addListener($className::register);"
                var mainModified = mainOriginal.replace(
                    Regex("""(?m)^[ \t]*${Regex.escape(className)}\.register\s*\(\s*\)\s*;\s*\r?\n"""),
                    ""
                )
                if (!mainModified.contains("$className::register")) {
                    mainModified = insertModBusListener(mainModified, busName, listenerLine, className)
                }
                if (mainModified != mainOriginal) {
                    if (!dryRun) mainClass.writeText(mainModified)
                    changes.add(Change(
                        file = mainClass,
                        line = 1,
                        description = "Register migrated BasePacket payload handler on mod event bus",
                        before = "$className.register()",
                        after = "$busName.addListener($className::register)",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-basepacket-main-registration"
                    ))
                }
            }
        return changes
    }

    private fun rewritePacketRelayCalls(srcDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
            .forEach { file ->
                val original = file.readText()
                if (!original.contains("PacketRelay.")) return@forEach
                var modified = original
                modified = rewriteJavaInvocation(modified, "PacketRelay.sendToServer") { args ->
                    if (args.size == 2) "PacketDistributor.sendToServer(${args[1].trim()})" else null
                }
                modified = rewriteJavaInvocation(modified, "PacketRelay.sendToPlayer") { args ->
                    if (args.size == 3) "PacketDistributor.sendToPlayer(${args[2].trim()}, ${args[1].trim()})" else null
                }
                modified = rewriteJavaInvocation(modified, "PacketRelay.sendToAll") { args ->
                    if (args.size == 2) "PacketDistributor.sendToAllPlayers(${args[1].trim()})" else null
                }
                modified = rewriteJavaInvocation(modified, "PacketRelay.sendToNear") { args ->
                    if (args.size != 7) return@rewriteJavaInvocation null
                    val levelExpr = args[6].trim().removeSuffix(".dimension()")
                    if (!Regex("""\bServerLevel\s+${Regex.escape(levelExpr)}\b""").containsMatchIn(modified)) {
                        return@rewriteJavaInvocation null
                    }
                    "PacketDistributor.sendToPlayersNear($levelExpr, null, ${args[2].trim()}, ${args[3].trim()}, ${args[4].trim()}, ${args[5].trim()}, ${args[1].trim()})"
                }
                if (modified != original) {
                    modified = addImportIfMissing(modified, "net.neoforged.neoforge.network.PacketDistributor")
                    modified = removeImportIfPresent(modified, "com.aetherteam.nitrogen.network.PacketRelay")
                    modified = removeUnusedImportsBySimpleNamePattern(modified, Regex("""[A-Za-z_$][\w$]*PacketHandler"""))
                    if (!dryRun) file.writeText(modified)
                    changes.add(Change(
                        file = file,
                        line = 1,
                        description = "Migrate PacketRelay sends to NeoForge PacketDistributor",
                        before = "PacketRelay.sendTo*(channel, packet, ...)",
                        after = "PacketDistributor.sendTo*(packet, ...)",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-packetrelay-distributor"
                    ))
                }
            }
        return changes
    }

    private fun rewriteJavaInvocation(source: String, qualifiedName: String, replacement: (List<String>) -> String?): String {
        var result = source
        var cursor = 0
        while (true) {
            val index = result.indexOf("$qualifiedName(", cursor)
            if (index < 0) break
            val openParen = index + qualifiedName.length
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen <= openParen) {
                cursor = index + qualifiedName.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val call = replacement(args)
            if (call == null) {
                cursor = closeParen + 1
                continue
            }
            result = result.substring(0, index) + call + result.substring(closeParen + 1)
            cursor = index + call.length
        }
        return result
    }

    private fun removeJavaStatementsMatching(source: String, predicate: (String) -> Boolean): String {
        val separator = if (source.contains("\r\n")) "\r\n" else "\n"
        val lines = source.lines()
        val kept = mutableListOf<String>()
        var i = 0
        while (i < lines.size) {
            val startLine = lines[i]
            val mightRemove = startLine.contains("NetworkRegistry.newSimpleChannel") ||
                startLine.contains(".registerMessage(")
            if (!mightRemove) {
                kept.add(startLine)
                i++
                continue
            }

            var end = i
            val statementLines = mutableListOf(startLine)
            while (!statementLines.joinToString("\n").trimEnd().endsWith(";") && end + 1 < lines.size) {
                end++
                statementLines.add(lines[end])
            }
            val statement = statementLines.joinToString("\n")
            if (predicate(statement)) {
                i = end + 1
            } else {
                kept.add(startLine)
                i++
            }
        }
        return kept.joinToString(separator)
    }

    /**
     * Detect mod ID from @Mod annotation.
     */
    private fun detectModId(projectDir: Path): String? {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return null
        try {
            val javaFiles = Files.walk(srcDir).filter { it.toString().endsWith(".java") }.toList()
            for (file in javaFiles) {
                val text = file.readText()
                val directMatch = Regex("""@Mod\s*\(\s*"(\w+)"\s*\)""").find(text)
                if (directMatch != null) return directMatch.groupValues[1]
                val constRef = Regex("""@Mod\s*\(\s*(\w+)\.(\w+)\s*\)""").find(text)
                if (constRef != null) {
                    val constName = constRef.groupValues[2]
                    val constVal = Regex("${constName}\\s*=\\s*\"(\\w+)\"").find(text)
                    if (constVal != null) return constVal.groupValues[1]
                }
            }
        } catch (_: Exception) {}
        return null
    }

    /**
     * Find the main @Mod-annotated class file.
     */
    private fun detectModMainClass(projectDir: Path): Path? {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return null
        try {
            val javaFiles = Files.walk(srcDir).filter { it.toString().endsWith(".java") }.toList()
            for (file in javaFiles) {
                val text = file.readText()
                if (Regex("""@Mod\s*\(""").containsMatchIn(text)) return file
            }
        } catch (_: Exception) {}
        return null
    }

    private fun migrateMissingMappingsAliases(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir).filter { it.toString().endsWith(".java") }.toList()
        val registryFields = collectDeferredRegisterFields(javaFiles)
        if (registryFields.isEmpty()) return emptyList()

        val changes = mutableListOf<Change>()
        for (file in javaFiles) {
            val original = file.readText()
            if (!original.contains("MissingMappingsEvent") || !original.contains(".remap(")) continue
            val modAccess = inferModAccess(original) ?: continue
            val rules = extractMissingMappingAliasRules(original)
            if (rules.isEmpty()) continue
            val entries = expandMissingMappingAliasRules(rules, registryFields)
            if (entries.isEmpty()) continue

            val packageName = packageNameOf(original)
            val className = file.fileName.toString().removeSuffix(".java")
            var migrated = missingMappingAliasClassSource(packageName, className, modAccess, registryFields, entries)
            if (migrated != original) {
                changes.add(Change(
                    file = file,
                    line = 0,
                    description = "Migrate MissingMappingsEvent remaps to DeferredRegister aliases",
                    before = "MissingMappingsEvent + mapping.remap(...)",
                    after = "DeferredRegister#addAlias",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-missing-mappings-add-alias"
                ))
                if (!dryRun) file.writeText(migrated)
            }

            val mainClass = detectModMainClass(projectDir)
            if (mainClass != null) {
                val mainOriginal = mainClass.readText()
                val remapperFqn = if (packageName.isBlank()) className else "$packageName.$className"
                val mainMigrated = addMissingMappingAliasCall(mainOriginal, remapperFqn, className)
                if (mainMigrated != mainOriginal) {
                    changes.add(Change(
                        file = mainClass,
                        line = 0,
                        description = "Call migrated registry alias setup during mod construction",
                        before = "MissingMappingsEvent subscriber",
                        after = "$className.addRegistryAliases()",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-missing-mappings-alias-call"
                    ))
                    if (!dryRun) mainClass.writeText(mainMigrated)
                }
            }
        }
        return changes
    }

    private fun collectDeferredRegisterFields(javaFiles: List<Path>): Map<String, RegistryFieldInfo> {
        val fields = mutableMapOf<String, RegistryFieldInfo>()
        val fieldPattern = Regex("""DeferredRegister\s*<\s*([^;=]+?)\s*>\s+([A-Z0-9_]+)\s*=""")
        for (file in javaFiles) {
            val source = file.readText()
            if (!source.contains("DeferredRegister<")) continue
            val packageName = packageNameOf(source)
            val className = file.fileName.toString().removeSuffix(".java")
            val qualifiedClassName = if (packageName.isBlank()) className else "$packageName.$className"
            val fieldMatches = fieldPattern.findAll(source).toList()
            val helperRegisteredNames = if (fieldMatches.size == 1) {
                Regex("""\bregister[A-Za-z0-9_]*\(\s*"([^"]+)"""")
                    .findAll(source)
                    .map { it.groupValues[1] }
                    .toSet()
            } else {
                emptySet()
            }
            fieldMatches.forEach { match ->
                val type = match.groupValues[1]
                val kind = when {
                    Regex("""\bEntityType\b""").containsMatchIn(type) -> "entity"
                    Regex("""\bBlock\b""").containsMatchIn(type) -> "block"
                    Regex("""\bItem\b""").containsMatchIn(type) -> "item"
                    else -> return@forEach
                }
                val fieldName = match.groupValues[2]
                val directRegisteredNames = Regex("""\b${Regex.escape(fieldName)}\.register\(\s*"([^"]+)"""")
                    .findAll(source)
                    .map { it.groupValues[1] }
                    .toSet()
                val registeredNames = directRegisteredNames + helperRegisteredNames
                val info = RegistryFieldInfo(kind, className, qualifiedClassName, fieldName, registeredNames)
                val existing = fields[kind]
                if (existing == null || info.registeredNames.size > existing.registeredNames.size) {
                    fields[kind] = info
                }
            }
        }
        return fields
    }

    private fun extractMissingMappingAliasRules(source: String): List<RegistryAliasRule> {
        val helperKinds = mutableMapOf<String, String>()
        Regex("""\b(?:private|public|protected)?\s*static\s+void\s+([A-Za-z_$][\w$]*)\s*\(\s*MissingMappingsEvent\.Mapping\s*<\s*Block\s*>\s+""")
            .findAll(source)
            .forEach { helperKinds[it.groupValues[1]] = "block" }
        Regex("""\b(?:private|public|protected)?\s*static\s+void\s+([A-Za-z_$][\w$]*)\s*\(\s*MissingMappingsEvent\.Mapping\s*<\s*Item\s*>\s+""")
            .findAll(source)
            .forEach { helperKinds[it.groupValues[1]] = "item" }
        Regex("""\b(?:private|public|protected)?\s*static\s+void\s+([A-Za-z_$][\w$]*)\s*\(\s*MissingMappingsEvent\.Mapping\s*<\s*EntityType<\?>\s*>\s+""")
            .findAll(source)
            .forEach { helperKinds[it.groupValues[1]] = "entity" }
        if (helperKinds.isEmpty()) return emptyList()

        return helperKinds.flatMap { (helper, kind) ->
            Regex("""\b${Regex.escape(helper)}\(\s*[A-Za-z_$][\w$]*\s*,\s*"([^"]+)"\s*,\s*"([^"]+)"\s*\)""")
                .findAll(source)
                .map { RegistryAliasRule(kind, it.groupValues[1], it.groupValues[2]) }
                .toList()
        }
    }

    private fun expandMissingMappingAliasRules(
        rules: List<RegistryAliasRule>,
        registryFields: Map<String, RegistryFieldInfo>
    ): List<RegistryAliasEntry> {
        val entries = linkedSetOf<RegistryAliasEntry>()
        for (rule in rules) {
            val field = registryFields[rule.kind] ?: continue
            val expanded = field.registeredNames
                .filter { it.contains(rule.newPattern) }
                .map { newId -> newId.replace(rule.newPattern, rule.oldPattern) to newId }
                .filter { (oldId, newId) -> oldId != newId }
            val aliases = expanded.ifEmpty { listOf(rule.oldPattern to rule.newPattern) }
            aliases.forEach { (oldId, newId) ->
                entries.add(RegistryAliasEntry(field.ref, oldId, newId))
            }
        }
        return entries.toList()
    }

    private fun missingMappingAliasClassSource(
        packageName: String,
        className: String,
        modAccess: ModAccess,
        registryFields: Map<String, RegistryFieldInfo>,
        entries: List<RegistryAliasEntry>
    ): String {
        val imports = linkedSetOf(
            "net.minecraft.resources.ResourceLocation",
            "net.neoforged.neoforge.registries.DeferredRegister"
        )
        modAccess.modImport?.let { imports.add(it) }
        entries.map { it.registryRef.substringBefore('.') }
            .toSet()
            .forEach { simpleClass ->
                registryFields.values.firstOrNull { it.className == simpleClass }?.qualifiedClassName?.let(imports::add)
            }

        val grouped = entries.groupBy { it.oldId to it.newId }
        val lines = grouped.entries.map { (key, group) ->
            val refs = group.map { it.registryRef }.distinct()
            val oldId = key.first
            val newId = key.second
            if (refs.size == 1) {
                """		remapEntry(${refs.first()}, "$oldId", "$newId");"""
            } else {
                """		remapEntryFromRegistries("$oldId", "$newId", ${refs.joinToString(", ")});"""
            }
        }

        val packageLine = if (packageName.isBlank()) "" else "package $packageName;\n\n"
        return buildString {
            append(packageLine)
            imports.sorted().forEach { append("import $it;\n") }
            append("\n")
            append("public class $className {\n\n")
            append("\tpublic static void addRegistryAliases() {\n")
            lines.forEach { append(it).append("\n") }
            append("\t}\n\n")
            append("\tprivate static void remapEntry(DeferredRegister<?> registry, String oldId, String newId) {\n")
            append("\t\tregistry.addAlias(prefix(oldId), prefix(newId));\n")
            append("\t}\n\n")
            append("\tprivate static void remapEntryFromRegistries(String oldId, String newId, DeferredRegister<?>... registries) {\n")
            append("\t\tfor (DeferredRegister<?> registry : registries) {\n")
            append("\t\t\tregistry.addAlias(prefix(oldId), prefix(newId));\n")
            append("\t\t}\n")
            append("\t}\n\n")
            append("\tprivate static ResourceLocation prefix(String id) {\n")
            append("\t\treturn ResourceLocation.fromNamespaceAndPath(${modAccess.modIdExpression}, id);\n")
            append("\t}\n")
            append("}\n")
        }
    }

    private fun addMissingMappingAliasCall(source: String, remapperFqn: String, remapperSimpleName: String): String {
        if (source.contains("$remapperSimpleName.addRegistryAliases()")) return source
        var result = source
        val packageName = packageNameOf(source)
        if (remapperFqn.contains('.') && remapperFqn.substringBeforeLast('.') != packageName) {
            result = addImportIfMissing(result, remapperFqn)
        }
        val lines = result.lines().toMutableList()
        val insertIndex = lines.indexOfLast { Regex("""\.register\(\s*[A-Za-z_$][\w$]*\s*\)\s*;""").containsMatchIn(it) }
        if (insertIndex < 0) return result
        val indent = lines[insertIndex].takeWhile { it == ' ' || it == '\t' }
        lines.add(insertIndex + 1, "$indent$remapperSimpleName.addRegistryAliases();")
        return lines.joinToString(if (result.contains("\r\n")) "\r\n" else "\n")
    }

    /**
     * Migrate the common Forge item capability read pattern:
     *
     * Optional<T> maybe = stack.getCapability(ForgeCapabilities.ITEM_HANDLER).resolve();
     * if (maybe.isEmpty()) return ...
     * T handler = maybe.get();
     *
     * In NeoForge 1.21, ItemStack#getCapability returns nullable T directly.
     */
    private fun migrateItemStackCapabilityOptionals(
        source: String,
        cu: CompilationUnit,
        file: Path,
        changes: MutableList<Change>
    ): String {
        val itemStackNames = findItemStackNames(cu)
        if (itemStackNames.isEmpty() || !source.contains("getCapability")) return source

        var result = source
        var changed = false

        for (name in itemStackNames) {
            val itemHandlerRegex = Regex(
                """\b${Regex.escape(name)}\.getCapability\(\s*Capabilities\.(?:ITEM_HANDLER|ItemHandler\.BLOCK)(?:\s*,\s*[^)\r\n]+)?\s*\)"""
            )
            result = itemHandlerRegex.replace(result) { match ->
                changed = true
                val line = lineNumber(source, match.range.first)
                changes.add(Change(
                    file = file,
                    line = line,
                    description = "ItemStack ForgeCapabilities.ITEM_HANDLER -> Capabilities.ItemHandler.ITEM",
                    before = match.value,
                    after = "$name.getCapability(Capabilities.ItemHandler.ITEM)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-itemstack-item-handler-capability"
                ))
                "$name.getCapability(Capabilities.ItemHandler.ITEM)"
            }
        }

        val migratedOptionalNames = mutableSetOf<String>()
        val optionalResolveRegex = Regex(
            """(?m)^([ \t]*)Optional<([^>\r\n]+)>\s+(\w+)\s*=\s*([^;\r\n]+?\.getCapability\([^;\r\n]+?\))\.resolve\(\);\s*$"""
        )
        result = optionalResolveRegex.replace(result) { match ->
            val indent = match.groupValues[1]
            val type = match.groupValues[2].trim()
            val varName = match.groupValues[3]
            val getter = match.groupValues[4].trim()
            migratedOptionalNames.add(varName)
            changed = true
            val replacement = "$indent$type $varName = $getter;"
            changes.add(Change(
                file = file,
                line = lineNumber(result, match.range.first),
                description = "Capability Optional.resolve() -> nullable capability local",
                before = match.value.trim(),
                after = replacement.trim(),
                confidence = Confidence.HIGH,
                ruleId = "struct-capability-resolve-nullable"
            ))
            replacement
        }

        for (varName in migratedOptionalNames) {
            result = Regex("""\b${Regex.escape(varName)}\.isEmpty\(\)""").replace(result) { match ->
                changed = true
                changes.add(Change(
                    file = file,
                    line = lineNumber(result, match.range.first),
                    description = "Capability Optional.isEmpty() -> null check",
                    before = match.value,
                    after = "$varName == null",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-capability-optional-empty-null"
                ))
                "$varName == null"
            }
            result = Regex("""\b${Regex.escape(varName)}\.isPresent\(\)""").replace(result) { match ->
                changed = true
                changes.add(Change(
                    file = file,
                    line = lineNumber(result, match.range.first),
                    description = "Capability Optional.isPresent() -> null check",
                    before = match.value,
                    after = "$varName != null",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-capability-optional-present-null"
                ))
                "$varName != null"
            }
            result = Regex("""\b${Regex.escape(varName)}\.get\(\)""").replace(result) { match ->
                changed = true
                changes.add(Change(
                    file = file,
                    line = lineNumber(result, match.range.first),
                    description = "Capability Optional.get() -> nullable local",
                    before = match.value,
                    after = varName,
                    confidence = Confidence.HIGH,
                    ruleId = "struct-capability-optional-get-local"
                ))
                varName
            }
        }

        val directIsPresentRegex = Regex("""(\b\w+\.getCapability\([^;\r\n]+?\))\.isPresent\(\)""")
        result = directIsPresentRegex.replace(result) { match ->
            val getter = match.groupValues[1]
            if (itemStackNames.none { getter.startsWith("$it.") }) {
                match.value
            } else {
                changed = true
                val replacement = "$getter != null"
                changes.add(Change(
                    file = file,
                    line = lineNumber(result, match.range.first),
                    description = "ItemStack capability isPresent() -> null check",
                    before = match.value,
                    after = replacement,
                    confidence = Confidence.HIGH,
                    ruleId = "struct-itemstack-capability-present-null"
                ))
                replacement
            }
        }

        if (changed && result.contains("import java.util.Optional;") &&
            !Regex("""\bOptional(?:[.<])""").containsMatchIn(result.replace("import java.util.Optional;", ""))
        ) {
            result = result.replace(Regex("""import java\.util\.Optional;\r?\n"""), "")
            changes.add(Change(
                file = file,
                line = 0,
                description = "Remove stale Optional import after capability nullable migration",
                before = "import java.util.Optional;",
                after = "",
                confidence = Confidence.HIGH,
                ruleId = "struct-capability-remove-optional-import"
            ))
        }

        return result
    }

    private fun findItemStackNames(cu: CompilationUnit): Set<String> {
        val names = mutableSetOf<String>()
        cu.findAll(Parameter::class.java).forEach { parameter ->
            if (parameter.type.asString() == "ItemStack") {
                names.add(parameter.nameAsString)
            }
        }
        cu.findAll(VariableDeclarator::class.java).forEach { variable ->
            if (variable.type.asString() == "ItemStack") {
                names.add(variable.nameAsString)
            }
        }
        return names
    }

    private fun lineNumber(text: String, offset: Int): Int =
        text.substring(0, offset.coerceIn(0, text.length)).count { it == '\n' } + 1

    /**
     * Detect LazyOptional usage and flag for null-based replacement.
     */
    private fun detectLazyOptionalUsage(
        cu: CompilationUnit,
        file: Path,
        changes: MutableList<Change>
    ) {
        // Detect LazyOptional type usage
        cu.findAll(ClassOrInterfaceType::class.java).forEach { type ->
            if (type.nameAsString == "LazyOptional") {
                val line = type.begin.map { it.line }.orElse(0)
                changes.add(Change(
                    file = file, line = line,
                    description = "LazyOptional<T> -> @Nullable T (capabilities no longer use LazyOptional)",
                    before = type.toString(),
                    after = "@Nullable ${type.typeArguments.map { it.first().toString() }.orElse("T")}",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-lazy-optional"
                ))
            }
        }

        // Detect .ifPresent() / .orElse() on LazyOptional
        cu.findAll(MethodCallExpr::class.java).forEach { call ->
            if (call.nameAsString == "ifPresent" || call.nameAsString == "orElse" ||
                call.nameAsString == "orElseThrow" || call.nameAsString == "resolve") {
                // Check if scope contains capability-related expressions
                val scopeStr = call.scope.map { it.toString() }.orElse("")
                if (scopeStr.contains("getCapability") || scopeStr.contains("LazyOptional") ||
                    scopeStr.contains("cap") || scopeStr.contains("handler")) {
                    val line = call.begin.map { it.line }.orElse(0)
                    changes.add(Change(
                        file = file, line = line,
                        description = "LazyOptional.${call.nameAsString}() -> null check pattern",
                        before = call.toString(),
                        after = "// Replace with: var result = ...; if (result != null) { ... }",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-lazy-optional-method"
                    ))
                }
            }
        }
    }

    /**
     * Remove NeoForge.EVENT_BUS.register(this) from @Mod classes that have no @SubscribeEvent methods.
     * In NeoForge 1.21.1, registering a class without @SubscribeEvent methods throws an IllegalArgumentException.
     */
    // Known mod-bus event types (fired on mod event bus, NOT game bus)
    private val modBusEventTypes = setOf(
        "EntityAttributeCreationEvent",
        "BuildCreativeModeTabContentsEvent",
        "EntityRenderersEvent",
        "RegisterEvent",
        "FMLCommonSetupEvent",
        "FMLClientSetupEvent",
        "FMLDedicatedServerSetupEvent",
        "GatherDataEvent",
        "RegisterColorHandlersEvent",
        "RegisterParticleProvidersEvent",
        "ModelEvent",
        "TextureAtlasStitchedEvent",
        "RegisterShadersEvent",
        "RegisterKeyMappingsEvent",
        "FMLLoadCompleteEvent",
        "InterModEnqueueEvent",
        "InterModProcessEvent"
    )

    private fun removeEmptyEventBusRegistration(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { javaFile ->
                val text = javaFile.toFile().readText()
                // Only process @Mod-annotated classes
                if (!text.contains("@Mod(") && !text.contains("@Mod\n")) return@forEach
                // Only process files with EVENT_BUS.register(this)
                if (!text.contains("EVENT_BUS.register(this)")) return@forEach

                // Check if any @SubscribeEvent methods handle game-bus events
                // If ALL @SubscribeEvent methods handle mod-bus events, remove EVENT_BUS.register(this)
                val hasGameBusEvents = if (!text.contains("@SubscribeEvent")) {
                    false
                } else {
                    // Find @SubscribeEvent method parameter types
                    val subscribePattern = Regex("""@SubscribeEvent\s+(?:@\w+(?:\([^)]*\))?\s+)*(?:public\s+)?(?:static\s+)?(?:void\s+)\w+\s*\((\w+(?:\.\w+)*)""")
                    val eventTypes = subscribePattern.findAll(text).map { it.groupValues[1] }.toList()
                    eventTypes.any { eventType ->
                        // Check both the full type (e.g. EntityRenderersEvent.RegisterRenderers)
                        // and simple name against known mod-bus events
                        !modBusEventTypes.any { modEvent ->
                            eventType.contains(modEvent)
                        }
                    }
                }

                if (hasGameBusEvents) return@forEach

                // Remove the EVENT_BUS.register(this) line
                val modified = text.replace(
                    Regex("""^\s*(?:NeoForge|MinecraftForge)\.EVENT_BUS\.register\(this\);\s*\r?\n?""", RegexOption.MULTILINE),
                    ""
                )

                if (modified != text) {
                    if (!dryRun) {
                        javaFile.toFile().writeText(modified)
                    }
                    changes.add(Change(
                        file = javaFile,
                        line = 0,
                        description = "Remove EVENT_BUS.register(this) — all @SubscribeEvent methods are mod-bus events",
                        before = "NeoForge.EVENT_BUS.register(this);",
                        after = "(removed)",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-remove-empty-eventbus-register"
                    ))
                }
            }

        return changes
    }

    /**
     * Migrate FMLJavaModLoadingContext constructor parameter to IEventBus + ModContainer.
     * In NeoForge 1.21.1, @Mod constructors receive IEventBus and ModContainer directly
     * instead of FMLJavaModLoadingContext.
     */
    private fun migrateFMLJavaModLoadingContext(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { javaFile ->
                var text = javaFile.toFile().readText()
                if (!text.contains("@Mod(") && !text.contains("@Mod\n")) return@forEach
                if (!text.contains("FMLJavaModLoadingContext")) return@forEach

                val original = text
                val className = Regex("""public\s+class\s+(\w+)""").find(text)?.groupValues?.get(1)

                // Replace constructor parameter: FMLJavaModLoadingContext <name> -> IEventBus modEventBus
                val ctorParamPattern = Regex("""FMLJavaModLoadingContext\s+(\w+)""")
                val ctorMatch = ctorParamPattern.find(text)
                if (ctorMatch != null) {
                    val contextVarName = ctorMatch.groupValues[1]

                    // Replace the parameter type
                    text = text.replace(ctorMatch.value, "IEventBus modEventBus")
                    if (className != null) {
                        val constructorPattern = Regex("""public\s+${Regex.escape(className)}\s*\(([^)]*\bIEventBus\s+modEventBus[^)]*)\)""")
                        val constructorMatch = constructorPattern.find(text)
                        if (constructorMatch != null && !constructorMatch.groupValues[1].contains("ModContainer")) {
                            val params = constructorMatch.groupValues[1].trim()
                            text = text.replaceRange(
                                constructorMatch.range,
                                "public $className($params, ModContainer modContainer)"
                            )
                        }
                    }

                    // Replace context.getModEventBus() -> modEventBus
                    text = text.replace("${contextVarName}.getModEventBus()", "modEventBus")

                    // Replace context.registerConfig -> modContainer.registerConfig
                    text = text.replace("${contextVarName}.registerConfig(", "modContainer.registerConfig(")
                    text = text.replace(
                        "ModLoadingContext.get().getActiveContainer().registerConfig(",
                        "modContainer.registerConfig("
                    )
                    text = text.replace(
                        "ModLoadingContext.get().registerConfig(",
                        "modContainer.registerConfig("
                    )

                    // Replace IEventBus <varName> = context.getModEventBus() assignment with modEventBus
                    val busAssignPattern = Regex("""IEventBus\s+(\w+)\s*=\s*modEventBus;\s*\r?\n""")
                    val busAssignMatch = busAssignPattern.find(text)
                    if (busAssignMatch != null) {
                        val busVarName = busAssignMatch.groupValues[1]
                        // Remove the redundant assignment and replace usages
                        text = text.replace(busAssignMatch.value, "")
                        text = Regex("\\b${Regex.escape(busVarName)}\\b").replace(text, "modEventBus")
                    }
                    text = Regex("""\s*IEventBus\s+modEventBus\s*=\s*this\.modEventBus;\s*\r?\n""")
                        .replace(text, "\n")

                    if (className != null) {
                        val delegatedCtorPattern = Regex(
                            """(?s)\s*(?:@SuppressWarnings\("removal"\)\s*)?public\s+${Regex.escape(className)}\s*\(\s*(?:ModContainer\s+\w+)?\s*\)\s*\{\s*this\s*\(\s*FMLJavaModLoadingContext\.get\(\)\s*\)\s*;\s*\}\s*"""
                        )
                        text = delegatedCtorPattern.replace(text, "\n")
                    }

                    // Remove FMLJavaModLoadingContext import
                    text = text.replace(Regex("""import\s+net\.neoforged\.fml\.javafmlmod\.FMLJavaModLoadingContext;\s*\r?\n"""), "")

                    // Remove ModLoadingContext import if present and unused
                    if (!text.contains("ModLoadingContext.")) {
                        text = text.replace(Regex("""import\s+net\.neoforged\.fml\.ModLoadingContext;\s*\r?\n"""), "")
                    }

                    // Ensure ModContainer import exists
                    if (!text.contains("import net.neoforged.fml.ModContainer;")) {
                        text = text.replace(
                            "import net.neoforged.fml.common.Mod;",
                            "import net.neoforged.fml.ModContainer;\nimport net.neoforged.fml.common.Mod;"
                        )
                    }
                }

                if (ctorMatch == null && text.contains("modContainer")) {
                    if (className != null && text.contains("FMLJavaModLoadingContext.get().getModEventBus()")) {
                        val constructorPattern = Regex(
                            """public\s+${Regex.escape(className)}\s*\(([^)]*)\)"""
                        )
                        val constructorMatch = constructorPattern.find(text)
                        if (constructorMatch != null) {
                            val params = constructorMatch.groupValues[1].trim()
                            val replacement = if (Regex("""\bIEventBus\b""").containsMatchIn(params)) {
                                constructorMatch.value
                            } else {
                                val newParams = if (params.isBlank()) {
                                    "IEventBus modEventBus, ModContainer modContainer"
                                } else {
                                    "IEventBus modEventBus, $params"
                                }
                                "public $className($newParams)"
                            }
                            text = text.replaceRange(constructorMatch.range, replacement)
                        }
                    }
                    text = text.replace(
                        "FMLJavaModLoadingContext.get().getModEventBus()",
                        "modEventBus"
                    )
                    text = text.replace(
                        "ModLoadingContext.get().getActiveContainer().registerConfig(",
                        "modContainer.registerConfig("
                    )
                    text = text.replace(
                        "ModLoadingContext.get().registerConfig(",
                        "modContainer.registerConfig("
                    )

                    text = text.replace(Regex("""import\s+net\.neoforged\.fml\.javafmlmod\.FMLJavaModLoadingContext;\s*\r?\n"""), "")
                    if (!text.contains("ModLoadingContext.")) {
                        text = text.replace(Regex("""import\s+net\.neoforged\.fml\.ModLoadingContext;\s*\r?\n"""), "")
                    }
                }

                if (text.contains("ModContainer modContainer") && !text.contains("import net.neoforged.fml.ModContainer;")) {
                    text = text.replace(
                        "import net.neoforged.fml.common.Mod;",
                        "import net.neoforged.fml.ModContainer;\nimport net.neoforged.fml.common.Mod;"
                    )
                }
                if (text.contains("IEventBus modEventBus") && !text.contains("import net.neoforged.bus.api.IEventBus;")) {
                    text = if (text.contains("import net.neoforged.fml.ModContainer;")) {
                        text.replace(
                            "import net.neoforged.fml.ModContainer;",
                            "import net.neoforged.bus.api.IEventBus;\nimport net.neoforged.fml.ModContainer;"
                        )
                    } else {
                        text.replace(
                            "import net.neoforged.fml.common.Mod;",
                            "import net.neoforged.bus.api.IEventBus;\nimport net.neoforged.fml.common.Mod;"
                        )
                    }
                }

                if (text != original) {
                    if (!dryRun) {
                        javaFile.toFile().writeText(text)
                    }
                    changes.add(Change(
                        file = javaFile,
                        line = 0,
                        description = "Migrate FMLJavaModLoadingContext to IEventBus + ModContainer constructor",
                        before = "FMLJavaModLoadingContext context",
                        after = "IEventBus modEventBus, ModContainer modContainer",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-fml-context-to-eventbus"
                    ))
                }
            }

        return changes
    }

    private data class FluidBucketCapabilityMigration(
        val itemClassFile: Path,
        val packageName: String,
        val className: String
    )

    private data class RegisteredItemReference(
        val registryFile: Path,
        val packageName: String,
        val registryClassName: String,
        val fieldName: String
    ) {
        val qualifiedRegistryClass: String
            get() = if (packageName.isBlank()) registryClassName else "$packageName.$registryClassName"
    }

    private fun migrateFluidBucketItemCapabilities(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()

        val migrations = javaFiles.mapNotNull { javaFile ->
            val text = javaFile.readText()
            if (!text.contains("extends BucketItem") ||
                !text.contains("initCapabilities") ||
                !text.contains("FluidBucketWrapper")
            ) {
                return@mapNotNull null
            }

            val className = Regex("""\bclass\s+(\w+)\s+extends\s+BucketItem\b""")
                .find(text)
                ?.groupValues
                ?.get(1)
                ?: return@mapNotNull null
            val packageName = packageNameOf(text)
            var modified = text

            val beforeMethodRemoval = modified
            modified = removeFluidBucketInitCapabilities(modified)
            if (modified == beforeMethodRemoval) return@mapNotNull null

            modified = migrateBucketItemSupplierSuperCall(modified, className)
            modified = addFluidBucketCapabilityRegistrationMethod(modified, className)
            modified = addImportIfMissing(modified, "net.minecraft.world.level.ItemLike")
            modified = addImportIfMissing(modified, "net.neoforged.neoforge.capabilities.Capabilities")
            modified = addImportIfMissing(modified, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")
            modified = addImportIfMissing(modified, "net.neoforged.neoforge.fluids.capability.wrappers.FluidBucketWrapper")

            if (!dryRun) {
                javaFile.writeText(modified)
            }
            changes.add(Change(
                file = javaFile,
                line = 0,
                description = "Migrate legacy BucketItem initCapabilities() to RegisterCapabilitiesEvent item provider",
                before = "initCapabilities(...) { return new FluidBucketWrapper(stack); }",
                after = "registerCapabilities(RegisterCapabilitiesEvent, ItemLike...)",
                confidence = Confidence.HIGH,
                ruleId = "struct-fluid-bucket-item-capability"
            ))

            FluidBucketCapabilityMigration(
                itemClassFile = javaFile,
                packageName = packageName,
                className = className
            )
        }

        if (migrations.isEmpty()) return changes

        val mainClass = detectModMainClass(projectDir) ?: return changes
        var mainText = mainClass.readText()
        val originalMainText = mainText
        val mainPackage = packageNameOf(mainText)
        val constructorBusName = Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)""")
            .find(mainText)
            ?.groupValues
            ?.get(1)
            ?: "modEventBus"

        for (migration in migrations) {
            val itemRefs = findRegisteredItemReferences(javaFiles, migration.className)
            if (itemRefs.isEmpty()) continue
            if (mainText.contains("${migration.className}.registerCapabilities")) continue

            if (migration.packageName != mainPackage) {
                mainText = addImportIfMissing(mainText, "${migration.packageName}.${migration.className}")
            }
            mainText = addImportIfMissing(mainText, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")
            itemRefs.map { it.qualifiedRegistryClass }
                .distinct()
                .filter { it.substringBeforeLast('.', "") != mainPackage }
                .forEach { mainText = addImportIfMissing(mainText, it) }

            val itemArguments = itemRefs.joinToString(",\n") { ref ->
                "                ${ref.registryClassName}.${ref.fieldName}.get()"
            }
            val registration = """
        $constructorBusName.addListener((RegisterCapabilitiesEvent event) -> ${migration.className}.registerCapabilities(event,
$itemArguments
        ));
""".trimEnd()

            mainText = insertModBusListener(mainText, constructorBusName, registration, itemRefs.first().registryClassName)
            changes.add(Change(
                file = mainClass,
                line = 0,
                description = "Register ${migration.className} fluid item capability providers on the mod event bus",
                before = "(no RegisterCapabilitiesEvent listener)",
                after = "${migration.className}.registerCapabilities(event, ...)",
                confidence = Confidence.HIGH,
                ruleId = "struct-fluid-bucket-capability-listener"
            ))
        }

        if (mainText != originalMainText && !dryRun) {
            mainClass.writeText(mainText)
        }

        return changes
    }

    private fun removeFluidBucketInitCapabilities(source: String): String {
        val methodName = "initCapabilities"
        var searchStart = source.indexOf(methodName)
        var result = source
        while (searchStart >= 0) {
            val methodNameIndex = result.indexOf(methodName, searchStart)
            if (methodNameIndex < 0) return result
            val openBrace = result.indexOf('{', methodNameIndex)
            if (openBrace < 0) return result
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) return result
            val signatureStart = result.lastIndexOf('\n', methodNameIndex).let { if (it < 0) 0 else it + 1 }
            val annotationStart = Regex("""(?m)[ \t]*@Override\s*\r?\n\s*$""")
                .findAll(result.substring(0, signatureStart))
                .lastOrNull()
                ?.range
                ?.first
                ?: signatureStart
            val methodText = result.substring(annotationStart, closeBrace + 1)
            if (!methodText.contains("FluidBucketWrapper") || !methodText.contains("ICapabilityProvider")) {
                searchStart = closeBrace + 1
                continue
            }
            val end = (closeBrace + 1).let { idx ->
                if (idx < result.length && result[idx] == '\r') (idx + 1).coerceAtMost(result.length)
                else idx
            }.let { idx ->
                if (idx < result.length && result[idx] == '\n') idx + 1 else idx
            }
            return result.removeRange(annotationStart, end)
        }
        return result
    }

    private fun migrateBucketItemSupplierSuperCall(source: String, className: String): String {
        val constructorPattern = Regex(
            """(public\s+${Regex.escape(className)}\s*\(\s*Supplier\s*<\s*\?\s+extends\s+Fluid\s*>\s+(\w+)\s*,\s*Properties\s+(\w+)\s*\)\s*\{\s*)super\(\s*\2\s*,\s*\3\s*\);"""
        )
        return constructorPattern.replace(source) { match ->
            "${match.groupValues[1]}super(${match.groupValues[2]}.get(), ${match.groupValues[3]});"
        }
    }

    private fun addFluidBucketCapabilityRegistrationMethod(source: String, className: String): String {
        if (source.contains("registerCapabilities(RegisterCapabilitiesEvent")) return source
        val classMatch = Regex("""\bclass\s+${Regex.escape(className)}\s+extends\s+BucketItem\b""").find(source)
            ?: return source
        val classOpen = source.indexOf('{', classMatch.range.last)
        if (classOpen < 0) return source
        val method = """

    public static void registerCapabilities(RegisterCapabilitiesEvent event, ItemLike... items) {
        event.registerItem(Capabilities.FluidHandler.ITEM, (stack, context) -> new FluidBucketWrapper(stack), items);
    }
"""
        return source.substring(0, classOpen + 1) + method + source.substring(classOpen + 1)
    }

    private fun findRegisteredItemReferences(
        javaFiles: List<Path>,
        itemClassName: String
    ): List<RegisteredItemReference> =
        javaFiles.flatMap { javaFile ->
            val text = javaFile.readText()
            if (!text.contains("new $itemClassName")) return@flatMap emptyList()
            val packageName = packageNameOf(text)
            val registryClassName = Regex("""\bclass\s+(\w+)\b""")
                .find(text)
                ?.groupValues
                ?.get(1)
                ?: return@flatMap emptyList()
            val fieldPattern = Regex(
                """(?s)public\s+static\s+final\s+[^=;]+?\s+(\w+)\s*=\s*\w+\.register\s*\([^;]*?new\s+${Regex.escape(itemClassName)}\s*\("""
            )
            fieldPattern.findAll(text).map { match ->
                RegisteredItemReference(
                    registryFile = javaFile,
                    packageName = packageName,
                    registryClassName = registryClassName,
                    fieldName = match.groupValues[1]
                )
            }.toList()
        }

    private fun insertModBusListener(
        source: String,
        eventBusName: String,
        registration: String,
        preferredRegistryClassName: String
    ): String {
        val constructorBody = findConstructorBodyWithEventBus(source, eventBusName)
        fun insideConstructor(match: MatchResult): Boolean =
            constructorBody == null || match.range.first in constructorBody

        val afterPreferredRegister = Regex(
            """(?m)^([ \t]*)${Regex.escape(preferredRegistryClassName)}(?:\.\w+)*\.register\(${Regex.escape(eventBusName)}\);\s*$"""
        ).findAll(source)
            .lastOrNull(::insideConstructor)
        if (afterPreferredRegister != null) {
            val insertPos = afterPreferredRegister.range.last + 1
            return source.substring(0, insertPos) + "\n" + registration + source.substring(insertPos)
        }

        val afterAnyRegister = Regex("""(?m)^([ \t]*)[\w.]+\.register\(${Regex.escape(eventBusName)}\);\s*$""")
            .findAll(source)
            .filter(::insideConstructor)
            .lastOrNull()
        if (afterAnyRegister != null) {
            val insertPos = afterAnyRegister.range.last + 1
            return source.substring(0, insertPos) + "\n" + registration + source.substring(insertPos)
        }

        if (constructorBody != null) {
            val localDeclaration = Regex(
                """(?m)^([ \t]*)IEventBus\s+${Regex.escape(eventBusName)}\s*=[^;]*;\s*$"""
            ).findAll(source)
                .filter(::insideConstructor)
                .firstOrNull()
            if (localDeclaration != null) {
                val insertPos = localDeclaration.range.last + 1
                return source.substring(0, insertPos) + "\n" + registration + source.substring(insertPos)
            }

            val insertPos = constructorBody.last + 1
            return source.substring(0, insertPos) + "\n" + registration + "\n" + source.substring(insertPos)
        }

        return source + "\n" + registration + "\n"
    }

    private fun findConstructorBodyWithEventBus(source: String, eventBusName: String): IntRange? {
        val className = Regex("""\b(?:public\s+)?class\s+(\w+)\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return null
        val constructorPattern = Regex("""\bpublic\s+${Regex.escape(className)}\s*\([^)]*\)\s*\{""")
        for (constructorMatch in constructorPattern.findAll(source)) {
            val openBrace = source.indexOf('{', constructorMatch.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (openBrace < 0 || closeBrace <= openBrace) continue
            val header = source.substring(constructorMatch.range.first, openBrace)
            val body = source.substring(openBrace + 1, closeBrace)
            val parameterBus = Regex("""\bIEventBus\s+${Regex.escape(eventBusName)}\b""").containsMatchIn(header)
            val localBus = Regex("""\bIEventBus\s+${Regex.escape(eventBusName)}\s*=""").containsMatchIn(body)
            if (parameterBus || localBus) {
                return (openBrace + 1) until closeBrace
            }
        }
        return null
    }

    private fun migrateCustomFluidItemCapabilities(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()

        val capabilityFile = javaFiles.firstOrNull { file ->
            val text = file.readText()
            text.contains("class CustomFluidCapabilities") &&
                text.contains("CustomFluidContainerHandler implements IFluidHandlerItem") &&
                text.contains("ICapabilityProvider") &&
                text.contains("createProvider")
        } ?: return changes

        var capabilityText = capabilityFile.readText()
        val originalCapabilityText = capabilityText
        if (!capabilityText.contains("registerCapabilities(RegisterCapabilitiesEvent")) {
            val modAccess = inferModAccess(capabilityText)
            capabilityText = capabilityText.replace(
                modAccess?.let {
                    Regex("""(?m)^[ \t]*@EventBusSubscriber\(modid\s*=\s*${Regex.escape(it.modIdExpression)}\)\s*\r?\n""")
                } ?: Regex("""(?!)"""),
                ""
            )
            capabilityText = capabilityText.replace(
                Regex("""(?m)^[ \t]*public\s+static\s+final\s+ResourceLocation\s+CAPABILITY_ID\s*=\s*[^;\r\n]+;\s*\r?\n"""),
                ""
            )
            capabilityText = removeMethodByName(capabilityText, "attachCapabilities")
            capabilityText = removeMethodByName(capabilityText, "createProvider")
            capabilityText = removeMethodByName(capabilityText, "createProvider")
            capabilityText = removeInnerClassByName(capabilityText, "CustomFluidContainerProvider")
            capabilityText = addCustomFluidRegisterCapabilitiesMethod(capabilityText)

            listOf(
                "net.minecraft.core.Direction",
                "com.modporter.compat.Capability",
                "net.neoforged.neoforge.capabilities.ICapabilityProvider",
                "com.modporter.compat.LazyOptional",
                "net.neoforged.neoforge.event.AttachCapabilitiesEvent",
                "net.neoforged.bus.api.SubscribeEvent",
                "net.neoforged.fml.common.Mod",
                "javax.annotation.Nonnull",
                "org.jetbrains.annotations.Nullable",
                "net.neoforged.fml.common.EventBusSubscriber"
            ).plus(listOfNotNull(modAccess?.modImport)).forEach { importName ->
                capabilityText = capabilityText.replace(
                    Regex("""(?m)^[ \t]*import\s+${Regex.escape(importName)};\s*\r?\n"""),
                    ""
                )
            }
            capabilityText = addImportIfMissing(capabilityText, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")

            if (capabilityText != originalCapabilityText) {
                if (!dryRun) {
                    capabilityFile.writeText(capabilityText)
                }
                changes.add(Change(
                    file = capabilityFile,
                    line = 0,
                    description = "Migrate CustomFluidCapabilities provider wrapper to RegisterCapabilitiesEvent item registrations",
                    before = "AttachCapabilitiesEvent + ICapabilityProvider wrapper",
                    after = "RegisterCapabilitiesEvent.registerItem(Capabilities.FluidHandler.ITEM, ...)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-custom-fluid-item-capabilities"
                ))
            }
        }

        var removedItemHooks = false
        javaFiles.forEach { javaFile ->
            var text = javaFile.readText()
            if (!text.contains("initCapabilities") || !text.contains("CustomFluidCapabilities.createProvider")) {
                return@forEach
            }
            val original = text
            text = removeInitCapabilitiesContaining(text, "CustomFluidCapabilities.createProvider")
            text = text.replace(
                Regex("""(?m)^[ \t]*import\s+net\.neoforged\.neoforge\.capabilities\.ICapabilityProvider;\s*\r?\n"""),
                ""
            )
            if (!text.contains("CompoundTag")) {
                text = text.replace(Regex("""(?m)^[ \t]*import\s+net\.minecraft\.nbt\.CompoundTag;\s*\r?\n"""), "")
            }
            if (!text.contains("@Nullable")) {
                text = text.replace(Regex("""(?m)^[ \t]*import\s+org\.jetbrains\.annotations\.Nullable;\s*\r?\n"""), "")
            }
            if (text != original) {
                removedItemHooks = true
                if (!dryRun) {
                    javaFile.writeText(text)
                }
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Remove legacy initCapabilities hook for custom fluid item",
                    before = "initCapabilities(...) -> CustomFluidCapabilities.createProvider(...)",
                    after = "Registered through CustomFluidCapabilities.registerCapabilities",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-custom-fluid-item-initcapabilities"
                ))
            }
        }

        if (removedItemHooks || capabilityText != originalCapabilityText) {
            val mainClass = detectModMainClass(projectDir)
            if (mainClass != null) {
                var mainText = mainClass.readText()
                val originalMainText = mainText
                val mainPackage = packageNameOf(mainText)
                val capabilityPackage = packageNameOf(capabilityText)
                val constructorBusName = Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)""")
                    .find(mainText)
                    ?.groupValues
                    ?.get(1)
                    ?: "modEventBus"

                if (!mainText.contains("CustomFluidCapabilities::registerCapabilities")) {
                    if (capabilityPackage != mainPackage) {
                        mainText = addImportIfMissing(mainText, "$capabilityPackage.CustomFluidCapabilities")
                    }
                    val registration = "        $constructorBusName.addListener(CustomFluidCapabilities::registerCapabilities);"
                    mainText = insertModBusListener(mainText, constructorBusName, registration, "CustomFluidItems")
                    changes.add(Change(
                        file = mainClass,
                        line = 0,
                        description = "Register CustomFluidCapabilities on the mod event bus",
                        before = "(no CustomFluidCapabilities listener)",
                        after = "modEventBus.addListener(CustomFluidCapabilities::registerCapabilities)",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-custom-fluid-capability-listener"
                    ))
                }

                if (mainText != originalMainText && !dryRun) {
                    mainClass.writeText(mainText)
                }
            }
        }

        return changes
    }

    private data class CuriosItemCapabilityMigration(
        val compatFile: Path,
        val compatPackageName: String,
        val compatClassName: String,
        val itemClassNames: Set<String>,
        val itemReferences: List<RegisteredItemReference>
    )

    private fun migrateCuriosItemCapabilities(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()

        val compatFile = javaFiles.firstOrNull { javaFile ->
            val text = javaFile.readText()
            text.contains("CurioItemCapability.createProvider") && text.contains("new ICurio")
        } ?: return changes

        var compatText = compatFile.readText()
        val originalCompatText = compatText
        val compatPackageName = packageNameOf(compatText)
        val compatClassName = classNameOfJavaSource(compatText) ?: return changes
        val providerExpression = extractCuriosProviderExpression(compatText) ?: return changes

        compatText = replaceCuriosProviderFactory(compatText, providerExpression)
        compatText = removeImportIfPresent(compatText, "net.neoforged.neoforge.capabilities.ICapabilityProvider")
        compatText = removeImportIfPresent(compatText, "top.theillusivec4.curios.common.capability.CurioItemCapability")
        compatText = addImportIfMissing(compatText, "net.minecraft.world.level.ItemLike")
        compatText = addImportIfMissing(compatText, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")
        compatText = addImportIfMissing(compatText, "top.theillusivec4.curios.api.CuriosCapability")
        compatText = removeUnusedImportsBySimpleNamePattern(compatText, Regex("""[A-Za-z_$][\w$]*PacketHandler"""))

        if (compatText != originalCompatText) {
            if (!dryRun) {
                compatFile.writeText(compatText)
            }
            changes.add(Change(
                file = compatFile,
                line = 0,
                description = "Migrate legacy Curios ICapabilityProvider factory to RegisterCapabilitiesEvent item registration",
                before = "CurioItemCapability.createProvider(new ICurio() { ... })",
                after = "event.registerItem(CuriosCapability.ITEM, (stack, context) -> new ICurio() { ... }, items)",
                confidence = Confidence.HIGH,
                ruleId = "struct-curios-item-capability"
            ))
        }

        val itemClassNames = linkedSetOf<String>()
        javaFiles.forEach { javaFile ->
            if (javaFile == compatFile) return@forEach
            var text = javaFile.readText()
            if (!text.contains("setupCurio") && !text.contains("setupCuriosCapability")) return@forEach
            val original = text
            val className = classNameOfJavaSource(text)

            text = removeMethodByNameContaining(text, "initCapabilities", listOf("setupCurio", "setupCuriosCapability"))
            text = removeMethodByNameContaining(text, "setupCurio", listOf("setupCuriosCapability"))
            text = removeUnusedSimpleImports(
                text,
                listOf(
                    "net.minecraft.nbt.CompoundTag",
                    "net.minecraft.world.item.ItemStack",
                    "net.neoforged.neoforge.capabilities.ICapabilityProvider",
                    "net.neoforged.fml.ModList",
                    "org.jetbrains.annotations.Nullable",
                    "$compatPackageName.$compatClassName"
                )
            )

            if (text != original) {
                className?.let { itemClassNames.add(it) }
                if (!dryRun) {
                    javaFile.writeText(text)
                }
                changes.add(Change(
                    file = javaFile,
                    line = 0,
                    description = "Remove legacy Item#initCapabilities Curios hook after event registration migration",
                    before = "initCapabilities(...) -> Curios capability provider",
                    after = "Registered through RegisterCapabilitiesEvent.registerItem",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-curios-item-initcapabilities"
                ))
            }
        }

        if (itemClassNames.isEmpty()) return changes
        val itemReferences = itemClassNames
            .flatMap { itemClassName -> findRegisteredItemReferences(javaFiles, itemClassName) }
            .distinctBy { "${it.qualifiedRegistryClass}.${it.fieldName}" }
            .sortedWith(compareBy({ it.qualifiedRegistryClass }, { it.fieldName }))
        if (itemReferences.isEmpty()) return changes

        changes.addAll(registerCuriosItemCapabilitiesOnModBus(
            projectDir,
            CuriosItemCapabilityMigration(
                compatFile = compatFile,
                compatPackageName = compatPackageName,
                compatClassName = compatClassName,
                itemClassNames = itemClassNames,
                itemReferences = itemReferences
            ),
            dryRun
        ))

        return changes
    }

    private fun extractCuriosProviderExpression(source: String): String? {
        val factoryIndex = source.indexOf("CurioItemCapability.createProvider")
        if (factoryIndex < 0) return null
        val newIndex = source.indexOf("new ICurio", factoryIndex)
        if (newIndex < 0) return null
        val openBrace = source.indexOf('{', newIndex)
        if (openBrace < 0) return null
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return null
        return source.substring(newIndex, closeBrace + 1)
    }

    private fun replaceCuriosProviderFactory(source: String, providerExpression: String): String {
        val methodNameIndex = Regex("""\bsetupCuriosCapability\s*\(""")
            .find(source)
            ?.range
            ?.first
            ?: return source
        val openBrace = source.indexOf('{', methodNameIndex)
        if (openBrace < 0) return source
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return source
        val signatureStart = source.lastIndexOf('\n', methodNameIndex).let { if (it < 0) 0 else it + 1 }
        val annotationStart = Regex("""(?m)(?:^[ \t]*@[A-Za-z0-9_.]+(?:\([^)]*\))?\s*\r?\n)+[ \t]*$""")
            .findAll(source.substring(0, signatureStart))
            .lastOrNull()
            ?.range
            ?.first
            ?: signatureStart
        var end = closeBrace + 1
        if (end < source.length && source[end] == '\r') end++
        if (end < source.length && source[end] == '\n') end++

        val migratedProvider = migrateCuriosProviderExpression(providerExpression)
        val replacement = """
	public static void registerCuriosCapabilities(RegisterCapabilitiesEvent event, ItemLike... items) {
		event.registerItem(CuriosCapability.ITEM, (stack, context) -> $migratedProvider, items);
	}

"""
        return source.substring(0, annotationStart) + replacement + source.substring(end)
    }

    private fun migrateCuriosProviderExpression(providerExpression: String): String {
        var result = providerExpression
        result = Regex("""new\s+SoundInfo\(\s*(SoundEvents\.[A-Za-z0-9_]+)\s*,""")
            .replace(result) { match -> "new SoundInfo(${match.groupValues[1]}.value()," }
        result = Regex(
            """[A-Za-z_$][\w$.]*\.CHANNEL\.send\(\s*PacketDistributor\.TRACKING_ENTITY_AND_SELF\.with\(([^)]*)\)\s*,\s*([^;]+)\);"""
        ).replace(result) { match ->
            val target = packetDistributorTargetExpression(match.groupValues[1].trim())
            "PacketDistributor.sendToPlayersTrackingEntityAndSelf($target, ${match.groupValues[2].trim()});"
        }
        return result
    }

    private fun packetDistributorTargetExpression(distributorArgument: String): String {
        val methodReference = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)::([A-Za-z_$][\w$]*)""")
            .matchEntire(distributorArgument)
        if (methodReference != null) {
            return "${methodReference.groupValues[1]}.${methodReference.groupValues[2]}()"
        }
        return distributorArgument
    }

    private fun registerCuriosItemCapabilitiesOnModBus(
        projectDir: Path,
        migration: CuriosItemCapabilityMigration,
        dryRun: Boolean
    ): List<Change> {
        val mainClass = detectModMainClass(projectDir) ?: return emptyList()
        var mainText = mainClass.readText()
        if (mainText.contains("${migration.compatClassName}::registerCuriosCapabilities")) return emptyList()
        val originalMainText = mainText
        val mainPackage = packageNameOf(mainText)
        val constructorBusName = inferModEventBusName(mainText)

        if (migration.compatPackageName != mainPackage) {
            mainText = addImportIfMissing(mainText, "${migration.compatPackageName}.${migration.compatClassName}")
        }
        mainText = addImportIfMissing(mainText, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")
        migration.itemReferences.map { it.qualifiedRegistryClass }
            .distinct()
            .filter { it.substringBeforeLast('.', "") != mainPackage }
            .forEach { mainText = addImportIfMissing(mainText, it) }

        val itemArguments = migration.itemReferences.joinToString(",\n") { ref ->
            "                ${ref.registryClassName}.${ref.fieldName}.get()"
        }
        val registration = """
        $constructorBusName.addListener((RegisterCapabilitiesEvent event) -> ${migration.compatClassName}.registerCuriosCapabilities(event,
$itemArguments
        ));
""".trimEnd()
        val mainWithConditionalRegistration = insertIntoModLoadedBlock(
            mainText,
            "curios",
            registration.prependIndent("    ")
        )
        mainText = mainWithConditionalRegistration ?: insertModBusListener(
            mainText,
            constructorBusName,
            registration,
            migration.itemReferences.first().registryClassName
        )

        if (mainText != originalMainText && !dryRun) {
            mainClass.writeText(mainText)
        }

        return listOf(Change(
            file = mainClass,
            line = 0,
            description = "Register Curios item capability providers on the mod event bus",
            before = "(no RegisterCapabilitiesEvent Curios item listener)",
            after = "${migration.compatClassName}.registerCuriosCapabilities(event, ...)",
            confidence = Confidence.HIGH,
            ruleId = "struct-curios-item-capability-listener"
        ))
    }

    private fun insertIntoModLoadedBlock(source: String, modId: String, registration: String): String? {
        val modLoadedPattern = Regex(
            """if\s*\(\s*ModList\.get\(\)\.isLoaded\(\s*"${Regex.escape(modId)}"\s*\)\s*\)\s*\{"""
        )
        for (match in modLoadedPattern.findAll(source)) {
            val openBrace = source.indexOf('{', match.range.first)
            if (openBrace < 0) continue
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace < 0) continue
            val block = source.substring(openBrace + 1, closeBrace)
            if (block.contains(registration.trim())) return source
            return source.substring(0, openBrace + 1) + "\n" + registration + source.substring(openBrace + 1)
        }
        return null
    }

    private fun classNameOfJavaSource(source: String): String? =
        Regex("""(?m)^[ \t]*(?:(?:public|protected|private|abstract|final|static|sealed|non-sealed)\s+)*(?:class|interface|enum|record)\s+([A-Za-z_$][\w$]*)\b""")
            .find(source)
            ?.groupValues
            ?.get(1)

    private fun removeMethodByNameContaining(source: String, methodName: String, requiredNeedles: List<String>): String {
        var result = source
        var searchStart = 0
        while (searchStart < result.length) {
            val methodNameIndex = Regex("""\b${Regex.escape(methodName)}\s*\(""")
                .find(result, searchStart)
                ?.range
                ?.first
                ?: return result
            val openBrace = result.indexOf('{', methodNameIndex)
            if (openBrace < 0) return result
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) return result
            val signatureStart = result.lastIndexOf('\n', methodNameIndex).let { if (it < 0) 0 else it + 1 }
            val annotationStart = Regex("""(?m)(?:^[ \t]*@[A-Za-z0-9_.]+(?:\([^)]*\))?\s*\r?\n)+[ \t]*$""")
                .findAll(result.substring(0, signatureStart))
                .lastOrNull()
                ?.range
                ?.first
                ?: signatureStart
            val methodText = result.substring(annotationStart, closeBrace + 1)
            if (requiredNeedles.none { methodText.contains(it) }) {
                searchStart = closeBrace + 1
                continue
            }
            var end = closeBrace + 1
            if (end < result.length && result[end] == '\r') end++
            if (end < result.length && result[end] == '\n') end++
            result = result.removeRange(annotationStart, end)
            searchStart = annotationStart
        }
        return result
    }

    private fun removeUnusedSimpleImports(source: String, importNames: List<String>): String {
        var result = source
        for (importName in importNames) {
            val withoutImport = removeImportIfPresent(result, importName)
            val simpleName = importName.substringAfterLast('.')
            if (!Regex("""\b${Regex.escape(simpleName)}\b""").containsMatchIn(withoutImport)) {
                result = withoutImport
            }
        }
        return result
    }

    private fun removeUnusedImportsBySimpleNamePattern(source: String, simpleNamePattern: Regex): String {
        var result = source
        val imports = Regex("""(?m)^[ \t]*import\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.([A-Za-z_$][\w$]*));\s*\r?\n""")
            .findAll(source)
            .map { it.groupValues[1] to it.groupValues[2] }
            .toList()
        for ((importName, simpleName) in imports) {
            if (!simpleNamePattern.matches(simpleName)) continue
            val withoutImport = removeImportIfPresent(result, importName)
            if (!Regex("""\b${Regex.escape(simpleName)}\b""").containsMatchIn(withoutImport)) {
                result = withoutImport
            }
        }
        return result
    }

    private fun cleanupAttachmentRegistrationEventAnnotations(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val changes = mutableListOf<Change>()
        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
            .forEach { file ->
                val original = file.readText()
                if (!original.contains("registerAttachments(IEventBus") || !original.contains("@SubscribeEvent")) {
                    return@forEach
                }
                var modified = Regex("""(?m)^([ \t]*)@SubscribeEvent[ \t]*(?:\r?\n[ \t]*)+((?:public|protected|private)\s+static\s+void\s+registerAttachments\s*\(\s*IEventBus\b)""")
                    .replace(original) { match -> match.groupValues[1] + match.groupValues[2] }
                if (modified != original) {
                    if (!modified.contains("@SubscribeEvent")) {
                        modified = Regex("""(?m)^[ \t]*@(?:Mod\.)?EventBusSubscriber\b[^\r\n]*\r?\n""").replace(modified, "")
                        modified = removeImport(modified, "net.neoforged.fml.common.EventBusSubscriber")
                    }
                    modified = removeUnusedSimpleImports(modified, listOf(
                        "net.neoforged.bus.api.SubscribeEvent",
                        "net.neoforged.fml.common.Mod"
                    ))
                    if (!dryRun) file.writeText(modified)
                    changes.add(Change(
                        file = file,
                        line = 1,
                        description = "Remove event-subscriber wiring from attachment registration helper",
                        before = "@SubscribeEvent public static void registerAttachments(IEventBus)",
                        after = "public static void registerAttachments(IEventBus)",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-attachment-registration-event-cleanup"
                    ))
                }
            }
        return changes
    }

    private fun inferModEventBusName(source: String): String =
        Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+([A-Za-z_$][\w$]*)""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: Regex("""\bIEventBus\s+([A-Za-z_$][\w$]*)\s*=\s*[^;]*getEventBus\(\)\s*;""")
                .find(source)
                ?.groupValues
                ?.get(1)
            ?: "modEventBus"

    private data class LegacyEntityCapability(
        val fieldName: String,
        val apiType: String,
        val implementationType: String?,
        val entityKind: String,
        val setsEntity: Boolean,
        val constructorArgFromEntity: Boolean = false,
        val entityVariableName: String = entityKind.replaceFirstChar { it.lowercase() },
        val idPath: String? = null,
        val modIdExpression: String? = null,
        val serializable: Boolean = false
    )

    private data class LegacyLevelCapability(
        val fieldName: String,
        val apiType: String,
        val implementationType: String,
        val idPath: String,
        val modIdExpression: String
    )

    private fun migrateCustomEntityCapabilities(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        val compatPackage = detectGeneratedCompatPackage(projectDir)
        val changes = mutableListOf<Change>()
        val entityCapabilityNames = linkedSetOf<String>()
        val entityAttachmentNames = linkedSetOf<String>()

        val capabilityFiles = javaFiles.filter { file ->
            val text = file.readText()
            text.contains("CapabilityManager.get(new CapabilityToken") &&
                text.contains("AttachCapabilitiesEvent<Entity>")
        }
        if (capabilityFiles.isEmpty()) return emptyList()

        val implementationByInterface = findCapabilityImplementations(javaFiles)
        val entityKindByInterface = findCapabilityEntityKinds(javaFiles)
        val serializableCapabilityTypes = findSerializableCapabilityTypes(javaFiles)
        val levelCapabilityNames = capabilityFiles
            .flatMap { extractAttachLevelCapabilitySpecs(it.readText(), implementationByInterface).map { spec -> spec.fieldName } }
            .toSet()

        for (capabilityFile in capabilityFiles) {
            val original = capabilityFile.readText()
            val attachEntitySpecs = extractAttachEntityCapabilitySpecs(original)
            val levelCapabilitySpecs = extractAttachLevelCapabilitySpecs(original, implementationByInterface)
                .associateBy { it.fieldName }
            val declarations = Regex(
                """public\s+static\s+final\s+Capability<\s*([A-Za-z_$][\w$]*)\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*CapabilityManager\.get\s*\(\s*new\s+CapabilityToken<>\s*\(\s*\)\s*\{\s*}\s*\)\s*;"""
            ).findAll(original).map { match ->
                val apiType = match.groupValues[1]
                val fieldName = match.groupValues[2]
                val attachSpec = attachEntitySpecs[fieldName]
                val implementationType = attachSpec?.implementationType ?: implementationByInterface[apiType]
                LegacyEntityCapability(
                    fieldName = fieldName,
                    apiType = apiType,
                    implementationType = implementationType,
                    entityKind = attachSpec?.entityKind ?: entityKindByInterface[apiType] ?: "LivingEntity",
                    setsEntity = attachSpec == null && entityKindByInterface.containsKey(apiType),
                    constructorArgFromEntity = attachSpec != null,
                    entityVariableName = attachSpec?.entityVariableName
                        ?: (entityKindByInterface[apiType] ?: "LivingEntity").replaceFirstChar { it.lowercase() },
                    idPath = attachSpec?.idPath,
                    modIdExpression = attachSpec?.modIdExpression,
                    serializable = attachSpec != null &&
                        (apiType in serializableCapabilityTypes ||
                            (implementationType != null && implementationType in serializableCapabilityTypes))
                )
            }.toList()

            val entityCapabilities = declarations.filter {
                it.implementationType != null && !it.serializable && !levelCapabilitySpecs.containsKey(it.fieldName)
            }
            val entityAttachmentCapabilities = declarations.filter {
                it.implementationType != null && it.serializable && it.idPath != null &&
                    it.modIdExpression != null && !levelCapabilitySpecs.containsKey(it.fieldName)
            }
            val levelCapabilities = levelCapabilitySpecs.values.toList()
            val attachmentCapabilitiesPresent = entityAttachmentCapabilities.isNotEmpty() || levelCapabilities.isNotEmpty()
            entityCapabilityNames.addAll(entityCapabilities.map { it.fieldName })
            entityAttachmentNames.addAll(entityAttachmentCapabilities.map { it.fieldName })
            if (entityCapabilities.isEmpty() && entityAttachmentCapabilities.isEmpty() && levelCapabilities.isEmpty()) continue

            var modified = original
            for (capability in declarations) {
                val levelCapability = levelCapabilitySpecs[capability.fieldName]
                val replacement = when {
                    levelCapability != null -> {
                        val attachmentType = if (levelCapability.apiType in serializableCapabilityTypes ||
                            implementationByInterface[levelCapability.apiType] == levelCapability.implementationType) {
                            levelCapability.apiType
                        } else {
                            levelCapability.implementationType
                        }
                        "public static final Supplier<AttachmentType<$attachmentType>> ${levelCapability.fieldName} = ATTACHMENT_TYPES.register(\"${levelCapability.idPath}\", () -> AttachmentType.<net.minecraft.nbt.CompoundTag, $attachmentType>serializable(holder -> new ${levelCapability.implementationType}((Level) holder)).build());"
                    }
                    capability in entityAttachmentCapabilities -> {
                        val attachmentType = if (capability.apiType in serializableCapabilityTypes ||
                            implementationByInterface[capability.apiType] == capability.implementationType) {
                            capability.apiType
                        } else {
                            capability.implementationType!!
                        }
                        "public static final Supplier<AttachmentType<$attachmentType>> ${capability.fieldName} = ATTACHMENT_TYPES.register(\"${capability.idPath}\", () -> AttachmentType.<net.minecraft.nbt.CompoundTag, $attachmentType>serializable(holder -> new ${capability.implementationType}((${capability.entityKind}) holder)).build());"
                    }
                    else ->
                        "public static final EntityCapability<${capability.apiType}, Direction> ${capability.fieldName} = EntityCapability.createSided(${capability.apiType}.ID, ${capability.apiType}.class);"
                }
                modified = Regex(
                    """public\s+static\s+final\s+Capability<\s*${Regex.escape(capability.apiType)}\s*>\s+${Regex.escape(capability.fieldName)}\s*=\s*CapabilityManager\.get\s*\(\s*new\s+CapabilityToken<>\s*\(\s*\)\s*\{\s*}\s*\)\s*;"""
                ).replace(modified, replacement)
            }
            if (attachmentCapabilitiesPresent && !modified.contains("DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES")) {
                val firstField = Regex("""(?m)^[ \t]*public\s+static\s+final\s+(?:Supplier<AttachmentType<[^>]+>>|EntityCapability<[^;]+>)\s+[A-Za-z_$][\w$]*\s*=""")
                    .find(modified)
                val modRef = levelCapabilities.firstOrNull()?.modIdExpression
                    ?: entityAttachmentCapabilities.firstNotNullOf { it.modIdExpression }
                val registerField = """
	public static final DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES = DeferredRegister.create(NeoForgeRegistries.ATTACHMENT_TYPES, $modRef);

""".trimStart()
                if (firstField != null) {
                    modified = modified.substring(0, firstField.range.first) + registerField + modified.substring(firstField.range.first)
                }
            }

            modified = removeAttachCapabilitiesEventMethods(modified)
            modified = if (entityCapabilities.isNotEmpty()) {
                replaceRegisterCapabilitiesMethod(modified, entityCapabilities)
            } else {
                removeRegisterCapabilitiesEventMethod(modified)
            }
            if (attachmentCapabilitiesPresent && !modified.contains("registerAttachments(IEventBus")) {
                modified = insertBeforeLastClassBrace(modified, """

	public static void registerAttachments(IEventBus modEventBus) {
		ATTACHMENT_TYPES.register(modEventBus);
	}
""".trimEnd())
            }

            listOf(
                "net.neoforged.neoforge.event.AttachCapabilitiesEvent",
                "net.neoforged.neoforge.capabilities.Capability",
                "net.neoforged.neoforge.capabilities.CapabilityManager",
                "net.neoforged.neoforge.capabilities.CapabilityToken",
                "net.neoforged.neoforge.capabilities.ICapabilitySerializable",
                "com.modporter.compat.Capability",
                "com.modporter.compat.LazyOptional",
                "$compatPackage.LazyOptional",
                "javax.annotation.Nonnull",
                "org.jetbrains.annotations.NotNull",
                "org.jetbrains.annotations.Nullable"
            ).forEach { modified = removeImport(modified, it) }
            val withoutCapabilityProviderImports = Regex("""(?m)^[ \t]*import\s+[\w.]+\.CapabilityProvider;\s*\r?\n""")
                .replace(modified, "")
            if (!Regex("""\bCapabilityProvider\b""").containsMatchIn(withoutCapabilityProviderImports)) {
                modified = withoutCapabilityProviderImports
            }
            modified = modified.replace(
                Regex("""(?m)^[ \t]*import\s+net\.neoforged\.neoforge\.capabilities\.\*;\s*\r?\n"""),
                ""
            )
            if (entityCapabilities.isNotEmpty()) {
                modified = addImportIfMissing(modified, "java.util.Collections")
                modified = addImportIfMissing(modified, "java.util.Map")
                modified = addImportIfMissing(modified, "java.util.WeakHashMap")
                modified = addImportIfMissing(modified, "net.minecraft.core.Direction")
                modified = addImportIfMissing(modified, "net.minecraft.core.registries.BuiltInRegistries")
                modified = addImportIfMissing(modified, "net.minecraft.world.entity.EntityType")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.capabilities.EntityCapability")
                for (entityKind in entityCapabilities.map { it.entityKind }.toSet()) {
                    entityKindImport(entityKind)?.let { modified = addImportIfMissing(modified, it) }
                }
            }
            if (levelCapabilities.isNotEmpty()) {
                modified = addImportIfMissing(modified, "java.util.function.Supplier")
                modified = addImportIfMissing(modified, "net.minecraft.world.level.Level")
                modified = addImportIfMissing(modified, "net.neoforged.bus.api.IEventBus")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.attachment.AttachmentType")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.registries.DeferredRegister")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.registries.NeoForgeRegistries")
            }
            if (entityCapabilities.isNotEmpty()) {
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")
            }
            if (attachmentCapabilitiesPresent) {
                modified = addImportIfMissing(modified, "java.util.function.Supplier")
                modified = addImportIfMissing(modified, "net.neoforged.bus.api.IEventBus")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.attachment.AttachmentType")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.registries.DeferredRegister")
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.registries.NeoForgeRegistries")
                for (entityKind in entityAttachmentCapabilities.map { it.entityKind }.toSet()) {
                    entityKindImport(entityKind)?.let { modified = addImportIfMissing(modified, it) }
                }
            }
            modified = removeUnusedImportsBySimpleNamePattern(
                modified,
                Regex("""Capability|CapabilityManager|CapabilityToken|CapabilityProvider|RegisterCapabilitiesEvent""")
            )
            modified = Regex("""(?m)^([ \t]*)@SubscribeEvent[ \t]*(?:\r?\n[ \t]*)+((?:public|protected|private)\s+static\s+void\s+registerAttachments\s*\()""")
                .replace(modified) { match -> match.groupValues[1] + match.groupValues[2] }
            if (!modified.contains("@SubscribeEvent")) {
                modified = Regex("""(?m)^[ \t]*@(?:Mod\.)?EventBusSubscriber\b[^\r\n]*\r?\n""").replace(modified, "")
                modified = removeImport(modified, "net.neoforged.fml.common.EventBusSubscriber")
            }
            modified = removeUnusedSimpleImports(modified, listOf("net.neoforged.bus.api.SubscribeEvent"))

            if (modified != original) {
                if (!dryRun) capabilityFile.writeText(modified)
                changes.add(Change(
                    file = capabilityFile,
                    line = 1,
                    description = "Migrate legacy custom entity capabilities to NeoForge EntityCapability registrations",
                    before = "CapabilityManager + AttachCapabilitiesEvent<Entity>",
                    after = "EntityCapability.createSided + RegisterCapabilitiesEvent",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-custom-entity-capabilities"
                ))
            }
        }

        val capabilityListNames = capabilityFiles.map { it.fileName.toString().removeSuffix(".java") }.toSet()
        for (javaFile in javaFiles) {
            var text = javaFile.readText()
            val original = text
            if (entityAttachmentNames.isNotEmpty() && capabilityListNames.any { text.contains("$it.") }) {
                text = rewriteLegacyAttachmentCapabilityQueries(text, capabilityListNames, entityAttachmentNames, compatPackage)
            }
            if (entityCapabilityNames.isNotEmpty() && capabilityListNames.any { text.contains("$it.") } && text.contains(".getCapability(")) {
                text = rewriteLegacyEntityCapabilityQueries(text, capabilityListNames, entityCapabilityNames, compatPackage)
            }
            if (levelCapabilityNames.isNotEmpty() && capabilityListNames.any { text.contains("$it.") }) {
                text = rewriteLegacyLevelCapabilityQueries(text, capabilityListNames, levelCapabilityNames, compatPackage)
            }
            if (capabilityListNames.any { text.contains("::attach") }) {
                text = text.lines()
                    .filterNot { line -> capabilityListNames.any { name -> line.contains("$name::attach") } }
                    .joinToString(System.lineSeparator())
            }
            if (text != original) {
                if (!dryRun) javaFile.writeText(text)
                changes.add(Change(
                    file = javaFile,
                    line = 1,
                    description = "Wrap NeoForge custom entity capability lookups in LazyOptional compatibility adapter",
                    before = "entity.getCapability(CapabilityList.CAP)",
                    after = "LazyOptional.ofNullable(entity.getCapability(CapabilityList.CAP, null))",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-custom-entity-capability-lookups"
                ))
            }
        }

        val mainClass = detectModMainClass(projectDir)
        val mainText = mainClass?.readText().orEmpty()
        val attachmentOwnerFiles = capabilityFiles.filter { file ->
            file.readText().contains("registerAttachments(IEventBus")
        }
        for (attachmentOwner in attachmentOwnerFiles) {
            if (mainClass == null || mainText.isBlank()) continue
            val ownerText = attachmentOwner.readText()
            val ownerPackage = packageNameOf(ownerText)
            val ownerClass = attachmentOwner.fileName.toString().removeSuffix(".java")
            val call = "$ownerClass.registerAttachments("
            if (mainClass.readText().contains(call)) continue
            var migratedMain = mainClass.readText()
            val busName = detectModBusVariable(migratedMain) ?: "modEventBus"
            val mainPackage = packageNameOf(migratedMain)
            if (ownerPackage != mainPackage) {
                migratedMain = addImportIfMissing(migratedMain, "$ownerPackage.$ownerClass")
            }
            migratedMain = insertModBusListener(
                migratedMain,
                busName,
                "        $ownerClass.registerAttachments($busName);",
                "$ownerClass.attachments"
            )
            if (migratedMain != mainClass.readText()) {
                if (!dryRun) mainClass.writeText(migratedMain)
                changes.add(Change(
                    file = mainClass,
                    line = 1,
                    description = "Register migrated level capability attachments on the mod event bus",
                    before = "AttachCapabilitiesEvent<Level>",
                    after = "$ownerClass.registerAttachments($busName)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-level-capability-attachment-main-register"
                ))
            }
        }

        return changes
    }

    private fun findCapabilityImplementations(javaFiles: List<Path>): Map<String, String> {
        val result = linkedMapOf<String, String>()
        for (file in javaFiles) {
            val text = file.readText()
            val match = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+implements\s+([A-Za-z_$][\w$]*)\b""").find(text) ?: continue
            result.putIfAbsent(match.groupValues[2], match.groupValues[1])
        }
        return result
    }

    private fun findCapabilityEntityKinds(javaFiles: List<Path>): Map<String, String> {
        val result = linkedMapOf<String, String>()
        for (file in javaFiles) {
            val text = file.readText()
            val interfaceMatch = Regex("""\binterface\s+([A-Za-z_$][\w$]*)\b""").find(text) ?: continue
            val interfaceName = interfaceMatch.groupValues[1]
            val kind = when {
                Regex("""\bsetEntity\s*\(\s*Player\b""").containsMatchIn(text) -> "Player"
                Regex("""\bsetEntity\s*\(\s*LivingEntity\b""").containsMatchIn(text) -> "LivingEntity"
                else -> continue
            }
            result[interfaceName] = kind
        }
        return result
    }

    private fun findSerializableCapabilityTypes(javaFiles: List<Path>): Set<String> {
        val result = linkedSetOf<String>()
        for (file in javaFiles) {
            val text = file.readText()
            val typeName = Regex("""\b(?:interface|class)\s+([A-Za-z_$][\w$]*)\b""")
                .find(text)
                ?.groupValues
                ?.get(1)
                ?: continue
            if (text.contains("INBTSerializable") ||
                text.contains("INBTSynchable") ||
                (text.contains("serializeNBT(") && text.contains("deserializeNBT("))) {
                result.add(typeName)
            }
        }
        return result
    }

    private data class AttachEntityCapabilitySpec(
        val fieldName: String,
        val implementationType: String,
        val entityKind: String,
        val entityVariableName: String,
        val idPath: String,
        val modIdExpression: String
    )

    private fun extractAttachEntityCapabilitySpecs(source: String): Map<String, AttachEntityCapabilitySpec> {
        if (!source.contains("AttachCapabilitiesEvent<Entity>") || !source.contains("event.addCapability(")) {
            return emptyMap()
        }
        val specs = linkedMapOf<String, AttachEntityCapabilitySpec>()
        val instancePattern = Regex("""(?:event\.getObject\(\)|[A-Za-z_$][\w$]*)\s+instanceof\s+([A-Za-z_$][\w$]*)\s+([A-Za-z_$][\w$]*)""")
        var cursor = 0
        while (true) {
            val match = instancePattern.find(source, cursor) ?: break
            val entityKind = match.groupValues[1]
            val entityVariable = match.groupValues[2]
            val closeParen = source.indexOf(')', match.range.last)
            val openBrace = if (closeParen >= 0) source.indexOf('{', closeParen) else -1
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = source.substring(openBrace + 1, closeBrace)
            val providerPattern = Regex(
                """event\.addCapability\s*\(\s*ResourceLocation\.fromNamespaceAndPath\s*\(\s*([^,]+?)\s*,\s*"([^"]+)"\s*\)\s*,\s*new\s+CapabilityProvider\s*\(\s*(?:[A-Za-z_$][\w$]*\.)?([A-Z_$][A-Z0-9_$]*)\s*,\s*new\s+([A-Za-z_$][\w$]*)\s*\(\s*${Regex.escape(entityVariable)}\s*\)\s*\)""",
                RegexOption.DOT_MATCHES_ALL
            )
            providerPattern.findAll(body).forEach { provider ->
                val fieldName = provider.groupValues[3]
                specs[fieldName] = AttachEntityCapabilitySpec(
                    fieldName = fieldName,
                    implementationType = provider.groupValues[4],
                    entityKind = entityKind,
                    entityVariableName = entityVariable,
                    idPath = provider.groupValues[2],
                    modIdExpression = provider.groupValues[1].trim()
                )
            }
            cursor = match.range.last + 1
        }
        return specs
    }

    private fun extractAttachLevelCapabilitySpecs(
        source: String,
        implementationByInterface: Map<String, String>
    ): List<LegacyLevelCapability> {
        if (!source.contains("AttachCapabilitiesEvent<Level>") || !source.contains("event.addCapability(")) {
            return emptyList()
        }
        val apiTypeByField = Regex(
            """public\s+static\s+final\s+Capability<\s*([A-Za-z_$][\w$]*)\s*>\s+([A-Z_$][A-Z0-9_$]*)\s*="""
        ).findAll(source).associate { it.groupValues[2] to it.groupValues[1] }
        val specs = mutableListOf<LegacyLevelCapability>()
        val pattern = Regex(
            """event\.addCapability\s*\(\s*ResourceLocation\.fromNamespaceAndPath\s*\(\s*([^,]+?)\s*,\s*"([^"]+)"\s*\)\s*,\s*new\s+CapabilityProvider\s*\(\s*(?:[A-Za-z_$][\w$]*\.)?([A-Z_$][A-Z0-9_$]*)\s*,\s*new\s+([A-Za-z_$][\w$]*)\s*\(\s*event\.getObject\(\)\s*\)\s*\)\s*\)""",
            RegexOption.DOT_MATCHES_ALL
        )
        pattern.findAll(source).forEach { match ->
            val fieldName = match.groupValues[3]
            val apiType = apiTypeByField[fieldName] ?: return@forEach
            val implementationType = match.groupValues[4].ifBlank { implementationByInterface[apiType] ?: return@forEach }
            specs.add(LegacyLevelCapability(
                fieldName = fieldName,
                apiType = apiType,
                implementationType = implementationType,
                idPath = match.groupValues[2],
                modIdExpression = match.groupValues[1].trim()
            ))
        }
        return specs
    }

    private fun removeAttachCapabilitiesEventMethods(source: String): String {
        var result = source
        val methodNames = Regex("""\b([A-Za-z_$][\w$]*)\s*\(\s*AttachCapabilitiesEvent<[^>]+>\s+[A-Za-z_$][\w$]*\s*\)""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        for (methodName in methodNames) {
            result = removeMethodByName(result, methodName)
        }
        return result
    }

    private fun removeRegisterCapabilitiesEventMethod(source: String): String {
        val methodMatch = Regex(
            """(?:public|protected|private)\s+static\s+void\s+[A-Za-z_$][\w$]*\s*\(\s*RegisterCapabilitiesEvent\s+[A-Za-z_$][\w$]*\s*\)"""
        ).find(source) ?: return source
        val start = source.lastIndexOf('\n', methodMatch.range.first).let { if (it < 0) 0 else it + 1 }
        val openBrace = source.indexOf('{', methodMatch.range.first)
        if (openBrace < 0) return source
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace <= openBrace) return source
        var end = closeBrace + 1
        if (end < source.length && source[end] == '\r') end++
        if (end < source.length && source[end] == '\n') end++
        return source.removeRange(start, end)
    }

    private fun entityKindImport(entityKind: String): String? = when (entityKind) {
        "Entity" -> "net.minecraft.world.entity.Entity"
        "LivingEntity" -> "net.minecraft.world.entity.LivingEntity"
        "Mob" -> "net.minecraft.world.entity.Mob"
        "Player" -> "net.minecraft.world.entity.player.Player"
        "ItemEntity" -> "net.minecraft.world.entity.item.ItemEntity"
        "LightningBolt" -> "net.minecraft.world.entity.LightningBolt"
        "AbstractArrow" -> "net.minecraft.world.entity.projectile.AbstractArrow"
        else -> null
    }

    private fun replaceRegisterCapabilitiesMethod(source: String, capabilities: List<LegacyEntityCapability>): String {
        val methodMatch = Regex(
            """(?:public|protected|private)\s+static\s+void\s+[A-Za-z_$][\w$]*\s*\(\s*RegisterCapabilitiesEvent\s+[A-Za-z_$][\w$]*\s*\)"""
        ).find(source) ?: return source
        val nameIndex = methodMatch.range.first
        val openBrace = source.indexOf('{', nameIndex)
        if (openBrace < 0) return source
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace <= openBrace) return source

        val methodSource = renderEntityCapabilityRegisterMethod(capabilities)
        return source.substring(0, source.lastIndexOf('\n', nameIndex).let { if (it < 0) 0 else it + 1 }) +
            methodSource +
            source.substring(closeBrace + 1)
    }

    private fun renderEntityCapabilityRegisterMethod(capabilities: List<LegacyEntityCapability>): String {
        val caches = capabilities.joinToString(System.lineSeparator()) { capability ->
            "    private static final Map<Entity, ${capability.apiType}> ${capability.fieldName}_CACHE = Collections.synchronizedMap(new WeakHashMap<>());"
        }
        val registrations = capabilities.joinToString(System.lineSeparator()) { capability ->
            "            event.registerEntity(${capability.fieldName}, (EntityType) entityType, (entity, side) -> getOrCreate${capability.fieldName}(entity));"
        }
        val helpers = capabilities.joinToString(System.lineSeparator() + System.lineSeparator()) { capability ->
            val implementation = capability.implementationType ?: capability.apiType
            val entityVariable = capability.entityVariableName
            val guard = when (capability.entityKind) {
                "Entity" -> ""
                else -> "if (!(entity instanceof ${capability.entityKind} $entityVariable)) return null;"
            }
            val constructor = if (capability.constructorArgFromEntity) {
                "new $implementation($entityVariable)"
            } else {
                "new $implementation()"
            }
            val setEntityArg = when {
                capability.constructorArgFromEntity -> null
                capability.entityKind == "Entity" -> "entity"
                else -> entityVariable
            }
            val setEntity = if (capability.setsEntity && setEntityArg != null) {
                "            capability.setEntity($setEntityArg);${System.lineSeparator()}"
            } else {
                ""
            }
            val guardLine = if (guard.isBlank()) {
                ""
            } else {
                "        $guard${System.lineSeparator()}"
            }
            """
    private static ${capability.apiType} getOrCreate${capability.fieldName}(Entity entity) {
$guardLine        return ${capability.fieldName}_CACHE.computeIfAbsent(entity, key -> {
            $implementation capability = $constructor;
$setEntity            return capability;
        });
    }
""".trimEnd()
        }
        return """
$caches

    @SuppressWarnings({"unchecked", "rawtypes"})
    public static void registerCapabilities(RegisterCapabilitiesEvent event) {
        for (EntityType<?> entityType : BuiltInRegistries.ENTITY_TYPE) {
$registrations
        }
    }

$helpers
""".trimEnd()
    }

    private fun rewriteLegacyLevelCapabilityQueries(
        source: String,
        capabilityListNames: Set<String>,
        levelCapabilityNames: Set<String>,
        compatPackage: String
    ): String {
        var result = source
        val ownerAlternation = capabilityListNames.joinToString("|") { Regex.escape(it) }
        val fieldAlternation = levelCapabilityNames.joinToString("|") { Regex.escape(it) }
        if (ownerAlternation.isBlank() || fieldAlternation.isBlank()) return source
        val alreadyWrappedPattern = Regex(
            """((?:[A-Za-z_$][\w$]*\.)*LazyOptional\.ofNullable\(\s*)((?<![A-Za-z0-9_$])[A-Za-z_$][\w$]*(?:(?:\.[A-Za-z_$][\w$]*)|(?:\.[A-Za-z_$][\w$]*\(\)))*)\.getCapability\(\s*(($ownerAlternation)\.($fieldAlternation))\s*(?:,\s*null\s*)?\)(\s*\))"""
        )
        result = alreadyWrappedPattern.replace(result) { match ->
            "${match.groupValues[1]}${match.groupValues[2]}.getData(${match.groupValues[3]}.get())${match.groupValues[6]}"
        }
        val directPattern = Regex(
            """(?<![A-Za-z0-9_$])([A-Za-z_$][\w$]*(?:(?:\.[A-Za-z_$][\w$]*)|(?:\.[A-Za-z_$][\w$]*\(\)))*)\.getCapability\(\s*(($ownerAlternation)\.($fieldAlternation))\s*(?:,\s*null\s*)?\)"""
        )
        result = directPattern.replace(result) { match ->
            "${match.groupValues[1]}.getData(${match.groupValues[2]}.get())"
        }
        return result
    }

    private fun rewriteLegacyEntityCapabilityQueries(
        source: String,
        capabilityListNames: Set<String>,
        entityCapabilityNames: Set<String>,
        compatPackage: String
    ): String {
        var result = source
        val listAlternation = capabilityListNames.joinToString("|") { Regex.escape(it) }
        val fieldAlternation = entityCapabilityNames.joinToString("|") { Regex.escape(it) }
        if (listAlternation.isBlank() || fieldAlternation.isBlank()) return source
        val wrappedPattern = Regex(
            """((?:[A-Za-z_$][\w$]*\.)*LazyOptional\.ofNullable\(\s*)([A-Za-z_$][\w$]*(?:(?:\.[A-Za-z_$][\w$]*)|(?:\.[A-Za-z_$][\w$]*\(\)))*)\.getCapability\(\s*(($listAlternation)\.($fieldAlternation))\s*\)(\s*\))"""
        )
        result = wrappedPattern.replace(result) { match ->
            "${match.groupValues[1]}${match.groupValues[2]}.getCapability(${match.groupValues[3]}, null)${match.groupValues[6]}"
        }
        val queryPattern = Regex(
            """(?<!ofNullable\()(?<![A-Za-z0-9_$])([A-Za-z_$][\w$]*(?:(?:\.[A-Za-z_$][\w$]*)|(?:\.[A-Za-z_$][\w$]*\(\)))*)\.getCapability\(\s*(($listAlternation)\.($fieldAlternation))\s*\)"""
        )
        result = queryPattern.replace(result) { match ->
            val receiver = match.groupValues[1]
            val capability = match.groupValues[2]
            "$compatPackage.LazyOptional.ofNullable($receiver.getCapability($capability, null))"
        }
        return result
    }

    private fun rewriteLegacyAttachmentCapabilityQueries(
        source: String,
        capabilityListNames: Set<String>,
        attachmentCapabilityNames: Set<String>,
        compatPackage: String
    ): String {
        var result = source
        val ownerAlternation = capabilityListNames.joinToString("|") { Regex.escape(it) }
        val fieldAlternation = attachmentCapabilityNames.joinToString("|") { Regex.escape(it) }
        if (ownerAlternation.isBlank() || fieldAlternation.isBlank()) return source
        val alreadyWrappedPattern = Regex(
            """((?:[A-Za-z_$][\w$]*\.)*LazyOptional\.ofNullable\(\s*)([A-Za-z_$][\w$]*(?:(?:\.[A-Za-z_$][\w$]*)|(?:\.[A-Za-z_$][\w$]*\(\)))*)\.getCapability\(\s*(($ownerAlternation)\.($fieldAlternation))\s*(?:,\s*null\s*)?\)(\s*\))"""
        )
        result = alreadyWrappedPattern.replace(result) { match ->
            "${match.groupValues[1]}${match.groupValues[2]}.getData(${match.groupValues[3]}.get())${match.groupValues[6]}"
        }
        val directPattern = Regex(
            """(?<![A-Za-z0-9_$])([A-Za-z_$][\w$]*(?:(?:\.[A-Za-z_$][\w$]*)|(?:\.[A-Za-z_$][\w$]*\(\)))*)\.getCapability\(\s*(($ownerAlternation)\.($fieldAlternation))\s*(?:,\s*null\s*)?\)"""
        )
        result = directPattern.replace(result) { match ->
            "$compatPackage.LazyOptional.ofNullable(${match.groupValues[1]}.getData(${match.groupValues[2]}.get()))"
        }
        return result
    }

    private fun migrateNitrogenAttachmentApi(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        val changes = mutableListOf<Change>()

        val entitySyncPackets = javaFiles.mapNotNull { javaFile ->
            val text = javaFile.readText()
            Regex("""\b(?:class|record)\s+([A-Za-z_$][\w$]*)[\s\S]*?\bextends\s+SyncEntityPacket\s*<""")
                .find(text)
                ?.groupValues
                ?.get(1)
        }.toSet()
        val syncOwnerAccessors = collectNitrogenSyncOwnerAccessors(javaFiles)

        for (javaFile in javaFiles) {
            val original = javaFile.readText()
            if (!original.contains("com.aetherteam.nitrogen.capability.INBTSynchable") &&
                !original.contains("getSyncPacket(") &&
                !original.contains("setSynched(") &&
                !original.contains("forceSync(")) {
                continue
            }

            var modified = original
            modified = modified.replace(
                "com.aetherteam.nitrogen.capability.INBTSynchable",
                "com.aetherteam.nitrogen.attachment.INBTSynchable"
            )
            if (modified.contains("getSyncPacket(")) {
                modified = modified.replace(
                    "import com.aetherteam.nitrogen.network.BasePacket;",
                    "import com.aetherteam.nitrogen.network.packet.SyncPacket;"
                )
                modified = modified.replace(
                    "com.aetherteam.nitrogen.network.BasePacket",
                    "com.aetherteam.nitrogen.network.packet.SyncPacket"
                )
                if (modified.contains("SyncPacket")) {
                    modified = Regex("""\bBasePacket\b""").replace(modified, "SyncPacket")
                }
            }

            val synchableGeneric = Regex("""\bINBTSynchable\s*<\s*([^>]+)\s*>""")
            if (synchableGeneric.containsMatchIn(modified)) {
                modified = synchableGeneric.replace(modified) { match ->
                    "INBTSynchable, INBTSerializable<${match.groupValues[1].trim()}>"
                }
                modified = addImportIfMissing(modified, "net.neoforged.neoforge.common.util.INBTSerializable")
            }

            if (modified.contains("extends SyncEntityPacket<") || modified.contains("extends SyncLevelPacket<")) {
                modified = modified.replace(
                    "import net.minecraft.network.FriendlyByteBuf;",
                    "import net.minecraft.network.RegistryFriendlyByteBuf;"
                )
                modified = Regex("""\bFriendlyByteBuf\s+([A-Za-z_$][\w$]*)""")
                    .replace(modified, "RegistryFriendlyByteBuf $1")
            }

            modified = rewriteNitrogenGetSyncPacketSignature(modified, entitySyncPackets)
            val ownerEntityId = inferNitrogenOwnerEntityId(modified)
            val receiverOwnerEntityIds = inferNitrogenReceiverOwnerEntityIds(modified, syncOwnerAccessors)
            modified = rewriteNitrogenSyncCalls(modified, "setSynched", ownerEntityId, receiverOwnerEntityIds)
            modified = rewriteNitrogenSyncCalls(modified, "forceSync", ownerEntityId, receiverOwnerEntityIds)

            if (modified.contains("getPacketChannel(")) {
                modified = removeMethodByName(modified, "getPacketChannel")
            }

            modified = removeUnusedSimpleImports(modified, listOf(
                "net.minecraftforge.network.simple.SimpleChannel",
                "net.neoforged.neoforge.network.simple.SimpleChannel"
            ))
            modified = removeUnusedImportsBySimpleNamePattern(modified, Regex("""[A-Za-z_$][\w$]*PacketHandler"""))

            if (modified != original) {
                if (!dryRun) javaFile.writeText(modified)
                changes.add(Change(
                    file = javaFile,
                    line = 1,
                    description = "Migrate Nitrogen sync capability API to attachment INBTSynchable surface",
                    before = "com.aetherteam.nitrogen.capability.INBTSynchable/BasePacket",
                    after = "com.aetherteam.nitrogen.attachment.INBTSynchable/SyncPacket",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-nitrogen-attachment-api"
                ))
            }
        }

        return changes
    }

    private fun collectNitrogenSyncOwnerAccessors(javaFiles: List<Path>): Map<String, String> {
        val entityTypes = "(?:Player|ServerPlayer|Entity|LivingEntity|Mob|AbstractArrow|Projectile)"
        return javaFiles.mapNotNull { javaFile ->
            val text = javaFile.readText()
            if (!text.contains("INBTSynchable")) return@mapNotNull null
            val typeName = Regex("""\b(?:class|interface)\s+([A-Za-z_$][\w$]*)\b""")
                .find(text)
                ?.groupValues
                ?.get(1)
                ?: return@mapNotNull null
            val accessors = Regex("""\b(?:public\s+)?$entityTypes\s+(get[A-Za-z_$][\w$]*)\s*\(\s*\)\s*(?:;|\{)""")
                .findAll(text)
                .map { it.groupValues[1] }
                .distinct()
                .toList()
            if (accessors.size == 1) typeName to accessors.single() else null
        }.toMap()
    }

    private fun rewriteNitrogenGetSyncPacketSignature(source: String, entitySyncPackets: Set<String>): String {
        var result = Regex(
            """(public\s+SyncPacket\s+getSyncPacket\s*\()\s*String\s+key\s*,\s*Type\s+type\s*,\s*Object\s+value\s*\)"""
        ).replace(source) { match ->
            "${match.groupValues[1]}int entityID, String key, Type type, Object value)"
        }
        for (packetName in entitySyncPackets) {
            result = Regex("""new\s+${Regex.escape(packetName)}\s*\(\s*key\s*,\s*type\s*,\s*value\s*\)""")
                .replace(result, "new $packetName(entityID, key, type, value)")
        }
        return result
    }

    private fun inferNitrogenOwnerEntityId(source: String): String? {
        val entityTypes = "(?:Player|ServerPlayer|Entity|LivingEntity|Mob|ItemEntity|LightningBolt|AbstractArrow|Projectile)"
        val accessors = Regex("""\bpublic\s+$entityTypes\s+(get[A-Za-z_$][\w$]*)\s*\(\s*\)""")
            .findAll(source)
            .map { it.groupValues[1] }
            .distinct()
            .toList()
        if (accessors.size == 1) {
            return "this.${accessors.single()}().getId()"
        }
        val fields = Regex("""\bprivate\s+(?:final\s+)?$entityTypes\s+([A-Za-z_$][\w$]*)\s*;""")
            .findAll(source)
            .map { it.groupValues[1] }
            .distinct()
            .toList()
        if (fields.size == 1) {
            return "this.${fields.single()}.getId()"
        }
        return null
    }

    private fun inferNitrogenReceiverOwnerEntityIds(source: String, ownerAccessors: Map<String, String>): Map<String, String> {
        if (ownerAccessors.isEmpty()) return emptyMap()
        val typeAlternation = ownerAccessors.keys.joinToString("|") { Regex.escape(it) }
        val receiverTypes = mutableMapOf<String, MutableSet<String>>()
        fun record(receiver: String, typeName: String) {
            receiverTypes.getOrPut(receiver) { mutableSetOf() }.add(typeName)
        }
        Regex("""\b($typeAlternation)\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .forEach { match -> record(match.groupValues[2], match.groupValues[1]) }
        Regex("""\b($typeAlternation)\.get\s*\([^)]*\)\s*(?:\.resolve\s*\(\s*\))?\s*\.ifPresent\s*\(\s*\(?\s*([A-Za-z_$][\w$]*)""")
            .findAll(source)
            .forEach { match -> record(match.groupValues[2], match.groupValues[1]) }
        return receiverTypes.mapNotNull { (receiver, types) ->
            val typeName = types.singleOrNull() ?: return@mapNotNull null
            val accessor = ownerAccessors[typeName] ?: return@mapNotNull null
            receiver to "$receiver.$accessor().getId()"
        }.toMap()
    }

    private fun rewriteNitrogenSyncCalls(
        source: String,
        methodName: String,
        ownerEntityId: String?,
        receiverOwnerEntityIds: Map<String, String>
    ): String {
        var result = source
        var cursor = 0
        val pattern = Regex("""(?:(this|[A-Za-z_$][\w$]*)\.)?${Regex.escape(methodName)}\s*\(""")
        while (true) {
            val match = pattern.find(result, cursor) ?: break
            val lineStart = result.lastIndexOf('\n', match.range.first).let { if (it < 0) 0 else it + 1 }
            val linePrefix = result.substring(lineStart, match.range.first)
            if (Regex("""\b(?:public|protected|private|abstract|default)\b""").containsMatchIn(linePrefix)) {
                cursor = match.range.last + 1
                continue
            }
            val openParen = result.indexOf('(', match.range.first)
            val closeParen = if (openParen >= 0) findMatchingParen(result, openParen) else -1
            if (openParen < 0 || closeParen <= openParen) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen)).toMutableList()
            if (args.isEmpty() || !args[0].contains("Direction.")) {
                cursor = closeParen + 1
                continue
            }
            val receiverName = match.groupValues.getOrNull(1).orEmpty()
            val receiverEntityId = if (receiverName.isNotBlank() && receiverName != "this") {
                receiverOwnerEntityIds[receiverName]
            } else {
                null
            }
            val idExpression = nitrogenSyncIdExpression(args, ownerEntityId, receiverEntityId)
            if (idExpression == null) {
                cursor = closeParen + 1
                continue
            }
            if (args[0].contains("Direction.DIMENSION") && args.isNotEmpty()) {
                val lastIndex = args.lastIndex
                args[lastIndex] = stripDimensionAccessor(args[lastIndex])
            }
            val replacementArgs = (listOf(idExpression) + args).joinToString(", ")
            result = result.substring(0, openParen + 1) + replacementArgs + result.substring(closeParen)
            cursor = openParen + replacementArgs.length + 2
        }
        return result
    }

    private fun nitrogenSyncIdExpression(args: List<String>, ownerEntityId: String?, receiverEntityId: String?): String? {
        val direction = args.firstOrNull() ?: return null
        return when {
            direction.contains("Direction.DIMENSION") -> "-1"
            direction.contains("Direction.PLAYER") && args.size >= 2 -> {
                val target = args.last().trim()
                if (target.isBlank()) null else "${stripDimensionAccessor(target)}.getId()"
            }
            else -> receiverEntityId ?: ownerEntityId
        }
    }

    private fun stripDimensionAccessor(expression: String): String =
        expression.trim().removeSuffix(".dimension()")

    private fun detectGeneratedCompatPackage(projectDir: Path): String {
        val modId = detectModId(projectDir) ?: projectDir.fileName.toString()
        val sanitized = modId.lowercase()
            .replace(Regex("""[^a-z0-9_]"""), "_")
            .trim('_')
            .ifBlank { "mod" }
            .let { if (it.first().isDigit()) "m$it" else it }
        return "com.modporter.generated.$sanitized.compat"
    }

    private fun migrateLegacyPackResourceApis(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()

        val compatPackage = detectGeneratedCompatPackage(projectDir)
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .filter { !it.toString().replace('\\', '/').contains("/src/main/java/${compatPackage.replace('.', '/')}/") }
            .toList()
        val changes = mutableListOf<Change>()
        var needsPathPackResources = false
        var needsDelegatingPackResources = false
        var needsLegacyResourcesSupplier = false

        for (javaFile in javaFiles) {
            val original = javaFile.readText()
            var modified = original
            val hadPathPackResources =
                modified.contains("net.neoforged.neoforge.resource.PathPackResources") ||
                    modified.contains("net.minecraftforge.resource.PathPackResources")
            val hadDelegatingPackResources =
                modified.contains("net.neoforged.neoforge.resource.DelegatingPackResources") ||
                    modified.contains("net.minecraftforge.resource.DelegatingPackResources")

            if (hadPathPackResources) {
                modified = modified
                    .replace("import net.neoforged.neoforge.resource.PathPackResources;", "import $compatPackage.PathPackResources;")
                    .replace("import net.minecraftforge.resource.PathPackResources;", "import $compatPackage.PathPackResources;")
                    .replace("net.neoforged.neoforge.resource.PathPackResources", "$compatPackage.PathPackResources")
                    .replace("net.minecraftforge.resource.PathPackResources", "$compatPackage.PathPackResources")
                needsPathPackResources = true
            }
            if (hadDelegatingPackResources) {
                modified = modified
                    .replace("import net.neoforged.neoforge.resource.DelegatingPackResources;", "import $compatPackage.DelegatingPackResources;")
                    .replace("import net.minecraftforge.resource.DelegatingPackResources;", "import $compatPackage.DelegatingPackResources;")
                    .replace("net.neoforged.neoforge.resource.DelegatingPackResources", "$compatPackage.DelegatingPackResources")
                    .replace("net.minecraftforge.resource.DelegatingPackResources", "$compatPackage.DelegatingPackResources")
                needsDelegatingPackResources = true
            }

            val accessorMigrated = migratePackMetadataSectionAccessors(modified)
            modified = accessorMigrated

            val createRewrite = rewriteLegacyPackCreateCalls(modified, compatPackage)
            modified = createRewrite.first
            needsLegacyResourcesSupplier = needsLegacyResourcesSupplier || createRewrite.second

            val supplierRewrite = rewriteLegacyPackResourcesSupplierAssignments(modified, compatPackage)
            modified = supplierRewrite.first
            needsLegacyResourcesSupplier = needsLegacyResourcesSupplier || supplierRewrite.second

            val readInfoRewrite = rewriteLegacyPackReadInfoCalls(modified)
            modified = readInfoRewrite

            if (modified.contains("Pack.Info")) {
                modified = Regex("""\bPack\.Info\b(?!\s*\()""").replace(modified, "Pack.Metadata")
            }

            modified = addLegacyPackApiImports(modified)

            if (modified != original) {
                if (!dryRun) javaFile.writeText(modified)
                changes.add(Change(
                    file = javaFile,
                    line = 1,
                    description = "Migrate legacy built-in pack resource APIs to Minecraft 1.21 PackLocationInfo/ResourcesSupplier contracts",
                    before = "PathPackResources/DelegatingPackResources/Pack.create/Pack.Info legacy shape",
                    after = "PackLocationInfo + PackSelectionConfig + generated PackResources adapters",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-legacy-pack-resources"
                ))
            }
        }

        if (needsPathPackResources) {
            changes.addAll(ensureGeneratedPackResourceCompat(
                srcDir,
                compatPackage,
                "PathPackResources.java",
                generatedPathPackResourcesSource(compatPackage),
                "Generate source-compatible PathPackResources adapter",
                "struct-generate-path-pack-resources",
                dryRun
            ))
        }
        if (needsDelegatingPackResources) {
            changes.addAll(ensureGeneratedPackResourceCompat(
                srcDir,
                compatPackage,
                "DelegatingPackResources.java",
                generatedDelegatingPackResourcesSource(compatPackage),
                "Generate source-compatible DelegatingPackResources adapter",
                "struct-generate-delegating-pack-resources",
                dryRun
            ))
        }
        if (needsLegacyResourcesSupplier) {
            changes.addAll(ensureGeneratedPackResourceCompat(
                srcDir,
                compatPackage,
                "LegacyPackResourcesSupplier.java",
                generatedLegacyPackResourcesSupplierSource(compatPackage),
                "Generate adapter for legacy single-method Pack.ResourcesSupplier lambdas",
                "struct-generate-legacy-pack-resources-supplier",
                dryRun
            ))
        }

        return changes
    }

    private fun addLegacyPackApiImports(source: String): String {
        var result = source
        if (result.contains("new PackLocationInfo(") || result.contains("Pack.readPackMetadata(")) {
            result = addImportIfMissing(result, "net.minecraft.server.packs.PackLocationInfo")
        }
        if (result.contains("new PackSelectionConfig(")) {
            result = addImportIfMissing(result, "net.minecraft.server.packs.PackSelectionConfig")
        }
        if (result.contains("PackCompatibility.forVersion(")) {
            result = addImportIfMissing(result, "net.minecraft.server.packs.repository.PackCompatibility")
            result = addImportIfMissing(result, "net.minecraft.util.InclusiveRange")
            result = addImportIfMissing(result, "net.minecraft.SharedConstants")
        }
        if (result.contains("Pack.readPackMetadata(")) {
            result = addImportIfMissing(result, "net.minecraft.SharedConstants")
            result = addImportIfMissing(result, "net.minecraft.network.chat.Component")
            result = addImportIfMissing(result, "net.minecraft.server.packs.PackType")
            result = addImportIfMissing(result, "net.minecraft.server.packs.repository.PackSource")
        }
        return result
    }

    private fun migratePackMetadataSectionAccessors(source: String): String {
        if (!source.contains("PackMetadataSection")) return source
        val metadataNames = Regex("""\bPackMetadataSection\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (metadataNames.isEmpty()) return source
        var result = source
        for (name in metadataNames) {
            result = result.replace("$name.getDescription()", "$name.description()")
            result = Regex("""\b${Regex.escape(name)}\.getPackFormat\s*\(\s*PackType\.[A-Z_]+\s*\)""")
                .replace(result, "$name.packFormat()")
        }
        return result
    }

    private fun rewriteLegacyPackResourcesSupplierAssignments(source: String, compatPackage: String): Pair<String, Boolean> {
        var usedAdapter = false
        val pattern = Regex(
            """(Pack\.ResourcesSupplier\s+[A-Za-z_$][\w$]*\s*=\s*)((?:\([^;\n{}]*\)|[A-Za-z_$][\w$]*)\s*->\s*[^;]+);"""
        )
        val rewritten = pattern.replace(source) { match ->
            val rhs = match.groupValues[2].trim()
            if (rhs.contains("LegacyPackResourcesSupplier")) return@replace match.value
            usedAdapter = true
            "${match.groupValues[1]}new $compatPackage.LegacyPackResourcesSupplier($rhs);"
        }
        return rewritten to usedAdapter
    }

    private fun rewriteLegacyPackReadInfoCalls(source: String): String {
        var result = source
        var cursor = 0
        val token = "Pack.readPackInfo("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + token.length - 1
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != 2) {
                cursor = closeParen + 1
                continue
            }
            val id = args[0].trim()
            val resources = args[1].trim()
            val replacement =
                "Pack.readPackMetadata(new PackLocationInfo($id, Component.literal(String.valueOf($id)), PackSource.BUILT_IN, java.util.Optional.empty()), $resources, SharedConstants.getCurrentVersion().getPackVersion(PackType.CLIENT_RESOURCES))"
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            cursor = tokenIndex + replacement.length
        }
        return result
    }

    private fun rewriteLegacyPackCreateCalls(source: String, compatPackage: String): Pair<String, Boolean> {
        var result = source
        var usedSupplierAdapter = false
        var cursor = 0
        val token = "Pack.create("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + token.length - 1
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != 9) {
                cursor = closeParen + 1
                continue
            }
            val supplier = wrapLegacyPackResourcesSupplier(args[3], compatPackage)
            usedSupplierAdapter = usedSupplierAdapter || supplier != args[3].trim()
            val metadata = rewriteLegacyPackInfoExpression(args[4], args[5])
            val location = "new PackLocationInfo(${args[0]}, ${args[1]}, ${args[8]}, java.util.Optional.empty())"
            val selection = "new PackSelectionConfig(${args[2]}, ${args[6]}, ${args[7]})"
            val replacement = "new Pack($location, $supplier, $metadata, $selection)"
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            cursor = tokenIndex + replacement.length
        }
        return result to usedSupplierAdapter
    }

    private fun wrapLegacyPackResourcesSupplier(expression: String, compatPackage: String): String {
        val trimmed = expression.trim()
        if (!trimmed.contains("->") || trimmed.contains("LegacyPackResourcesSupplier")) return trimmed
        return "new $compatPackage.LegacyPackResourcesSupplier($trimmed)"
    }

    private fun rewriteLegacyPackInfoExpression(expression: String, packTypeExpression: String): String {
        val trimmed = expression.trim()
        val args = parseNewPackInfoArgs(trimmed) ?: return trimmed
        if (args.size < 5) return trimmed
        val packType = packTypeExpression.trim()
        val selectedFormat = "($packType == PackType.SERVER_DATA ? ${args[1]} : ${args[2]})"
        val compatibility =
            "PackCompatibility.forVersion(new InclusiveRange<>($selectedFormat), SharedConstants.getCurrentVersion().getPackVersion($packType))"
        return "new Pack.Metadata(${args[0]}, $compatibility, ${args[3]}, java.util.List.of(), ${args[4]})"
    }

    private fun parseNewPackInfoArgs(expression: String): List<String>? {
        val prefixes = listOf("new Pack.Info(", "new Pack.Metadata(")
        val prefix = prefixes.firstOrNull { expression.startsWith(it) } ?: return null
        val openParen = prefix.length - 1
        val closeParen = findMatchingParen(expression, openParen)
        if (closeParen != expression.length - 1) return null
        return splitTopLevelJavaArgs(expression.substring(openParen + 1, closeParen))
    }

    private fun ensureGeneratedPackResourceCompat(
        srcDir: Path,
        compatPackage: String,
        fileName: String,
        source: String,
        description: String,
        ruleId: String,
        dryRun: Boolean
    ): List<Change> {
        val compatFile = srcDir.resolve(compatPackage.replace('.', '/')).resolve(fileName)
        if (compatFile.exists() && compatFile.readText() == source) return emptyList()
        if (!dryRun) {
            compatFile.parent.createDirectories()
            compatFile.writeText(source)
        }
        return listOf(Change(
            file = compatFile,
            line = 1,
            description = description,
            before = "(missing generated pack resource adapter)",
            after = compatPackage,
            confidence = Confidence.HIGH,
            ruleId = ruleId
        ))
    }

    private fun generatedPathPackResourcesSource(packageName: String): String = """
package $packageName;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.minecraft.network.chat.Component;
import net.minecraft.server.packs.CompositePackResources;
import net.minecraft.server.packs.PackLocationInfo;
import net.minecraft.server.packs.PackResources;
import net.minecraft.server.packs.PackType;
import net.minecraft.server.packs.repository.Pack;
import net.minecraft.server.packs.repository.PackSource;

/**
 * Source-compatible adapter generated by modporter for the removed legacy
 * PathPackResources constructors.
 */
public class PathPackResources extends net.minecraft.server.packs.PathPackResources {
    private final boolean hidden;
    private final Path root;

    public PathPackResources(String id, boolean hidden, Path root) {
        this(new PackLocationInfo(id, Component.literal(id), PackSource.BUILT_IN, Optional.empty()), hidden, root);
    }

    public PathPackResources(PackLocationInfo location, Path root) {
        this(location, false, root);
    }

    public PathPackResources(PackLocationInfo location, boolean hidden, Path root) {
        super(location, root);
        this.hidden = hidden;
        this.root = root;
    }

    @Override
    public boolean isHidden() {
        return this.hidden;
    }

    public Path root() {
        return this.root;
    }

    public static class PathResourcesSupplier implements Pack.ResourcesSupplier {
        private final Path content;
        private final boolean hidden;

        public PathResourcesSupplier(Path content) {
            this(content, false);
        }

        public PathResourcesSupplier(Path content, boolean hidden) {
            this.content = content;
            this.hidden = hidden;
        }

        @Override
        public PackResources openPrimary(PackLocationInfo location) {
            return new PathPackResources(location, this.hidden, this.content);
        }

        @Override
        public PackResources openFull(PackLocationInfo location, Pack.Metadata metadata) {
            PackResources primary = this.openPrimary(location);
            List<String> overlays = metadata.overlays();
            if (overlays.isEmpty()) {
                return primary;
            }
            List<PackResources> overlayPacks = new ArrayList<>(overlays.size());
            for (String overlay : overlays) {
                overlayPacks.add(new PathPackResources(location, this.hidden, this.content.resolve(overlay)));
            }
            return new CompositePackResources(primary, overlayPacks);
        }
    }
}
""".trimStart()

    private fun generatedLegacyPackResourcesSupplierSource(packageName: String): String = """
package $packageName;

import java.util.Objects;
import java.util.function.Function;
import net.minecraft.server.packs.PackLocationInfo;
import net.minecraft.server.packs.PackResources;
import net.minecraft.server.packs.repository.Pack;

/**
 * Adapter generated by modporter for old single-method Pack.ResourcesSupplier
 * lambdas. It preserves the old supplier contract and exposes it through the
 * Minecraft 1.21 openPrimary/openFull interface.
 */
public record LegacyPackResourcesSupplier(Function<String, ? extends PackResources> factory) implements Pack.ResourcesSupplier {
    public LegacyPackResourcesSupplier {
        Objects.requireNonNull(factory, "factory");
    }

    @Override
    public PackResources openPrimary(PackLocationInfo location) {
        return this.factory.apply(location.id());
    }

    @Override
    public PackResources openFull(PackLocationInfo location, Pack.Metadata metadata) {
        return this.openPrimary(location);
    }
}
""".trimStart()

    private fun generatedDelegatingPackResourcesSource(packageName: String): String = """
package $packageName;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import javax.annotation.Nullable;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.AbstractPackResources;
import net.minecraft.server.packs.PackLocationInfo;
import net.minecraft.server.packs.PackResources;
import net.minecraft.server.packs.PackType;
import net.minecraft.server.packs.metadata.MetadataSectionSerializer;
import net.minecraft.server.packs.metadata.pack.PackMetadataSection;
import net.minecraft.server.packs.repository.PackSource;
import net.minecraft.server.packs.resources.IoSupplier;

/**
 * Source-compatible implementation of the removed DelegatingPackResources base.
 * It preserves the legacy constructor contract by merging namespace lookups
 * across the supplied child packs.
 */
public class DelegatingPackResources extends AbstractPackResources {
    private final boolean hidden;
    private final PackMetadataSection packInfo;
    private final List<PackResources> packs;
    private final Map<String, List<PackResources>> assets;
    private final Map<String, List<PackResources>> data;

    public DelegatingPackResources(String id, boolean hidden, PackMetadataSection packInfo, List<? extends PackResources> packs) {
        super(new PackLocationInfo(id, Component.literal(id), PackSource.BUILT_IN, Optional.empty()));
        this.hidden = hidden;
        this.packInfo = packInfo;
        this.packs = List.copyOf(packs);
        this.assets = this.buildNamespaceMap(PackType.CLIENT_RESOURCES, packs);
        this.data = this.buildNamespaceMap(PackType.SERVER_DATA, packs);
    }

    private Map<String, List<PackResources>> buildNamespaceMap(PackType type, List<? extends PackResources> packList) {
        Map<String, List<PackResources>> map = new LinkedHashMap<>();
        for (PackResources pack : packList) {
            for (String namespace : pack.getNamespaces(type)) {
                map.computeIfAbsent(namespace, key -> new ArrayList<>()).add(pack);
            }
        }
        map.replaceAll((key, value) -> List.copyOf(value));
        return Map.copyOf(map);
    }

    @Override
    public boolean isHidden() {
        return this.hidden;
    }

    @Nullable
    @Override
    public IoSupplier<InputStream> getRootResource(String... paths) {
        for (PackResources pack : this.packs) {
            IoSupplier<InputStream> resource = pack.getRootResource(paths);
            if (resource != null) {
                return resource;
            }
        }
        return null;
    }

    @SuppressWarnings("unchecked")
    @Nullable
    @Override
    public <T> T getMetadataSection(MetadataSectionSerializer<T> deserializer) throws IOException {
        return deserializer.getMetadataSectionName().equals("pack") ? (T) this.packInfo : null;
    }

    @Nullable
    @Override
    public IoSupplier<InputStream> getResource(PackType type, ResourceLocation location) {
        for (PackResources pack : this.getCandidatePacks(type, location)) {
            IoSupplier<InputStream> resource = pack.getResource(type, location);
            if (resource != null) {
                return resource;
            }
        }
        return null;
    }

    @Override
    public void listResources(PackType type, String namespace, String path, ResourceOutput output) {
        for (PackResources pack : this.packs) {
            pack.listResources(type, namespace, path, output);
        }
    }

    @Override
    public Set<String> getNamespaces(PackType type) {
        return type == PackType.CLIENT_RESOURCES ? this.assets.keySet() : this.data.keySet();
    }

    @Override
    public void close() {
        for (PackResources pack : this.packs) {
            pack.close();
        }
    }

    @Nullable
    public List<PackResources> getChildren() {
        return this.packs;
    }

    private List<PackResources> getCandidatePacks(PackType type, ResourceLocation location) {
        Map<String, List<PackResources>> map = type == PackType.CLIENT_RESOURCES ? this.assets : this.data;
        return map.getOrDefault(location.getNamespace(), Collections.emptyList());
    }
}
""".trimStart()


    private fun rewriteUnusedLegacyEnchantmentSubclasses(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        val sources = javaFiles.associateWith { it.readText() }
        val extendsByClass = sources.mapNotNull { (file, source) ->
            val match = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+([A-Za-z_$][\w$]*)\b""").find(source)
                ?: return@mapNotNull null
            file to (match.groupValues[1] to match.groupValues[2])
        }

        val legacyNames = linkedSetOf<String>()
        extendsByClass
            .filter { (_, classAndBase) -> classAndBase.second == "Enchantment" }
            .forEach { (_, classAndBase) -> legacyNames.add(classAndBase.first) }
        var changed: Boolean
        do {
            changed = false
            extendsByClass.forEach { (_, classAndBase) ->
                if (classAndBase.second in legacyNames && legacyNames.add(classAndBase.first)) {
                    changed = true
                }
            }
        } while (changed)
        if (legacyNames.isEmpty()) return emptyList()

        val allSource = sources.values.joinToString("\n")
        val changes = mutableListOf<Change>()
        for ((file, source) in sources) {
            val classMatch = Regex("""\bpublic\s+class\s+([A-Za-z_$][\w$]*)\s+extends\s+([A-Za-z_$][\w$]*)\b""").find(source)
                ?: continue
            val className = classMatch.groupValues[1]
            if (className !in legacyNames) continue
            if (Regex("""\bnew\s+${Regex.escape(className)}\s*\(""").containsMatchIn(allSource) ||
                Regex("""${Regex.escape(className)}\s*::\s*new""").containsMatchIn(allSource)) {
                continue
            }

            val rewritten = legacyEnchantmentUtilitySource(source, className)
            if (rewritten != source) {
                if (!dryRun) file.writeText(rewritten)
                changes.add(Change(
                    file = file,
                    line = 1,
                    description = "Rewrite unused legacy Enchantment subclass as utility holder",
                    before = "class $className extends Enchantment",
                    after = "final utility class preserving static helper methods",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-unused-enchantment-subclass-helper"
                ))
            }
        }
        return changes
    }

    private fun legacyEnchantmentUtilitySource(source: String, className: String): String {
        val packageLine = Regex("""(?m)^package\s+[\w.]+\s*;\s*""").find(source)?.value?.trimEnd().orEmpty()
        val imports = source.lines()
            .filter { it.trim().startsWith("import ") }
            .filterNot { line ->
                val trimmed = line.trim()
                trimmed == "import net.minecraft.world.item.enchantment.Enchantment;" ||
                    trimmed == "import net.minecraft.world.item.enchantment.Enchantments;" ||
                    trimmed.contains(".EnchantmentCategory;") ||
                    trimmed.contains(".MobType;")
            }
            .joinToString(System.lineSeparator())
        val staticMethods = extractStaticJavaMethods(source)
        val body = buildString {
            appendLine("public final class $className {")
            appendLine()
            appendLine("    private $className() {")
            appendLine("    }")
            if (staticMethods.isNotEmpty()) {
                appendLine()
                append(staticMethods.joinToString(System.lineSeparator() + System.lineSeparator()) { indentJavaBlock(it.trim(), "    ") })
                appendLine()
            }
            appendLine("}")
        }.trimEnd()
        return listOf(packageLine, imports, body)
            .filter { it.isNotBlank() }
            .joinToString(System.lineSeparator() + System.lineSeparator()) + System.lineSeparator()
    }

    private fun extractStaticJavaMethods(source: String): List<String> {
        val methods = mutableListOf<String>()
        val pattern = Regex("""(?m)^[ \t]*(?:public|protected|private)\s+static\s+[^=;]+?\)\s*\{""")
        for (match in pattern.findAll(source)) {
            val openBrace = source.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (closeBrace > openBrace) {
                methods.add(source.substring(match.range.first, closeBrace + 1))
            }
        }
        return methods
    }

    private fun indentJavaBlock(source: String, indent: String): String =
        source.lines().joinToString(System.lineSeparator()) { line ->
            if (line.isBlank()) line else indent + line.trimEnd()
        }

    private fun addCustomFluidRegisterCapabilitiesMethod(source: String): String {
        val constructorMatch = Regex("""private\s+CustomFluidCapabilities\s*\(\s*\)\s*\{\s*\}""")
            .find(source)
            ?: return source
        val method = """

    public static void registerCapabilities(RegisterCapabilitiesEvent event) {
        event.registerItem(
                Capabilities.FluidHandler.ITEM,
                (stack, context) -> new CustomFluidContainerHandler(stack, ContainerKind.BUCKET),
                Items.BUCKET,
                CustomFluidItems.CUSTOM_FLUID_BUCKET.get());
        event.registerItem(
                Capabilities.FluidHandler.ITEM,
                (stack, context) -> new CustomFluidContainerHandler(stack, ContainerKind.BOTTLE),
                Items.GLASS_BOTTLE,
                CustomFluidItems.CUSTOM_FLUID_BOTTLE.get());
    }
"""
        val insertPos = constructorMatch.range.last + 1
        return source.substring(0, insertPos) + method + source.substring(insertPos)
    }

    private fun removeInitCapabilitiesContaining(source: String, requiredText: String): String {
        var result = source
        while (true) {
            val methodNameIndex = result.indexOf("initCapabilities")
            if (methodNameIndex < 0) return result
            val openBrace = result.indexOf('{', methodNameIndex)
            if (openBrace < 0) return result
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) return result
            val signatureStart = result.lastIndexOf('\n', methodNameIndex).let { if (it < 0) 0 else it + 1 }
            val annotationStart = Regex("""(?m)[ \t]*@Override\s*\r?\n\s*$""")
                .findAll(result.substring(0, signatureStart))
                .lastOrNull()
                ?.range
                ?.first
                ?: signatureStart
            val methodText = result.substring(annotationStart, closeBrace + 1)
            if (!methodText.contains(requiredText)) return result
            var end = closeBrace + 1
            if (end < result.length && result[end] == '\r') end++
            if (end < result.length && result[end] == '\n') end++
            result = result.removeRange(annotationStart, end)
        }
    }

    private fun removeMethodByName(source: String, methodName: String): String {
        val methodNameIndex = Regex("""\b${Regex.escape(methodName)}\s*\(""")
            .find(source)
            ?.range
            ?.first
            ?: return source
        val openBrace = source.indexOf('{', methodNameIndex)
        if (openBrace < 0) return source
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return source
        val signatureStart = source.lastIndexOf('\n', methodNameIndex).let { if (it < 0) 0 else it + 1 }
        val annotationStart = Regex("""(?m)(?:^[ \t]*@[A-Za-z0-9_.]+(?:\([^)]*\))?\s*\r?\n)+[ \t]*$""")
            .findAll(source.substring(0, signatureStart))
            .lastOrNull()
            ?.range
            ?.first
            ?: signatureStart
        var end = closeBrace + 1
        if (end < source.length && source[end] == '\r') end++
        if (end < source.length && source[end] == '\n') end++
        return source.removeRange(annotationStart, end)
    }

    private fun removeInnerClassByName(source: String, className: String): String {
        val classMatch = Regex("""(?m)^[ \t]*(?:private|public|protected)?\s*static\s+final\s+class\s+${Regex.escape(className)}\b""")
            .find(source)
            ?: return source
        val openBrace = source.indexOf('{', classMatch.range.first)
        if (openBrace < 0) return source
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return source
        var end = closeBrace + 1
        if (end < source.length && source[end] == '\r') end++
        if (end < source.length && source[end] == '\n') end++
        return source.removeRange(classMatch.range.first, end)
    }

    private data class BlockEntityFluidCapabilityMigration(
        val file: Path,
        val packageName: String,
        val className: String
    )

    private fun migrateBlockEntityFluidCapabilities(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()
        val migrations = mutableListOf<BlockEntityFluidCapabilityMigration>()

        for (javaFile in javaFiles) {
            val original = javaFile.readText()
            if (!original.contains("extends BlockEntity") ||
                !original.contains("getCapability") ||
                !original.contains("Capabilities.FluidHandler.BLOCK") ||
                !original.contains("FluidTank")
            ) {
                continue
            }

            val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+BlockEntity\b""")
                .find(original)
                ?.groupValues
                ?.get(1)
                ?: continue
            val registryRef = Regex(
                """super\s*\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.([A-Z0-9_]+)\.get\(\)"""
            ).find(original) ?: continue
            val registryOwner = registryRef.groupValues[1]
            val registryField = registryRef.groupValues[2]
            val tankName = Regex("""\bFluidTank\s+([A-Za-z_$][\w$]*)\s*=""")
                .find(original)
                ?.groupValues
                ?.get(1)
                ?: "fluidTank"

            var modified = original
            modified = Regex(
                """(?m)^[ \t]*private\s+final\s+LazyOptional<[^;\r\n]+>\s+[A-Za-z_$][\w$]*\s*=\s*LazyOptional\.of\(\(\)\s*->\s*${Regex.escape(tankName)}\s*\);\s*\r?\n"""
            ).replace(modified, "")
            modified = removeMethodByName(modified, "getCapability")
            modified = removeMethodByName(modified, "invalidateCaps")

            if (!modified.contains("FluidTank getFluidTank()")) {
                modified = insertBeforeLastClassBrace(modified, """

    public FluidTank getFluidTank() {
        return $tankName;
    }
""".trimEnd())
            }

            if (!modified.contains("registerCapabilities(RegisterCapabilitiesEvent")) {
                modified = insertBeforeLastClassBrace(modified, """

    public static void registerCapabilities(RegisterCapabilitiesEvent event) {
        event.registerBlockEntity(
                Capabilities.FluidHandler.BLOCK,
                $registryOwner.$registryField.get(),
                ($className blockEntity, net.minecraft.core.Direction side) -> blockEntity.getFluidTank());
    }
""".trimEnd())
            }

            modified = addImportIfMissing(modified, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")
            modified = removeImport(modified, "com.modporter.compat.Capability")
            modified = removeImport(modified, "com.modporter.compat.LazyOptional")
            modified = removeImport(modified, "net.neoforged.neoforge.fluids.capability.IFluidHandler")
            if (!modified.contains("@NotNull")) {
                modified = removeImport(modified, "org.jetbrains.annotations.NotNull")
            }

            if (modified == original) continue

            if (!dryRun) {
                javaFile.writeText(modified)
            }
            migrations.add(BlockEntityFluidCapabilityMigration(javaFile, packageNameOf(modified), className))
            changes.add(Change(
                file = javaFile,
                line = 0,
                description = "Migrate BlockEntity fluid handler from getCapability() to RegisterCapabilitiesEvent",
                before = "getCapability(Capabilities.FluidHandler.BLOCK) -> LazyOptional fluid handler",
                after = "RegisterCapabilitiesEvent.registerBlockEntity(Capabilities.FluidHandler.BLOCK, ...)",
                confidence = Confidence.HIGH,
                ruleId = "struct-blockentity-fluid-capability"
            ))
        }

        if (migrations.isEmpty()) return changes

        val mainClass = detectModMainClass(projectDir) ?: return changes
        var mainText = mainClass.readText()
        val originalMainText = mainText
        val mainPackage = packageNameOf(mainText)
        val constructorBusName = Regex("""\bIEventBus\s+([A-Za-z_$][\w$]*)\s*=""")
            .find(mainText)
            ?.groupValues
            ?.get(1)
            ?: Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+([A-Za-z_$][\w$]*)""")
                .find(mainText)
                ?.groupValues
                ?.get(1)
            ?: "modEventBus"

        for (migration in migrations) {
            if (mainText.contains("${migration.className}::registerCapabilities")) continue
            if (migration.packageName != mainPackage) {
                mainText = addImportIfMissing(mainText, "${migration.packageName}.${migration.className}")
            }
            val registration = "        $constructorBusName.addListener(${migration.className}::registerCapabilities);"
            mainText = insertModBusListener(mainText, constructorBusName, registration, "BlockEntitiesRegister")
            changes.add(Change(
                file = mainClass,
                line = 0,
                description = "Register ${migration.className} block-entity capabilities on the mod event bus",
                before = "(no block-entity capability listener)",
                after = "$constructorBusName.addListener(${migration.className}::registerCapabilities)",
                confidence = Confidence.HIGH,
                ruleId = "struct-blockentity-fluid-capability-listener"
            ))
        }

        if (mainText != originalMainText && !dryRun) {
            mainClass.writeText(mainText)
        }

        return changes
    }

    private data class BlockEntityLegacyCapabilityMigration(
        val file: Path,
        val packageName: String,
        val className: String,
        val preferredRegistryClassName: String
    )

    private data class BlockEntityCapabilityProviderSpec(
        val capabilityExpression: String,
        val providerExpression: String,
        val consumedLazyOptionalFields: Set<String> = emptySet()
    )

    private data class JavaIfBlock(val condition: String, val body: String)

    private fun migrateBlockEntityLegacyCapabilities(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val migrations = mutableListOf<BlockEntityLegacyCapabilityMigration>()
        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()

        for (javaFile in javaFiles) {
            val original = javaFile.readText()
            if (!original.contains("getCapability") ||
                !original.contains("Capabilities.") ||
                !original.contains("LazyOptional") ||
                original.contains("registerCapabilities(RegisterCapabilitiesEvent")
            ) {
                continue
            }

            val id = """[A-Za-z_$][\w$]*"""
            val className = Regex("""\bclass\s+($id)\s+extends\s+$id(?:\.$id)*BlockEntity\b""")
                .find(original)
                ?.groupValues
                ?.get(1)
                ?: continue
            val registryRef = blockEntityRegistryRefFromConstructors(original) ?: continue
            val registryOwner = registryRef.substringBeforeLast('.')
            val registryField = registryRef.substringAfterLast('.')
            val getCapabilityMethod = javaDeclaredMethodText(original, "getCapability") ?: continue
            val providers = extractBlockEntityLegacyCapabilityProviders(getCapabilityMethod, original)
            if (providers.isEmpty()) continue

            var modified = original
            val consumedFields = providers.flatMap { it.consumedLazyOptionalFields }.toSet()
            modified = removeMethodByName(modified, "getCapability")
            modified = migrateLegacyCapabilityReviveCapsSource(modified)
            modified = removeLegacyCapabilityCacheState(modified, consumedFields)
            modified = cleanupLegacyCapabilityOverrideImports(modified)
            modified = addImportIfMissing(modified, "net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent")

            val registerMethod = renderBlockEntityCapabilityRegistrationMethod(
                className = className,
                registryRef = "$registryOwner.$registryField.get()",
                providers = providers
            )
            modified = insertBeforeLastClassBrace(modified, registerMethod)

            if (modified == original) continue
            if (!dryRun) {
                javaFile.writeText(modified)
            }
            migrations.add(
                BlockEntityLegacyCapabilityMigration(
                    file = javaFile,
                    packageName = packageNameOf(modified),
                    className = className,
                    preferredRegistryClassName = registryOwner.substringAfterLast('.')
                )
            )
            changes.add(Change(
                file = javaFile,
                line = 0,
                description = "Migrate source-shaped BlockEntity capabilities to RegisterCapabilitiesEvent",
                before = "getCapability(Capabilities.*.BLOCK) LazyOptional branches",
                after = "RegisterCapabilitiesEvent.registerBlockEntity providers",
                confidence = Confidence.HIGH,
                ruleId = "struct-blockentity-capability-provider"
            ))
        }

        if (migrations.isEmpty()) return changes

        val mainClass = detectModMainClass(projectDir) ?: return changes
        var mainText = mainClass.readText()
        val originalMainText = mainText
        val mainPackage = packageNameOf(mainText)
        val constructorBusName = Regex("""\bIEventBus\s+([A-Za-z_$][\w$]*)\s*=""")
            .find(mainText)
            ?.groupValues
            ?.get(1)
            ?: Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+([A-Za-z_$][\w$]*)""")
                .find(mainText)
                ?.groupValues
                ?.get(1)
            ?: "modEventBus"

        for (migration in migrations) {
            if (mainText.contains("${migration.className}::registerCapabilities")) continue
            if (migration.packageName != mainPackage) {
                mainText = addImportIfMissing(mainText, "${migration.packageName}.${migration.className}")
            }
            val registration = "        $constructorBusName.addListener(${migration.className}::registerCapabilities);"
            mainText = insertModBusListener(mainText, constructorBusName, registration, migration.preferredRegistryClassName)
            changes.add(Change(
                file = mainClass,
                line = 0,
                description = "Register ${migration.className} block-entity capabilities on the mod event bus",
                before = "(no block-entity capability listener)",
                after = "$constructorBusName.addListener(${migration.className}::registerCapabilities)",
                confidence = Confidence.HIGH,
                ruleId = "struct-blockentity-capability-provider-listener"
            ))
        }

        if (mainText != originalMainText && !dryRun) {
            mainClass.writeText(mainText)
        }

        return changes
    }

    private fun blockEntityRegistryRefFromConstructors(source: String): String? {
        val id = """[A-Za-z_$][\w$]*"""
        val registryReference = """($id(?:\.$id)*)\.([A-Z0-9_]+)\.get\(\)"""
        Regex("""super\s*\(\s*$registryReference""")
            .find(source)
            ?.let { return "${it.groupValues[1]}.${it.groupValues[2]}" }
        Regex("""\bthis\s*\(\s*$registryReference""")
            .find(source)
            ?.let { return "${it.groupValues[1]}.${it.groupValues[2]}" }
        return null
    }

    private fun extractBlockEntityLegacyCapabilityProviders(
        methodText: String,
        source: String
    ): List<BlockEntityCapabilityProviderSpec> {
        val removedGuard = Regex("""!\s*(?:this\.)?isRemoved\s*\(\s*\)""").containsMatchIn(methodText) ||
            Regex("""!\s*(?:this\.)?remove\b""").containsMatchIn(methodText)
        val sideParameter = getCapabilityDirectionParameterName(methodText)
        return listOf("Capabilities.ItemHandler.BLOCK", "Capabilities.FluidHandler.BLOCK")
            .mapNotNull { capability ->
                val block = findIfBlockContainingToken(methodText, capability) ?: return@mapNotNull null
                val provider = extractBlockEntityCapabilityProviderExpression(
                    branchBody = block.body,
                    source = source,
                    sideParameter = sideParameter
                ) ?: return@mapNotNull null
                val providerGuard = blockEntityCapabilityProviderGuard(
                    condition = block.condition,
                    capabilityExpression = capability,
                    sideParameter = sideParameter
                )
                val guards = (if (removedGuard) listOf("!blockEntity.isRemoved()") else emptyList()) + providerGuard
                val guardedProvider = if (guards.isNotEmpty()) {
                    "(${guards.distinct().joinToString(" && ")}) ? ${provider.expression} : null"
                } else {
                    provider.expression
                }
                BlockEntityCapabilityProviderSpec(capability, guardedProvider, provider.consumedLazyOptionalFields)
            }
    }

    private fun findIfBlockContainingToken(source: String, token: String): JavaIfBlock? {
        val tokenIndex = source.indexOf(token)
        if (tokenIndex < 0) return null
        var searchBefore = tokenIndex
        while (searchBefore >= 0) {
            val ifIndex = source.lastIndexOf("if", searchBefore)
            if (ifIndex < 0) return null
            val before = source.getOrNull(ifIndex - 1)
            val after = source.getOrNull(ifIndex + 2)
            if ((before != null && (before.isLetterOrDigit() || before == '_' || before == '$')) ||
                (after != null && (after.isLetterOrDigit() || after == '_' || after == '$'))) {
                searchBefore = ifIndex - 1
                continue
            }
            val openParen = source.indexOf('(', ifIndex)
            if (openParen < 0) return null
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) return null
            if (tokenIndex !in openParen..closeParen) {
                searchBefore = ifIndex - 1
                continue
            }
            val openBrace = source.indexOf('{', closeParen)
            if (openBrace < 0) return null
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace < 0) return null
            return JavaIfBlock(
                condition = source.substring(openParen + 1, closeParen).trim(),
                body = source.substring(openBrace + 1, closeBrace)
            )
        }
        return null
    }

    private data class LegacyCapabilityProvider(
        val expression: String,
        val consumedLazyOptionalFields: Set<String> = emptySet()
    )

    private fun getCapabilityDirectionParameterName(methodText: String): String {
        val signatureEnd = methodText.indexOf('{').takeIf { it >= 0 } ?: return "side"
        val signature = methodText.substring(0, signatureEnd)
        val paramsStart = signature.indexOf('(')
        val paramsEnd = signature.lastIndexOf(')')
        if (paramsStart < 0 || paramsEnd <= paramsStart) return "side"
        val params = splitTopLevelJavaArgs(signature.substring(paramsStart + 1, paramsEnd))
        return params.asReversed().firstNotNullOfOrNull { param ->
            Regex("""\bDirection\s+([A-Za-z_$][\w$]*)\b""").find(param)?.groupValues?.get(1)
        } ?: "side"
    }

    private fun blockEntityCapabilityProviderGuard(
        condition: String,
        capabilityExpression: String,
        sideParameter: String
    ): List<String> {
        return condition.split("&&")
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .filterNot { part ->
                part.contains(capabilityExpression) ||
                    Regex("""\b(?:cap|capability)\b""").containsMatchIn(part) &&
                    part.contains("Capabilities.")
            }
            .mapNotNull { part ->
                var migrated = part
                    .replace(Regex("""!\s*this\.remove\b"""), "!blockEntity.isRemoved()")
                    .replace(Regex("""!\s*remove\b"""), "!blockEntity.isRemoved()")
                    .replace(Regex("""this\.remove\b"""), "blockEntity.isRemoved()")
                    .replace(Regex("""\bthis\.isRemoved\s*\(\s*\)"""), "blockEntity.isRemoved()")
                if (sideParameter != "side") {
                    migrated = Regex("""\b${Regex.escape(sideParameter)}\b""").replace(migrated, "side")
                }
                migrated = migrated.replace("this.", "blockEntity.")
                if (migrated.contains("Capabilities.")) null else migrated
            }
    }

    private fun extractBlockEntityCapabilityProviderExpression(
        branchBody: String,
        source: String,
        sideParameter: String
    ): LegacyCapabilityProvider? {
        parseLegacyCapabilityReturnChain(branchBody, source, sideParameter)
            ?.let { return it }

        val sideBranch = Regex(
            """(?s)if\s*\((.*?)\)\s*\{\s*return\s+([^;]+);\s*}\s*else\s*\{\s*return\s+([^;]+);\s*}"""
        ).find(branchBody)
        if (sideBranch != null) {
            var condition = sideBranch.groupValues[1].trim().replace("this.", "blockEntity.")
            if (sideParameter != "side") {
                condition = Regex("""\b${Regex.escape(sideParameter)}\b""").replace(condition, "side")
            }
            val whenTrue = legacyCapabilityReturnToProvider(sideBranch.groupValues[2], branchBody, source) ?: return null
            val whenFalse = legacyCapabilityReturnToProvider(sideBranch.groupValues[3], branchBody, source) ?: return null
            return LegacyCapabilityProvider(
                expression = "($condition ? ${whenTrue.expression} : ${whenFalse.expression})",
                consumedLazyOptionalFields = whenTrue.consumedLazyOptionalFields + whenFalse.consumedLazyOptionalFields
            )
        }

        val directReturn = Regex("""return\s+([^;]+);""").find(branchBody) ?: return null
        return legacyCapabilityReturnToProvider(directReturn.groupValues[1], branchBody, source)
    }

    private fun parseLegacyCapabilityReturnChain(
        branchBody: String,
        source: String,
        sideParameter: String
    ): LegacyCapabilityProvider? {
        val returns = Regex("""return\s+([^;]+);""").findAll(branchBody).toList()
        if (returns.size < 2) return null
        val firstIf = Regex("""(?s)^\s*if\s*\((.*?)\)\s*\{""").find(branchBody) ?: return null
        val openBrace = branchBody.indexOf('{', firstIf.range.last)
        if (openBrace < 0) return null
        val closeBrace = findMatchingBrace(branchBody, openBrace)
        if (closeBrace < 0) return null
        val condition = firstIf.groupValues[1].trim()
        val ifBody = branchBody.substring(openBrace + 1, closeBrace)
        val trueReturn = Regex("""return\s+([^;]+);""").find(ifBody)?.groupValues?.get(1) ?: return null
        val elseIndex = branchBody.indexOf("else", closeBrace + 1)
        if (elseIndex < 0) return null
        val elseTail = branchBody.substring(elseIndex + "else".length).trimStart()
        val falseProvider = if (elseTail.startsWith("if")) {
            val nested = parseLegacyCapabilityReturnChain(elseTail.removePrefix("if").let { "if$it" }, source, sideParameter)
                ?: return null
            nested
        } else {
            val elseOpen = branchBody.indexOf('{', elseIndex)
            if (elseOpen < 0) return null
            val elseClose = findMatchingBrace(branchBody, elseOpen)
            if (elseClose < 0) return null
            val elseBody = branchBody.substring(elseOpen + 1, elseClose)
            val falseReturn = Regex("""return\s+([^;]+);""").find(elseBody)?.groupValues?.get(1) ?: return null
            legacyCapabilityReturnToProvider(falseReturn, branchBody, source) ?: return null
        }
        val trueProvider = legacyCapabilityReturnToProvider(trueReturn, branchBody, source) ?: return null
        var migratedCondition = condition.replace("this.", "blockEntity.")
        if (sideParameter != "side") {
            migratedCondition = Regex("""\b${Regex.escape(sideParameter)}\b""").replace(migratedCondition, "side")
        }
        return LegacyCapabilityProvider(
            expression = "($migratedCondition ? ${trueProvider.expression} : ${falseProvider.expression})",
            consumedLazyOptionalFields = trueProvider.consumedLazyOptionalFields + falseProvider.consumedLazyOptionalFields
        )
    }

    private fun legacyCapabilityReturnToProvider(
        returnExpression: String,
        branchBody: String,
        source: String
    ): LegacyCapabilityProvider? {
        val expression = returnExpression.trim()
        if (expression == "LazyOptional.empty()" || expression.endsWith(".empty()")) return LegacyCapabilityProvider("null")
        Regex("""^(?:this\.)?([A-Za-z_$][\w$]*)\.cast\(\)$""")
            .find(expression)
            ?.let { match ->
                val field = match.groupValues[1]
                val directProvider = legacyLazyOptionalFieldProvider(field, null, branchBody, source)
                if (directProvider != null) return directProvider
                return LegacyCapabilityProvider("blockEntity.$field.orElse(null)", setOf(field))
            }
        Regex("""^(?:this\.)?([A-Za-z_$][\w$]*)\s*\[\s*(\d+)\s*]\.cast\(\)$""")
            .find(expression)
            ?.let { match ->
                val field = match.groupValues[1]
                val index = match.groupValues[2].toIntOrNull()
                val indexedProvider = legacyLazyOptionalFieldProvider(field, index, branchBody, source)
                if (indexedProvider != null) return indexedProvider
                return LegacyCapabilityProvider("blockEntity.$field[$index].orElse(null)", setOf(field))
            }
        Regex("""^(?:this\.)?([A-Za-z_$][\w$]*)\.orElse\(\s*null\s*\)$""")
            .find(expression)
            ?.let { match ->
                val field = match.groupValues[1]
                val directProvider = legacyLazyOptionalFieldProvider(field, null, branchBody, source)
                if (directProvider != null) return directProvider
                return LegacyCapabilityProvider("blockEntity.$field.orElse(null)", setOf(field))
            }
        Regex("""^LazyOptional\.of\(\s*\(\)\s*->\s*(.*?)\s*\)\.cast\(\)$""")
            .find(expression)
            ?.let { return LegacyCapabilityProvider(it.groupValues[1].trim().replace("this.", "blockEntity.")) }
        return if (expression.startsWith("this.")) {
            LegacyCapabilityProvider(expression.replaceFirst("this.", "blockEntity."))
        } else {
            null
        }
    }

    private fun legacyLazyOptionalFieldProvider(
        fieldName: String,
        index: Int?,
        branchBody: String,
        source: String
    ): LegacyCapabilityProvider? {
        val assignmentPattern = if (index == null) {
            Regex("""(?:this\.)?${Regex.escape(fieldName)}\s*=\s*LazyOptional\.of\(\s*(.*?)\s*\)\s*;""", RegexOption.DOT_MATCHES_ALL)
        } else {
            null
        }
        val initializer = assignmentPattern
            ?.find(branchBody)
            ?.groupValues
            ?.get(1)
            ?: assignmentPattern
                ?.find(source)
                ?.groupValues
                ?.get(1)
        if (initializer != null) {
            legacyLazyOptionalInitializerToProvider(initializer)
                ?.let { return LegacyCapabilityProvider(it, setOf(fieldName)) }
        }

        if (index != null) {
            val sidedWrapper = sidedInvWrapperProviderForIndex(fieldName, index, source)
            if (sidedWrapper != null) {
                return LegacyCapabilityProvider(sidedWrapper, setOf(fieldName))
            }
        }

        Regex(
            """(?:private|protected|public)\s+(?:final\s+)?LazyOptional<[^;]+>\s+${Regex.escape(fieldName)}\s*=\s*LazyOptional\.of\(\s*(.*?)\s*\)\s*;""",
            RegexOption.DOT_MATCHES_ALL
        ).find(source)?.groupValues?.get(1)?.let { initializerExpression ->
            legacyLazyOptionalInitializerToProvider(initializerExpression)
                ?.let { return LegacyCapabilityProvider(it, setOf(fieldName)) }
        }
        return null
    }

    private fun legacyLazyOptionalInitializerToProvider(initializer: String): String? {
        val trimmed = initializer.trim()
        Regex("""^this::([A-Za-z_$][\w$]*)$""")
            .find(trimmed)
            ?.let { return "blockEntity.${it.groupValues[1]}()" }
        Regex("""^\(\s*\)\s*->\s*(.*?)$""", RegexOption.DOT_MATCHES_ALL)
            .find(trimmed)
            ?.let { match ->
                return legacyInstanceProviderExpression(match.groupValues[1].trim())
            }
        return null
    }

    private fun legacyInstanceProviderExpression(expression: String): String {
        val migrated = expression.replace("this.", "blockEntity.")
        if (migrated.contains("blockEntity.")) return migrated
        if (Regex("""^[A-Za-z_$][\w$]*\s*\([^;{}]*\)$""").matches(migrated)) {
            return "blockEntity.$migrated"
        }
        if (Regex("""^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*$""").matches(migrated) &&
            !migrated.substringBefore('.').first().isUpperCase()) {
            return "blockEntity.$migrated"
        }
        return migrated
    }

    private fun sidedInvWrapperProviderForIndex(fieldName: String, index: Int, source: String): String? {
        val initializer = Regex(
            """${Regex.escape(fieldName)}\s*=\s*SidedInvWrapper\.create\(\s*this\s*,\s*([^;]+?)\s*\)""",
            RegexOption.DOT_MATCHES_ALL
        ).find(source)?.groupValues?.get(1) ?: return null
        val sides = splitTopLevelJavaArgs(initializer).map { it.trim() }
        val side = sides.getOrNull(index) ?: return null
        return "new SidedInvWrapper(blockEntity, $side)"
    }

    private fun renderBlockEntityCapabilityRegistrationMethod(
        className: String,
        registryRef: String,
        providers: List<BlockEntityCapabilityProviderSpec>
    ): String {
        val registrations = providers.joinToString("\n") { provider ->
            """
        event.registerBlockEntity(
                ${provider.capabilityExpression},
                $registryRef,
                ($className blockEntity, net.minecraft.core.Direction side) -> ${provider.providerExpression});
""".trimEnd()
        }
        return """

    public static void registerCapabilities(RegisterCapabilitiesEvent event) {
$registrations
    }
""".trimEnd()
    }

    private fun migrateLegacyCapabilityReviveCapsSource(source: String): String {
        val methodText = javaDeclaredMethodText(source, "reviveCaps") ?: return source
        if (source.contains("void clearRemoved(")) return source
        val migratedMethod = Regex("""\breviveCaps\s*\(""")
            .replace(methodText, "clearRemoved(")
            .let { Regex("""super\.reviveCaps\(\)\s*;""").replace(it, "super.clearRemoved();") }
        return source.replace(methodText, migratedMethod)
    }

    private fun cleanupLegacyCapabilityOverrideImports(source: String): String {
        var result = source
        if (!Regex("""\bCapability\s*<""").containsMatchIn(result)) {
            result = removeImport(result, "net.neoforged.neoforge.capabilities.Capability")
            result = removeImport(result, "com.modporter.compat.Capability")
            result = Regex("""(?m)^[ \t]*import\s+[\w.]+\.compat\.Capability;\s*\r?\n""").replace(result, "")
        }
        val withoutImports = Regex("""(?m)^[ \t]*import\s+[^\r\n]+;\s*\r?\n""").replace(result, "")
        if (!withoutImports.contains("LazyOptional")) {
            result = removeImport(result, "com.modporter.compat.LazyOptional")
            result = Regex("""(?m)^[ \t]*import\s+[\w.]+\.compat\.LazyOptional;\s*\r?\n""").replace(result, "")
        }
        if (!result.contains("@Nullable")) {
            result = removeImport(result, "org.jetbrains.annotations.Nullable")
            result = removeImport(result, "javax.annotation.Nullable")
        }
        if (!result.contains("@Nonnull")) {
            result = removeImport(result, "javax.annotation.Nonnull")
        }
        if (!result.contains("@NotNull")) {
            result = removeImport(result, "org.jetbrains.annotations.NotNull")
        }
        return result
    }

    private fun removeLegacyCapabilityCacheState(source: String, fields: Set<String>): String {
        if (fields.isEmpty()) return source
        var result = source
        result = removeLegacyCapabilityCacheOnlyMethods(result, fields)
        result = removeLegacyCapabilityCacheBlocks(result, fields)
        for (field in fields) {
            result = removeLazyOptionalFieldDeclaration(result, field)
        }
        return result
    }

    private fun removeLegacyCapabilityCacheOnlyMethods(source: String, fields: Set<String>): String {
        var result = source
        val methodNames = listOf("invalidateCaps", "invalidateCapabilities", "reviveCaps", "clearRemoved")
        var changed: Boolean
        do {
            changed = false
            for (methodName in methodNames) {
                val methodText = javaDeclaredMethodText(result, methodName) ?: continue
                if (fields.none { methodText.contains(it) }) continue
                if (!isLegacyCapabilityCacheOnlyMethod(methodText, fields)) continue
                result = result.replace(methodText, "")
                changed = true
                break
            }
        } while (changed)
        return result
    }

    private fun isLegacyCapabilityCacheOnlyMethod(methodText: String, fields: Set<String>): Boolean {
        val openBrace = methodText.indexOf('{')
        val closeBrace = methodText.lastIndexOf('}')
        if (openBrace < 0 || closeBrace <= openBrace) return false
        var body = methodText.substring(openBrace + 1, closeBrace)
        body = removeLegacyCapabilityCacheBlocks(body, fields)
        body = Regex("""(?m)^[ \t]*super\.(?:invalidateCaps|invalidateCapabilities|reviveCaps|clearRemoved)\s*\(\s*\)\s*;\s*\r?$""")
            .replace(body, "")
        for (field in fields) {
            val fieldRef = Regex.escape(field)
            body = Regex("""(?m)^[ \t]*(?:this\.)?$fieldRef\s*=\s*(?:LazyOptional\.of|SidedInvWrapper\.create)\([^;]*;\s*\r?$""")
                .replace(body, "")
            body = Regex("""(?m)^[ \t]*(?:this\.)?$fieldRef\s*=\s*null\s*;\s*\r?$""")
                .replace(body, "")
        }
        body = Regex("""(?m)^[ \t]*LazyOptional<[^;]+>\s+[A-Za-z_$][\w$]*\s*:\s*[^;]+;\s*\r?$""").replace(body, "")
        return body.isBlank()
    }

    private fun removeLegacyCapabilityCacheBlocks(source: String, fields: Set<String>): String {
        var result = source
        var searchStart = 0
        while (searchStart < result.length) {
            val match = Regex("""\b(?:if|for)\s*\(""").find(result, searchStart) ?: break
            val openParen = result.indexOf('(', match.range.first)
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                searchStart = match.range.last + 1
                continue
            }
            val openBrace = result.indexOf('{', closeParen)
            if (openBrace < 0) {
                searchStart = closeParen + 1
                continue
            }
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) {
                searchStart = openBrace + 1
                continue
            }
            val blockText = result.substring(match.range.first, closeBrace + 1)
            val referencesField = fields.any { Regex("""\b${Regex.escape(it)}\b""").containsMatchIn(blockText) }
            val cacheOnly = referencesField &&
                (blockText.contains("LazyOptional") ||
                    blockText.contains(".invalidate()") ||
                    blockText.contains("SidedInvWrapper.create") ||
                    blockText.contains("= null"))
            if (!cacheOnly) {
                searchStart = closeBrace + 1
                continue
            }
            val lineStart = result.lastIndexOf('\n', match.range.first).let { if (it < 0) 0 else it + 1 }
            var end = closeBrace + 1
            if (end < result.length && result[end] == '\r') end++
            if (end < result.length && result[end] == '\n') end++
            result = result.removeRange(lineStart, end)
            searchStart = lineStart
        }
        return result
    }

    private fun removeLazyOptionalFieldDeclaration(source: String, fieldName: String): String {
        val lines = source.splitToSequence("\n").toMutableList()
        var index = 0
        while (index < lines.size) {
            val line = lines[index]
            if (!line.contains("LazyOptional") ||
                !Regex("""\b${Regex.escape(fieldName)}\b""").containsMatchIn(line) ||
                !line.trimEnd().endsWith(";")) {
                index++
                continue
            }
            var start = index
            while (start > 0 && Regex("""^[ \t]*@[A-Za-z0-9_.]+(?:\([^)]*\))?[ \t]*\r?$""").matches(lines[start - 1])) {
                start--
            }
            repeat(index - start + 1) { lines.removeAt(start) }
            index = start
        }
        return lines.joinToString("\n")
    }

    private fun migrateDirtinessCapabilityToAttachment(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()

        val capabilityFile = javaFiles.firstOrNull { file ->
            val text = file.readText()
            file.fileName.toString() == "DirtinessCapability.java" &&
                text.contains("class DirtinessCapability") &&
                text.contains("DirtinessData") &&
                (text.contains("ICapabilityProvider") || text.contains("AttachCapabilitiesEvent"))
        } ?: return changes

        val capabilityText = capabilityFile.readText()
        val packageName = packageNameOf(capabilityText)
        val dataFile = capabilityFile.parent.resolve("DirtinessData.java")
        val attachmentFile = capabilityFile.parent.resolve("DirtinessAttachment.java")
        val mainClass = detectModMainClass(projectDir)
        val mainText = mainClass?.readText().orEmpty()
        val modRef = modIdReferenceForGeneratedClass(mainClass, mainText, packageName)

        val bridgeSource = dirtinessCapabilityBridgeSource(packageName)
        if (capabilityText != bridgeSource) {
            if (!dryRun) {
                capabilityFile.writeText(bridgeSource)
            }
            changes.add(Change(
                file = capabilityFile,
                line = 1,
                description = "Migrate DirtinessCapability provider to a NeoForge attachment bridge",
                before = "CapabilityManager + AttachCapabilitiesEvent + ICapabilityProvider",
                after = "player.getData(DirtinessAttachment.DIRTINESS) bridge",
                confidence = Confidence.HIGH,
                ruleId = "struct-dirtiness-attachment-bridge"
            ))
        }

        if (dataFile.exists()) {
            val originalData = dataFile.readText()
            val migratedData = migrateDirtinessDataNbtSerializable(originalData)
            if (migratedData != originalData) {
                if (!dryRun) {
                    dataFile.writeText(migratedData)
                }
                changes.add(Change(
                    file = dataFile,
                    line = 1,
                    description = "Make DirtinessData compatible with AttachmentType.serializable",
                    before = "serializeNBT()/deserializeNBT(CompoundTag)",
                    after = "INBTSerializable<CompoundTag> with HolderLookup.Provider",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-dirtiness-data-attachment-serializable"
                ))
            }
        }

        if (!attachmentFile.exists()) {
            if (!dryRun) {
                attachmentFile.writeText(dirtinessAttachmentSource(packageName, modRef))
            }
            changes.add(Change(
                file = attachmentFile,
                line = 1,
                description = "Generate NeoForge attachment registration for DirtinessData",
                before = "(missing)",
                after = "DirtinessAttachment.register(IEventBus)",
                confidence = Confidence.HIGH,
                ruleId = "struct-dirtiness-attachment-register"
            ))
        }

        if (mainClass != null && mainText.isNotBlank() && !mainText.contains("DirtinessAttachment.register(")) {
            var migratedMain = mainText
            val mainPackage = packageNameOf(migratedMain)
            val constructorBusName = Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)""")
                .find(migratedMain)
                ?.groupValues
                ?.get(1)
                ?: "modEventBus"

            if (packageName != mainPackage) {
                migratedMain = addImportIfMissing(migratedMain, "$packageName.DirtinessAttachment")
            }
            val registration = "        DirtinessAttachment.register($constructorBusName);"
            migratedMain = insertModBusListener(migratedMain, constructorBusName, registration, "EntityRegister")
            if (migratedMain != mainText) {
                if (!dryRun) {
                    mainClass.writeText(migratedMain)
                }
                changes.add(Change(
                    file = mainClass,
                    line = 1,
                    description = "Register DirtinessAttachment on the mod event bus",
                    before = "(no DirtinessAttachment.register call)",
                    after = "DirtinessAttachment.register($constructorBusName)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-dirtiness-attachment-main-register"
                ))
            }
        }

        return changes
    }

    private fun dirtinessCapabilityBridgeSource(packageName: String): String = """package $packageName;

import com.modporter.compat.LazyOptional;
import net.minecraft.world.entity.player.Player;
import org.jetbrains.annotations.Nullable;

public final class DirtinessCapability {
    private DirtinessCapability() {
    }

    public static LazyOptional<DirtinessData> get(Player player) {
        return LazyOptional.of(() -> player.getData(DirtinessAttachment.DIRTINESS));
    }

    @Nullable
    public static DirtinessData getOrNull(Player player) {
        return player.getData(DirtinessAttachment.DIRTINESS);
    }
}
"""

    private fun dirtinessAttachmentSource(packageName: String, modRef: String): String = """package $packageName;

import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.neoforged.neoforge.registries.NeoForgeRegistries;

import java.util.function.Supplier;

public final class DirtinessAttachment {
    public static final DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES =
            DeferredRegister.create(NeoForgeRegistries.ATTACHMENT_TYPES, $modRef);

    public static final Supplier<AttachmentType<DirtinessData>> DIRTINESS =
            ATTACHMENT_TYPES.register("dirtiness", () -> AttachmentType.serializable(DirtinessData::new).copyOnDeath().build());

    private DirtinessAttachment() {
    }

    public static void register(IEventBus modEventBus) {
        ATTACHMENT_TYPES.register(modEventBus);
    }
}
"""

    private fun migrateDirtinessDataNbtSerializable(source: String): String {
        var result = source
        if (!result.contains("implements INBTSerializable<CompoundTag>")) {
            result = Regex("""public\s+class\s+DirtinessData\b""")
                .replace(result, "public class DirtinessData implements INBTSerializable<CompoundTag>")
            result = addImportIfMissing(result, "net.neoforged.neoforge.common.util.INBTSerializable")
        }
        result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        result = result.replace(
            Regex("""public\s+CompoundTag\s+serializeNBT\s*\(\s*\)"""),
            "public CompoundTag serializeNBT(HolderLookup.Provider provider)"
        )
        result = result.replace(
            Regex("""public\s+void\s+deserializeNBT\s*\(\s*CompoundTag\s+(\w+)\s*\)""")
        ) { match ->
            "public void deserializeNBT(HolderLookup.Provider provider, CompoundTag ${match.groupValues[1]})"
        }
        if (result.contains("serializeNBT(HolderLookup.Provider provider)") &&
            !Regex("""@Override\s*\r?\n\s*public\s+CompoundTag\s+serializeNBT\(HolderLookup\.Provider provider\)""").containsMatchIn(result)
        ) {
            result = result.replace(
                "public CompoundTag serializeNBT(HolderLookup.Provider provider)",
                "@Override\n    public CompoundTag serializeNBT(HolderLookup.Provider provider)"
            )
        }
        if (result.contains("deserializeNBT(HolderLookup.Provider provider, CompoundTag") &&
            !Regex("""@Override\s*\r?\n\s*public\s+void\s+deserializeNBT\(HolderLookup\.Provider provider,""").containsMatchIn(result)
        ) {
            result = result.replace(
                Regex("""public\s+void\s+deserializeNBT\(HolderLookup\.Provider provider, CompoundTag\s+(\w+)\)"""),
                "@Override\n    public void deserializeNBT(HolderLookup.Provider provider, CompoundTag $1)"
            )
        }
        return result
    }

    private fun modIdReferenceForGeneratedClass(mainClass: Path?, mainText: String, generatedPackage: String): String {
        if (mainClass == null || mainText.isBlank()) {
            return detectModIdFromText(mainText)?.let { "\"$it\"" } ?: "\"modid\""
        }
        val mainPackage = packageNameOf(mainText)
        val className = mainClass.fileName.toString().removeSuffix(".java")
        val classRef = if (mainPackage.isBlank() || mainPackage == generatedPackage) {
            className
        } else {
            "$mainPackage.$className"
        }
        val constRef = Regex("""@Mod\s*\(\s*${Regex.escape(className)}\.(\w+)\s*\)""").find(mainText)
        if (constRef != null) {
            return "$classRef.${constRef.groupValues[1]}"
        }
        val directConst = Regex("""public\s+static\s+final\s+String\s+(MOD_ID|MODID)\s*=\s*"[^"]+"""").find(mainText)
        if (directConst != null) {
            return "$classRef.${directConst.groupValues[1]}"
        }
        return detectModIdFromText(mainText)?.let { "\"$it\"" } ?: "\"${mainPackage.substringAfterLast('.', "modid")}\""
    }

    private fun detectModIdFromText(text: String): String? {
        Regex("""@Mod\s*\(\s*"([^"]+)"\s*\)""").find(text)?.let { return it.groupValues[1] }
        val constRef = Regex("""@Mod\s*\(\s*\w+\.(\w+)\s*\)""").find(text)
        if (constRef != null) {
            Regex("""${Regex.escape(constRef.groupValues[1])}\s*=\s*"([^"]+)"""")
                .find(text)
                ?.let { return it.groupValues[1] }
        }
        return null
    }

    private data class AdvancementTriggerSpec(
        val namespace: String,
        val path: String
    ) {
        val fieldName: String
            get() = path.uppercase()
                .replace(Regex("""[^A-Z0-9]+"""), "_")
                .trim('_')
                .let { if (it.endsWith("_TRIGGER")) it else "${it}_TRIGGER" }
    }

    private fun migrateAdvancementCriterionTriggers(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return changes

        val javaFiles = Files.walk(srcDir)
            .filter { it.extension == "java" }
            .toList()

        changes.addAll(migrateLegacySimpleCriterionTriggers(projectDir, javaFiles, dryRun))

        val triggerFile = javaFiles.firstOrNull { file ->
            val text = file.readText()
            file.fileName.toString() == "AdvancementTrigger.java" &&
                text.contains("class AdvancementTrigger") &&
                text.contains("CriterionTrigger") &&
                (text.contains("createInstance") ||
                    text.contains("serializeToJson") ||
                    text.contains("SerializationContext") ||
                    text.contains("DeserializationContext") ||
                    text.contains("getCriterion()") ||
                    text.contains("getId()"))
        }

        if (triggerFile != null) {
            val triggerText = triggerFile.readText()
            val packageName = packageNameOf(triggerText)
            val migrated = advancementTriggerCodecSource(packageName)
            if (triggerText != migrated) {
                if (!dryRun) {
                    triggerFile.writeText(migrated)
                }
                changes.add(Change(
                    file = triggerFile,
                    line = 1,
                    description = "Migrate custom advancement trigger to the 1.21 codec CriterionTrigger API",
                    before = "getId/createInstance/serializeToJson legacy trigger",
                    after = "codec() + CriterionTriggerInstance.validate",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-advancement-trigger-codec"
                ))
            }
        }

        val registrarFile = javaFiles.firstOrNull { file ->
            val text = file.readText()
            file.fileName.toString() == "ExtraEventsRegister.java" &&
                text.contains("AdvancementTrigger") &&
                (text.contains("CriteriaTriggers.register") || text.contains("new AdvancementTrigger"))
        } ?: return changes

        val registrarText = registrarFile.readText()
        val specs = extractAdvancementTriggerSpecs(registrarText)
        if (specs.isEmpty()) return changes

        val mainClass = detectModMainClass(projectDir)
        val mainText = mainClass?.readText().orEmpty()
        val registrarPackage = packageNameOf(registrarText)
        val triggerPackage = triggerFile?.readText()?.let { packageNameOf(it) }
            ?: javaFiles.firstOrNull { it.fileName.toString() == "AdvancementTrigger.java" }
                ?.readText()
                ?.let { packageNameOf(it) }
            ?: registrarPackage.substringBeforeLast('.', registrarPackage) + ".advancements"
        val modRef = modIdReferenceForGeneratedClass(mainClass, mainText, registrarPackage)
        val migratedRegistrar = extraEventsRegisterAdvancementSource(
            packageName = registrarPackage,
            triggerPackage = triggerPackage,
            modRef = modRef,
            specs = specs
        )

        if (registrarText != migratedRegistrar) {
            if (!dryRun) {
                registrarFile.writeText(migratedRegistrar)
            }
            changes.add(Change(
                file = registrarFile,
                line = 1,
                description = "Register custom advancement triggers through DeferredRegister",
                before = "CriteriaTriggers.register(new AdvancementTrigger(...))",
                after = "DeferredRegister<CriterionTrigger<?>> TRIGGERS",
                confidence = Confidence.HIGH,
                ruleId = "struct-advancement-trigger-deferred-register"
            ))
        }

        if (mainClass != null && mainText.isNotBlank() && !mainText.contains("ExtraEventsRegister.register(")) {
            var migratedMain = mainText
            val mainPackage = packageNameOf(migratedMain)
            val constructorBusName = Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)""")
                .find(migratedMain)
                ?.groupValues
                ?.get(1)
                ?: "modEventBus"

            if (registrarPackage != mainPackage) {
                migratedMain = addImportIfMissing(migratedMain, "$registrarPackage.ExtraEventsRegister")
            }
            val registration = "        ExtraEventsRegister.register($constructorBusName);"
            migratedMain = insertModBusListener(migratedMain, constructorBusName, registration, "EntityRegister")
            if (migratedMain != mainText) {
                if (!dryRun) {
                    mainClass.writeText(migratedMain)
                }
                changes.add(Change(
                    file = mainClass,
                    line = 1,
                    description = "Register ExtraEventsRegister on the mod event bus",
                    before = "(no ExtraEventsRegister.register call)",
                    after = "ExtraEventsRegister.register($constructorBusName)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-advancement-trigger-main-register"
                ))
            }
        }

        return changes
    }

    private fun extractAdvancementTriggerSpecs(source: String): List<AdvancementTriggerSpec> {
        val pattern = Regex("""new\s+AdvancementTrigger\s*\(\s*"([^"]+)"\s*,\s*"([^"]+)"\s*\)""")
        return pattern.findAll(source)
            .map { AdvancementTriggerSpec(it.groupValues[1], it.groupValues[2]) }
            .distinct()
            .toList()
    }

    private data class LegacyCriterionRegistration(
        val registryFile: Path,
        val registryPackage: String,
        val registryClassName: String,
        val fieldName: String,
        val triggerClassName: String,
        val triggerPath: String
    )

    private fun migrateLegacySimpleCriterionTriggers(
        projectDir: Path,
        javaFiles: List<Path>,
        dryRun: Boolean
    ): List<Change> {
        val changes = mutableListOf<Change>()
        val registrationPattern = Regex(
            """(?m)^([ \t]*)public\s+static\s+final\s+[\w.$<>?]+\s+(\w+)\s*=\s*CriteriaTriggers\.register\s*\(\s*new\s+(\w+)\s*\(\s*\)\s*\)\s*;\s*$"""
        )
        val singletonRegistrationPattern = Regex(
            """(?m)^([ \t]*)CriteriaTriggers\.register\s*\(\s*(\w+)\.INSTANCE\s*\)\s*;\s*$"""
        )
        val triggerSources = javaFiles.associateBy { it.fileName.toString().removeSuffix(".java") }
        val registrations = javaFiles.flatMap { javaFile ->
            val text = javaFile.readText()
            if (!text.contains("CriteriaTriggers.register(")) return@flatMap emptyList()
            val registryPackage = packageNameOf(text)
            val registryClassName = Regex("""\bclass\s+(\w+)\b""")
                .find(text)
                ?.groupValues
                ?.get(1)
                ?: return@flatMap emptyList()
            val fieldRegistrations = registrationPattern.findAll(text).map { match ->
                val triggerClassName = match.groupValues[3]
                LegacyCriterionRegistration(
                    registryFile = javaFile,
                    registryPackage = registryPackage,
                    registryClassName = registryClassName,
                    fieldName = match.groupValues[2],
                    triggerClassName = triggerClassName,
                    triggerPath = triggerSources[triggerClassName]
                        ?.readText()
                        ?.let(::extractCriterionTriggerPath)
                        ?: criterionFieldToPath(match.groupValues[2])
                )
            }
            val singletonRegistrations = singletonRegistrationPattern.findAll(text).map { match ->
                val triggerClassName = match.groupValues[2]
                val triggerPath = triggerSources[triggerClassName]
                    ?.readText()
                    ?.let(::extractCriterionTriggerPath)
                    ?: criterionFieldToPath(triggerClassName.removeSuffix("Trigger"))
                LegacyCriterionRegistration(
                    registryFile = javaFile,
                    registryPackage = registryPackage,
                    registryClassName = registryClassName,
                    fieldName = criterionPathToField(triggerPath),
                    triggerClassName = triggerClassName,
                    triggerPath = triggerPath
                )
            }
            (fieldRegistrations + singletonRegistrations).toList().distinctBy { it.triggerClassName }
        }
        if (registrations.isEmpty()) return changes

        registrations.groupBy { it.registryFile }.forEach { (registryFile, fileRegistrations) ->
            val original = registryFile.readText()
            val migrated = migrateLegacyCriterionRegistrySource(projectDir, original, fileRegistrations)
            if (migrated != original) {
                if (!dryRun) registryFile.writeText(migrated)
                changes.add(Change(
                    file = registryFile,
                    line = 1,
                    description = "Migrate CriteriaTriggers.register fields to DeferredRegister trigger types",
                    before = "CriteriaTriggers.register(new Trigger())",
                    after = "DeferredHolder<CriterionTrigger<?>, Trigger>",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-criterion-trigger-deferred-register"
                ))
            }
        }

        for (registration in registrations) {
            val triggerFile = triggerSources[registration.triggerClassName] ?: continue
            val original = triggerFile.readText()
            if (!original.contains("SimpleCriterionTrigger") ||
                (!original.contains("createInstance") && !original.contains("SimpleCriterionTrigger.SimpleInstance") && !original.contains("AbstractCriterionTriggerInstance"))) {
                continue
            }
            val migrated = migrateLegacySimpleCriterionTriggerSource(original, registration) ?: continue
            if (migrated != original) {
                if (!dryRun) triggerFile.writeText(migrated)
                changes.add(Change(
                    file = triggerFile,
                    line = 1,
                    description = "Migrate legacy SimpleCriterionTrigger to the 1.21 codec trigger API",
                    before = "getId/createInstance/SimpleInstance class",
                    after = "codec() + record SimpleInstance",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-simple-criterion-trigger-codec"
                ))
            }
        }

        val registryGroups = registrations.groupBy { it.registryClassName }
        for (javaFile in javaFiles) {
            val original = javaFile.readText()
            var text = original
            for ((registryClassName, refs) in registryGroups) {
                val fieldAlternation = refs.joinToString("|") { Regex.escape(it.fieldName) }
                text = Regex("""\b${Regex.escape(registryClassName)}\.($fieldAlternation)\.trigger\s*\(""")
                    .replace(text) { match -> "${registryClassName}.${match.groupValues[1]}.get().trigger(" }
                text = Regex("""(?m)^[ \t]*${Regex.escape(registryClassName)}\.init\s*\(\s*\)\s*;\s*\r?\n?""")
                    .replace(text, "")
            }
            if (text != original) {
                if (!dryRun) javaFile.writeText(text)
                changes.add(Change(
                    file = javaFile,
                    line = 1,
                    description = "Dereference DeferredHolder advancement triggers before firing",
                    before = "AdvancementRegistry.FIELD.trigger(...)",
                    after = "AdvancementRegistry.FIELD.get().trigger(...)",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-criterion-trigger-holder-get"
                ))
            }
        }

        registerCriterionRegistriesOnModBus(projectDir, registrations, dryRun)?.let { changes.add(it) }

        return changes
    }

    private fun migrateLegacyCriterionRegistrySource(
        projectDir: Path,
        source: String,
        registrations: List<LegacyCriterionRegistration>
    ): String {
        var text = source
        val mainClass = detectModMainClass(projectDir)
        val mainText = mainClass?.readText().orEmpty()
        val modRef = modIdReferenceForGeneratedClass(mainClass, mainText, registrations.first().registryPackage)
        val registryClassName = registrations.first().registryClassName
        text = removeImportIfPresent(text, "net.minecraft.advancements.CriteriaTriggers")
        text = addImportIfMissing(text, "net.minecraft.advancements.CriterionTrigger")
        text = addImportIfMissing(text, "net.minecraft.core.registries.Registries")
        text = addImportIfMissing(text, "net.neoforged.neoforge.registries.DeferredHolder")
        text = addImportIfMissing(text, "net.neoforged.neoforge.registries.DeferredRegister")
        if (!text.contains("DeferredRegister<CriterionTrigger<?>> TRIGGERS")) {
            val classOpen = Regex("""public\s+class\s+${Regex.escape(registryClassName)}\s*\{\s*""").find(text)
            if (classOpen != null) {
                val insertPos = classOpen.range.last + 1
                text = text.substring(0, insertPos) +
                    "\n    public static final DeferredRegister<CriterionTrigger<?>> TRIGGERS = DeferredRegister.create(Registries.TRIGGER_TYPE, $modRef);\n" +
                    text.substring(insertPos)
            }
        }
        for (registration in registrations) {
            val fieldPattern = Regex(
                """(?m)^([ \t]*)public\s+static\s+final\s+[\w.$<>?]+\s+${Regex.escape(registration.fieldName)}\s*=\s*CriteriaTriggers\.register\s*\(\s*new\s+${Regex.escape(registration.triggerClassName)}\s*\(\s*\)\s*\)\s*;\s*$"""
            )
            text = fieldPattern.replace(text) { match ->
                val indent = match.groupValues[1]
                "${indent}public static final DeferredHolder<CriterionTrigger<?>, ${registration.triggerClassName}> ${registration.fieldName} = TRIGGERS.register(\"${registration.triggerPath}\", ${registration.triggerClassName}::new);"
            }
            if (!Regex("""\b${Regex.escape(registration.fieldName)}\b\s*=""").containsMatchIn(text)) {
                val triggerRegister = Regex(
                    """(?m)^([ \t]*)public\s+static\s+final\s+DeferredRegister<CriterionTrigger<\?>>\s+TRIGGERS\s*=\s*[^;\r\n]+;\s*$"""
                ).find(text)
                if (triggerRegister != null) {
                    val indent = triggerRegister.groupValues[1]
                    val insertPos = triggerRegister.range.last + 1
                    val fieldLine = "\n${indent}public static final DeferredHolder<CriterionTrigger<?>, ${registration.triggerClassName}> ${registration.fieldName} = TRIGGERS.register(\"${registration.triggerPath}\", ${registration.triggerClassName}::new);"
                    text = text.substring(0, insertPos) + fieldLine + text.substring(insertPos)
                }
            }
            text = Regex(
                """(?m)^[ \t]*CriteriaTriggers\.register\s*\(\s*${Regex.escape(registration.triggerClassName)}\.INSTANCE\s*\)\s*;\s*\r?\n?"""
            ).replace(text, "")
        }
        text = Regex("""(?s)\n[ \t]*public\s+static\s+void\s+init\s*\(\s*\)\s*\{\s*}\s*""")
            .replace(text, "\n")
        return text
    }

    private fun registerCriterionRegistriesOnModBus(
        projectDir: Path,
        registrations: List<LegacyCriterionRegistration>,
        dryRun: Boolean
    ): Change? {
        val mainClass = detectModMainClass(projectDir) ?: return null
        val original = mainClass.readText()
        var text = original
        val mainPackage = packageNameOf(text)
        val constructorBusName = Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)""")
            .find(text)
            ?.groupValues
            ?.get(1)
            ?: Regex("""\bIEventBus\s+(\w+)\s*=""")
                .find(text)
                ?.groupValues
                ?.get(1)
            ?: "modEventBus"
        for ((registryFile, fileRegistrations) in registrations.groupBy { it.registryFile }) {
            val first = fileRegistrations.first()
            val classRef = if (first.registryPackage == mainPackage) {
                first.registryClassName
            } else {
                text = addImportIfMissing(text, "${first.registryPackage}.${first.registryClassName}")
                first.registryClassName
            }
            val registrationLine = "        $classRef.TRIGGERS.register($constructorBusName);"
            if (!text.contains("$classRef.TRIGGERS.register(")) {
                text = insertModBusListener(text, constructorBusName, registrationLine, first.registryClassName)
            }
            // Keep registryFile referenced so grouping is deterministic even if only one registry exists.
            registryFile.fileName
        }
        if (text == original) return null
        if (!dryRun) mainClass.writeText(text)
        return Change(
            file = mainClass,
            line = 1,
            description = "Register advancement trigger DeferredRegister on the mod event bus",
            before = "(CriteriaTriggers static registration)",
            after = "AdvancementRegistry.TRIGGERS.register(modEventBus)",
            confidence = Confidence.HIGH,
            ruleId = "struct-criterion-trigger-main-register"
        )
    }

    private data class LegacyConditionCodecRegistration(
        val registerFile: Path,
        val conditionFile: Path,
        val conditionPackage: String,
        val conditionClassName: String,
        val registryIdExpression: String,
        val fieldName: String
    )

    private fun migrateLegacyConditionCodecRegistrations(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val javaFiles = Files.walk(srcDir).filter { it.toString().endsWith(".java") }.toList()
        val conditionFiles = javaFiles.mapNotNull { file ->
            val text = file.readText()
            val className = classNameOfJavaSource(text) ?: return@mapNotNull null
            if (text.contains("implements ICondition") && text.contains("MapCodec<") && text.contains("CODEC")) {
                className to file
            } else {
                null
            }
        }.toMap()

        val registerPattern = Regex("""CraftingHelper\.register\s*\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.Serializer\.INSTANCE\s*\)\s*;?""")
        val registrations = javaFiles.flatMap { file ->
            val text = file.readText()
            if (!text.contains("CraftingHelper.register(")) return@flatMap emptyList()
            registerPattern.findAll(text).mapNotNull { match ->
                val rawClassRef = match.groupValues[1]
                val className = rawClassRef.substringAfterLast('.')
                val conditionFile = conditionFiles[className] ?: return@mapNotNull null
                val conditionText = conditionFile.readText()
                val conditionPackage = packageNameOf(conditionText)
                LegacyConditionCodecRegistration(
                    registerFile = file,
                    conditionFile = conditionFile,
                    conditionPackage = conditionPackage,
                    conditionClassName = className,
                    registryIdExpression = if (conditionText.contains("CONDITION_ID")) "$className.CONDITION_ID" else "\"${classNameToPath(className.removeSuffix("Condition"))}\"",
                    fieldName = classNameToConstant(className)
                )
            }.toList()
        }
        if (registrations.isEmpty()) return emptyList()

        val changes = mutableListOf<Change>()
        val registryFile = selectConditionCodecRegistryFile(javaFiles) ?: detectModMainClass(projectDir) ?: return emptyList()
        val registryOriginal = registryFile.readText()
        val registryClassName = classNameOfJavaSource(registryOriginal) ?: return emptyList()
        val registryPackage = packageNameOf(registryOriginal)
        val mainClass = detectModMainClass(projectDir)
        val mainText = mainClass?.readText().orEmpty()
        val modRef = modIdReferenceForGeneratedClass(mainClass, mainText, registryPackage)
        val registryMigrated = migrateConditionCodecRegistrySource(
            registryOriginal,
            registryClassName,
            registryPackage,
            modRef,
            registrations
        )
        if (registryMigrated != registryOriginal) {
            if (!dryRun) registryFile.writeText(registryMigrated)
            changes.add(Change(
                file = registryFile,
                line = 1,
                description = "Register legacy recipe condition codecs through DeferredRegister",
                before = "CraftingHelper.register(Condition.Serializer.INSTANCE)",
                after = "DeferredRegister<MapCodec<? extends ICondition>> CONDITION_CODECS",
                confidence = Confidence.HIGH,
                ruleId = "struct-condition-codec-deferred-register"
            ))
        }

        migrateConditionCodecMainRegistration(
            projectDir,
            registryPackage,
            registryClassName,
            dryRun
        )?.let { changes.add(it) }

        registrations.map { it.registerFile }.distinct().forEach { registerFile ->
            val original = registerFile.readText()
            val migrated = removeLegacyCraftingHelperConditionRegistration(original)
            if (migrated != original) {
                if (!dryRun) registerFile.writeText(migrated)
                changes.add(Change(
                    file = registerFile,
                    line = 1,
                    description = "Remove obsolete CraftingHelper recipe condition serializer registration after codec registry migration",
                    before = "CraftingHelper.register(Condition.Serializer.INSTANCE)",
                    after = "Condition codec DeferredRegister entry",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-condition-codec-remove-craftinghelper-register"
                ))
            }
        }

        return changes
    }

    private fun selectConditionCodecRegistryFile(javaFiles: List<Path>): Path? =
        javaFiles.firstOrNull { file ->
            val text = file.readText()
            text.contains("DeferredRegister<") &&
                (text.contains("LootItemConditionType") || text.contains("LootItemFunctionType") || text.contains("CONDITION_CODECS"))
        }

    private fun migrateConditionCodecRegistrySource(
        source: String,
        registryClassName: String,
        registryPackage: String,
        modRef: String,
        registrations: List<LegacyConditionCodecRegistration>
    ): String {
        var text = source
        text = addImportIfMissing(text, "com.mojang.serialization.MapCodec")
        text = addImportIfMissing(text, "net.neoforged.neoforge.common.conditions.ICondition")
        text = addImportIfMissing(text, "net.neoforged.neoforge.registries.DeferredHolder")
        text = addImportIfMissing(text, "net.neoforged.neoforge.registries.DeferredRegister")
        text = addImportIfMissing(text, "net.neoforged.neoforge.registries.NeoForgeRegistries")
        for (registration in registrations) {
            if (registration.conditionPackage.isNotBlank() && registration.conditionPackage != registryPackage) {
                text = addImportIfMissing(text, "${registration.conditionPackage}.${registration.conditionClassName}")
            }
        }

        if (!text.contains("DeferredRegister<MapCodec<? extends ICondition>> CONDITION_CODECS")) {
            val classOpen = Regex("""public\s+(?:final\s+)?class\s+${Regex.escape(registryClassName)}\s*\{\s*""").find(text)
            if (classOpen != null) {
                val insertPos = classOpen.range.last + 1
                text = text.substring(0, insertPos) +
                    "\n    public static final DeferredRegister<MapCodec<? extends ICondition>> CONDITION_CODECS = DeferredRegister.create(NeoForgeRegistries.Keys.CONDITION_CODECS, $modRef);\n" +
                    text.substring(insertPos)
            }
        }

        for (registration in registrations) {
            if (Regex("""\b${Regex.escape(registration.fieldName)}\b""").containsMatchIn(text)) continue
            val line = "    public static final DeferredHolder<MapCodec<? extends ICondition>, MapCodec<${registration.conditionClassName}>> ${registration.fieldName} = CONDITION_CODECS.register(${registration.registryIdExpression}, () -> ${registration.conditionClassName}.CODEC);\n"
            val conditionCodecRegister = Regex(
                """(?m)^[ \t]*public\s+static\s+final\s+DeferredRegister<MapCodec<\? extends ICondition>>\s+CONDITION_CODECS\s*=\s*[^;\r\n]+;\s*$"""
            ).find(text)
            text = if (conditionCodecRegister != null) {
                val insertPos = conditionCodecRegister.range.last + 1
                text.substring(0, insertPos) + "\n" + line + text.substring(insertPos)
            } else {
                val classOpen = Regex("""public\s+(?:final\s+)?class\s+${Regex.escape(registryClassName)}\s*\{\s*""").find(text)
                if (classOpen != null) {
                    text.substring(0, classOpen.range.last + 1) + "\n" + line + text.substring(classOpen.range.last + 1)
                } else {
                    text
                }
            }
        }
        return text
    }

    private fun migrateConditionCodecMainRegistration(
        projectDir: Path,
        registryPackage: String,
        registryClassName: String,
        dryRun: Boolean
    ): Change? {
        val mainClass = detectModMainClass(projectDir) ?: return null
        val original = mainClass.readText()
        var text = original
        val mainPackage = packageNameOf(text)
        val constructorBusName = Regex("""public\s+\w+\s*\([^)]*\bIEventBus\s+(\w+)""")
            .find(text)
            ?.groupValues
            ?.get(1)
            ?: Regex("""\bIEventBus\s+(\w+)\s*=""")
                .find(text)
                ?.groupValues
                ?.get(1)
            ?: "modEventBus"
        val classRef = if (registryPackage == mainPackage || registryPackage.isBlank()) {
            registryClassName
        } else {
            text = addImportIfMissing(text, "$registryPackage.$registryClassName")
            registryClassName
        }
        if (!text.contains("$classRef.CONDITION_CODECS.register(")) {
            val registrationLine = "        $classRef.CONDITION_CODECS.register($constructorBusName);"
            text = insertModBusListener(text, constructorBusName, registrationLine, registryClassName)
        }
        if (text == original) return null
        if (!dryRun) mainClass.writeText(text)
        return Change(
            file = mainClass,
            line = 1,
            description = "Register recipe condition codec DeferredRegister on the mod event bus",
            before = "CraftingHelper.register condition serializer",
            after = "$classRef.CONDITION_CODECS.register($constructorBusName)",
            confidence = Confidence.HIGH,
            ruleId = "struct-condition-codec-main-register"
        )
    }

    private fun removeLegacyCraftingHelperConditionRegistration(source: String): String {
        var text = source
        text = Regex(
            """(?s)\s*else\s+if\s*\(\s*[A-Za-z_$][\w$]*\.getRegistryKey\(\)\.equals\(\s*Registries\.RECIPE_SERIALIZER\s*\)\s*\)\s*\{\s*CraftingHelper\.register\s*\(\s*[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.Serializer\.INSTANCE\s*\)\s*;\s*\}"""
        ).replace(text, "")
        text = Regex(
            """(?m)^[ \t]*CraftingHelper\.register\s*\(\s*[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.Serializer\.INSTANCE\s*\)\s*;\s*\r?\n"""
        ).replace(text, "")
        if (!text.contains("CraftingHelper.")) {
            text = removeImportIfPresent(text, "net.neoforged.neoforge.common.crafting.CraftingHelper")
            text = removeImportIfPresent(text, "net.minecraftforge.common.crafting.CraftingHelper")
        }
        return text
    }

    private fun classNameToConstant(className: String): String =
        className.replace(Regex("""([a-z0-9])([A-Z])"""), "$1_$2")
            .replace(Regex("""([A-Z])([A-Z][a-z])"""), "$1_$2")
            .uppercase()

    private fun classNameToPath(className: String): String =
        classNameToConstant(className).lowercase()

    private fun migrateLegacySimpleCriterionTriggerSource(
        source: String,
        registration: LegacyCriterionRegistration
    ): String? {
        val packageName = packageNameOf(source)
        val className = registration.triggerClassName
        val instanceName = Regex("""extends\s+SimpleCriterionTrigger\s*<\s*${Regex.escape(className)}\.(\w+)\s*>""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: Regex("""public\s+static\s+class\s+(\w+)\s+extends\s+(?:SimpleCriterionTrigger\.SimpleInstance|AbstractCriterionTriggerInstance)""")
                .find(source)
                ?.groupValues
                ?.get(1)
            ?: "Instance"
        val registryImport = if (registration.registryPackage == packageName) "" else "import ${registration.registryPackage}.${registration.registryClassName};\n"
        return when {
            source.contains("EntityPredicate.fromJson") && source.contains("hurt_entity") ->
                hurtBossCriterionTriggerSource(packageName, registryImport, className, instanceName, registration)
            source.contains("deserializeBug") || (source.contains("\"bug\"") && source.contains("BlockState")) ->
                blockCriterionTriggerSource(packageName, registryImport, className, instanceName, registration)
            source.contains("ItemPredicate.fromJson") ->
                itemCriterionTriggerSource(packageName, registryImport, className, instanceName, registration, source)
            source.contains("MinMaxBounds.Ints.fromJson") && source.contains("Potion") ->
                potionCriterionTriggerSource(packageName, registryImport, className, instanceName, registration)
            source.contains("\"structure\"") && source.contains("structureName") ->
                stringCriterionTriggerSource(packageName, registryImport, className, instanceName, registration)
            else -> {
                val factories = Regex("""public\s+static\s+${Regex.escape(instanceName)}\s+(\w+)\s*\(\s*\)""")
                    .findAll(source)
                    .map { it.groupValues[1] }
                    .distinct()
                    .toList()
                noArgCriterionTriggerSource(packageName, registryImport, className, instanceName, registration, factories)
            }
        }
    }

    private fun noArgCriterionTriggerSource(
        packageName: String,
        registryImport: String,
        className: String,
        instanceName: String,
        registration: LegacyCriterionRegistration,
        factories: List<String>
    ): String {
        val factoryMethods = factories.joinToString("\n\n") { methodName ->
            """
        public static Criterion<$className.$instanceName> $methodName() {
            return ${registration.registryClassName}.${registration.fieldName}.get().createCriterion(new $instanceName(Optional.empty()));
        }
""".trimEnd()
        }
        return """package $packageName;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.advancements.Criterion;
import net.minecraft.advancements.critereon.ContextAwarePredicate;
import net.minecraft.advancements.critereon.EntityPredicate;
import net.minecraft.advancements.critereon.SimpleCriterionTrigger;
import net.minecraft.server.level.ServerPlayer;
${registryImport}import java.util.Optional;

public class $className extends SimpleCriterionTrigger<$className.$instanceName> {

    @Override
    public Codec<$className.$instanceName> codec() {
        return $instanceName.CODEC;
    }

    public void trigger(ServerPlayer player) {
        this.trigger(player, instance -> true);
    }

    public record $instanceName(Optional<ContextAwarePredicate> player) implements SimpleInstance {
        public static final Codec<$className.$instanceName> CODEC = RecordCodecBuilder.create(instance -> instance.group(
                EntityPredicate.ADVANCEMENT_CODEC.optionalFieldOf("player").forGetter($className.$instanceName::player))
            .apply(instance, $className.$instanceName::new));

$factoryMethods
    }
}
"""
    }

    private fun hurtBossCriterionTriggerSource(
        packageName: String,
        registryImport: String,
        className: String,
        instanceName: String,
        registration: LegacyCriterionRegistration
    ): String = """package $packageName;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.advancements.Criterion;
import net.minecraft.advancements.critereon.ContextAwarePredicate;
import net.minecraft.advancements.critereon.EntityPredicate;
import net.minecraft.advancements.critereon.SimpleCriterionTrigger;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.level.storage.loot.LootContext;
${registryImport}import java.util.Optional;

public class $className extends SimpleCriterionTrigger<$className.$instanceName> {

    @Override
    public Codec<$className.$instanceName> codec() {
        return $instanceName.CODEC;
    }

    public void trigger(ServerPlayer player, Entity hurt) {
        LootContext entity = EntityPredicate.createContext(player, hurt);
        this.trigger(player, instance -> instance.matches(entity));
    }

    public record $instanceName(Optional<ContextAwarePredicate> player, Optional<ContextAwarePredicate> hurt) implements SimpleInstance {
        public static final Codec<$className.$instanceName> CODEC = RecordCodecBuilder.create(instance -> instance.group(
                EntityPredicate.ADVANCEMENT_CODEC.optionalFieldOf("player").forGetter($className.$instanceName::player),
                EntityPredicate.ADVANCEMENT_CODEC.optionalFieldOf("hurt_entity").forGetter($className.$instanceName::hurt))
            .apply(instance, $className.$instanceName::new));

        public boolean matches(LootContext hurt) {
            return this.hurt.isEmpty() || this.hurt.get().matches(hurt);
        }

        public static Criterion<$className.$instanceName> hurtBoss(EntityPredicate.Builder hurt) {
            return ${registration.registryClassName}.${registration.fieldName}.get().createCriterion(new $instanceName(Optional.empty(), Optional.of(EntityPredicate.wrap(hurt.build()))));
        }
    }
}
"""

    private fun blockCriterionTriggerSource(
