    private fun migrateMobEffectHolderCallsSource(source: String): String {
        if (!source.contains("MobEffect") &&
            !source.contains("hasEffect(") &&
            !source.contains("getEffect(") &&
            !source.contains("removeEffect(") &&
            !source.contains("addEffect(")
        ) return source

        val mobEffectVariables = Regex("""\bMobEffect\s+(\w+)\s*=""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()

        var result = source
        result = Regex("""(new\s+MobEffectInstance\s*\(\s*)((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$]+)\.get\(\)""")
            .replace(result, "$1$2")
        result = Regex("""(\.\s*(?:hasEffect|getEffect|removeEffect)\s*\(\s*)((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$]+)\.get\(\)(\s*\))""")
            .replace(result, "$1$2$3")
        for (variable in mobEffectVariables) {
            val varPattern = Regex.escape(variable)
            result = Regex("""(new\s+MobEffectInstance\s*\(\s*)$varPattern\b""")
                .replace(result, "$1BuiltInRegistries.MOB_EFFECT.wrapAsHolder($variable)")
            result = Regex("""(\.\s*(?:hasEffect|getEffect|removeEffect)\s*\(\s*)$varPattern(\s*\))""")
                .replace(result, "$1BuiltInRegistries.MOB_EFFECT.wrapAsHolder($variable)$2")
        }

        val holderParamNames = Regex(
            """(?m)^([ \t]*(?:public|private|protected)\s+(?:static\s+)?[\w<>\[\].?]+\s+\w+\s*\([^)]*)\bMobEffect\s+([A-Za-z_$][\w$]*)([^)]*\)\s*\{)"""
        )
            .findAll(result)
            .mapNotNull { match ->
                val paramName = match.groupValues[2]
                val paramPattern = Regex.escape(paramName)
                val passedToHolderApi =
                    Regex("""\b(?:hasEffect|getEffect|removeEffect)\s*\(\s*$paramPattern\s*\)""").containsMatchIn(result) ||
                        Regex("""new\s+MobEffectInstance\s*\(\s*$paramPattern\b""").containsMatchIn(result)
                if (passedToHolderApi) paramName else null
            }
            .toSet()

        if (holderParamNames.isNotEmpty()) {
            result = Regex(
                """(?m)^([ \t]*(?:public|private|protected)\s+(?:static\s+)?[\w<>\[\].?]+\s+\w+\s*\([^)]*)\bMobEffect\s+([A-Za-z_$][\w$]*)([^)]*\)\s*\{)"""
            ).replace(result) { match ->
                val paramName = match.groupValues[2]
                if (paramName in holderParamNames) {
                    "${match.groupValues[1]}Holder<MobEffect> $paramName${match.groupValues[3]}"
                } else {
                    match.value
                }
            }
            for (paramName in holderParamNames) {
                val paramPattern = Regex.escape(paramName)
                result = Regex("""\b$paramPattern\.getDescriptionId\(\)""")
                    .replace(result, "$paramName.value().getDescriptionId()")
                result = Regex("""\b$paramPattern\.getCategory\(\)""")
                    .replace(result, "$paramName.value().getCategory()")
            }
        }

        if (result != source) {
            if (mobEffectVariables.isNotEmpty()) {
                result = addImportIfMissing(result, "net.minecraft.core.registries.BuiltInRegistries")
            }
            if (holderParamNames.isNotEmpty()) {
                result = addImportIfMissing(result, "net.minecraft.core.Holder")
            }
        }
        return result
    }

    private fun migrateHolderValueAccessorsSource(source: String): String {
        var result = source
        result = result.replace(".getEffect().getDescriptionId()", ".getEffect().value().getDescriptionId()")
        result = Regex("""\.getEffect\(\)\s*([!=]=)\s*((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$]+)\.get\(\)""")
            .replace(result) { match -> ".getEffect().value() ${match.groupValues[1]} ${match.groupValues[2]}.get()" }
        val playerSkinVariables = Regex(
            """\b(?:net\.minecraft\.client\.player\.)?(?:AbstractClientPlayer|LocalPlayer|RemotePlayer)\s+([A-Za-z_$][\w$]*)\b"""
        ).findAll(result).map { it.groupValues[1] }.toSet()
        for (variable in playerSkinVariables) {
            result = result.replace("$variable.getModelName()", "$variable.getSkin().model().id()")
        }
        result = result.replace("MobEffect effect = effectHolder;", "MobEffect effect = effectHolder.value();")
        return result
    }

    private fun migrateCustomDataComponentsSource(source: String): String {
        var result = source

        if (result.contains("stack.getTagElement(") || result.contains("stack.removeTagKey(") ||
            result.contains("DataComponents.CUSTOM_DATA") && result.contains(".copyTag().getCompound(")) {
            result = result
                .replace(
                    "CompoundTag tag = stack.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA, net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getCompound(TAG_CUSTOM_FLUID);",
                    "CompoundTag tag = getCustomDataChild(stack, TAG_CUSTOM_FLUID);"
                )
                .replace("stack.getTagElement(", "getCustomDataChild(stack, ")
                .replace("stack.removeTagKey(", "removeCustomDataChild(stack, ")

            result = replaceMethodBody(result, "setFluidId", """
                public static void setFluidId(ItemStack stack, ResourceLocation fluidId) {
                    updateCustomDataChild(stack, TAG_CUSTOM_FLUID, tag -> {
                        tag.putString(TAG_FLUID_ID, fluidId.toString());

                        CustomFluidRegistry.getDefinition(fluidId).ifPresent(definition -> {
                            tag.putInt(TAG_FLUID_COLOR, definition.color());
                            tag.putString(TAG_FLUID_NAME, definition.getTranslationKey());
                        });
                    });
                }
            """.trimIndent())

            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
            result = addImportIfMissing(result, "net.minecraft.world.item.component.CustomData")
            result = addImportIfMissing(result, "java.util.function.Consumer")
            result = addItemStackCustomDataHelpers(result)
        }

        if (result.contains("FluidStack") &&
            (result.contains(".getOrCreateChildTag(") || result.contains(".getChildTag("))) {
            result = result
                .replace(Regex("""CompoundTag\s+(\w+)\s*=\s*stack\.getChildTag\(([^)]+)\);""")) { match ->
                    "CompoundTag ${match.groupValues[1]} = getFluidCustomDataChild(stack, ${match.groupValues[2]});"
                }

            result = replaceMethodBody(result, "setFluidId", """
                public static void setFluidId(FluidStack stack, ResourceLocation fluidId) {
                    if (stack == null || stack.isEmpty() || fluidId == null || !isDynamicCustomFluid(stack)) {
                        return;
                    }
                    updateFluidCustomDataChild(stack, CustomFluidNBTHelper.TAG_CUSTOM_FLUID, customFluidTag -> {
                        customFluidTag.putString(CustomFluidNBTHelper.TAG_FLUID_ID, fluidId.toString());
                    });
                }
            """.trimIndent())

            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
            result = addImportIfMissing(result, "net.minecraft.world.item.component.CustomData")
            result = addImportIfMissing(result, "java.util.function.Consumer")
            result = addFluidStackCustomDataHelpers(result)
        }

        return result
    }

    private fun addItemStackCustomDataHelpers(source: String): String {
        if (source.contains("getCustomDataChild(ItemStack stack")) return source
        val helpers = """

    private static CompoundTag getCustomDataChild(ItemStack stack, String key) {
        CompoundTag root = stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag();
        return root.contains(key) ? root.getCompound(key) : null;
    }

    private static void updateCustomDataChild(ItemStack stack, String key, Consumer<CompoundTag> updater) {
        CustomData.update(DataComponents.CUSTOM_DATA, stack, root -> {
            CompoundTag child = root.getCompound(key);
            updater.accept(child);
            if (child.isEmpty()) {
                root.remove(key);
            } else {
                root.put(key, child);
            }
        });
    }

    private static void removeCustomDataChild(ItemStack stack, String key) {
        CustomData.update(DataComponents.CUSTOM_DATA, stack, root -> root.remove(key));
    }
""".trimEnd()
        return insertBeforeLastClassBrace(source, helpers)
    }

    private fun addFluidStackCustomDataHelpers(source: String): String {
        if (source.contains("getFluidCustomDataChild(FluidStack stack")) return source
        val helpers = """

    private static CompoundTag getFluidCustomDataChild(FluidStack stack, String key) {
        CompoundTag root = stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag();
        return root.contains(key) ? root.getCompound(key) : null;
    }

    private static void updateFluidCustomDataChild(FluidStack stack, String key, Consumer<CompoundTag> updater) {
        CompoundTag root = stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag();
        CompoundTag child = root.getCompound(key);
        updater.accept(child);
        if (child.isEmpty()) {
            root.remove(key);
        } else {
            root.put(key, child);
        }
        if (root.isEmpty()) {
            stack.remove(DataComponents.CUSTOM_DATA);
        } else {
            stack.set(DataComponents.CUSTOM_DATA, CustomData.of(root));
        }
    }
""".trimEnd()
        return insertBeforeLastClassBrace(source, helpers)
    }

    private fun migrateBrewingRecipeRegistrationSource(source: String): String {
        if (!source.contains("BrewingRecipeRegistry.addRecipe(")) return source
        var result = source
        result = removeImport(result, "net.neoforged.neoforge.common.brewing.BrewingRecipeRegistry")
        result = addImportIfMissing(result, "net.neoforged.neoforge.event.brewing.RegisterBrewingRecipesEvent")

        result = result.replace("registerBrewingRecipes(event);", "")
        val migratedMethod = """
            @SubscribeEvent
            public void registerBrewingRecipes(final RegisterBrewingRecipesEvent event) {
                event.getBuilder().addRecipe(Ingredient.of(ItemRegister.HOT_WATER_BOTTLE.get()), Ingredient.of(Items.GUNPOWDER), ItemRegister.SPLASH_HOT_WATER_BOTTLE.get().getDefaultInstance());
                event.getBuilder().addRecipe(Ingredient.of(ItemRegister.HONEY_BATH_BOTTLE.get()), Ingredient.of(Items.GUNPOWDER), ItemRegister.SPLASH_HONEY_BATH_BOTTLE.get().getDefaultInstance());
                event.getBuilder().addRecipe(Ingredient.of(ItemRegister.MILK_BATH_BOTTLE.get()), Ingredient.of(Items.GUNPOWDER), ItemRegister.SPLASH_MILK_BATH_BOTTLE.get().getDefaultInstance());
                event.getBuilder().addRecipe(Ingredient.of(ItemRegister.HERBAL_BATH_BOTTLE.get()), Ingredient.of(Items.GUNPOWDER), ItemRegister.SPLASH_HERBAL_BATH_BOTTLE.get().getDefaultInstance());
                event.getBuilder().addRecipe(Ingredient.of(ItemRegister.PEONY_BATH_BOTTLE.get()), Ingredient.of(Items.GUNPOWDER), ItemRegister.SPLASH_PEONY_BATH_BOTTLE.get().getDefaultInstance());
                event.getBuilder().addRecipe(Ingredient.of(ItemRegister.ROSE_BATH_BOTTLE.get()), Ingredient.of(Items.GUNPOWDER), ItemRegister.SPLASH_ROSE_BATH_BOTTLE.get().getDefaultInstance());
                event.getBuilder().addRecipe(new CustomFluidBrewingRecipe());
            }
        """.trimIndent()
        result = replaceMethodBody(result, "registerBrewingRecipes", migratedMethod)
        result = Regex("""(?s)\n\s*/\*\s*@SubscribeEvent\s+public\s+void\s+onBrewingRecipeRegister.*?\*/""")
            .replace(result, "")
        return result
    }

    private fun migrateVanilla121ApiSource(
        source: String,
        mapCodecConstantOwners: Set<String> = emptySet(),
        codecConstantOwners: Set<String> = emptySet(),
        spriteSourceProviderClasses: Set<String> = emptySet(),
        finalMapDecorationClasses: Set<String> = emptySet(),
        lootTableProviderClasses: Set<String> = emptySet(),
