                }
            result = Regex("""\.normal\(\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^)]+)\)""")
                .replace(result) { match ->
                    ".setNormal(${match.groupValues[1].trim()}, ${match.groupValues[2].trim()}, ${match.groupValues[3].trim()})"
                }
            val helperSignature = Regex(
                """private\s+void\s+addVertex\([^)]*Matrix3f\s+([A-Za-z_$][\w$]*)[\s\S]*?float\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*int\s+packedLight"""
            ).find(result)
            if (helperSignature != null && !result.contains("transformedNormal")) {
                val normalParam = helperSignature.groupValues[1]
                val nxParam = helperSignature.groupValues[2]
                val nyParam = helperSignature.groupValues[3]
                val nzParam = helperSignature.groupValues[4]
                val setNormalCall = ".setNormal($normalParam, $nxParam, $nyParam, $nzParam)"
                if (result.contains(setNormalCall)) {
                    result = Regex("""(?m)^([ \t]*)builder\.addVertex\(""")
                        .replaceFirst(
                            result,
                            "$1org.joml.Vector3f transformedNormal = $normalParam.transform($nxParam, $nyParam, $nzParam, new org.joml.Vector3f());\n$1builder.addVertex("
                        )
                    result = result.replace(
                        setNormalCall,
                        ".setNormal(transformedNormal.x(), transformedNormal.y(), transformedNormal.z())"
                    )
                }
            }
        }

        if (result.contains("getMobType() == MobType.UNDEAD")) {
            result = Regex("""(\w+)\.getMobType\(\)\s*==\s*MobType\.UNDEAD""")
                .replace(result) { match -> "${match.groupValues[1]}.getType().is(EntityTypeTags.UNDEAD)" }
            result = removeImport(result, "net.minecraft.world.entity.MobType")
            needsEntityTypeTags = true
        }

        result = result
            .replace("AttributeModifier.Operation.ADDITION", "AttributeModifier.Operation.ADD_VALUE")
            .replace("AttributeModifier.Operation.MULTIPLY_TOTAL", "AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL")
            .replace("AttributeModifier.Operation.MULTIPLY_BASE", "AttributeModifier.Operation.ADD_MULTIPLIED_BASE")

        if (result.contains("Attribute attribute,")) {
            result = result.replace("Attribute attribute,", "Holder<Attribute> attribute,")
            needsHolder = true
        }
        result = result.replace("new AttributeModifier(uuid, modifierName.toString(), value, operation)", "new AttributeModifier(modifierName, value, operation)")
        result = Regex("""new\s+AttributeModifier\(\s*\w+\s*,\s*(\w+)\.toString\(\)\s*,\s*([^,]+)\s*,\s*([^)]+)\)""")
            .replace(result) { match ->
                "new AttributeModifier(${match.groupValues[1]}, ${match.groupValues[2].trim()}, ${match.groupValues[3].trim()})"
            }
        result = result.replace("attributeInstance.hasModifier(modifier)", "attributeInstance.hasModifier(modifier.id())")
        result = result.replace("attributeInstance.removeModifier(uuid)", "attributeInstance.removeModifier(modifierName)")

        result = Regex("""protected\s+float\s+getGravity\s*\(\s*\)""")
            .replace(result, "protected double getDefaultGravity()")

        if (result.contains("ParticleTypes.ENTITY_EFFECT")) {
            val particlePattern = Regex(
                """addParticle\(\s*ParticleTypes\.ENTITY_EFFECT\s*,\s*([^,\n]+(?:\([^)]*\))?(?:\s*\+\s*[^,\n]+)?),\s*([^,\n]+(?:\([^)]*\))?(?:\s*\+\s*[^,\n]+)?),\s*([^,\n]+(?:\([^)]*\))?(?:\s*\+\s*[^,\n]+)?),\s*([A-Za-z_][\w]*)\s*,\s*([A-Za-z_][\w]*)\s*,\s*([A-Za-z_][\w]*)\s*\)"""
            )
            result = particlePattern.replace(result) { match ->
                needsColorParticle = true
                "addParticle(ColorParticleOption.create(ParticleTypes.ENTITY_EFFECT, (float) ${match.groupValues[4]}, (float) ${match.groupValues[5]}, (float) ${match.groupValues[6]}), ${match.groupValues[1]}, ${match.groupValues[2]}, ${match.groupValues[3]}, 0.0D, 0.0D, 0.0D)"
            }
        }

        if (result.contains("extends AbstractItemModelProvider")) {
            result = result
                .replace("bushItem(item);", "itemBlockFlat(() -> blockItem.getBlock());")
                .replace("itemBlock(blockItem::getBlock);", "toBlock(() -> blockItem.getBlock());")
                .replace("normalItem(", "singleTex(")
        }

        if (result.contains("extends AbstractBlockStateProvider")) {
            result = Regex("""\blog\((BlockRegistry\.[A-Z0-9_]+)\);""")
                .replace(result) { match ->
                    needsDatagenSupplier = true
                    needsDatagenBlockHelpers = true
                    "log(${match.groupValues[1]}::get);"
                }
            result = Regex("""\bcrossBlock\((BlockRegistry\.[A-Z0-9_]+)\);""")
                .replace(result) { match ->
                    needsDatagenSupplier = true
                    "crossBlock(${match.groupValues[1]}::get);"
                }
            result = Regex("""\bstageBlock\((BlockRegistry\.[A-Z0-9_]+)\s*,""")
                .replace(result) { match ->
                    needsDatagenSupplier = true
                    needsDatagenBlockHelpers = true
                    "stageBlock(${match.groupValues[1]}::get,"
                }
            result = Regex("""\bfacingSlabBlock\((BlockRegistry\.[A-Z0-9_]+)\s*,""")
                .replace(result) { match ->
                    needsDatagenSupplier = true
                    needsDatagenBlockHelpers = true
                    "facingSlabBlock(${match.groupValues[1]}::get,"
                }
            if (needsDatagenBlockHelpers && !result.contains("private void stageBlock(Supplier<? extends Block>")) {
                result = insertBeforeLastClassBrace(result, legacyMmlibBlockStateHelpers())
            }
        }

        if (result.contains("part.render(poseStack, consumer, packedLight, OverlayTexture.NO_OVERLAY, r, g, b, alpha)")) {
            result = result.replace(
                "part.render(poseStack, consumer, packedLight, OverlayTexture.NO_OVERLAY, r, g, b, alpha)",
                "part.render(poseStack, consumer, packedLight, OverlayTexture.NO_OVERLAY, FastColor.ARGB32.colorFromFloat(alpha, r, g, b))"
            )
            needsFastColor = true
        }

        if (result.contains("event.getSkin(\"default\")") || result.contains("event.getSkin(\"slim\")")) {
            result = result
                .replace("event.getSkin(\"default\")", "event.getSkin(PlayerSkin.Model.WIDE)")
                .replace("event.getSkin(\"slim\")", "event.getSkin(PlayerSkin.Model.SLIM)")
            needsPlayerSkin = true
        }

        result = Regex("""new\s+MerchantOffer\(\s*new\s+ItemStack\((Items\.\w+),\s*(\d+)\),""")
            .replace(result) { match ->
                needsItemCost = true
                "new MerchantOffer(\n                                            new ItemCost(${match.groupValues[1]}, ${match.groupValues[2]}),"
            }

        if (result.contains("PotionUtils.")) {
            result = Regex("""(?:net\.minecraft\.world\.item\.alchemy\.)?PotionUtils\.setPotion\(([^,]+),\s*([^)]+)\)""")
                .replace(result) { match ->
                    "${match.groupValues[1].trim()}.set(DataComponents.POTION_CONTENTS, new PotionContents(${match.groupValues[2].trim()}))"
                }
            result = Regex("""(?:net\.minecraft\.world\.item\.alchemy\.)?PotionUtils\.getPotion\(([^)]+)\)""")
                .replace(result) { match ->
                    "${match.groupValues[1].trim()}.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY).potion().orElse(Potions.EMPTY)"
                }
            result = Regex("""(?:net\.minecraft\.world\.item\.alchemy\.)?PotionUtils\.getColor\(([^)]+)\)""")
                .replace(result) { match ->
                    "${match.groupValues[1].trim()}.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY).getColor()"
                }
            result = Regex("""(?:net\.minecraft\.world\.item\.alchemy\.)?PotionUtils\.getMobEffects\(([^)]+)\)\.isEmpty\(\)""")
                .replace(result) { match ->
                    "!${match.groupValues[1].trim()}.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY).getAllEffects().iterator().hasNext()"
                }
            result = Regex("""(?:net\.minecraft\.world\.item\.alchemy\.)?PotionUtils\.getMobEffects\(([^)]+)\)""")
                .replace(result) { match ->
                    "${match.groupValues[1].trim()}.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY).getAllEffects()"
                }
            result = Regex("""(?:net\.minecraft\.world\.item\.alchemy\.)?PotionUtils\.addPotionTooltip\(([^,]+),\s*([^,]+),\s*([^)]+)\)""")
                .replace(result) { match ->
                    "${match.groupValues[1].trim()}.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY).addPotionTooltip(${match.groupValues[2].trim()}::add, ${match.groupValues[3].trim()}, 20.0F)"
                }
            needsDataComponents = true
            needsPotionContents = true
            if (!result.contains("PotionUtils.")) {
                result = removeImport(result, "net.minecraft.world.item.alchemy.PotionUtils")
            }
        }
        if (result.contains("Potions.EMPTY") || result.contains("Potion.byName(") || result.contains("new PotionContents(")) {
            result = Regex("""new\s+PotionContents\(\s*Potions\.EMPTY\s*\)""")
                .replace(result, "PotionContents.EMPTY")
            result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*\([^)]*\))*\.getOrDefault\(DataComponents\.POTION_CONTENTS,\s*PotionContents\.EMPTY\))\.potion\(\)\.orElse\(Potions\.EMPTY\)\s*!=\s*Potions\.EMPTY""")
                .replace(result) { match -> "${match.groupValues[1]}.potion().isPresent()" }
            result = Regex("""([A-Za-z_$][\w$]*)\.getString\("Potion"\)\.equals\(Potions\.EMPTY\.toString\(\)\)""")
                .replace(result) { match -> "\"minecraft:empty\".equals(${match.groupValues[1]}.getString(\"Potion\"))" }
            result = Regex("""Potion\.byName\(\s*([^)]+)\s*\)""")
                .replace(result) { match ->
                    "net.minecraft.core.registries.BuiltInRegistries.POTION.get(net.minecraft.resources.ResourceLocation.parse(${match.groupValues[1].trim()}))"
                }
            result = result.replace("Potions.EMPTY.value()", "Potions.WATER.value()")
            result = result.replace("Potions.EMPTY", "Potions.WATER.value()")
            result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*\([^)]*\))*\.getOrDefault\(DataComponents\.POTION_CONTENTS,\s*PotionContents\.EMPTY\))\.potion\(\)\.orElse\(Potions\.WATER\.value\(\)\)\s*!=\s*Potions\.WATER\.value\(\)""")
                .replace(result) { match -> "${match.groupValues[1]}.potion().isPresent()" }
            if (result.contains("PotionContents.EMPTY")) {
                needsPotionContents = true
            }
        }

        result = Regex("""\bthis\.has\(\s*(DataComponents\.[A-Z0-9_]+|net\.minecraft\.core\.component\.DataComponents\.[A-Z0-9_]+)\s*\)""")
            .replace(result) { match ->
                if (result.contains("UseOnContext context")) {
                    "context.getItemInHand().has(${match.groupValues[1]})"
                } else {
                    match.value
                }
            }
        result = Regex("""\bthis\.getUseDuration\(\s*stack\s*\)""")
            .replace(result) {
                if (result.contains("LivingEntity living")) {
                    "this.getUseDuration(stack, living)"
                } else if (result.contains("LivingEntity entity")) {
                    "this.getUseDuration(stack, entity)"
                } else {
                    it.value
                }
            }
        result = result.replace(".restore(true, false)", ".restore()")

        result = Regex(
            """public\s+@NotNull\s+ItemStack\s+pickupBlock\(@NotNull\s+LevelAccessor\s+level,\s*@NotNull\s+BlockPos\s+pos,\s*@NotNull\s+BlockState\s+state\)"""
        ).replace(result) {
            needsNullable = true
            "public @NotNull ItemStack pickupBlock(@Nullable Player player, @NotNull LevelAccessor level, @NotNull BlockPos pos, @NotNull BlockState state)"
        }
        result = result.replace("super.pickupBlock(level, pos, state)", "super.pickupBlock(player, level, pos, state)")
        if (needsNullable) {
            if (!result.contains("import org.jetbrains.annotations.Nullable;")) {
                result = addImportIfMissing(result, "javax.annotation.Nullable")
            }
            result = addImportIfMissing(result, "net.minecraft.world.entity.player.Player")
        }

        result = Regex("""(\w+)\.getCapability\(DirtinessCapability\.DIRTINESS\)\.ifPresent\(data\s*->\s*\{\s*(.*?)\s*\}\);""", RegexOption.DOT_MATCHES_ALL)
            .replace(result) { match ->
                val playerName = match.groupValues[1]
                val body = match.groupValues[2].trimIndent()
                "DirtinessData data = DirtinessCapability.getOrNull($playerName);\n                        if (data != null) {\n                            $body\n                        }"
            }
        if (result != source && result.contains("DirtinessData data = DirtinessCapability.getOrNull(")) {
            val dirtinessDataImport = Regex("""(?m)^[ \t]*import\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.DirtinessCapability;\s*$""")
                .find(result)
                ?.groupValues
                ?.get(1)
                ?.let { "$it.DirtinessData" }
            if (dirtinessDataImport != null) {
                result = addImportIfMissing(result, dirtinessDataImport)
            }
        }

        result = migrateJava21StrictWarningSource(result)

        if (needsEntityTypeTags) result = addImportIfMissing(result, "net.minecraft.tags.EntityTypeTags")
        if (needsHolder) result = addImportIfMissing(result, "net.minecraft.core.Holder")
        if (result.contains("Holder<Attribute>")) result = addImportIfMissing(result, "net.minecraft.world.entity.ai.attributes.Attribute")
        if (needsColorParticle) result = addImportIfMissing(result, "net.minecraft.core.particles.ColorParticleOption")
        if (needsFastColor) result = addImportIfMissing(result, "net.minecraft.util.FastColor")
        if (needsPlayerSkin) result = addImportIfMissing(result, "net.minecraft.client.resources.PlayerSkin")
        if (needsItemCost) result = addImportIfMissing(result, "net.minecraft.world.item.trading.ItemCost")
        if (needsDataComponents || result.contains("DataComponents.FOOD")) result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        if (needsPotionContents) result = addImportIfMissing(result, "net.minecraft.world.item.alchemy.PotionContents")
        if (needsItemTooltipContext || result.contains("Item.TooltipContext")) result = addImportIfMissing(result, "net.minecraft.world.item.Item")
        if (needsOverlayTexture || result.contains("OverlayTexture.")) {
            result = addImportIfMissing(result, "net.minecraft.client.renderer.texture.OverlayTexture")
        }
        if (needsRandomSource) result = addImportIfMissing(result, "net.minecraft.util.RandomSource")
        if (needsServerLevel) result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        if (needsVanillaEnchantmentProviders) result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.providers.VanillaEnchantmentProviders")
        if (needsEnchantmentEffectComponents) result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.EnchantmentEffectComponents")
        if (needsDatagenSupplier) result = addImportIfMissing(result, "java.util.function.Supplier")
        if (needsRegistryFriendlyByteBuf) result = addImportIfMissing(result, "net.minecraft.network.RegistryFriendlyByteBuf")
        if (needsEntityWithComplexSpawn) result = addImportIfMissing(result, "net.neoforged.neoforge.entity.IEntityWithComplexSpawn")
        if (needsDatagenBlockHelpers) {
            result = addImportIfMissing(result, "net.minecraft.world.level.block.RotatedPillarBlock")
            result = addImportIfMissing(result, "net.minecraft.world.level.block.state.properties.IntegerProperty")
            result = addImportIfMissing(result, "net.minecraft.world.level.block.state.properties.Property")
            result = addImportIfMissing(result, "net.minecraft.world.level.block.state.properties.SlabType")
            result = addImportIfMissing(result, "net.neoforged.neoforge.client.model.generators.ConfiguredModel")
            result = addImportIfMissing(result, "net.neoforged.neoforge.client.model.generators.ModelFile")
        }
        val withoutAttributeImport = removeImport(result, "net.minecraft.world.entity.ai.attributes.Attribute")
        result = if (hasSimpleTypeReference(withoutAttributeImport, "Attribute")) {
            addImportIfMissing(result, "net.minecraft.world.entity.ai.attributes.Attribute")
        } else {
            withoutAttributeImport
        }
        if (result.contains("@Nullable") &&
            !result.contains("import org.jetbrains.annotations.Nullable;") &&
            !result.contains("import javax.annotation.Nullable;")) {
            result = addImportIfMissing(result, "javax.annotation.Nullable")
        }
        if (result.contains("import org.jetbrains.annotations.Nullable;") && result.contains("import javax.annotation.Nullable;")) {
            result = removeImport(result, "javax.annotation.Nullable")
        }
        return result
    }

    private fun migrateJava21StrictWarningSource(source: String): String {
        var result = source
        result = migrateRedundantJava21Casts(result)
        result = migrateBlockDefaultStateThisEscapeWarning(result)
        result = migrateConstructorThisMethodThisEscapeWarning(result)
        result = migrateFieldInitializerThisMethodThisEscapeWarning(result)
        result = migrateClassLevelThisEscapeFallback(result)
        result = migrateCuriosHelperRemovalApis(result)
        result = migrateJeiRecipeCategoryBackgroundApi(result)
        result = migrateRequiredRemovalWarningAnnotations(result)
        result = migrateMthTrigonometryFloatArguments(result)
        return result
    }

    private fun migrateRedundantJava21Casts(source: String): String {
        var result = source
        val floatVariables = Regex("""\bfloat\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in floatVariables) {
            result = Regex("""\(float\)\s+${Regex.escape(variable)}\b""")
                .replace(result, variable)
        }

        val livingEntityVariables = Regex("""\bLivingEntity\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in livingEntityVariables) {
            result = Regex("""\(\s*\(\s*LivingEntity\s*\)\s*${Regex.escape(variable)}\s*\)""")
                .replace(result, variable)
        }

        if (result.contains("Vector3f")) {
            val vectorVariables = Regex("""\b(?:org\.joml\.)?Vector3f\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
            val vectorArrays = Regex("""\b(?:org\.joml\.)?Vector3f\s*\[\s*]\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
            val vectorReceivers = (vectorVariables + vectorArrays).joinToString("|") { Regex.escape(it) }
            if (vectorReceivers.isNotBlank()) {
                result = Regex("""\(float\)\s*\(\s*(($vectorReceivers)(?:\s*\[[^]]+])?\.(?:x|y|z)\(\))\s*\)""")
                    .replace(result) { match -> match.groupValues[1] }
            }
        }

        return result
    }

    private fun migrateBlockDefaultStateThisEscapeWarning(source: String): String {
        if (!source.contains("registerDefaultState(this.getStateDefinition()")) return source
        val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return source
        return addSuppressWarningToConstructorsContaining(
            source,
            className,
            "this-escape",
            listOf("registerDefaultState(this.getStateDefinition()")
        )
    }

    private fun migrateConstructorThisMethodThisEscapeWarning(source: String): String {
        val thisMethodCall = Regex("""\bthis\.[A-Za-z_$][\w$]*\s*\(""")
        val unqualifiedAccessorCall = Regex("""(?<![.\w$])(?:get|is|has|can|should|set|add|register)[A-Z][A-Za-z_$\d]*\s*\(""")
        val thisAsArgument = Regex("""\(\s*this\s*(?:,|\))|,\s*this\s*(?:,|\))""")
        val thisMethodReference = Regex("""\bthis::[A-Za-z_$][\w$]*\b""")
        if (!thisMethodCall.containsMatchIn(source) &&
            !unqualifiedAccessorCall.containsMatchIn(source) &&
            !thisAsArgument.containsMatchIn(source) &&
            !thisMethodReference.containsMatchIn(source)) return source
        val classNames = javaClassNames(source)
        if (classNames.isEmpty()) return source
        var result = source
        classNames.forEach { className ->
            result = addSuppressWarningToConstructorsMatching(result, className, "this-escape") { constructorText ->
                thisMethodCall.containsMatchIn(constructorText) ||
                    unqualifiedAccessorCall.containsMatchIn(constructorText) ||
                    thisAsArgument.containsMatchIn(constructorText) ||
                    thisMethodReference.containsMatchIn(constructorText)
            }
        }
        return result
    }

    private fun migrateFieldInitializerThisMethodThisEscapeWarning(source: String): String {
        val thisMethodCall = Regex("""\bthis\.[A-Za-z_$][\w$]*\s*\(""")
        val unqualifiedAccessorCall = Regex("""(?<![.\w$])(?:get|is|has|can|should|set|add|register)[A-Z][A-Za-z_$\d]*\s*\(""")
        if (!thisMethodCall.containsMatchIn(source) && !unqualifiedAccessorCall.containsMatchIn(source)) return source
        val linePattern = Regex("""^[ \t]*(?:public|protected|private)\s+""")
        val starts = mutableListOf<Int>()
        var offset = 0
        for (line in source.splitToSequence('\n')) {
            val trimmed = line.trim()
            if (linePattern.containsMatchIn(line) &&
                !Regex("""\bstatic\b""").containsMatchIn(trimmed.substringBefore('=')) &&
                trimmed.contains("=") &&
                trimmed.endsWith(";") &&
                (thisMethodCall.containsMatchIn(trimmed) || unqualifiedAccessorCall.containsMatchIn(trimmed))) {
                starts.add(offset)
            }
            offset += line.length + 1
        }
        var result = source
        for (start in starts.asReversed()) {
            result = addSuppressWarningToElementAt(result, start, "this-escape")
        }
        return result
    }

    private fun migrateClassLevelThisEscapeFallback(source: String): String {
        if (source.contains("\"this-escape\"")) return source
        val thisMethodCall = Regex("""\bthis\.[A-Za-z_$][\w$]*\s*\(""")
        val thisAsArgument = Regex("""\(\s*this\s*(?:,|\))|,\s*this\s*(?:,|\))""")
        val thisMethodReference = Regex("""\bthis::[A-Za-z_$][\w$]*\b""")
        val unqualifiedAccessorCall = Regex("""(?<![.\w$])(?:get|is|has|can|should)[A-Z][A-Za-z_$\d]*\s*\(""")
        val fieldEscape = source.lineSequence().any { line ->
            val trimmed = line.trim()
            Regex("""^(?:public|protected|private)\s+""").containsMatchIn(trimmed) &&
                !Regex("""\bstatic\b""").containsMatchIn(trimmed.substringBefore('=')) &&
                trimmed.contains("=") &&
                trimmed.endsWith(";") &&
                (thisMethodCall.containsMatchIn(trimmed) || unqualifiedAccessorCall.containsMatchIn(trimmed))
        }
        val constructorEscape = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\s*\r?\n[ \t]*)*(?:public|protected|private)\s+[A-Z][A-Za-z_$\d]*\s*\([^;{}]*\)\s*(?:throws\s+[^{;]+)?\{"""
        ).findAll(source).any { match ->
            val openBrace = source.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            closeBrace > openBrace &&
                source.substring(openBrace + 1, closeBrace).let { body ->
                    thisMethodCall.containsMatchIn(body) ||
                        unqualifiedAccessorCall.containsMatchIn(body) ||
                        thisAsArgument.containsMatchIn(body) ||
                        thisMethodReference.containsMatchIn(body)
                }
        }
        if (!fieldEscape && !constructorEscape) return source
        val classDeclaration = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\s*\r?\n[ \t]*)*(?:public\s+)?(?:abstract\s+|final\s+)?class\s+[A-Za-z_$][\w$]*\b"""
        ).find(source) ?: return source
        return addSuppressWarningToElementAt(source, classDeclaration.range.first, "this-escape")
    }

    private fun migrateCuriosHelperRemovalApis(source: String): String {
        if (!source.contains("CuriosApi.getCuriosHelper()")) return source
        var result = source
        result = rewriteJavaCall(result, "getEquippedCurios") { receiver, args ->
            if (receiver != "CuriosApi.getCuriosHelper()" || args.size != 1) return@rewriteJavaCall null
            "CuriosApi.getCuriosInventory(${args[0].trim()}).map(handler -> handler.getEquippedCurios())"
        }
        result = rewriteJavaCall(result, "findFirstCurio") { receiver, args ->
            if (receiver != "CuriosApi.getCuriosHelper()" || args.size != 2) return@rewriteJavaCall null
            "CuriosApi.getCuriosInventory(${args[0].trim()}).flatMap(handler -> handler.findFirstCurio(${args[1].trim()}))"
        }
        return result
    }

    private fun migrateCuriosInventoryOptionalTypes(source: String): String {
        if (!source.contains("CuriosApi.getCuriosInventory") || !source.contains("LazyOptional")) return source

        val before = source
        var result = Regex("""\b(?:net\.neoforged\.neoforge\.common\.util\.)?LazyOptional\s*<\s*ICuriosItemHandler\s*>""")
            .replace(source, "Optional<ICuriosItemHandler>")
        if (result == before) return source
        val optionalCuriosVariables = Regex("""\bOptional\s*<\s*ICuriosItemHandler\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        optionalCuriosVariables.forEach { variable ->
            result = Regex("""\b${Regex.escape(variable)}\.resolve\(\)""").replace(result, variable)
            result = Regex("""\b${Regex.escape(variable)}\.isPresent\(\)\s*&&\s*${Regex.escape(variable)}\.isPresent\(\)""")
                .replace(result, "$variable.isPresent()")
        }
        result = removeImport(result, "net.neoforged.neoforge.common.util.LazyOptional")
        result = addImportIfMissing(result, "java.util.Optional")
        return result
    }

    private fun migrateJeiRecipeCategoryBackgroundApi(source: String): String {
        if (!source.contains("IRecipeCategory<") || !source.contains("getBackground()")) return source
        val backgroundMethod = javaDeclaredMethodText(source, "getBackground") ?: return source
        val backgroundField = Regex("""return\s+(?:this\.)?([A-Za-z_$][\w$]*)\s*;""")
            .find(backgroundMethod)
            ?.groupValues
            ?.get(1)
            ?: return source
        if (!Regex("""\bIDrawable\s+$backgroundField\b""").containsMatchIn(source)) return source

        var result = source.replace(backgroundMethod, "")
        val sizeMethods = """

	@Override
	public int getWidth() {
		return this.$backgroundField.getWidth();
	}

	@Override
	public int getHeight() {
		return this.$backgroundField.getHeight();
	}
""".trimEnd()
        if (!Regex("""\bint\s+getWidth\s*\(""").containsMatchIn(result)) {
            result = javaDeclaredMethodText(result, "getIcon")
                ?.let { iconMethod -> result.replace(iconMethod, sizeMethods + "\n\n" + iconMethod) }
                ?: insertBeforeLastClassBrace(result, "\n$sizeMethods\n")
        }

        val drawMethod = javaDeclaredMethodText(result, "draw")
        result = if (drawMethod != null) {
            val graphicsName = Regex("""\bGuiGraphics\s+([A-Za-z_$][\w$]*)\b""")
                .find(drawMethod)
                ?.groupValues
                ?.get(1)
            if (graphicsName != null && !drawMethod.contains("$backgroundField.draw($graphicsName)")) {
                val openBrace = drawMethod.indexOf('{')
                val absoluteStart = result.indexOf(drawMethod)
                val insertAt = absoluteStart + openBrace + 1
                val indent = Regex("""(?m)^([ \t]*)[^\r\n]*\{""")
                    .find(drawMethod)
                    ?.groupValues
                    ?.get(1)
                    ?.plus("\t")
                    ?: "\t\t"
                result.substring(0, insertAt) +
                    "\n${indent}this.$backgroundField.draw($graphicsName);" +
                    result.substring(insertAt)
            } else {
                result
            }
        } else {
            val recipeType = Regex("""implements\s+IRecipeCategory\s*<\s*([^>{}]+)\s*>""")
                .find(result)
                ?.groupValues
                ?.get(1)
                ?.trim()
                ?: "Object"
            val draw = """

	@Override
	public void draw($recipeType recipe, IRecipeSlotsView recipeSlotsView, GuiGraphics graphics, double mouseX, double mouseY) {
		this.$backgroundField.draw(graphics);
	}
""".trimEnd()
            result = javaDeclaredMethodText(result, "setRecipe")
                ?.let { setRecipe -> result.replace(setRecipe, draw + "\n\n" + setRecipe) }
                ?: insertBeforeLastClassBrace(result, "\n$draw\n")
            result = addImportIfMissing(result, "mezz.jei.api.gui.ingredient.IRecipeSlotsView")
            result = addImportIfMissing(result, "net.minecraft.client.gui.GuiGraphics")
            result
        }

        return result
    }

    private fun migrateRequiredRemovalWarningAnnotations(source: String): String =
        addSuppressWarningToMethodsContaining(source, "removal") { methodText ->
            methodText.contains("initializeClient(Consumer<IClientItemExtensions>") ||
                methodText.contains("initializeClient(Consumer<IClientBlockExtensions>") ||
                methodText.contains("removeFromBlockToItemMap(") ||
                (methodText.contains("getTooltip(") && methodText.contains("TooltipFlag")) ||
                (methodText.contains("getUniqueId(") && methodText.contains("UidContext")) ||
                (methodText.contains("IModIngredientRegistration") && methodText.contains(".register("))
        }

    private fun migrateFinalLivingEntityDimensionsOverrides(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        if (!source.contains("getDimensions(Pose") || !source.contains("@Override")) return source

        var result = source
        var cursor = 0
        val signaturePattern = Regex("""\b(public|protected)\s+EntityDimensions\s+getDimensions\s*\(\s*Pose\s+([A-Za-z_$][\w$]*)\s*\)""")
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val classDeclaration = enclosingJavaClassDeclaration(result, match.range.first)
            if (!javaClassExtendsAny(classDeclaration, javaLivingEntityBaseTypes(), javaInheritanceIndex)) {
                cursor = match.range.last + 1
                continue
            }
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val signature = result.substring(match.range.first, openBrace)
            val rewrittenSignature = signaturePattern.replace(signature) { signatureMatch ->
                "${signatureMatch.groupValues[1]} EntityDimensions getDefaultDimensions(Pose ${signatureMatch.groupValues[2]})"
            }
            val rewrittenBody = result.substring(openBrace, closeBrace + 1)
                .replace("super.getDimensions(", "super.getDefaultDimensions(")
            result = result.substring(0, match.range.first) +
                rewrittenSignature +
                rewrittenBody +
                result.substring(closeBrace + 1)
            cursor = match.range.first + rewrittenSignature.length + rewrittenBody.length
        }
        return result
    }

    private fun migrateSaddleableEquipSaddleSignature(source: String): String {
        if (!source.contains("equipSaddle(") || !source.contains("SoundSource")) return source
        var changed = false
        val result = Regex(
            """public\s+void\s+equipSaddle\(\s*((?:@(?:[\w.]+\.)?Nullable\s+)?)((?:net\.minecraft\.sounds\.)?SoundSource)\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(source) { match ->
            changed = true
            val nullable = match.groupValues[1]
            val soundType = match.groupValues[2]
            val soundName = match.groupValues[3]
            "public void equipSaddle(ItemStack stack, $nullable$soundType $soundName)"
        }
        return if (changed) addImportIfMissing(result, "net.minecraft.world.item.ItemStack") else source
    }

    private fun migrateMthTrigonometryFloatArguments(source: String): String {
        if (!source.contains("Mth.sin(") && !source.contains("Mth.cos(")) return source
        val doubleVariables = Regex("""\bdouble\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (doubleVariables.isEmpty()) return source

        var result = source
        for (variable in doubleVariables) {
            val escaped = Regex.escape(variable)
            result = Regex("""\bMth\.sin\(\s*$escaped\s*\)""").replace(result, "Mth.sin((float) $variable)")
            result = Regex("""\bMth\.cos\(\s*$escaped\s*\)""").replace(result, "Mth.cos((float) $variable)")
        }
        return result
    }

    private fun migrateMapDecorationRecordSource(source: String): String {
        if (!source.contains("MapDecoration")) return source

        var result = source
        if (result.contains("MapDecoration.Type.")) {
            result = result.replace("MapDecoration.Type.", "MapDecorationTypes.")
            result = addImportIfMissing(result, "net.minecraft.world.level.saveddata.maps.MapDecorationTypes")
        }
        val decorationVariables = Regex("""\bMapDecoration\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in decorationVariables) {
            result = result
                .replace("$variable.getX()", "$variable.x()")
                .replace("$variable.getY()", "$variable.y()")
                .replace("$variable.getRot()", "$variable.rot()")
        }

        if (result.contains("new MapDecoration(")) {
            result = Regex("""new\s+MapDecoration\(([^;\r\n]*?),\s*null\s*\)""")
                .replace(result) { match ->
                    "new MapDecoration(${match.groupValues[1]}, java.util.Optional.empty())"
                }
            result = Regex("""new\s+MapDecoration\(([^;\r\n]*?),\s*(Component\.[^;\r\n)]+\(.*?\))\s*\)""")
                .replace(result) { match ->
                    val args = match.groupValues[1]
                    val component = match.groupValues[2]
                    if (args.contains("java.util.Optional.") || component.startsWith("java.util.Optional.")) {
                        match.value
                    } else {
                        "new MapDecoration($args, java.util.Optional.of($component))"
                    }
                }
        }

        return result
    }

    private fun migrateLegacyModelRenderPackedColorBodies(source: String): String {
        if (!source.contains("renderToBuffer(") && !source.contains(".render(")) return source
        var result = source
        var needsFastColor = false

        result = rewriteJavaCall(result, "render") { receiver, args ->
            if (args.size != 8) return@rewriteJavaCall null
            if (!isLegacyModelPartColorRenderArgs(args)) return@rewriteJavaCall null
            needsFastColor = true
            "$receiver.render(${args[0]}, ${args[1]}, ${args[2]}, ${args[3]}, FastColor.ARGB32.colorFromFloat(${args[7]}, ${args[4]}, ${args[5]}, ${args[6]}))"
        }
        result = rewriteJavaCall(result, "renderToBuffer") { receiver, args ->
            if (args.size != 8) return@rewriteJavaCall null
            if (!isLegacyModelPartColorRenderArgs(args)) return@rewriteJavaCall null
            needsFastColor = true
            "$receiver.renderToBuffer(${args[0]}, ${args[1]}, ${args[2]}, ${args[3]}, FastColor.ARGB32.colorFromFloat(${args[7]}, ${args[4]}, ${args[5]}, ${args[6]}))"
        }

        var cursor = 0
        val signature = Regex("""renderToBuffer\s*\([^)]*\bint\s+color\s*\)\s*\{""")
        while (true) {
            val match = signature.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val unpackLocals = linkedMapOf<String, String>()
            fun addUnpackLocal(name: String, expression: String) {
                if (Regex("""[A-Za-z_$][\w$]*""").matches(name) &&
                    name != "color" &&
                    !Regex("""\b(?:float|int)\s+${Regex.escape(name)}\b""").containsMatchIn(body)) {
                    unpackLocals.putIfAbsent(name, expression)
                }
            }
            Regex(
                """FastColor\.ARGB32\.colorFromFloat\(\s*([^,()]+)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)"""
            ).findAll(body).forEach { colorMatch ->
                val alphaExpression = colorMatch.groupValues[1].trim()
                addUnpackLocal(alphaExpression, "FastColor.ARGB32.alpha(color) / 255.0F")
                Regex("""\b(alpha|scale|a)\b""").findAll(alphaExpression).forEach { token ->
                    addUnpackLocal(token.value, "FastColor.ARGB32.alpha(color) / 255.0F")
                }
                addUnpackLocal(colorMatch.groupValues[2].trim(), "FastColor.ARGB32.red(color) / 255.0F")
                addUnpackLocal(colorMatch.groupValues[3].trim(), "FastColor.ARGB32.green(color) / 255.0F")
                addUnpackLocal(colorMatch.groupValues[4].trim(), "FastColor.ARGB32.blue(color) / 255.0F")
            }
            if (unpackLocals.isEmpty() &&
                !body.contains("FastColor.ARGB32.alpha(color)") &&
                Regex("""\b(red|green|blue|alpha|scale)\b""").containsMatchIn(body)) {
                addUnpackLocal("alpha", "FastColor.ARGB32.alpha(color) / 255.0F")
                addUnpackLocal("scale", "alpha")
                addUnpackLocal("red", "FastColor.ARGB32.red(color) / 255.0F")
                addUnpackLocal("green", "FastColor.ARGB32.green(color) / 255.0F")
                addUnpackLocal("blue", "FastColor.ARGB32.blue(color) / 255.0F")
            }
            if (unpackLocals.isNotEmpty()) {
                val insertion = unpackLocals.entries.joinToString(
                    separator = "",
                    prefix = "\n",
                    postfix = ""
                ) { (name, expression) -> "\n\t\tfloat $name = $expression;" }
                result = result.substring(0, openBrace + 1) + insertion + result.substring(openBrace + 1)
                needsFastColor = true
                cursor = closeBrace + insertion.length + 1
            } else {
                cursor = closeBrace + 1
            }
        }

        cursor = 0
        val floatColorSignature = Regex("""\([^)]*\bfloat\s+red\s*,\s*float\s+green\s*,\s*float\s+blue\s*,\s*float\s+alpha\s*\)\s*\{""")
        while (true) {
            val match = floatColorSignature.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val rewrittenBody = rewriteJavaCall(body, "render") { receiver, args ->
                if (args.size == 5 && args[4] == "color") {
                    "$receiver.render(${args[0]}, ${args[1]}, ${args[2]}, ${args[3]}, FastColor.ARGB32.colorFromFloat(alpha, red, green, blue))"
                } else {
                    null
                }
            }
            if (rewrittenBody != body) {
                result = result.substring(0, openBrace + 1) + rewrittenBody + result.substring(closeBrace)
                needsFastColor = true
                cursor = openBrace + 1 + rewrittenBody.length
            } else {
                cursor = closeBrace + 1
            }
        }

        return if (needsFastColor || result.contains("FastColor.ARGB32.")) {
            addImportIfMissing(result, "net.minecraft.util.FastColor")
        } else {
            result
        }
    }

    private fun isLegacyModelPartColorRenderArgs(args: List<String>): Boolean {
        if (args.size != 8) return false
        val poseArg = args[0].trim()
        val consumerArg = args[1].trim()
        if (!Regex("""[A-Za-z_$][\w$]*""").matches(poseArg)) return false
        val poseName = poseArg.lowercase()
        if (poseName != "ms" && "pose" !in poseName && "stack" !in poseName && "matrix" !in poseName) {
            return false
        }
        val consumerName = consumerArg.lowercase()
        if ("consumer" !in consumerName && "buffer" !in consumerName && "vertex" !in consumerName && "builder" !in consumerName) {
            return false
        }

        val renderInfrastructure = listOf(
            "ItemDisplayContext",
            "OverlayTexture",
            "MultiBufferSource",
            "BakedModel",
            "applyTransform(",
            "bufferSource",
            "getBuffer(",
            "ItemStack"
        )
        if (args.drop(4).any { arg -> renderInfrastructure.any { marker -> marker in arg } }) {
            return false
        }

        val colorTerms = setOf(
            "red",
            "green",
            "blue",
            "alpha",
            "r",
            "g",
            "b",
            "a",
            "scale",
            "opacity"
        )
        val colorLikeCount = args.drop(4).count { arg ->
            val tokens = Regex("""[A-Za-z_$][\w$]*""").findAll(arg).map { it.value.lowercase() }.toSet()
            arg.contains("FastColor.ARGB32.") ||
                tokens.any { it in colorTerms || it.endsWith("color") || it.endsWith("colors") || it.endsWith("col") } ||
                Regex("""[-+]?\d+(?:\.\d+)?[FfDd]?""").matches(arg.trim())
        }
        return colorLikeCount >= 3
    }

    private fun migrateLegacyClientRenderingSource(source: String): String {
        if (!source.contains("RenderSystem.getModelViewStack()") &&
            !source.contains(".getPartialTick()") &&
            !source.contains(".getFrameTime()") &&
            !source.contains(".getDeltaFrameTime()") &&
            !source.contains(".vertex(") &&
            !source.contains(".color(") &&
            !source.contains(".setNormal(") &&
            !source.contains(".getU(") &&
            !source.contains(".getV(") &&
            !source.contains("BufferUploader.drawWithShader(") &&
            !source.contains("Tesselator.getInstance()") &&
            !source.contains("InventoryScreen.renderEntityInInventory") &&
            !source.contains("PanoramaRenderer") &&
            !source.contains("ArmorTrim.getTrim(") &&
            !source.contains("ItemRenderer.getArmorFoilBuffer(")
        ) {
            return source
        }

        var result = source
        var needsBufferUploader = false

        result = migratePartialTickAccessors(result)
        result = Regex("""PoseStack\s+([A-Za-z_$][\w$]*)\s*=\s*RenderSystem\.getModelViewStack\(\)\s*;""")
            .replace(result) { match ->
                val stack = match.groupValues[1]
                "PoseStack $stack = new PoseStack();\n            $stack.mulPose(RenderSystem.getModelViewMatrix());"
            }

        val bufferBuilderVariables = Regex("""\bBufferBuilder\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toList()
        val firstBufferBuilder = bufferBuilderVariables.firstOrNull()
        if (firstBufferBuilder != null && "buffer" !in bufferBuilderVariables) {
            result = result.replace("buffer.buildOrThrow()", "$firstBufferBuilder.buildOrThrow()")
        }
        if (result.contains("BufferUploader.drawWithShader(")) {
            needsBufferUploader = true
        }

        result = rewriteJavaCall(result, "vertex") { receiver, args ->
            when (args.size) {
                3 -> "$receiver.addVertex((float) (${args[0]}), (float) (${args[1]}), (float) (${args[2]}))"
                4 -> "$receiver.addVertex(${args[0]}, ${args[1]}, ${args[2]}, ${args[3]})"
                else -> null
            }
        }
        result = migrateTextureAtlasSpriteFloatCoordinateCalls(result)
        result = migrateVertexConsumerPoseNormals(result)
        result = migrateLegacyTesselatorSource(result)
        result = migrateInventoryScreenEntityPreviewCalls(result)
        result = migratePanoramaRendererRenderApis(result)
        result = migrateArmorTrimComponentRendering(result)
        result = migrateArmorFoilBufferCalls(result)
        val vertexConsumerVariables = Regex("""\bVertexConsumer\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        result = rewriteJavaCall(result, "color") { receiver, args ->
            if (args.size !in setOf(3, 4)) return@rewriteJavaCall null
            if (receiver !in vertexConsumerVariables && !receiver.contains(".addVertex(")) {
                return@rewriteJavaCall null
            }
            "$receiver.setColor(${args.joinToString(", ") { it.trim() }})"
        }
        result = Regex("""\.setLight\(\s*([^,()]+)\s*,\s*([^,()]+)\s*\)""")
            .replace(result) { match -> ".setUv2(${match.groupValues[1].trim()}, ${match.groupValues[2].trim()})" }

        return if (needsBufferUploader) addImportIfMissing(result, "com.mojang.blaze3d.vertex.BufferUploader") else result
    }

    private fun migrateArmorFoilBufferCalls(source: String): String {
        if (!source.contains("ItemRenderer.getArmorFoilBuffer(")) return source

        return rewriteJavaCall(source, "getArmorFoilBuffer") { receiver, args ->
            if (receiver != "ItemRenderer" || args.size != 4) return@rewriteJavaCall null
            "ItemRenderer.getArmorFoilBuffer(${args[0].trim()}, ${args[1].trim()}, ${args[3].trim()})"
        }
    }

    private fun migrateArmorTrimComponentRendering(source: String): String {
        if (!source.contains("ArmorTrim.getTrim(")) return source

        var result = Regex(
            """ArmorTrim\.getTrim\s*\(\s*([^,]+)\s*,\s*([^)]+?)\s*\)\.ifPresent\s*\("""
        ).replace(source) { match ->
            val stack = match.groupValues[2].trim()
            "java.util.Optional.ofNullable($stack.get(DataComponents.TRIM)).ifPresent("
        }
        if (result == source) return source

        var cursor = 0
        val lambdaPattern = Regex("""java\.util\.Optional\.ofNullable\([^;\r\n]*DataComponents\.TRIM[^;\r\n]*\)\.ifPresent\s*\(\s*\(?\s*([A-Za-z_$][\w$]*)\s*\)?\s*->\s*\{""")
        while (true) {
            val match = lambdaPattern.find(result, cursor) ?: break
            val trimVariable = match.groupValues[1]
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val migratedBody = body.replace(
                "Sheets.armorTrimsSheet()",
                "Sheets.armorTrimsSheet($trimVariable.pattern().value().decal())"
            )
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }

        result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        val withoutArmorTrimImport = removeImport(result, "net.minecraft.world.item.armortrim.ArmorTrim")
        if (!Regex("""\bArmorTrim\b""").containsMatchIn(withoutArmorTrimImport)) {
            result = withoutArmorTrimImport
        }
        return result
    }

    private data class JavaParameter(val type: String, val name: String)

    private fun migratePanoramaRendererRenderApis(source: String): String {
        if (!source.contains("PanoramaRenderer")) return source

        var result = source
        result = rewriteJavaCallWithOffset(result, "render") { receiver, args, callOffset ->
            if (args.size != 2) return@rewriteJavaCallWithOffset null
            if (!Regex("""[A-Za-z_$][\w$]*""").matches(receiver)) return@rewriteJavaCallWithOffset null
            val methodText = enclosingMethodText(result, callOffset) ?: return@rewriteJavaCallWithOffset null
            val params = javaMethodParameters(methodText)
            if (params.none { it.name == receiver && it.type.endsWith("PanoramaRenderer") } &&
                !Regex("""\bPanoramaRenderer\s+${Regex.escape(receiver)}\b""").containsMatchIn(methodText)) {
                return@rewriteJavaCallWithOffset null
            }
            val guiGraphics = params.firstOrNull { it.type.endsWith("GuiGraphics") }?.name ?: return@rewriteJavaCallWithOffset null
            val screen = params.firstOrNull { it.type.endsWith("Screen") }?.name ?: return@rewriteJavaCallWithOffset null
            "$receiver.render($guiGraphics, $screen.width, $screen.height, ${args[0].trim()}, ${args[1].trim()})"
        }

        if (result.contains("@Mixin(PanoramaRenderer.class)") ||
            result.contains("@Mixin(net.minecraft.client.renderer.PanoramaRenderer.class)")) {
            val beforeMixin = result
            result = result
                .replace("method = \"render(FF)V\"", "method = \"render(Lnet/minecraft/client/gui/GuiGraphics;IIFF)V\"")
                .replace("method = {\"render(FF)V\"}", "method = {\"render(Lnet/minecraft/client/gui/GuiGraphics;IIFF)V\"}")
            result = Regex(
                """\b((?:public|protected|private)\s+(?:static\s+)?)void\s+([A-Za-z_$][\w$]*)\s*\(\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*CallbackInfo\s+([A-Za-z_$][\w$]*)\s*\)"""
            ).replace(result) { match ->
                "${match.groupValues[1]}void ${match.groupValues[2]}(GuiGraphics guiGraphics, int width, int height, float ${match.groupValues[3]}, float ${match.groupValues[4]}, CallbackInfo ${match.groupValues[5]})"
            }
            if (result != beforeMixin && !result.contains("import net.minecraft.client.gui.GuiGraphics;")) {
                result = addImportIfMissing(result, "net.minecraft.client.gui.GuiGraphics")
            }
        }

        return result
    }

    private fun javaMethodParameters(methodText: String): List<JavaParameter> {
        val paramsText = Regex(
            """(?s)\b(?:public|protected|private|static|final|synchronized|default|abstract|\s)+[A-Za-z_$][\w$<>\[\].?,\s]*\s+[A-Za-z_$][\w$]*\s*\(([^{};]*)\)\s*(?:throws\s+[^{]+)?\{"""
        ).find(methodText)?.groupValues?.get(1) ?: return emptyList()
        return splitTopLevelJavaArgs(paramsText).mapNotNull { rawParam ->
            val cleaned = rawParam
                .replace(Regex("""@\w+(?:\([^)]*\))?\s*"""), "")
                .replace(Regex("""\bfinal\s+"""), "")
                .trim()
            val name = Regex("""([A-Za-z_$][\w$]*)\s*$""").find(cleaned)?.groupValues?.get(1) ?: return@mapNotNull null
            val type = cleaned.removeSuffix(name).trim().removeSuffix("...").trim()
            if (type.isBlank()) null else JavaParameter(type, name)
        }
    }

    private fun migrateInventoryScreenEntityPreviewCalls(source: String): String {
        if (!source.contains("InventoryScreen.renderEntityInInventory")) return source

        var result = rewriteJavaCall(source, "renderEntityInInventoryFollowsMouse") { receiver, args ->
            if (receiver != "InventoryScreen" || args.size != 7) return@rewriteJavaCall null
            val guiGraphics = args[0].trim()
            val x = args[1].trim()
            val y = args[2].trim()
            val scale = args[3].trim()
            val angleXInput = args[4].trim()
            val angleYInput = args[5].trim()
            val entity = args[6].trim()
            "InventoryScreen.renderEntityInInventoryFollowsAngle(" +
                "$guiGraphics, " +
                "($x) - ($scale), " +
                "($y) - ($scale), " +
                "($x) + ($scale), " +
                "($y) + ($scale), " +
                "$scale, " +
                "0.0F, " +
                "(float) Math.atan((double) (($angleXInput) / 40.0F)), " +
                "(float) Math.atan((double) (($angleYInput) / 40.0F)), " +
                "$entity)"
        }
        result = rewriteJavaCall(result, "renderEntityInInventory") { receiver, args ->
            if (receiver != "InventoryScreen" || args.size != 7) return@rewriteJavaCall null
            if (args[4].contains("Vector3f")) return@rewriteJavaCall null
            val entity = args[6].trim()
            "InventoryScreen.renderEntityInInventory(" +
                "${args[0].trim()}, " +
                "(float) (${args[1].trim()}), " +
                "(float) (${args[2].trim()}), " +
                "(float) (${args[3].trim()}), " +
                "new org.joml.Vector3f(0.0F, $entity.getBbHeight() / 2.0F, 0.0F), " +
                "${args[4].trim()}, " +
                "${args[5].trim()}, " +
                "$entity)"
        }
        return result
    }

    private fun migrateLegacyTesselatorSource(source: String): String {
        if (!source.contains("Tesselator.getInstance()") &&
            !source.contains(".getBuilder()") &&
            !source.contains(".end()")) {
            return source
        }
        var result = source
        var needsBufferUploader = false
        var needsBufferBuilder = false

        val tesselatorVariables = Regex("""\bTesselator\s+([A-Za-z_$][\w$]*)\s*=\s*Tesselator\.getInstance\(\)\s*;""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        tesselatorVariables.forEach { tesselator ->
            result = Regex("""\bBufferBuilder\s+([A-Za-z_$][\w$]*)\s*=\s*${Regex.escape(tesselator)}\.getBuilder\(\)\s*;""")
                .replace(result) { match -> "BufferBuilder ${match.groupValues[1]} = null;" }
        }

        result = Regex(
            """(?m)^([ \t]*)BufferBuilder\s+([A-Za-z_$][\w$]*)\s*=\s*Tesselator\.getInstance\(\)\.getBuilder\(\)\s*;\s*\r?\n[ \t]*\2\s*=\s*Tesselator\.getInstance\(\)\.begin\("""
        ).replace(result) { match ->
            "${match.groupValues[1]}BufferBuilder ${match.groupValues[2]} = Tesselator.getInstance().begin("
        }
        result = Regex("""\b([A-Za-z_$][\w$]*)\.end\(\)""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                if (Regex("""\bBufferBuilder\s+${Regex.escape(receiver)}\b""").containsMatchIn(result)) {
                    "$receiver.buildOrThrow()"
                } else {
                    match.value
                }
            }

        if (result.contains("Tesselator.getInstance().end()")) {
            result = migrateTesselatorEndHelperMethods(result)
            needsBufferUploader = result.contains("BufferUploader.drawWithShader(")
            needsBufferBuilder = result.contains("BufferBuilder builder")
        }
        result = migrateTesselatorVariableEndCalls(result).also { migrated ->
            if (migrated != result) {
                needsBufferUploader = true
                result = migrated
            }
        }

        val beginBuffer = Regex(
            """\bBufferBuilder\s+([A-Za-z_$][\w$]*)\s*=\s*Tesselator\.getInstance\(\)\.begin\("""
        ).find(result)?.groupValues?.get(1)
        if (beginBuffer != null) {
            result = rewriteJavaCall(result, "invokeThenEndTesselator") { receiver, args ->
                if (receiver.isBlank() || args.any { it.trim() == beginBuffer }) return@rewriteJavaCall null
                "$receiver.invokeThenEndTesselator(${(args + beginBuffer).joinToString(", ") { it.trim() }})"
            }
        }

        if (needsBufferUploader) {
            result = addImportIfMissing(result, "com.mojang.blaze3d.vertex.BufferUploader")
        }
        if (needsBufferBuilder) {
            result = addImportIfMissing(result, "com.mojang.blaze3d.vertex.BufferBuilder")
        }
        return result
    }

    private fun migrateTesselatorVariableEndCalls(source: String): String {
        var result = source
        val methodPattern = Regex("""(?m)(?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^)]*\)\s*\{""")
        var cursor = 0
        while (true) {
            val method = methodPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', method.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = method.range.last + 1
                continue
            }
            var body = result.substring(openBrace + 1, closeBrace)
            val originalBody = body
            val bufferVariables = Regex("""\bBufferBuilder\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(body)
                .map { it.groupValues[1] }
                .toList()
            if (bufferVariables.isEmpty()) {
                cursor = closeBrace + 1
                continue
            }
            val tesselatorVariables = Regex("""\bTesselator\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(body)
                .map { it.groupValues[1] }
                .toSet()
            val activeBuffer = bufferVariables.firstOrNull { variable ->
                Regex("""\b${Regex.escape(variable)}\s*=\s*Tesselator\.getInstance\(\)\.begin\(""").containsMatchIn(body) ||
                    Regex("""\b${Regex.escape(variable)}\s*=\s*[A-Za-z_$][\w$]*\.begin\(""").containsMatchIn(body)
            } ?: bufferVariables.first()
            tesselatorVariables.forEach { tesselator ->
                body = Regex("""\b${Regex.escape(tesselator)}\.end\(\)\s*;""")
                    .replace(body, "BufferUploader.drawWithShader($activeBuffer.buildOrThrow());")
            }
            if (body != originalBody) {
                result = result.substring(0, openBrace + 1) + body + result.substring(closeBrace)
                cursor = openBrace + 1 + body.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun migrateTesselatorEndHelperMethods(source: String): String {
        var result = source
        val methodPattern = Regex(
            """(?m)(public|protected|private)\s+(?:final\s+)?void\s+([A-Za-z_$][\w$]*)\s*\(([^)]*)\)\s*\{"""
        )
        var cursor = 0
        while (true) {
            val method = methodPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', method.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = method.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            if (!body.contains("Tesselator.getInstance().end()")) {
                cursor = closeBrace + 1
                continue
            }

            val signature = result.substring(method.range.first, openBrace)
            val rewrittenSignature = if (signature.contains("BufferBuilder ")) {
                signature
            } else {
                val params = method.groupValues[3].trim()
                val insertion = if (params.isEmpty()) "BufferBuilder builder" else "$params, BufferBuilder builder"
                signature.replace(Regex("""\([^)]*\)"""), "($insertion)")
            }
            val rewrittenBody = body.replace(
                "Tesselator.getInstance().end()",
                "BufferUploader.drawWithShader(builder.buildOrThrow())"
            )
            result = result.substring(0, method.range.first) +
                rewrittenSignature +
                result.substring(openBrace, openBrace + 1) +
                rewrittenBody +
                result.substring(closeBrace)
            cursor = method.range.first + rewrittenSignature.length + 1 + rewrittenBody.length
        }
        return result
    }

    private fun migrateLegacyModelEventSource(source: String): String {
        if (!source.contains("ModelResourceLocation") && !source.contains("ModelEvent.")) return source
        var result = source
        var needsResourceLocation = false
        val modIdExpression = Regex("""@(?:Mod\.)?EventBusSubscriber\s*\([^)]*\bmodid\s*=\s*([^,\)]+)""")
            .find(result)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: Regex("""(?m)\b(?:public\s+)?static\s+final\s+String\s+(?:MOD_ID|MODID|ID)\s*=\s*([^;\r\n]+);""")
                .find(result)
                ?.groupValues
                ?.get(1)
                ?.trim()

        result = result.replace("List<Map.Entry<ResourceLocation, BakedModel>>", "List<Map.Entry<ModelResourceLocation, BakedModel>>")
        result = Regex("""(\b[A-Za-z_$][\w$]*\.getKey\(\))\.getNamespace\(\)""")
            .replace(result, "$1.id().getNamespace()")
        result = Regex("""(\b[A-Za-z_$][\w$]*\.getKey\(\))\.getPath\(\)""")
            .replace(result, "$1.id().getPath()")

        result = rewriteJavaNew(result, "ModelResourceLocation") { args ->
            if (args.size != 2) return@rewriteJavaNew null
            val model = args[0].trim()
            val variant = args[1].trim()
            if (variant == "\"inventory\"") {
                "ModelResourceLocation.inventory($model)"
            } else {
                "ModelResourceLocation.standalone($model)"
            }
        }

        if (result.contains("ModelEvent.RegisterGeometryLoaders")) {
            result = rewriteJavaCall(result, "register") { receiver, args ->
                if (args.size != 2) return@rewriteJavaCall null
                if (!receiver.endsWith("event") && !receiver.endsWith("Event")) return@rewriteJavaCall null
                val id = args[0].trim()
                val namespace = modIdExpression ?: return@rewriteJavaCall null
                if (!Regex(""""(?:\\.|[^"\\])*"""").matches(id)) return@rewriteJavaCall null
                needsResourceLocation = true
                "$receiver.register(ResourceLocation.fromNamespaceAndPath($namespace, $id), ${args[1].trim()})"
            }
        }

        if (result.contains("ModelEvent.RegisterAdditional")) {
            result = rewriteJavaCall(result, "register") { receiver, args ->
                if (args.size != 1) return@rewriteJavaCall null
                val arg = args[0].trim()
                if (!receiver.endsWith("event") && !receiver.endsWith("Event")) return@rewriteJavaCall null
                modelResourceLocationStandaloneExpression(arg)?.let { standalone ->
                    return@rewriteJavaCall "$receiver.register($standalone)"
                }
                if (arg.startsWith("new ModelResourceLocation(") || arg.startsWith("ModelResourceLocation.")) {
                    return@rewriteJavaCall null
                }
                if (arg.contains(".prefix(") || arg.contains("ResourceLocation.")) {
                    "$receiver.register(ModelResourceLocation.standalone($arg))"
                } else {
                    null
                }
            }
        }
        if (needsResourceLocation) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceLocation")
        }
        return result
    }

    private data class CumulusMenuOwner(
        val simpleName: String,
        val qualifiedName: String,
        val registerFieldName: String,
        val menuFields: Set<String>
    )

    private data class CumulusMenuDefinitionMigration(
        val source: String,
        val owner: CumulusMenuOwner?
    )

    private data class CumulusMenuRegistration(
        val start: Int,
        val end: Int,
        val prefix: String,
        val fieldName: String,
        val id: String,
        val args: List<String>
    )

    private fun migrateCumulusMenuApi(projectDir: Path, dryRun: Boolean): List<Change> {
        val javaFiles = Files.walk(projectDir)
            .filter { it.extension == "java" }
            .filter { !projectDir.relativize(it).toString().replace('\\', '/').let { rel ->
                rel.startsWith("build/") || rel.contains("/build/") ||
                    rel.startsWith("src/references/") || rel.contains("/src/references/")
            }}
            .toList()

        val changes = mutableListOf<Change>()
        val stagedSources = linkedMapOf<Path, String>()
        val owners = mutableListOf<CumulusMenuOwner>()

        for (file in javaFiles) {
            val original = file.readText()
            val migration = migrateCumulusMenuDefinitionSource(projectDir, original)
            migration.owner?.let { owners += it }
            if (migration.source != original) {
                stagedSources[file] = migration.source
                changes += Change(
                    file = file,
                    line = 1,
                    description = "Migrate Cumulus menu DeferredRegister to entrypoint callback",
                    before = "DeferredRegister<Menu> + MENUS.register(...)",
                    after = "@CumulusEntrypoint MenuInitializer#registerMenus",
                    confidence = Confidence.HIGH,
                    ruleId = "struct-cumulus-menu-api-121"
                )
            }
        }

        if (owners.isNotEmpty()) {
            for (file in javaFiles) {
                val base = stagedSources[file] ?: file.readText()
                val migrated = migrateCumulusMenuReferences(base, owners)
                if (migrated != base) {
                    stagedSources[file] = migrated
                    changes += Change(
                        file = file,
                        line = 1,
                        description = "Update Cumulus menu record access and registration call sites",
                        before = "Menu DeferredHolder get()/getMusic()/MENUS.register(bus)",
                        after = "Menu record accessors and entrypoint-owned registration",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-cumulus-menu-api-121"
                    )
                }
            }
        }

        if (!dryRun) {
            stagedSources.forEach { (file, source) -> file.writeText(source) }
        }
        return changes
    }

    private fun migrateCumulusMenuDefinitionSource(projectDir: Path, source: String): CumulusMenuDefinitionMigration {
        if (!source.contains("Cumulus.MENU_REGISTRY_KEY") ||
            !source.contains("DeferredRegister<Menu>") ||
            !source.contains(".register(") ||
            !source.contains("com.aetherteam.cumulus.api.Menu")) {
            return CumulusMenuDefinitionMigration(source, null)
        }

        val className = javaTopLevelTypeName(source) ?: return CumulusMenuDefinitionMigration(source, null)
        val registerPattern = Regex(
            """(?ms)^[ \t]*(?:public|protected|private)\s+static\s+final\s+DeferredRegister\s*<\s*Menu\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*DeferredRegister\.create\(\s*Cumulus\.MENU_REGISTRY_KEY\s*,\s*([^)]+?)\s*\)\s*;\s*\r?\n?"""
        )
        val registerMatch = registerPattern.find(source) ?: return CumulusMenuDefinitionMigration(source, null)
        val registerField = registerMatch.groupValues[1]
        val modIdExpression = registerMatch.groupValues[2].trim()
        val registrations = findCumulusMenuRegistrations(source, registerField)
        if (registrations.isEmpty()) return CumulusMenuDefinitionMigration(source, null)

        val hasLegacyBackground = registrations.any { registration ->
            registration.args.any { it.contains(".background(") }
        } || source.contains("Menu.Background")
        val panoramaExpression = if (hasLegacyBackground) {
            cumulusPanoramaExpression(projectDir, modIdExpression) ?: return CumulusMenuDefinitionMigration(source, null)
        } else {
            null
        }
        val booleanSuppliers = Regex("""\bBooleanSupplier\s+([A-Za-z_$][\w$]*)\s*=""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()

        var result = source
        var needsCubeMapImport = false
        for (registration in registrations.asReversed()) {
            val migratedArgs = migrateCumulusMenuConstructorArgs(
                registration.args,
                booleanSuppliers,
                panoramaExpression
            ) ?: return CumulusMenuDefinitionMigration(source, null)
            if (migratedArgs.any { it.contains("new CubeMap(") }) {
                needsCubeMapImport = true
            }
            val replacement = "${registration.prefix}Menu ${registration.fieldName} = new Menu(${migratedArgs.joinToString(", ") { it.trim() }});\n"
            result = result.substring(0, registration.start) + replacement + result.substring(registration.end)
        }

        result = registerPattern.replace(result, "")
        result = removeUnusedCumulusBooleanSupplierFields(result, booleanSuppliers)
        result = removeCumulusMenuBackgroundFields(result)
        result = addCumulusMenuInitializerClassShape(result, className)
        result = insertCumulusRegisterMenusMethod(result, modIdExpression, registrations)
        result = removeImport(result, "com.aetherteam.cumulus.Cumulus")
        result = removeImport(result, "java.util.function.BooleanSupplier")
        result = removeImport(result, "net.neoforged.neoforge.registries.DeferredRegister")
        result = removeImport(result, "net.neoforged.neoforge.registries.DeferredHolder")
        result = addImportIfMissing(result, "com.aetherteam.cumulus.api.CumulusEntrypoint")
        result = addImportIfMissing(result, "com.aetherteam.cumulus.api.MenuInitializer")
        result = addImportIfMissing(result, "com.aetherteam.cumulus.api.MenuRegisterCallback")
        result = addImportIfMissing(result, "net.minecraft.resources.ResourceLocation")
        if (needsCubeMapImport) {
            result = addImportIfMissing(result, "net.minecraft.client.renderer.CubeMap")
        }
        result = cleanupRedundantBlankLines(result)

        val packageName = packageNameOf(result)
        val owner = CumulusMenuOwner(
            simpleName = className,
            qualifiedName = if (packageName.isBlank()) className else "$packageName.$className",
            registerFieldName = registerField,
            menuFields = registrations.map { it.fieldName }.toSet()
        )
        return CumulusMenuDefinitionMigration(result, owner)
    }

    private fun findCumulusMenuRegistrations(source: String, registerField: String): List<CumulusMenuRegistration> {
        val id = """[A-Za-z_$][\w$]*"""
        val prefixPattern = Regex(
            """(?m)^([ \t]*(?:public|protected|private)\s+static\s+final\s+)DeferredHolder\s*<\s*Menu\s*,\s*Menu\s*>\s+($id)\s*=\s*${Regex.escape(registerField)}\.register\(\s*"([^"]+)"\s*,\s*\(\)\s*->\s*new\s+Menu\s*\("""
        )
        val registrations = mutableListOf<CumulusMenuRegistration>()
        var cursor = 0
        while (true) {
            val match = prefixPattern.find(source, cursor) ?: break
            val openParen = match.range.last
            val closeMenu = findMatchingParen(source, openParen)
            if (closeMenu < 0) {
                cursor = match.range.last + 1
                continue
            }
            var end = closeMenu + 1
            while (end < source.length && source[end].isWhitespace()) end++
            if (end >= source.length || source[end] != ')') {
                cursor = closeMenu + 1
                continue
            }
            end++
            while (end < source.length && source[end].isWhitespace()) end++
            if (end >= source.length || source[end] != ';') {
                cursor = closeMenu + 1
                continue
            }
            end++
            if (end < source.length && source[end] == '\r') end++
            if (end < source.length && source[end] == '\n') end++
            registrations += CumulusMenuRegistration(
                start = match.range.first,
                end = end,
                prefix = match.groupValues[1],
                fieldName = match.groupValues[2],
                id = match.groupValues[3],
                args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeMenu))
            )
            cursor = end
        }
        return registrations
    }

    private fun migrateCumulusMenuConstructorArgs(
        args: List<String>,
        booleanSuppliers: Set<String>,
        panoramaExpression: String?
    ): List<String>? {
        val migrated = args.toMutableList()
        if (migrated.size >= 4 && migrated[3].trim() in booleanSuppliers) {
            migrated.removeAt(3)
        }
        for (index in migrated.indices) {
            if (!migrated[index].contains(".background(")) continue
            val panorama = panoramaExpression ?: return null
            migrated[index] = Regex("""\.background\(\s*[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\s*\)""")
                .replace(migrated[index], ".panorama($panorama)")
        }
        return migrated
    }

    private fun cumulusPanoramaExpression(projectDir: Path, modIdExpression: String): String? {
        val namespace = resolveLiteralModIdExpression(modIdExpression)
            ?: projectMetadataModId(projectDir)
            ?: singleAssetNamespace(projectDir)
            ?: return null
        val relative = Path.of("assets", namespace, "textures", "gui", "title", "panorama", "panorama_0.png")
        val hasPanorama = listOf(
            projectDir.resolve("src/main/resources"),
            projectDir.resolve("src/generated/resources")
        ).any { it.resolve(relative).exists() }
        if (!hasPanorama) return null
        return """new CubeMap(ResourceLocation.fromNamespaceAndPath($modIdExpression, "textures/gui/title/panorama/panorama"))"""
    }

    private fun resolveLiteralModIdExpression(expression: String): String? {
        val trimmed = expression.trim()
        return if (Regex(""""(?:\\.|[^"\\])*"""").matches(trimmed)) trimmed.trim('"') else null
    }

    private fun projectMetadataModId(projectDir: Path): String? {
        val gradleProperties = projectDir.resolve("gradle.properties")
        if (gradleProperties.exists()) {
            Regex("""(?m)^\s*(?:mod_id|modid)\s*=\s*([A-Za-z0-9_.-]+)\s*$""")
                .find(gradleProperties.readText())
                ?.groupValues
                ?.get(1)
                ?.let { return it }
        }
        return listOf(
            projectDir.resolve("src/main/resources/META-INF/neoforge.mods.toml"),
            projectDir.resolve("src/main/resources/META-INF/mods.toml")
        ).asSequence()
            .filter { it.exists() }
            .mapNotNull { file ->
                Regex("(?m)^\\s*modId\\s*=\\s*\"([^\"]+)\"")
                    .find(file.readText())
                    ?.groupValues
                    ?.get(1)
            }
            .firstOrNull()
    }

    private fun singleAssetNamespace(projectDir: Path): String? {
        val namespaces = linkedSetOf<String>()
        for (root in listOf(
            projectDir.resolve("src/main/resources/assets"),
            projectDir.resolve("src/generated/resources/assets")
        )) {
            if (!root.exists()) continue
            Files.list(root).use { children ->
                children.filter { it.isDirectory() }
                    .forEach { namespaces += it.fileName.toString() }
            }
        }
        return namespaces.singleOrNull()
    }

    private fun removeUnusedCumulusBooleanSupplierFields(source: String, booleanSuppliers: Set<String>): String {
        var result = source
        for (name in booleanSuppliers) {
            val declaration = Regex(
                """(?ms)^[ \t]*(?:public|protected|private)\s+static\s+final\s+BooleanSupplier\s+${Regex.escape(name)}\s*=\s*.*?;\s*\r?\n?"""
            ).find(result) ?: continue
            val withoutDeclaration = result.substring(0, declaration.range.first) +
                result.substring(declaration.range.last + 1)
            if (!Regex("""\b${Regex.escape(name)}\b""").containsMatchIn(withoutDeclaration)) {
                result = withoutDeclaration
            }
        }
        return result
    }

    private fun removeCumulusMenuBackgroundFields(source: String): String =
        Regex(
            """(?ms)^[ \t]*(?:public|protected|private)\s+static\s+final\s+Menu\.Background\s+[A-Za-z_$][\w$]*\s*=\s*new\s+Menu\.Background\(\).*?;\s*\r?\n?"""
        ).replace(source, "")

    private fun addCumulusMenuInitializerClassShape(source: String, className: String): String {
        var result = Regex("""\bimplements\s+MenuInitializer(?:\s+implements\s+MenuInitializer)+\b""")
            .replace(source, "implements MenuInitializer")
        if (!Regex("""@CumulusEntrypoint\b""").containsMatchIn(result)) {
            val classMatch = Regex("""(?m)^([ \t]*)(public\s+(?:final\s+)?class\s+${Regex.escape(className)}\b)""")
                .find(result)
            if (classMatch != null) {
                result = result.substring(0, classMatch.range.first) +
                    "${classMatch.groupValues[1]}@CumulusEntrypoint\n" +
                    result.substring(classMatch.range.first)
            }
        }
        val classHeader = Regex("""(?m)(public\s+(?:final\s+)?class\s+${Regex.escape(className)}\b)([^{]*)\{""")
            .find(result)
            ?: return result
        if (classHeader.groupValues[2].contains(Regex("""\bMenuInitializer\b"""))) return result
        val tailRange = classHeader.groups[2]!!.range
        val tail = classHeader.groupValues[2]
        val migratedTail = if (tail.contains(Regex("""\bimplements\b"""))) {
            tail.trimEnd() + ", MenuInitializer "
        } else {
            tail.trimEnd() + " implements MenuInitializer "
        }
        return result.substring(0, tailRange.first) + migratedTail + result.substring(tailRange.last + 1)
    }

    private fun insertCumulusRegisterMenusMethod(
        source: String,
        modIdExpression: String,
        registrations: List<CumulusMenuRegistration>
    ): String {
        if (Regex("""\bvoid\s+registerMenus\s*\(\s*MenuRegisterCallback\b""").containsMatchIn(source)) return source
        val body = registrations.joinToString("\n") { registration ->
            """        menuRegisterCallback.registerMenu(ResourceLocation.fromNamespaceAndPath($modIdExpression, "${registration.id}"), ${registration.fieldName});"""
        }
        val method = """

    @Override
    public void registerMenus(MenuRegisterCallback menuRegisterCallback) {
$body
    }
""".trimEnd()
        return insertBeforeLastClassBrace(source, method)
    }

    private fun migrateCumulusMenuReferences(source: String, owners: List<CumulusMenuOwner>): String {
        var result = source
        for (owner in owners) {
            val ownerNames = listOf(owner.simpleName, owner.qualifiedName).distinct()
            for (ownerName in ownerNames) {
                val escapedOwner = Regex.escape(ownerName)
                result = Regex("""(?m)^[ \t]*$escapedOwner\.${Regex.escape(owner.registerFieldName)}\.register\([^;\r\n]*\);\s*\r?\n""")
                    .replace(result, "")
                for (field in owner.menuFields) {
                    val escapedField = Regex.escape(field)
                    result = Regex("""\b$escapedOwner\.$escapedField\.get\(\)\.getMusic\(\)""")
                        .replace(result, "$ownerName.$field.music()")
                    result = Regex("""\b$escapedOwner\.$escapedField\.get\(\)\.toString\(\)""")
                        .replace(result, "$ownerName.$field.toString()")
                    result = Regex("""\b$escapedOwner\.$escapedField\.get\(\)""")
                        .replace(result, "$ownerName.$field")
                }
            }
        }
        result = Regex("""\bMenus\.MINECRAFT\.get\(\)\.getMusic\(\)""")
            .replace(result, "Menus.MINECRAFT.music()")
        result = Regex("""\bMenus\.MINECRAFT\.get\(\)\.toString\(\)""")
            .replace(result, "Menus.MINECRAFT.toString()")
        result = Regex("""\bMenus\.MINECRAFT\.get\(\)""")
            .replace(result, "Menus.MINECRAFT")
        return result
    }

    private fun cleanupRedundantBlankLines(source: String): String =
        Regex("""\n{3,}""").replace(source, "\n\n")

    private fun migrateRegisterAdditionalModelResourceLocations(projectDir: Path, dryRun: Boolean): List<Change> {
        val changes = mutableListOf<Change>()
        val javaFiles = Files.walk(projectDir)
            .filter { it.extension == "java" }
            .filter { !projectDir.relativize(it).toString().replace('\\', '/').let { rel ->
                rel.startsWith("build/") || rel.contains("/build/") ||
                    rel.startsWith("src/references/") || rel.contains("/src/references/")
            }}
            .toList()
        if (javaFiles.isEmpty()) return changes

        val sources = javaFiles.associateWith { it.readText() }.toMutableMap()
        val classFiles = mutableMapOf<String, MutableList<Path>>()
        for ((file, source) in sources) {
            val className = classNameOfJavaSource(source) ?: continue
            classFiles.getOrPut(className) { mutableListOf() }.add(file)
        }
        val sourcesByClass = sources.values.mapNotNull { source ->
            classNameOfJavaSource(source)?.let { it to source }
        }.toMap()

        for ((file, original) in sources.toMap()) {
            val migrated = rewriteRegisterAdditionalStandaloneModelPaths(original, projectDir, sourcesByClass)
            if (migrated == original) continue
            sources[file] = migrated
            if (!dryRun) file.writeText(migrated)
            changes.add(Change(
                file = file,
                line = 1,
                description = "Preserve legacy inventory model resource path for RegisterAdditional standalone model",
                before = "ModelResourceLocation.standalone(modid:path)",
                after = "ModelResourceLocation.standalone(modid:item/path)",
                confidence = Confidence.HIGH,
                ruleId = "struct-registeradditional-model-item-path"
            ))
        }

        val registeredFields = linkedSetOf<Pair<String, String>>()
        for ((_, source) in sources) {
            if (!source.contains("RegisterAdditional") || !source.contains(".register(")) continue
            registeredFields.addAll(collectRegisterAdditionalModelFieldReferences(source))
        }
        if (registeredFields.isEmpty()) return changes

        for ((className, fieldName) in registeredFields) {
            val targetFile = classFiles[className]?.singleOrNull() ?: continue
            val original = sources[targetFile] ?: targetFile.readText()
            val migrated = rewriteStaticModelResourceLocationField(original, fieldName, projectDir, sourcesByClass)
            if (migrated == original) continue
            sources[targetFile] = migrated
            if (!dryRun) targetFile.writeText(migrated)
            changes.add(Change(
                file = targetFile,
                line = Regex("""\bModelResourceLocation\s+${Regex.escape(fieldName)}\s*=""")
                    .find(original)
                    ?.let { lineNumberAt(original, it.range.first) }
                    ?: 1,
                description = "Use standalone ModelResourceLocation for RegisterAdditional static model key",
                before = "$className.$fieldName = ModelResourceLocation.inventory(...)",
                after = "$className.$fieldName = ModelResourceLocation.standalone(...)",
                confidence = Confidence.HIGH,
                ruleId = "struct-registeradditional-model-standalone"
            ))
        }
        return changes
    }

    private data class ResolvedResourceLocationExpression(
        val namespace: String,
        val path: String,
        val rewrittenExpression: String
    )

    private fun rewriteRegisterAdditionalStandaloneModelPaths(
        source: String,
        projectDir: Path,
        sourcesByClass: Map<String, String>
    ): String {
        return rewriteRegisterAdditionalRegisterCalls(source) { arg ->
            rewriteRegisteredModelResourceLocationExpression(arg, projectDir, sourcesByClass)
        }
    }

    private fun rewriteRegisterAdditionalRegisterCalls(source: String, transformArg: (String) -> String?): String {
        var result = source
        val parameterPattern = Regex("""\b(?:[A-Za-z_$][\w$]*\.)?RegisterAdditional\s+([A-Za-z_$][\w$]*)\b""")
        var cursor = 0
        while (true) {
            val paramMatch = parameterPattern.find(result, cursor) ?: break
            val openParen = result.lastIndexOf('(', paramMatch.range.first)
            val closeParen = result.indexOf(')', paramMatch.range.last + 1)
            val openBrace = if (closeParen >= 0) result.indexOf('{', closeParen + 1) else -1
            if (openParen < 0 || closeParen < 0 || openBrace < 0) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val semicolon = result.indexOf(';', closeParen + 1)
            if (semicolon >= 0 && semicolon < openBrace) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val params = result.substring(openParen + 1, closeParen)
            if (!params.contains(paramMatch.value)) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val eventParam = paramMatch.groupValues[1]
            val body = result.substring(openBrace + 1, closeBrace)
            val rewrittenBody = rewriteJavaCall(body, "register") { receiver, args ->
                if (receiver != eventParam || args.size != 1) return@rewriteJavaCall null
                val rewrittenArg = transformArg(args[0].trim()) ?: return@rewriteJavaCall null
                "$receiver.register($rewrittenArg)"
            }
            if (rewrittenBody != body) {
                result = result.substring(0, openBrace + 1) + rewrittenBody + result.substring(closeBrace)
                cursor = openBrace + 1 + rewrittenBody.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun collectRegisterAdditionalModelFieldReferences(source: String): Set<Pair<String, String>> {
        val refs = linkedSetOf<Pair<String, String>>()
        val ownerClass = classNameOfJavaSource(source)
        val parameterPattern = Regex("""\b(?:[A-Za-z_$][\w$]*\.)?RegisterAdditional\s+([A-Za-z_$][\w$]*)\b""")
        var cursor = 0
        while (true) {
            val paramMatch = parameterPattern.find(source, cursor) ?: break
            val openParen = source.lastIndexOf('(', paramMatch.range.first)
            val closeParen = source.indexOf(')', paramMatch.range.last + 1)
            val openBrace = if (closeParen >= 0) source.indexOf('{', closeParen + 1) else -1
            if (openParen < 0 || closeParen < 0 || openBrace < 0) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val semicolon = source.indexOf(';', closeParen + 1)
            if (semicolon >= 0 && semicolon < openBrace) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val params = source.substring(openParen + 1, closeParen)
            if (!params.contains(paramMatch.value)) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace < 0) {
                cursor = paramMatch.range.last + 1
                continue
            }
            val eventParam = paramMatch.groupValues[1]
            val body = source.substring(openBrace + 1, closeBrace)
            collectJavaCallArguments(body, "register") { receiver, args ->
                if (receiver == eventParam && args.size == 1) {
                    parseStaticModelResourceLocationReference(args[0].trim(), ownerClass)?.let(refs::add)
                }
            }
            cursor = closeBrace + 1
        }
        return refs
    }

    private fun collectJavaCallArguments(
        source: String,
        methodName: String,
        consumer: (receiver: String, args: List<String>) -> Unit
    ) {
        var cursor = 0
        val token = ".${methodName}("
        while (true) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + methodName.length + 1
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val receiverStart = findExpressionReceiverStart(source, tokenIndex)
            if (receiverStart < 0 || receiverStart >= tokenIndex) {
                cursor = closeParen + 1
                continue
            }
            val receiver = source.substring(receiverStart, tokenIndex).trim()
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            consumer(receiver, args)
            cursor = closeParen + 1
        }
    }

    private fun parseStaticModelResourceLocationReference(arg: String, ownerClass: String?): Pair<String, String>? {
        if (arg.startsWith("ModelResourceLocation.") || arg.startsWith("new ModelResourceLocation(")) return null
        val qualified = Regex("""^([A-Za-z_$][\w$]*)\.([A-Za-z_$][\w$]*)$""").matchEntire(arg)
        if (qualified != null) {
            return qualified.groupValues[1] to qualified.groupValues[2]
        }
        if (ownerClass != null && Regex("""^[A-Za-z_$][\w$]*$""").matches(arg)) {
            return ownerClass to arg
        }
        return null
    }

    private fun rewriteStaticModelResourceLocationField(
        source: String,
        fieldName: String,
        projectDir: Path,
        sourcesByClass: Map<String, String>
    ): String {
        val fieldPattern = Regex(
            """(?m)^[^\r\n;{}]*\bstatic\b[^\r\n;{}]*\bModelResourceLocation\s+${Regex.escape(fieldName)}\s*="""
        )
        val match = fieldPattern.find(source) ?: return source
        val expressionStart = match.range.last + 1
        var cursor = expressionStart
        while (cursor < source.length && source[cursor].isWhitespace()) cursor++
        val callStart = cursor
        val openParen = source.indexOf('(', callStart).takeIf { it >= 0 } ?: return source
        val closeParen = findMatchingParen(source, openParen).takeIf { it >= 0 } ?: return source
        val expressionEnd = closeParen + 1
        val trailing = source.substring(expressionEnd).takeWhile { it.isWhitespace() }
        if (source.getOrNull(expressionEnd + trailing.length) != ';') return source
        val expression = source.substring(callStart, expressionEnd)
        val standalone = rewriteRegisteredModelResourceLocationExpression(expression, projectDir, sourcesByClass)
            ?: modelResourceLocationStandaloneExpression(expression)
            ?: return source
        return source.substring(0, callStart) + standalone + source.substring(expressionEnd)
    }

    private fun rewriteRegisteredModelResourceLocationExpression(
        expression: String,
        projectDir: Path,
        sourcesByClass: Map<String, String>
    ): String? {
        val trimmed = expression.trim()
        val modelExpression = when {
            trimmed.startsWith("ModelResourceLocation.inventory(") || trimmed.startsWith("ModelResourceLocation.standalone(") -> {
                val openParen = trimmed.indexOf('(')
                val closeParen = findMatchingParen(trimmed, openParen)
                if (closeParen != trimmed.length - 1) return null
                trimmed.substring(openParen + 1, closeParen).trim()
            }
            trimmed.startsWith("new ModelResourceLocation(") -> {
                val openParen = trimmed.indexOf('(')
                val closeParen = findMatchingParen(trimmed, openParen)
                if (closeParen != trimmed.length - 1) return null
                val args = splitTopLevelJavaArgs(trimmed.substring(openParen + 1, closeParen))
                if (args.size != 2 || args[1].trim() != "\"inventory\"") return null
                args[0].trim()
            }
            else -> return null
        }
        val rewrittenModel = rewriteStandaloneModelResourcePath(modelExpression, projectDir, sourcesByClass)
        val standalone = "ModelResourceLocation.standalone(${rewrittenModel ?: modelExpression})"
        return if (trimmed.startsWith("ModelResourceLocation.standalone(") && rewrittenModel == null) null else standalone
    }

    private fun rewriteStandaloneModelResourcePath(
        expression: String,
        projectDir: Path,
        sourcesByClass: Map<String, String>
    ): String? {
        val resolved = resolveResourceLocationExpression(expression, sourcesByClass) ?: return null
        if (resolved.path.startsWith("item/")) return null
        if (modelJsonExists(projectDir, resolved.namespace, resolved.path)) return null
        val itemPath = "item/${resolved.path}"
        if (!modelJsonExists(projectDir, resolved.namespace, itemPath)) return null
        return resolved.rewrittenExpression
    }

    private fun resolveResourceLocationExpression(
        expression: String,
        sourcesByClass: Map<String, String>
    ): ResolvedResourceLocationExpression? {
        val trimmed = expression.trim()
        val prefixCall = Regex("""^([A-Za-z_$][\w$]*)\.([A-Za-z_$][\w$]*)\(\s*"([^"]+)"\s*\)$""").matchEntire(trimmed)
        if (prefixCall != null) {
            val className = prefixCall.groupValues[1]
            val methodName = prefixCall.groupValues[2]
            val path = prefixCall.groupValues[3]
            val namespace = resolveResourceLocationFactoryNamespace(className, methodName, sourcesByClass) ?: return null
            return ResolvedResourceLocationExpression(namespace, path, "$className.$methodName(\"item/$path\")")
        }

        val fromNamespaceAndPath = Regex(
            """^ResourceLocation\.fromNamespaceAndPath\(\s*([^,]+)\s*,\s*"([^"]+)"\s*\)$"""
        ).matchEntire(trimmed)
        if (fromNamespaceAndPath != null) {
            val namespaceExpression = fromNamespaceAndPath.groupValues[1].trim()
            val path = fromNamespaceAndPath.groupValues[2]
            val namespace = resolveStringExpression(namespaceExpression, sourcesByClass) ?: return null
            return ResolvedResourceLocationExpression(
                namespace,
                path,
                "ResourceLocation.fromNamespaceAndPath($namespaceExpression, \"item/$path\")"
            )
        }

        val constructor = Regex("""^new ResourceLocation\(\s*([^,]+)\s*,\s*"([^"]+)"\s*\)$""").matchEntire(trimmed)
        if (constructor != null) {
            val namespaceExpression = constructor.groupValues[1].trim()
            val path = constructor.groupValues[2]
            val namespace = resolveStringExpression(namespaceExpression, sourcesByClass) ?: return null
            return ResolvedResourceLocationExpression(namespace, path, "new ResourceLocation($namespaceExpression, \"item/$path\")")
        }
        return null
    }

    private fun resolveResourceLocationFactoryNamespace(
        className: String,
        methodName: String,
        sourcesByClass: Map<String, String>
    ): String? {
        val source = sourcesByClass[className] ?: return null
        val methodPattern = Regex(
            """(?s)\b${Regex.escape(methodName)}\s*\(\s*String\s+([A-Za-z_$][\w$]*)\s*\)\s*\{(.*?)\}"""
        )
        val match = methodPattern.find(source) ?: return null
        val body = match.groupValues[2]
        val namespaceExpression = Regex("""ResourceLocation\.fromNamespaceAndPath\(\s*([^,]+)\s*,""")
            .find(body)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: Regex("""new\s+ResourceLocation\(\s*([^,]+)\s*,""")
                .find(body)
                ?.groupValues
                ?.get(1)
                ?.trim()
            ?: return null
        return resolveStaticStringField(source, namespaceExpression)
            ?: resolveStringExpression(namespaceExpression, sourcesByClass + (className to source))
    }

    private fun resolveStringExpression(expression: String, sourcesByClass: Map<String, String>): String? {
        val trimmed = expression.trim()
        if (Regex(""""(?:\\.|[^"\\])*"""").matches(trimmed)) return trimmed.trim('"')
        val fieldRef = Regex("""^([A-Za-z_$][\w$]*)\.([A-Za-z_$][\w$]*)$""").matchEntire(trimmed)
        if (fieldRef != null) {
            val source = sourcesByClass[fieldRef.groupValues[1]] ?: return null
            return resolveStaticStringField(source, fieldRef.groupValues[2])
        }
        return sourcesByClass.values.asSequence()
            .mapNotNull { resolveStaticStringField(it, trimmed) }
            .distinct()
            .singleOrNull()
    }

    private fun resolveStaticStringField(source: String, fieldName: String): String? =
        Regex("""(?m)\bstatic\s+final\s+String\s+${Regex.escape(fieldName)}\s*=\s*"([^"]+)"""")
            .find(source)
            ?.groupValues
            ?.get(1)

    private fun modelJsonExists(projectDir: Path, namespace: String, modelPath: String): Boolean {
        val relative = Path.of("assets", namespace, "models", "$modelPath.json")
        return listOf(
            projectDir.resolve("src/generated/resources"),
            projectDir.resolve("src/main/resources")
        ).any { it.resolve(relative).exists() }
    }

    private fun modelResourceLocationStandaloneExpression(expression: String): String? {
        val trimmed = expression.trim()
        if (trimmed.startsWith("ModelResourceLocation.standalone(")) return null
        if (trimmed.startsWith("ModelResourceLocation.inventory(")) {
            val openParen = trimmed.indexOf('(')
            val closeParen = findMatchingParen(trimmed, openParen)
            if (closeParen == trimmed.length - 1) {
                return "ModelResourceLocation.standalone(${trimmed.substring(openParen + 1, closeParen).trim()})"
            }
        }
        if (trimmed.startsWith("new ModelResourceLocation(")) {
            val openParen = trimmed.indexOf('(')
            val closeParen = findMatchingParen(trimmed, openParen)
            if (closeParen == trimmed.length - 1) {
                val args = splitTopLevelJavaArgs(trimmed.substring(openParen + 1, closeParen))
                if (args.size == 2 && args[1].trim() == "\"inventory\"") {
                    return "ModelResourceLocation.standalone(${args[0].trim()})"
                }
            }
        }
        return null
    }

    private fun migrateVertexConsumerPoseNormals(source: String): String {
        if (!source.contains(".setNormal(") && !source.contains(".normal(")) return source

        var result = source
        result = Regex("""((?:[A-Za-z_$][\w$]*\.)*last\(\))\.setNormal\(\)""")
            .replace(result, "$1.normal()")
        result = Regex("""\.(?:setNormal|normal)\(\s*([A-Za-z_$][\w$]*)\.normal\(\)\s*,""")
            .replace(result, ".setNormal($1,")
        result = Regex("""\.(?:setNormal|normal)\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*\(\))*)\.normal\(\)\s*,""")
            .replace(result, ".setNormal($1,")
        if (!result.contains("Matrix3f")) return result
        val poseNormalReceiver = """[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\([^()]*\))?)*"""
        val normalToPose = Regex(
            """\bMatrix3f\s+([A-Za-z_$][\w$]*)\s*=\s*($poseNormalReceiver)\.normal\(\)\s*;"""
        ).findAll(result).associate { it.groupValues[1] to it.groupValues[2] }
        val poseNormalMethodIndexes = linkedMapOf<String, MutableSet<Int>>()
        val methodPattern = Regex(
            """(?m)((?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+([A-Za-z_$][\w$]*)\s*)\(([^)]*)\)\s*\{"""
        )

        var changed = true
        while (changed) {
            changed = false
            var cursor = 0
            while (true) {
                val method = methodPattern.find(result, cursor) ?: break
                val openBrace = result.indexOf('{', method.range.first)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
                if (openBrace < 0 || closeBrace < 0) {
                    cursor = method.range.last + 1
                    continue
                }
                val params = splitTopLevelJavaArgs(method.groupValues[3])
                if (params.none { it.contains("Matrix3f") }) {
                    cursor = closeBrace + 1
                    continue
                }
                val body = result.substring(openBrace + 1, closeBrace)
                val normalIndexes = linkedSetOf<Int>()
                val migratedParams = params.mapIndexed { index, param ->
                    val paramMatch = Regex("""\bMatrix3f\s+([A-Za-z_$][\w$]*)\b""").find(param)
                    val paramName = paramMatch?.groupValues?.get(1)
                    if (paramName != null &&
                        (body.contains(".setNormal($paramName,") ||
                            body.contains(".normal($paramName,") ||
                            passesParameterToKnownPoseNormalHelper(body, paramName, poseNormalMethodIndexes))) {
                        normalIndexes += index
                        param.replace(Regex("""\bMatrix3f\s+${Regex.escape(paramName)}\b"""), "PoseStack.Pose $paramName")
                    } else {
                        param
                    }
                }
                if (normalIndexes.isNotEmpty()) {
                    val replacementSignature = method.groupValues[1] + "(" + migratedParams.joinToString(", ") { it.trim() } + ")"
                    result = result.substring(0, method.range.first) +
                        replacementSignature +
                        result.substring(openBrace)
                    poseNormalMethodIndexes.getOrPut(method.groupValues[2]) { linkedSetOf() }.addAll(normalIndexes)
                    val delta = replacementSignature.length - (openBrace - method.range.first)
                    cursor = closeBrace + delta + 1
                    changed = true
                } else {
                    cursor = closeBrace + 1
                }
            }
        }

        poseNormalMethodIndexes.forEach { (methodName, indexes) ->
            result = rewriteJavaInvocationArguments(result, methodName) { args ->
                if (indexes.any { it >= args.size }) return@rewriteJavaInvocationArguments null
                val migrated = args.mapIndexed { index, arg ->
                    if (index in indexes) poseNormalArgumentToPose(arg, normalToPose) else arg
                }
                if (migrated == args) null else migrated
            }
        }
        result = migrateLocalPoseNormalSetNormalCalls(result)
        result = removeUnusedPoseNormalMatrixLocals(result)
        if (result.contains("PoseStack.Pose")) {
            result = addImportIfMissing(result, "com.mojang.blaze3d.vertex.PoseStack")
        }

        val withoutMatrix3fImport = removeImport(result, "org.joml.Matrix3f")
        if (!Regex("""\bMatrix3f\b""").containsMatchIn(withoutMatrix3fImport)) {
            result = withoutMatrix3fImport
        }
        return result
    }

    private fun passesParameterToKnownPoseNormalHelper(
        body: String,
        paramName: String,
        poseNormalMethodIndexes: Map<String, Set<Int>>
    ): Boolean {
        if (poseNormalMethodIndexes.isEmpty()) return false
        poseNormalMethodIndexes.forEach { (methodName, indexes) ->
            var cursor = 0
            val token = "$methodName("
            while (true) {
                val tokenIndex = body.indexOf(token, cursor)
                if (tokenIndex < 0) break
                if (tokenIndex > 0 && (body[tokenIndex - 1].isLetterOrDigit() || body[tokenIndex - 1] == '_' || body[tokenIndex - 1] == '$')) {
                    cursor = tokenIndex + token.length
                    continue
                }
                val openParen = tokenIndex + methodName.length
                val closeParen = findMatchingParen(body, openParen)
                if (closeParen < 0) {
                    cursor = tokenIndex + token.length
                    continue
                }
                val args = splitTopLevelJavaArgs(body.substring(openParen + 1, closeParen))
                if (indexes.any { it < args.size && args[it].trim() == paramName }) {
                    return true
                }
                cursor = closeParen + 1
            }
        }
        return false
    }

    private fun poseNormalArgumentToPose(arg: String, normalToPose: Map<String, String>): String {
        val trimmed = arg.trim()
        normalToPose[trimmed]?.let { return it }
        return when {
            trimmed.endsWith(".normal()") -> trimmed.removeSuffix(".normal()")
            trimmed.endsWith(".setNormal()") -> trimmed.removeSuffix(".setNormal()")
            else -> arg
        }
    }

    private fun migratePoseNormalHelperParametersByIndex(
        source: String,
        normalToPose: Map<String, String>
    ): String {
        if (normalToPose.isEmpty() || !source.contains("Matrix3f")) return source
        var result = source
        val methodParamIndexes = linkedMapOf<String, Set<Int>>()
        val methodPattern = Regex(
            """(?m)((?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+([A-Za-z_$][\w$]*)\s*)\(([^)]*)\)\s*\{"""
        )
        var cursor = 0
        while (true) {
            val method = methodPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', method.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = method.range.last + 1
                continue
            }
            val params = splitTopLevelJavaArgs(method.groupValues[3])
            val body = result.substring(openBrace + 1, closeBrace)
            val normalIndexes = linkedSetOf<Int>()
            val migratedParams = params.mapIndexed { index, param ->
                val paramMatch = Regex("""\bMatrix3f\s+([A-Za-z_$][\w$]*)\b""").find(param)
                val paramName = paramMatch?.groupValues?.get(1)
                if (paramName != null &&
                    (body.contains(".setNormal($paramName,") || body.contains(".normal($paramName,"))) {
                    normalIndexes += index
                    param.replace(Regex("""\bMatrix3f\s+${Regex.escape(paramName)}\b"""), "PoseStack.Pose $paramName")
                } else {
                    param
                }
            }
            if (normalIndexes.isNotEmpty()) {
                val replacementSignature = method.groupValues[1] + "(" + migratedParams.joinToString(", ") { it.trim() } + ")"
                result = result.substring(0, method.range.first) +
                    replacementSignature +
                    result.substring(openBrace)
                methodParamIndexes[method.groupValues[2]] = normalIndexes
                val delta = replacementSignature.length - (openBrace - method.range.first)
                cursor = closeBrace + delta + 1
            } else {
                cursor = closeBrace + 1
            }
        }

        methodParamIndexes.forEach { (methodName, indexes) ->
            result = rewriteJavaInvocationArguments(result, methodName) { args ->
                if (indexes.any { it >= args.size }) return@rewriteJavaInvocationArguments null
                val migrated = args.mapIndexed { index, arg ->
                    if (index in indexes) normalToPose[arg.trim()] ?: arg else arg
                }
                if (migrated == args) null else migrated
            }
        }
        return result
    }

    private fun removeUnusedPoseNormalMatrixLocals(source: String): String {
        var result = source
        val methodPattern = Regex("""(?m)(?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^)]*\)\s*\{""")
        var cursor = 0
        while (true) {
            val method = methodPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', method.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = method.range.last + 1
                continue
            }
            var body = result.substring(openBrace + 1, closeBrace)
            val originalBody = body
            val poseNormalReceiver = """[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\([^()]*\))?)*"""
            val declaration = Regex("""(?m)^[ \t]*Matrix3f\s+([A-Za-z_$][\w$]*)\s*=\s*$poseNormalReceiver\.normal\(\)\s*;\s*\r?\n""")
            var localCursor = 0
            while (true) {
                val match = declaration.find(body, localCursor) ?: break
                val variable = match.groupValues[1]
                val withoutDeclaration = body.removeRange(match.range)
                if (!Regex("""\b${Regex.escape(variable)}\b""").containsMatchIn(withoutDeclaration)) {
                    body = withoutDeclaration
                    localCursor = match.range.first
                } else {
                    localCursor = match.range.last + 1
                }
            }
            if (body != originalBody) {
                result = result.substring(0, openBrace + 1) + body + result.substring(closeBrace)
                cursor = openBrace + 1 + body.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun migrateLocalPoseNormalSetNormalCalls(source: String): String {
        var result = source
        var cursor = 0
        val methodPattern = Regex("""(?m)(?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^)]*\)\s*\{""")
        while (true) {
            val match = methodPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val localNormalToPose = Regex(
                """\bMatrix3f\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\([^()]*\))?)*)\.normal\(\)\s*;"""
            ).findAll(body).associate { it.groupValues[1] to it.groupValues[2] }
            if (localNormalToPose.isEmpty()) {
                cursor = closeBrace + 1
                continue
            }
            var rewrittenBody = body
            for ((normal, pose) in localNormalToPose) {
                rewrittenBody = Regex("""\.setNormal\(\s*${Regex.escape(normal)}\s*,""")
                    .replace(rewrittenBody, ".setNormal($pose,")
            }
            if (rewrittenBody != body) {
                result = result.substring(0, openBrace + 1) + rewrittenBody + result.substring(closeBrace)
                cursor = openBrace + 1 + rewrittenBody.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun migrateLegacyGuiLayerRegistrationSource(source: String): String {
        if (!source.contains("VanillaGuiOverlay") && !source.contains("registerAbove(") && !source.contains("registerBelow(")) {
            return source
        }

        var result = source
        var needsVanillaGuiLayers = false
        var needsResourceLocation = false
        val vanillaLayerNames = mapOf(
            "HOTBAR" to "HOTBAR",
            "MOUNT_HEALTH" to "VEHICLE_HEALTH",
            "CROSSHAIR" to "CROSSHAIR",
            "EXPERIENCE_BAR" to "EXPERIENCE_BAR",
            "PLAYER_HEALTH" to "PLAYER_HEALTH",
            "ARMOR_LEVEL" to "ARMOR_LEVEL",
            "FOOD_LEVEL" to "FOOD_LEVEL",
            "AIR_LEVEL" to "AIR_LEVEL",
            "BOSS_OVERLAY" to "BOSS_OVERLAY",
            "CHAT" to "CHAT",
            "TAB_LIST" to "TAB_LIST"
        )
        for ((oldName, newName) in vanillaLayerNames) {
            val before = result
            result = result.replace("VanillaGuiOverlay.$oldName.id()", "VanillaGuiLayers.$newName")
            if (result != before) needsVanillaGuiLayers = true
        }

        val modIdExpression = Regex("""@(?:Mod\.)?EventBusSubscriber\s*\([^)]*\bmodid\s*=\s*([^,\)]+)""")
            .find(result)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: Regex("""@Mod\s*\(\s*([^)\r\n]+)\s*\)""")
                .find(result)
                ?.groupValues
                ?.get(1)
                ?.trim()
            ?: Regex("""(?m)\b(?:public\s+)?static\s+final\s+String\s+(?:MOD_ID|MODID|ID)\s*=\s*([^;\r\n]+);""")
                .find(result)
                ?.groupValues
                ?.get(1)
                ?.trim()

        fun migrateRegisterLayerCall(methodName: String, expectedArgs: Int): Unit {
            result = rewriteJavaInvocationArguments(result, methodName) { args ->
                if (args.size != expectedArgs) return@rewriteJavaInvocationArguments null
                val idIndex = expectedArgs - 2
                val layerIndex = expectedArgs - 1
                val rawLayerId = args[idIndex].trim()
                if (!Regex(""""(?:\\.|[^"\\])*"""").matches(rawLayerId)) return@rewriteJavaInvocationArguments null
                val namespace = modIdExpression ?: return@rewriteJavaInvocationArguments null
                val migrated = args.toMutableList()
                migrated[idIndex] = "ResourceLocation.fromNamespaceAndPath($namespace, ${rawLayerId})"
                migrated[layerIndex] = migrateLegacyGuiLayerLambda(migrated[layerIndex])
                needsResourceLocation = true
                migrated
            }
        }

        migrateRegisterLayerCall("registerAbove", 3)
        migrateRegisterLayerCall("registerBelow", 3)
        migrateRegisterLayerCall("registerAboveAll", 2)
        migrateRegisterLayerCall("registerBelowAll", 2)

        result = migrateLegacyGuiLayerLambdas(result)

        if (needsVanillaGuiLayers) {
            result = addImportIfMissing(result, "net.neoforged.neoforge.client.gui.VanillaGuiLayers")
        }
        if (needsResourceLocation) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceLocation")
        }
        result = removeImport(result, "net.neoforged.neoforge.client.gui.overlay.VanillaGuiOverlay")
        result = removeImport(result, "net.minecraftforge.client.gui.overlay.VanillaGuiOverlay")
        return result
    }

    private fun migrateLegacyGuiLayerLambdas(source: String): String {
        var result = source
        result = rewriteJavaInvocationArguments(result, "registerAbove") { args ->
            if (args.size == 3) {
                val migrated = args.toMutableList()
                migrated[2] = migrateLegacyGuiLayerLambda(args[2])
                if (migrated == args) null else migrated
            } else {
                null
            }
        }
        result = rewriteJavaInvocationArguments(result, "registerBelow") { args ->
            if (args.size == 3) {
                val migrated = args.toMutableList()
                migrated[2] = migrateLegacyGuiLayerLambda(args[2])
                if (migrated == args) null else migrated
            } else {
                null
            }
        }
        return result
    }

    private fun migrateLegacyGuiLayerLambda(lambdaSource: String): String {
        val lambda = lambdaSource.trim()
        val match = Regex(
            """^\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)\s*->\s*\{([\s\S]*)}$"""
        ).find(lambda) ?: return lambdaSource
        val guiName = match.groupValues[1]
        val graphicsName = match.groupValues[2]
        val partialTickName = match.groupValues[3]
        val widthName = match.groupValues[4]
        val heightName = match.groupValues[5]
        val body = match.groupValues[6]
        val locals = mutableListOf<String>()
        if (Regex("""\b${Regex.escape(guiName)}\b""").containsMatchIn(body)) {
            locals += "net.minecraft.client.gui.Gui $guiName = net.minecraft.client.Minecraft.getInstance().gui;"
        }
        if (Regex("""\b${Regex.escape(partialTickName)}\b""").containsMatchIn(body)) {
            locals += "float $partialTickName = deltaTracker.getGameTimeDeltaPartialTick(false);"
        }
        if (Regex("""\b${Regex.escape(widthName)}\b""").containsMatchIn(body)) {
            locals += "int $widthName = $graphicsName.guiWidth();"
        }
        if (Regex("""\b${Regex.escape(heightName)}\b""").containsMatchIn(body)) {
            locals += "int $heightName = $graphicsName.guiHeight();"
        }
        val prefix = if (locals.isEmpty()) "" else locals.joinToString(separator = "\n", postfix = "\n") { "\t\t\t$it" }
        return "($graphicsName, deltaTracker) -> {\n$prefix$body}"
    }

    private fun migrateLegacyGuiSurvivalElementsSource(source: String): String {
        if (!source.contains(".shouldDrawSurvivalElements()")) return source
        return Regex("""\b[A-Za-z_$][\w$]*\.shouldDrawSurvivalElements\(\)""")
            .replace(
                source,
                "net.minecraft.client.Minecraft.getInstance().gameMode.canHurtPlayer() && !net.minecraft.client.Minecraft.getInstance().options.hideGui"
            )
    }

    private fun migrateLegacyJumpFromGroundVisibility(source: String): String =
        Regex("""(?m)^(\s*)protected(\s+void\s+jumpFromGround\s*\(\s*\))""")
            .replace(source, "$1public$2")

    private fun migrateTextureAtlasSpriteFloatCoordinateCalls(source: String): String {
        var result = source
        fun needsFloatCast(arg: String): Boolean {
            val trimmed = arg.trim()
            return !trimmed.startsWith("(float)") &&
                (
                    "(double)" in trimmed ||
                        Regex("""\d(?:\.\d+)?[dD]\b""").containsMatchIn(trimmed) ||
                        Regex("""\bdouble\b""").containsMatchIn(trimmed)
                    )
        }
        result = rewriteJavaCall(result, "getU") { receiver, args ->
            if (args.size == 1 && needsFloatCast(args[0])) {
                "$receiver.getU((float) (${args[0]}))"
            } else {
                null
            }
        }
        result = rewriteJavaCall(result, "getV") { receiver, args ->
            if (args.size == 1 && needsFloatCast(args[0])) {
                "$receiver.getV((float) (${args[0]}))"
            } else {
                null
            }
        }
        return result
    }

    private fun migratePartialTickAccessors(source: String): String {
        if (!source.contains("getPartialTick()") &&
            !source.contains("getFrameTime()") &&
            !source.contains("getDeltaFrameTime()")) return source
        var result = source.replace(
            "Minecraft.getInstance().getPartialTick()",
            "Minecraft.getInstance().getTimer().getGameTimeDeltaPartialTick(false)"
        ).replace(
            "Minecraft.getInstance().getFrameTime()",
            "Minecraft.getInstance().getTimer().getGameTimeDeltaPartialTick(false)"
        ).replace(
            "Minecraft.getInstance().getDeltaFrameTime()",
            "Minecraft.getInstance().getTimer().getGameTimeDeltaPartialTick(false)"
        )

        val minecraftVariables = Regex("""\bMinecraft\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in minecraftVariables) {
            result = result.replace(
                "$variable.getPartialTick()",
                "$variable.getTimer().getGameTimeDeltaPartialTick(false)"
            )
            result = result.replace(
                "$variable.getFrameTime()",
                "$variable.getTimer().getGameTimeDeltaPartialTick(false)"
            )
            result = result.replace(
                "$variable.getDeltaFrameTime()",
                "$variable.getTimer().getGameTimeDeltaPartialTick(false)"
            )
        }

        result = rewritePartialTickWithinRenderHighlightMethods(result)
        result = rewritePartialTickWithinDeltaTrackerEvents(result)

        return result
    }

    private fun rewritePartialTickWithinRenderHighlightMethods(source: String): String {
        var result = source
        var cursor = 0
        val methodWithRenderHighlight = Regex(
            """\([^)]*\b(?:net\.neoforged\.neoforge\.client\.event\.)?RenderHighlightEvent(?:\.[A-Za-z_$][\w$]*)?\s+([A-Za-z_$][\w$]*)[^)]*\)\s*\{"""
        )
        while (true) {
            val match = methodWithRenderHighlight.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val variable = match.groupValues[1]
            val body = result.substring(openBrace + 1, closeBrace)
            val rewritten = body.replace(
                "$variable.getPartialTick()",
                "$variable.getDeltaTracker().getGameTimeDeltaPartialTick(false)"
            )
            if (rewritten != body) {
                result = result.substring(0, openBrace + 1) + rewritten + result.substring(closeBrace)
                cursor = openBrace + 1 + rewritten.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun rewritePartialTickWithinDeltaTrackerEvents(source: String): String {
        var result = source
        var cursor = 0
        val methodWithDeltaTrackerPartial = Regex(
            """\([^)]*\b(?:net\.neoforged\.neoforge\.client\.event\.)?(RenderLevelStageEvent)\s+([A-Za-z_$][\w$]*)[^)]*\)\s*\{"""
        )
        while (true) {
            val match = methodWithDeltaTrackerPartial.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val variable = match.groupValues[2]
            val body = result.substring(openBrace + 1, closeBrace)
            val rewritten = body.replace(
                "$variable.getPartialTick()",
                "$variable.getPartialTick().getGameTimeDeltaPartialTick(false)"
            )
            if (rewritten != body) {
                result = result.substring(0, openBrace + 1) + rewritten + result.substring(closeBrace)
                cursor = openBrace + 1 + rewritten.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun migrateLegacyEventBusPostBooleans(source: String): String {
        if (!source.contains("EVENT_BUS.post(")) return source
        return rewriteJavaCall(source, "post") { receiver, args ->
            if (!receiver.endsWith("EVENT_BUS") || args.size != 1) return@rewriteJavaCall null
            "$receiver.post(${args[0]}).isCanceled()"
        }
    }

    private fun migrateLegacyFollowOwnerGoalConstructors(source: String): String {
        if (!source.contains("new FollowOwnerGoal(")) return source
        return rewriteJavaNew(source, "FollowOwnerGoal") { args ->
            if (args.size == 5) "new FollowOwnerGoal(${args.take(4).joinToString(", ")})" else null
        }
    }

    private fun migrateLegacyDyeColorFloatArrays(source: String): String {
        if (!source.contains("getTextureDiffuseColors()") && !source.contains("Sheep.getColorArray(")) {
            return source
        }

        var result = source
        val packedColorVariables = linkedSetOf<String>()
        result = Regex("""\b(?:final\s+)?float\[\]\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]+?)\.getTextureDiffuseColors\(\)\s*;""")
            .replace(result) { match ->
                val variable = match.groupValues[1]
                packedColorVariables += variable
                "int $variable = ${match.groupValues[2].trim()}.getTextureDiffuseColor();"
            }
        result = Regex("""\b(?:final\s+)?float\[\]\s+([A-Za-z_$][\w$]*)\s*=\s*Sheep\.getColorArray\(\s*([^;\r\n]+?)\s*\)\s*;""")
            .replace(result) { match ->
                val variable = match.groupValues[1]
                packedColorVariables += variable
                "int $variable = Sheep.getColor(${match.groupValues[2].trim()});"
            }
        for (variable in packedColorVariables) {
            val escaped = Regex.escape(variable)
            result = result.replace(Regex("""\b$escaped\s*\[\s*0\s*\]"""), "FastColor.ARGB32.red($variable) / 255.0F")
            result = result.replace(Regex("""\b$escaped\s*\[\s*1\s*\]"""), "FastColor.ARGB32.green($variable) / 255.0F")
            result = result.replace(Regex("""\b$escaped\s*\[\s*2\s*\]"""), "FastColor.ARGB32.blue($variable) / 255.0F")
        }
        return if (packedColorVariables.isNotEmpty()) addImportIfMissing(result, "net.minecraft.util.FastColor") else result
    }

    private fun migrateLegacyRendererSetupRotations(source: String): String {
        if (!source.contains("setupRotations(") || !source.contains("PoseStack")) return source
        var result = source
        val signaturePattern = Regex(
            """(?m)(protected\s+void\s+setupRotations\s*\(\s*([^,]+)\s+([A-Za-z_$][\w$]*)\s*,\s*PoseStack\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*\))"""
        )
        var cursor = 0
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val signature = match.value
            if (signature.contains("float scale")) {
                cursor = closeBrace + 1
                continue
            }
            val entityType = match.groupValues[2].trim()
            val entity = match.groupValues[3]
            val pose = match.groupValues[4]
            val age = match.groupValues[5]
            val yaw = match.groupValues[6]
            val partial = match.groupValues[7]
            val migratedSignature =
                "protected void setupRotations($entityType $entity, PoseStack $pose, float $age, float $yaw, float scale, float $partial)"
            var body = result.substring(openBrace + 1, closeBrace)
            body = Regex(
                """super\.setupRotations\(\s*${Regex.escape(entity)}\s*,\s*${Regex.escape(pose)}\s*,\s*${Regex.escape(age)}\s*,\s*${Regex.escape(yaw)}\s*,\s*${Regex.escape(partial)}\s*\)"""
            ).replace(body, "super.setupRotations($entity, $pose, $age, $yaw, scale, $partial)")
            result = result.substring(0, match.range.first) +
                migratedSignature +
                result.substring(openBrace, openBrace + 1) +
                body +
                result.substring(closeBrace)
            cursor = match.range.first + migratedSignature.length + 1 + body.length
        }
        return result
    }

    private fun migrateLegacySkinManagerTextureLookups(source: String): String {
        if (!source.contains("DefaultPlayerSkin") &&
            !source.contains("getInsecureSkinInformation(") &&
            !source.contains("getSkinTextureLocation()")) {
            return source
        }
        var result = source
        var needsPlayerSkin = false

        result = result.replace("DefaultPlayerSkin.getDefaultSkin()", "DefaultPlayerSkin.getDefaultTexture()")
        result = Regex("""DefaultPlayerSkin\.getDefaultSkin\(\s*([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result, "DefaultPlayerSkin.get($1).texture()")
        result = Regex("""DefaultPlayerSkin\.getSkinModelName\(\s*([A-Za-z_$][\w$]*)\s*\)\.equals\(\s*"slim"\s*\)""")
            .replace(result, "DefaultPlayerSkin.get($1).model().id().equals(\"slim\")")
        result = Regex("""\b([A-Za-z_$][\w$]*)\.getSkinTextureLocation\(\)""")
            .replace(result, "$1.getSkin().texture()")

        val legacyProfileTextureBlock = Regex(
            """(?s)Map\s*<\s*MinecraftProfileTexture\.Type\s*,\s*MinecraftProfileTexture\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.getSkinManager\(\)\.getInsecureSkinInformation\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;\s*""" +
                """if\s*\(\s*\1\.containsKey\(MinecraftProfileTexture\.Type\.SKIN\)\s*\)\s*\{\s*""" +
                """MinecraftProfileTexture\s+([A-Za-z_$][\w$]*)\s*=\s*\1\.get\(MinecraftProfileTexture\.Type\.SKIN\)\s*;\s*""" +
                """([A-Za-z_$][\w$]*)\s*=\s*\2\.getSkinManager\(\)\.registerTexture\(\s*\1\.get\(MinecraftProfileTexture\.Type\.SKIN\)\s*,\s*MinecraftProfileTexture\.Type\.SKIN\s*\)\s*;\s*""" +
                """if\s*\(\s*Objects\.equals\(\s*\4\.getMetadata\(\s*"model"\s*\)\s*,\s*"slim"\s*\)\s*\)\s*this\.model\s*=\s*this\.slimModel\s*;\s*""" +
                """\}\s*else\s*\{\s*UUID\s+([A-Za-z_$][\w$]*)\s*=\s*UUIDUtil\.getOrCreatePlayerUUID\(\s*\3\s*\)\s*;\s*""" +
                """\5\s*=\s*DefaultPlayerSkin\.getDefaultSkin\(\s*\6\s*\)\s*;\s*""" +
                """if\s*\(\s*DefaultPlayerSkin\.getSkinModelName\(\s*\6\s*\)\.equals\(\s*"slim"\s*\)\s*\)\s*this\.model\s*=\s*this\.slimModel\s*;\s*""" +
                """\}"""
        )
        result = legacyProfileTextureBlock.replace(result) { match ->
            needsPlayerSkin = true
            val minecraft = match.groupValues[2]
            val profile = match.groupValues[3]
            val textureVariable = match.groupValues[5]
            "PlayerSkin playerSkin = $minecraft.getSkinManager().getInsecureSkin($profile);\n" +
                "\t\t\t$textureVariable = playerSkin.texture();\n" +
                "\t\t\tif (playerSkin.model().id().equals(\"slim\")) this.model = this.slimModel;"
        }
        val migratedDefaultProfileTextureBlock = Regex(
            """(?s)Map\s*<\s*MinecraftProfileTexture\.Type\s*,\s*MinecraftProfileTexture\s*>\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.getSkinManager\(\)\.getInsecureSkinInformation\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;\s*""" +
                """if\s*\(\s*\1\.containsKey\(MinecraftProfileTexture\.Type\.SKIN\)\s*\)\s*\{\s*""" +
                """MinecraftProfileTexture\s+([A-Za-z_$][\w$]*)\s*=\s*\1\.get\(MinecraftProfileTexture\.Type\.SKIN\)\s*;\s*""" +
                """([A-Za-z_$][\w$]*)\s*=\s*\2\.getSkinManager\(\)\.registerTexture\(\s*\1\.get\(MinecraftProfileTexture\.Type\.SKIN\)\s*,\s*MinecraftProfileTexture\.Type\.SKIN\s*\)\s*;\s*""" +
                """if\s*\(\s*Objects\.equals\(\s*\4\.getMetadata\(\s*"model"\s*\)\s*,\s*"slim"\s*\)\s*\)\s*this\.model\s*=\s*this\.slimModel\s*;\s*""" +
                """\}\s*else\s*\{\s*UUID\s+([A-Za-z_$][\w$]*)\s*=\s*UUIDUtil\.getOrCreatePlayerUUID\(\s*\3\s*\)\s*;\s*""" +
                """\5\s*=\s*DefaultPlayerSkin\.get\(\s*\6\s*\)\.texture\(\)\s*;\s*""" +
                """if\s*\(\s*DefaultPlayerSkin\.get\(\s*\6\s*\)\.model\(\)\.id\(\)\.equals\(\s*"slim"\s*\)\s*\)\s*this\.model\s*=\s*this\.slimModel\s*;\s*""" +
                """\}"""
        )
        result = migratedDefaultProfileTextureBlock.replace(result) { match ->
            needsPlayerSkin = true
            val minecraft = match.groupValues[2]
            val profile = match.groupValues[3]
            val textureVariable = match.groupValues[5]
            "PlayerSkin playerSkin = $minecraft.getSkinManager().getInsecureSkin($profile);\n" +
                "\t\t\t$textureVariable = playerSkin.texture();\n" +
                "\t\t\tif (playerSkin.model().id().equals(\"slim\")) this.model = this.slimModel;"
        }

        if (needsPlayerSkin) {
            result = addImportIfMissing(result, "net.minecraft.client.resources.PlayerSkin")
        }
        val withoutProfileTexture = removeImport(result, "com.mojang.authlib.minecraft.MinecraftProfileTexture")
        if (!Regex("""\bMinecraftProfileTexture\b""").containsMatchIn(withoutProfileTexture)) {
            result = withoutProfileTexture
        }
        val withoutUuidUtil = removeImport(result, "net.minecraft.core.UUIDUtil")
        if (!Regex("""\bUUIDUtil\b""").containsMatchIn(withoutUuidUtil)) {
            result = withoutUuidUtil
        }
        val withoutMap = removeImport(result, "java.util.Map")
        if (!Regex("""\bMap\s*<""").containsMatchIn(withoutMap)) {
            result = withoutMap
        }
        val withoutObjects = removeImport(result, "java.util.Objects")
        if (!Regex("""\bObjects\b""").containsMatchIn(withoutObjects)) {
            result = withoutObjects
        }
        val withoutUuid = removeImport(result, "java.util.UUID")
        if (!Regex("""\bUUID\b""").containsMatchIn(withoutUuid)) {
            result = withoutUuid
        }
        return result
    }

    private fun migrateLegacyMobExperienceOverrides(source: String): String {
        if (!source.contains("dropExperience()") && !source.contains("getExperienceReward()")) {
            return source
        }

        var result = source
        result = Regex(
            """(?m)^([ \t]*)@Override\s*\r?\n[ \t]*protected\s+void\s+dropExperience\s*\(\s*\)\s*\{\s*\r?\n[ \t]*\}"""
        ).replace(result) { match ->
            val indent = match.groupValues[1]
            "${indent}@Override\n${indent}public boolean shouldDropExperience() {\n${indent}\treturn false;\n${indent}}"
        }
        result = Regex("""protected\s+void\s+dropExperience\s*\(\s*\)""")
            .replace(result, "protected void dropExperience(net.minecraft.world.entity.Entity entity)")
        result = Regex("""public\s+int\s+getExperienceReward\s*\(\s*\)""")
            .replace(result, "protected int getBaseExperienceReward()")
        return result
    }

    private fun migrateLegacyWolfModelLayerDefinitions(source: String): String =
        source.replace(
            "WolfModel::createBodyLayer",
            "() -> LayerDefinition.create(WolfModel.createMeshDefinition(CubeDeformation.NONE), 64, 32)"
        )

    private fun migrateLossyCompoundAssignments(source: String): String {
        if (!source.contains("+=") && !source.contains("-=") && !source.contains("*=") && !source.contains("/=")) {
            return source
        }

        val floatNames = collectPrimitiveNames(source, "float")
        val doubleNames = collectPrimitiveNames(source, "double")
        val intNames = collectPrimitiveNames(source, "int")
        val floatLikeFields = setOf("xRot", "yRot", "zRot", "quadSize", "rCol", "gCol", "bCol", "alpha")
        val lhsPattern = """[A-Za-z_$][\w$]*(?:\[[^\]\r\n]+\])?(?:\.[A-Za-z_$][\w$]*(?:\[[^\]\r\n]+\])?)*"""
        return Regex("""(?m)^([ \t]*)($lhsPattern)\s*([+\-*/])=\s*([^;\r\n]+);""")
            .replace(source) { match ->
                val lhs = match.groupValues[2].trim()
                val operator = match.groupValues[3]
                val rhs = match.groupValues[4].trim()
                val lastName = lhs.substringAfterLast('.').substringBefore('[')
                val targetType = when {
                    lastName in floatNames || lastName in floatLikeFields -> "float"
                    lastName in intNames -> "int"
                    else -> null
                } ?: return@replace match.value
                if (!compoundAssignmentNeedsExplicitNarrowing(targetType, rhs, floatNames, doubleNames)) {
                    return@replace match.value
                }
                val narrowedRhs = when (targetType) {
                    "float" -> "($targetType) ($rhs)"
                    else -> "($targetType) ($rhs)"
                }
                "${match.groupValues[1]}$lhs $operator= $narrowedRhs;"
            }
    }

    private fun collectPrimitiveNames(source: String, primitive: String): Set<String> =
        Regex("""\b${Regex.escape(primitive)}\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()

    private fun compoundAssignmentNeedsExplicitNarrowing(
        targetType: String,
        rhs: String,
        floatNames: Set<String>,
        doubleNames: Set<String>
    ): Boolean {
        if (rhs.startsWith("($targetType)")) return false
        val tokens = Regex("""[A-Za-z_$][\w$]*""").findAll(rhs).map { it.value }.toSet()
        return when (targetType) {
            "float" ->
                (rhs.contains("Math.PI") && !rhs.contains("(float) Math.PI") && !rhs.contains("(float)Math.PI")) ||
                    Regex("""\d+\.\d+(?![0-9Ff])""").containsMatchIn(rhs) ||
                    tokens.any { it in doubleNames }
            "int" ->
                Regex("""\d+\.\d+[Ff]?(?![0-9A-Za-z_$])""").containsMatchIn(rhs) ||
                    tokens.any { it in floatNames || it in doubleNames }
            else -> false
        }
    }

    private fun migrateLegacyEmptyUnsidedItemHandlerOverrides(source: String): String {
        if (!source.contains("createUnSidedHandler(")) return source
        var result = Regex(
            """(?s)\n[ \t]*@Override\s*\r?\n[ \t]*(?:protected|public)\s+IItemHandler\s+createUnSidedHandler\s*\(\s*\)\s*\{\s*(?:return\s+(?:EmptyItemHandler\.INSTANCE|new\s+EmptyHandler\s*\(\s*\))\s*;)\s*\}\s*"""
        ).replace(source, "\n")
        if (result == source) return source
        removeImport(result, "net.neoforged.neoforge.items.IItemHandler").let { withoutImport ->
            if (!Regex("""\bIItemHandler\b""").containsMatchIn(withoutImport)) result = withoutImport
        }
        removeImport(result, "net.neoforged.neoforge.items.wrapper.EmptyItemHandler").let { withoutImport ->
            if (!withoutImport.contains("EmptyItemHandler")) result = withoutImport
        }
        removeImport(result, "net.neoforged.neoforge.items.wrapper.EmptyHandler").let { withoutImport ->
            if (!withoutImport.contains("EmptyHandler")) result = withoutImport
        }
        return result
    }

    private fun migrateLegacyHangingEntityBoundingBoxes(source: String): String {
        if (!source.contains("extends HangingEntity") ||
            Regex("""\b(?:public|protected|private)\s+AABB\s+calculateBoundingBox\s*\(""").containsMatchIn(source)) {
            return source
        }
        if (!source.contains("getWidth()") || !source.contains("getHeight()")) return source
        val classOpen = source.indexOf('{')
        val classClose = source.lastIndexOf('}')
        if (classOpen < 0 || classClose <= classOpen) return source

        var result = source
        result = Regex("""(?m)^([ \t]*)@Override\s*\r?\n([ \t]*public\s+int\s+get(?:Width|Height)\s*\()""")
            .replace(result, "$1$2")
        val insertion = """

    @Override
    protected AABB calculateBoundingBox(BlockPos pos, Direction direction) {
        Vec3 base = Vec3.atCenterOf(pos).relative(direction, -0.46875D);
        double widthOffset = this.offsetForHangingEntitySize(this.getWidth());
        double heightOffset = this.offsetForHangingEntitySize(this.getHeight());
        Vec3 center = base.relative(direction.getCounterClockWise(), widthOffset).relative(Direction.UP, heightOffset);
        Direction.Axis axis = direction.getAxis();
        double scale = 1.0D / 16.0D;
        double xSize = axis == Direction.Axis.X ? 0.0625D : this.getWidth() * scale;
        double ySize = this.getHeight() * scale;
        double zSize = axis == Direction.Axis.Z ? 0.0625D : this.getWidth() * scale;
        return AABB.ofSize(center, xSize, ySize, zSize);
    }

    private double offsetForHangingEntitySize(int size) {
        return size % 32 == 0 ? 0.5D : 0.0D;
    }
""".trimEnd()
        val insertAt = result.lastIndexOf('}')
        if (insertAt < 0) return source
        result = result.substring(0, insertAt) + insertion + "\n" + result.substring(insertAt)
        result = addImportIfMissing(result, "net.minecraft.world.phys.AABB")
        result = addImportIfMissing(result, "net.minecraft.world.phys.Vec3")
        return result
    }

    private fun migrateLegacyToastTextureRendering(source: String): String {
        if (!source.contains("implements Toast") || !source.contains("graphics.blit(TEXTURE")) return source
        var result = source
        result = Regex(
            """graphics\.blit\(TEXTURE,\s*0,\s*0,\s*0,\s*0,\s*this\.width\(\),\s*this\.height\(\)\);"""
        ).replace(result, "graphics.blitSprite(BACKGROUND_SPRITE, 0, 0, this.width(), this.height());")
        if (result == source) return source
        if (!result.contains("BACKGROUND_SPRITE")) return result
        if (!Regex("""\bBACKGROUND_SPRITE\s*=""").containsMatchIn(result)) {
            val anchor = Regex("""(?m)^([ \t]*private\s+static\s+final\s+Component\s+[A-Z0-9_]+\s*=.*;\s*)$""")
                .find(result)
            val insertion = "\n\tprivate static final ResourceLocation BACKGROUND_SPRITE = ResourceLocation.withDefaultNamespace(\"toast/advancement\");"
            result = if (anchor != null) {
                result.substring(0, anchor.range.last + 1) + insertion + result.substring(anchor.range.last + 1)
            } else {
                val openBrace = result.indexOf('{')
                if (openBrace >= 0) result.substring(0, openBrace + 1) + insertion + "\n" + result.substring(openBrace + 1) else result
            }
        }
        return addImportIfMissing(result, "net.minecraft.resources.ResourceLocation")
    }

    private fun migrateEntityDimensionsRecordAccessors(source: String): String {
        var result = source
        result = Regex(
            """(\b[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*\.dimensions)\.(width|height|fixed)\b(?!\s*\()"""
        ).replace(result) { match ->
            "${match.groupValues[1]}.${match.groupValues[2]}()"
        }

        val dimensionsVariables = Regex("""\bEntityDimensions\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in dimensionsVariables) {
            result = Regex("""\b${Regex.escape(variable)}\.(width|height|fixed)\b(?!\s*\()""")
                .replace(result) { match -> "$variable.${match.groupValues[1]}()" }
        }

        return result
    }

    private fun migrateAdvancementRequirementsStrategySource(source: String): String {
        if (!source.contains("AdvancementRequirements.Strategy") ||
            !source.contains("createRequirements(")) {
            return source
        }

        var result = Regex(
            """public\s+String\[\]\[\]\s+createRequirements(\s*\(\s*Collection\s*<\s*String\s*>\s+[A-Za-z_$][\w$]*\s*\))"""
        ).replace(source, "public AdvancementRequirements create$1")

        if (result.contains("String[][] requirements")) {
            result = Regex("""return\s+requirements\s*;""")
                .replace(
                    result,
                    "return new AdvancementRequirements(java.util.Arrays.stream(requirements).map(group -> java.util.List.of(group)).toList());"
                )
        } else if (result.contains("List<List<String>> requirements")) {
            result = Regex("""return\s+requirements\s*;""")
                .replace(result, "return new AdvancementRequirements(requirements);")
        }
        result = Regex("""(?s)return\s+(new\s+String\[\]\[\]\s*\{.*?})\s*;""")
            .replace(result) { match ->
                "return new AdvancementRequirements(java.util.Arrays.stream(${match.groupValues[1]}).map(group -> java.util.List.of(group)).toList());"
            }

        return result
    }

    private fun migrateLegacyAdvancementHolderApis(source: String): String {
        if (!source.contains("Advancement") && !source.contains(".getAdvancement(") && !source.contains("MissingAdvancementToast")) {
            return source
        }

        var result = source
        result = result.replace(".getAdvancements().getAdvancement(", ".getAdvancements().get(")
        result = result.replace("manager.getAdvancements().get(", "manager.get(")
        val advancementManagerVariables = Regex("""\bServerAdvancementManager\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (managerVariable in advancementManagerVariables) {
            result = result.replace("$managerVariable.getAdvancement(", "$managerVariable.get(")
        }

        result = result.replace("Predicate<Advancement>", "Predicate<AdvancementHolder>")
        result = result.replace("{@link Advancement}", "{@link AdvancementHolder}")
        result = result.replace("matches(Advancement ", "matches(AdvancementHolder ")
        result = result.replace("retrieveOverride(Advancement ", "retrieveOverride(AdvancementHolder ")
        result = result.replace("checkRoot(Advancement ", "checkRoot(AdvancementHolder ")
        if (result.contains("AdvancementToast.class")) {
            result = Regex("""\bprivate\s+Advancement\s+advancement\s*;""")
                .replace(result, "private AdvancementHolder advancement;")
        }
        result = Regex("""\b(public|private|protected)\s+static\s+Advancement\s+getAdvancement\s*\(""")
            .replace(result, "$1 static AdvancementHolder getAdvancement(")
        result = Regex(
            """\b(public|private|protected)\s+static\s+boolean\s+doesPlayerHaveRequiredAdvancement\(\s*Player\s+([A-Za-z_$][\w$]*)\s*,\s*Advancement\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(result) { match ->
            "${match.groupValues[1]} static boolean doesPlayerHaveRequiredAdvancement(Player ${match.groupValues[2]}, AdvancementHolder ${match.groupValues[3]})"
        }
        result = Regex(
            """\bAdvancement\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]*(?:getAdvancement|getAdvancements\(\)\.get|manager\.get|PlayerHelper\.getAdvancement)\([^;\r\n]*;)"""
        ).replace(result) { match ->
            "AdvancementHolder ${match.groupValues[1]} = ${match.groupValues[2]}"
        }

        val holderVariables = Regex("""\bAdvancementHolder\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        val holderLambdaVariables = if (result.contains("Predicate<AdvancementHolder>") || result.contains("new AdvancementSoundOverride")) {
            Regex("""\b([A-Za-z_$][\w$]*)\s*->[^;\r\n]*\b\1\.getId\(\)""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
        } else {
            emptySet()
        }
        for (variable in holderVariables) {
            result = result.replace("$variable.getDisplay()", "$variable.value().display().orElse(null)")
            result = result.replace("$variable.getId()", "$variable.id()")
        }
        for (variable in holderLambdaVariables) {
            result = result.replace("$variable.getId()", "$variable.id()")
        }
        result = migrateLegacyAdvancementParentLoop(result)
        result = migrateLegacyDeferredRegistryEntryStream(result)

        result = Regex("""([A-Za-z_$][\w$]*)\.FALLBACK\s*:\s*new\s+([A-Za-z_$][\w$]*Packet)\(""")
            .replace(result) { match ->
                val fallbackType = match.groupValues[1]
                val packetType = match.groupValues[2]
                "new $packetType($fallbackType.FALLBACK.title(), $fallbackType.FALLBACK.icon()) : new $packetType("
            }

        if (result != source && result.contains("AdvancementHolder")) {
            result = addImportIfMissing(result, "net.minecraft.advancements.AdvancementHolder")
            if (result.contains("Minecraft.getInstance().player")) {
                result = addImportIfMissing(result, "net.minecraft.client.Minecraft")
                result = addImportIfMissing(result, "net.minecraft.client.player.LocalPlayer")
            }
            if (result.contains("DeferredHolder::value")) {
                result = addImportIfMissing(result, "net.neoforged.neoforge.registries.DeferredHolder")
            }
            val withoutAdvancementImport = removeImport(result, "net.minecraft.advancements.Advancement")
            if (!Regex("""\bAdvancement\b""").containsMatchIn(withoutAdvancementImport)) {
                result = withoutAdvancementImport
            }
        }
        return result
    }

    private fun migrateLegacyAdvancementParentLoop(source: String): String {
        if (!source.contains(".getParent()") || !source.contains("AdvancementHolder")) return source
        var result = source
        var cursor = 0
        val loopHeader = Regex("""for\s*\(\s*Advancement\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\s*;\s*([A-Za-z_$][\w$]*)\s*!=\s*null\s*;\s*([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.getParent\(\)\s*\)\s*\{""")
        while (true) {
            val match = loopHeader.find(result, cursor) ?: break
            val loopVariable = match.groupValues[1]
            if (match.groupValues[3] != loopVariable || match.groupValues[4] != loopVariable || match.groupValues[5] != loopVariable) {
                cursor = match.range.last + 1
                continue
            }
            val holder = match.groupValues[2]
            val openBrace = match.range.last
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val loopBody = result.substring(openBrace + 1, closeBrace)
            val bodyMatch = Regex("""if\s*\(\s*${Regex.escape(loopVariable)}\.(?:getId\(\)|id\(\))\.equals\(([^)]+)\)\s*\)\s*\{\s*return\s+true\s*;\s*}""")
                .find(loopBody)
            if (bodyMatch == null) {
                cursor = closeBrace + 1
                continue
            }
            val indent = leadingIndentAt(result, match.range.first)
            val root = bodyMatch.groupValues[1].trim()
            val inner = "$indent    "
            val replacement = """
${indent}LocalPlayer player = Minecraft.getInstance().player;
${indent}if (player != null) {
${inner}for (AdvancementHolder current = $holder; current != null && current.value().parent().isPresent(); current = player.connection.getAdvancements().get(current.value().parent().get())) {
${inner}    if (current.id().equals($root)) {
${inner}        return true;
${inner}    }
${inner}}
${indent}}
""".trim('\n')
            result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = match.range.first + replacement.length
        }
        return result
    }

    private fun migrateLegacyDeferredRegistryEntryStream(source: String): String {
        if (!source.contains(".getEntries().stream().map(Map.Entry::getValue)")) return source
        val deferredRegisters = Regex("""\bDeferredRegister\s*<\s*([A-Za-z_$][\w$]*)\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] to it.groupValues[2] }
            .toList()
        if (deferredRegisters.isEmpty()) return source
        var result = source
        for ((type, deferredRegister) in deferredRegisters) {
            val registries = linkedSetOf<String>()
            registries += Regex("""\bRegistry\s*<\s*${Regex.escape(type)}\s*>\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
            registries += Regex("""\bIForgeRegistry\s*<\s*${Regex.escape(type)}\s*>\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
            registries += Regex("""\bSupplier\s*<\s*(?:IForgeRegistry|Registry)\s*<\s*${Regex.escape(type)}\s*>\s*>\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
            for (registry in registries) {
                result = Regex("""(?:[A-Za-z_$][\w$]*\.)?${Regex.escape(registry)}(?:\.get\(\))?\.getEntries\(\)\.stream\(\)\.map\(Map\.Entry::getValue\)""")
                    .replace(result, "$deferredRegister.getEntries().stream().map(DeferredHolder::value)")
            }
        }
        return result
    }

    private fun migrateLegacyDatagenTagConstantsSource(source: String): String {
        if (!source.contains("ItemTags.") &&
            !source.contains("Tags.Items.ARMORS_") &&
            !source.contains("BuiltInRegistries.ENCHANTMENT")) {
            return source
        }

        var result = source
        result = result.replace("ItemTags.MUSIC_DISCS", "Tags.Items.MUSIC_DISCS")
        result = result.replace("Tags.Items.ARMORS_HELMETS", "ItemTags.HEAD_ARMOR")
        result = result.replace("Tags.Items.ARMORS_CHESTPLATES", "ItemTags.CHEST_ARMOR")
        result = result.replace("Tags.Items.ARMORS_LEGGINGS", "ItemTags.LEG_ARMOR")
        result = result.replace("Tags.Items.ARMORS_BOOTS", "ItemTags.FOOT_ARMOR")
        result = Regex(
            """BuiltInRegistries\.ENCHANTMENT\.getResourceKey\(\s*(Enchantments\.[A-Z0-9_]+)\s*\)\.get\(\)"""
        ).replace(result, "$1")
        return result
    }

    private fun migrateHolderValueMethodArgumentSource(
        source: String,
        hints: HolderValueParameterHints
    ): String {
        if (!source.contains("SoundEvents.") && !source.contains("Potions.")) return source

        var result = source
        hints.soundEventParameters.forEach { (methodName, positions) ->
            result = rewriteJavaInvocationArguments(result, methodName) { args ->
                var changed = false
                val migrated = args.toMutableList()
                positions.forEach { index ->
                    val arg = migrated.getOrNull(index)?.trim() ?: return@forEach
                    if (isHolderSoundEventConstant(arg)) {
                        migrated[index] = "$arg.value()"
                        changed = true
                    }
                }
                if (changed) migrated else null
            }
        }
        hints.potionParameters.forEach { (methodName, positions) ->
            result = rewriteJavaInvocationArguments(result, methodName) { args ->
                var changed = false
                val migrated = args.toMutableList()
                positions.forEach { index ->
                    val arg = migrated.getOrNull(index)?.trim() ?: return@forEach
                    if (Regex("""^Potions\.[A-Z0-9_]+$""").matches(arg)) {
                        migrated[index] = "$arg.value()"
                        changed = true
                    }
                }
                if (changed) migrated else null
            }
        }
        result = Regex("""BuiltInRegistries\.POTION\.getKey\(\s*(Potions\.[A-Z0-9_]+)\s*\)""")
            .replace(result, "BuiltInRegistries.POTION.getKey($1.value())")
        return result
    }

    private fun isHolderSoundEventConstant(expression: String): Boolean {
        if (!Regex("""^SoundEvents\.[A-Z0-9_]+$""").matches(expression)) return false
        val constant = expression.substringAfter("SoundEvents.")
        return constant.startsWith("ARMOR_EQUIP_") ||
            constant.startsWith("NOTE_BLOCK_") ||
            constant.startsWith("MUSIC_") ||
            constant.startsWith("AMBIENT_")
    }

    private fun migrateLegacyAdvancementDatagenSource(
        source: String,
        criterionFactoryHints: CriterionInstanceFactoryHints
    ): String {
        if (!source.contains("Advancement") &&
            !source.contains("LocationPredicate.") &&
            !source.contains("ContextAwarePredicate.ANY") &&
            !source.contains("ItemDurabilityTrigger.TriggerInstance.changedDurability") &&
            !source.contains(".hasNbt(") &&
            !source.contains(".addStat(Stats.CUSTOM.get(")) {
            return source
        }

        var result = source
        val providerName = Regex("""\bHolderLookup\.Provider\s+([A-Za-z_$][\w$]*)\b""")
            .find(result)
            ?.groupValues
            ?.get(1)

        result = Regex("""(?s)\bAdvancement\s+([A-Za-z_$][\w$]*)\s*=\s*((?:(?!;).)*?\.save\s*\()""")
            .replace(result) { match -> "AdvancementHolder ${match.groupValues[1]} = ${match.groupValues[2]}" }
        result = Regex("""\b(PlayerTrigger\.TriggerInstance\s+advancementTrigger\s*\(\s*)Advancement(\s+[A-Za-z_$][\w$]*\s*\))""")
            .replace(result, "$1AdvancementHolder$2")
        result = Regex("""\b(private|protected|public)\s+PlayerTrigger\.TriggerInstance\s+(advancementTrigger\s*\()""")
            .replace(result, "$1 Criterion<PlayerTrigger.TriggerInstance> $2")

        val holderVariables = Regex("""\bAdvancementHolder\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        holderVariables.forEach { variable ->
            result = result.replace("$variable.getId()", "$variable.id()")
        }
        result = result.replace(".getAdvancement().getId()", ".getAdvancement().id()")

        result = result.replace("LocationPredicate.inDimension(", "LocationPredicate.Builder.inDimension(")
        if (providerName != null) {
            result = result.replace("LocationPredicate.inBiome(", "LocationPredicate.Builder.inBiome(")
            result = result.replace("LocationPredicate.inStructure(", "LocationPredicate.Builder.inStructure(")
            result = rewriteJavaInvocationArguments(result, "LocationPredicate.Builder.inBiome") { args ->
                if (args.size == 1 && !args[0].contains("lookupOrThrow")) {
                    listOf("$providerName.lookupOrThrow(Registries.BIOME).getOrThrow(${args[0].trim()})")
                } else {
                    null
                }
            }
            result = rewriteJavaInvocationArguments(result, "LocationPredicate.Builder.inStructure") { args ->
                if (args.size == 1 && !args[0].contains("lookupOrThrow")) {
                    listOf("$providerName.lookupOrThrow(Registries.STRUCTURE).getOrThrow(${args[0].trim()})")
                } else {
                    null
                }
            }
        }

        result = rewriteJavaCall(result, "setBlock") { receiver, args ->
            val blockArg = args.singleOrNull()?.trim() ?: return@rewriteJavaCall null
            val migratedArg = removeTrailingBuildCall(blockArg, "BlockPredicate.Builder")
            if (migratedArg != blockArg) "$receiver.setBlock($migratedArg)" else null
        }
        result = rewriteJavaCall(result, "setProperties") { receiver, args ->
            val propertiesArg = args.singleOrNull()?.trim() ?: return@rewriteJavaCall null
            val migratedArg = removeTrailingBuildCall(propertiesArg, "StatePropertiesPredicate.Builder")
            if (migratedArg != propertiesArg) "$receiver.setProperties($migratedArg)" else null
        }

        result = Regex("""new\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.Instance)\(\s*ContextAwarePredicate\.ANY\s*\)""")
            .replace(result, "new $1(java.util.Optional.empty())")
        criterionFactoryHints.emptyInstanceFactories.forEach { (instanceType, factoryCall) ->
            result = Regex("""new\s+${Regex.escape(instanceType)}\(\s*(?:java\.util\.)?Optional\.empty\(\)\s*\)""")
                .replace(result, factoryCall)
        }
        result = rewriteJavaNew(result, "PlayerTrigger.TriggerInstance") { args ->
            if (args.size == 2 && args[0].contains("CriteriaTriggers.")) {
                "new PlayerTrigger.TriggerInstance(java.util.Optional.of(${args[1].trim()}))"
            } else {
                null
            }
        }
        result = Regex("""(?m)^([ \t]*)return\s+new\s+PlayerTrigger\.TriggerInstance\((.*)\)\s*;""")
            .replace(result) { match ->
                "${match.groupValues[1]}return CriteriaTriggers.TICK.createCriterion(new PlayerTrigger.TriggerInstance(${match.groupValues[2]}));"
            }
        result = rewriteJavaInvocationArguments(result, "PlayerTrigger.TriggerInstance.located") { args ->
            if (args.size == 1) {
                val arg = args[0].trim()
                val migrated = removeTrailingBuildCall(arg, "EntityPredicate.Builder")
                if (migrated != arg) listOf(migrated) else null
            } else {
                null
            }
        }
        result = rewriteJavaInvocationArguments(result, "ItemDurabilityTrigger.TriggerInstance.changedDurability") { args ->
            if (args.size == 2 && !args[0].trim().startsWith("java.util.Optional.") && !args[0].trim().startsWith("Optional.")) {
                listOf("java.util.Optional.of(${args[0].trim()})", args[1])
            } else {
                null
            }
        }

        if (result.contains(".hasNbt(")) {
            result = rewriteJavaCall(result, "hasNbt") { receiver, args ->
                val tagArg = args.singleOrNull()?.trim() ?: return@rewriteJavaCall null
                "$receiver.hasComponents(DataComponentPredicate.builder().expect(DataComponents.CUSTOM_DATA, CustomData.of($tagArg)).build())"
            }
            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponentPredicate")
            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
            result = addImportIfMissing(result, "net.minecraft.world.item.component.CustomData")
        }

        result = rewriteJavaInvocationArguments(result, "addStat") { args ->
            if (args.size == 2 && args[0].trim().startsWith("Stats.CUSTOM.get(")) {
                val statArg = args[0].trim()
                val openParen = statArg.indexOf('(')
                val closeParen = if (openParen >= 0) findMatchingParen(statArg, openParen) else -1
                if (closeParen > openParen) {
                    val keyExpr = statArg.substring(openParen + 1, closeParen).trim()
                    listOf(
                        "Stats.CUSTOM",
                        "BuiltInRegistries.CUSTOM_STAT.getHolderOrThrow(ResourceKey.create(Registries.CUSTOM_STAT, $keyExpr))",
                        args[1]
                    )
                } else {
                    null
                }
            } else {
                null
            }
        }
        if (result.contains("ResourceKey.create(Registries.CUSTOM_STAT")) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
            result = addImportIfMissing(result, "net.minecraft.core.registries.BuiltInRegistries")
            result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
        }

        if (result != source && result.contains("AdvancementHolder")) {
            result = addImportIfMissing(result, "net.minecraft.advancements.AdvancementHolder")
            val withoutAdvancementImport = removeImport(result, "net.minecraft.advancements.Advancement")
            if (!Regex("""\bAdvancement\b""").containsMatchIn(withoutAdvancementImport)) {
                result = withoutAdvancementImport
            }
        }
        return result
    }

    private fun migrateLegacyCriterionTriggerInstanceCallSites(
        source: String,
        criterionFactoryHints: CriterionInstanceFactoryHints
    ): String {
        if (!source.contains(".INSTANCE.") || criterionFactoryHints.triggerHoldersByTriggerClass.isEmpty()) {
            return source
        }
        var result = source
        criterionFactoryHints.triggerHoldersByTriggerClass.forEach { (triggerClass, holderExpression) ->
            val simpleTrigger = triggerClass.substringAfterLast('.')
            result = Regex("""\b${Regex.escape(simpleTrigger)}\.INSTANCE\.""")
                .replace(result, "$holderExpression.get().")
            result = Regex("""\b${Regex.escape(triggerClass)}\.INSTANCE\.""")
                .replace(result, "$holderExpression.get().")
        }
        return result
    }

    private fun removeTrailingBuildCall(expression: String, requiredBuilder: String): String {
        val trimmed = expression.trim()
        if (!trimmed.endsWith(".build()") || !trimmed.contains(requiredBuilder)) return expression
        return trimmed.removeSuffix(".build()")
    }

    private fun migrateLegacyItemStackHurtSource(source: String): String {
        if (!source.contains(".hurt(") || !source.contains(", null")) return source

        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        var needsServerLevel = false

        while (cursor < source.length) {
            val tokenIndex = source.indexOf(".hurt(", cursor)
            if (tokenIndex < 0) break
            val receiverStart = findDottedReceiverStart(source, tokenIndex)
            val receiver = source.substring(receiverStart, tokenIndex).trim()
            val openParen = tokenIndex + ".hurt".length
            val closeParen = findMatchingParen(source, openParen)
            if (receiver.isBlank() || closeParen < 0) {
                migrated.append(source, cursor, tokenIndex + ".hurt(".length)
                cursor = tokenIndex + ".hurt(".length
                continue
            }

            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val hurtPlan = if (args.size == 3 && args[2].trim() == "null") {
                legacyItemStackHurtPlan(args[1], source)
            } else {
                null
            }
            if (hurtPlan == null) {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }

            val ifStart = findIfStatementStartForCondition(source, receiverStart)
            if (ifStart != null) {
                val conditionOpen = source.indexOf('(', ifStart)
                val conditionClose = if (conditionOpen >= 0) findMatchingParen(source, conditionOpen) else -1
                val blockOpen = nextNonWhitespaceIndex(source, conditionClose + 1)
                if (conditionOpen >= 0 &&
                    receiverStart > conditionOpen &&
                    closeParen < conditionClose &&
                    blockOpen >= 0 &&
                    source[blockOpen] == '{'
                ) {
                    val blockClose = findMatchingBrace(source, blockOpen)
                    if (blockClose > blockOpen) {
                        val condition = source.substring(conditionOpen + 1, conditionClose).trim()
                        val hurtCall = source.substring(receiverStart, closeParen + 1)
                        val conditionParts = legacyItemStackHurtConditionParts(condition, hurtCall)
                        if (conditionParts == null) {
                            migrated.append(source, cursor, closeParen + 1)
                            cursor = closeParen + 1
                            continue
                        }
                        val lineStart = source.lastIndexOf('\n', ifStart).let { if (it < 0) 0 else it + 1 }
                        val indent = source.substring(lineStart, ifStart).takeWhile { it == ' ' || it == '\t' }
                        val amount = args[0].trim()
                        val body = source.substring(blockOpen + 1, blockClose).trim()
                        val replacement = if (hurtPlan.serverLevel == null) {
                            legacyItemStackManualHurtReplacement(
                                indent = indent,
                                condition = conditionParts.outerCondition,
                                callbackCondition = conditionParts.callbackCondition,
                                receiver = receiver,
                                amount = amount,
                                callbackBody = body
                            )
                        } else {
                            legacyItemStackHurtReplacement(
                                indent = indent,
                                condition = conditionParts.outerCondition,
                                callbackCondition = conditionParts.callbackCondition,
                                receiver = receiver,
                                amount = amount,
                                serverLevel = hurtPlan.serverLevel,
                                callbackBody = body
                            )
                        }
                        migrated.append(source, cursor, ifStart)
                        migrated.append(replacement)
                        cursor = blockClose + 1
                        changed = true
                        needsServerLevel = needsServerLevel || hurtPlan.serverLevel != null
                        continue
                    }
                }
            }

            migrated.append(source, cursor, receiverStart)
            if (hurtPlan.serverLevel == null) {
                migrated.append("${receiver}.setDamageValue(${receiver}.getDamageValue() + ${args[0].trim()})")
            } else {
                migrated.append("${receiver}.hurtAndBreak(${args[0].trim()}, ${hurtPlan.serverLevel}, null, item -> {})")
            }
            cursor = closeParen + 1
            changed = true
            needsServerLevel = needsServerLevel || hurtPlan.serverLevel != null
        }

        if (!changed) return source
        migrated.append(source, cursor, source.length)
        var result = migrated.toString()
        if (needsServerLevel) {
            result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        }
        return result
    }

    private data class LegacyItemStackHurtPlan(val serverLevel: String?)

    private data class LegacyItemStackHurtCondition(
        val outerCondition: String?,
        val callbackCondition: String?
    )

    private fun legacyItemStackHurtPlan(randomExpression: String, source: String): LegacyItemStackHurtPlan? {
        val random = randomExpression.trim()
        val levelExpression = when {
            random.endsWith(".getRandom()") -> random.removeSuffix(".getRandom()").trim()
            random.endsWith(".random") -> random.removeSuffix(".random").trim()
            else -> return null
        }
        return LegacyItemStackHurtPlan(inferServerLevelExpression(levelExpression, source))
    }

    private fun inferServerLevelExpression(levelExpression: String, source: String): String? {
        val level = levelExpression.trim()
        return level.takeIf {
            Regex("""\b(?:net\.minecraft\.server\.level\.)?ServerLevel\s+${Regex.escape(level)}\b""").containsMatchIn(source)
        }
    }

    private fun legacyItemStackHurtConditionParts(condition: String, hurtCall: String): LegacyItemStackHurtCondition? {
        val callIndex = condition.indexOf(hurtCall)
        if (callIndex < 0) return null
        val before = condition.substring(0, callIndex).trim()
        val after = condition.substring(callIndex + hurtCall.length).trim()
        return when {
            before.isBlank() && after.isBlank() -> LegacyItemStackHurtCondition(null, null)
            before.endsWith("&&") && after.isBlank() ->
                LegacyItemStackHurtCondition(before.removeSuffix("&&").trim().ifBlank { null }, null)
            before.isBlank() && after.startsWith("&&") ->
                LegacyItemStackHurtCondition(null, after.removePrefix("&&").trim().ifBlank { null })
            before.endsWith("&&") && after.startsWith("&&") ->
                LegacyItemStackHurtCondition(
                    before.removeSuffix("&&").trim().ifBlank { null },
                    after.removePrefix("&&").trim().ifBlank { null }
                )
            else -> null
        }
    }

    private fun findIfStatementStartForCondition(source: String, expressionStart: Int): Int? {
        val lineStart = source.lastIndexOf('\n', expressionStart).let { if (it < 0) 0 else it + 1 }
        val prefix = source.substring(lineStart, expressionStart)
        val offset = prefix.lastIndexOf("if")
        if (offset < 0) return null
        val candidate = lineStart + offset
        if (candidate > 0 && (source[candidate - 1].isLetterOrDigit() || source[candidate - 1] == '_')) return null
        val after = candidate + 2
        return if (after < source.length && source.substring(after, minOf(source.length, after + 8)).trimStart().startsWith("(")) {
            candidate
        } else {
            null
        }
    }

    private fun nextNonWhitespaceIndex(source: String, start: Int): Int {
        var index = start
        while (index < source.length && source[index].isWhitespace()) index++
        return if (index < source.length) index else -1
    }

    private fun legacyItemStackHurtReplacement(
        indent: String,
        condition: String?,
        callbackCondition: String?,
        receiver: String,
        amount: String,
        serverLevel: String,
        callbackBody: String
    ): String {
        val callbackBodyLines = if (callbackBody.isBlank()) {
            ""
        } else {
            callbackBody.lines()
                .joinToString("\n") { line -> if (line.isBlank()) line else "$indent        ${line.trim()}" }
        }
        val guardedBody = when {
            callbackBodyLines.isBlank() -> ""
            callbackCondition.isNullOrBlank() -> callbackBodyLines
            else -> """$indent        if ($callbackCondition) {
$callbackBodyLines
$indent        }"""
        }
        val callback = if (guardedBody.isBlank()) {
            "$receiver.hurtAndBreak($amount, $serverLevel, null, item -> {});"
        } else {
            """$receiver.hurtAndBreak($amount, $serverLevel, null, item -> {
$guardedBody
$indent    });"""
        }
        return if (condition == null) {
            "$indent$callback"
        } else {
            """${indent}if ($condition) {
$indent    $callback
$indent}"""
        }
    }

    private fun legacyItemStackManualHurtReplacement(
        indent: String,
        condition: String?,
        callbackCondition: String?,
        receiver: String,
        amount: String,
        callbackBody: String
    ): String {
        val body = if (callbackBody.isBlank()) {
            ""
        } else {
            callbackBody.lines()
                .joinToString("\n") { line -> if (line.isBlank()) line else "$indent            ${line.trim()}" }
        }
        val breakBody = when {
            body.isBlank() -> ""
            callbackCondition.isNullOrBlank() -> body
            else -> """$indent            if ($callbackCondition) {
$body
$indent            }"""
        }
        val damage = "$receiver.setDamageValue($receiver.getDamageValue() + $amount);"
        val breakCheck = if (breakBody.isBlank()) {
            ""
        } else {
            """
$indent    if ($receiver.getDamageValue() >= $receiver.getMaxDamage()) {
$breakBody
$indent    }""".trimEnd()
        }
        val migrated = if (breakCheck.isBlank()) {
            "$indent$damage"
        } else {
            "$indent$damage\n$breakCheck"
        }
        return if (condition == null) {
            migrated
        } else {
            """${indent}if ($condition) {
$migrated
$indent}"""
        }
    }

    private fun migrateLegacyBlockSourceCoordinateAccessors(source: String): String {
        if (!source.contains("BlockSource") ||
            (!source.contains(".x()") &&
                !source.contains(".y()") &&
                !source.contains(".z()") &&
                !source.contains(".getPos()") &&
                !source.contains(".getBlockState()") &&
                !source.contains(".getLevel()") &&
                !source.contains("getEntity()"))
        ) {
            return source
        }
        val blockSourceVars = Regex("""\bBlockSource\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (blockSourceVars.isEmpty()) return source
        var result = source
        for (variable in blockSourceVars) {
            result = Regex("""\b${Regex.escape(variable)}\.(x|y|z)\(\)""")
                .replace(result) { match -> "$variable.center().${match.groupValues[1]}()" }
            result = Regex("""\b${Regex.escape(variable)}\.getPos\(\)""")
                .replace(result, "$variable.pos()")
            result = Regex("""\b${Regex.escape(variable)}\.getBlockState\(\)""")
                .replace(result, "$variable.state()")
            result = Regex("""\b${Regex.escape(variable)}\.getLevel\(\)""")
                .replace(result, "$variable.level()")
            result = Regex("""\b${Regex.escape(variable)}\s*\.\s*(?:<[^>]+>\s*)?getEntity\(\)""")
                .replace(result, "$variable.blockEntity()")
            result = Regex("""\b${Regex.escape(variable)}\.blockEntity\(\)\.addItem\(([^;\r\n]+)\)\s*<\s*0""")
                .replace(result) { match -> "!$variable.blockEntity().insertItem(${match.groupValues[1].trim()}).isEmpty()" }
            result = Regex("""\b${Regex.escape(variable)}\.blockEntity\(\)\.addItem\(""")
                .replace(result, "$variable.blockEntity().insertItem(")
        }
        return result
    }

    private fun migrateLegacyProjectileDispenseBehaviorSource(source: String): String {
        if (!source.contains("ProjectileDispenseBehavior")) return source
        var result = source
        var changed = false
        var synthesizedExecute = false

        var cursor = 0
        val anonymousPattern = Regex("""new\s+ProjectileDispenseBehavior\s*\(\s*\)\s*\{""")
        while (true) {
            val match = anonymousPattern.find(result, cursor) ?: break
            val openBrace = match.range.last
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val migratedBody = migrateLegacyProjectileDispenseBody(body)
            synthesizedExecute = synthesizedExecute || migratedBody.contains("Projectile projectile = this.getProjectile(") && !body.contains("ItemStack execute(")
            result = result.substring(0, match.range.first) +
                "new DefaultDispenseItemBehavior() {" +
                migratedBody +
                result.substring(closeBrace)
            cursor = match.range.first + "new DefaultDispenseItemBehavior() {".length + migratedBody.length + 1
            changed = true
        }

        if (Regex("""extends\s+ProjectileDispenseBehavior\b""").containsMatchIn(result) &&
            (result.contains("getProjectile(") || result.contains("getPower()") || result.contains("getUncertainty()"))
        ) {
            result = Regex("""extends\s+ProjectileDispenseBehavior\b""").replace(result, "extends DefaultDispenseItemBehavior")
            val migrated = migrateLegacyProjectileDispenseBody(result)
            synthesizedExecute = synthesizedExecute || migrated.contains("Projectile projectile = this.getProjectile(") && !result.contains("ItemStack execute(")
            result = migrated
            changed = true
        }

        if (!changed) return source
        if (synthesizedExecute) {
            result = addImportIfMissing(result, "net.minecraft.core.Direction")
            result = addImportIfMissing(result, "net.minecraft.core.dispenser.BlockSource")
            result = addImportIfMissing(result, "net.minecraft.world.level.block.DispenserBlock")
        }
        result = addImportIfMissing(result, "net.minecraft.core.dispenser.DefaultDispenseItemBehavior")
        val withoutProjectileImport = removeImport(result, "net.minecraft.core.dispenser.ProjectileDispenseBehavior")
        if (!withoutProjectileImport.contains("ProjectileDispenseBehavior")) {
            result = withoutProjectileImport
        }
        return result
    }

    private fun migrateLegacyProjectileDispenseBody(source: String): String {
        val hasPowerMethod = legacyProjectileHookMethodExists(source, "getPower")
        val hasUncertaintyMethod = legacyProjectileHookMethodExists(source, "getUncertainty")
        val powerArgument = if (hasPowerMethod) "this.getPower()" else "1.1F"
        val uncertaintyArgument = if (hasUncertaintyMethod) "this.getUncertainty()" else "6.0F"
        var result = source
        if (!hasPowerMethod) {
            result = result.replace("this.getPower()", powerArgument)
        }
        if (!hasUncertaintyMethod) {
            result = result.replace("this.getUncertainty()", uncertaintyArgument)
        }
        if (!legacyProjectileExecuteMethodExists(result)) {
            legacyProjectileGetProjectileMethod(result)?.let { method ->
                val execute = buildLegacyProjectileDispenseExecute(
                    indent = leadingIndentAt(result, method.start),
                    level = method.level,
                    position = method.position,
                    stack = method.stack,
                    powerArgument = powerArgument,
                    uncertaintyArgument = uncertaintyArgument
                )
                result = result.substring(0, method.start) + execute + "\n" + result.substring(method.start)
            }
        }
        return removeOverrideFromLegacyProjectileHooks(result)
    }

    private data class LegacyProjectileMethod(val start: Int, val level: String, val position: String, val stack: String)

    private fun legacyProjectileGetProjectileMethod(source: String): LegacyProjectileMethod? {
        val pattern = Regex(
            """(?m)(?:[ \t]*@[\w.]+(?:\([^)]*\))?\s*\r?\n)*[ \t]*(?:public|protected|private)\s+Projectile\s+getProjectile\s*\(\s*Level\s+([A-Za-z_$][\w$]*)\s*,\s*Position\s+([A-Za-z_$][\w$]*)\s*,\s*ItemStack\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
        )
        val match = pattern.find(source) ?: return null
        return LegacyProjectileMethod(
            start = match.range.first,
            level = match.groupValues[1],
            position = match.groupValues[2],
            stack = match.groupValues[3]
        )
    }

    private fun legacyProjectileExecuteMethodExists(source: String): Boolean =
        Regex("""\bItemStack\s+execute\s*\(\s*BlockSource\s+[A-Za-z_$][\w$]*\s*,\s*ItemStack\s+[A-Za-z_$][\w$]*\s*\)""")
            .containsMatchIn(source)

    private fun legacyProjectileHookMethodExists(source: String, methodName: String): Boolean =
        Regex("""\b(?:public|protected|private)\s+(?:float|Projectile)\s+${Regex.escape(methodName)}\s*\(""")
            .containsMatchIn(source)

    private fun buildLegacyProjectileDispenseExecute(
        indent: String,
        level: String,
        position: String,
        stack: String,
        powerArgument: String,
        uncertaintyArgument: String
    ): String {
        val inner = "$indent    "
        return """
${indent}@Override
${indent}protected ItemStack execute(BlockSource source, ItemStack $stack) {
${inner}Level $level = source.level();
${inner}Direction direction = source.state().getValue(DispenserBlock.FACING);
${inner}Position $position = DispenserBlock.getDispensePosition(source);
${inner}Projectile projectile = this.getProjectile($level, $position, $stack);
${inner}projectile.shoot(direction.getStepX(), direction.getStepY(), direction.getStepZ(), $powerArgument, $uncertaintyArgument);
${inner}$level.addFreshEntity(projectile);
${inner}$stack.shrink(1);
${inner}return $stack;
${indent}}
""".trim('\n')
    }

    private fun removeOverrideFromLegacyProjectileHooks(source: String): String =
        Regex(
            """(?m)^[ \t]*@Override\s*\r?\n(?=[ \t]*(?:@[\w.]+(?:\([^)]*\))?\s*\r?\n)*[ \t]*(?:public|protected|private)\s+(?:float|Projectile)\s+(?:getProjectile|getPower|getUncertainty)\s*\()"""
        ).replace(source, "")

    private fun leadingIndentAt(source: String, offset: Int): String {
        val lineStart = source.lastIndexOf('\n', (offset - 1).coerceAtLeast(0)).let { if (it < 0) 0 else it + 1 }
        return source.substring(lineStart, offset).takeWhile { it == ' ' || it == '\t' }
    }

    private fun migrateLegacyAbstractArrowPickupItemSource(source: String): String {
        if (!source.contains("extends AbstractArrow") || !source.contains("getPickupItem()")) return source
        return Regex("""protected\s+ItemStack\s+getPickupItem\s*\(\s*\)""")
            .replace(source, "protected ItemStack getDefaultPickupItem()")
    }

    private fun migrateLegacyTooltipPartHiding(source: String): String {
        if (!source.contains(".hideTooltipPart(") || !source.contains("ItemStack.TooltipPart.ADDITIONAL")) return source

        var changed = false
        var result = rewriteJavaCall(source, "hideTooltipPart") { receiver, args ->
            if (args.size != 1 || args[0].trim() != "ItemStack.TooltipPart.ADDITIONAL") {
                return@rewriteJavaCall null
            }
            changed = true
            "$receiver.set(DataComponents.HIDE_ADDITIONAL_TOOLTIP, Unit.INSTANCE)"
        }
        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        result = addImportIfMissing(result, "net.minecraft.util.Unit")
        return result
    }

    private fun parseJavaConstructorParameters(parameters: String): List<JavaParameter> =
        splitTopLevelJavaArgs(parameters).mapNotNull { parameter ->
            val normalized = parameter
                .replace(Regex("""@\w+(?:\([^)]*\))?\s*"""), "")
                .replace(Regex("""\bfinal\s+"""), "")
                .trim()
            val match = Regex("""^(.+?)\s+([A-Za-z_$][\w$]*)$""").find(normalized) ?: return@mapNotNull null
            JavaParameter(match.groupValues[1].trim(), match.groupValues[2])
        }

    private fun JavaParameter.simpleTypeName(): String =
        type.substringBefore('<').substringAfterLast('.').trim()

    private fun JavaParameter.isLevelParameter(): Boolean =
        simpleTypeName() == "Level"

    private fun JavaParameter.isLivingEntityParameter(): Boolean =
        simpleTypeName() == "LivingEntity"

    private fun JavaParameter.isItemStackParameter(): Boolean =
        simpleTypeName() == "ItemStack"

    private fun JavaParameter.isItemSupplierParameter(): Boolean =
        simpleTypeName() == "Supplier" && Regex("""\bItem\b""").containsMatchIn(type)

    private fun migrateLegacyAbstractArrowConstructors(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        if (!source.contains("super(") || !source.contains("AbstractArrow")) return source

        var result = source
        var cursor = 0
        var changed = false
        var needsItemStack = false
        val constructorPattern = Regex(
            """(?m)^[ \t]*(?:public|protected|private)\s+([A-Za-z_$][\w$]*)\s*\(([^;{}]*)\)\s*(?:throws\s+[^{]+)?\{"""
        )
        while (true) {
            val match = constructorPattern.find(result, cursor) ?: break
            val classDeclaration = enclosingJavaClassDeclaration(result, match.range.first)
            if (classDeclaration?.name != match.groupValues[1] ||
                !javaClassExtendsAny(classDeclaration, setOf("AbstractArrow"), javaInheritanceIndex)) {
                cursor = match.range.last + 1
                continue
            }

            val parameters = parseJavaConstructorParameters(match.groupValues[2])
            val constructorOpenBrace = result.indexOf('{', match.range.last)
            val constructorCloseBrace = if (constructorOpenBrace >= 0) findMatchingBrace(result, constructorOpenBrace) else -1
            if (constructorOpenBrace < 0 || constructorCloseBrace < 0) {
                cursor = match.range.last + 1
                continue
            }

            val superIndex = result.indexOf("super(", constructorOpenBrace + 1)
            if (superIndex < 0 || superIndex > constructorCloseBrace) {
                cursor = constructorCloseBrace + 1
                continue
            }
            val superOpenParen = superIndex + "super".length
            val superCloseParen = findMatchingParen(result, superOpenParen)
            if (superCloseParen < 0 || superCloseParen > constructorCloseBrace) {
                cursor = constructorCloseBrace + 1
                continue
            }
            val semicolonIndex = nextNonWhitespaceIndex(result, superCloseParen + 1)
            if (semicolonIndex < 0 || result[semicolonIndex] != ';') {
                cursor = superCloseParen + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(superOpenParen + 1, superCloseParen))
            if (args.size != 3) {
                cursor = semicolonIndex + 1
                continue
            }

            val ownerArg = args[1].trim()
            val levelArg = args[2].trim()
            val ownerParameter = parameters.firstOrNull { it.name == ownerArg && it.isLivingEntityParameter() }
            val levelParameter = parameters.firstOrNull { it.name == levelArg && it.isLevelParameter() }
            if (ownerParameter == null || levelParameter == null) {
                cursor = semicolonIndex + 1
                continue
            }

            val pickupSupplier = parameters.firstOrNull { it.name !in args && it.isItemSupplierParameter() }
            val pickupStack = parameters.firstOrNull { it.name !in args && it.isItemStackParameter() }
            val pickupExpression = when {
                pickupSupplier != null -> {
                    needsItemStack = true
                    "new ItemStack(${pickupSupplier.name}.get())"
                }
                pickupStack != null -> pickupStack.name
                else -> {
                    cursor = semicolonIndex + 1
                    continue
                }
            }
            val weaponStack = parameters.firstOrNull {
                it.name != pickupStack?.name &&
                    it.name != pickupSupplier?.name &&
                    it.isItemStackParameter() &&
                    Regex("""(?i)(weapon|fired)""").containsMatchIn(it.name)
            }?.name ?: "null"

            val replacement = "super(${args[0].trim()}, $ownerArg, $levelArg, $pickupExpression, $weaponStack);"
            result = result.substring(0, superIndex) + replacement + result.substring(semicolonIndex + 1)
            cursor = superIndex + replacement.length
            changed = true
        }

        return if (changed && needsItemStack) addImportIfMissing(result, "net.minecraft.world.item.ItemStack") else result
    }

    private fun migrateLegacyAbstractArrowKnockbackSource(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        if (!source.contains("this.getKnockback()") || !source.contains("AbstractArrow")) return source

        var result = source
        var cursor = 0
        val ifPattern = Regex("""if\s*\(\s*this\.getKnockback\(\)\s*>\s*0\s*\)\s*\{""")
        while (true) {
            val match = ifPattern.find(result, cursor) ?: break
            val classDeclaration = enclosingJavaClassDeclaration(result, match.range.first)
            if (!javaClassExtendsAny(classDeclaration, setOf("AbstractArrow"), javaInheritanceIndex)) {
                cursor = match.range.last + 1
                continue
            }
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val block = result.substring(openBrace + 1, closeBrace)
            val livingVariable = Regex("""\b([A-Za-z_$][\w$]*)\.push\s*\(""")
                .find(block)
                ?.groupValues
                ?.get(1)
            val methodRange = enclosingMethodRange(result, match.range.first)
            val methodPrefix = methodRange?.let { result.substring(it.first, match.range.first) }
            val damageSource = methodPrefix?.let(::lastDamageSourceVariable)
            if (livingVariable == null || damageSource == null || !block.contains("this.getKnockback()")) {
                cursor = closeBrace + 1
                continue
            }

            val statementStart = result.lastIndexOf('\n', match.range.first).let { if (it < 0) 0 else it + 1 }
            val indent = result.substring(statementStart, match.range.first).takeWhile { it == ' ' || it == '\t' }
            val replacement = "${indent}this.doKnockback($livingVariable, $damageSource);"
            result = result.substring(0, statementStart) + replacement + result.substring(closeBrace + 1)
            cursor = statementStart + replacement.length
        }
        return result
    }

    private fun migrateLegacyEntityArmorSlotAccessSource(source: String): String {
        if (!source.contains(".getArmorSlots()")) return source
        val entityVars = Regex("""\bEntity\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (entityVars.isEmpty()) return source
        var changed = false
        var result = source
        for (variable in entityVars) {
            val guarded = source.contains("$variable instanceof LivingEntity") || source.contains("$variable instanceof Player")
            if (!guarded) continue
            val before = result
            result = Regex("""\b${Regex.escape(variable)}\.getArmorSlots\(\)""")
                .replace(result, "((LivingEntity) $variable).getArmorSlots()")
            changed = changed || result != before
        }
        return if (changed) addImportIfMissing(result, "net.minecraft.world.entity.LivingEntity") else source
    }

    private fun migrateLegacyAbstractHurtingProjectilePowerFields(source: String): String {
        if (!source.contains(".xPower") && !source.contains(".yPower") && !source.contains(".zPower")) return source
        return Regex(
            """(?m)^([ \t]*)([A-Za-z_$][\w$]*)\.xPower\s*=\s*([A-Za-z_$][\w$]*)\.x\(\)\s*\*\s*([^;\r\n]+);\s*\r?\n\1\2\.yPower\s*=\s*\3\.y\(\)\s*\*\s*\4;\s*\r?\n\1\2\.zPower\s*=\s*\3\.z\(\)\s*\*\s*\4;"""
        ).replace(source) { match ->
            val indent = match.groupValues[1]
            val projectile = match.groupValues[2]
            val scale = match.groupValues[4].trim()
            "${indent}$projectile.accelerationPower = $scale;"
        }
    }

    private fun migrateEntityEffectColorParticleTrailCalls(source: String): String {
        if (!source.contains("ParticleTypes.ENTITY_EFFECT") || !source.contains(".makeTrail(")) return source
        var changed = false
        var result = migrateMethodCalls(source, ".makeTrail") { args ->
            if (args.size == 5 && args[0].trim() == "ParticleTypes.ENTITY_EFFECT") {
                changed = true
                listOf(
                    "ColorParticleOption.create(ParticleTypes.ENTITY_EFFECT, (float) ${args[1].trim()}, (float) ${args[2].trim()}, (float) ${args[3].trim()})",
                    args[4]
                )
            } else {
                args
            }
        }
        if (changed) {
            result = addImportIfMissing(result, "net.minecraft.core.particles.ColorParticleOption")
        }
        return result
    }

    private fun migrateSynchedEntityDataBufferSource(source: String): String {
        if (!source.contains("SynchedEntityData.DataValue") ||
            !source.contains("FriendlyByteBuf")) {
            return source
        }

        var result = Regex("""\bFriendlyByteBuf\b""").replace(source, "RegistryFriendlyByteBuf")
        result = removeImport(result, "net.minecraft.network.FriendlyByteBuf")
        result = addImportIfMissing(result, "net.minecraft.network.RegistryFriendlyByteBuf")
        return result
    }

    private fun migrateHurtAndBreakEquipmentSlotSource(source: String): String {
        if (!source.contains(".hurtAndBreak(") || !source.contains("onEquippedItemBroken") && !source.contains("broadcastBreakEvent")) {
            return source
        }

        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        var needsEquipmentSlot = false
        var needsServerLevel = false
        val token = ".hurtAndBreak("

        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + ".hurtAndBreak".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val callback = args.getOrNull(2)?.let(::parseBreakCallback)
            val breakCall = callback?.let { findBreakCallbackCall(it.body, it.parameter) }
            if (args.size == 3 && callback != null && breakCall != null) {
                val amount = args[0].trim()
                val entity = args[1].trim()
                val slot = normalizeBreakSlotExpression(breakCall.slotExpression) {
                    needsEquipmentSlot = true
                }
                if (breakCall.isOnlyStatement) {
                    migrated.append(source, cursor, tokenIndex)
                    migrated.append(".hurtAndBreak($amount, $entity, $slot)")
                    cursor = closeParen + 1
                    changed = true
                    continue
                }

                val statementStart = source.lastIndexOf('\n', tokenIndex).let { if (it < 0) 0 else it + 1 }
                val prefix = source.substring(statementStart, tokenIndex)
                val indent = prefix.takeWhile { it == ' ' || it == '\t' }
                val receiver = prefix.substring(indent.length).trim()
                val afterParen = source.substring(closeParen + 1)
                val semicolonOffset = afterParen.indexOf(';').takeIf {
                    it >= 0 && afterParen.substring(0, it).isBlank()
                }
                if (receiver.isNotEmpty() &&
                    prefix.substring(indent.length).trim() == receiver &&
                    semicolonOffset != null) {
                    val callbackBody = migrateBreakCallbackBody(callback.body, callback.parameter, entity, slot, "brokenItem") {
                        needsEquipmentSlot = true
                    }
                    val indentedBody = callbackBody
                        .lines()
                        .map { line -> if (line.isBlank()) line else "$indent        ${line.trim()}" }
                        .joinToString("\n")
                    migrated.append(source, cursor, statementStart)
                    migrated.append(
                        """${indent}if ($entity.level() instanceof ServerLevel serverLevel) {
${indent}    $receiver.hurtAndBreak($amount, serverLevel, $entity, brokenItem -> {
$indentedBody
${indent}    });
${indent}}"""
                    )
                    cursor = closeParen + 1 + semicolonOffset + 1
                    needsServerLevel = true
                    changed = true
                    continue
                }
            }

            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }

        if (!changed) return source
        migrated.append(source, cursor, source.length)
        var result = migrated.toString()
        if (needsEquipmentSlot) {
            result = addImportIfMissing(result, "net.minecraft.world.entity.EquipmentSlot")
        }
        if (needsServerLevel) {
            result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        }
        return result
    }

    private data class BreakCallback(val parameter: String, val body: String)

    private data class BreakCallbackCall(val slotExpression: String, val isOnlyStatement: Boolean)

    private fun parseBreakCallback(lambda: String): BreakCallback? {
        val match = Regex("""(?s)^\s*\(?\s*([A-Za-z_$][\w$]*)\s*\)?\s*->\s*(.*?)\s*$""")
            .find(lambda)
            ?: return null
        val parameter = match.groupValues[1]
        var body = match.groupValues[2].trim()
        if (body.startsWith("{") && body.endsWith("}")) {
            body = body.substring(1, body.length - 1).trim()
        }
        return BreakCallback(parameter, body)
    }

    private fun findBreakCallbackCall(body: String, parameter: String): BreakCallbackCall? {
        val receivers = listOf("onEquippedItemBroken", "broadcastBreakEvent")
        for (method in receivers) {
            val token = "$parameter.$method("
            val index = body.indexOf(token)
            if (index < 0) continue
            val openParen = index + token.length - 1
            val closeParen = findMatchingParen(body, openParen)
            if (closeParen < 0) continue
            val slotExpression = body.substring(openParen + 1, closeParen).trim()
            val before = body.substring(0, index).trim()
            val after = body.substring(closeParen + 1).trim().removePrefix(";").trim()
            return BreakCallbackCall(slotExpression, before.isEmpty() && after.isEmpty())
        }
        return null
    }

    private fun migrateBreakCallbackBody(
        body: String,
        parameter: String,
        entity: String,
        slot: String,
        brokenItem: String,
        markEquipmentSlot: () -> Unit
    ): String {
        var result = body
        val receivers = listOf("onEquippedItemBroken", "broadcastBreakEvent")
        for (method in receivers) {
            var searchFrom = 0
            val token = "$parameter.$method("
            while (searchFrom < result.length) {
                val index = result.indexOf(token, searchFrom)
                if (index < 0) break
                val openParen = index + token.length - 1
                val closeParen = findMatchingParen(result, openParen)
                if (closeParen < 0) break
                val slotExpression = result.substring(openParen + 1, closeParen).trim()
                val normalizedSlot = normalizeBreakSlotExpression(slotExpression, markEquipmentSlot)
                val replacement = "$entity.onEquippedItemBroken($brokenItem, $normalizedSlot)"
                result = result.substring(0, index) + replacement + result.substring(closeParen + 1)
                searchFrom = index + replacement.length
            }
        }
        result = Regex("""\b${Regex.escape(parameter)}\.""").replace(result, "$entity.")
        if (slot.contains("EquipmentSlot.")) markEquipmentSlot()
        return result
    }

    private fun normalizeBreakSlotExpression(expression: String, markEquipmentSlot: () -> Unit): String {
        val slot = expression.trim()
        return when {
            slot == "InteractionHand.MAIN_HAND" -> {
                markEquipmentSlot()
                "EquipmentSlot.MAINHAND"
            }
            slot == "InteractionHand.OFF_HAND" -> {
                markEquipmentSlot()
                "EquipmentSlot.OFFHAND"
            }
            slot == "hand" || slot == "handIn" -> "net.minecraft.world.entity.LivingEntity.getSlotForHand($slot)"
            slot.contains("EquipmentSlot.") || slot.contains(".getEquipmentSlot()") -> slot
            else -> "net.minecraft.world.entity.LivingEntity.getSlotForHand($slot)"
        }
    }

    private fun migrateSingleStackRecipeInputs(source: String): String {
        var changedInput = false
        var result = migrateCachedCheckSingleStackRecipeHolderBoundaries(source)
        result = migrateQuickCheckRecipeHolderCallBoundaries(result)
        if (!result.contains(".getRecipeFor(")) return result
        result = Regex("""((?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*getQuickCheck\(\)\.getRecipeFor\(\s*)(this|[A-Za-z_$][\w$]*)(\s*,)""")
            .replace(result) { match ->
                changedInput = true
                val receiver = match.groupValues[2]
                "${match.groupValues[1]}new SingleRecipeInput($receiver.getItem(0))${match.groupValues[3]}"
            }
        result = migrateMethodCalls(result, ".getRecipeFor") { args ->
            if (args.size >= 3) {
                val recipeType = args[0].trim()
                val migratedInput = when {
                    args[1].trim().startsWith("new SingleRecipeInput(") -> args[1]
                    args[1].trim().startsWith("new SimpleContainer(") -> {
                        changedInput = true
                        val inner = args[1].trim()
                            .removePrefix("new SimpleContainer(")
                            .removeSuffix(")")
                            .trim()
                        "new SingleRecipeInput($inner)"
                    }
                    recipeType == "RecipeType.SMELTING" && Regex("""^(this|[A-Za-z_$][\w$]*)$""").matches(args[1].trim()) -> {
                        changedInput = true
                        "new SingleRecipeInput(${args[1].trim()}.getItem(0))"
                    }
                    else -> args[1]
                }
                listOf(args[0], migratedInput) + args.drop(2)
            } else {
                args
            }
        }
        result = rewriteJavaInvocationArguments(result, "getRecipeFor") { args ->
            if (args.size == 2 && Regex("""RecipeManager\.CachedCheck\s*<\s*SingleRecipeInput\s*,""").containsMatchIn(result)) {
                val input = args[0].trim()
                if (!input.startsWith("new SingleRecipeInput(") &&
                    Regex("""^(?:this|[A-Za-z_$][\w$]*)$""").matches(input)) {
                    changedInput = true
                    listOf("new SingleRecipeInput($input.getItem(0))", args[1])
                } else {
                    null
                }
            } else {
                null
            }
        }

        if (changedInput) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.SingleRecipeInput")
            val withoutSimpleContainerImport = removeImport(result, "net.minecraft.world.SimpleContainer")
            if (!Regex("""\bSimpleContainer\b""").containsMatchIn(withoutSimpleContainerImport)) {
                result = withoutSimpleContainerImport
            }
        }

        var needsRecipeHolder = false
        result = Regex("""(?m)(\.getRecipeFor\([^;\r\n]+)\.orElse\(null\)""")
            .replace(result) { match ->
                val call = match.groupValues[1]
                if ((!call.contains("RecipeType.SMELTING") && !call.contains("new SingleRecipeInput(")) || call.contains(".map(")) {
                    match.value
                } else {
                    needsRecipeHolder = true
                    "$call.map(RecipeHolder::value).orElse(null)"
                }
            }
        result = Regex(
            """(?s)(\.getRecipeFor\([^;\r\n]*?\))\.map\(AbstractCookingRecipe::getCookingTime\)"""
        ).replace(result) { match ->
            needsRecipeHolder = true
            "${match.groupValues[1]}.map(RecipeHolder::value).map(AbstractCookingRecipe::getCookingTime)"
        }
        result = Regex(
            """(?s)(\.getRecipeFor\([^;\r\n]*?\))\.map\(AbstractCookingRecipe::([A-Za-z_$][\w$]*)\)"""
        ).replace(result) { match ->
            if (match.value.contains("RecipeHolder::value")) {
                match.value
            } else {
                needsRecipeHolder = true
                "${match.groupValues[1]}.map(RecipeHolder::value).map(AbstractCookingRecipe::${match.groupValues[2]})"
            }
        }
        Regex("""RecipeManager\.CachedCheck\s*<\s*SingleRecipeInput\s*,\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s*>""")
            .findAll(result)
            .map { it.groupValues[1].substringAfterLast('.') }
            .toSet()
            .forEach { recipeType ->
                result = Regex(
                    """(?s)(\.getRecipeFor\([^;\r\n]*?\))\.map\(${Regex.escape(recipeType)}::([A-Za-z_$][\w$]*)\)"""
                ).replace(result) { match ->
                    needsRecipeHolder = true
                    "${match.groupValues[1]}.map(RecipeHolder::value).map($recipeType::${match.groupValues[2]})"
                }
                result = Regex(
                    """RecipeHolder<${Regex.escape(recipeType)}>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]*?\.getRecipeFor\([^;\r\n]*?\))\.map\(RecipeHolder::value\)\.orElse\(null\)\s*;"""
                ).replace(result) { match ->
                    needsRecipeHolder = true
                    "RecipeHolder<$recipeType> ${match.groupValues[1]} = ${match.groupValues[2]}.orElse(null);"
                }
                val holderVariables = Regex("""RecipeHolder\s*<\s*${Regex.escape(recipeType)}\s*>\s+([A-Za-z_$][\w$]*)\b""")
                    .findAll(result)
                    .map { it.groupValues[1] }
                    .toSet()
                for (holderVar in holderVariables) {
                    result = Regex(
                        """\b${Regex.escape(holderVar)}\s*=\s*([^;\r\n]*?\.getRecipeFor\([^;\r\n]*?\))\.map\(RecipeHolder::value\)\.orElse\(null\)\s*;"""
                    ).replace(result) { match ->
                        "$holderVar = ${match.groupValues[1]}.orElse(null);"
                    }
                    result = Regex("""\b${Regex.escape(holderVar)}\.getId\s*\(\s*\)""")
                        .replace(result, "$holderVar.id()")
                    result = Regex("""\b${Regex.escape(holderVar)}\.(get[A-Z][A-Za-z0-9_$]*)\s*\(""")
                        .replace(result, "$holderVar.value().$1(")
                }
            }
        Regex("""RecipeHolder\s*<\s*[^;\r\n]+?\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
            .forEach { holderVar ->
                result = Regex(
                    """\b${Regex.escape(holderVar)}\s*=\s*([^;\r\n]*?\.getRecipeFor\([^;\r\n]*?\))\.map\(RecipeHolder::value\)\.orElse\(null\)\s*;"""
                ).replace(result) { match ->
                    needsRecipeHolder = true
                    "$holderVar = ${match.groupValues[1]}.orElse(null);"
                }
            }
        result = Regex("""\.map\(\s*([A-Za-z_$][\w$]*)\s*->\s*\1\.getResultItem\(""")
            .replace(result) { match ->
                if (result.contains(".getRecipeFor(")) {
                    ".map(${match.groupValues[1]} -> ${match.groupValues[1]}.value().getResultItem("
                } else {
                    match.value
                }
            }
        result = migrateRecipeHolderSingleStackAssembleCalls(result)

        if (needsRecipeHolder) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        }
        if (result.contains("RecipeHolder<")) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        }
        return result
    }

    private fun migrateQuickCheckRecipeHolderCallBoundaries(source: String): String {
        if (!source.contains("getQuickCheck().getRecipeFor(")) return source
        val holderAssignedVariables = Regex("""\b([A-Za-z_$][\w$]*)\s*=\s*[^;\r\n]*getQuickCheck\(\)\.getRecipeFor\(""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (holderAssignedVariables.isEmpty()) return source

        var result = source
        var changed = false
        for (variable in holderAssignedVariables) {
            val id = Regex.escape(variable)
            result = Regex("""\bRecipe\s*<\s*\?\s*>\s+$id\s*;""")
                .replace(result) {
                    changed = true
                    "RecipeHolder<?> $variable;"
