        var result = Regex(
            """(?s)([A-Za-z_$][\w$.]*)\.sendParticles\(\s*ParticleTypes\.ENTITY_EFFECT\s*,\s*([^,;]+?)\s*,\s*([^,;]+?)\s*,\s*([^,;]+?)\s*,\s*([^,;]+?)\s*,\s*([^,;]+?)\s*,\s*([^,;]+?)\s*,\s*([^,;]+?)\s*,\s*([^)]+?)\s*\)"""
        ).replace(source) { match ->
