            !source.contains("getRarity().getWeight()")) {
            return source
        }

        var result = source
        var changed = false

        val legacyMergePattern = Regex(
            """(?s)\s*//[^\r\n]*result has innate enchantments[^\r\n]*\r?\n\s*Map<Enchantment,\s*Integer>\s+([A-Za-z_$][\w$]*)\s*=\s*EnchantmentHelper\.getEnchantments\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;\s*\r?\n\s*Map<Enchantment,\s*Integer>\s+([A-Za-z_$][\w$]*)\s*=\s*EnchantmentHelper\.getEnchantments\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;\s*\r?\n\s*//[^\r\n]*\r?\n\s*\3\.keySet\(\)\.removeIf\(\s*([A-Za-z_$][\w$]*)\s*->\s*\5\s*==\s*null\s*\|\|\s*!\5\.canEnchant\(\s*\2\s*\)\s*\)\s*;\s*\r?\n\s*if\s*\(\s*([A-Za-z_$][\w$]*)\s*!=\s*null\s*\)\s*\{\s*\r?\n\s*//[^\r\n]*\r?\n\s*\6\.remove\(\s*"ench"\s*\)\s*;\s*\r?\n\s*\6\.remove\(\s*"Damage"\s*\)\s*;\s*\r?\n\s*\2\.set\(\s*net\.minecraft\.core\.component\.DataComponents\.CUSTOM_DATA\s*,\s*net\.minecraft\.world\.item\.component\.CustomData\.of\(\s*\6\s*\)\s*\)\s*;\s*\r?\n\s*EnchantmentHelper\.setEnchantments\(\s*\3\s*,\s*\2\s*\)\s*;\s*\r?\n\s*\}\s*\r?\n\s*//[^\r\n]*\r?\n\s*for\s*\(\s*Map\.Entry<Enchantment,\s*Integer>\s+([A-Za-z_$][\w$]*)\s*:\s*\1\.entrySet\(\)\s*\)\s*\{\s*\r?\n\s*Enchantment\s+([A-Za-z_$][\w$]*)\s*=\s*\7\.getKey\(\)\s*;\s*\r?\n\s*int\s+([A-Za-z_$][\w$]*)\s*=\s*\7\.getValue\(\)\s*;\s*\r?\n\s*//[^\r\n]*\r?\n\s*//[^\r\n]*\r?\n\s*if\s*\(\s*EnchantmentHelper\.isEnchantmentCompatible\(\s*EnchantmentHelper\.getEnchantments\(\s*\2\s*\)\.keySet\(\)\s*,\s*\8\s*\)\s*&&\s*EnchantmentHelper\.getTagEnchantmentLevel\(\s*\8\s*,\s*\2\s*\)\s*<\s*\9\s*\)\s*\{\s*\r?\n\s*\2\.enchant\(\s*\8\s*,\s*\9\s*\)\s*;\s*\r?\n\s*\}\s*\r?\n\s*\}"""
        )
        result = legacyMergePattern.replace(result) { match ->
            changed = true
            val resultStack = match.groupValues[2]
            val inputEnchantments = match.groupValues[3]
            val inputStack = match.groupValues[4]
            val inputTags = match.groupValues[6]
            """

				ItemEnchantments.Mutable $inputEnchantments = new ItemEnchantments.Mutable($inputStack.getOrDefault(net.minecraft.core.component.DataComponents.ENCHANTMENTS, ItemEnchantments.EMPTY));
				if ($resultStack.has(net.minecraft.core.component.DataComponents.ENCHANTMENTS)) {
					$resultStack.get(net.minecraft.core.component.DataComponents.ENCHANTMENTS).entrySet().forEach(enchantment -> $inputEnchantments.set(enchantment.getKey(), enchantment.getIntValue()));
				}
				$inputEnchantments.removeIf(enchantment -> !$resultStack.supportsEnchantment(enchantment));

				if ($inputTags != null) {
					$inputTags.remove("Damage");
					$resultStack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA, net.minecraft.world.item.component.CustomData.of($inputTags));
				}

				$resultStack.remove(net.minecraft.core.component.DataComponents.ENCHANTMENTS);
				EnchantmentHelper.setEnchantments($resultStack, $inputEnchantments.toImmutable());
            """.trimEnd()
        }

        result = Regex("""EnchantmentHelper\.getEnchantments\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\([^)]*\))?)*)\s*\)\.size\(\)""")
            .replace(result) { match ->
                changed = true
                "${match.groupValues[1]}.getTagEnchantments().size()"
            }

        result = Regex(
            """for\s*\(\s*Map\.Entry<Enchantment,\s*Integer>\s+([A-Za-z_$][\w$]*)\s*:\s*EnchantmentHelper\.getEnchantments\(\s*([A-Za-z_$][\w$]*)\s*\)\.entrySet\(\)\s*\)"""
        ).replace(result) { match ->
            changed = true
            "for (Object2IntMap.Entry<Holder<Enchantment>> ${match.groupValues[1]} : ${match.groupValues[2]}.getTagEnchantments().entrySet())"
        }
        result = Regex("""Enchantment\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.getKey\(\)\s*;""")
            .replace(result) { match ->
                val entry = match.groupValues[2]
                if (result.contains("Object2IntMap.Entry<Holder<Enchantment>> $entry")) {
                    changed = true
                    "Enchantment ${match.groupValues[1]} = $entry.getKey().value();"
                } else {
                    match.value
                }
            }
        result = Regex("""int\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.getValue\(\)\s*;""")
            .replace(result) { match ->
                val entry = match.groupValues[2]
                if (result.contains("Object2IntMap.Entry<Holder<Enchantment>> $entry")) {
                    changed = true
                    "int ${match.groupValues[1]} = $entry.getIntValue();"
                } else {
                    match.value
                }
            }
        result = Regex("""([A-Za-z_$][\w$]*)\s*!=\s*null\s*&&\s*([A-Za-z_$][\w$]*)\s*>\s*0""")
            .replace(result) { match ->
                val maybeEnchantment = match.groupValues[1]
                val level = match.groupValues[2]
                if (Regex("""Enchantment\s+${Regex.escape(maybeEnchantment)}\s*=""").containsMatchIn(result)) {
                    changed = true
                    "$level > 0"
                } else {
                    match.value
                }
            }

        if (result.contains("getRarity().getWeight()")) {
            result = result.replace(".getRarity().getWeight()", ".getWeight()")
            changed = true
        }

        if (!changed) return source
        if (result.contains("ItemEnchantments.")) {
            result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.ItemEnchantments")
        }
        if (result.contains("Object2IntMap.Entry<Holder<Enchantment>>")) {
            result = addImportIfMissing(result, "it.unimi.dsi.fastutil.objects.Object2IntMap")
            result = addImportIfMissing(result, "net.minecraft.core.Holder")
        }
        val withoutJavaMap = removeImport(result, "java.util.Map")
        if (!Regex("""\bMap\s*<""").containsMatchIn(withoutJavaMap)) {
            result = withoutJavaMap
        }
        return result
    }

    private fun migrateDeferredSpawnEggLookups(source: String): String {
        if (!source.contains("DeferredSpawnEggItem.fromEntityType(")) return source

        var changed = false
        var index = 0
        val expr = """((?:[^()]|\([^()]*\))+)"""
        val pattern = Regex(
            """(?m)^([ \t]*)(.+?\.addInvisibleIngredients\([^\r\n;]+\))\.addItemStack\(\s*new\s+ItemStack\(\s*DeferredSpawnEggItem\.fromEntityType\(\s*$expr\s*\)\s*\)\s*\)\s*;\s*$"""
        )
        var result = pattern.replace(source) { match ->
            changed = true
            val indent = match.groupValues[1]
            val receiver = match.groupValues[2].trim()
            val entityType = match.groupValues[3].trim()
            val variable = "spawnEggItem${index++}"
            """${indent}SpawnEggItem $variable = SpawnEggItem.byId($entityType);
${indent}if ($variable != null) {
${indent}    $receiver.addItemStack(new ItemStack($variable));
${indent}}"""
        }

        if (!changed) {
            result = Regex("""DeferredSpawnEggItem\.fromEntityType\(\s*$expr\s*\)""")
                .replace(result) { match ->
                    changed = true
                    "SpawnEggItem.byId(${match.groupValues[1].trim()})"
                }
        }
        if (!changed) return source

        result = addImportIfMissing(result, "net.minecraft.world.item.SpawnEggItem")
        if (!result.contains("DeferredSpawnEggItem.")) {
            result = removeImport(result, "net.neoforged.neoforge.common.DeferredSpawnEggItem")
            result = removeImport(result, "net.minecraftforge.common.ForgeSpawnEggItem")
        }
        return result
    }

    private fun migrateLegacyEntityTypeSpawnCompoundTagSource(source: String): String {
        if (!source.contains(".spawn(") || !source.contains("CompoundTag")) return source

        var changed = false
        val spawnPattern = Regex(
            """(?m)^([ \t]*)([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.spawn\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([^,]+?)\s*,\s*([^,]+?)\s*,\s*([^,]+?)\s*,\s*([^,]+?)\s*,\s*([^)]+?)\s*\)\s*;"""
        )
        val result = spawnPattern.replace(source) { match ->
            val methodRange = enclosingMethodRange(source, match.range.first) ?: return@replace match.value
            val methodPrefix = source.substring(methodRange.first, match.range.first)
            val tagVariable = match.groupValues[6]
            if (!Regex("""\bCompoundTag\s+${Regex.escape(tagVariable)}\s*=""").containsMatchIn(methodPrefix)) {
                return@replace match.value
            }
            val itemStackVariables = Regex("""\bItemStack\s+([A-Za-z_$][\w$]*)\s*=""")
                .findAll(methodPrefix)
                .map { it.groupValues[1] }
                .distinct()
                .toList()
            if (itemStackVariables.size != 1) return@replace match.value
            val indent = match.groupValues[1]
            val entityType = match.groupValues[2]
            val entityVariable = match.groupValues[3]
            val spawnReceiver = match.groupValues[4]
            val level = match.groupValues[5]
            val player = match.groupValues[7].trim()
            val pos = match.groupValues[8].trim()
            val spawnType = match.groupValues[9].trim()
            val shouldOffsetY = match.groupValues[10].trim()
            val shouldOffsetYMore = match.groupValues[11].trim()
            val itemStackVariable = itemStackVariables.single()
            changed = true
            buildString {
                appendLine("${indent}$entityType $entityVariable = $spawnReceiver.spawn($level,")
                appendLine("${indent}        net.minecraft.world.entity.EntityType.appendDefaultStackConfig(consumerEntity -> {")
                appendLine("${indent}            if ($tagVariable != null && consumerEntity instanceof net.minecraft.world.entity.LivingEntity livingEntity) {")
                appendLine("${indent}                livingEntity.readAdditionalSaveData($tagVariable);")
                appendLine("${indent}            }")
                appendLine("${indent}        }, $level, $itemStackVariable, $player),")
                append("${indent}        $pos, $spawnType, $shouldOffsetY, $shouldOffsetYMore);")
            }
        }
        return if (changed) result else source
    }

    private fun enclosingMethodRange(source: String, index: Int): IntRange? {
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\r?\n[ \t]*)*(?:(?:public|protected|private|static|final|synchronized)\s+)*(?:<[^>{};]+>\s*)?[A-Za-z_$][\w$<>\[\].?,\s]*\s+[A-Za-z_$][\w$]*\s*\([^;{}]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        var best: IntRange? = null
        methodPattern.findAll(source).forEach { match ->
            val openBrace = source.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (closeBrace > openBrace && index in (openBrace + 1) until closeBrace) {
                val candidate = (openBrace + 1) until closeBrace
                if (best == null || candidate.count() < best!!.count()) {
                    best = candidate
                }
            }
        }
        return best
    }

    private fun enclosingMethodText(source: String, index: Int): String? {
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\r?\n[ \t]*)*(?:(?:public|protected|private|static|final|synchronized|default|abstract)\s+)*(?:<[^>{};]+>\s*)?[A-Za-z_$][\w$<>\[\].?,\s]*\s+[A-Za-z_$][\w$]*\s*\([^;{}]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        var best: IntRange? = null
        methodPattern.findAll(source).forEach { match ->
            val openBrace = source.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (closeBrace > openBrace && index in (openBrace + 1) until closeBrace) {
                val candidate = match.range.first..closeBrace
                if (best == null || candidate.count() < best!!.count()) {
                    best = candidate
                }
            }
        }
        return best?.let { source.substring(it) }
    }

    private fun uniqueLocalNameInScope(scope: String, baseName: String): String {
        if (!Regex("""\b${Regex.escape(baseName)}\b""").containsMatchIn(scope)) return baseName
        var index = 1
        while (Regex("""\b${Regex.escape(baseName + index)}\b""").containsMatchIn(scope)) {
            index++
        }
        return baseName + index
    }

    private fun migrateEnchantmentLevelHolderLookups(source: String): String {
        if (!source.contains(".getEnchantmentLevel(Enchantments.")) return source

        val registryAccess = when {
            Regex("""\bLootParams\.Builder\s+([A-Za-z_$][\w$]*)""").find(source) != null ->
                Regex("""\bLootParams\.Builder\s+([A-Za-z_$][\w$]*)""").find(source)!!.groupValues[1] + ".getLevel().registryAccess()"
            Regex("""\bLevel\s+([A-Za-z_$][\w$]*)""").find(source) != null ->
                Regex("""\bLevel\s+([A-Za-z_$][\w$]*)""").find(source)!!.groupValues[1] + ".registryAccess()"
            else -> return source
        }

        var result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\([^)]*\))?)*)\.getEnchantmentLevel\(Enchantments\.([A-Z0-9_]+)\)""")
            .replace(source) { match ->
                val stack = match.groupValues[1]
                val enchantment = match.groupValues[2]
                """$registryAccess.lookup(net.minecraft.core.registries.Registries.ENCHANTMENT)
                    .flatMap(registry -> registry.get(Enchantments.$enchantment))
                    .map(holder -> net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(holder, $stack))
                    .orElse(0)"""
            }
        if (result.contains("EnchantmentHelper.getItemEnchantmentLevel")) {
            result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.EnchantmentHelper")
        }
        return result
    }

    private fun migrateLegacySweepingDamageRatioCalls(source: String): String {
        if (!source.contains("EnchantmentHelper.getSweepingDamageRatio(")) return source
        var result = Regex("""EnchantmentHelper\.getSweepingDamageRatio\(\s*([A-Za-z_$][\w$]*)\s*\)""")
            .replace(source) { match ->
                "(float) ${match.groupValues[1]}.getAttributeValue(Attributes.SWEEPING_DAMAGE_RATIO)"
            }
        if (result != source) {
            result = addImportIfMissing(result, "net.minecraft.world.entity.ai.attributes.Attributes")
        }
        return result
    }

    private fun migrateLegacyEnchantmentHelperCalls(source: String): String {
        if (!source.contains("Enchantments.") &&
            !source.contains("EnchantmentHelper.hasFrostWalker(") &&
            !source.contains("EnchantmentHelper.getTagEnchantmentLevel(")) {
            return source
        }

        var result = migrateLegacyEnchantmentConstantNames(source)

        if (result.contains("EnchantmentHelper.hasFrostWalker(")) {
            result = Regex("""EnchantmentHelper\.hasFrostWalker\(\s*([A-Za-z_$][\w$]*)\s*\)""")
                .replace(result) { match ->
                    val living = match.groupValues[1]
                    "EnchantmentHelper.hasTag($living.getItemBySlot(EquipmentSlot.FEET), EnchantmentTags.PREVENTS_ICE_MELTING)"
                }
            result = addImportIfMissing(result, "net.minecraft.tags.EnchantmentTags")
            result = addImportIfMissing(result, "net.minecraft.world.entity.EquipmentSlot")
        }

        val hasMigratableEnchantmentLookup =
            result.contains("EnchantmentHelper.getTagEnchantmentLevel(Enchantments.") ||
                result.contains("EnchantmentHelper.getItemEnchantmentLevel(Enchantments.") ||
                Regex("""EnchantmentHelper\.(?:getTagEnchantmentLevel|getItemEnchantmentLevel)\(\s*(?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$]+\.get\(\)\s*,""")
                    .containsMatchIn(result)
        if (!hasMigratableEnchantmentLookup) {
            return result
        }

        val registryAccess = inferRegistryAccessExpression(result)
        if (registryAccess != null) {
            result = migrateLegacyEnchantmentLevelHelperCall(result, "getTagEnchantmentLevel", registryAccess)
            result = migrateLegacyEnchantmentLevelHelperCall(result, "getItemEnchantmentLevel", registryAccess)
        } else {
            result = migrateLegacyEnchantmentResourceKeyHelperCall(result, "getTagEnchantmentLevel")
            result = migrateLegacyEnchantmentResourceKeyHelperCall(result, "getItemEnchantmentLevel")
        }
        return result
    }

    private fun migrateLegacyEnchantmentConstantNames(source: String): String {
        if (!source.contains("Enchantments.")) return source
        val renamedEnchantments = mapOf(
            "ALL_DAMAGE_PROTECTION" to "PROTECTION",
            "FALL_PROTECTION" to "FEATHER_FALLING",
            "FIRE_PROTECTION" to "FIRE_PROTECTION",
            "BLAST_PROTECTION" to "BLAST_PROTECTION",
            "PROJECTILE_PROTECTION" to "PROJECTILE_PROTECTION",
            "RESPIRATION" to "RESPIRATION",
            "AQUA_AFFINITY" to "AQUA_AFFINITY",
            "THORNS" to "THORNS",
            "DEPTH_STRIDER" to "DEPTH_STRIDER",
            "FROST_WALKER" to "FROST_WALKER",
            "BINDING_CURSE" to "BINDING_CURSE",
            "SOUL_SPEED" to "SOUL_SPEED",
            "SWIFT_SNEAK" to "SWIFT_SNEAK",
            "DAMAGE_ALL" to "SHARPNESS",
            "DAMAGE_UNDEAD" to "SMITE",
            "DAMAGE_ARTHROPODS" to "BANE_OF_ARTHROPODS",
            "KNOCKBACK" to "KNOCKBACK",
            "FIRE_ASPECT" to "FIRE_ASPECT",
            "MOB_LOOTING" to "LOOTING",
            "SWEEPING_EDGE" to "SWEEPING_EDGE",
            "BLOCK_EFFICIENCY" to "EFFICIENCY",
            "DIG_SPEED" to "EFFICIENCY",
            "SILK_TOUCH" to "SILK_TOUCH",
            "DURABILITY" to "UNBREAKING",
            "BLOCK_FORTUNE" to "FORTUNE",
            "LOOT_BONUS_BLOCKS" to "FORTUNE",
            "LOOT_BONUS_MOBS" to "LOOTING",
            "ARROW_DAMAGE" to "POWER",
            "POWER_ARROWS" to "POWER",
            "ARROW_KNOCKBACK" to "PUNCH",
            "PUNCH_ARROWS" to "PUNCH",
            "ARROW_FIRE" to "FLAME",
            "FLAMING_ARROWS" to "FLAME",
            "ARROW_INFINITE" to "INFINITY",
            "INFINITY_ARROWS" to "INFINITY",
            "MENDING" to "MENDING",
            "VANISHING_CURSE" to "VANISHING_CURSE"
        )
        var result = source
        for ((oldName, newName) in renamedEnchantments) {
            if (oldName != newName) {
                result = result.replace("Enchantments.$oldName", "Enchantments.$newName")
            }
        }
        return result
    }

    private fun migrateLegacyEnchantmentLevelHelperCall(source: String, methodName: String, registryAccess: String): String {
        val token = "EnchantmentHelper.$methodName("
        if (!source.contains(token)) return source
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + "EnchantmentHelper.$methodName".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val enchantment = args.getOrNull(0)?.trim()
            val stack = args.getOrNull(1)?.trim()
            val enchantmentMatch = enchantment?.let { Regex("""^Enchantments\.([A-Z0-9_]+)$""").find(it) }
            val resourceKeyMatch = enchantment?.let { Regex("""^((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$]+)\.get\(\)$""").find(it) }
            if (args.size == 2 && enchantmentMatch != null && stack != null) {
                val enchantmentName = enchantmentMatch.groupValues[1]
                migrated.append(source, cursor, tokenIndex)
                migrated.append(
                    """$registryAccess.lookup(net.minecraft.core.registries.Registries.ENCHANTMENT)
                    .flatMap(registry -> registry.get(Enchantments.$enchantmentName))
                    .map(holder -> EnchantmentHelper.$methodName(holder, $stack))
                    .orElse(0)"""
                )
                cursor = closeParen + 1
                changed = true
                continue
            }
            if (args.size == 2 && resourceKeyMatch != null && stack != null) {
                val enchantmentKey = resourceKeyMatch.groupValues[1]
                migrated.append(source, cursor, tokenIndex)
                migrated.append(
                    """$registryAccess.lookup(net.minecraft.core.registries.Registries.ENCHANTMENT)
                    .flatMap(registry -> registry.get($enchantmentKey))
                    .map(holder -> EnchantmentHelper.$methodName(holder, $stack))
                    .orElse(0)"""
                )
                cursor = closeParen + 1
                changed = true
                continue
            }
            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateLegacyEnchantmentResourceKeyHelperCall(source: String, methodName: String): String {
        val token = "EnchantmentHelper.$methodName("
        if (!source.contains(token)) return source
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + "EnchantmentHelper.$methodName".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val enchantment = args.getOrNull(0)?.trim()
            val stack = args.getOrNull(1)?.trim()
            val resourceKeyMatch = enchantment?.let { Regex("""^((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$]+)\.get\(\)$""").find(it) }
            if (args.size == 2 && resourceKeyMatch != null && stack != null) {
                val enchantmentKey = resourceKeyMatch.groupValues[1]
                migrated.append(source, cursor, tokenIndex)
                migrated.append(
                    "EnchantmentHelper.$methodName(net.neoforged.neoforge.common.CommonHooks.resolveLookup(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow($enchantmentKey), $stack)"
                )
                cursor = closeParen + 1
                changed = true
                continue
            }
            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun inferRegistryAccessExpression(source: String): String? {
        topLevelSelfRegistryAccessExpression(source)?.let { return it }
        val declarations = mutableListOf<String>()
        listOf(
            "RegistryAccess",
            "ServerLevel",
            "Level",
            "WorldGenLevel",
            "ServerLevelAccessor",
            "LevelAccessor",
            "LevelReader",
            "Inventory",
            "ServerPlayer",
            "Player",
            "LivingEntity",
            "Entity",
            "Mob"
        ).forEach { type ->
            Regex("""\b$type\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(source)
                .forEach { declarations += "$type ${it.groupValues[1]}" }
        }
        return registryAccessFromParameters(declarations)
    }

    private fun registryAccessExpressionForEnclosingMethod(source: String, offset: Int): String? {
        return registryAccessFromParameters(currentMethodParametersBeforeOffset(source, offset))
    }

    private fun currentMethodParametersBeforeOffset(source: String, offset: Int): List<String> {
        val methodPattern = Regex(
            """(?m)(?:^|\r?\n)[ \t]*(?:(?:@[A-Za-z_$][\w$]*(?:\([^)]*\))?\s*)*)(?:(?:public|protected|private|static|final|synchronized)\s+)+[A-Za-z_$][\w$<>\[\].?,\s]*\s+[A-Za-z_$][\w$]*\s*\(([^()]*)\)\s*\{"""
        )
        return methodPattern.findAll(source)
            .filter { it.range.first < offset }
            .lastOrNull { match ->
                val openBrace = source.indexOf('{', match.range.last - 1)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
                closeBrace >= offset
            }
            ?.groupValues
            ?.get(1)
            ?.let { splitTopLevelJavaArgs(it) }
            ?: emptyList()
    }

    private fun registryAccessFromParameters(parameters: List<String>): String? {
        holderLookupProviderFromParameters(parameters)?.let { return it }
        val parameterPattern = Regex("""(?:final\s+)?(?:@[A-Za-z_$][\w$]*(?:\([^)]*\))?\s*)*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*(?:<[^>]+>)?)\s+([A-Za-z_$][\w$]*)$""")
        val parsed = parameters.mapNotNull { parameter ->
            val cleaned = parameter.trim()
                .replace(Regex("""\s+"""), " ")
            parameterPattern.find(cleaned)?.let { it.groupValues[1].substringAfterLast('.') to it.groupValues[2] }
        }
        val explicitRegistryAccess = parsed
            .filter { it.first == "RegistryAccess" }
            .map { it.second }
            .distinct()
        if (explicitRegistryAccess.size == 1) return explicitRegistryAccess.single()
        if (explicitRegistryAccess.size > 1) return null

        val levelRegistryAccess = parsed
            .filter { it.first in setOf("ServerLevel", "Level", "WorldGenLevel", "ServerLevelAccessor", "LevelAccessor", "LevelReader") }
            .map { "${it.second}.registryAccess()" }
            .distinct()
        if (levelRegistryAccess.size == 1) return levelRegistryAccess.single()
        if (levelRegistryAccess.size > 1) return null

        val inventoryRegistryAccess = parsed
            .filter { it.first == "Inventory" }
            .map { "${it.second}.player.registryAccess()" }
            .distinct()
        if (inventoryRegistryAccess.size == 1) return inventoryRegistryAccess.single()
        if (inventoryRegistryAccess.size > 1) return null

        val entityRegistryAccess = parsed
            .filter { it.first in setOf("ServerPlayer", "Player", "LivingEntity", "Entity", "Mob") }
            .map { "${it.second}.registryAccess()" }
            .distinct()
        if (entityRegistryAccess.size == 1) return entityRegistryAccess.single()
        return null
    }

    private fun holderLookupProviderFromParameters(parameters: List<String>): String? {
        val parameterPattern = Regex("""(?:final\s+)?(?:@[A-Za-z_$][\w$]*(?:\([^)]*\))?\s*)*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s+([A-Za-z_$][\w$]*)$""")
        val providers = parameters.mapNotNull { parameter ->
            val cleaned = parameter.trim()
                .replace(Regex("""\s+"""), " ")
            val match = parameterPattern.find(cleaned) ?: return@mapNotNull null
            val type = match.groupValues[1]
            if (type == "HolderLookup.Provider" || type == "net.minecraft.core.HolderLookup.Provider") {
                match.groupValues[2]
            } else {
                null
            }
        }.distinct()
        return providers.singleOrNull()
    }

    private fun registryAccessExpressionAt(source: String, offset: Int): String? {
        val parameters = currentMethodParametersBeforeOffset(source, offset)
        return holderLookupProviderFromParameters(parameters)
            ?: registryAccessFromParameters(parameters)
            ?: selfRegistryAccessExpression(source, offset)
    }

    private fun topLevelSelfRegistryAccessExpression(source: String): String? {
        val typeMatch = Regex(
            """(?m)^[ \t]*(?:(?:public|protected|private|abstract|final|static)\s+)*(?:class|record)\s+[A-Za-z_$][\w$]*\b([^{};]*)\{"""
        ).find(source) ?: return null
        return if (javaTypeHeaderExtendsRegistryAccessEntity(typeMatch.groupValues[1])) "this.registryAccess()" else null
    }

    private fun selfRegistryAccessExpression(source: String, offset: Int): String? {
        val typePattern = Regex(
            """(?m)^[ \t]*(?:(?:public|protected|private|abstract|final|static)\s+)*(?:class|record)\s+[A-Za-z_$][\w$]*\b([^{};]*)\{"""
        )
        val owner = typePattern.findAll(source)
            .filter { it.range.first < offset }
            .lastOrNull { match ->
                val openBrace = match.range.last
                val closeBrace = findMatchingBrace(source, openBrace)
                closeBrace >= offset
            }
            ?: return null
        return if (javaTypeHeaderExtendsRegistryAccessEntity(owner.groupValues[1])) "this.registryAccess()" else null
    }

    private fun javaTypeHeaderExtendsRegistryAccessEntity(rawHeader: String): Boolean {
        val header = removeLeadingJavaTypeParameters(rawHeader).replace(Regex("""\s+"""), " ")
        val parent = Regex("""\bextends\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\b""")
            .find(header)
            ?.groupValues
            ?.get(1)
            ?.substringAfterLast('.')
            ?: return false
        return parent in setOf("Mob", "Monster", "LivingEntity", "Entity") ||
            parent.endsWith("Entity") ||
            parent.endsWith("Projectile")
    }

    private fun removeLeadingJavaTypeParameters(rawHeader: String): String {
        val header = rawHeader.trimStart()
        if (!header.startsWith("<")) return header
        var depth = 0
        for (index in header.indices) {
            when (header[index]) {
                '<' -> depth++
                '>' -> {
                    if (depth > 0) depth--
                    if (depth == 0) return header.substring(index + 1)
                }
            }
        }
        return header
    }

    private fun migrateLegacyDamageBonusMobTypeCalls(source: String): String {
        if (!source.contains("EnchantmentHelper.getDamageBonus(") || !source.contains(".getMobType()")) return source

        var result = source
        var changed = false
        val methodNames = Regex("""(?m)^[ \t]*(?:@Override\s*)?(?:public|protected|private)\s+[\w<>\[\].?,\s]+\s+([A-Za-z_$][\w$]*)\s*\(""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toList()
        for (methodName in methodNames) {
            val methodText = javaDeclaredMethodText(result, methodName) ?: continue
            if (!methodText.contains("EnchantmentHelper.getDamageBonus(") || !methodText.contains(".getMobType()")) continue

            val damageSourceExpr = firstHurtDamageSourceArgument(methodText) ?: continue
            val serverLevelExpr = inferServerLevelExpressionForMethod(methodText) ?: continue
            var replacement = methodText
            val baseDamageVariable = Regex("""\b(?:float|double)\s+([A-Za-z_$][\w$]*)\s*=\s*[^;\r\n]*Attributes\.ATTACK_DAMAGE[^;\r\n]*;""")
                .find(methodText)
                ?.groupValues
                ?.get(1)
            if (baseDamageVariable != null) {
                replacement = Regex(
                    """EnchantmentHelper\.getDamageBonus\(\s*([^,]+?)\s*,\s*([A-Za-z_$][\w$]*)\.getMobType\(\)\s*\)"""
                ).replace(replacement) { match ->
                    changed = true
                    val stack = match.groupValues[1].trim()
                    val living = match.groupValues[2]
                    "(EnchantmentHelper.modifyDamage($serverLevelExpr, $stack, $living, $damageSourceExpr, $baseDamageVariable) - $baseDamageVariable)"
                }
            }
            replacement = Regex(
                """([A-Za-z_$][\w$]*|(?:\d+(?:\.\d+)?F?))\s*\+\s*EnchantmentHelper\.getDamageBonus\(\s*([^,]+?)\s*,\s*([A-Za-z_$][\w$]*)\.getMobType\(\)\s*\)"""
            ).replace(replacement) { match ->
                changed = true
                val baseDamage = match.groupValues[1].trim()
                val stack = match.groupValues[2].trim()
                val living = match.groupValues[3]
                "EnchantmentHelper.modifyDamage($serverLevelExpr, $stack, $living, $damageSourceExpr, $baseDamage)"
            }
            if (replacement != methodText) {
                result = result.replace(methodText, replacement)
            }
        }

        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        return result
    }

    private fun migrateLivingDamageEventBoundarySource(source: String): String {
        if (!source.contains("LivingDamageEvent")) return source
        var result = source
        val methodPattern = Regex(
            """(?m)(?:^|\r?\n)[ \t]*(?:(?:@[A-Za-z_$][\w$]*(?:\([^)]*\))?\s*)*)(?:(?:public|protected|private|static|final|synchronized)\s+)+[A-Za-z_$][\w$<>\[\].?,\s]*\s+[A-Za-z_$][\w$]*\s*\(([^()]*)\)\s*\{"""
        )
        methodPattern.findAll(source).toList().asReversed().forEach { match ->
            val openBrace = source.indexOf('{', match.range.last - 1)
            if (openBrace < 0) return@forEach
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace < 0) return@forEach
            val methodText = result.substring(match.range.first, closeBrace + 1)
            val eventVars = Regex("""\bLivingDamageEvent\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(methodText)
                .map { it.groupValues[1] }
                .toList()
            if (eventVars.isEmpty()) return@forEach
            var replacement = methodText
            eventVars.forEach { eventVar ->
                val usesMutableDamage = Regex("""\b${Regex.escape(eventVar)}\.setAmount\(""").containsMatchIn(replacement)
                val nestedType = if (usesMutableDamage) "Pre" else "Post"
                replacement = Regex("""\bLivingDamageEvent\s+${Regex.escape(eventVar)}\b""")
                    .replace(replacement, "LivingDamageEvent.$nestedType $eventVar")
                replacement = Regex("""\b${Regex.escape(eventVar)}\.getAmount\(\)""")
                    .replace(replacement, "$eventVar.getNewDamage()")
                replacement = Regex("""\b${Regex.escape(eventVar)}\.setAmount\(""")
                    .replace(replacement, "$eventVar.setNewDamage(")
            }
            if (replacement != methodText) {
                result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            }
        }
        return result
    }

    private fun firstHurtDamageSourceArgument(methodText: String): String? {
        val sources = linkedSetOf<String>()
        var cursor = 0
        while (cursor < methodText.length) {
            val tokenIndex = methodText.indexOf(".hurt(", cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + ".hurt".length
            val closeParen = findMatchingParen(methodText, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(methodText.substring(openParen + 1, closeParen))
            if (args.size >= 2) {
                sources += args[0].trim()
            }
            cursor = closeParen + 1
        }
        return sources.singleOrNull()
    }

    private fun inferServerLevelExpressionForMethod(methodText: String): String? {
        Regex("""this\.level\(\)\s+instanceof\s+ServerLevel\s+([A-Za-z_$][\w$]*)""")
            .find(methodText)
            ?.groupValues
            ?.get(1)
            ?.let { return it }
        Regex("""\bServerLevel\s+([A-Za-z_$][\w$]*)\b""")
            .find(methodText)
            ?.groupValues
            ?.get(1)
            ?.let { return it }
        val serverCheckedLevels = Regex("""\bLevel\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(methodText)
            .map { it.groupValues[1] }
            .filter { levelName ->
                methodText.contains("if ($levelName.isClientSide()) return;") ||
                    methodText.contains("if (${levelName}.isClientSide) return;") ||
                    methodText.contains("if (!$levelName.isClientSide())")
            }
            .distinct()
            .toList()
        if (serverCheckedLevels.size == 1) {
            return "(ServerLevel) ${serverCheckedLevels.single()}"
        }
        if (methodText.contains("!this.level().isClientSide()") || methodText.contains("this.level().isClientSide()")) {
            return "(ServerLevel) this.level()"
        }
        return null
    }

    private fun migrateLegacyMobCustomDamageSourceAttacks(source: String): String {
        if (!source.contains("boolean doHurtTarget(Entity entity)") ||
            !source.contains("EnchantmentHelper.getDamageBonus(") ||
            !source.contains("EnchantmentHelper.getKnockbackBonus(") ||
            !source.contains("EnchantmentHelper.getFireAspect(") ||
            !source.contains("doEnchantDamageEffects(")) {
            return source
        }

        val methodText = javaMethodText(source, "doHurtTarget") ?: return source
        val hurtCall = Regex("""boolean\s+([A-Za-z_$][\w$]*)\s*=\s*entity\.hurt\(\s*(.+?)\s*,\s*f\s*\);""")
            .find(methodText)
            ?: return source
        val flagVar = hurtCall.groupValues[1]
        val damageSourceExpr = hurtCall.groupValues[2].trim()
        var replacement = methodText

        val oldEnchantmentBlock = Regex(
            """(?s)\s*float\s+f1\s*=\s*\(float\)\s*this\.getAttributeValue\(Attributes\.ATTACK_KNOCKBACK\);\s*if\s*\(\s*entity\s+instanceof\s+LivingEntity\s+[A-Za-z_$][\w$]*\s*\)\s*\{.*?EnchantmentHelper\.getKnockbackBonus\(this\).*?\}\s*int\s+[A-Za-z_$][\w$]*\s*=\s*EnchantmentHelper\.getFireAspect\(this\);\s*if\s*\(\s*[A-Za-z_$][\w$]*\s*>\s*0\s*\)\s*\{\s*entity\.igniteForSeconds\([^;]+;\s*\}\s*"""
        )
        replacement = oldEnchantmentBlock.replace(
            replacement,
            """
		DamageSource damagesource = $damageSourceExpr;
		if (this.level() instanceof ServerLevel serverlevel) {
			f = EnchantmentHelper.modifyDamage(serverlevel, this.getWeaponItem(), entity, damagesource, f);
		}

            """.trimIndent().prependIndent("\t\t").removePrefix("\t\t")
        )
        if (replacement == methodText) return source

        replacement = replacement.replace(hurtCall.value, "boolean $flagVar = entity.hurt(damagesource, f);")
        replacement = Regex("""if\s*\(\s*$flagVar\s*\)\s*\{\s*\r?\n\s*if\s*\(\s*f1\s*>""")
            .replace(replacement) { match ->
                match.value.replace(
                    "if (f1 >",
                    "float f1 = this.getKnockback(entity, damagesource);\n\t\t\tif (f1 >"
                )
            }
        replacement = Regex(
            """(?s)\s*if\s*\(\s*entity\s+instanceof\s+Player\s+[A-Za-z_$][\w$]*\s*\)\s*\{\s*this\.maybeDisableShield\(.*?\);\s*\}\s*"""
        ).replace(replacement, "\n")
        replacement = Regex("""this\.doEnchantDamageEffects\(\s*this\s*,\s*entity\s*\)\s*;""")
            .replace(
                replacement,
                """if (this.level() instanceof ServerLevel serverlevel1) {
				EnchantmentHelper.doPostAttackEffects(serverlevel1, entity, damagesource);
			}"""
            )

        var result = source.replace(methodText, replacement)
        result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        return result
    }

    private fun migrateLegacyMobCustomDamageSourceUtilityAttacks(source: String): String {
        if (!source.contains("EnchantmentHelper.getDamageBonus(") ||
            !source.contains("EnchantmentHelper.getKnockbackBonus(") ||
            !source.contains("EnchantmentHelper.getFireAspect(") ||
            !source.contains(".doEnchantDamageEffects(") ||
            !source.contains("DamageSource")) {
            return source
        }

        val methodNames = Regex("""(?m)^[ \t]*(?:@Override\s*)?(?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+([A-Za-z_$][\w$]*)\s*\(""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toList()
        var result = source
        var changed = false

        for (methodName in methodNames) {
            val methodText = javaDeclaredMethodText(result, methodName) ?: continue
            if (!methodText.contains("EnchantmentHelper.getDamageBonus(") ||
                !methodText.contains("EnchantmentHelper.getKnockbackBonus(") ||
                !methodText.contains("EnchantmentHelper.getFireAspect(") ||
                !methodText.contains(".doEnchantDamageEffects(")) {
                continue
            }
            val mob = Regex("""\bMob\s+([A-Za-z_$][\w$]*)\b""").find(methodText)?.groupValues?.get(1) ?: continue
            val hurtCall = Regex("""boolean\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.hurt\(\s*([^,]+?)\s*,\s*([A-Za-z_$][\w$]*)\s*\);""")
                .find(methodText)
                ?: continue
            val flag = hurtCall.groupValues[1]
            val target = hurtCall.groupValues[2]
            val damageSource = hurtCall.groupValues[3].trim()
            val damageVar = hurtCall.groupValues[4]

            var replacement = methodText
            replacement = Regex(
                """(?s)\s*float\s+([A-Za-z_$][\w$]*)\s*=\s*\(float\)\s*${Regex.escape(mob)}\.getAttributeValue\(Attributes\.ATTACK_KNOCKBACK\);\s*if\s*\(\s*${Regex.escape(target)}\s+instanceof\s+LivingEntity\s*\)\s*\{.*?EnchantmentHelper\.getKnockbackBonus\(\s*${Regex.escape(mob)}\s*\).*?\}\s*int\s+[A-Za-z_$][\w$]*\s*=\s*EnchantmentHelper\.getFireAspect\(\s*${Regex.escape(mob)}\s*\);\s*if\s*\(\s*[A-Za-z_$][\w$]*\s*>\s*0\s*\)\s*\{\s*${Regex.escape(target)}\.igniteForSeconds\([^;]+;\s*\}\s*"""
            ).replace(replacement) {
                "\n\t\tif ($mob.level() instanceof ServerLevel serverlevel) {\n" +
                    "\t\t\t$damageVar = EnchantmentHelper.modifyDamage(serverlevel, $mob.getWeaponItem(), $target, $damageSource, $damageVar);\n" +
                    "\t\t}\n"
            }
            if (replacement == methodText) continue

            replacement = replacement.replace(hurtCall.value, "boolean $flag = $target.hurt($damageSource, $damageVar);")
            replacement = Regex("""if\s*\(\s*$flag\s*\)\s*\{\s*\r?\n\s*if\s*\(\s*[A-Za-z_$][\w$]*\s*>""")
                .replace(replacement) { match ->
                    match.value.replace(
                        Regex("""if\s*\(\s*[A-Za-z_$][\w$]*\s*>"""),
                        "float f1 = (float)$mob.getAttributeValue(Attributes.ATTACK_KNOCKBACK);\n" +
                            "\t\t\tif ($mob.level() instanceof ServerLevel serverlevel2) {\n" +
                            "\t\t\t\tf1 = EnchantmentHelper.modifyKnockback(serverlevel2, $mob.getWeaponItem(), $target, $damageSource, f1);\n" +
                            "\t\t\t}\n" +
                            "\t\t\tif (f1 >"
                    )
                }
            replacement = Regex(
                """(?s)\s*if\s*\(\s*${Regex.escape(target)}\s+instanceof\s+Player\s+[A-Za-z_$][\w$]*\s*\)\s*\{\s*${Regex.escape(mob)}\.maybeDisableShield\(.*?\);\s*\}\s*"""
            ).replace(replacement, "\n")
            replacement = Regex("""${Regex.escape(mob)}\.doEnchantDamageEffects\(\s*${Regex.escape(mob)}\s*,\s*${Regex.escape(target)}\s*\)\s*;""")
                .replace(
                    replacement,
                    """if ($mob.level() instanceof ServerLevel serverlevel1) {
				EnchantmentHelper.doPostAttackEffects(serverlevel1, $target, $damageSource);
			}"""
                )

            result = result.replace(methodText, replacement)
            changed = true
        }

        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        return result
    }

    private fun migrateMobSpawnEquipmentSignatures(source: String): String {
        if (!source.contains("populateDefaultEquipmentSlots") &&
            !source.contains("populateDefaultEquipmentEnchantments") &&
            !source.contains("finalizeSpawn(")) {
            return source
        }

        var result = source
        result = Regex("""super\.finalizeSpawn\(\s*([^,]+)\s*,\s*([^,]+)\s*,\s*([^,]+)\s*,\s*([^,\)]+)\s*,\s*dataTag\s*\)""")
            .replace(result) { match ->
                "super.finalizeSpawn(${match.groupValues[1].trim()}, ${match.groupValues[2].trim()}, ${match.groupValues[3].trim()}, ${match.groupValues[4].trim()})"
            }
        result = rewriteLegacyFinalizeSpawnCalls(result)
        result = Regex("""\b(this\.)?populateDefaultEquipmentSlots\(\s*([A-Za-z_$][\w$]*)\s*,\s*\2\.getRandom\(\)\s*,\s*([^)]+)\)""")
            .replace(result) { match ->
                "${match.groupValues[1]}populateDefaultEquipmentSlots(${match.groupValues[2]}.getRandom(), ${match.groupValues[3].trim()})"
            }
        result = Regex("""\b(this\.)?populateDefaultEquipmentSlots\(\s*([A-Za-z_$][\w$]*)\.getRandom\(\)\s*,\s*([^)]+)\)""")
            .replace(result) { match ->
                "${match.groupValues[1]}populateDefaultEquipmentSlots(${match.groupValues[2]}.getRandom(), ${match.groupValues[3].trim()})"
            }
        result = Regex("""\b(this\.)?populateDefaultEquipmentEnchantments\(\s*([A-Za-z_$][\w$]*)\.getRandom\(\)\s*,\s*([^)]+)\)""")
            .replace(result) { match ->
                "${match.groupValues[1]}populateDefaultEquipmentEnchantments(${match.groupValues[2]}, ${match.groupValues[2]}.getRandom(), ${match.groupValues[3].trim()})"
            }
        result = Regex(
            """protected\s+void\s+populateDefaultEquipmentSlots\(\s*RandomSource\s+([A-Za-z_$][\w$]*)\s*,\s*DifficultyInstance\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(result) { match ->
            "protected void populateDefaultEquipmentSlots(RandomSource ${match.groupValues[1]}, DifficultyInstance ${match.groupValues[2]})"
        }
        result = Regex(
            """protected\s+void\s+populateDefaultEquipmentSlots\(\s*ServerLevelAccessor\s+[A-Za-z_$][\w$]*\s*,\s*RandomSource\s+([A-Za-z_$][\w$]*)\s*,\s*DifficultyInstance\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(result) { match ->
            "protected void populateDefaultEquipmentSlots(RandomSource ${match.groupValues[1]}, DifficultyInstance ${match.groupValues[2]})"
        }
        result = Regex(
            """protected\s+void\s+populateDefaultEquipmentEnchantments\(\s*RandomSource\s+([A-Za-z_$][\w$]*)\s*,\s*DifficultyInstance\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(result) { match ->
            "protected void populateDefaultEquipmentEnchantments(ServerLevelAccessor accessor, RandomSource ${match.groupValues[1]}, DifficultyInstance ${match.groupValues[2]})"
        }
        if (result.contains("ServerLevelAccessor accessor")) {
            result = addImportIfMissing(result, "net.minecraft.world.level.ServerLevelAccessor")
        }
        return result
    }

    private fun removeLegacyFinalizeSpawnTagGuards(source: String, tagNames: Set<String>): String {
        if (tagNames.isEmpty() || !source.contains("finalizeSpawn(")) return source

        var result = source
        tagNames.forEach { tagName ->
            result = Regex("""(?m)^[ \t]*\*\s*@param\s+${Regex.escape(tagName)}\b[^\r\n]*(?:\r?\n)?""")
                .replace(result, "")
        }

        var changed: Boolean
        do {
            changed = false
            val removals = mutableListOf<IntRange>()
            val methodPattern = Regex(
                """(?m)^[ \t]*(?:@[^\r\n]+\r?\n[ \t]*)*(?:(?:public|protected|private|static|final|synchronized)\s+)*SpawnGroupData\s+finalizeSpawn\s*\([^;{}]*\)\s*\{"""
            )

            methodPattern.findAll(result).forEach { method ->
                val methodOpen = result.indexOf('{', method.range.last)
                val methodClose = if (methodOpen >= 0) findMatchingBrace(result, methodOpen) else -1
                if (methodClose <= methodOpen) return@forEach

                var cursor = methodOpen + 1
                while (cursor in (methodOpen + 1) until methodClose) {
                    val ifIndex = result.indexOf("if", cursor)
                    if (ifIndex < 0 || ifIndex >= methodClose) break
                    if (!isStandaloneJavaToken(result, ifIndex, "if")) {
                        cursor = ifIndex + 2
                        continue
                    }
                    val lineStart = result.lastIndexOf('\n', ifIndex).let { if (it < 0) 0 else it + 1 }
                    if (result.substring(lineStart, ifIndex).any { it != ' ' && it != '\t' }) {
                        cursor = ifIndex + 2
                        continue
                    }
                    val conditionOpen = skipWhitespace(result, ifIndex + 2)
                    if (conditionOpen >= result.length || result[conditionOpen] != '(') {
                        cursor = ifIndex + 2
                        continue
                    }
                    val conditionClose = findMatchingParen(result, conditionOpen)
                    if (conditionClose < 0 || conditionClose >= methodClose) {
                        cursor = ifIndex + 2
                        continue
                    }
                    val condition = result.substring(conditionOpen + 1, conditionClose)
                    if (!conditionHasLegacyFinalizeSpawnTagGuard(condition, tagNames)) {
                        cursor = conditionClose + 1
                        continue
                    }
                    val blockOpen = skipWhitespace(result, conditionClose + 1)
                    if (blockOpen >= result.length || result[blockOpen] != '{') {
                        cursor = conditionClose + 1
                        continue
                    }
                    val blockClose = findMatchingBrace(result, blockOpen)
                    if (blockClose < 0 || blockClose >= methodClose) {
                        cursor = blockOpen + 1
                        continue
                    }

                    var removeEnd = blockClose + 1
                    if (removeEnd < result.length && result[removeEnd] == '\r') removeEnd++
                    if (removeEnd < result.length && result[removeEnd] == '\n') removeEnd++
                    removals.add(lineStart until removeEnd)
                    cursor = removeEnd
                }
            }

            if (removals.isNotEmpty()) {
                val builder = StringBuilder(result)
                removals.sortedByDescending { it.first }.forEach { range ->
                    builder.delete(range.first, range.last + 1)
                }
                result = builder.toString()
                changed = true
            }
        } while (changed)

        return result
    }

    private fun conditionHasLegacyFinalizeSpawnTagGuard(condition: String, tagNames: Set<String>): Boolean =
        tagNames.any { tagName ->
            Regex("""(?<![\w$])${Regex.escape(tagName)}\s*!=\s*null(?![\w$])""").containsMatchIn(condition)
        }

    private fun isStandaloneJavaToken(source: String, index: Int, token: String): Boolean {
        if (!source.startsWith(token, index)) return false
        val before = source.getOrNull(index - 1)
        val after = source.getOrNull(index + token.length)
        return before?.let { !it.isLetterOrDigit() && it != '_' && it != '$' } != false &&
            after?.let { !it.isLetterOrDigit() && it != '_' && it != '$' } != false
    }

    private fun rewriteLegacyFinalizeSpawnCalls(source: String): String {
        if (!source.contains(".finalizeSpawn(") ||
            !source.contains("SpawnGroupData") ||
            !source.contains("MobSpawnType")) {
            return source
        }

        return rewriteJavaCall(source, "finalizeSpawn") { receiver, args ->
            if (args.size != 5) return@rewriteJavaCall null
            val tagArg = args[4]
            if (!tagArg.matches(Regex("""[A-Za-z_$][\w$]*"""))) return@rewriteJavaCall null
            "$receiver.finalizeSpawn(${args.take(4).joinToString(", ")})"
        }
    }

    private fun migrateLegacyNeoForgeModelApiSource(source: String): String {
        if (!source.contains("CustomLoaderBuilder") &&
            !source.contains("IUnbakedGeometry") &&
            !source.contains("BlockElementFace") &&
            !source.contains("FaceBakery") &&
            !source.contains("UnbakedGeometryHelper") &&
            !source.contains("new ResourceLocation(")) {
            return source
        }

        var result = source

        if (result.contains("extends CustomLoaderBuilder")) {
            result = rewriteSuperConstructorCalls(result) { args ->
                if (args.size == 3) "super(${args.joinToString(", ")}, false)" else null
            }
        }

        val modelLocationReplacements = linkedMapOf<String, String>()
        result = Regex(
            """public\s+BakedModel\s+bake\(\s*IGeometryBakingContext\s+([A-Za-z_$][\w$]*)\s*,\s*ModelBaker\s+([A-Za-z_$][\w$]*)\s*,\s*Function<Material,\s*TextureAtlasSprite>\s+([A-Za-z_$][\w$]*)\s*,\s*ModelState\s+([A-Za-z_$][\w$]*)\s*,\s*ItemOverrides\s+([A-Za-z_$][\w$]*)\s*,\s*ResourceLocation\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(result) { match ->
            val contextName = match.groupValues[1]
            val modelLocationName = match.groupValues[6]
            modelLocationReplacements[modelLocationName] =
                "net.minecraft.resources.ResourceLocation.parse($contextName.getModelName())"
            "public BakedModel bake(IGeometryBakingContext $contextName, ModelBaker ${match.groupValues[2]}, Function<Material, TextureAtlasSprite> ${match.groupValues[3]}, ModelState ${match.groupValues[4]}, ItemOverrides ${match.groupValues[5]})"
        }

        result = rewriteJavaCall(result, "bakeElementFace") { receiver, args ->
            if (receiver != "UnbakedGeometryHelper" || args.size != 6) return@rewriteJavaCall null
            "$receiver.bakeElementFace(${args.take(5).joinToString(", ")})"
        }
        result = rewriteJavaCall(result, "bakeQuad") { receiver, args ->
            if (args.size != 9) return@rewriteJavaCall null
            "$receiver.bakeQuad(${args.take(8).joinToString(", ")})"
        }
        for ((modelLocationName, replacement) in modelLocationReplacements) {
            result = Regex("""\b${Regex.escape(modelLocationName)}\b""").replace(result, replacement)
        }

        result = rewriteJavaNew(result, "BlockElementFace") { args ->
            when {
                args.size == 5 && args[4] == "null" ->
                    "new BlockElementFace(${args.take(4).joinToString(", ")})"
                args.size == 5 ->
                    "new BlockElementFace(${args.joinToString(", ")}, new org.apache.commons.lang3.mutable.MutableObject<>())"
                else -> null
            }
        }

        result = rewriteJavaNew(result, "ResourceLocation") { args ->
            when (args.size) {
                1 -> "ResourceLocation.parse(${args[0]})"
                2 -> "ResourceLocation.fromNamespaceAndPath(${args[0]}, ${args[1]})"
                else -> null
            }
        }

        if (result.contains("BlockElementFace")) {
            val faceVariables = Regex("""\bBlockElementFace\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
            for (variable in faceVariables) {
                val escaped = Regex.escape(variable)
                result = Regex("""\b$escaped\.uv\.uvs\b""").replace(result, "$variable.uv().uvs")
                result = Regex("""\b$escaped\.uv\.rotation\b""").replace(result, "$variable.uv().rotation")
                result = Regex("""\b$escaped\.cullForDirection\b(?!\s*\()""").replace(result, "$variable.cullForDirection()")
                result = Regex("""\b$escaped\.texture\b(?!\s*\()""").replace(result, "$variable.texture()")
                result = Regex("""\b$escaped\.tintIndex\b(?!\s*\()""").replace(result, "$variable.tintIndex()")
                result = Regex("""\b$escaped\.getFaceData\(\)""").replace(result, "$variable.faceData()")
            }
        }

        return result
    }

    private fun migrateAttributeModifierResourceLocationIds(
        source: String,
        crossFileAttributeModifierIds: Set<String> = emptySet(),
        attributeModifierMethods: Map<String, Set<String>> = emptyMap(),
        genericMethodReturnTypes: Map<String, String> = emptyMap(),
        attributeModifierIdMethodArguments: Set<AttributeModifierIdMethodArgument> = emptySet()
    ): String {
        val ownerName = javaTopLevelTypeName(source)
        val hasAttributeModifierIdMethodArguments = ownerName != null &&
            attributeModifierIdMethodArguments.any { it.owner == ownerName }
        if (source.contains("getDefaultAttributeModifiers(EquipmentSlot") &&
            source.contains("ImmutableMultimap") &&
            source.contains("new AttributeModifier(")) {
            return source
        }
        if (!source.contains("AttributeModifier") &&
            !source.contains("UUID.fromString") &&
            !source.contains(".hasModifier(") &&
            !source.contains(".removeModifier(") &&
            !source.contains(".getModifier(") &&
            !source.contains(".addAttributeModifier(") &&
            !hasAttributeModifierIdMethodArguments) {
            return source
        }

        val namespace = inferModAccess(source)?.modIdExpression
            ?: "\"${Regex("""(?m)^package\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*;""")
                .find(source)
                ?.groupValues
                ?.get(1)
                ?.substringBefore('.')
                ?: "modporter"}\""
        fun idExpression(path: String): String =
            "net.minecraft.resources.ResourceLocation.fromNamespaceAndPath($namespace, \"$path\")"

        val idAliases = mutableMapOf<String, String>()
        var result = source

        result = Regex("""\bUUID\s+([A-Z0-9_]*MODIFIER[A-Z0-9_]*)\s*=\s*UUID\.fromString\(\s*"[^"]+"\s*\)""")
            .replace(result) { match ->
                val name = match.groupValues[1]
                if (!isAttributeModifierIdUse(source, name, crossFileAttributeModifierIds, ownerName)) {
                    return@replace match.value
                }
                val id = idExpression(modifierConstantPathName(name))
                idAliases[name] = id
                "net.minecraft.resources.ResourceLocation $name = $id"
            }
        result = Regex("""\bUUID\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*_[A-Z0-9_]*MODIFIER[A-Z0-9_]*)\s*;""")
            .replace(result) { match ->
                val alias = match.groupValues[1]
                val target = match.groupValues[2]
                if (!isAttributeModifierIdUse(source, alias, crossFileAttributeModifierIds, ownerName) &&
                    !isAttributeModifierIdUse(source, target, crossFileAttributeModifierIds, ownerName)) {
                    return@replace match.value
                }
                "net.minecraft.resources.ResourceLocation $alias = $target;"
            }
        result = Regex(
            """new\s+AttributeModifier\(\s*"([^"]+)"\s*,\s*([^,]+)\s*,\s*AttributeModifier\.Operation\.([A-Z_]+)\s*\)"""
        ).replace(result) { match ->
            val id = idExpression(modifierPathName(match.groupValues[1]))
            "new AttributeModifier($id, ${match.groupValues[2].trim()}, AttributeModifier.Operation.${match.groupValues[3]})"
        }
        result = Regex(
            """new\s+AttributeModifier\(\s*([^,\r\n]+)\s*,\s*"([^"]+)"\s*,\s*([^,]+)\s*,\s*AttributeModifier\.Operation\.([A-Z_]+)\s*\)"""
        ).replace(result) { match ->
            val oldId = match.groupValues[1].trim()
            val id = idExpression(modifierPathName(match.groupValues[2]))
            idAliases[oldId] = id
            "new AttributeModifier($id, ${match.groupValues[3].trim()}, AttributeModifier.Operation.${match.groupValues[4]})"
        }
        result = Regex("""\.addAttributeModifier\(\s*([^,]+)\s*,\s*([^,\r\n]+)\.toString\(\)\s*,""")
            .replace(result) { match ->
                ".addAttributeModifier(${match.groupValues[1].trim()}, ${match.groupValues[2].trim()},"
            }
        result = Regex("""\.addAttributeModifier\(\s*([^,]+)\s*,\s*"([^"]+)"\s*,""")
            .replace(result) { match ->
                val id = idExpression(modifierPathName(match.groupValues[2]))
                ".addAttributeModifier(${match.groupValues[1].trim()}, $id,"
            }

        for ((oldId, newId) in idAliases) {
            val escaped = Regex.escape(oldId)
            result = Regex("""\.(getModifier|hasModifier|removeModifier)\(\s*$escaped\s*\)""")
                .replace(result) { match -> ".${match.groupValues[1]}($newId)" }
        }

        val modifierVariables = Regex("""\bAttributeModifier\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        val ownerAttributeModifierMethods = ownerName?.let { attributeModifierMethods[it] }.orEmpty() +
            declaredAttributeModifierMethodNames(result)
        fun methodsForType(typeName: String, typeParameterBounds: Map<String, Set<String>>): Set<String> {
            val simple = typeName.substringAfterLast('.')
            val methods = linkedSetOf<String>()
            methods += attributeModifierMethods[simple].orEmpty()
            typeParameterBounds[simple].orEmpty().forEach { bound ->
                methods += attributeModifierMethods[bound].orEmpty()
            }
            return methods
        }

        fun attributeModifierStreamLambdaParameters(scope: String): Set<String> {
            val id = """[A-Za-z_$][\w$]*"""
            val parameters = linkedSetOf<String>()
            val attributeModifierCollectionVariables = Regex(
                """\b(?:java\.util\.)?(?:Collection|Iterable|List|Set)\s*<\s*(?:net\.minecraft\.world\.entity\.ai\.attributes\.)?AttributeModifier\s*>\s+($id)\b"""
            ).findAll(scope).map { it.groupValues[1] }.toSet()
            Regex("""(?s)([^;{}]+?)\.stream\s*\(\s*\)\s*\.\w+\s*\(\s*\(?\s*($id)\s*\)?\s*->""")
                .findAll(scope)
                .forEach { match ->
                    val streamSource = match.groupValues[1].trim()
                    val root = streamSource.substringBefore('.').trim()
                    val isAttributeModifierSource =
                        root in attributeModifierCollectionVariables ||
                            streamSource.endsWith(".getModifiers()") ||
                            streamSource.contains(".getAttributeModifiers(")
                    if (isAttributeModifierSource) {
                        parameters += match.groupValues[2]
                    }
                }
            return parameters
        }

        fun attributeModifierIdExpression(argument: String, callOffset: Int): String? {
            val trimmed = argument.trim()
            if (trimmed.endsWith(".id()")) return null
            if (trimmed in modifierVariables) return "$trimmed.id()"
            if (Regex("""^new\s+(?:net\.minecraft\.world\.entity\.ai\.attributes\.)?AttributeModifier\s*\(""")
                    .containsMatchIn(trimmed)) {
                return "$trimmed.id()"
            }
            val scope = enclosingMethodText(result, callOffset) ?: result
            val variableTypes = javaLocalVariableTypes(scope, genericMethodReturnTypes)
            val typeParameterBounds = javaTypeParameterBounds(scope)
            val methodCall = Regex("""(?s)^(?:(.+)\.)?([A-Za-z_$][\w$]*)\s*\(.*\)$""").matchEntire(trimmed)
                ?: return null
            val receiver = methodCall.groupValues[1].trim()
            val methodName = methodCall.groupValues[2]
            if (receiver.isBlank()) {
                return if (methodName in ownerAttributeModifierMethods) "$trimmed.id()" else null
            }
            if (receiver == "this") {
                return if (methodName in ownerAttributeModifierMethods) "$trimmed.id()" else null
            }
            val receiverType = variableTypes[receiver]
            if (receiverType != null && methodName in methodsForType(receiverType, typeParameterBounds)) {
                return "$trimmed.id()"
            }
            if (methodName in attributeModifierMethods[receiver.substringAfterLast('.')].orEmpty()) {
                return "$trimmed.id()"
            }
            return null
        }

        fun isAttributeModifierExpression(expression: String, callOffset: Int): Boolean {
            val trimmed = expression.trim()
            if (trimmed in modifierVariables) return true
            if (Regex("""^new\s+(?:net\.minecraft\.world\.entity\.ai\.attributes\.)?AttributeModifier\s*\(""")
                    .containsMatchIn(trimmed)) {
                return true
            }
            val scope = enclosingMethodText(result, callOffset) ?: result
            val variableTypes = javaLocalVariableTypes(scope, genericMethodReturnTypes)
            val typeParameterBounds = javaTypeParameterBounds(scope)
            if (trimmed in attributeModifierStreamLambdaParameters(scope)) return true
            val directType = variableTypes[trimmed]
            if (directType == "AttributeModifier" || "AttributeModifier" in typeParameterBounds[directType].orEmpty()) {
                return true
            }
            val methodCall = Regex("""(?s)^(?:(.+)\.)?([A-Za-z_$][\w$]*)\s*\(.*\)$""").matchEntire(trimmed)
                ?: return false
            val receiver = methodCall.groupValues[1].trim()
            val methodName = methodCall.groupValues[2]
            if (receiver.isBlank()) {
                return methodName in ownerAttributeModifierMethods
            }
            if (receiver == "this") {
                return methodName in ownerAttributeModifierMethods
            }
            val receiverType = variableTypes[receiver]
            if (receiverType != null && methodName in methodsForType(receiverType, typeParameterBounds)) {
                return true
            }
            return methodName in attributeModifierMethods[receiver.substringAfterLast('.')].orEmpty()
        }

        for (variable in modifierVariables) {
            val escaped = Regex.escape(variable)
            result = Regex("""\.(getModifier|hasModifier|removeModifier)\(\s*$escaped\s*\)""")
                .replace(result) { match -> ".${match.groupValues[1]}($variable.id())" }
            result = Regex("""\b$escaped\.getId\(\)""").replace(result, "$variable.id()")
            result = Regex("""\b$escaped\.getAmount\(\)""").replace(result, "$variable.amount()")
            result = Regex("""\b$escaped\.getOperation\(\)""").replace(result, "$variable.operation()")
        }
        listOf(
            "getId" to "id",
            "getAmount" to "amount",
            "getOperation" to "operation"
        ).forEach { (legacyName, recordName) ->
            result = rewriteJavaCallWithOffset(result, legacyName) { receiver, args, callOffset ->
                if (args.isNotEmpty()) return@rewriteJavaCallWithOffset null
                if (!isAttributeModifierExpression(receiver, callOffset)) return@rewriteJavaCallWithOffset null
                "$receiver.$recordName()"
            }
        }
        listOf("getModifier", "hasModifier", "removeModifier").forEach { methodName ->
            result = rewriteJavaCallWithOffset(result, methodName) { receiver, args, callOffset ->
                if (args.size != 1) return@rewriteJavaCallWithOffset null
                val idExpression = attributeModifierIdExpression(args[0], callOffset) ?: return@rewriteJavaCallWithOffset null
                "$receiver.$methodName($idExpression)"
            }
        }
        result = migrateAttributeModifierIdMethodParameterTypes(result, attributeModifierIdMethodArguments)

        val withoutUuidImport = removeImport(result, "java.util.UUID")
        if (!Regex("""\bUUID\b""").containsMatchIn(withoutUuidImport)) {
            result = withoutUuidImport
        }
        return result
    }

    private fun migrateAttributeModifierIdMethodParameterTypes(
        source: String,
        attributeModifierIdMethodArguments: Set<AttributeModifierIdMethodArgument>
    ): String {
        val ownerName = javaTopLevelTypeName(source) ?: return source
        val ownerHints = attributeModifierIdMethodArguments
            .filter { it.owner == ownerName }
            .groupBy { it.methodName }
            .mapValues { entry -> entry.value.map { it.parameterIndex }.toSet() }
        if (ownerHints.isEmpty() || !source.contains("UUID")) return source

        val id = """[A-Za-z_$][\w$]*"""
        val migratedParameterNames = linkedSetOf<String>()
        var changed = false
        var result = Regex(
            """(?m)^([ \t]*(?:(?:public|protected|private|static|final|default|abstract|synchronized)\s+)+[\w<>\[\].?,\s]+\s+($id)\s*\()([^;{}\r\n]*)\)"""
        ).replace(source) { match ->
            val methodName = match.groupValues[2]
            val migratedIndexes = ownerHints[methodName] ?: return@replace match.value
            val params = splitTopLevelJavaArgs(match.groupValues[3])
            if (params.isEmpty()) return@replace match.value
            var methodChanged = false
            val migratedParams = params.mapIndexed { index, param ->
                if (index !in migratedIndexes) return@mapIndexed param
                val migrated = Regex(
                    """((?:@[A-Za-z_$][\w$.]*(?:\([^)]*\))?\s+)*)((?:java\.util\.)?UUID)(\s+($id)\b)"""
                ).replace(param) { paramMatch ->
                    methodChanged = true
                    migratedParameterNames += paramMatch.groupValues[4]
                    "${paramMatch.groupValues[1]}ResourceLocation${paramMatch.groupValues[3]}"
                }
                migrated
            }
            if (!methodChanged) {
                match.value
            } else {
                changed = true
                "${match.groupValues[1]}${migratedParams.joinToString(", ")})"
            }
        }
        if (!changed) return source

        val idMaps = linkedSetOf<String>()
        for (paramName in migratedParameterNames) {
            val escaped = Regex.escape(paramName)
            Regex("""\b($id)\s*\.\s*(?:put|get|containsKey|remove)\(\s*$escaped\b""")
                .findAll(result)
                .forEach { idMaps += it.groupValues[1] }
        }
        for (mapName in idMaps) {
            result = Regex(
                """\b((?:java\.util\.)?(?:Map|HashMap|LinkedHashMap|ConcurrentHashMap|ConcurrentMap)\s*<\s*)(?:java\.util\.)?UUID(\s*,[^;=\r\n>]*(?:>[^;=\r\n>]*)?\s+${Regex.escape(mapName)}\b)"""
            ).replace(result) { match ->
                "${match.groupValues[1]}ResourceLocation${match.groupValues[2]}"
            }
        }
        return addImportIfMissing(result, "net.minecraft.resources.ResourceLocation")
    }

    private fun declaredAttributeModifierMethodNames(source: String): Set<String> {
        val id = """[A-Za-z_$][\w$]*"""
        return Regex(
            """(?m)\b(?:(?:public|protected|private|static|final|default|abstract|synchronized)\s+)*(?:net\.minecraft\.world\.entity\.ai\.attributes\.)?AttributeModifier\s+($id)\s*\("""
        ).findAll(source).map { it.groupValues[1] }.toSet()
    }

    private fun javaLocalVariableTypes(
        source: String,
        genericMethodReturnTypes: Map<String, String> = emptyMap()
    ): Map<String, String> {
        val id = """[A-Za-z_$][\w$]*"""
        val types = linkedMapOf<String, String>()
        val typeExpression = """(?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*(?:\s*<[^;=(){}]*>)?(?:\s*\[\])?"""
        fun simpleTypeName(type: String): String =
            type.replace(Regex("""<[^<>]*>"""), "")
                .trim()
                .removeSuffix("[]")
                .substringAfterLast('.')

        Regex("""\b($typeExpression)\s+($id)\b(?=\s*(?:[,;)=]))""")
            .findAll(source)
            .forEach { match ->
                val type = simpleTypeName(match.groupValues[1])
                val name = match.groupValues[2]
                if (type !in setOf("void", "return", "new", "if", "for", "while", "switch")) {
                    types[name] = type
                }
            }
        Regex("""\binstanceof\s+($typeExpression)\s+($id)\b""")
            .findAll(source)
            .forEach { match ->
                types[match.groupValues[2]] = simpleTypeName(match.groupValues[1])
            }
        Regex("""\bfor\s*\(\s*($typeExpression)\s+($id)\s*:""")
            .findAll(source)
            .forEach { match ->
                types[match.groupValues[2]] = simpleTypeName(match.groupValues[1])
            }
        Regex("""\b((?:$id\.)*$id)\s*\.\s*($id)\s*\([^;{}]*?\)\s*\.\s*ifPresent\s*\(\s*($id)\s*->""")
            .findAll(source)
            .forEach { match ->
                val owner = match.groupValues[1].substringAfterLast('.')
                val method = match.groupValues[2]
                val lambdaParameter = match.groupValues[3]
                genericMethodReturnTypes["$owner.$method"]?.let { returnedType ->
                    types[lambdaParameter] = returnedType
                }
            }
        return types
    }

    private fun javaTypeParameterBounds(source: String): Map<String, Set<String>> {
        val id = """[A-Za-z_$][\w$]*"""
        val bounds = linkedMapOf<String, MutableSet<String>>()
        fun simpleTypeName(type: String): String =
            type.replace(Regex("""<[^<>]*>"""), "")
                .trim()
                .substringAfterLast('.')

        Regex("""<([^<>]*\bextends\b[^<>]*)>""")
            .findAll(source)
            .forEach { typeParameters ->
                typeParameters.groupValues[1].split(',').forEach { parameter ->
                    val match = Regex("""^\s*($id)\s+extends\s+(.+?)\s*$""").find(parameter) ?: return@forEach
                    match.groupValues[2].split('&')
                        .map { simpleTypeName(it) }
                        .filter { it.isNotBlank() }
                        .forEach { bound ->
                            bounds.getOrPut(match.groupValues[1]) { linkedSetOf() } += bound
                        }
                }
            }
        return bounds
    }

    private fun isAttributeModifierIdUse(
        source: String,
        idName: String,
        crossFileAttributeModifierIds: Set<String> = emptySet(),
        ownerName: String? = null
    ): Boolean {
        if (ownerName != null && "$ownerName.$idName" in crossFileAttributeModifierIds) return true
        fun directUse(name: String): Boolean {
            val escaped = Regex.escape(name)
            return Regex("""new\s+AttributeModifier\s*\(\s*$escaped\b""").containsMatchIn(source) ||
                Regex("""\.(?:getModifier|hasModifier|removeModifier)\(\s*$escaped\s*\)""").containsMatchIn(source) ||
                Regex("""\.addAttributeModifier\([^;\n]*\b$escaped\b""").containsMatchIn(source)
        }
        if (directUse(idName)) return true
        val escaped = Regex.escape(idName)
        return Regex("""\bUUID\s+([A-Za-z_$][\w$]*)\s*=\s*$escaped\s*;""")
            .findAll(source)
            .map { it.groupValues[1] }
            .any { directUse(it) }
    }

    private fun modifierConstantPathName(name: String): String {
        val normalized = name.removeSuffix("_UUID").removeSuffix("_ID")
        val parts = normalized.split('_').filter { it.isNotBlank() }
        val modifierIndex = parts.indexOfLast { it == "MODIFIER" }
        if (modifierIndex > 0) {
            val semantic = parts.getOrNull(modifierIndex - 1)
            if (semantic != null && semantic !in setOf("ATTRIBUTE", "ENTITY", "ITEM")) {
                return modifierPathName("${semantic}_MODIFIER")
            }
        }
        return modifierPathName(normalized.removeSuffix("_MODIFIER"))
    }

    private fun migrateEntityRidingOffsetExpressions(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        var result = source
        result = Regex(
            """new\s+Vec3\s*\(\s*([A-Za-z_$][\w$]*)\.getX\(\)\s*,\s*\1\.getY\(\)\s*-\s*\1\.getMyRidingOffset\(\)\s*\+\s*\1\.getBbHeight\(\)\s*/\s*2\s*,\s*\1\.getZ\(\)\s*\)"""
        ).replace(result) { match -> "${match.groupValues[1]}.getBoundingBox().getCenter()" }
        result = Regex(
            """\b([A-Za-z_$][\w$]*)\.getY\(\)\s*-\s*\1\.getMyRidingOffset\(\)\s*\+\s*\1\.getBbHeight\(\)\s*/\s*2"""
        ).replace(result) { match -> "${match.groupValues[1]}.getBoundingBox().getCenter().y" }
        if (result.contains(".getMyRidingOffset()") && sourceDeclaresEntityDerivedType(result, javaInheritanceIndex)) {
            result = rewriteJavaCallWithOffset(result, "getMyRidingOffset") { receiver, args, callOffset ->
                if (args.isNotEmpty()) return@rewriteJavaCallWithOffset null
                val normalizedReceiver = receiver.trim()
                if (normalizedReceiver == "this" || normalizedReceiver == "super") return@rewriteJavaCallWithOffset null
                val methodText = enclosingMethodText(result, callOffset) ?: return@rewriteJavaCallWithOffset null
                val methodHeader = methodText.substringBefore("{")
                if (Regex("""\bstatic\b""").containsMatchIn(methodHeader)) return@rewriteJavaCallWithOffset null
                "(-$normalizedReceiver.getVehicleAttachmentPoint(this).y)"
            }
            result = Regex("""\+\s*\(-([^;\r\n]+?\.getVehicleAttachmentPoint\(this\)\.y)\)""")
                .replace(result, "- $1")
            result = Regex("""-\s*\(-([^;\r\n]+?\.getVehicleAttachmentPoint\(this\)\.y)\)""")
                .replace(result, "+ $1")
        }
        return result
    }

    private fun sourceDeclaresEntityDerivedType(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): Boolean {
        val entityBaseTypes = javaEntityBaseTypes()
        return Regex(
            """\bclass\s+([A-Za-z_$][\w$]*)(?:\s*<[^>{}]+>)?\s+extends\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\b"""
        ).findAll(source).any { match ->
            javaInheritanceIndex.inherits(match.groupValues[2], entityBaseTypes)
        }
    }

    private fun migrateLegacyPassengerAttachmentOverrides(source: String): String {
        if (!source.contains("getPassengersRidingOffset()") || source.contains("getPassengerAttachmentPoint(")) {
            return source
        }
        val offsetMethod = javaMethodText(source, "getPassengersRidingOffset") ?: return source
        val returnExpr = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL)
            .find(offsetMethod)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: return source
        val yExpression = returnExpr.replace("super.getPassengersRidingOffset()", "dimensions.height()")
        val distanceExpression = Regex("""float\s+distance\s*=\s*([0-9]+(?:\.[0-9]+)?[Ff]?)\s*;""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { if (it.endsWith("F", ignoreCase = true)) it.uppercase() else "${it}F" }
            ?: "0.0F"
        val replacement = """
protected Vec3 getPassengerAttachmentPoint(Entity entity, EntityDimensions dimensions, float yRot) {
		return new Vec3(0.0F, $yExpression, $distanceExpression);
	}
        """.trimIndent()
        var result = source.replace(offsetMethod, replacement)
        result = removeMethodByName(result, "positionRider")
        result = removeMethodByName(result, "getRiderPosition")
        result = addImportIfMissing(result, "net.minecraft.world.entity.EntityDimensions")
        result = addImportIfMissing(result, "net.minecraft.world.phys.Vec3")
        return result
    }

    private fun migrateLegacyEntityOverrideSignatures(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        var result = source
        var needsLevel = false
        var needsEntity = false
        var needsVec3 = false

        result = migrateLegacyEyeHeightOverrides(result, javaInheritanceIndex)
        result = removeLegacyEntityRemoveCapabilityInvalidation(result, javaInheritanceIndex)

        if (result.contains("canChangeDimensions()")) {
            result = Regex("""\b(public|protected)\s+boolean\s+canChangeDimensions\s*\(\s*\)""")
                .replace(result) { match ->
                    needsLevel = true
                    "${match.groupValues[1]} boolean canChangeDimensions(Level from, Level to)"
                }
        }

        if (result.contains("canBeLeashed(")) {
            result = Regex("""\b(public|protected)\s+boolean\s+canBeLeashed\s*\(\s*Player\s+[A-Za-z_$][\w$]*\s*\)""")
                .replace(result) { match -> "${match.groupValues[1]} boolean canBeLeashed()" }
        }

        if (result.contains("getMyRidingOffset()") && !result.contains("getVehicleAttachmentPoint(")) {
            val offsetMethod = javaMethodText(result, "getMyRidingOffset")
            if (offsetMethod != null) {
                val returnExpr = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL)
                    .find(offsetMethod)
                    ?.groupValues
                    ?.get(1)
                    ?.trim()
                if (returnExpr != null) {
                    val replacement = """
public Vec3 getVehicleAttachmentPoint(Entity vehicle) {
		return new Vec3(0.0D, $returnExpr, 0.0D);
	}
                    """.trimIndent()
                    result = result.replace(offsetMethod, replacement)
                    needsEntity = true
                    needsVec3 = true
                }
            }
        }

        if (result.contains("invalidateCaps()")) {
            result = result.replace(".invalidateCaps()", ".invalidateCapabilities()")
        }

        if (result.contains("lerpTo(")) {
            result = Regex(
                """public\s+void\s+lerpTo\(\s*double\s+([A-Za-z_$][\w$]*)\s*,\s*double\s+([A-Za-z_$][\w$]*)\s*,\s*double\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*float\s+([A-Za-z_$][\w$]*)\s*,\s*int\s+([A-Za-z_$][\w$]*)\s*,\s*boolean\s+[A-Za-z_$][\w$]*\s*\)"""
            ).replace(result) { match ->
                "public void lerpTo(double ${match.groupValues[1]}, double ${match.groupValues[2]}, double ${match.groupValues[3]}, float ${match.groupValues[4]}, float ${match.groupValues[5]}, int ${match.groupValues[6]})"
            }
        }

        result = Regex(
            """(?s)\s*@Override\s*\r?\n\s*protected\s+void\s+enchantSpawned(?:Weapon|Armor)\s*\([^)]*\)\s*\{\s*\}\s*"""
        ).replace(result, "\n")

        if (needsLevel) result = addImportIfMissing(result, "net.minecraft.world.level.Level")
        if (needsEntity) result = addImportIfMissing(result, "net.minecraft.world.entity.Entity")
        if (needsVec3) result = addImportIfMissing(result, "net.minecraft.world.phys.Vec3")
        return result
    }

    private fun removeLegacyEntityRemoveCapabilityInvalidation(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        if (!source.contains("remove(") ||
            (!source.contains("invalidateCaps()") && !source.contains("invalidateCapabilities()"))) {
            return source
        }

        var result = source
        var cursor = 0
        val removePattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\r?\n[ \t]*)*(?:public|protected)\s+void\s+remove\s*\(\s*(?:Entity\.)?RemovalReason\s+[A-Za-z_$][\w$]*\s*\)\s*\{"""
        )
        while (true) {
            val match = removePattern.find(result, cursor) ?: break
            val classDeclaration = enclosingJavaClassDeclaration(result, match.range.first)
            if (!javaClassExtendsAny(classDeclaration, javaEntityBaseTypes(), javaInheritanceIndex)) {
                cursor = match.range.last + 1
                continue
            }
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val rewrittenBody = Regex(
                """(?m)^[ \t]*(?:this|super)\.invalidate(?:Caps|Capabilities)\(\);\s*\r?\n?"""
            ).replace(body, "")
            if (rewrittenBody == body) {
                cursor = closeBrace + 1
                continue
            }
            result = result.substring(0, openBrace + 1) + rewrittenBody + result.substring(closeBrace)
            cursor = openBrace + 1 + rewrittenBody.length
        }
        return result
    }

    private fun migrateLegacyParticleCullingOverrides(source: String): String {
        if (!source.contains("shouldCull()")) return source
        return Regex("""(?m)^([ \t]*)@Override\s*\r?\n([ \t]*public\s+boolean\s+shouldCull\s*\(\s*\))""")
            .replace(source, "$1$2")
    }

    private fun migrateLegacyItemStackRegistrySerialization(source: String): String {
        if (!source.contains("ItemStack.parseOptional(") && !source.contains("ItemStack.of(") && !source.contains(".save()")) return source
        var result = source
        val fallbackRegistryAccess = if (result.contains("readAdditionalSaveData(") || result.contains("addAdditionalSaveData(")) {
            "this.registryAccess()"
        } else {
            inferRegistryAccessExpression(result) ?: return result
        }
        fun registryAccessAt(offset: Int): String {
            return holderLookupProviderFromParameters(currentMethodParametersBeforeOffset(result, offset))
                ?: fallbackRegistryAccess
        }
        val itemStackNames = Regex("""\bItemStack\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        result = Regex("""ItemStack\.parseOptional\(\s*player\.registryAccess\(\)\s*,""")
            .replace(result) { match -> "ItemStack.parseOptional(${registryAccessAt(match.range.first)}," }
        var itemStackOfCursor = 0
        while (true) {
            val tokenIndex = result.indexOf("ItemStack.of(", itemStackOfCursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + "ItemStack.of".length
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                itemStackOfCursor = tokenIndex + "ItemStack.of(".length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size != 1) {
                itemStackOfCursor = closeParen + 1
                continue
            }
            val replacement = "ItemStack.parseOptional(${registryAccessAt(tokenIndex)}, ${args[0].trim()})"
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            itemStackOfCursor = tokenIndex + replacement.length
        }
        result = Regex("""\b([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*(?:\(\))?)*)\.save\(\s*\)""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                val lastName = receiver.substringAfterLast('.').removeSuffix("()")
                if (lastName !in itemStackNames) {
                    match.value
                } else {
                    "$receiver.save(${registryAccessAt(match.range.first)})"
                }
            }
        return result
    }

    private fun migrateLegacyBlockEntityLoadCalls(source: String): String {
        if (!source.contains(".load(") || !source.contains("BlockEntity")) return source
        val registryAccess = inferRegistryAccessExpression(source) ?: return source
        val variables = Regex("""\b(?:BlockEntity|[A-Za-z_$][\w$]*BlockEntity)\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (variables.isEmpty()) return source
        var result = source
        variables.forEach { variable ->
            result = Regex("""\b${Regex.escape(variable)}\.load\(\s*([A-Za-z_$][\w$]*)\s*\)""")
                .replace(result, "$variable.loadWithComponents($1, $registryAccess)")
        }
        return result
    }

    private fun migrateCommandSourceStackLevelAccess(source: String): String {
        if (!source.contains("CommandSourceStack") || !source.contains(".level()")) return source
        var result = source
        val variables = Regex("""\bCommandSourceStack\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        variables.forEach { variable ->
            result = Regex("""\b${Regex.escape(variable)}\.level\(\)""")
                .replace(result, "$variable.getLevel()")
        }
        return result
    }

    private fun migrateLegacyStaticFmlModEventBusAccess(source: String): String {
        if (!source.contains("FMLJavaModLoadingContext.get().getModEventBus()")) return source
        val modId = Regex("""@EventBusSubscriber\s*\([^)]*\bmodid\s*=\s*([^,\)]+)""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: Regex("""@Mod\s*\(\s*([^)]+?)\s*\)""")
                .find(source)
                ?.groupValues
                ?.get(1)
                ?.trim()
            ?: return source
        var result = source.replace(
            "FMLJavaModLoadingContext.get().getModEventBus()",
            "net.neoforged.fml.ModList.get().getModContainerById($modId).orElseThrow().getEventBus()"
        )
        result = removeImport(result, "net.neoforged.fml.javafmlmod.FMLJavaModLoadingContext")
        return result
    }

    private fun migrateLegacyEntityStepHeightOverrides(source: String): String {
        if (!source.contains("getStepHeight(")) return source
        return Regex("""\b(public|protected)\s+float\s+getStepHeight\s*\(\s*\)""")
            .replace(source) { match -> "${match.groupValues[1]} float maxUpStep()" }
    }

    private fun migrateLegacyEntityTypeAabbCalls(source: String): String {
        if (!source.contains(".getAABB(")) return source
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        val token = ".getAABB("
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + ".getAABB".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val receiverStart = findExpressionReceiverStart(source, tokenIndex)
            val receiver = source.substring(receiverStart, tokenIndex).trim()
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (receiver.isNotEmpty() && args.size == 3) {
                migrated.append(source, cursor, receiverStart)
                migrated.append("${receiver}.getDimensions().makeBoundingBox(${args[0].trim()}, ${args[1].trim()}, ${args[2].trim()})")
                cursor = closeParen + 1
                changed = true
                continue
            }
            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun findExpressionReceiverStart(source: String, tokenIndex: Int): Int {
        var index = tokenIndex - 1
        var parenDepth = 0
        var bracketDepth = 0
        scan@ while (index >= 0) {
            val c = source[index]
            when (c) {
                ')' -> parenDepth++
                '(' -> {
                    if (parenDepth == 0) break@scan
                    parenDepth--
                }
                ']' -> bracketDepth++
                '[' -> {
                    if (bracketDepth == 0) break@scan
                    bracketDepth--
                }
                else -> {
                    if (parenDepth == 0 && bracketDepth == 0 &&
                        !(c.isLetterOrDigit() || c == '_' || c == '$' || c == '.')) {
                        break@scan
                    }
                }
            }
            index--
        }
        return index + 1
    }

    private fun migrateLegacyBlockValidSpawnOverrides(source: String): String {
        if (!source.contains("isValidSpawn(") || !source.contains("EntityType<?>")) return source
        val methodText = javaMethodText(source, "isValidSpawn") ?: return source
        val signature = Regex(
            """(?s)(?:[ \t]*@\w+(?:\([^)]*\))?\s*\r?\n)*[ \t]*(?:public|protected)\s+boolean\s+isValidSpawn\s*\(\s*BlockState\s+([A-Za-z_$][\w$]*)\s*,\s*BlockGetter\s+([A-Za-z_$][\w$]*)\s*,\s*BlockPos\s+([A-Za-z_$][\w$]*)\s*,\s*EntityType<\?>\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).find(methodText) ?: return source
        val returnExpr = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL)
            .find(methodText)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: return source
        var result = removeMethodByName(source, "isValidSpawn")
        val constructorPattern = Regex("""\bsuper\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;""")
        val constructorSuper = constructorPattern.find(result) ?: return source
        val replacement = constructorSuper.let { match ->
            val properties = match.groupValues[1]
            val stateName = signature.groupValues[1]
            val getterName = signature.groupValues[2]
            val posName = signature.groupValues[3]
            val entityTypeName = signature.groupValues[4]
            "super($properties.isValidSpawn(($stateName, $getterName, $posName, $entityTypeName) -> $returnExpr));"
        }
        result = result.substring(0, constructorSuper.range.first) + replacement + result.substring(constructorSuper.range.last + 1)
        if (!Regex("""\bisValidSpawn\s*\(""").containsMatchIn(result)) {
            val withoutEntityType = removeImport(result, "net.minecraft.world.entity.EntityType")
            result = if (!Regex("""\bEntityType\b""").containsMatchIn(withoutEntityType)) withoutEntityType else result
            val withoutSpawnPlacements = removeImport(result, "net.minecraft.world.entity.SpawnPlacements")
            result = if (!Regex("""\bSpawnPlacements\b""").containsMatchIn(withoutSpawnPlacements)) withoutSpawnPlacements else result
        }
        return result
    }

    private fun migrateLegacyBlockAndEntityCapabilityAccessors(source: String): String {
        if (!source.contains("getCapability(Capabilities.ItemHandler.")) return source

        var result = source
        val blockEntityAccesses = collectBlockEntityAccesses(result)
        val blockEntityVariables = collectBlockEntityVariables(result)
        var needsServerLevel = false
        var needsItemHandler = false
        var handlerCounter = 0

        val blockIfPresentPattern = Regex(
            """(?m)^([ \t]*)([A-Za-z_$][\w$]*)\.getCapability\(\s*Capabilities\.ItemHandler\.BLOCK\s*,\s*([A-Za-z_$][\w$]*)\s*\)\.ifPresent\(([^;\r\n]+)\);\s*$"""
        )
        result = blockIfPresentPattern.replace(result) { match ->
            val receiver = match.groupValues[2]
            val access = blockEntityAccesses[receiver] ?: return@replace match.value
            val side = match.groupValues[3]
            val consumer = match.groupValues[4].trim()
            val indent = match.groupValues[1]
            val handlerVar = "modporterItemHandler${handlerCounter++}"
            needsServerLevel = needsServerLevel || !access.levelIsServerLevel
            needsItemHandler = true
            val statement = consumerToItemHandlerStatement(consumer, handlerVar)
                ?: "$consumer.accept($handlerVar);"
            if (access.levelIsServerLevel) {
                """${indent}IItemHandler $handlerVar = net.neoforged.neoforge.capabilities.BlockCapabilityCache.create(Capabilities.ItemHandler.BLOCK, ${access.levelExpression}, ${access.positionExpression}, $side).getCapability();
${indent}if ($handlerVar != null) $statement"""
            } else {
                """${indent}if (${access.levelExpression} instanceof ServerLevel modporterServerLevel) {
${indent}    IItemHandler $handlerVar = net.neoforged.neoforge.capabilities.BlockCapabilityCache.create(Capabilities.ItemHandler.BLOCK, modporterServerLevel, ${access.positionExpression}, $side).getCapability();
${indent}    if ($handlerVar != null) $statement
${indent}}"""
            }
        }

        val entityIfPresentPattern = Regex(
            """(?m)^([ \t]*)([A-Za-z_$][\w$]*)\.getCapability\(\s*Capabilities\.ItemHandler\.BLOCK\s*,\s*([A-Za-z_$][\w$]*)\s*\)\.ifPresent\(([^;\r\n]+)\);\s*$"""
        )
        result = entityIfPresentPattern.replace(result) { match ->
            val receiver = match.groupValues[2]
            if (receiver in blockEntityVariables) return@replace match.value
            val side = match.groupValues[3]
            val consumer = match.groupValues[4].trim()
            val indent = match.groupValues[1]
            val handlerVar = "modporterItemHandler${handlerCounter++}"
            needsItemHandler = true
            val statement = consumerToItemHandlerStatement(consumer, handlerVar)
                ?: "$consumer.accept($handlerVar);"
            """${indent}IItemHandler $handlerVar = $receiver.getCapability(Capabilities.ItemHandler.ENTITY_AUTOMATION, $side);
${indent}if ($handlerVar != null) $statement"""
        }

        result = Regex("""Capabilities\.ItemHandler\.BLOCK\)""")
            .replace(result, "Capabilities.ItemHandler.ENTITY)")

        if (needsServerLevel) result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        if (needsItemHandler) result = addImportIfMissing(result, "net.neoforged.neoforge.items.IItemHandler")
        return result
    }

    private data class BlockEntityAccess(
        val levelExpression: String,
        val positionExpression: String,
        val levelIsServerLevel: Boolean
    )

    private fun collectBlockEntityAccesses(source: String): Map<String, BlockEntityAccess> {
        val accesses = mutableMapOf<String, BlockEntityAccess>()
        val serverLevelVariables = Regex("""\b(?:net\.minecraft\.server\.level\.)?ServerLevel\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        val id = """[A-Za-z_$][\w$]*"""
        val accessExpression = """(?:this|$id)(?:\.$id(?:\(\))?)*"""
        Regex(
            """\b(?:net\.minecraft\.world\.level\.block\.entity\.)?BlockEntity\s+($id)\s*=\s*($accessExpression)\.getBlockEntity\(\s*($accessExpression)\s*\)\s*;"""
        ).findAll(source).forEach { match ->
            val levelExpression = match.groupValues[2]
            accesses[match.groupValues[1]] = BlockEntityAccess(
                levelExpression = levelExpression,
                positionExpression = match.groupValues[3],
                levelIsServerLevel = levelExpression in serverLevelVariables
            )
        }
        return accesses
    }

    private fun collectBlockEntityVariables(source: String): Set<String> =
        Regex("""\b(?:net\.minecraft\.world\.level\.block\.entity\.)?BlockEntity\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()

    private fun consumerToItemHandlerStatement(consumer: String, handlerVar: String): String? {
        Regex("""^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)::([A-Za-z_$][\w$]*)$""")
            .find(consumer)
            ?.let { return "${it.groupValues[1]}.${it.groupValues[2]}($handlerVar);" }
        Regex("""^([A-Za-z_$][\w$]*)\s*->\s*(.+)$""")
            .find(consumer)
            ?.let { match ->
                val parameter = match.groupValues[1]
                val body = match.groupValues[2].trim()
                return Regex("""\b${Regex.escape(parameter)}\b""").replace(body, handlerVar).let {
                    if (it.endsWith(";")) it else "$it;"
                }
        }
        return null
    }

    private fun migrateLegacyITeleporterDimensionTransitions(source: String): String {
        if (!source.contains("ITeleporter") && !source.contains("PortalInfo") && !source.contains(".changeDimension(")) {
            return source
        }

        var result = source
        val getPortalInfoMethod = javaMethodText(source, "getPortalInfo")
        val defaultSuperCall = getPortalInfoMethod?.let {
            Regex("""ITeleporter\.super\.getPortalInfo\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)""")
                .find(it)
        }
        val defaultPortalInfoPosition = if (defaultSuperCall != null) {
            getPortalInfoMethod
                ?.let(::inferLegacyTeleporterDefaultPortalPosition)
                ?: return source
        } else {
            null
        }
        val legacySignature = legacyGetPortalInfoSignature(result)
        if (result.contains("implements ITeleporter")) {
            result = result.replace(" implements ITeleporter", "")
            result = removeImport(result, "net.neoforged.neoforge.common.util.ITeleporter")
            result = removeImport(result, "net.minecraftforge.common.util.ITeleporter")
        }
        val beforeNullChangeDimensionOverride = result
        result = Regex(
            """(?m)^([ \t]*)(@Nullable\s*\r?\n)?\1@Override\s*\r?\n\1public\s+Entity\s+changeDimension\(\s*ServerLevel\s+[A-Za-z_$][\w$]*\s*,\s*ITeleporter\s+[A-Za-z_$][\w$]*\s*\)\s*\{\s*\r?\n\1[ \t]*return\s+null\s*;\s*\r?\n\1}"""
        ).replace(result) { match ->
            val indent = match.groupValues[1]
            val nullable = match.groupValues[2]
            "${indent}${nullable}${indent}@Override\n${indent}public Entity changeDimension(DimensionTransition transition) {\n${indent}    return null;\n${indent}}"
        }
        if (result != beforeNullChangeDimensionOverride) {
            result = removeImport(result, "net.neoforged.neoforge.common.util.ITeleporter")
            result = removeImport(result, "net.minecraftforge.common.util.ITeleporter")
            result = addImportIfMissing(result, "net.minecraft.world.level.portal.DimensionTransition")
        }
        if (result.contains("PortalInfo")) {
            result = result.replace("import net.minecraft.world.level.portal.PortalInfo;", "import net.minecraft.world.level.portal.DimensionTransition;")
            if (!result.contains("import net.minecraft.world.level.portal.DimensionTransition;")) {
                result = addImportIfMissing(result, "net.minecraft.world.level.portal.DimensionTransition")
            }
            result = Regex("""\(\s*Entity\s+([A-Za-z_$][\w$]*)\s*,\s*ServerLevel\s+([A-Za-z_$][\w$]*)\s*,\s*(?:java\.util\.function\.)?Function\s*<\s*ServerLevel\s*,\s*PortalInfo\s*>\s*[A-Za-z_$][\w$]*\s*\)""")
                .replace(result) { match -> "(Entity ${match.groupValues[1]}, ServerLevel ${match.groupValues[2]})" }
            result = Regex("""(?m)^([ \t]*)@Override\s*\r?\n\1public\s+PortalInfo\s+getPortalInfo\(\s*Entity\s+([A-Za-z_$][\w$]*)\s*,\s*ServerLevel\s+([A-Za-z_$][\w$]*)\s*\)""")
                .replace(result) { match -> "${match.groupValues[1]}public DimensionTransition getPortalInfo(Entity ${match.groupValues[2]}, ServerLevel ${match.groupValues[3]})" }
            result = Regex("""(?m)^([ \t]*)public\s+PortalInfo\s+getPortalInfo\(\s*Entity\s+([A-Za-z_$][\w$]*)\s*,\s*ServerLevel\s+([A-Za-z_$][\w$]*)\s*\)""")
                .replace(result) { match -> "${match.groupValues[1]}public DimensionTransition getPortalInfo(Entity ${match.groupValues[2]}, ServerLevel ${match.groupValues[3]})" }
            result = Regex("""(?m)^([ \t]*)@Override\s*\r?\n\1public\s+boolean\s+playTeleportSound\(""")
                .replace(result) { match -> "${match.groupValues[1]}public boolean playTeleportSound(" }
            result = result.replace("PortalInfo pos;", "DimensionTransition pos;")
            result = Regex("""\bPortalInfo\s+([A-Za-z_$][\w$]*)\s*=""")
                .replace(result) { match -> "DimensionTransition ${match.groupValues[1]} =" }
            result = Regex("""\bprivate\s+static\s+PortalInfo\s+""").replace(result, "private static DimensionTransition ")
            result = Regex("""\bprotected\s+static\s+PortalInfo\s+""").replace(result, "protected static DimensionTransition ")
            result = Regex("""\bpublic\s+static\s+PortalInfo\s+""").replace(result, "public static DimensionTransition ")
            result = result.replace("pos.pos)", "pos.pos())")
            result = result.replace("pos.pos;", "pos.pos();")
            result = result.replace("BlockPos.containing(pos.pos)", "BlockPos.containing(pos.pos())")
            if (defaultPortalInfoPosition != null) {
                val entityParam = defaultSuperCall?.groupValues?.get(1) ?: legacySignature?.entityParam ?: "entity"
                val levelParam = defaultSuperCall?.groupValues?.get(2) ?: legacySignature?.levelParam ?: "dest"
                result = result.replace(
                    defaultSuperCall!!.value,
                    "makePortalInfo($levelParam, $entityParam, Vec3.atCenterOf($defaultPortalInfoPosition))"
                )
            }
            result = result.replace("return makePortalInfo(entity, portalX, portalY, portalZ);", "return makePortalInfo(destDim, entity, portalX, portalY, portalZ);")
            result = result.replace("return makePortalInfo(entity, Vec3.atCenterOf(pos));", "return makePortalInfo(world, entity, Vec3.atCenterOf(pos));")
            result = result.replace("return makePortalInfo(entity, safeCoords.getX(), entity.getY(), safeCoords.getZ());", "return makePortalInfo(world, entity, safeCoords.getX(), entity.getY(), safeCoords.getZ());")
            result = result.replace("return makePortalInfo(entity, new Vec3(x, y, z));", "return makePortalInfo(level, entity, new Vec3(x, y, z));")
            result = Regex("""private\s+static\s+DimensionTransition\s+makePortalInfo\(\s*Entity\s+entity\s*,\s*double\s+x\s*,\s*double\s+y\s*,\s*double\s+z\s*\)""")
                .replace(result, "private static DimensionTransition makePortalInfo(ServerLevel level, Entity entity, double x, double y, double z)")
            result = Regex("""private\s+static\s+DimensionTransition\s+makePortalInfo\(\s*Entity\s+entity\s*,\s*Vec3\s+pos\s*\)""")
                .replace(result, "private static DimensionTransition makePortalInfo(ServerLevel level, Entity entity, Vec3 pos)")
            result = Regex("""new\s+PortalInfo\(\s*pos\s*,\s*Vec3\.ZERO\s*,\s*entity\.getYRot\(\)\s*,\s*entity\.getXRot\(\)\s*\)""")
                .replace(result, "new DimensionTransition(level, pos, Vec3.ZERO, entity.getYRot(), entity.getXRot(), DimensionTransition.PLACE_PORTAL_TICKET)")
            legacySignature?.let {
                result = migratePortalInfoConstructorsInMethod(result, "getPortalInfo", it.levelParam)
                result = migratePortalShapeCreatePortalInfoInMethod(result, "getPortalInfo")
            }
            result = migratePortalInfoConstructorsInMethod(result, "makePortalInfo", "level")
            result = removeMethodByName(result, "placeEntity")
            result = removeImport(result, "java.util.function.Function")
            javaMethodText(result, "getPortalInfo")?.let { method ->
                val targetLevelParam = legacySignature?.levelParam ?: "dest"
                val migratedMethod = method.replace("makePortalInfo(entity,", "makePortalInfo($targetLevelParam, entity,")
                result = result.replace(method, migratedMethod)
            }
        }

        result = Regex(
            """([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.changeDimension\(\s*([A-Za-z_$][\w$]*)\s*,\s*new\s+([A-Za-z_$][\w$]*)\(([^)]*)\)\s*\)"""
        ).replace(result) { match ->
            val entity = match.groupValues[1]
            val dest = match.groupValues[2]
            val teleporterClass = match.groupValues[3]
            val args = match.groupValues[4].trim()
            "$entity.changeDimension(new $teleporterClass($args).getPortalInfo($entity, $dest))"
        }
        result = Regex(
            """([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.changeDimension\(\s*([A-Za-z_$][\w$]*)\s*,\s*([^?;\r\n]+?)\?\s*new\s+([A-Za-z_$][\w$]*)\(([^)]*)\)\s*:\s*new\s+([A-Za-z_$][\w$]*)\(([^)]*)\)\s*\)"""
        ).replace(result) { match ->
            val entity = match.groupValues[1]
            val dest = match.groupValues[2]
            val condition = match.groupValues[3].trim()
            val trueClass = match.groupValues[4]
            val trueArgs = match.groupValues[5].trim()
            val falseClass = match.groupValues[6]
            val falseArgs = match.groupValues[7].trim()
            "$entity.changeDimension($condition ? new $trueClass($trueArgs).getPortalInfo($entity, $dest) : new $falseClass($falseArgs).getPortalInfo($entity, $dest))"
        }
        return result
    }

    private data class LegacyPortalInfoSignature(
        val entityParam: String,
        val levelParam: String,
        val defaultPortalInfoParam: String
    )

    private fun legacyGetPortalInfoSignature(source: String): LegacyPortalInfoSignature? =
        Regex("""public\s+PortalInfo\s+getPortalInfo\(\s*Entity\s+([A-Za-z_$][\w$]*)\s*,\s*ServerLevel\s+([A-Za-z_$][\w$]*)\s*,\s*(?:java\.util\.function\.)?Function\s*<\s*ServerLevel\s*,\s*PortalInfo\s*>\s*([A-Za-z_$][\w$]*)\s*\)""")
            .find(source)
            ?.let { match ->
                LegacyPortalInfoSignature(
                    entityParam = match.groupValues[1],
                    levelParam = match.groupValues[2],
                    defaultPortalInfoParam = match.groupValues[3]
                )
            }

    private fun migratePortalInfoConstructorsInMethod(source: String, methodName: String, levelExpression: String): String {
        val method = javaMethodText(source, methodName) ?: return source
        val migrated = migratePortalInfoConstructors(method, levelExpression)
        return if (migrated == method) source else source.replace(method, migrated)
    }

    private fun migratePortalInfoConstructors(source: String, levelExpression: String): String {
        val result = StringBuilder()
        var cursor = 0
        while (cursor < source.length) {
            val constructorIndex = source.indexOf("new PortalInfo", cursor)
            if (constructorIndex < 0) break
            val openParen = source.indexOf('(', constructorIndex)
            if (openParen < 0) break
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen)).map { it.trim() }
            if (args.size != 4) {
                cursor = closeParen + 1
                continue
            }
            result.append(source, cursor, constructorIndex)
            result.append("new DimensionTransition(")
            result.append(levelExpression)
            result.append(", ")
            result.append(args[0])
            result.append(", ")
            result.append(args[1])
            result.append(", ")
            result.append(args[2])
            result.append(", ")
            result.append(args[3])
            result.append(", DimensionTransition.PLACE_PORTAL_TICKET)")
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        result.append(source, cursor, source.length)
        return result.toString()
    }

    private fun migratePortalShapeCreatePortalInfoInMethod(source: String, methodName: String): String {
        val method = javaMethodText(source, methodName) ?: return source
        val migrated = migratePortalShapeCreatePortalInfo(method)
        return if (migrated == method) source else source.replace(method, migrated)
    }

    private fun migratePortalShapeCreatePortalInfo(source: String): String {
        val result = StringBuilder()
        var cursor = 0
        while (cursor < source.length) {
            val callIndex = source.indexOf("PortalShape.createPortalInfo", cursor)
            if (callIndex < 0) break
            val openParen = source.indexOf('(', callIndex)
            if (openParen < 0) break
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen)).map { it.trim() }
            if (args.size != 8) {
                cursor = closeParen + 1
                continue
            }
            val level = args[0]
            val rectangle = args[1]
            val axis = args[2]
            val relativePosition = args[3]
            val entity = args[4]
            val speed = args[5]
            val yRot = args[6]
            val xRot = args[7]
            val dimensions = "$entity.getDimensions($entity.getPose())"
            result.append(source, cursor, callIndex)
            result.append("new DimensionTransition(")
            result.append(level)
            result.append(", PortalShape.findCollisionFreePosition(PortalShape.getRelativePosition(")
            result.append(rectangle)
            result.append(", ")
            result.append(axis)
            result.append(", ")
            result.append(relativePosition)
            result.append(", ")
            result.append(dimensions)
            result.append("), ")
            result.append(level)
            result.append(", ")
            result.append(entity)
            result.append(", ")
            result.append(dimensions)
            result.append("), ")
            result.append(speed)
            result.append(", ")
            result.append(yRot)
            result.append(", ")
            result.append(xRot)
            result.append(", DimensionTransition.PLACE_PORTAL_TICKET)")
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        result.append(source, cursor, source.length)
        return result.toString()
    }

    private fun inferLegacyTeleporterDefaultPortalPosition(getPortalInfoMethod: String): String? {
        val id = """[A-Za-z_$][\w$]*"""
        return Regex("""\bBlockPos\s+($id)\s*=""")
            .findAll(getPortalInfoMethod)
            .map { it.groupValues[1] }
            .firstOrNull { variable ->
                val escaped = Regex.escape(variable)
                Regex("""\b(?:placeInExistingPortal|moveToSafeCoords)\(\s*[A-Za-z_$][\w$]*\s*,\s*[A-Za-z_$][\w$]*\s*,\s*$escaped\s*\)""")
                    .containsMatchIn(getPortalInfoMethod)
            }
    }

    private fun migrateLegacyCanChangeDimensionsCallSites(source: String): String {
        if (!source.contains(".canChangeDimensions()")) return source
        var result = source
        val oldGuard = Regex(
            """if\s*\(\s*([A-Za-z_$][\w$]*)\.isPassenger\(\)\s*\|\|\s*\1\.isVehicle\(\)\s*\|\|\s*!\s*\1\.canChangeDimensions\(\)\s*\)\s*\{\s*return\s*;\s*\}"""
        ).find(result) ?: return migrateHelperResolvedCanChangeDimensionsCallSites(source)
        val entity = oldGuard.groupValues[1]
        result = result.substring(0, oldGuard.range.first) +
            "if ($entity.isPassenger() || $entity.isVehicle()) {\n\t\t\treturn;\n\t\t}" +
            result.substring(oldGuard.range.last + 1)
        val nullGuard = Regex("""if\s*\(\s*([A-Za-z_$][\w$]*)\s*==\s*null\s*\)\s*(?:\{\s*)?return\s*;(?:\s*\})?""")
            .find(result, oldGuard.range.first)
            ?: return result
        val serverLevel = nullGuard.groupValues[1]
        val replacement = "if ($serverLevel == null || !$entity.canChangeDimensions($entity.level(), $serverLevel))\n\t\t\treturn;"
        return result.substring(0, nullGuard.range.first) + replacement + result.substring(nullGuard.range.last + 1)
    }

    private fun migrateHelperResolvedCanChangeDimensionsCallSites(source: String): String {
        val helpers = portalDimensionHelperMethods(source)
        if (helpers.isEmpty()) return source
        var result = source
        var changed = false
        for (helper in helpers) {
            val helperCall = Regex("""\b(?:this\.)?${Regex.escape(helper.name)}\s*\(\s*([A-Za-z_$][\w$]*)\s*\)""")
            val guardedEntities = helperCall.findAll(result)
                .map { it.groupValues[1] }
                .filter { entity -> Regex("""\b${Regex.escape(entity)}\.canChangeDimensions\(\)""").containsMatchIn(result) }
                .distinct()
                .toList()
            if (guardedEntities.isEmpty()) continue

            val withHelperGuard = addCanChangeDimensionsToHelperDestinationGuard(result, helper)
            if (withHelperGuard == result) continue
            result = withHelperGuard
            for (entity in guardedEntities) {
                result = removeNoArgCanChangeDimensionsCondition(result, entity)
            }
            changed = true
        }
        return if (changed) result else source
    }

    private data class PortalDimensionHelper(
        val name: String,
        val entityParameter: String,
        val destinationLevel: String
    )

    private fun portalDimensionHelperMethods(source: String): List<PortalDimensionHelper> {
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:private|protected|public)\s+(?:static\s+)?[\w.$<>\[\], ?]+\s+([A-Za-z_$][\w$]*)\s*\(\s*Entity\s+([A-Za-z_$][\w$]*)\s*\)\s*\{"""
        )
        return methodPattern.findAll(source).mapNotNull { match ->
            val openBrace = source.indexOf('{', match.range.last - 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) return@mapNotNull null
            val body = source.substring(openBrace + 1, closeBrace)
            val entity = match.groupValues[2]
            val destination = Regex("""\bServerLevel\s+([A-Za-z_$][\w$]*)\s*=""")
                .find(body)
                ?.groupValues
                ?.get(1)
                ?: return@mapNotNull null
            val usesDestinationTransition = Regex(
                """\b${Regex.escape(entity)}\.changeDimension\s*\([\s\S]*\b${Regex.escape(destination)}\b"""
            ).containsMatchIn(body)
            val hasDestinationGuard = Regex("""\bif\s*\(\s*${Regex.escape(destination)}\s*!=\s*null\b""")
                .containsMatchIn(body)
            if (!usesDestinationTransition || !hasDestinationGuard) return@mapNotNull null
            PortalDimensionHelper(match.groupValues[1], entity, destination)
        }.toList()
    }

    private fun addCanChangeDimensionsToHelperDestinationGuard(source: String, helper: PortalDimensionHelper): String {
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:private|protected|public)\s+(?:static\s+)?[\w.$<>\[\], ?]+\s+${Regex.escape(helper.name)}\s*\(\s*Entity\s+${Regex.escape(helper.entityParameter)}\s*\)\s*\{"""
        )
        val method = methodPattern.find(source) ?: return source
        val openBrace = source.indexOf('{', method.range.last - 1)
        val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
        if (openBrace < 0 || closeBrace < 0) return source
        val methodText = source.substring(method.range.first, closeBrace + 1)
        val canChange = "${helper.entityParameter}.canChangeDimensions(${helper.entityParameter}.level(), ${helper.destinationLevel})"
        if (methodText.contains(canChange)) return source
        var migratedMethod = Regex(
            """if\s*\(\s*${Regex.escape(helper.destinationLevel)}\s*!=\s*null\s*&&\s*!\s*${Regex.escape(helper.entityParameter)}\.isPassenger\(\)\s*\)"""
        ).replace(methodText) {
            "if (${helper.destinationLevel} != null && !${helper.entityParameter}.isPassenger() && $canChange)"
        }
        if (migratedMethod == methodText) {
            migratedMethod = Regex("""if\s*\(\s*${Regex.escape(helper.destinationLevel)}\s*!=\s*null\s*\)""")
                .replace(methodText) { "if (${helper.destinationLevel} != null && $canChange)" }
        }
        if (migratedMethod == methodText) return source
        return source.substring(0, method.range.first) + migratedMethod + source.substring(closeBrace + 1)
    }

    private fun removeNoArgCanChangeDimensionsCondition(source: String, entity: String): String {
        val escapedEntity = Regex.escape(entity)
        var result = source
        result = Regex("""\s*&&\s*$escapedEntity\.canChangeDimensions\(\)""").replace(result, "")
        result = Regex("""$escapedEntity\.canChangeDimensions\(\)\s*&&\s*""").replace(result, "")
        result = Regex("""!\s*$escapedEntity\.canChangeDimensions\(\)\s*\|\|\s*""").replace(result, "")
        result = Regex("""\s*\|\|\s*!\s*$escapedEntity\.canChangeDimensions\(\)""").replace(result, "")
        return result
    }

    private fun migrateLegacyPortalWaitTimeCalls(source: String): String =
        if (source.contains(".getPortalWaitTime()")) {
            source.replace(".getPortalWaitTime()", ".getDimensionChangingDelay()")
        } else {
            source
        }

    private fun migrateLegacyAnimalFoodPredicateOverrides(source: String): String {
        if ((!source.contains("extends Animal") && !source.contains("extends TamableAnimal")) ||
            source.contains("isFood(ItemStack")) {
            return source
        }

        val temptIngredient = Regex("""new\s+TemptGoal\s*\([^;]*?Ingredient\.of\(\s*([^)]+?)\s*\)""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.trim()
        val interactAt = javaMethodText(source, "interactAt")
        val feedingIngredient = interactAt
            ?.let {
                Regex("""(?:getMainHandItem|getOffhandItem|getItemInHand)\s*\([^)]*\)?\.is\s*\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\)""")
                    .find(it)
                    ?.groupValues
                    ?.get(1)
                    ?.trim()
            }
        val predicate = temptIngredient ?: feedingIngredient ?: return source
        val method = """

	@Override
	public boolean isFood(ItemStack stack) {
		return stack.is($predicate);
	}
""".trimEnd()
        return addImportIfMissing(insertBeforeLastClassBrace(source, method), "net.minecraft.world.item.ItemStack")
    }

    private fun migrateLegacyMushroomBlockConstructorOrder(source: String): String {
        if (!source.contains("extends MushroomBlock") || !source.contains("super(")) return source
        return Regex("""super\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)\s*\);""")
            .replace(source) { match ->
                val first = match.groupValues[1]
                val second = match.groupValues[2]
                if (first == "properties" || first.endsWith("Properties")) {
                    "super($second, $first);"
                } else {
                    match.value
                }
            }
    }

    private fun migrateLegacyVanillaBlockConstructors121(source: String): String {
        if (!source.contains("new StairBlock(") &&
            !source.contains("new ButtonBlock(") &&
            !source.contains("new FenceGateBlock(") &&
            !source.contains("new PressurePlateBlock(") &&
            !source.contains("new DoorBlock(") &&
            !source.contains("new TrapDoorBlock(") &&
            !source.contains("new TorchBlock(") &&
            !source.contains("new WallTorchBlock(")
        ) {
            return source
        }

        var result = source
        result = rewriteJavaNew(result, "StairBlock") { args ->
            if (args.size != 2) return@rewriteJavaNew null
            val stateSupplier = args[0].trim()
            if (!stateSupplier.startsWith("() ->") || !stateSupplier.contains(".defaultBlockState()")) {
                return@rewriteJavaNew null
            }
            val state = stateSupplier.removePrefix("() ->").trim()
            "new StairBlock($state, ${args[1].trim()})"
        }
        result = rewriteJavaNew(result, "ButtonBlock") { args ->
            if (args.size != 4 || !looksLikeBlockPropertiesExpression(args[0])) return@rewriteJavaNew null
            "new ButtonBlock(${args[1].trim()}, ${args[2].trim()}, ${args[0].trim()})"
        }
        result = rewriteJavaNew(result, "FenceGateBlock") { args ->
            if (args.size != 2 || !looksLikeBlockPropertiesExpression(args[0])) return@rewriteJavaNew null
            "new FenceGateBlock(${args[1].trim()}, ${args[0].trim()})"
        }
        result = rewriteJavaNew(result, "PressurePlateBlock") { args ->
            if (args.size != 3 || !args[0].trim().contains("Sensitivity") || !looksLikeBlockPropertiesExpression(args[1])) {
                return@rewriteJavaNew null
            }
            "new PressurePlateBlock(${args[2].trim()}, ${args[1].trim()})"
        }
        result = rewriteJavaNew(result, "DoorBlock") { args ->
            if (args.size != 2 || !looksLikeBlockPropertiesExpression(args[0])) return@rewriteJavaNew null
            "new DoorBlock(${args[1].trim()}, ${args[0].trim()})"
        }
        result = rewriteJavaNew(result, "TrapDoorBlock") { args ->
            if (args.size != 2 || !looksLikeBlockPropertiesExpression(args[0])) return@rewriteJavaNew null
            "new TrapDoorBlock(${args[1].trim()}, ${args[0].trim()})"
        }
        result = rewriteJavaNew(result, "TorchBlock") { args ->
            if (args.size != 2 || !looksLikeBlockPropertiesExpression(args[0]) || !looksLikeParticleOptionsExpression(args[1])) {
                return@rewriteJavaNew null
            }
            "new TorchBlock(${args[1].trim()}, ${args[0].trim()})"
        }
        result = rewriteJavaNew(result, "WallTorchBlock") { args ->
            if (args.size != 2 || !looksLikeBlockPropertiesExpression(args[0]) || !looksLikeParticleOptionsExpression(args[1])) {
                return@rewriteJavaNew null
            }
            "new WallTorchBlock(${args[1].trim()}, ${args[0].trim()})"
        }
        return result
    }

    private fun looksLikeBlockPropertiesExpression(expression: String): Boolean {
        val trimmed = expression.trim()
        return trimmed.contains("BlockBehaviour.Properties.") ||
            trimmed.contains(".Properties.") ||
            trimmed.startsWith("properties") ||
            trimmed.endsWith("Properties") ||
            trimmed.contains(".ofFullCopy(") ||
            trimmed.contains(".ofLegacyCopy(") ||
            trimmed.contains(".of()") ||
            trimmed.contains(".strength(") ||
            trimmed.contains(".sound(") ||
            trimmed.contains(".noCollission()") ||
            trimmed.contains(".noOcclusion()")
    }

    private fun looksLikeParticleOptionsExpression(expression: String): Boolean {
        val trimmed = expression.trim()
        return Regex("""\b(?:ParticleTypes|[A-Za-z_$][\w$]*ParticleTypes)\.[A-Z][A-Z0-9_]*(?:\.get\(\))?\b""").containsMatchIn(trimmed) ||
            Regex("""\b(?:ParticleOptions|SimpleParticleType|ParticleType\s*<[^>]+>)\s+[A-Za-z_$][\w$]*\b""").containsMatchIn(trimmed)
    }

    private fun migrateLegacyGameEventConstructors(source: String): String {
        if (!source.contains("new GameEvent(") || !source.contains("DeferredRegister")) return source
        val gameEventRegisters = Regex("""\bDeferredRegister\s*<\s*GameEvent\s*>\s+([A-Za-z_$][\w$]*)\s*=""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (gameEventRegisters.isEmpty()) return source

        val stringLiteral = Regex(""""(?:\\.|[^"\\])*"""")
        fun migrateSupplier(registerId: String, supplier: String): String {
            return rewriteJavaNew(supplier, "GameEvent") { args ->
                if (args.size != 2) return@rewriteJavaNew null
                val legacyId = args[0].trim()
                if (!stringLiteral.matches(registerId) || legacyId != registerId) return@rewriteJavaNew null
                "new GameEvent(${args[1].trim()})"
            }
        }

        return rewriteJavaCall(source, "register") { receiver, args ->
            if (args.size < 2) return@rewriteJavaCall null
            val registerName = receiver.trim().substringAfterLast(".")
            if (registerName !in gameEventRegisters) return@rewriteJavaCall null
            val migratedSupplier = migrateSupplier(args[0].trim(), args[1])
            if (migratedSupplier == args[1]) return@rewriteJavaCall null
            val migratedArgs = args.toMutableList()
            migratedArgs[1] = migratedSupplier
            "$receiver.register(${migratedArgs.joinToString(", ") { it.trim() }})"
        }
    }

    private fun migrateLegacyBannerPatternConstructors(source: String): String {
        if (!source.contains("BannerPattern") || !source.contains("new BannerPattern(")) return source
        val namespaceExpression = inferBannerPatternNamespaceExpression(source) ?: return source
        var changed = false
        val result = rewriteJavaNew(source, "BannerPattern") { args ->
            if (args.size != 1) return@rewriteJavaNew null
            val translationKey = args[0].trim()
            if (!Regex(""""(?:\\.|[^"\\])*"""").matches(translationKey)) return@rewriteJavaNew null
            changed = true
            "new BannerPattern(ResourceLocation.fromNamespaceAndPath($namespaceExpression, $translationKey), $translationKey)"
        }
        return if (changed) addImportIfMissing(result, "net.minecraft.resources.ResourceLocation") else source
    }

    private fun inferBannerPatternNamespaceExpression(source: String): String? =
        inferModAccess(source)?.modIdExpression
            ?: Regex("""DeferredRegister\.create\(\s*Registries\.BANNER_PATTERN\s*,\s*([^)]+?)\s*\)""")
                .find(source)
                ?.groupValues
                ?.get(1)
                ?.trim()

    private fun migrateLegacyWallSignBlockCodecSource(source: String): String {
        if (!source.contains("extends WallSignBlock") || !source.contains("WoodType")) return source
        val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+WallSignBlock\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return source
        var result = source

        val codecReplacement = """
@Override
    public com.mojang.serialization.MapCodec<WallSignBlock> codec() {
        return CODEC;
    }
""".trimEnd()
        javaMethodText(result, "codec")?.let { method ->
            if (method.contains("WallSignBlock") && method.contains("CODEC")) {
                result = result.replace(method, codecReplacement)
            }
        }
        result = Regex(
            """public\s+static\s+final\s+com\.mojang\.serialization\.MapCodec<${Regex.escape(className)}>\s+CODEC\s*=\s*com\.mojang\.serialization\.codecs\.RecordCodecBuilder(?:\s*\.\s*<\s*${Regex.escape(className)}\s*>)?\.mapCodec\(\s*instance\s*->\s*instance\.group\(\s*WoodType\.CODEC\.fieldOf\("type"\)\.forGetter\(${Regex.escape(className)}::getType\),\s*propertiesCodec\(\)\s*\)\.apply\(instance,\s*\(type,\s*properties\)\s*->\s*new\s+${Regex.escape(className)}\(properties,\s*type\)\)\s*\);"""
        ).replace(result) {
            """
public static final com.mojang.serialization.MapCodec<WallSignBlock> CODEC = com.mojang.serialization.codecs.RecordCodecBuilder.mapCodec(instance -> instance.group(
            WoodType.CODEC.fieldOf("type").forGetter(block -> (($className) block).getType()),
            propertiesCodec()
        ).apply(instance, (type, properties) -> new $className(properties, type)));
""".trimEnd()
        }
        result = Regex("""public\s+static\s+final\s+com\.mojang\.serialization\.MapCodec\s*<\s*${Regex.escape(className)}\s*>\s+CODEC\s*=""")
            .replace(result, "public static final com.mojang.serialization.MapCodec<WallSignBlock> CODEC =")
        result = result
            .replace(
                "RecordCodecBuilder.<$className>mapCodec",
                "RecordCodecBuilder.mapCodec"
            )
            .replace(
                "WoodType.CODEC.fieldOf(\"type\").forGetter($className::getType)",
                "WoodType.CODEC.fieldOf(\"type\").forGetter(block -> (($className) block).getType())"
            )

        if (!Regex("""\bprivate\s+final\s+WoodType\s+type\s*;""").containsMatchIn(result)) {
            val classOpen = result.indexOf('{', Regex("""\bclass\s+${Regex.escape(className)}\b""").find(result)?.range?.first ?: 0)
            if (classOpen >= 0) {
                result = result.substring(0, classOpen + 1) +
                    "\n\tprivate final WoodType type;\n" +
                    result.substring(classOpen + 1)
            }
        }

        val constructor = Regex(
            """public\s+${Regex.escape(className)}\s*\(\s*Properties\s+([A-Za-z_$][\w$]*)\s*,\s*WoodType\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).find(result)
        if (constructor != null) {
            val openBrace = result.indexOf('{', constructor.range.last + 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (closeBrace >= 0) {
                val propertiesName = constructor.groupValues[1]
                val typeName = constructor.groupValues[2]
                val body = result.substring(openBrace + 1, closeBrace)
                if (body.contains("super($typeName, $propertiesName)")) {
                    val getter = if (Regex("""\bWoodType\s+getType\s*\(""").containsMatchIn(result)) {
                        ""
                    } else {
                        """

	public WoodType getType() {
		return this.type;
	}
""".trimEnd()
                    }
                    val replacement = """
public $className(Properties $propertiesName, WoodType $typeName) {
		super($typeName, $propertiesName);
		this.type = $typeName;
	}$getter
""".trimEnd()
                    result = result.substring(0, constructor.range.first) + replacement + result.substring(closeBrace + 1)
                }
            }
        }
        return Regex("""(?m)([ \t]*@Override\s*\r?\n\s*){2,}""")
            .replace(result) { match -> match.groupValues[1] }
    }

    private fun migrateLegacyMapCodecOptionalFields(source: String): String {
        if (!source.contains(".CODEC.optionalFieldOf(") || !source.contains("MapCodec<")) return source
        val mapCodecTypes = Regex("""\bMapCodec<\s*([A-Za-z_$][\w$]*)\s*>\s+CODEC\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (mapCodecTypes.isEmpty()) return source
        var result = source
        for (type in mapCodecTypes) {
            result = result.replace("$type.CODEC.optionalFieldOf(", "$type.CODEC.codec().optionalFieldOf(")
        }
        return result
    }

    private fun migrateLegacyComponentSerializationSource(source: String): String {
        if (!source.contains("Component.Serializer.toJson(") && !source.contains("Component.Serializer.fromJson(")) return source
        var result = source
        result = rewriteJavaInvocationArgumentsWithOffset(result, "Component.Serializer.toJson") { args, offset ->
            val registries = registryAccessExpressionAt(result, offset) ?: return@rewriteJavaInvocationArgumentsWithOffset null
            when {
                args.size == 1 -> listOf(args[0], registries)
                args.size == 2 && isRegistryAccessEmptyExpression(args[1]) -> listOf(args[0], registries)
                else -> null
            }
        }
        result = rewriteJavaInvocationArgumentsWithOffset(result, "Component.Serializer.fromJson") { args, offset ->
            val registries = registryAccessExpressionAt(result, offset) ?: return@rewriteJavaInvocationArgumentsWithOffset null
            when {
                args.size == 1 -> listOf(args[0], registries)
                args.size == 2 && isRegistryAccessEmptyExpression(args[1]) -> listOf(args[0], registries)
                else -> null
            }
        }
        return result
    }

    private fun migrateGameProfileDisplayNameComponents(source: String): String {
        if (!source.contains("ComponentUtils.getDisplayName(")) return source

        var result = rewriteJavaCall(source, "getDisplayName") { receiver, args ->
            if (receiver != "ComponentUtils" || args.size != 1) return@rewriteJavaCall null
            val profile = args[0].trim()
            "Component.literal($profile.getName())"
        }
        if (result == source) return source

        result = addImportIfMissing(result, "net.minecraft.network.chat.Component")
        val withoutComponentUtils = removeImport(result, "net.minecraft.network.chat.ComponentUtils")
        if (!Regex("""\bComponentUtils\b""").containsMatchIn(withoutComponentUtils)) {
            result = withoutComponentUtils
        }
        return result
    }

    private fun migrateRegistryAccessEmptyFallbacks(source: String): String {
        if (!source.contains("RegistryAccess.EMPTY")) return source
        var result = source
        var cursor = 0
        val qualifiedEmpty = "net.minecraft.core.RegistryAccess.EMPTY"
        while (cursor < result.length) {
            val index = result.indexOf(qualifiedEmpty, cursor)
            if (index < 0) break
            val replacement = registryAccessExpressionAt(result, index)
            if (replacement == null || replacement == qualifiedEmpty) {
                cursor = index + qualifiedEmpty.length
                continue
            }
            result = result.substring(0, index) + replacement + result.substring(index + qualifiedEmpty.length)
            cursor = index + replacement.length
        }
        return result
    }

    private fun isRegistryAccessEmptyExpression(expression: String): Boolean =
        expression.trim() == "net.minecraft.core.RegistryAccess.EMPTY" || expression.trim() == "RegistryAccess.EMPTY"

    private fun migrateLegacyGameEventListenerSource(source: String): String {
        if (!source.contains("GameEventListener") || !source.contains("handleGameEvent(")) return source
        var result = source
        var changed = false
        result = Regex(
            """boolean\s+handleGameEvent\s*\(\s*ServerLevel\s+([A-Za-z_$][\w$]*)\s*,\s*GameEvent\s+([A-Za-z_$][\w$]*)\s*,\s*GameEvent\.Context\s+([A-Za-z_$][\w$]*)\s*,\s*Vec3\s+([A-Za-z_$][\w$]*)\s*\)"""
        ).replace(result) { match ->
            changed = true
            "boolean handleGameEvent(ServerLevel ${match.groupValues[1]}, Holder<GameEvent> ${match.groupValues[2]}, GameEvent.Context ${match.groupValues[3]}, Vec3 ${match.groupValues[4]})"
        }

        val holderEventVariables = Regex("""\bHolder\s*<\s*GameEvent\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        if (holderEventVariables.isEmpty()) return if (changed) addImportIfMissing(result, "net.minecraft.core.Holder") else result

        val eventConstant = """((?:[A-Za-z_$][\w$]*\.)+[A-Z0-9_$][A-Za-z0-9_$]*(?:\.get\(\))?)"""
        for (eventVariable in holderEventVariables) {
            result = Regex("""\b${Regex.escape(eventVariable)}\s*==\s*$eventConstant""")
                .replace(result) { match ->
                    changed = true
                    "${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
                }
            result = Regex("""$eventConstant\s*==\s*\b${Regex.escape(eventVariable)}\b""")
                .replace(result) { match ->
                    changed = true
                    "${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
                }
            result = Regex("""\b${Regex.escape(eventVariable)}\s*!=\s*$eventConstant""")
                .replace(result) { match ->
                    changed = true
                    "!${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
                }
            result = Regex("""$eventConstant\s*!=\s*\b${Regex.escape(eventVariable)}\b""")
                .replace(result) { match ->
                    changed = true
                    "!${eventVariable}.is(${normaliseGameEventHolderComparison(match.groupValues[1])})"
                }
        }

        return if (changed) addImportIfMissing(result, "net.minecraft.core.Holder") else result
    }

    private fun normaliseGameEventHolderComparison(expression: String): String =
        expression.trim().removeSuffix(".get()")

    private fun migrateRequiredMapCodecConstants(source: String): String {
        if (!source.contains("Codec<") || !source.contains("CODEC")) return source
        val mapCodecTypes = mutableSetOf<String>()
        val topLevelClassName = classNameOfJavaSource(source)
        val mapCodecBasePattern = """(?:[A-Za-z_$][\w$]*\.)*(?:BiomeSource|PlacementModifier|Structure|StructureProcessor|StructurePlacement)"""
        if (topLevelClassName != null &&
            Regex("""\bextends\s+$mapCodecBasePattern\b""").containsMatchIn(source)
        ) {
            mapCodecTypes += topLevelClassName
        }
        Regex("""\b(?:class|record)\s+([A-Za-z_$][\w$]*)\b[^{;]*\bextends\s+$mapCodecBasePattern\b""")
            .findAll(source)
            .forEach { mapCodecTypes += it.groupValues[1] }
        if (mapCodecTypes.isEmpty()) return source

        var result = source
        var changed = false
        for (className in mapCodecTypes) {
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*RecordCodecBuilder\s*\.\s*(?:<\s*${Regex.escape(className)}\s*>\s*)?create\s*\("""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = RecordCodecBuilder.<$className>mapCodec("
            }

            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*((?:[A-Za-z_$][\w$]*\.)*[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*\.CODEC(?:\.codec\(\))?\.listOf\(\))\.xmap\(([^;\r\n]+)\);"""
            ).replace(result) { match ->
                val fieldName = Regex("""\b[A-Za-z_$][\w$]*\s*->\s*[A-Za-z_$][\w$]*\.([A-Za-z_$][\w$]*)\b""")
                    .find(match.groupValues[3])
                    ?.groupValues
                    ?.get(1)
                    ?: "value"
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = ${match.groupValues[2]}.fieldOf(\"$fieldName\").xmap(${match.groupValues[3]});"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*((?:[A-Za-z_$][\w$]*\.)*[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*\.CODEC(?:\.codec\(\))?\.listOf\(\)\.fieldOf\("[^"]+"\)\.xmap\([^;\r\n]+?\))\.codec\(\)\s*;"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = ${match.groupValues[2]};"
            }
            result = Regex(
                """\bCodec\s*<\s*${Regex.escape(className)}\s*>\s+([A-Z][A-Z0-9_]*)\s*=\s*Codec\.unit\(\s*\(\s*\)\s*->\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\)\s*;"""
            ).replace(result) { match ->
                changed = true
                "MapCodec<$className> ${match.groupValues[1]} = MapCodec.unit(${match.groupValues[2]});"
            }
        }

        if (changed) {
            result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
            if (!Regex("""\bCodec\s*<""").containsMatchIn(result) && !Regex("""\bCodec\.""").containsMatchIn(result)) {
                result = removeImport(result, "com.mojang.serialization.Codec")
            }
        }
        if (result.contains("extends BiomeSource")) {
            result = Regex("""protected\s+Codec\s*<\s*\?\s+extends\s+BiomeSource\s*>\s+codec\s*\(""")
                .replace(result, "protected MapCodec<? extends BiomeSource> codec(")
        }
        return result
    }

    private fun migrateKnownVanillaCodecCodecCalls(
        source: String,
        mapCodecConstantOwners: Set<String>,
        codecConstantOwners: Set<String>
    ): String {
        if (!source.contains(".CODEC.codec()")) return source
        val knownCodecOwners = setOf(
            "BlockState",
            "BoundingBox",
            "MobSpawnSettings.SpawnerData",
            "ProcessorRule",
            "ResourceLocation",
            "TreeDecorator"
        )
        var result = source
        for (owner in knownCodecOwners + codecConstantOwners) {
            if (owner in mapCodecConstantOwners) continue
            result = Regex("""\b((?:[A-Za-z_$][\w$]*\.)*${Regex.escape(owner)}\.CODEC)\.codec\(\)""")
                .replace(result) { match -> match.groupValues[1] }
        }
        return result
    }

    private fun migrateMapCodecFeatureConstructorArguments(
        source: String,
        mapCodecConstantOwners: Set<String>
    ): String {
        if (mapCodecConstantOwners.isEmpty() || !source.contains("new ") || !source.contains(".CODEC")) return source
        var result = source
        var cursor = 0
        val pattern = Regex("""new\s+([A-Za-z_$][\w$]*)\s*\(""")
        while (true) {
            val match = pattern.find(result, cursor) ?: break
            val className = match.groupValues[1]
            if (!className.endsWith("Feature")) {
                cursor = match.range.last + 1
                continue
            }
            val openParen = result.indexOf('(', match.range.last)
            val closeParen = if (openParen >= 0) findMatchingParen(result, openParen) else -1
            if (openParen < 0 || closeParen < 0) {
                cursor = match.range.last + 1
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val migratedArgs = args.map { arg -> migrateMapCodecReferenceArgument(arg, mapCodecConstantOwners) }
            if (migratedArgs != args) {
                val replacement = migratedArgs.joinToString(", ")
                result = result.substring(0, openParen + 1) + replacement + result.substring(closeParen)
                cursor = openParen + replacement.length + 1
            } else {
                cursor = closeParen + 1
            }
        }
        return result
    }

    private fun migrateMapCodecReferenceArgument(arg: String, mapCodecConstantOwners: Set<String>): String {
        val trimmed = arg.trim()
        if (trimmed.endsWith(".codec()")) return arg
        val owner = mapCodecCodecReferenceOwner(trimmed) ?: return arg
        return if (owner in mapCodecConstantOwners) "${trimmed}.codec()" else arg
    }

    private fun migrateLegacyLazyRegistryCodecs(source: String): String {
        if (!source.contains("ExtraCodecs.lazyInitializedCodec(") || !source.contains(".byNameCodec()")) return source
        var result = Regex(
            """ExtraCodecs\.lazyInitializedCodec\(\s*\(\s*\)\s*->\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.byNameCodec\(\))\s*\)"""
        ).replace(source) { match -> match.groupValues[1] }
        if (!result.contains("ExtraCodecs.")) {
            result = removeImport(result, "net.minecraft.util.ExtraCodecs")
        }
        return result
    }

    private fun migrateLegacyDeferredHolderDelegateAccessors(source: String): String {
