            ).replace(result) { match ->
                changed = true
                "public $className(PackOutput ${match.groupValues[1]}, CompletableFuture<HolderLookup.Provider> lookupProvider) {\n\t\tsuper(${match.groupValues[1]}, lookupProvider, ${match.groupValues[2].trim()});\n\t}"
            }
