    private fun migrateLegacyPackMetadataSectionSource(source: String): String {
        if (!source.contains("new PackMetadataSection(") || !source.contains("Collectors.toMap")) return source
        var result = source
        var changed = false
        var cursor = 0
        val token = "new PackMetadataSection"
        while (cursor < result.length) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = result.indexOf('(', tokenIndex + token.length)
            if (openParen < 0) break
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            if (args.size == 3 && args[2].contains("Collectors.toMap")) {
                val replacementArgs = listOf(
                    args[0].trim(),
                    args[1].trim(),
                    "java.util.Optional.of(new InclusiveRange<>(0, Integer.MAX_VALUE))"
                ).joinToString(",\n\t\t\t\t\t\t")
                result = result.substring(0, openParen + 1) + replacementArgs + result.substring(closeParen)
                changed = true
                cursor = openParen + replacementArgs.length + 1
            } else {
                cursor = closeParen + 1
            }
        }
        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.util.InclusiveRange")
        if (!result.contains("Arrays.")) {
            result = removeImport(result, "java.util.Arrays")
        }
        if (!result.contains("Function.")) {
            result = removeImport(result, "java.util.function.Function")
        }
        if (!result.contains("Collectors.")) {
            result = removeImport(result, "java.util.stream.Collectors")
        }
        return result
    }

    private fun migrateLegacyLootFunctionSource(source: String): String {
        if (!source.contains("SetNbtFunction") &&
            !source.contains("EnchantWithLevelsFunction.enchantWithLevels(") &&
            !source.contains("SetEnchantmentsFunction") &&
            !source.contains("EnchantRandomlyFunction") &&
            !source.contains("LootingEnchantFunction") &&
            !source.contains("SetNameFunction.setName(") &&
            !source.contains(".serializeNBT()")
        ) {
            return source
        }

        var result = source
        var changed = false
        val needsProvider =
            result.contains("EnchantWithLevelsFunction.enchantWithLevels(") ||
                result.contains("new SetEnchantmentsFunction.Builder") ||
                result.contains("new EnchantRandomlyFunction.Builder().withEnchantment(")
        if (needsProvider && result.contains("implements LootTableSubProvider")) {
            val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+implements\s+LootTableSubProvider\b""")
                .find(result)
                ?.groupValues
                ?.get(1)
            if (className != null && !result.contains("private final HolderLookup.Provider registries;")) {
                result = Regex("""(?m)^([ \t]*)@Override\s*\r?\n([ \t]*)public\s+void\s+generate\(""")
                    .replace(result, "    private final HolderLookup.Provider registries;\n\n    public $className(HolderLookup.Provider registries) {\n        this.registries = registries;\n    }\n\n$1@Override\n$2public void generate(")
                changed = true
            }
        }

        if (result.contains("SetNbtFunction.setTag")) {
            result = Regex(
                """SetNbtFunction\.setTag\(\s*Util\.make\(\s*new\s+CompoundTag\(\)\s*,\s*(?:\(\s*)?([A-Za-z_$][\w$]*)(?:\s*\))?\s*->\s*\1\.putString\(\s*"Potion"\s*,\s*"minecraft:([a-z0-9_]+)"\s*\)\s*\)\s*\)"""
            ).replace(result) { match ->
                changed = true
                "SetPotionFunction.setPotion(Potions.${match.groupValues[2].uppercase()})"
            }
            migrateLegacySetNbtContainerContentsSource(result)?.let { migrated ->
                result = migrated
                changed = true
            }
        }

        if (result.contains("EnchantWithLevelsFunction.enchantWithLevels(")) {
            result = rewriteJavaCall(result, "enchantWithLevels") { receiver, args ->
                if (receiver != "EnchantWithLevelsFunction" || args.size != 1) return@rewriteJavaCall null
                changed = true
                "EnchantWithLevelsFunction.enchantWithLevels(this.registries, ${args[0]})"
            }
        }

        if (result.contains("LootingEnchantFunction.lootingMultiplier(")) {
            result = rewriteJavaCall(result, "lootingMultiplier") { receiver, args ->
                if (receiver != "LootingEnchantFunction" || args.size != 1) return@rewriteJavaCall null
                changed = true
                "EnchantedCountIncreaseFunction.lootingMultiplier(this.registries, ${args[0].trim()})"
            }
            result = result.replace(
                "import net.minecraft.world.level.storage.loot.functions.LootingEnchantFunction;",
                "import net.minecraft.world.level.storage.loot.functions.EnchantedCountIncreaseFunction;"
            )
        }

        if (result.contains("SetNameFunction.setName(")) {
            result = rewriteJavaCall(result, "setName") { receiver, args ->
                if (receiver != "SetNameFunction" || args.size != 1) return@rewriteJavaCall null
                changed = true
                "SetNameFunction.setName(${args[0].trim()}, SetNameFunction.Target.CUSTOM_NAME)"
            }
        }

        if (result.contains(".serializeNBT()") && result.contains("this.registries")) {
            result = Regex("""((?:new\s+)?[A-Za-z_$][\w$]*(?:\([^;]*?\))?)\.serializeNBT\(\)""")
                .replace(result) { match ->
                    changed = true
                    "${match.groupValues[1]}.save(this.registries)"
                }
        }

        result = Regex("""Enchantments\.ALL_DAMAGE_PROTECTION\b""").replace(result) {
            changed = true
            "Enchantments.PROTECTION"
        }
        result = Regex("""Enchantments\.FALL_PROTECTION\b""").replace(result) {
            changed = true
            "Enchantments.FEATHER_FALLING"
        }

        if (result.contains(".withEnchantment(")) {
            result = rewriteJavaCall(result, "withEnchantment") { receiver, args ->
                if (args.size != 2) return@rewriteJavaCall null
                val enchantment = args[0].trim()
                val holderExpr = enchantmentHolderExpression(enchantment) ?: return@rewriteJavaCall null
                changed = true
                "$receiver.withEnchantment($holderExpr, ${args[1].trim()})"
            }
            result = Regex("""\.withEnchantment\(\s*((?:[A-Za-z_$][\w$]*\.)+[A-Za-z_$][\w$]*\.get\(\))\s*\)""")
                .replace(result) { match ->
                    val holderExpr = enchantmentHolderExpression(match.groupValues[1]) ?: return@replace match.value
                    changed = true
                    ".withEnchantment($holderExpr)"
                }
        }

        if (!changed) return source
        if (result.contains("HolderLookup.Provider")) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        }
        if (result.contains("lookupOrThrow(Registries.ENCHANTMENT)")) {
            result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
        }
        if (result.contains("SetPotionFunction.setPotion(")) {
            result = addImportIfMissing(result, "net.minecraft.world.item.alchemy.Potions")
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.functions.SetPotionFunction")
            result = result.replace(Regex("""(?m)^[ \t]*import\s+net\.minecraft\.Util;\s*\r?\n"""), "")
            result = result.replace(Regex("""(?m)^[ \t]*import\s+net\.minecraft\.nbt\.CompoundTag;\s*\r?\n"""), "")
            result = result.replace(Regex("""(?m)^[ \t]*import\s+net\.minecraft\.world\.level\.storage\.loot\.functions\.SetNbtFunction;\s*\r?\n"""), "")
        }
        if (result.contains("SetContainerContents.setContents(")) {
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.ContainerComponentManipulators")
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.entries.LootItem")
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.functions.SetContainerContents")
            if (result.contains("SetItemCountFunction.setCount(")) {
                result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.functions.SetItemCountFunction")
                result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.providers.number.ConstantValue")
            }
            listOf(
                "net.minecraft.Util",
                "net.minecraft.nbt.CompoundTag",
                "net.minecraft.nbt.ListTag",
                "net.minecraft.world.level.storage.loot.functions.SetNbtFunction"
            ).forEach { importName ->
                val withoutImport = removeImport(result, importName)
                val simple = importName.substringAfterLast('.')
                if (!Regex("""\b${Regex.escape(simple)}\b""").containsMatchIn(withoutImport)) {
                    result = withoutImport
                }
            }
        }
        return result
    }

    private fun migrateLegacySetNbtContainerContentsSource(source: String): String? {
        if (!source.contains("SetNbtFunction.setTag") || !source.contains(".put(\"Items\"")) return null
        var result = source
        var changed = false
        val pattern = Regex(
            """(?s)SetNbtFunction\.setTag\(\s*Util\.make\(\s*new\s+CompoundTag\(\)\s*,\s*(?:\(\s*)?([A-Za-z_$][\w$]*)(?:\s*\))?\s*->\s*\{(.*?)\}\s*\)\s*\)"""
        )
        result = pattern.replace(result) { match ->
            val nbtVar = match.groupValues[1]
            val body = match.groupValues[2]
            val listVar = Regex("""\bListTag\s+([A-Za-z_$][\w$]*)\s*=\s*new\s+ListTag\s*\(\s*\)\s*;""")
                .find(body)
                ?.groupValues
                ?.get(1)
                ?: return@replace match.value
            if (!Regex("""\b${Regex.escape(nbtVar)}\.put\s*\(\s*"Items"\s*,\s*${Regex.escape(listVar)}\s*\)\s*;""").containsMatchIn(body)) {
                return@replace match.value
            }
            val entries = Regex(
                """(?s)\b${Regex.escape(listVar)}\.add\s*\(\s*new\s+ItemStack\s*\((.*?)\)\s*\.\s*(?:save\s*\([^)]*\)|serializeNBT\s*\(\s*\))\s*\)\s*;"""
            ).findAll(body).mapNotNull { itemMatch ->
                val args = splitTopLevelJavaArgs(itemMatch.groupValues[1]).map { it.trim() }
                if (args.isEmpty()) return@mapNotNull null
                val base = "LootItem.lootTableItem(${args[0]})"
                if (args.size >= 2) {
                    "$base.apply(SetItemCountFunction.setCount(ConstantValue.exactly(${args[1]})))"
                } else {
                    base
                }
            }.toList()
            if (entries.isEmpty()) return@replace match.value
            changed = true
            "SetContainerContents.setContents(ContainerComponentManipulators.BUNDLE_CONTENTS)" +
                entries.joinToString("") { "\n\t\t\t\t\t\t\t\t\t\t.withEntry($it)" }
        }
        return if (changed) result else null
    }

    private fun migrateLegacyEntityLootSubProviderSource(source: String): String {
        if (!source.contains("extends EntityLootSubProvider") &&
            !source.contains("ENTITY_ON_FIRE") &&
            !source.contains("ResourceKey.create(Registries.LOOT_TABLE")) {
            return source
        }

        var result = source
        var changed = false
        val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+EntityLootSubProvider\b""")
            .find(result)
            ?.groupValues
            ?.get(1)

        if (className != null) {
            val constructorPattern = Regex(
                """(?s)(protected|public)\s+${Regex.escape(className)}\s*\(\s*\)\s*\{\s*super\s*\((.*?)\)\s*;\s*\}"""
            )
            result = constructorPattern.replace(result) { match ->
                val args = splitTopLevelJavaArgs(match.groupValues[2]).map { it.trim() }
                if (args.isEmpty()) return@replace match.value
                changed = true
                "${match.groupValues[1]} $className(HolderLookup.Provider registries) {\n\t\tsuper(${(args + "registries").joinToString(", ")});\n\t}"
            }
        }

        if (result.contains("ENTITY_ON_FIRE")) {
            result = Regex(
                """LootItemEntityPropertyCondition\.hasProperties\(\s*LootContext\.EntityTarget\.THIS\s*,\s*ENTITY_ON_FIRE\s*\)"""
            ).replace(result) {
                changed = true
                "this.shouldSmeltLoot()"
            }
        }

        result = Regex(
            """ResourceKey\.create\(\s*Registries\.LOOT_TABLE\s*,\s*([^()]+\.getDefaultLootTable\(\)|BuiltInLootTables\.[A-Z0-9_]+|[A-Za-z_$][\w$]*LootTables\.[A-Z0-9_]+)\s*\)"""
        ).replace(result) { match ->
            changed = true
            match.groupValues[1].trim()
        }

        if (!changed) return source
        if (result.contains("HolderLookup.Provider")) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        }
        return result
    }

    private fun enchantmentHolderExpression(expression: String): String? {
        if (expression.contains("lookupOrThrow(Registries.ENCHANTMENT)") || expression.contains("Holder<")) return null
        if (expression.startsWith("Enchantments.") || expression.matches(Regex("""(?:[A-Za-z_$][\w$]*\.)+[A-Za-z_$][\w$]*\.get\(\)"""))) {
            val keyExpression = if (expression.endsWith(".get()")) expression.removeSuffix(".get()") else expression
            return "this.registries.lookupOrThrow(Registries.ENCHANTMENT).getOrThrow($keyExpression)"
        }
        return null
    }

    private fun migrateFinalMapDecorationSubclassSource(source: String): String {
        if (!source.contains("extends MapDecoration")) return source

        var result = source
        var changed = false
        val pattern = Regex("""(?s)public\s+static\s+class\s+([A-Za-z_$][\w$]*)\s+extends\s+MapDecoration\s*\{""")
        var cursor = 0
        while (true) {
            val match = pattern.find(result, cursor) ?: break
            val className = match.groupValues[1]
            val openBrace = result.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val replacementBody = rewriteMapDecorationSubclassBody(className, body)
            if (replacementBody == null) {
                cursor = closeBrace + 1
                continue
            }
            result = result.substring(0, match.range.first) +
                "public static class $className {\n$replacementBody\n\t}" +
                result.substring(closeBrace + 1)
            cursor = match.range.first + "public static class $className {\n$replacementBody\n\t}".length
            changed = true
        }

        if (!changed) return source
        result = result.replace("super.equals(o) && o instanceof", "o instanceof")
        result = result.replace("super.hashCode() * 31 +", "")
        result = Regex("""(?m)^([ \t]*)@Override\s*\r?\n([ \t]*(?:@[A-Za-z_$][\w$]*(?:\([^)]*\))?\s*\r?\n)?[ \t]*public\s+boolean\s+render\s*\()""")
            .replace(result, "$1$2")
        result = result.replace("Type.TARGET_X", "MapDecorationTypes.TARGET_X")
        result = addImportIfMissing(result, "net.minecraft.world.level.saveddata.maps.MapDecorationTypes")
        return migrateMapDecorationRecordSource(result)
    }

    private fun migrateFinalMapDecorationSubclassUsageSource(
        source: String,
        finalMapDecorationClasses: Set<String>
    ): String {
        if (finalMapDecorationClasses.isEmpty() || !source.contains(".decorations.put(")) return source
        var result = source
        finalMapDecorationClasses.forEach { className ->
            val variables = Regex("""\b(?:[A-Za-z_$][\w$]*\.)*${Regex.escape(className)}\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
            variables.forEach { variable ->
                result = Regex("""(\.decorations\.put\(\s*[^,\r\n]+,\s*)${Regex.escape(variable)}(\s*\))""")
                    .replace(result, "$1$variable.asMapDecoration()$2")
            }
        }
        return result
    }

    private fun rewriteMapDecorationSubclassBody(className: String, body: String): String? {
        if (!body.contains("super(")) return null
        var result = body
        val javaKeywords = setOf("false", "return", "static", "true")
        val legacyFieldAccessors = Regex("""(?m)^[ \t]*(?:(?:public|protected|private)\s+(?!static\b)(?:final\s+)?|final\s+)(?!static\b)([A-Za-z_$][\w$<>, ?.\[\]]*)\s+([A-Za-z_$][\w$]*)\s*;\s*$""")
            .findAll(result)
            .map { it.groupValues[1].trim() to it.groupValues[2] }
            .filter { (_, name) -> name != "decoration" && name !in javaKeywords }
            .distinctBy { (_, name) -> name }
            .toList()
        result = Regex("""(?m)^([ \t]*)(?:(?:public|protected|private)\s+)?(?:final\s+)?int\s+featureId\s*;\s*$""")
            .replace(result) { match ->
                val indent = match.groupValues[1]
                "${indent}private final int featureId;\n${indent}private final MapDecoration decoration;"
            }
        val constructorPattern = Regex("""(?s)public\s+${Regex.escape(className)}\s*\((.*?)\)\s*\{\s*super\s*\((.*?)\)\s*;\s*(.*?)\}""")
        var changed = false
        result = constructorPattern.replace(result) { match ->
            val params = match.groupValues[1]
            val args = splitTopLevelJavaArgs(match.groupValues[2])
            val rest = match.groupValues[3]
            if (args.size != 5) return@replace match.value
            val componentArg = args[4].trim()
            val nameArg = when {
                componentArg == "null" -> "java.util.Optional.empty()"
                componentArg.startsWith("java.util.Optional.") -> componentArg
                else -> "java.util.Optional.of($componentArg)"
            }
            changed = true
            "public $className($params) {\n\t\t\tthis.decoration = new MapDecoration(${args[0].trim()}, ${args[1].trim()}, ${args[2].trim()}, ${args[3].trim()}, $nameArg);\n${rest.trimEnd()}\n\t\t}"
        }
        if (!changed) return null
        val accessors = listOf(
            "x" to "byte",
            "y" to "byte",
            "rot" to "byte",
            "type" to "net.minecraft.core.Holder<net.minecraft.world.level.saveddata.maps.MapDecorationType>",
            "name" to "java.util.Optional<net.minecraft.network.chat.Component>"
        )
        val existing = accessors.filterNot { (name, _) -> result.contains(" $name()") }
            .joinToString("\n\n") { (name, type) ->
                "\t\tpublic $type $name() {\n\t\t\treturn this.decoration.$name();\n\t\t}"
            }
        val legacyAccessors = listOf(
            "getX" to "x",
            "getY" to "y",
            "getRot" to "rot"
        ).filterNot { (method, _) ->
            Regex("""(?m)\b(?:public|protected|private)\s+[\w.<>\[\]?]+\s+${Regex.escape(method)}\s*\(""")
                .containsMatchIn(result)
        }
            .joinToString("\n\n") { (method, accessor) ->
                "\t\tpublic byte $method() {\n\t\t\treturn this.decoration.$accessor();\n\t\t}"
            }
        val decorationAccessor = if (result.contains(" asMapDecoration()")) {
            ""
        } else {
            "\t\tpublic MapDecoration asMapDecoration() {\n\t\t\treturn this.decoration;\n\t\t}"
        }
        val legacyGetters = legacyFieldAccessors.joinToString("\n\n") { (type, name) ->
            "\t\tpublic $type ${name}() {\n\t\t\treturn this.$name;\n\t\t}"
        }
        val extras = listOf(existing, legacyAccessors, decorationAccessor, legacyGetters)
            .filter { it.isNotBlank() }
            .joinToString("\n\n")
        if (extras.isNotBlank()) {
            result = result.trimEnd() + "\n\n" + extras + "\n"
        }
        return result
    }

    private fun migrateLegacyMeleeAttackGoalOverrides(source: String): String {
        if (!source.contains("checkAndPerformAttack")) {
            return source
        }
        var result = source
        var cursor = 0
        val signaturePattern = Regex(
            """(?m)((?:[ \t]*@\w+(?:\([^)]*\))?\s*)*[ \t]*protected\s+void\s+checkAndPerformAttack\s*\(\s*((?:net\.minecraft\.world\.entity\.)?LivingEntity)\s+([A-Za-z_$][\w$]*)\s*,\s*double\s+([A-Za-z_$][\w$]*)\s*\)\s*\{)"""
        )
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            if (openBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val entityType = match.groupValues[2]
            val targetName = match.groupValues[3]
            val distanceName = match.groupValues[4]
            val body = result.substring(openBrace + 1, closeBrace)
            val reachVars = Regex(
                """\b(?:double|float)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:this\.)?getAttackReachSqr\s*\(\s*${Regex.escape(targetName)}\s*\)\s*;"""
            ).findAll(body).map { it.groupValues[1] }.toSet()

            var migratedBody = body
            migratedBody = Regex(
                """super\.checkAndPerformAttack\s*\(\s*${Regex.escape(targetName)}\s*,\s*${Regex.escape(distanceName)}\s*\)"""
            ).replace(migratedBody, "super.checkAndPerformAttack($targetName)")
            migratedBody = Regex(
                """super\.checkAndPerformAttack\s*\(\s*${Regex.escape(targetName)}\s*,\s*(?:[^()]|\([^()]*\))*\)"""
            ).replace(migratedBody, "super.checkAndPerformAttack($targetName)")
            reachVars.forEach { reachVar ->
                migratedBody = Regex(
                    """(?m)^[ \t]*(?:double|float)\s+${Regex.escape(reachVar)}\s*=\s*(?:this\.)?getAttackReachSqr\s*\(\s*${Regex.escape(targetName)}\s*\)\s*;\s*\r?\n"""
                ).replace(migratedBody, "")
                migratedBody = Regex("""\b${Regex.escape(distanceName)}\s*<=\s*${Regex.escape(reachVar)}\b""")
                    .replace(migratedBody, "this.canPerformAttack($targetName)")
                migratedBody = Regex("""\b${Regex.escape(reachVar)}\s*>=\s*${Regex.escape(distanceName)}\b""")
                    .replace(migratedBody, "this.canPerformAttack($targetName)")
            }
            migratedBody = Regex(
                """\b${Regex.escape(distanceName)}\s*<=\s*(?:this\.)?getAttackReachSqr\s*\(\s*${Regex.escape(targetName)}\s*\)"""
            ).replace(migratedBody, "this.canPerformAttack($targetName)")
            migratedBody = Regex(
                """(?:this\.)?getAttackReachSqr\s*\(\s*${Regex.escape(targetName)}\s*\)\s*>=\s*${Regex.escape(distanceName)}\b"""
            ).replace(migratedBody, "this.canPerformAttack($targetName)")
            migratedBody = Regex("""\b${Regex.escape(distanceName)}\b""")
                .replace(migratedBody, "this.mob.distanceToSqr($targetName)")

            val migratedSignature = match.value.replace(
                Regex("""checkAndPerformAttack\s*\(\s*${Regex.escape(entityType)}\s+${Regex.escape(targetName)}\s*,\s*double\s+${Regex.escape(distanceName)}\s*\)"""),
                "checkAndPerformAttack($entityType $targetName)"
            )
            result = result.substring(0, match.range.first) +
                migratedSignature +
                migratedBody +
                result.substring(closeBrace)
            cursor = match.range.first + migratedSignature.length + migratedBody.length + 1
        }
        return result
    }

    private fun migrateCustomGoalAttackReach(source: String): String {
        if (!source.contains("getAttackReachSqr")) return source
        var result = if (source.contains("MeleeAttackGoal")) {
            migrateMeleeAttackGoalReachOverrides(source)
        } else {
            source
        }

        if (result.contains("extends Goal") && result.contains("getAttackReachSqr")) {
            result = Regex(
                """this\.getAttackReachSqr\s*\(\s*([A-Za-z_$][\w$]*)\s*\)\s*>=\s*this\.mob\.distanceToSqr\s*\(\s*\1\.getX\(\)\s*,\s*\1\.getY\(\)\s*,\s*\1\.getZ\(\)\s*\)"""
            ).replace(result) { match -> "this.mob.isWithinMeleeAttackRange(${match.groupValues[1]})" }
            result = Regex(
                """(?m)^[ \t]*double\s+([A-Za-z_$][\w$]*)\s*=\s*this\.mob\.getPerceivedTargetDistanceSquareForMeleeAttack\s*\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;\s*\r?\n[ \t]*this\.checkAndPerformAttack\s*\(\s*\2\s*,\s*\1\s*\)\s*;"""
            ).replace(result) { match -> "			this.checkAndPerformAttack(${match.groupValues[2]});" }
            result = Regex("""this\.canPerformAttack\s*\(\s*([A-Za-z_$][\w$]*)\s*\)""")
                .replace(result) { match ->
                    val target = match.groupValues[1]
                    "this.attackTick <= 0 && this.mob.isWithinMeleeAttackRange($target) && this.mob.hasLineOfSight($target)"
                }
            result = removeMethodByName(result, "getAttackReachSqr")
        }

        return result
    }

    private fun migrateAttributeHolderApiArguments(
        source: String,
        attributeHolderAccessHints: AttributeHolderAccessHints
    ): String {
        if (attributeHolderAccessHints.qualifiedFields.isEmpty() || !source.contains(".get()")) return source
        val expressions = linkedSetOf<String>()
        expressions += attributeHolderAccessHints.qualifiedFields
        declaredAttributeHolderFieldNames(source).forEach { expressions += it }
        Regex("""(?m)^\s*import\s+static\s+([^;\s]+)\s*;""")
            .findAll(source)
            .map { it.groupValues[1].trim() }
            .filter { it in attributeHolderAccessHints.qualifiedFields }
            .forEach { expressions += it.substringAfterLast('.') }
        if (expressions.isEmpty()) return source
        val expressionPattern = expressions
            .sortedByDescending { it.length }
            .joinToString("|") { Regex.escape(it) }
        var result = source
        result = Regex("""(\.(?:getAttribute|getAttributeValue|hasAttribute)\(\s*)($expressionPattern)\.get\(\)(\s*\))""")
            .replace(result) { match ->
                "${match.groupValues[1]}${match.groupValues[2]}.getDelegate()${match.groupValues[3]}"
            }
        result = Regex("""(\.add\(\s*)($expressionPattern)\.get\(\)(\s*,)""")
            .replace(result) { match ->
                "${match.groupValues[1]}${match.groupValues[2]}.getDelegate()${match.groupValues[3]}"
        }
        return result
    }

    private fun migrateLegacyServerDataConstructors(source: String): String {
        if (!source.contains("new ServerData(")) return source
        return migrateMethodCalls(source, "new ServerData") { args ->
            if (args.size != 3) return@migrateMethodCalls args
            val serverType = when (args[2].trim()) {
                "true" -> "ServerData.Type.LAN"
                "false" -> "ServerData.Type.OTHER"
                else -> return@migrateMethodCalls args
            }
            listOf(args[0], args[1], serverType)
        }
    }

    private fun migrateLegacyConnectScreenStartConnectingCalls(source: String): String {
        if (!source.contains("ConnectScreen.startConnecting(")) return source
        return migrateMethodCalls(source, "ConnectScreen.startConnecting") { args ->
            if (args.size == 5) args + "null" else args
        }
    }

    private fun migrateLegacyBindingCurseChecks(source: String): String {
        val token = "EnchantmentHelper.hasBindingCurse"
        if (!source.contains(token)) return source
        val migrated = StringBuilder()
        var cursor = 0
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + token.length
            if (openParen >= source.length || source[openParen] != '(') {
                migrated.append(source, cursor, openParen)
                cursor = openParen
                continue
            }
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size != 1) {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }
            migrated.append(source, cursor, tokenIndex)
            migrated.append("EnchantmentHelper.has(${args[0].trim()}, EnchantmentEffectComponents.PREVENT_ARMOR_CHANGE)")
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateRecipeBookGhostRecipeSource(source: String): String {
        if (!source.contains("setupGhostRecipe") || !source.contains("Recipe<?>")) return source
        val id = """[A-Za-z_$][\w$]*"""
        val signaturePattern = Regex(
            """public\s+void\s+setupGhostRecipe\s*\(\s*Recipe\s*<\s*\?\s*>\s+($id)\s*,\s*List\s*<\s*Slot\s*>\s+($id)\s*\)"""
        )
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        while (cursor < source.length) {
            val match = signaturePattern.find(source, cursor) ?: break
            val openBrace = source.indexOf('{', match.range.last)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                migrated.append(source, cursor, match.range.last + 1)
                cursor = match.range.last + 1
                continue
            }
            val recipeVar = match.groupValues[1]
            migrated.append(source, cursor, match.range.first)
            migrated.append(match.value.replace(Regex("""Recipe\s*<\s*\?\s*>"""), "RecipeHolder<?>"))
            migrated.append(source, match.range.last + 1, openBrace + 1)
            val body = source.substring(openBrace + 1, closeBrace)
                .replace(Regex("""\b${Regex.escape(recipeVar)}\.getIngredients\(\)"""), "$recipeVar.value().getIngredients()")
            migrated.append(body)
            migrated.append("}")
            cursor = closeBrace + 1
            changed = true
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        var result = migrated.toString()
        result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        val withoutRecipeImport = removeImport(result, "net.minecraft.world.item.crafting.Recipe")
        result = if (hasSimpleTypeReference(withoutRecipeImport, "Recipe")) result else withoutRecipeImport
        return result
    }

    private fun migrateMeleeAttackGoalReachOverrides(source: String): String {
        if (!source.contains("extends") && !source.contains("new MeleeAttackGoal")) return source
        var result = source
        var cursor = 0
        val signaturePattern = Regex(
            """(?m)((?:[ \t]*@\w+(?:\([^)]*\))?\s*)*[ \t]*protected\s+double\s+getAttackReachSqr\s*\(\s*((?:net\.minecraft\.world\.entity\.)?LivingEntity)\s+([A-Za-z_$][\w$]*)\s*\)\s*\{)"""
        )
        while (true) {
            val match = signaturePattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', match.range.first)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val contextStart = (match.range.first - 700).coerceAtLeast(0)
            val nearbyContext = result.substring(contextStart, match.range.first)
            val isMeleeContext = nearbyContext.contains("new MeleeAttackGoal") ||
                Regex("""extends\s+MeleeAttackGoal\b""").containsMatchIn(nearbyContext)
            if (!isMeleeContext) {
                cursor = closeBrace + 1
                continue
            }
            val targetName = match.groupValues[3]
            val body = result.substring(openBrace + 1, closeBrace)
            val returnMatch = Regex("""return\s+(.+?);""", RegexOption.DOT_MATCHES_ALL).find(body)
            if (returnMatch == null) {
                cursor = closeBrace + 1
                continue
            }
            val returnExpr = returnMatch.groupValues[1].trim()
            val migratedReach = returnExpr.replace(
                Regex("""super\.getAttackReachSqr\s*\(\s*${Regex.escape(targetName)}\s*\)"""),
                "this.mob.getBbWidth() * 2.0F * this.mob.getBbWidth() * 2.0F + $targetName.getBbWidth()"
            )
            val distance = "this.mob.distanceToSqr($targetName.getX(), $targetName.getY(), $targetName.getZ())"
            val condition = "($migratedReach) >= $distance"
            val replacement = """
protected boolean canPerformAttack(${match.groupValues[2]} $targetName) {
		return this.isTimeToAttack() && ($condition) && this.mob.getSensing().hasLineOfSight($targetName);
	}
            """.trimIndent()
            result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = match.range.first + replacement.length
        }
        return result
    }

    private fun migrateLegacyDataAndComponentAccess(source: String): String {
        var result = source
        var needsDataComponents = false
        var needsItemTags = false
        var needsAttributes = false
        var needsPlayer = false
        var needsCollisionContext = false
        var needsLevelReader = false

        if (result.contains("ItemPredicate")) {
            Regex("""\bItemPredicate\s+([A-Za-z_$][\w$]*)\b""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
                .forEach { variable ->
                    result = Regex("""\b${Regex.escape(variable)}\.matches\(""")
                        .replace(result, "$variable.test(")
                }
            result = Regex("""(\b[A-Za-z_$][\w$]*\.get\(\))\.matches\(""")
                .replace(result, "$1.test(")
            result = Regex("""(\bthis\.[A-Za-z_$][\w$]*\.get\(\))\.matches\(""")
                .replace(result, "$1.test(")
        }
        if (result.contains("GameEvent.ENTITY_ROAR")) {
            result = result.replace("GameEvent.ENTITY_ROAR", "GameEvent.ENTITY_ACTION")
        }
        result = migrateBuiltInRegistryDelegateMapAccess(result)
        if (result.contains("Container")) {
            val containerVariables = Regex("""(?m)^[ \t]*(?:(?:public|protected|private|static|final|transient|volatile)\s+)*(?:(?:@\w+(?:\([^)]*\))?)\s+)*(?:net\.minecraft\.world\.)?Container\s+([A-Za-z_$][\w$]*)\s*(?:[=;,)]|$)""")
                .findAll(result)
                .map { it.groupValues[1] }
                .toSet()
            containerVariables.forEach { variable ->
                result = Regex("""\b${Regex.escape(variable)}\.size\(\)""")
                    .replace(result, "$variable.getContainerSize()")
            }
            result = migrateContainerSizeCallsForDeclaredContainerScopes(result)
        }
        if (result.contains("new ClipContext(")) {
            val clipBefore = result
            result = migrateMethodCalls(result, "new ClipContext") { args ->
                if (args.size == 5 && args[4].trim() == "null") {
                    needsCollisionContext = true
                    args.take(4) + "CollisionContext.empty()"
                } else {
                    args
                }
            }
            if (result == clipBefore) {
                needsCollisionContext = false
            }
        }
        if (result.contains("getCloneItemStack") && result.contains("BlockGetter")) {
            val before = result
            result = Regex(
                """getCloneItemStack\s*\(\s*BlockState\s+([A-Za-z_$][\w$]*)\s*,\s*HitResult\s+([A-Za-z_$][\w$]*)\s*,\s*BlockGetter\s+([A-Za-z_$][\w$]*)\s*,\s*BlockPos\s+([A-Za-z_$][\w$]*)\s*,\s*Player\s+([A-Za-z_$][\w$]*)\s*\)"""
            ).replace(result) { match ->
                "getCloneItemStack(BlockState ${match.groupValues[1]}, HitResult ${match.groupValues[2]}, LevelReader ${match.groupValues[3]}, BlockPos ${match.groupValues[4]}, Player ${match.groupValues[5]})"
            }
            if (result != before) {
                needsLevelReader = true
            }
        }
        if (result.contains(".hasCustomHoverName()")) {
            result = result.replace(".hasCustomHoverName()", ".has(DataComponents.CUSTOM_NAME)")
            needsDataComponents = true
        }
        result = result.replace(".getBiome(pos).get().", ".getBiome(pos).value().")
        result = Regex("""\.getBiome\(([^)]+)\)\.get\(\)\.""")
            .replace(result) { match -> ".getBiome(${match.groupValues[1].trim()}).value()." }
        if (result.contains("Tags.Items.HEADS")) {
            result = result.replace("Tags.Items.HEADS", "ItemTags.SKULLS")
            needsItemTags = true
        }
        if ((result.contains("NeoForgeMod.BLOCK_REACH.get()") || result.contains("NeoForgeMod.ENTITY_REACH.get()")) &&
            !(result.contains("getDefaultAttributeModifiers(EquipmentSlot") && result.contains("ImmutableMultimap"))) {
            result = result
                .replace("NeoForgeMod.BLOCK_REACH.get()", "Attributes.BLOCK_INTERACTION_RANGE")
                .replace("NeoForgeMod.ENTITY_REACH.get()", "Attributes.ENTITY_INTERACTION_RANGE")
            needsAttributes = true
            val withoutNeoForgeMod = removeImport(result, "net.neoforged.neoforge.common.NeoForgeMod")
            if (!Regex("""\bNeoForgeMod\b""").containsMatchIn(withoutNeoForgeMod)) {
                result = withoutNeoForgeMod
            }
        }
        if (result.contains("NeoForgeMod.ENTITY_GRAVITY.get()") ||
            result.contains("net.neoforged.neoforge.common.NeoForgeMod.ENTITY_GRAVITY.get()")) {
            result = result
                .replace("net.neoforged.neoforge.common.NeoForgeMod.ENTITY_GRAVITY.get()", "Attributes.GRAVITY")
                .replace("NeoForgeMod.ENTITY_GRAVITY.get()", "Attributes.GRAVITY")
            needsAttributes = true
            val withoutNeoForgeMod = removeImport(result, "net.neoforged.neoforge.common.NeoForgeMod")
            if (!Regex("""\bNeoForgeMod\b""").containsMatchIn(withoutNeoForgeMod)) {
                result = withoutNeoForgeMod
            }
        }
        if (result.contains("NeoForgeMod.STEP_HEIGHT_ADDITION.get()") ||
            result.contains("net.neoforged.neoforge.common.NeoForgeMod.STEP_HEIGHT_ADDITION.get()")) {
            result = result
                .replace("net.neoforged.neoforge.common.NeoForgeMod.STEP_HEIGHT_ADDITION.get()", "Attributes.STEP_HEIGHT")
                .replace("NeoForgeMod.STEP_HEIGHT_ADDITION.get()", "Attributes.STEP_HEIGHT")
            needsAttributes = true
            val withoutNeoForgeMod = removeImport(result, "net.neoforged.neoforge.common.NeoForgeMod")
            if (!Regex("""\bNeoForgeMod\b""").containsMatchIn(withoutNeoForgeMod)) {
                result = withoutNeoForgeMod
            }
        }
        result = migrateAabbBlockPosPairConstructors(result)
        if (result.contains("BucketPickup") || result.contains("LiquidBlockContainer") || result.contains("pickupBlock(") || result.contains("canPlaceLiquid(")) {
            val beforeLiquidInterfaces = result
            result = Regex(
                """pickupBlock\s*\(\s*LevelAccessor\s+([A-Za-z_$][\w$]*)\s*,\s*BlockPos\s+([A-Za-z_$][\w$]*)\s*,\s*BlockState\s+([A-Za-z_$][\w$]*)\s*\)"""
            ).replace(result) { match ->
                needsPlayer = true
                "pickupBlock(Player player, LevelAccessor ${match.groupValues[1]}, BlockPos ${match.groupValues[2]}, BlockState ${match.groupValues[3]})"
            }
            result = Regex(
                """canPlaceLiquid\s*\(\s*BlockGetter\s+([A-Za-z_$][\w$]*)\s*,\s*BlockPos\s+([A-Za-z_$][\w$]*)\s*,\s*BlockState\s+([A-Za-z_$][\w$]*)\s*,\s*Fluid\s+([A-Za-z_$][\w$]*)\s*\)"""
            ).replace(result) { match ->
                needsPlayer = true
                "canPlaceLiquid(Player player, BlockGetter ${match.groupValues[1]}, BlockPos ${match.groupValues[2]}, BlockState ${match.groupValues[3]}, Fluid ${match.groupValues[4]})"
            }
            if (result != beforeLiquidInterfaces) {
                result = Regex("""super\.pickupBlock\(\s*([^,\r\n]+)\s*,\s*([^,\r\n]+)\s*,\s*([^)]+)\)""")
                    .replace(result) { match ->
                        "super.pickupBlock(player, ${match.groupValues[1].trim()}, ${match.groupValues[2].trim()}, ${match.groupValues[3].trim()})"
                    }
            }
            result = migrateLegacyBucketPickupCallSites(result)
        }

        if (needsDataComponents) result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        if (needsItemTags) result = addImportIfMissing(result, "net.minecraft.tags.ItemTags")
        if (needsAttributes) result = addImportIfMissing(result, "net.minecraft.world.entity.ai.attributes.Attributes")
        if (needsPlayer) result = addImportIfMissing(result, "net.minecraft.world.entity.player.Player")
        if (needsCollisionContext) result = addImportIfMissing(result, "net.minecraft.world.phys.shapes.CollisionContext")
        if (needsLevelReader) result = addImportIfMissing(result, "net.minecraft.world.level.LevelReader")
        return result
    }

    private fun migrateBuiltInRegistryDelegateMapAccess(source: String): String {
        if (!source.contains("Holder.Reference<") && !source.contains("getDelegateOrThrow(")) return source
        var result = source

        if (result.contains("@Accessor(\"blockColors\")") && result.contains("BlockColors.class")) {
            result = Regex("""Map\s*<\s*Holder\.Reference\s*<\s*Block\s*>\s*,\s*BlockColor\s*>""")
                .replace(result, "Map<Block, BlockColor>")
        }

        val registryBySimpleType = mapOf(
            "Block" to "BLOCK",
            "Item" to "ITEM",
            "Fluid" to "FLUID",
            "MobEffect" to "MOB_EFFECT",
            "SoundEvent" to "SOUND_EVENT",
            "EntityType" to "ENTITY_TYPE"
        )
        val delegateMapVariables = mutableMapOf<String, String>()
        val mapDeclaration = Regex(
            """Map\s*<\s*Holder\.Reference\s*<\s*([A-Za-z_$][\w$.]*)\s*>\s*,\s*([^>\r\n;=]+?)\s*>\s+([A-Za-z_$][\w$]*)\s*="""
        )
        result = mapDeclaration.replace(result) { match ->
            val typeName = match.groupValues[1].trim()
            val simpleType = typeName.substringAfterLast('.')
            val registryName = registryBySimpleType[simpleType] ?: return@replace match.value
            val variable = match.groupValues[3]
            val delegatesIntoMap = Regex(
                """\b${Regex.escape(variable)}\.get\s*\(\s*BuiltInRegistries\.${Regex.escape(registryName)}\.getDelegateOrThrow\s*\("""
            ).containsMatchIn(result)
            if (!delegatesIntoMap) return@replace match.value
            delegateMapVariables[variable] = registryName
            "Map<$typeName, ${match.groupValues[2].trim()}> $variable ="
        }

        for ((variable, registryName) in delegateMapVariables) {
            result = migrateMethodCalls(result, "$variable.get") { args ->
                if (args.size != 1) return@migrateMethodCalls args
                val arg = args.single().trim()
                val token = "BuiltInRegistries.$registryName.getDelegateOrThrow"
                if (!arg.startsWith("$token(")) return@migrateMethodCalls args
                val openParen = arg.indexOf('(', token.length)
                val closeParen = if (openParen >= 0) findMatchingParen(arg, openParen) else -1
                if (openParen < 0 || closeParen != arg.length - 1) return@migrateMethodCalls args
                listOf(arg.substring(openParen + 1, closeParen).trim())
            }
        }

        val withoutHolderImport = removeImport(result, "net.minecraft.core.Holder")
        if (!Regex("""(?<![\w$])Holder(?![\w$])""").containsMatchIn(withoutHolderImport)) {
            result = withoutHolderImport
        }
        val withoutBuiltInRegistriesImport = removeImport(result, "net.minecraft.core.registries.BuiltInRegistries")
        if (!Regex("""(?<![\w$])BuiltInRegistries(?![\w$])""").containsMatchIn(withoutBuiltInRegistriesImport)) {
            result = withoutBuiltInRegistriesImport
        }
        return result
    }

    private fun migrateLegacyBucketPickupCallSites(source: String): String {
        if (!source.contains("BucketPickup") || !source.contains(".pickupBlock(")) return source
        var result = source
        var cursor = 0
        val instanceofPattern = Regex("""\binstanceof\s+BucketPickup\s+([A-Za-z_$][\w$]*)\b""")
        while (true) {
            val match = instanceofPattern.find(result, cursor) ?: break
            val receiver = match.groupValues[1]
            val openBrace = result.indexOf('{', match.range.last + 1)
            if (openBrace < 0) {
                cursor = match.range.last + 1
                continue
            }
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val playerArgument = bucketPickupPlayerArgumentForEnclosingMethod(result, match.range.first)
            val migratedBody = migrateLegacyBucketPickupCallsForReceiver(body, receiver, playerArgument)
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }

        cursor = 0
        val parameterPattern = Regex(
            """\b(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^;{}()]*\b(?:net\.minecraft\.world\.level\.block\.)?BucketPickup\s+([A-Za-z_$][\w$]*)[^;{}()]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        while (true) {
            val match = parameterPattern.find(result, cursor) ?: break
            val receiver = match.groupValues[1]
            val openBrace = match.range.last
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val playerArgument = bucketPickupPlayerArgumentForEnclosingMethod(result, match.range.first)
            val migratedBody = migrateLegacyBucketPickupCallsForReceiver(body, receiver, playerArgument)
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }

        cursor = 0
        val methodPattern = Regex(
            """\b(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^;{}()]*\)\s*(?:throws\s+[^{]+)?\{"""
        )
        while (true) {
            val match = methodPattern.find(result, cursor) ?: break
            val openBrace = match.range.last
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace <= openBrace) {
                cursor = match.range.last + 1
                continue
            }
            val body = result.substring(openBrace + 1, closeBrace)
            val playerArgument = bucketPickupPlayerArgumentForEnclosingMethod(result, match.range.first)
            val migratedBody = migrateLegacyBucketPickupLocalDeclarationBody(body, playerArgument)
            if (migratedBody != body) {
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                cursor = openBrace + 1 + migratedBody.length
            } else {
                cursor = closeBrace + 1
            }
        }
        return result
    }

    private fun bucketPickupPlayerArgumentForEnclosingMethod(source: String, offset: Int): String {
        val methodPattern = Regex(
            """\b(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\(([^;{}()]*)\)\s*(?:throws\s+[^{]+)?\{"""
        )
        val method = methodPattern.findAll(source.substring(0, offset)).lastOrNull() ?: return "null"
        val openBrace = method.range.last
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace <= offset) return "null"
        return singlePlayerParameterName(method.groupValues[1]) ?: "null"
    }

    private fun singlePlayerParameterName(parameters: String): String? {
        val playerType = Regex(
            """(?:^|[\s<,])(?:final\s+)?(?:(?:net\.minecraft\.world\.entity\.player\.)?Player|(?:net\.minecraft\.server\.level\.)?ServerPlayer)\s+([A-Za-z_$][\w$]*)\b"""
        )
        val playerParameters = splitTopLevelJavaArgs(parameters)
            .mapNotNull { parameter -> playerType.find(parameter)?.groupValues?.get(1) }
            .distinct()
        return playerParameters.singleOrNull()
    }

    private fun migrateLegacyBucketPickupLocalDeclarationBody(body: String, playerArgument: String): String {
        var result = body
        val declarations = Regex("""(?m)^[ \t]*(?:final\s+)?(?:net\.minecraft\.world\.level\.block\.)?BucketPickup\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(body)
            .toList()
            .asReversed()
        for (declaration in declarations) {
            val receiver = declaration.groupValues[1]
            val suffixStart = declaration.range.last + 1
            val suffix = result.substring(suffixStart)
            val migratedSuffix = migrateLegacyBucketPickupCallsForReceiver(suffix, receiver, playerArgument)
            if (migratedSuffix != suffix) {
                result = result.substring(0, suffixStart) + migratedSuffix
            }
        }
        return result
    }

    private fun migrateLegacyBucketPickupCallsForReceiver(source: String, receiver: String, playerArgument: String): String {
        val token = "$receiver.pickupBlock"
        val migrated = StringBuilder()
        var cursor = 0
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + token.length
            if (openParen >= source.length || source[openParen] != '(') {
                migrated.append(source, cursor, openParen)
                cursor = openParen
                continue
            }
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val migratedArgs = if (args.size == 3) listOf(playerArgument) + args else args
            migrated.append(source, cursor, openParen + 1)
            migrated.append(migratedArgs.joinToString(", ") { it.trim() })
            migrated.append(")")
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateLegacyHolderSoundEventPlaySoundArguments(source: String): String {
        if (!source.contains(".playSound(") || !source.contains("SoundEvents.")) return source
        return migrateMethodCalls(source, ".playSound") { args ->
            val migratedArgs = args.toMutableList()
            val candidateSoundIndices = when (args.size) {
                3 -> listOf(0)
                4 -> listOf(2)
                6 -> listOf(2, 4)
                8 -> listOf(4)
                else -> emptyList()
            }
            for (index in candidateSoundIndices) {
                if (index !in migratedArgs.indices) continue
                migratedArgs[index] = unwrapVanillaHolderSoundEventArgument(migratedArgs[index])
            }
            migratedArgs
        }
    }

    private fun unwrapVanillaHolderSoundEventArgument(argument: String): String {
        val trimmed = argument.trim()
        if (trimmed.endsWith(".value()")) return argument
        val sound = Regex("""^SoundEvents\.([A-Z0-9_]+)$""").find(trimmed)?.groupValues?.get(1) ?: return argument
        return if (isVanillaHolderSoundEvent(sound)) "${trimmed}.value()" else argument
    }

    private fun isVanillaHolderSoundEvent(name: String): Boolean =
        name == "AMBIENT_CAVE" ||
            name.startsWith("AMBIENT_BASALT_DELTAS_") ||
            name.startsWith("AMBIENT_CRIMSON_FOREST_") ||
            name.startsWith("AMBIENT_NETHER_WASTES_") ||
            name.startsWith("AMBIENT_SOUL_SAND_VALLEY_") ||
            name.startsWith("AMBIENT_WARPED_FOREST_") ||
            name.startsWith("ARMOR_EQUIP_") ||
            name == "BREEZE_WIND_CHARGE_BURST" ||
            name.startsWith("CROSSBOW_LOADING_") ||
            name.startsWith("CROSSBOW_QUICK_CHARGE_") ||
            name == "GENERIC_EXPLODE" ||
            name == "LLAMA_SWAG" ||
            name.startsWith("MUSIC_") ||
            name.startsWith("NOTE_BLOCK_") ||
            name == "RAID_HORN" ||
            name == "RESPAWN_ANCHOR_DEPLETE" ||
            name == "SOUL_ESCAPE" ||
            name.startsWith("TRIDENT_RIPTIDE_") ||
            name == "TRIDENT_THROW" ||
            name == "TRIDENT_THUNDER" ||
            name == "UI_BUTTON_CLICK" ||
            name == "WIND_CHARGE_BURST"

    private fun migrateCraftingInputSizeCallsForDeclaredScopes(source: String): String {
        if (!source.contains("CraftingInput") ||
            (!source.contains(".getContainerSize()") && !source.contains(".asCraftInput()"))) {
            return source
        }
        val id = """[A-Za-z_$][\w$]*"""
        val parameterPattern = Regex(
            """[(,]\s*(?:final\s+)?(?:(?:@\w+(?:\([^)]*\))?)\s+)*(?:net\.minecraft\.world\.item\.crafting\.)?CraftingInput\s+($id)\s*(?=[,)])"""
        )
        val fieldVariables = Regex(
            """(?m)^[ \t]*(?:(?:public|protected|private|static|final)\s+)*(?:net\.minecraft\.world\.item\.crafting\.)?CraftingInput\s+($id)\b"""
        ).findAll(source)
            .map { it.groupValues[1] }
            .toSet()

        var result = source
        for (field in fieldVariables) {
            val escaped = Regex.escape(field)
            result = Regex("""\bthis\.$escaped\.asCraftInput\(\)""").replace(result, "this.$field")
            result = Regex("""\bthis\.$escaped\.getContainerSize\(\)""").replace(result, "this.$field.size()")
        }

        var cursor = 0
        while (cursor < result.length) {
            val match = parameterPattern.find(result, cursor) ?: break
            val methodOpen = result.indexOf('{', match.range.last + 1)
            val nextSemicolon = result.indexOf(';', match.range.last + 1)
            if (methodOpen < 0 || (nextSemicolon >= 0 && nextSemicolon < methodOpen)) {
                cursor = match.range.last + 1
                continue
            }
            val methodClose = findMatchingBrace(result, methodOpen)
            if (methodClose <= methodOpen) {
                cursor = match.range.last + 1
                continue
            }
            val variable = match.groupValues[1]
            val escaped = Regex.escape(variable)
            val body = result.substring(methodOpen + 1, methodClose)
            val migratedBody = Regex("""\b((?:this\.)?$escaped)\.asCraftInput\(\)""")
                .replace(body) { scopedMatch -> scopedMatch.groupValues[1] }
                .let { scoped ->
                    Regex("""\b$escaped\.getContainerSize\(\)""").replace(scoped, "$variable.size()")
                }
            if (migratedBody != body) {
                result = result.substring(0, methodOpen + 1) + migratedBody + result.substring(methodClose)
                cursor = methodOpen + 1 + migratedBody.length
            } else {
                cursor = methodClose + 1
            }
        }

        return result
    }

    private fun migrateContainerSizeCallsForDeclaredContainerScopes(source: String): String {
        if (!source.contains("Container") || !source.contains(".size()")) return source
        val id = """[A-Za-z_$][\w$]*"""
        val parameterPattern = Regex("""[(,]\s*(?:final\s+)?(?:(?:@\w+(?:\([^)]*\))?)\s+)*(?:net\.minecraft\.world\.)?Container\s+($id)\s*(?=[,)])""")
        var result = source
        var cursor = 0
        while (cursor < result.length) {
            val match = parameterPattern.find(result, cursor) ?: break
            val methodOpen = result.indexOf('{', match.range.last + 1)
            val nextSemicolon = result.indexOf(';', match.range.last + 1)
            if (methodOpen < 0 || (nextSemicolon >= 0 && nextSemicolon < methodOpen)) {
                cursor = match.range.last + 1
                continue
            }
            val methodClose = findMatchingBrace(result, methodOpen)
            if (methodClose <= methodOpen) {
                cursor = match.range.last + 1
                continue
            }
            val variable = match.groupValues[1]
            val body = result.substring(methodOpen + 1, methodClose)
            val migratedBody = Regex("""\b${Regex.escape(variable)}\.size\(\)""")
                .replace(body, "$variable.getContainerSize()")
            if (migratedBody != body) {
                result = result.substring(0, methodOpen + 1) + migratedBody + result.substring(methodClose)
                cursor = methodOpen + 1 + migratedBody.length
            } else {
                cursor = methodClose + 1
            }
        }
        return result
    }

    private fun migrateDeclaredCollectionGetSizeCalls(source: String): String {
        if (!source.contains(".getSize()")) return source
        val id = """[A-Za-z_$][\w$]*"""
        val collectionType = """
            (?:
                (?:java\.util\.)?(?:Collection|Iterable|List|Map|Queue|Deque|Set|SortedMap|SortedSet|NavigableMap|NavigableSet)|
                (?:com\.google\.common\.collect\.)?(?:ImmutableList|ImmutableMap|ImmutableSet|ImmutableCollection|Multimap)|
                (?:it\.unimi\.dsi\.fastutil\.[A-Za-z0-9_.]+\.)?[A-Za-z0-9_]+(?:2[A-Za-z0-9_]+)?(?:Map|List|Set|Collection)
            )
        """.trimIndent().replace(Regex("""\s+"""), "")
        val declaredCollections = Regex(
            """\b(?:public|protected|private|static|final|transient|volatile|\s)*($collectionType)(?:\s*<[^;=(){}]*?>+)?\s+($id)\b(?=\s*(?:=|;|,|\)))"""
        ).findAll(source).map { it.groupValues[2] }.toSet()
        if (declaredCollections.isEmpty()) return source

        var result = source
        for (variable in declaredCollections) {
            val escaped = Regex.escape(variable)
            result = Regex("""\bthis\.$escaped\.getSize\(\)""").replace(result, "this.$variable.size()")
            result = Regex("""(?<!\.)\b$escaped\.getSize\(\)""").replace(result, "$variable.size()")
        }
        return result
    }

    private fun migrateDeclaredCollectionGetSizeCalls(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val changes = mutableListOf<Change>()
        Files.walk(srcDir)
            .filter { it.extension == "java" }
            .forEach { javaFile ->
                val original = javaFile.readText()
                val migrated = migrateDeclaredCollectionGetSizeCalls(original)
                if (migrated != original) {
                    changes.add(Change(
                        file = javaFile,
                        line = 0,
                        description = "Migrate declared Java collection getSize() calls to size()",
                        before = "Map/List/Set variable .getSize()",
                        after = "Map/List/Set variable .size()",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-collection-getsize"
                    ))
                    if (!dryRun) {
                        javaFile.writeText(migrated)
                    }
                }
            }
        return changes
    }

    private fun migrateAabbBlockPosPairConstructors(source: String): String {
        if (!source.contains("new AABB(")) return source
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        val token = "new AABB("
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + "new AABB".length
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size == 2 &&
                args.none { Regex("""^\s*[-+]?\d""").containsMatchIn(it) || it.contains("new Vec3") || it.contains("Vec3.") }) {
                migrated.append(source, cursor, tokenIndex)
                migrated.append("AABB.encapsulatingFullBlocks(${args[0].trim()}, ${args[1].trim()})")
                cursor = closeParen + 1
                changed = true
                continue
            }
            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateGlobalLootModifierCodecs(source: String): String {
        if (!source.contains("IGlobalLootModifier") && !source.contains("GLOBAL_LOOT_MODIFIER_SERIALIZERS")) {
            return source
        }
        var result = source
        result = Regex("""(?<!Map)Codec<\? extends IGlobalLootModifier>""")
            .replace(result, "MapCodec<? extends IGlobalLootModifier>")
        result = result.replace("MapCodec<? extends ChunkGenerator>", "MapCodec<? extends IGlobalLootModifier>")
        result = result.replace("MapMapCodec", "MapCodec")
        result = result.replace("public static final Codec<", "public static final MapCodec<")
        result = Regex("""RecordCodecBuilder(\s*\r?\n\s*)\.create\(""")
            .replace(result) { match -> "RecordCodecBuilder${match.groupValues[1]}.mapCodec(" }
        result = result.replace("RecordCodecBuilder.create(", "RecordCodecBuilder.mapCodec(")
        if (result.contains("MapCodec<")) {
            result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
            if (!Regex("""\bCodec\s*[<.]""").containsMatchIn(result)) {
                result = removeImport(result, "com.mojang.serialization.Codec")
            }
        }
        return result
    }

    private fun migrateBonemealableTargetCalls(source: String): String =
        migrateMethodCalls(source, ".isValidBonemealTarget") { args ->
            if (args.size == 4) args.take(3) else args
        }

    private fun migrateItemUseDurationCalls(source: String): String {
        if (!source.contains(".getUseDuration(")) return source
        var result = Regex("""\b([A-Za-z_$][\w$]*)\.getUseItem\(\)\.getUseDuration\(\s*\)""")
            .replace(source) { match ->
                val living = match.groupValues[1]
                "$living.getUseItem().getUseDuration($living)"
            }
        result = migrateMethodCalls(result, ".getUseDuration") { args ->
            when (args.size) {
                0 -> listOf("null")
                1 -> listOf(args[0], "null")
                else -> args
            }
        }
        val itemStackVariables = Regex("""\bItemStack\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        result = rewriteJavaCall(result, "getUseDuration") { receiver, args ->
            if (args.size != 2 || args[1].trim() != "null") return@rewriteJavaCall null
            val simpleReceiver = receiver.removePrefix("this.").trim()
            val isItemStackReceiver = simpleReceiver in itemStackVariables || receiver.endsWith(".getUseItem()")
            if (isItemStackReceiver) "$receiver.getUseDuration(${args[0].trim()})" else null
        }
        return result
    }

    private fun migrateArmorMaterialHolderFields(source: String): String {
        if (!source.contains("ArmorMaterial") || !source.contains(" material")) return source
        val declaresMaterialField = Regex(
            """(?m)^([ \t]*(?:public|protected|private)\s+(?:static\s+)?(?:final\s+)?)ArmorMaterial\s+material\s*;"""
        ).containsMatchIn(source)
        if (!declaresMaterialField) return source
        if (!source.contains("this.material.") &&
            !source.contains(" material.") &&
            !source.contains("getMaterial()")) {
            return source
        }

        var result = source
        result = Regex("""(?m)^([ \t]*(?:public|protected|private)\s+(?:static\s+)?(?:final\s+)?)ArmorMaterial\s+material\s*;""")
            .replace(result, "$1Holder<ArmorMaterial> material;")
        result = Regex("""\bArmorMaterial\s+material\b""")
            .replace(result, "Holder<ArmorMaterial> material")
        result = Regex("""\bpublic\s+ArmorMaterial\s+getMaterial\s*\(\s*\)""")
            .replace(result, "public Holder<ArmorMaterial> getMaterial()")

        result = result
            .replace(".material.getEnchantmentValue()", ".material.value().enchantmentValue()")
            .replace(".material.getRepairIngredient()", ".material.value().repairIngredient().get()")
            .replace(".material.getToughness()", ".material.value().toughness()")
            .replace(".material.getKnockbackResistance()", ".material.value().knockbackResistance()")
            .replace(".material.getEquipSound()", ".material.value().equipSound().value()")

        val materialVariables = Regex("""\bHolder\s*<\s*ArmorMaterial\s*>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in materialVariables) {
            val escaped = Regex.escape(variable)
            result = Regex("""\b$escaped\.getEnchantmentValue\(\)""").replace(result, "$variable.value().enchantmentValue()")
            result = Regex("""\b$escaped\.getRepairIngredient\(\)""").replace(result, "$variable.value().repairIngredient().get()")
            result = Regex("""\b$escaped\.getToughness\(\)""").replace(result, "$variable.value().toughness()")
            result = Regex("""\b$escaped\.getKnockbackResistance\(\)""").replace(result, "$variable.value().knockbackResistance()")
            result = Regex("""\b$escaped\.getEquipSound\(\)""").replace(result, "$variable.value().equipSound().value()")
        }

        return if (result != source) addImportIfMissing(result, "net.minecraft.core.Holder") else source
    }

    private fun migrateLegacyItemExtensionAndProjectileApis(source: String): String {
        if (!source.contains("canEquip(") &&
            !source.contains("customArrow(") &&
            !source.contains("getArmorTexture(") &&
            !source.contains("getRarity(") &&
            !source.contains("createArrow(") &&
            !source.contains("setKnockback(") &&
            !source.contains("getEquipmentSlotForItem(") &&
            !source.contains(".hurtAndBreak(") &&
            !source.contains("entityLiving")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var needsLivingEntity = false
        var needsItemStack = false
        var needsEquipmentSlot = false
        var needsArmorMaterial = false
        var needsResourceLocation = false
        var needsDataComponents = false

        result = Regex("""public\s+boolean\s+canEquip\(\s*ItemStack\s+($id)\s*,\s*EquipmentSlot\s+($id)\s*,\s*Entity\s+($id)\s*\)""")
            .replace(result) { match ->
                needsLivingEntity = true
                "public boolean canEquip(ItemStack ${match.groupValues[1]}, EquipmentSlot ${match.groupValues[2]}, LivingEntity ${match.groupValues[3]})"
            }

        result = Regex("""public\s+AbstractArrow\s+customArrow\s*\(\s*AbstractArrow\s+($id)\s*\)""")
            .replace(result) { match ->
                needsItemStack = true
                "public AbstractArrow customArrow(AbstractArrow ${match.groupValues[1]}, ItemStack projectileStack, ItemStack weaponStack)"
            }

        var legacyArmorLayerParameter: String? = null
        result = Regex(
            """public\s+String\s+getArmorTexture\s*\(\s*ItemStack\s+($id)\s*,\s*Entity\s+($id)\s*,\s*EquipmentSlot\s+($id)\s*,\s*(?:@\w+(?:\.\w+)*\s+)?String\s+($id)\s*\)"""
        ).replace(result) { match ->
            legacyArmorLayerParameter = match.groupValues[4]
            needsArmorMaterial = true
            needsResourceLocation = true
            "public ResourceLocation getArmorTexture(ItemStack ${match.groupValues[1]}, Entity ${match.groupValues[2]}, EquipmentSlot ${match.groupValues[3]}, ArmorMaterial.Layer ${match.groupValues[4]}, boolean innerModel)"
        }
        legacyArmorLayerParameter?.let { layerParameter ->
            result = Regex("""\b${Regex.escape(layerParameter)}\s*==\s*null\b""")
                .replace(result, "$layerParameter.dyeable()")
            result = Regex("""\b${Regex.escape(layerParameter)}\s*!=\s*null\b""")
                .replace(result, "!$layerParameter.dyeable()")
            val armorTextureMethod = javaDeclaredMethodText(result, "getArmorTexture")
            if (armorTextureMethod != null) {
                val replacement = Regex("""return\s+([^;\r\n]+);""").replace(armorTextureMethod) { match ->
                    val expression = match.groupValues[1].trim()
                    if (expression == "null" || expression.startsWith("ResourceLocation.")) {
                        match.value
                    } else {
                        "return ResourceLocation.parse($expression);"
                    }
                }
                result = result.replace(armorTextureMethod, replacement)
            }
            val withoutNullableImport = removeImport(result, "org.jetbrains.annotations.Nullable")
            if (!Regex("""@Nullable\b""").containsMatchIn(withoutNullableImport)) {
                result = withoutNullableImport
            }
        }

        val legacyRarity = Regex("""public\s+Rarity\s+getRarity\s*\(\s*ItemStack\s+($id)\s*\)""").find(result)
        if (legacyRarity != null && !result.contains("verifyComponentsAfterLoad(ItemStack")) {
            val stackParameter = legacyRarity.groupValues[1]
            needsDataComponents = true
            result = Regex("""(?m)^([ \t]*)@Override\s*\r?\n([ \t]*public\s+Rarity\s+getRarity\s*\()""")
                .replace(result, "$1$2")
            val getDefaultInstanceMethod = javaDeclaredMethodText(result, "getDefaultInstance")
            if (getDefaultInstanceMethod != null) {
                val stackLocal = Regex("""\bItemStack\s+($id)\s*=""").find(getDefaultInstanceMethod)?.groupValues?.get(1)
                if (stackLocal != null) {
                    val replacement = Regex("""(?m)^([ \t]*)return\s+${Regex.escape(stackLocal)}\s*;""")
                        .replace(getDefaultInstanceMethod) { match ->
                            "${match.groupValues[1]}$stackLocal.set(DataComponents.RARITY, this.getRarity($stackLocal));\n${match.value}"
                        }
                    result = result.replace(getDefaultInstanceMethod, replacement)
                }
            }
            val verifier = """

	@Override
	public void verifyComponentsAfterLoad(ItemStack $stackParameter) {
		super.verifyComponentsAfterLoad($stackParameter);
		$stackParameter.set(DataComponents.RARITY, this.getRarity($stackParameter));
	}
""".trimEnd()
            result = insertBeforeLastClassBrace(result, verifier)
        }

        val releaseUsing = Regex(
            """releaseUsing\s*\(\s*ItemStack\s+($id)\s*,\s*Level\s+($id)\s*,\s*LivingEntity\s+($id)\s*,\s*int\s+($id)\s*\)"""
        ).find(result)
        if (releaseUsing != null) {
            val weaponStack = releaseUsing.groupValues[1]
            val livingEntity = releaseUsing.groupValues[3]
            result = result.replace("getUseDuration($weaponStack, entityLiving)", "getUseDuration($weaponStack, $livingEntity)")
            result = rewriteJavaCall(result, "createArrow") { receiver, args ->
                if (args.size == 3 && Regex("""\bArrowItem\b""").containsMatchIn(result)) {
                    "$receiver.createArrow(${args[0].trim()}, ${args[1].trim()}, ${args[2].trim()}, $weaponStack)"
                } else {
                    null
                }
            }
            result = Regex("""(?m)^[ \t]*if\s*\(\s*([A-Za-z_$][\w$]*)\s*>\s*0\s*\)\s*[A-Za-z_$][\w$]*\.setKnockback\(\s*\1\s*\);\s*\r?\n""")
                .replace(result, "")
        }

        val equipmentSlotOwner = Regex("""\bPlayer\s+($id)\b""").find(result)?.groupValues?.get(1)
            ?: Regex("""\bLivingEntity\s+($id)\b""").find(result)?.groupValues?.get(1)
        if (equipmentSlotOwner != null) {
            result = Regex("""\bthis\.getEquipmentSlotForItem\(""")
                .replace(result, "$equipmentSlotOwner.getEquipmentSlotForItem(")
        }

        result = Regex(
            """(?s)if\s*\(\s*($id)\s+instanceof\s+Player\s+($id)\s*&&\s*!\2\.isCreative\(\)\s*\)\s*\{\s*($id)\.hurtAndBreak\(\s*([^,]+)\s*,\s*($id)\s*,\s*null\s*,\s*item\s*->\s*\{\s*}\s*\)\s*;\s*}"""
        ).replace(result) { match ->
            needsEquipmentSlot = true
            val player = match.groupValues[2]
            val stack = match.groupValues[3]
            val amount = match.groupValues[4].trim()
            "if (${match.groupValues[1]} instanceof Player $player && !$player.isCreative()) {\n\t\t\t\t\t\t\t$stack.hurtAndBreak($amount, $player, EquipmentSlot.MAINHAND);\n\t\t\t\t\t\t}"
        }

        if (needsLivingEntity) {
            result = addImportIfMissing(result, "net.minecraft.world.entity.LivingEntity")
            val withoutEntityImport = removeImport(result, "net.minecraft.world.entity.Entity")
            if (!Regex("""\bEntity\b""").containsMatchIn(withoutEntityImport)) {
                result = withoutEntityImport
            }
        }
        if (needsItemStack) {
            result = addImportIfMissing(result, "net.minecraft.world.item.ItemStack")
        }
        if (needsEquipmentSlot) {
            result = addImportIfMissing(result, "net.minecraft.world.entity.EquipmentSlot")
        }
        if (needsArmorMaterial) {
            result = addImportIfMissing(result, "net.minecraft.world.item.ArmorMaterial")
        }
        if (needsResourceLocation) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceLocation")
        }
        if (needsDataComponents) {
            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        }
        return result
    }

    private fun migrateLegacyTooltipContextAndEntityDataSource(source: String): String {
        if (!source.contains("TooltipContext") &&
            !source.contains("EntityType.updateCustomEntityTag(")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var needsLevel = false
        var needsCustomData = false

        val hoverText = javaDeclaredMethodText(result, "appendHoverText")
        if (hoverText != null) {
            val contextVariable = Regex("""\b(?:Item\.)?TooltipContext\s+($id)\b""")
                .find(hoverText)
                ?.groupValues
                ?.get(1)
            if (contextVariable != null &&
                (hoverText.contains("$contextVariable.registryAccess()") ||
                    hoverText.contains("$contextVariable.dimensionType()") ||
                    hoverText.contains("$contextVariable.getMoonPhase()"))) {
                val levelVariable = uniqueLocalName(hoverText, "tooltipLevel")
                var migratedMethod = hoverText
                migratedMethod = Regex("""\bif\s*\(\s*${Regex.escape(contextVariable)}\s*!=\s*null\s*\)""")
                    .replace(migratedMethod, "if ($levelVariable != null)")
                migratedMethod = Regex("""\b${Regex.escape(contextVariable)}\.registryAccess\(\)""")
                    .replace(migratedMethod, "$levelVariable.registryAccess()")
                migratedMethod = Regex("""\b${Regex.escape(contextVariable)}\s*!=\s*null\s*&&\s*${Regex.escape(contextVariable)}\.dimensionType\(\)""")
                    .replace(migratedMethod, "$levelVariable != null && $levelVariable.dimensionType()")
                migratedMethod = Regex("""\b${Regex.escape(contextVariable)}\.dimensionType\(\)""")
                    .replace(migratedMethod, "$levelVariable.dimensionType()")
                migratedMethod = Regex("""\b${Regex.escape(contextVariable)}\.getMoonPhase\(\)""")
                    .replace(migratedMethod, "$levelVariable.getMoonPhase()")

                val localLine = "Level $levelVariable = $contextVariable != null ? $contextVariable.level() : null;"
                if (!migratedMethod.contains(localLine)) {
                    val superCall = Regex("""(?m)^([ \t]*)super\.appendHoverText\([^;\r\n]*;\s*$""").find(migratedMethod)
                    migratedMethod = if (superCall != null) {
                        val insertAt = superCall.range.last + 1
                        val indent = superCall.groupValues[1]
                        migratedMethod.substring(0, insertAt) +
                            "\n${indent}$localLine" +
                            migratedMethod.substring(insertAt)
                    } else {
                        val openBrace = migratedMethod.indexOf('{')
                        if (openBrace >= 0) {
                            val nextLineIndent = Regex("""\r?\n([ \t]+)\S""")
                                .find(migratedMethod, openBrace)
                                ?.groupValues
                                ?.get(1)
                                ?: "\t\t"
                            migratedMethod.substring(0, openBrace + 1) +
                                "\n$nextLineIndent$localLine" +
                                migratedMethod.substring(openBrace + 1)
                        } else {
                            migratedMethod
                        }
                    }
                    needsLevel = true
                }
                result = result.replace(hoverText, migratedMethod)
            }
        }

        val compoundTagVariables = Regex("""\bCompoundTag\s+($id)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        result = rewriteJavaInvocationArguments(result, "EntityType.updateCustomEntityTag") { args ->
            if (args.size != 4) return@rewriteJavaInvocationArguments null
            val tagArg = args[3].trim()
            if (tagArg.startsWith("CustomData.") ||
                tagArg.startsWith("net.minecraft.world.item.component.CustomData.") ||
                tagArg !in compoundTagVariables) {
                return@rewriteJavaInvocationArguments null
            }
            needsCustomData = true
            args.take(3) + "CustomData.of($tagArg)"
        }

        if (needsLevel) {
            result = addImportIfMissing(result, "net.minecraft.world.level.Level")
        }
        if (needsCustomData) {
            result = addImportIfMissing(result, "net.minecraft.world.item.component.CustomData")
        }
        return result
    }

    private fun migrateMobEffectApplyEffectTickReturnSource(source: String): String {
        if (!source.contains("boolean applyEffectTick(")) return source
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\s*\r?\n[ \t]*)*public\s+boolean\s+applyEffectTick\s*\([^;{}]*\)\s*(?:throws\s+[^{;]+)?\{"""
        )
        val insertions = methodPattern.findAll(source)
            .mapNotNull { match ->
                val openBrace = source.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
                if (openBrace < 0 || closeBrace < 0) return@mapNotNull null
                val body = source.substring(openBrace + 1, closeBrace)
                if (!mobEffectBooleanMethodNeedsTrailingTrue(body)) return@mapNotNull null
                val lineStart = source.lastIndexOf('\n', match.range.first).let { if (it < 0) 0 else it + 1 }
                val indent = source.substring(lineStart, match.range.first).takeWhile { it == ' ' || it == '\t' }
                closeBrace to "\n${indent}\treturn true;"
            }
            .toList()
        if (insertions.isEmpty()) return source
        var result = source
        for ((index, text) in insertions.asReversed()) {
            result = result.substring(0, index) + text + result.substring(index)
        }
        return result
    }

    private fun mobEffectBooleanMethodNeedsTrailingTrue(body: String): Boolean {
        val trimmed = body.trimEnd()
        if (trimmed.isBlank()) return true
        if (Regex("""(?s)\b(?:return|throw)\b[^;]*;\s*$""").containsMatchIn(trimmed)) return false
        if (Regex("""(?s)\belse\s*(?:\{[^{}]*\}|\b(?:return|throw)\b[^;]*;)\s*$""").containsMatchIn(trimmed)) return false
        return true
    }

    private fun migrateLegacyNetworkBufferCodecsSource(source: String): String {
        if (!source.contains("readComponent()") &&
            !source.contains("writeComponent(") &&
            !source.contains("readItem()") &&
            !source.contains("writeItem(")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var needsComponentSerialization = false
        var needsRegistryFriendlyByteBuf = false

        result = Regex("""\b($id)\.readComponent\(\)""").replace(result) { match ->
            needsComponentSerialization = true
            needsRegistryFriendlyByteBuf = true
            "ComponentSerialization.STREAM_CODEC.decode(${match.groupValues[1]})"
        }
        result = rewriteJavaCall(result, "writeComponent") { receiver, args ->
            if (args.size != 1) {
                null
            } else {
                needsComponentSerialization = true
                needsRegistryFriendlyByteBuf = true
                "ComponentSerialization.STREAM_CODEC.encode($receiver, ${args[0].trim()})"
            }
        }
        result = Regex("""\b($id)\.readItem\(\)""").replace(result) { match ->
            needsRegistryFriendlyByteBuf = true
            "ItemStack.STREAM_CODEC.decode(${match.groupValues[1]})"
        }
        result = rewriteJavaCall(result, "writeItem") { receiver, args ->
            if (args.size != 1) {
                null
            } else {
                needsRegistryFriendlyByteBuf = true
                "ItemStack.STREAM_CODEC.encode($receiver, ${args[0].trim()})"
            }
        }

        if (needsRegistryFriendlyByteBuf) {
            result = result
                .replace("StreamCodec<FriendlyByteBuf,", "StreamCodec<RegistryFriendlyByteBuf,")
                .replace(Regex("""\bFriendlyByteBuf\s+($id)\b"""), "RegistryFriendlyByteBuf $1")
            result = addImportIfMissing(result, "net.minecraft.network.RegistryFriendlyByteBuf")
            val withoutFriendly = removeImport(result, "net.minecraft.network.FriendlyByteBuf")
            if (!Regex("""\bFriendlyByteBuf\b""").containsMatchIn(withoutFriendly)) {
                result = withoutFriendly
            }
        }
        if (needsComponentSerialization) {
            result = addImportIfMissing(result, "net.minecraft.network.chat.ComponentSerialization")
        }
        return result
    }

    private fun migrateLegacyMapItemApis(source: String): String {
        if (!source.contains("MapItem") &&
            !source.contains("MapItemSavedData") &&
            !source.contains("ClientboundMapItemDataPacket") &&
            !source.contains("getFreeMapId()") &&
            !source.contains("getMapId(")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var needsMapId = false
        var needsDataComponents = false
        var needsHolderLookup = false
        var needsSavedData = false
        var needsRegistryFriendlyByteBuf = false

        result = Regex("""\b([A-Za-z_$][\w$]*)\.getLevelData\(\)\.getXSpawn\(\)""")
            .replace(result, "$1.getSharedSpawnPos().getX()")
        result = Regex("""\b([A-Za-z_$][\w$]*)\.getLevelData\(\)\.getYSpawn\(\)""")
            .replace(result, "$1.getSharedSpawnPos().getY()")
        result = Regex("""\b([A-Za-z_$][\w$]*)\.getLevelData\(\)\.getZSpawn\(\)""")
            .replace(result, "$1.getSharedSpawnPos().getZ()")

        if (result.contains("extends MapItem") || result.contains(" getFreeMapId()") || result.contains("getMapId(")) {
            result = Regex("""\bInteger\s+($id)\s*=\s*getMapId\(\s*($id)\s*\)\s*;""")
                .replace(result) { match ->
                    needsMapId = true
                    needsDataComponents = true
                    "MapId ${match.groupValues[1]} = ${match.groupValues[2]}.get(DataComponents.MAP_ID);"
                }
            result = Regex("""\bint\s+($id)\s*=\s*([A-Za-z_$][\w$]*)\.getFreeMapId\(\)\s*;""")
                .replace(result) { match ->
                    needsMapId = true
                    "MapId ${match.groupValues[1]} = ${match.groupValues[2]}.getFreeMapId();"
                }
            result = Regex("""public\s+static\s+String\s+getMapName\s*\(\s*int\s+($id)\s*\)""")
                .replace(result) { match ->
                    needsMapId = true
                    "public static String getMapName(MapId ${match.groupValues[1]})"
                }
            result = Regex("""return\s+STR_ID\s*\+\s*"_[^"]*"\s*\+\s*($id)\s*;""")
                .replace(result) { match ->
                    val variable = match.groupValues[1]
                    if (Regex("""\bgetMapName\s*\(\s*MapId\s+${Regex.escape(variable)}\s*\)""").containsMatchIn(result)) {
                        "return STR_ID + \"_\" + $variable.id();"
                    } else {
                        match.value
                    }
                }
            result = Regex(
                """(?m)^([ \t]*)($id)\.getOrDefault\(net\.minecraft\.core\.component\.DataComponents\.CUSTOM_DATA,\s*net\.minecraft\.world\.item\.component\.CustomData\.EMPTY\)\.copyTag\(\)\.putInt\(\s*"map"\s*,\s*($id)\s*\);\s*$"""
            ).replace(result) { match ->
                needsDataComponents = true
                "${match.groupValues[1]}${match.groupValues[2]}.set(DataComponents.MAP_ID, ${match.groupValues[3]});"
            }

            val hoverText = javaDeclaredMethodText(result, "appendHoverText")
            if (hoverText != null) {
                val contextVariable = Regex("""\b(?:Item\.)?TooltipContext\s+($id)\b""")
                    .find(hoverText)
                    ?.groupValues
                    ?.get(1)
                if (contextVariable != null && hoverText.contains("getData(") && hoverText.contains(", $contextVariable")) {
                    val levelVariable = uniqueLocalName(hoverText, "tooltipLevel")
                    var migratedMethod = hoverText
                    migratedMethod = Regex(
                        """\b${Regex.escape(contextVariable)}\s*==\s*null\s*\?\s*null\s*:\s*getData\(\s*([^,\r\n]+)\s*,\s*${Regex.escape(contextVariable)}\s*\)"""
                    ).replace(migratedMethod) { match ->
                        "$levelVariable == null ? null : getData(${match.groupValues[1].trim()}, $levelVariable)"
                    }
                    migratedMethod = Regex("""\bgetData\(\s*([^,\r\n]+)\s*,\s*${Regex.escape(contextVariable)}\s*\)""")
                        .replace(migratedMethod) { match ->
                            "getData(${match.groupValues[1].trim()}, $levelVariable)"
                        }
                    val localLine = "Level $levelVariable = $contextVariable != null ? $contextVariable.level() : null;"
                    if (!migratedMethod.contains(localLine)) {
                        val openBrace = migratedMethod.indexOf('{')
                        val insertAfter = Regex("""(?m)^([ \t]*)super\.appendHoverText\([^;\r\n]*;\s*$""").find(migratedMethod)
                        migratedMethod = if (insertAfter != null) {
                            val insertAt = insertAfter.range.last + 1
                            val indent = insertAfter.groupValues[1]
                            migratedMethod.substring(0, insertAt) + "\n${indent}$localLine" + migratedMethod.substring(insertAt)
                        } else if (openBrace >= 0) {
                            migratedMethod.substring(0, openBrace + 1) + "\n\t\t$localLine" + migratedMethod.substring(openBrace + 1)
                        } else {
                            migratedMethod
                        }
                    }
                    result = result.replace(hoverText, migratedMethod)
                }
            }
        }

        if (result.contains("extends MapItemSavedData")) {
            result = Regex("""public\s+static\s+($id)\s+load\s*\(\s*CompoundTag\s+($id)\s*\)""")
                .replace(result) { match ->
                    needsHolderLookup = true
                    "public static ${match.groupValues[1]} load(CompoundTag ${match.groupValues[2]}, HolderLookup.Provider registries)"
                }
            result = Regex("""MapItemSavedData\.load\(\s*($id)\s*\)""")
                .replace(result) { match ->
                    needsHolderLookup = true
                    "MapItemSavedData.load(${match.groupValues[1]}, registries)"
                }
            result = Regex("""public\s+CompoundTag\s+save\s*\(\s*CompoundTag\s+($id)\s*\)""")
                .replace(result) { match ->
                    needsHolderLookup = true
                    "public CompoundTag save(CompoundTag ${match.groupValues[1]}, HolderLookup.Provider registries)"
                }
            result = Regex("""super\.save\(\s*($id)\s*\)""")
                .replace(result) { match ->
                    needsHolderLookup = true
                    "super.save(${match.groupValues[1]}, registries)"
                }
            result = Regex("""\.get\(\s*($id)::load\s*,\s*([^)\r\n]+)\)""")
                .replace(result) { match ->
                    needsSavedData = true
                    ".get(new SavedData.Factory<>(() -> null, ${match.groupValues[1]}::load), ${match.groupValues[2].trim()})"
                }
            result = Regex("""getUpdatePacket\s*\(\s*int\s+($id)\s*,\s*Player\s+($id)\s*\)""")
                .replace(result) { match ->
                    needsMapId = true
                    "getUpdatePacket(MapId ${match.groupValues[1]}, Player ${match.groupValues[2]})"
                }
        }

        if (result.contains("ClientboundMapItemDataPacket")) {
            result = result
                .replace("new ClientboundMapItemDataPacket(buf)", "ClientboundMapItemDataPacket.STREAM_CODEC.decode(buf)")
                .replace("this.inner.write(buf);", "ClientboundMapItemDataPacket.STREAM_CODEC.encode(buf, this.inner);")
                .replace(".getMapId()", ".mapId()")
                .replace(".getScale()", ".scale()")
                .replace(".isLocked()", ".locked()")
            if (result.contains("ClientboundMapItemDataPacket.STREAM_CODEC")) {
                result = result
                    .replace("StreamCodec<FriendlyByteBuf,", "StreamCodec<RegistryFriendlyByteBuf,")
                    .replace("public ${classNameOfJavaSource(result) ?: ""}(FriendlyByteBuf buf)", "public ${classNameOfJavaSource(result) ?: ""}(RegistryFriendlyByteBuf buf)")
                    .replace("public void encode(FriendlyByteBuf buf)", "public void encode(RegistryFriendlyByteBuf buf)")
                needsRegistryFriendlyByteBuf = true
            }
        }

        if (needsMapId || result.contains("MapId ")) {
            result = addImportIfMissing(result, "net.minecraft.world.level.saveddata.maps.MapId")
        }
        if (needsDataComponents) {
            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        }
        if (needsHolderLookup) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
        }
        if (needsSavedData) {
            result = addImportIfMissing(result, "net.minecraft.world.level.saveddata.SavedData")
        }
        if (needsRegistryFriendlyByteBuf) {
            result = addImportIfMissing(result, "net.minecraft.network.RegistryFriendlyByteBuf")
            val withoutFriendly = removeImport(result, "net.minecraft.network.FriendlyByteBuf")
            if (!Regex("""\bFriendlyByteBuf\b""").containsMatchIn(withoutFriendly)) {
                result = withoutFriendly
            }
        }
        return result
    }

    private fun migrateLegacyLootTableKeyFields(source: String): String {
        if (!source.contains("ResourceKey.create(Registries.LOOT_TABLE") ||
            !source.contains("ResourceLocation")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        val lootTableFields = Regex("""this\.($id)\s*=\s*ResourceKey\.create\(\s*Registries\.LOOT_TABLE\s*,""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (lootTableFields.isEmpty()) return source

        var result = source
        lootTableFields.forEach { field ->
            result = Regex("""\b((?:public|protected|private)\s+(?:static\s+)?(?:final\s+)?)ResourceLocation(\s+${Regex.escape(field)}\s*[;=])""")
                .replace(result, "$1ResourceKey<LootTable>$2")
        }

        if (result != source) {
            result = addImportIfMissing(result, "net.minecraft.resources.ResourceKey")
            result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
            result = addImportIfMissing(result, "net.minecraft.world.level.storage.loot.LootTable")
            val withoutResourceLocationImport = removeImport(result, "net.minecraft.resources.ResourceLocation")
            if (!Regex("""\bResourceLocation\b""").containsMatchIn(withoutResourceLocationImport)) {
                result = withoutResourceLocationImport
            }
        }
        return result
    }

    private fun migrateLootTableResourceKeyReferenceCreates(
        source: String,
        resourceKeyLootTableOwners: Set<String>
    ): String {
        if (resourceKeyLootTableOwners.isEmpty() ||
            !source.contains("ResourceKey.create(Registries.LOOT_TABLE") ||
            !source.contains(".lootTable")) {
            return source
        }

        val ownerPattern = resourceKeyLootTableOwners.joinToString("|") { Regex.escape(it) }
        var result = Regex(
            """ResourceKey\.create\(\s*Registries\.LOOT_TABLE\s*,\s*(($ownerPattern)(?:\.[A-Za-z_$][\w$]*)+\.lootTable)\s*\)"""
        ).replace(source, "$1")

        val id = """[A-Za-z_$][\w$]*"""
        val ownerVariables = Regex("""\b(?:final\s+)?(?:$ownerPattern)\s+($id)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        if (ownerVariables.isNotEmpty()) {
            val variablePattern = ownerVariables.joinToString("|") { Regex.escape(it) }
            result = Regex(
                """ResourceKey\.create\(\s*Registries\.LOOT_TABLE\s*,\s*(($variablePattern)\.lootTable)\s*\)"""
            ).replace(result, "$1")
        }
        return result
    }

    private fun migrateClientLevelEntityInsertionCalls(source: String): String {
        if (!source.contains(".putNonPlayerEntity(")) return source
        return rewriteJavaCall(source, "putNonPlayerEntity") { receiver, args ->
            if (receiver.isBlank() || args.size != 2) {
                null
            } else {
                "$receiver.addEntity(${args[1].trim()})"
            }
        }
    }

    private fun migrateLegacyResourceLocationValidationSource(source: String): String {
        if (!source.contains("ResourceLocation.isValidResourceLocation(")) return source
        var result = Regex("""!\s*ResourceLocation\.isValidResourceLocation\(\s*([^()\r\n]+(?:\([^()\r\n]*\))?)\s*\)""")
            .replace(source) { match ->
                "ResourceLocation.tryParse(${match.groupValues[1].trim()}) == null"
            }
        result = Regex("""ResourceLocation\.isValidResourceLocation\(\s*([^()\r\n]+(?:\([^()\r\n]*\))?)\s*\)""").replace(result) { match ->
            "ResourceLocation.tryParse(${match.groupValues[1].trim()}) != null"
        }
        return result
    }

    private fun migrateLegacyHolderMethodReferences(source: String): String {
        if (!source.contains("Holder::get")) return source
        return source.replace("Holder::get", "Holder::value")
    }

    private fun migrateLegacyHolderValueCalls(source: String): String {
        if (!source.contains(".get()")) return source
        var result = source.replace(".generatorSettings().get()", ".generatorSettings().value()")
        if (result.contains("forMusic(") ||
            result.contains("forBossMusic(") ||
            result.contains("net.minecraft.sounds.Music") ||
            Regex("""\bMusic\s+[A-Za-z_$][\w$]*""").containsMatchIn(result)) {
            result = result.replace(".getEvent().get()", ".getEvent().value()")
        }
        result = Regex("""\b((?:net\.neoforged\.neoforge\.common\.)?NeoForgeMod\.(?:EMPTY_TYPE|WATER_TYPE|LAVA_TYPE))\.get\(\)""")
            .replace(result) { match -> "${match.groupValues[1]}.value()" }
        val holderVariables = Regex(
            """\b(?:final\s+)?(?:net\.minecraft\.core\.)?Holder(?:\.Reference)?\s*<[^;=()]+>\s+([A-Za-z_$][\w$]*)\b"""
        ).findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        holderVariables.forEach { variable ->
            result = Regex("""\b${Regex.escape(variable)}\.get\(\)""")
                .replace(result, "$variable.value()")
        }
        return result
    }

    private fun migrateLegacyHolderReferenceBindKeyCalls(source: String): String {
        if (!source.contains(".bindKey(") || !source.contains(".getOrThrow(")) return source
        val keyedReferences = Regex(
            """\b(?:final\s+)?(?:Holder\.Reference|net\.minecraft\.core\.Holder\.Reference)\s*<[^;=()]+>\s+([A-Za-z_$][\w$]*)\s*=\s*[^;\r\n]+\.getOrThrow\(\s*([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\)\s*;"""
        ).findAll(source)
            .associate { it.groupValues[1] to it.groupValues[2] }
        if (keyedReferences.isEmpty()) return source
        var result = source
        keyedReferences.forEach { (holder, key) ->
            result = Regex("""(?m)^[ \t]*${Regex.escape(holder)}\.bindKey\(\s*${Regex.escape(key)}\s*\)\s*;\s*\r?\n""")
                .replace(result, "")
        }
        return result
    }

    private fun migrateLegacyOptionalValueCalls(source: String): String {
        if (!source.contains(".value()") || !source.contains("Optional<")) return source
        val optionalVariables = Regex("""\bOptional\s*<[^;=()]+?>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (optionalVariables.isEmpty()) return source
        var result = source
        optionalVariables.forEach { variable ->
            result = Regex("""\b${Regex.escape(variable)}\.value\(\)""")
                .replace(result, "$variable.get()")
        }
        return result
    }

    private fun migrateLegacyChunkGeneratorAsyncSignatures(source: String): String {
        if (!source.contains("fillFromNoise(") && !source.contains("createBiomes(")) return source
        var result = source
        var changed = false
        val createBiomesPattern = Regex(
            """createBiomes\s*\(\s*Executor\s+([A-Za-z_$][\w$]*)\s*,\s*RandomState\s+([A-Za-z_$][\w$]*)\s*,\s*Blender\s+([A-Za-z_$][\w$]*)\s*,\s*StructureManager\s+([A-Za-z_$][\w$]*)\s*,\s*ChunkAccess\s+([A-Za-z_$][\w$]*)\s*\)"""
        )
        result = createBiomesPattern.replace(result) { match ->
            changed = true
            "createBiomes(RandomState ${match.groupValues[2]}, Blender ${match.groupValues[3]}, StructureManager ${match.groupValues[4]}, ChunkAccess ${match.groupValues[5]})"
        }
        val fillFromNoiseSignaturePattern = Regex(
            """fillFromNoise\s*\(\s*Executor\s+([A-Za-z_$][\w$]*)\s*,\s*Blender\s+([A-Za-z_$][\w$]*)\s*,\s*RandomState\s+([A-Za-z_$][\w$]*)\s*,\s*StructureManager\s+([A-Za-z_$][\w$]*)\s*,\s*ChunkAccess\s+([A-Za-z_$][\w$]*)\s*\)"""
        )
        result = fillFromNoiseSignaturePattern.replace(result) { match ->
            changed = true
            "fillFromNoise(Blender ${match.groupValues[2]}, RandomState ${match.groupValues[3]}, StructureManager ${match.groupValues[4]}, ChunkAccess ${match.groupValues[5]})"
        }
        result = Regex("""\b(super|this\.delegate|delegate)\.fillFromNoise\(\s*[A-Za-z_$][\w$]*\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)""")
            .replace(result) { match ->
                changed = true
                "${match.groupValues[1]}.fillFromNoise(${match.groupValues[2]}, ${match.groupValues[3]}, ${match.groupValues[4]}, ${match.groupValues[5]})"
            }
        if (changed && result.contains(", executor)")) {
            result = result.replace(", executor)", ", Util.backgroundExecutor())")
        }
        if (changed) {
            val withoutExecutor = removeImport(result, "java.util.concurrent.Executor")
            if (!Regex("""\bExecutor\b""").containsMatchIn(withoutExecutor)) {
                result = withoutExecutor
            }
        }
        return result
    }

    private fun migrateLegacyBlockStateSurvivalAndPlantCalls(source: String): String {
        if (!source.contains("canSurvive(") && !source.contains("canSustainPlant(")) return source
        var result = Regex(
            """((?:this\.)?[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.getBlock\(\)\.canSurvive\(\s*\1\s*,\s*([^,\r\n]+)\s*,\s*([^)]+)\s*\)"""
        ).replace(source) { match ->
            "${match.groupValues[1]}.canSurvive(${match.groupValues[2].trim()}, ${match.groupValues[3].trim()})"
        }
        result = rewriteJavaCall(result, "canSustainPlant") { receiver, args ->
            if (receiver.isBlank() || args.size != 5) return@rewriteJavaCall null
            val plant = args[4].trim()
            val migratedPlant = when {
                plant.contains(".defaultBlockState()") -> plant
                Regex("""(?:\.get\(\)|\bBlocks\.[A-Z0-9_]+)$""").containsMatchIn(plant) -> "$plant.defaultBlockState()"
                else -> return@rewriteJavaCall null
            }
            "$receiver.canSustainPlant(${args[0].trim()}, ${args[1].trim()}, ${args[2].trim()}, ${args[3].trim()}, $migratedPlant)"
        }
        result = Regex("""!\s*([^;\r\n]+?\.canSustainPlant\((?:[^()]|\([^()]*\))*\))""")
            .replace(result) { match ->
                val expression = match.groupValues[1]
                if (expression.contains("&&") || expression.contains("||") || expression.contains(" instanceof ")) {
                    match.value
                } else {
                    "$expression.isFalse()"
                }
            }
        result = Regex("""\breturn\s+([^;\r\n!]+?\.canSustainPlant\((?:[^()]|\([^()]*\))*\))\s*;""")
            .replace(result) { match ->
                val expression = match.groupValues[1]
                if (expression.contains("&&") || expression.contains("||") || expression.contains(" instanceof ")) {
                    match.value
                } else {
                    "return !$expression.isFalse();"
                }
            }
        result = Regex("""return\s+!super\.canSustainPlant\(((?:[^()]|\([^()]*\))*)\)\.isFalse\(\);""")
            .replace(result) { match -> "return super.canSustainPlant(${match.groupValues[1]});" }
        return result
    }

    private fun migrateLegacyAuthlibProfileFetchSource(source: String): String {
        if (!source.contains("YggdrasilAuthenticationService") ||
            !source.contains("MinecraftProfilePropertiesResponse") ||
            !source.contains("performGetRequest(")) {
            return source
        }
        var result = source
        val oldStart = result.indexOf("URL url = HttpAuthenticationService.constantURL(")
        val oldEndMarker = "GAME_PROFILES.add(result);"
        val oldEndCall = result.indexOf(oldEndMarker, oldStart)
        if (oldStart >= 0 && oldEndCall >= 0) {
            var oldBlockEnd = result.indexOf('\n', oldEndCall + oldEndMarker.length).let { if (it < 0) oldEndCall + oldEndMarker.length else it + 1 }
            while (oldBlockEnd < result.length) {
                val nextLineEnd = result.indexOf('\n', oldBlockEnd).let { if (it < 0) result.length else it + 1 }
                val line = result.substring(oldBlockEnd, nextLineEnd).trim()
                if (line.isNotEmpty() && line != "}") break
                oldBlockEnd = nextLineEnd
            }
            val indent = result.substring(result.lastIndexOf('\n', oldStart).let { if (it < 0) 0 else it + 1 }, oldStart)
                .takeWhile { it == ' ' || it == '\t' }
            val replacement = """
${indent}var profileResult = service.createMinecraftSessionService().fetchProfile(uuid, false);
${indent}if (profileResult != null && profileResult.profile() != null) {
${indent}	GAME_PROFILES.add(profileResult.profile());
${indent}}
            """.trimIndent()
            result = result.substring(0, oldStart) + replacement + "\n" + result.substring(oldBlockEnd)
        }
        result = Regex("""(?m)^[ \t]*String\s+baseUrl\s*=\s*EnvironmentParser\.getEnvironmentFromProperties\(\).*?;\s*\r?\n""")
            .replace(result, "")
        result = Regex("""(?m)^[ \t]*boolean\s+requireSecure\s*=\s*false\s*;\s*\r?\n""")
            .replace(result, "")
        result = result.replace("catch (AuthenticationException | IOException e)", "catch (RuntimeException e)")
        listOf(
            "com.mojang.authlib.EnvironmentParser",
            "com.mojang.authlib.HttpAuthenticationService",
            "com.mojang.authlib.exceptions.*",
            "com.mojang.authlib.minecraft.client.ObjectMapper",
            "com.mojang.authlib.yggdrasil.YggdrasilEnvironment",
            "com.mojang.authlib.yggdrasil.response.MinecraftProfilePropertiesResponse",
            "org.apache.commons.lang3.StringUtils",
            "java.io.IOException",
            "java.net.URL"
        ).forEach { importName ->
            result = removeImport(result, importName)
        }
        return result
    }

    private fun migrateLegacyPaintingVariantAccessors(source: String): String {
        if (!source.contains("PaintingVariant")) return source
        val variables = Regex("""\bPaintingVariant\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (variables.isEmpty()) return source

        var result = source
        variables.forEach { variable ->
            result = result
                .replace("$variable.getWidth()", "$variable.width()")
                .replace("$variable.getHeight()", "$variable.height()")
        }
        return result
    }

    private fun migrateLegacyPaintingVariantRegistrySource(
        source: String,
        legacyRegistryBackedMethods: Set<LegacyRegistryBackedMethod> = emptySet()
    ): String {
        if (!source.contains("BuiltInRegistries.PAINTING_VARIANT") && !source.contains(".getPaintingOfSize(")) return source
        var result = source
        var changed = false

        result = Regex("""BuiltInRegistries\.PAINTING_VARIANT\.getHolder\(\s*([^)]+)\s*\)\.get\(\)""")
            .replace(result) { match ->
                val registryAccess = registryAccessExpressionForEnclosingMethod(result, match.range.first)
                    ?: return@replace match.value
                if (registryAccess == "this.registryAccess()") {
                    return@replace match.value
                }
                    changed = true
                    "$registryAccess.registryOrThrow(Registries.PAINTING_VARIANT).getHolderOrThrow(${match.groupValues[1].trim()})"
            }

        if (result.contains("BuiltInRegistries.PAINTING_VARIANT.tags().getTag(")) {
            result = result
                .replace(
                    "getPaintingOfSize(RandomSource rand, int minSize)",
                    "getPaintingOfSize(RegistryAccess registryAccess, RandomSource rand, int minSize)"
                )
                .replace(
                    "getPaintingOfSize(RandomSource rand, int width, int height, boolean exactMeasurements)",
                    "getPaintingOfSize(RegistryAccess registryAccess, RandomSource rand, int width, int height, boolean exactMeasurements)"
                )
                .replace(
                    "return getPaintingOfSize(rand, minSize, minSize, false);",
                    "return getPaintingOfSize(registryAccess, rand, minSize, minSize, false);"
                )
            result = Regex(
                """for\s*\(\s*PaintingVariant\s+([A-Za-z_$][\w$]*)\s*:\s*BuiltInRegistries\.PAINTING_VARIANT\.tags\(\)\.getTag\(\s*([^)]+)\s*\)\s*\)\s*\{"""
            ).replace(result) { match ->
                changed = true
                val valueVar = match.groupValues[1]
                val tag = match.groupValues[2].trim()
                "for (Holder<PaintingVariant> ${valueVar}Holder : registryAccess.registryOrThrow(Registries.PAINTING_VARIANT).getTagOrEmpty($tag)) {\n\t\t\tPaintingVariant $valueVar = ${valueVar}Holder.value();"
            }
            result = Regex(
                """ResourceKey\.create\(\s*Registries\.PAINTING_VARIANT\s*,\s*Objects\.requireNonNull\(\s*BuiltInRegistries\.PAINTING_VARIANT\.getKey\(\s*([A-Za-z_$][\w$]*)\s*\)\s*\)\s*\)"""
            ).replace(result) { match ->
                changed = true
                "${match.groupValues[1]}Holder.unwrapKey().orElseThrow()"
            }
        }

        if (result.contains(".getPaintingOfSize(")) {
            result = Regex("""([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.getPaintingOfSize\(""")
                .replace(result) { match ->
                    if (!isKnownRegistryBackedMethodCall(result, match.groupValues[1], "getPaintingOfSize", legacyRegistryBackedMethods)) {
                        return@replace match.value
                    }
                    val callRegistryAccess = registryAccessExpressionForEnclosingMethod(result, match.range.first)
                        ?: return@replace match.value
                    changed = true
                    "${match.groupValues[1]}.getPaintingOfSize($callRegistryAccess, "
                }
        }

        if (!changed) return source
        if (result.contains("Holder<PaintingVariant>")) {
            result = addImportIfMissing(result, "net.minecraft.core.Holder")
        }
        if (result.contains("RegistryAccess")) {
            result = addImportIfMissing(result, "net.minecraft.core.RegistryAccess")
        }
        val withoutBuiltIn = removeImport(result, "net.minecraft.core.registries.BuiltInRegistries")
        if (!Regex("""\bBuiltInRegistries\b""").containsMatchIn(withoutBuiltIn)) {
            result = withoutBuiltIn
        }
        val withoutObjects = removeImport(result, "java.util.Objects")
        if (!Regex("""\bObjects\b""").containsMatchIn(withoutObjects)) {
            result = withoutObjects
        }
        return result
    }

    private fun migrateLegacyBiomeSourceCodecReturnSource(source: String): String {
        if (!source.contains("extends BiomeSource") || !source.contains(" codec()")) return source
        var changed = false
        var result = Regex(
            """protected\s+Codec\s*<\s*([A-Za-z_$][\w$]*)\s*>\s+codec\s*\(\s*\)"""
        ).replace(source) { match ->
            changed = true
            "protected MapCodec<${match.groupValues[1]}> codec()"
        }
        val className = Regex("""\bclass\s+([A-Za-z_$][\w$]*)\s+extends\s+BiomeSource\b""")
            .find(result)
            ?.groupValues
            ?.get(1)
        if (className != null) {
            val withoutBiomeSourceWitness = Regex("""RecordCodecBuilder\s*\.\s*<\s*${Regex.escape(className)}\s*>\s*mapCodec\(""")
                .replace(result, "RecordCodecBuilder.mapCodec(")
            if (withoutBiomeSourceWitness != result) {
                result = withoutBiomeSourceWitness
                changed = true
            }
        }
        if (!changed) return source
        result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
        val withoutCodec = removeImport(result, "com.mojang.serialization.Codec")
        if (!Regex("""\bCodec\b""").containsMatchIn(withoutCodec)) {
            result = withoutCodec
        }
        return result
    }

    private fun migrateLegacyAttachmentGetDataLazyOptionalReturns(source: String): String {
        if (!source.contains("LazyOptional<") || !source.contains(".getData(")) return source
        return Regex(
            """(?s)(\b(?:public|protected|private)?\s*static\s+LazyOptional\s*<[^>\r\n]+>\s+[A-Za-z_$][\w$]*\s*\([^)]*\)\s*\{(?:(?!\n\s*\}).)*?)return\s+([^;\r\n{}]+?\.getData\([^;\r\n{}]+?\))\s*;"""
        ).replace(source) { match ->
            val expression = match.groupValues[2].trim()
            if (expression.contains("LazyOptional.") || expression.contains("ofNullable(")) {
                match.value
            } else {
                "${match.groupValues[1]}return LazyOptional.ofNullable($expression);"
            }
        }
    }

    private fun migrateLegacyEntityCapabilityOptionalChains(source: String): String {
        if (!source.contains(".getCapability(") || !source.contains(".map(") || !source.contains(".orElse(")) return source
        val pattern = Regex(
            """(?ms)^([ \t]*)return\s+([^\r\n;]+?\.getCapability\((?:[^()]|\([^()]*\))*\))\.map\(\s*([A-Za-z_$][\w$]*)\s*->\s*\{(.*?)\}\s*\)\.orElse\(\s*([^;\r\n]+?)\s*\)\s*;"""
        )
        return pattern.replace(source) { match ->
            val indent = match.groupValues[1]
            val capabilityCall = match.groupValues[2].trim()
            val variable = match.groupValues[3]
            val body = match.groupValues[4].trim('\n', '\r')
            val fallback = match.groupValues[5].trim()
            """
${indent}var $variable = $capabilityCall;
${indent}if ($variable == null) {
${indent}	return $fallback;
${indent}}
${indent}{
$body
${indent}}
            """.trimIndent()
        }
    }

    private fun migrateLegacyEnchantmentTagChecks(source: String): String {
        if (!source.contains("BuiltInRegistries.ENCHANTMENT.tags().getTag(")) return source

        val id = """[A-Za-z_$][\w$]*"""
        val holderVariables = Regex("""\b(?:net\.minecraft\.core\.)?Holder\s*<\s*(?:net\.minecraft\.world\.item\.enchantment\.)?Enchantment\s*>\s+($id)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (holderVariables.isEmpty()) return source

        val tagExpression = """[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*"""
        var result = source
        result = Regex(
            """BuiltInRegistries\.ENCHANTMENT\.tags\(\)\.getTag\(\s*($tagExpression)\s*\)\.contains\(\s*($id)\s*\)"""
        ).replace(result) { match ->
            val holder = match.groupValues[2]
            if (holder in holderVariables) {
                "$holder.is(${match.groupValues[1]})"
            } else {
                match.value
            }
        }

        result = Regex(
            """(?s)for\s*\(\s*(?:final\s+)?Enchantment\s+($id)\s*:\s*BuiltInRegistries\.ENCHANTMENT\.tags\(\)\.getTag\(\s*($tagExpression)\s*\)\s*\)\s*\{\s*if\s*\(\s*Objects\.equals\(\s*\1\s*,\s*($id)\s*\)\s*\)\s*\{\s*(.*?)\s*break\s*;\s*}\s*}"""
        ).replace(result) { match ->
            val holder = match.groupValues[3]
            if (holder in holderVariables) {
                "if ($holder.is(${match.groupValues[2]})) {\n${match.groupValues[4].trimEnd()}\n\t\t\t}"
            } else {
                match.value
            }
        }
        result = Regex(
            """(?s)for\s*\(\s*(?:final\s+)?Enchantment\s+($id)\s*:\s*BuiltInRegistries\.ENCHANTMENT\.tags\(\)\.getTag\(\s*($tagExpression)\s*\)\s*\)\s*\{\s*if\s*\(\s*Objects\.equals\(\s*($id)\s*,\s*\1\s*\)\s*\)\s*\{\s*(.*?)\s*break\s*;\s*}\s*}"""
        ).replace(result) { match ->
            val holder = match.groupValues[3]
            if (holder in holderVariables) {
                "if ($holder.is(${match.groupValues[2]})) {\n${match.groupValues[4].trimEnd()}\n\t\t\t}"
            } else {
                match.value
            }
        }

        if (!result.contains("BuiltInRegistries.ENCHANTMENT")) {
            result = removeImport(result, "net.minecraft.core.registries.BuiltInRegistries")
        }
        if (!Regex("""\bObjects\.""").containsMatchIn(result)) {
            result = removeImport(result, "java.util.Objects")
        }
        return result
    }

    private fun uniqueLocalName(source: String, baseName: String): String {
        if (!Regex("""\b${Regex.escape(baseName)}\b""").containsMatchIn(source)) return baseName
        var index = 1
        while (Regex("""\b${Regex.escape(baseName)}$index\b""").containsMatchIn(source)) {
            index++
        }
        return "$baseName$index"
    }

    private fun migrateLegacyProjectileEnchantmentPostEffectsSource(
        source: String,
        javaInheritanceIndex: JavaInheritanceIndex = JavaInheritanceIndex.EMPTY
    ): String {
        if (!source.contains("EnchantmentHelper.doPostHurtEffects(") ||
            !source.contains("EnchantmentHelper.doPostDamageEffects(") ||
            !source.contains("AbstractArrow")) {
            return source
        }

        var result = source
        var cursor = 0
        var changed = false
        val hurtToken = "EnchantmentHelper.doPostHurtEffects("
        val damageToken = "EnchantmentHelper.doPostDamageEffects("
        while (true) {
            val hurtIndex = result.indexOf(hurtToken, cursor)
            if (hurtIndex < 0) break
            val classDeclaration = enclosingJavaClassDeclaration(result, hurtIndex)
            if (!javaClassExtendsAny(classDeclaration, setOf("AbstractArrow"), javaInheritanceIndex)) {
                cursor = hurtIndex + hurtToken.length
                continue
            }

            val hurtOpenParen = hurtIndex + "EnchantmentHelper.doPostHurtEffects".length
            val hurtCloseParen = findMatchingParen(result, hurtOpenParen)
            if (hurtCloseParen < 0) {
                cursor = hurtIndex + hurtToken.length
                continue
            }
            val hurtArgs = splitTopLevelJavaArgs(result.substring(hurtOpenParen + 1, hurtCloseParen))
            val hurtSemicolon = nextNonWhitespaceIndex(result, hurtCloseParen + 1)
            if (hurtArgs.size != 2 || hurtSemicolon < 0 || result[hurtSemicolon] != ';') {
                cursor = hurtCloseParen + 1
                continue
            }

            val damageIndex = nextNonWhitespaceIndex(result, hurtSemicolon + 1)
            if (damageIndex < 0 || !result.startsWith(damageToken, damageIndex)) {
                cursor = hurtSemicolon + 1
                continue
            }
            val damageOpenParen = damageIndex + "EnchantmentHelper.doPostDamageEffects".length
            val damageCloseParen = findMatchingParen(result, damageOpenParen)
            if (damageCloseParen < 0) {
                cursor = damageIndex + damageToken.length
                continue
            }
            val damageArgs = splitTopLevelJavaArgs(result.substring(damageOpenParen + 1, damageCloseParen))
            val damageSemicolon = nextNonWhitespaceIndex(result, damageCloseParen + 1)
            if (damageArgs.size != 2 || damageSemicolon < 0 || result[damageSemicolon] != ';') {
                cursor = damageCloseParen + 1
                continue
            }

            val target = hurtArgs[0].trim()
            if (damageArgs[1].trim() != target ||
                normalizeLegacyLivingEntityCast(damageArgs[0]) != hurtArgs[1].trim()) {
                cursor = damageSemicolon + 1
                continue
            }

            val methodRange = enclosingMethodRange(result, hurtIndex)
            val methodPrefix = methodRange?.let { result.substring(it.first, hurtIndex) }
            val methodText = methodRange?.let { result.substring(it) }
            val damageSource = methodPrefix?.let(::lastDamageSourceVariable)
            if (damageSource == null || methodText == null) {
                cursor = damageSemicolon + 1
                continue
            }

            val statementStart = result.lastIndexOf('\n', hurtIndex).let { if (it < 0) 0 else it + 1 }
            val indent = result.substring(statementStart, hurtIndex).takeWhile { it == ' ' || it == '\t' }
            val serverLevel = uniqueLocalNameInScope(methodText, "serverlevel")
            val replacement = """${indent}if (this.level() instanceof ServerLevel $serverLevel) {
$indent    EnchantmentHelper.doPostAttackEffectsWithItemSource($serverLevel, $target, $damageSource, this.getWeaponItem());
$indent}"""
            result = result.substring(0, statementStart) + replacement + result.substring(damageSemicolon + 1)
            cursor = statementStart + replacement.length
            changed = true
        }

        return if (changed) addImportIfMissing(result, "net.minecraft.server.level.ServerLevel") else result
    }

    private fun normalizeLegacyLivingEntityCast(expression: String): String =
        Regex("""^\(\s*LivingEntity\s*\)\s*""").replace(expression.trim(), "").trim()

    private fun lastDamageSourceVariable(prefix: String): String? =
        Regex("""\bDamageSource\s+([A-Za-z_$][\w$]*)\s*(?:=|;)""")
            .findAll(prefix)
            .lastOrNull()
            ?.groupValues
            ?.get(1)

    private fun migrateLegacyDoEnchantDamageEffectsSource(source: String): String {
        if (!source.contains(".doEnchantDamageEffects(")) return source

        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        var needsServerLevel = false
        var needsEnchantmentHelper = false
        var needsDamageSource = false
        val token = ".doEnchantDamageEffects("

        while (cursor < source.length) {
            val tokenIndex = source.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val receiverStart = findDottedReceiverStart(source, tokenIndex)
            val receiver = source.substring(receiverStart, tokenIndex).trim()
            val openParen = tokenIndex + ".doEnchantDamageEffects".length
            val closeParen = findMatchingParen(source, openParen)
            if (receiver.isBlank() || closeParen < 0) {
                migrated.append(source, cursor, tokenIndex + token.length)
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size != 2) {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }

            val statementStart = source.lastIndexOf('\n', receiverStart).let { if (it < 0) 0 else it + 1 }
            val semicolonIndex = nextNonWhitespaceIndex(source, closeParen + 1)
            if (semicolonIndex < 0 || source[semicolonIndex] != ';') {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }

            val target = args[1].trim()
            val damageSourceExpr = inferDamageSourceForDoEnchantDamageEffects(source, statementStart, target)
            if (damageSourceExpr == null) {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }

            val indent = source.substring(statementStart, receiverStart).takeWhile { it == ' ' || it == '\t' }
            val levelExpression = if (receiver == "this") "this.level()" else "$receiver.level()"
            val damageSource = if (Regex("""^[A-Za-z_$][\w$]*$""").matches(damageSourceExpr)) {
                damageSourceExpr
            } else {
                "postAttackDamageSource"
            }
            val sourceLine = if (damageSource == damageSourceExpr) {
                ""
            } else {
                "${indent}DamageSource $damageSource = $damageSourceExpr;\n"
            }
            val replacement = """$sourceLine${indent}if ($levelExpression instanceof ServerLevel serverLevel) {
$indent    EnchantmentHelper.doPostAttackEffects(serverLevel, $target, $damageSource);
$indent}"""
            migrated.append(source, cursor, statementStart)
            migrated.append(replacement)
            cursor = semicolonIndex + 1
            changed = true
            needsServerLevel = true
            needsEnchantmentHelper = true
            needsDamageSource = needsDamageSource || sourceLine.isNotEmpty()
        }

        if (!changed) return source
        migrated.append(source, cursor, source.length)
        var result = migrated.toString()
        if (needsServerLevel) {
            result = addImportIfMissing(result, "net.minecraft.server.level.ServerLevel")
        }
        if (needsEnchantmentHelper) {
            result = addImportIfMissing(result, "net.minecraft.world.item.enchantment.EnchantmentHelper")
        }
        if (needsDamageSource) {
            result = addImportIfMissing(result, "net.minecraft.world.damagesource.DamageSource")
        }
        return result
    }

    private fun inferDamageSourceForDoEnchantDamageEffects(source: String, callStatementStart: Int, targetExpression: String): String? {
        val methodStart = enclosingMethodRange(source, callStatementStart)?.first
            ?: source.lastIndexOf('{', callStatementStart).let { if (it < 0) 0 else it + 1 }
        val prefix = source.substring(methodStart, callStatementStart)
        val token = "$targetExpression.hurt("
        var cursor = 0
        var inferred: String? = null
        while (cursor < prefix.length) {
            val index = prefix.indexOf(token, cursor)
            if (index < 0) break
            val openParen = index + "$targetExpression.hurt".length
            val closeParen = findMatchingParen(prefix, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(prefix.substring(openParen + 1, closeParen))
            if (args.size >= 2) {
                inferred = args[0].trim()
            }
            cursor = closeParen + 1
        }
        if (inferred != null) {
            return inferred
        }
        return Regex("""\bDamageSource\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(prefix)
            .lastOrNull()
            ?.groupValues
            ?.get(1)
    }

    private fun migrateMethodCalls(
        source: String,
        methodToken: String,
        migrateArgs: (List<String>) -> List<String>
    ): String {
        val migrated = StringBuilder()
        var cursor = 0
        while (cursor < source.length) {
            val tokenIndex = source.indexOf(methodToken, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + methodToken.length
            if (openParen >= source.length || source[openParen] != '(') {
                migrated.append(source, cursor, openParen)
                cursor = openParen
                continue
            }
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break

            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            val migratedArgs = migrateArgs(args)
            migrated.append(source, cursor, openParen + 1)
            migrated.append(migratedArgs.joinToString(", ") { it.trim() })
            migrated.append(")")
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateLegacyRegistryObjectReflection(source: String): String {
        if (!source.contains("RegistryObject.class")) return source
        return source
            .replace("RegistryObject.class", "DeferredHolder.class")
            .replace("RegistryObject fields", "DeferredHolder fields")
    }

    private fun payloadPathName(className: String): String {
        val semanticName = className.removeSuffix("Packet").ifBlank { className }
        return semanticName.replace(Regex("([a-z])([A-Z])"), "$1_$2").lowercase()
    }

    private fun migrateNeoForgeGameTestResourceAssertions(source: String): String {
        if (!source.contains("@GameTest")) return source
        var result = source
        result = result.replace(
            "\"data/forge/loot_modifiers/global_loot_modifiers.json\"",
            "\"data/neoforge/loot_modifiers/global_loot_modifiers.json\""
        )
        result = result.replace("\"META-INF/mods.toml\"", "\"META-INF/neoforge.mods.toml\"")
        result = result.replace("block.contains(\"mandatory=false\")", "block.contains(\"type=\\\"optional\\\"\")")
        result = result.replace("forge:loot_table_id", "neoforge:loot_table_id")
        result = result.replace("minecraft:grass", "minecraft:short_grass")
        return result
    }

    private fun migrateLegacyItemAttributeModifierOverrides(projectDir: Path, dryRun: Boolean): List<Change> {
        val srcDir = projectDir.resolve("src/main/java")
        if (!srcDir.exists()) return emptyList()
        val mainClass = detectModMainClass(projectDir)
        val mainText = mainClass?.readText().orEmpty()
        val changes = mutableListOf<Change>()
        Files.walk(srcDir)
            .filter { it.toString().endsWith(".java") }
            .forEach { file ->
                val original = file.readText()
                if (!original.contains("getDefaultAttributeModifiers(EquipmentSlot") ||
                    !original.contains("new AttributeModifier(") ||
                    !original.contains("ImmutableMultimap")) {
                    return@forEach
                }
                val className = classNameOfJavaSource(original) ?: return@forEach
                val parentItem = Regex("""extends\s+([A-Za-z_$][\w$]*Item)\b""").find(original)
                    ?.groupValues
                    ?.get(1)
                    ?: return@forEach
                val legacyConstructor = Regex(
                    """public\s+${Regex.escape(className)}\s*\(\s*Tier\s+([A-Za-z_$][\w$]*)\s*,\s*Properties\s+([A-Za-z_$][\w$]*)\s*\)\s*\{\s*super\s*\(\s*\1\s*,\s*([^,]+)\s*,\s*([^,]+)\s*,\s*\2\s*\)\s*;"""
                ).find(original)
                val componentConstructor = Regex(
                    """public\s+${Regex.escape(className)}\s*\(\s*Tier\s+([A-Za-z_$][\w$]*)\s*,\s*Properties\s+([A-Za-z_$][\w$]*)\s*\)\s*\{\s*super\s*\(\s*\1\s*,\s*\2\.attributes\(\s*((?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*\.createAttributes)\(\s*\1\s*,\s*([^,]+)\s*,\s*([^)]+?)\s*\)\s*\)\s*\)\s*;"""
                ).find(original)
                if (legacyConstructor == null && componentConstructor == null) return@forEach
                val constructor = legacyConstructor ?: componentConstructor ?: return@forEach
                val tierName = constructor.groupValues[1]
                val propertiesName = constructor.groupValues[2]
                val baseAttributesFactory = componentConstructor?.groupValues?.get(3)?.trim()
                    ?: when (parentItem) {
                        "AxeItem", "HoeItem", "PickaxeItem", "ShovelItem" -> "net.minecraft.world.item.DiggerItem.createAttributes"
                        else -> "$parentItem.createAttributes"
                    }
                val damage = if (componentConstructor != null) constructor.groupValues[4].trim() else constructor.groupValues[3].trim()
                val speed = if (componentConstructor != null) constructor.groupValues[5].trim() else constructor.groupValues[4].trim()
                val methodText = javaMethodText(original, "getDefaultAttributeModifiers") ?: return@forEach
                val modifierLines = legacyItemAttributeModifierLines(methodText, file, mainClass, mainText)
                if (modifierLines.isEmpty()) return@forEach

                var migrated = original.replace(
                    constructor.value,
                    "public $className(Tier $tierName, Properties $propertiesName) {\n\t\tsuper($tierName, $propertiesName.attributes(create${className}Attributes($tierName, $damage, $speed)));"
                )
                migrated = removeMethodByNameContaining(
                    migrated,
                    "getDefaultAttributeModifiers",
                    listOf("ImmutableMultimap", "AttributeModifier")
                )
                val factory = """

	public static ItemAttributeModifiers create${className}Attributes(Tier tier, int damage, float speed) {
		return ${baseAttributesFactory}(tier, damage, speed)
${modifierLines.joinToString("\n")}
			;
	}
                """.trimEnd()
                val classOpen = Regex("""public\s+class\s+${Regex.escape(className)}\b[^{]*\{""").find(migrated)
                if (classOpen != null && !migrated.contains("create${className}Attributes(")) {
                    val insertAt = classOpen.range.last + 1
                    migrated = migrated.substring(0, insertAt) + factory + migrated.substring(insertAt)
                } else if (classOpen != null) {
                    val insertAt = classOpen.range.last + 1
                    migrated = migrated.substring(0, insertAt) + factory + migrated.substring(insertAt)
                }
                migrated = removeImportIfPresent(migrated, "com.google.common.collect.ImmutableMultimap")
                migrated = removeImportIfPresent(migrated, "com.google.common.collect.Multimap")
                migrated = removeImportIfPresent(migrated, "net.minecraft.world.entity.EquipmentSlot")
                migrated = removeImportIfPresent(migrated, "net.minecraft.world.entity.ai.attributes.Attribute")
                migrated = removeImportIfPresent(migrated, "net.neoforged.neoforge.common.NeoForgeMod")
                migrated = addImportIfMissing(migrated, "net.minecraft.world.entity.EquipmentSlotGroup")
                migrated = addImportIfMissing(migrated, "net.minecraft.world.entity.ai.attributes.Attributes")
                migrated = addImportIfMissing(migrated, "net.minecraft.world.item.component.ItemAttributeModifiers")

                if (migrated != original) {
                    if (!dryRun) file.writeText(migrated)
                    changes.add(Change(
                        file = file,
                        line = 1,
                        description = "Migrate legacy item attribute modifier override to 1.21 item attribute components",
                        before = "getDefaultAttributeModifiers(EquipmentSlot) + ImmutableMultimap",
                        after = "ItemAttributeModifiers factory on Item.Properties.attributes",
                        confidence = Confidence.HIGH,
                        ruleId = "struct-item-attribute-modifier-component"
                    ))
                }
            }
        return changes
    }

    private fun legacyItemAttributeModifierLines(
        methodText: String,
        file: Path,
        mainClass: Path?,
        mainText: String
    ): List<String> {
        val modRef = modIdReferenceForGeneratedClass(mainClass, mainText, packageNameOf(file.readText()))
        val modifierPattern = Regex(
            """attributeBuilder\.put\s*\(\s*([^,]+)\s*,\s*new\s+AttributeModifier\s*\(\s*[^,]+,\s*"([^"]+)"\s*,\s*([^,]+)\s*,\s*AttributeModifier\.Operation\.([A-Z_]+)\s*\)\s*\)\s*;"""
        )
        return modifierPattern.findAll(methodText).mapNotNull { match ->
            val attributeExpression = when (match.groupValues[1].trim()) {
                "NeoForgeMod.BLOCK_REACH.get()" -> "Attributes.BLOCK_INTERACTION_RANGE"
                "NeoForgeMod.ENTITY_REACH.get()" -> "Attributes.ENTITY_INTERACTION_RANGE"
                else -> return@mapNotNull null
            }
            val modifierName = modifierPathName(match.groupValues[2])
            val amount = match.groupValues[3].trim()
            val operation = match.groupValues[4].trim()
            "\t\t\t.withModifierAdded($attributeExpression, new AttributeModifier(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath($modRef, \"$modifierName\"), $amount, AttributeModifier.Operation.$operation), EquipmentSlotGroup.HAND)"
        }.toList()
    }

    private fun javaMethodText(source: String, methodName: String): String? {
        val nameMatch = Regex("""\b${Regex.escape(methodName)}\s*\(""").find(source) ?: return null
        val openBrace = source.indexOf('{', nameMatch.range.last)
        if (openBrace < 0) return null
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return null
        val lineStart = source.lastIndexOf('\n', nameMatch.range.first).let { if (it < 0) 0 else it + 1 }
        return source.substring(lineStart, closeBrace + 1)
    }

    private fun javaDeclaredMethodText(source: String, methodName: String): String? {
        val declaration = Regex(
            """(?m)^[ \t]*(?:@\w+(?:\([^)]*\))?\s*)*(?:public|protected|private)\s+(?:static\s+)?[\w<>\[\].?,\s]+\s+${Regex.escape(methodName)}\s*\("""
        ).find(source) ?: return null
        val openBrace = source.indexOf('{', declaration.range.last)
        if (openBrace < 0) return null
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return null
        return source.substring(declaration.range.first, closeBrace + 1)
    }

    private fun addSuppressWarningToMethodsContaining(
        source: String,
        warning: String,
        predicate: (String) -> Boolean
    ): String {
        val methodPattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\s*\r?\n[ \t]*)*(?:public|protected|private)\s+(?:static\s+)?(?:<[^>{};]+>\s*)?[\w<>\[\].?,\s]+\s+[A-Za-z_$][\w$]*\s*\([^;{}]*\)\s*(?:throws\s+[^{;]+)?\{"""
        )
        val starts = methodPattern.findAll(source)
            .mapNotNull { match ->
                val openBrace = source.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
                if (openBrace < 0 || closeBrace < 0) return@mapNotNull null
                val methodText = source.substring(match.range.first, closeBrace + 1)
                if (predicate(methodText)) match.range.first else null
            }
            .toList()
        var result = source
        for (start in starts.asReversed()) {
            result = addSuppressWarningToElementAt(result, start, warning)
        }
        return result
    }

    private fun addSuppressWarningToConstructorsContaining(
        source: String,
        className: String,
        warning: String,
        tokens: List<String>
    ): String =
        addSuppressWarningToConstructorsMatching(source, className, warning) { constructorText ->
            tokens.any { constructorText.contains(it) }
        }

    private fun addSuppressWarningToConstructorsMatching(
        source: String,
        className: String,
        warning: String,
        predicate: (String) -> Boolean
    ): String {
        val constructorPattern = Regex(
            """(?m)^[ \t]*(?:@[^\r\n]+\s*\r?\n[ \t]*)*(?:public|protected|private)\s+${Regex.escape(className)}\s*\([^;{}]*\)\s*(?:throws\s+[^{;]+)?\{"""
        )
        val starts = constructorPattern.findAll(source)
            .mapNotNull { match ->
                val openBrace = source.indexOf('{', match.range.last)
                val closeBrace = if (openBrace >= 0) findMatchingBrace(source, openBrace) else -1
                if (openBrace < 0 || closeBrace < 0) return@mapNotNull null
                val constructorText = source.substring(match.range.first, closeBrace + 1)
                if (predicate(constructorText)) match.range.first else null
            }
            .toList()
        var result = source
        for (start in starts.asReversed()) {
            result = addSuppressWarningToElementAt(result, start, warning)
        }
        return result
    }

    private fun addSuppressWarningToElementAt(source: String, elementStart: Int, warning: String): String {
        if (elementStart !in source.indices) return source
        val lineEnd = source.indexOf('\n', elementStart).let { if (it < 0) source.length else it }
        val firstLine = source.substring(elementStart, lineEnd)
        val indent = firstLine.takeWhile { it == ' ' || it == '\t' }
        val declarationStart = Regex("""(?m)^[ \t]*(?:public|protected|private|class)\b""")
            .find(source, elementStart)
            ?.range
            ?.first
            ?.takeIf { it >= elementStart }
            ?: elementStart
        val annotationBlock = source.substring(elementStart, declarationStart)
        val suppressMatch = Regex("""@SuppressWarnings\s*\(\s*(\{[^)]*}|"[^"]*")\s*\)""")
            .find(annotationBlock)
        if (suppressMatch != null) {
            if (suppressMatch.value.contains("\"$warning\"")) return source
            val absoluteStart = elementStart + suppressMatch.range.first
            val absoluteEnd = elementStart + suppressMatch.range.last + 1
            val body = suppressMatch.groupValues[1].trim()
            val replacement = if (body.startsWith("{")) {
                val inner = body.removePrefix("{").removeSuffix("}").trim()
                "@SuppressWarnings({$inner, \"$warning\"})"
            } else {
                "@SuppressWarnings({$body, \"$warning\"})"
            }
            return source.substring(0, absoluteStart) + replacement + source.substring(absoluteEnd)
        }
        return source.substring(0, elementStart) +
            "$indent@SuppressWarnings(\"$warning\")\n" +
            source.substring(elementStart)
    }

    private fun modifierPathName(text: String): String =
        text.trim()
            .lowercase()
            .replace(Regex("""[^a-z0-9]+"""), "_")
            .trim('_')

    private fun migratePayloadContextServerPlayer(source: String): String {
        if (!source.contains(".player()") || !source.contains("ServerPlayer")) return source
        return Regex(
            """(?m)^([ \t]*)ServerPlayer\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.player\(\);\s*\r?\n\1if\s*\(\s*\2\s*==\s*null\s*\)\s*return\s*;"""
        ).replace(source) { match ->
            "${match.groupValues[1]}if (!(${match.groupValues[3]}.player() instanceof ServerPlayer ${match.groupValues[2]})) return;"
        }
    }

    private fun migrateSupplierValueCalls(source: String): String {
        if (!source.contains(".value()") || !source.contains("Supplier<")) return source
        val supplierVariables = Regex("""\bSupplier\s*<[^;=\r\n]+>\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        if (supplierVariables.isEmpty()) return source
        var result = source
        supplierVariables.forEach { variable ->
            result = Regex("""\b${Regex.escape(variable)}\.value\(\)""").replace(result, "$variable.get()")
            result = Regex("""\bthis\.${Regex.escape(variable)}\.value\(\)""").replace(result, "this.$variable.get()")
        }
        return result
    }

    private fun migrateUnboundLevelRegistryAccessCalls(source: String): String {
        if (!source.contains("level.registryAccess()")) return source
        var result = source
        val methodPattern = Regex(
            """(?m)(?:^|\r?\n)[ \t]*(?:(?:@[A-Za-z_$][\w$]*(?:\([^)]*\))?\s*)*)(?:(?:public|protected|private|static|final|synchronized)\s+)+[A-Za-z_$][\w$<>\[\].?,\s]*\s+[A-Za-z_$][\w$]*\s*\(([^()]*)\)\s*\{"""
        )
        methodPattern.findAll(source).toList().asReversed().forEach { match ->
            val openBrace = source.indexOf('{', match.range.last - 1)
            if (openBrace < 0) return@forEach
            val closeBrace = findMatchingBrace(source, openBrace)
            if (closeBrace < 0) return@forEach
            val methodText = result.substring(match.range.first, closeBrace + 1)
            if (!methodText.contains("level.registryAccess()")) return@forEach
            val parameters = splitTopLevelJavaArgs(match.groupValues[1])
            val registryAccess = registryAccessFromParameters(parameters) ?: return@forEach
            val hasLevelBinding = Regex(
                """\b(?:ServerLevel|Level|WorldGenLevel|ServerLevelAccessor|LevelAccessor|LevelReader)\s+level\b"""
            ).containsMatchIn(methodText)
            if (hasLevelBinding) return@forEach
            val replacement = methodText.replace("level.registryAccess()", registryAccess)
            if (replacement != methodText) {
                result = result.substring(0, match.range.first) + replacement + result.substring(closeBrace + 1)
            }
        }
        return result
    }

    private fun migrateFoodComponentAccess(source: String): String {
        if (!source.contains(".getFoodProperties()") &&
            !source.contains(".getNutrition()") &&
            !source.contains(".getItem().has(")) {
            return source
        }
        var result = source
        val itemStackVariables = Regex("""\bItemStack\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        result = Regex(
            """(?m)^([ \t]*)Item\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]+);\s*\r?\n\1FoodProperties\s+([A-Za-z_$][\w$]*)\s*=\s*\2\.getFoodProperties\(\);"""
        ).replace(result) { match ->
            "${match.groupValues[1]}ItemStack stack = new ItemStack(${match.groupValues[3].trim()});\n" +
                "${match.groupValues[1]}FoodProperties ${match.groupValues[4]} = stack.get(DataComponents.FOOD);"
        }
        for (variable in itemStackVariables) {
            result = Regex("""\b${Regex.escape(variable)}\.getItem\(\)\.has\(\s*((?:net\.minecraft\.core\.component\.)?DataComponents\.[A-Za-z_$][\w$]*)\s*\)""")
                .replace(result) { match -> "$variable.has(${match.groupValues[1]})" }
        }
        result = result.replace(".getNutrition()", ".nutrition()")
        if (result.contains("DataComponents.FOOD")) {
            result = addImportIfMissing(result, "net.minecraft.core.component.DataComponents")
        }
        return result
    }

    private fun migrateNitrogenBlockStateRecipeConstructors(source: String): String {
        if (!source.contains("BlockStateIngredient") ||
            !source.contains("BlockPropertyPair") ||
            !source.contains("CacheableFunction") ||
            !source.contains("super(")) {
            return source
        }

        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var changed = false
        Regex("""class\s+($id)\s+extends\s+AbstractBlockStateRecipe\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { className ->
                val constructorPattern = Regex(
                    """(?s)public\s+${Regex.escape(className)}\s*\(\s*ResourceLocation\s+$id\s*,\s*BlockStateIngredient\s+($id)\s*,\s*BlockPropertyPair\s+($id)\s*,\s*@Nullable\s+CacheableFunction\s+($id)\s*\)\s*\{\s*super\(\s*([^,]+?)\s*,\s*$id\s*,\s*\1\s*,\s*\2\s*,\s*\3\s*\)\s*;\s*\}"""
                )
                result = constructorPattern.replace(result) { match ->
                    changed = true
                    val ingredient = match.groupValues[1]
                    val recipeResult = match.groupValues[2]
                    val function = match.groupValues[3]
                    val recipeType = match.groupValues[4].trim()
                    "public $className(BlockStateIngredient $ingredient, BlockPropertyPair $recipeResult, Optional<ResourceLocation> $function) {\n" +
                        "        super($recipeType, $ingredient, $recipeResult, $function);\n" +
                        "    }"
                }
            }

        Regex("""class\s+($id)\s+extends\s+AbstractBiomeParameterRecipe\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?.let { className ->
                val fullConstructorPattern = Regex(
                    """(?s)public\s+${Regex.escape(className)}\s*\(\s*ResourceLocation\s+$id\s*,\s*@Nullable\s+ResourceKey\s*<\s*Biome\s*>\s+($id)\s*,\s*@Nullable\s+TagKey\s*<\s*Biome\s*>\s+($id)\s*,\s*BlockStateIngredient\s+($id)\s*,\s*BlockPropertyPair\s+($id)\s*,\s*@Nullable\s+CacheableFunction\s+($id)\s*\)\s*\{\s*super\(\s*([^,]+?)\s*,\s*$id\s*,\s*\1\s*,\s*\2\s*,\s*\3\s*,\s*\4\s*,\s*\5\s*\)\s*;\s*\}"""
                )
                result = fullConstructorPattern.replace(result) { match ->
                    changed = true
                    val ingredient = match.groupValues[3]
                    val recipeResult = match.groupValues[4]
                    val function = match.groupValues[5]
                    val recipeType = match.groupValues[6].trim()
                    "public $className(Optional<Either<ResourceKey<Biome>, TagKey<Biome>>> biome, BlockStateIngredient $ingredient, BlockPropertyPair $recipeResult, Optional<ResourceLocation> $function) {\n" +
                        "        super($recipeType, biome, $ingredient, $recipeResult, $function);\n" +
                        "    }"
                }
                val simpleConstructorPattern = Regex(
                    """(?s)public\s+${Regex.escape(className)}\s*\(\s*ResourceLocation\s+$id\s*,\s*BlockStateIngredient\s+($id)\s*,\s*BlockPropertyPair\s+($id)\s*,\s*@Nullable\s+CacheableFunction\s+($id)\s*\)\s*\{\s*this\(\s*$id\s*,\s*null\s*,\s*null\s*,\s*\1\s*,\s*\2\s*,\s*\3\s*\)\s*;\s*\}"""
                )
                result = simpleConstructorPattern.replace(result) { match ->
                    changed = true
                    val ingredient = match.groupValues[1]
                    val recipeResult = match.groupValues[2]
                    val function = match.groupValues[3]
                    "public $className(BlockStateIngredient $ingredient, BlockPropertyPair $recipeResult, Optional<ResourceLocation> $function) {\n" +
                        "        this(Optional.empty(), $ingredient, $recipeResult, $function);\n" +
                        "    }"
                }
            }

        if (!changed) return source
        result = addImportIfMissing(result, "java.util.Optional")
        if (result.contains("Optional<Either<")) {
            result = addImportIfMissing(result, "com.mojang.datafixers.util.Either")
        }
        result = removeImport(result, "net.minecraft.commands.functions.CommandFunction")
        result = removeImport(result, "net.minecraft.commands.CacheableFunction")
        if (Regex("""\b@Nullable\b""").containsMatchIn(result)) {
            result = addImportIfMissing(result, "javax.annotation.Nullable")
        } else {
            result = removeImport(result, "javax.annotation.Nullable")
        }
        return result
    }

    private fun migrateNitrogenBiomeParameterRecipeSource(source: String): String {
        if (!source.contains("extends AbstractBlockStateRecipe") ||
            !source.contains("biomeKey") ||
            !source.contains("biomeTag") ||
            !source.contains("BlockStateIngredient") ||
            !source.contains("BlockPropertyPair") ||
            !source.contains("CacheableFunction")) {
            return source
        }

        val className = Regex("""class\s+([A-Za-z_$][\w$]*)\s+extends\s+AbstractBlockStateRecipe\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return source
        var result = source
        var changed = false
        result = Regex(
            """(?s)@Nullable\s*\r?\n\s*private\s+final\s+ResourceKey\s*<\s*Biome\s*>\s+biomeKey\s*;\s*@Nullable\s*\r?\n\s*private\s+final\s+TagKey\s*<\s*Biome\s*>\s+biomeTag\s*;"""
        ).replace(result) {
            changed = true
            "private final Optional<Either<ResourceKey<Biome>, TagKey<Biome>>> biome;"
        }
        result = Regex(
            """(?s)public\s+${Regex.escape(className)}\s*\(\s*RecipeType<\?>\s+type\s*,\s*ResourceLocation\s+id\s*,\s*@Nullable\s+ResourceKey\s*<\s*Biome\s*>\s+biomeKey\s*,\s*@Nullable\s+TagKey\s*<\s*Biome\s*>\s+biomeTag\s*,\s*BlockStateIngredient\s+ingredient\s*,\s*BlockPropertyPair\s+result\s*,\s*@Nullable\s+CacheableFunction\s+function\s*\)\s*\{\s*super\(\s*type\s*,\s*id\s*,\s*ingredient\s*,\s*result\s*,\s*function\s*\)\s*;\s*this\.biomeKey\s*=\s*biomeKey\s*;\s*this\.biomeTag\s*=\s*biomeTag\s*;\s*\}"""
        ).replace(result) {
            changed = true
            "public $className(RecipeType<?> type, Optional<Either<ResourceKey<Biome>, TagKey<Biome>>> biome, BlockStateIngredient ingredient, BlockPropertyPair result, Optional<ResourceLocation> function) {\n" +
                "        super(type, ingredient, result, function);\n" +
                "        this.biome = biome;\n" +
                "    }"
        }
        result = Regex(
            """(?s)if\s*\(\s*this\.biomeKey\s*!=\s*null\s*\)\s*\{\s*return\s+super\.matches\(\s*level\s*,\s*pos\s*,\s*state\s*\)\s*&&\s*level\.getBiome\(\s*pos\s*\)\.is\(\s*this\.biomeKey\s*\)\s*;\s*\}\s*else\s+if\s*\(\s*this\.biomeTag\s*!=\s*null\s*\)\s*\{\s*return\s+super\.matches\(\s*level\s*,\s*pos\s*,\s*state\s*\)\s*&&\s*level\.getBiome\(\s*pos\s*\)\.is\(\s*this\.biomeTag\s*\)\s*;"""
        ).replace(result) {
            changed = true
            "if (this.biome.isPresent() && this.biome.get().left().isPresent()) {\n" +
                "            return super.matches(level, pos, state) && level.getBiome(pos).is(this.biome.get().left().get());\n" +
                "        } else if (this.biome.isPresent() && this.biome.get().right().isPresent()) {\n" +
                "            return super.matches(level, pos, state) && level.getBiome(pos).is(this.biome.get().right().get());"
        }
        result = Regex(
            """(?s)@Nullable\s*\r?\n\s*public\s+ResourceKey\s*<\s*Biome\s*>\s+getBiomeKey\s*\(\s*\)\s*\{\s*return\s+this\.biomeKey\s*;\s*\}\s*@Nullable\s*\r?\n\s*public\s+TagKey\s*<\s*Biome\s*>\s+getBiomeTag\s*\(\s*\)\s*\{\s*return\s+this\.biomeTag\s*;\s*\}"""
        ).replace(result) {
            changed = true
            "public Optional<Either<ResourceKey<Biome>, TagKey<Biome>>> getBiome() {\n" +
                "        return this.biome;\n" +
                "    }"
        }
        if (!changed) return source
        result = addImportIfMissing(result, "com.mojang.datafixers.util.Either")
        result = addImportIfMissing(result, "java.util.Optional")
        result = removeImport(result, "net.minecraft.commands.functions.CommandFunction")
        result = removeImport(result, "net.minecraft.commands.CacheableFunction")
        if (!Regex("""\b@Nullable\b""").containsMatchIn(result)) {
            result = removeImport(result, "javax.annotation.Nullable")
        }
        return result
    }

    private fun migrateNitrogenBiomeParameterRecipeSerializerSource(source: String): String {
        if (!source.contains("extends BlockStateRecipeSerializer") ||
            !source.contains("CookieBaker") ||
            !source.contains("biomeRecipeDataFromJson") ||
            !source.contains("readBiomeKey") ||
            !source.contains("writeBiomeKey")) {
            return source
        }

        val packageLine = Regex("""(?m)^package\s+[^;]+;""").find(source)?.value ?: return source
        val recipeImport = Regex("""(?m)^import\s+([^;]+\.AbstractBiomeParameterRecipe);""")
            .find(source)
            ?.groupValues
            ?.get(1)
        val recipeImportLine = recipeImport?.let { "import $it;\n" }.orEmpty()
        val classMatch = Regex("""public\s+class\s+([A-Za-z_$][\w$]*)\s*<\s*T\s+extends\s+([A-Za-z_$][\w$]*)\s*>\s+extends\s+BlockStateRecipeSerializer\s*<\s*T\s*>""")
            .find(source)
            ?: return source
        val className = classMatch.groupValues[1]
        val recipeBase = classMatch.groupValues[2]

        return """
$packageLine

${recipeImportLine}import com.aetherteam.nitrogen.recipe.BlockPropertyPair;
import com.aetherteam.nitrogen.recipe.BlockStateIngredient;
import com.aetherteam.nitrogen.recipe.BlockStateRecipeUtil;
import com.aetherteam.nitrogen.recipe.recipes.AbstractBlockStateRecipe;
import com.aetherteam.nitrogen.recipe.serializer.BlockStateRecipeSerializer;
import com.mojang.datafixers.util.Either;
import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.tags.TagKey;
import net.minecraft.world.level.biome.Biome;

import java.util.Optional;

public class $className<T extends $recipeBase> extends BlockStateRecipeSerializer<T> {
    private final $className.Factory<T> factory;
    private final MapCodec<T> codec;

    public $className($className.Factory<T> factory, AbstractBlockStateRecipe.Factory<T> superFactory) {
        super(superFactory);
        this.factory = factory;
        this.codec = RecordCodecBuilder.mapCodec(inst -> inst.group(
                BlockStateRecipeUtil.KEY_CODEC.optionalFieldOf("biome").forGetter($recipeBase::getBiome),
                BlockStateIngredient.CODEC.fieldOf("ingredient").forGetter($recipeBase::getIngredient),
                BlockPropertyPair.CODEC.fieldOf("result").forGetter($recipeBase::getResult),
                ResourceLocation.CODEC.optionalFieldOf("mcfunction").forGetter($recipeBase::getFunctionId)
        ).apply(inst, factory::create));
    }

    @Override
    public MapCodec<T> codec() {
        return this.codec;
    }

    public T fromNetwork(RegistryFriendlyByteBuf buffer) {
        Optional<Either<ResourceKey<Biome>, TagKey<Biome>>> biome = buffer.readOptional(buf -> BlockStateRecipeUtil.STREAM_CODEC.decode((RegistryFriendlyByteBuf) buf));
        BlockStateIngredient ingredient = BlockStateIngredient.CONTENTS_STREAM_CODEC.decode(buffer);
        BlockPropertyPair result = BlockStateRecipeUtil.readPair(buffer);
        Optional<ResourceLocation> function = buffer.readOptional(FriendlyByteBuf::readResourceLocation);
        return this.factory.create(biome, ingredient, result, function);
    }

    public void toNetwork(RegistryFriendlyByteBuf buffer, T recipe) {
        buffer.writeOptional(recipe.getBiome(), (buf, either) -> BlockStateRecipeUtil.STREAM_CODEC.encode((RegistryFriendlyByteBuf) buf, either));
        super.toNetwork(buffer, recipe);
    }

    public interface Factory<T extends $recipeBase> {
        T create(Optional<Either<ResourceKey<Biome>, TagKey<Biome>>> biome, BlockStateIngredient ingredient, BlockPropertyPair result, Optional<ResourceLocation> function);
    }
}
""".trimStart()
    }

    private fun migrateCacheableFunctionOptionalBoundaries(source: String): String {
        if (!source.contains("CacheableFunction") ||
            (!source.contains("getFunction()") && !source.contains("BlockStateRecipeUtil.executeFunction("))) {
            return source
        }

        var result = source
        var changed = false
        result = Regex("""\bCacheableFunction\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\r\n]*\.getFunction\(\))\s*;""")
            .replace(result) { match ->
                changed = true
                "Optional<CacheableFunction> ${match.groupValues[1]} = ${match.groupValues[2].trim()};"
            }
        if (result.contains("BlockStateRecipeUtil.executeFunction(")) {
            result = Regex("""@Nullable\s+CacheableFunction\s+([A-Za-z_$][\w$]*)""")
                .replace(result) { match ->
                    changed = true
                    "Optional<CacheableFunction> ${match.groupValues[1]}"
                }
        }
        if (changed) {
            result = addImportIfMissing(result, "java.util.Optional")
        }
        return result
    }

    private fun migrateRecipeHolderAccess(source: String): String {
        if (!source.contains("RecipeManager") ||
            (!source.contains("rm.getRecipes()") && !source.contains("rm.byKey("))) {
            return source
        }
        var result = source
        result = result.replace("Collection<Recipe<?>> all = rm.getRecipes();", "Collection<RecipeHolder<?>> all = rm.getRecipes();")
        result = Regex("""for\s*\(\s*Recipe<\?>\s+([A-Za-z_$][\w$]*)\s*:\s*all\s*\)\s*\{""")
            .replace(result) { match ->
                "for (RecipeHolder<?> holder : all) {\n                Recipe<?> ${match.groupValues[1]} = holder.value();"
            }
        result = result.replace("private static Recipe<?> recipe(", "private static RecipeHolder<?> recipe(")
        result = result.replace("Recipe<?> r = recipe(", "RecipeHolder<?> r = recipe(")
        result = Regex("""\b([A-Za-z_$][\w$]*)\.getResultItem\(""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                if (receiver == "r") "$receiver.value().getResultItem(" else match.value
            }
        result = result.replace("RegistryAccess ra", "HolderLookup.Provider ra")
        result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        if (result.contains("HolderLookup.Provider")) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
            result = removeImport(result, "net.minecraft.core.RegistryAccess")
        }
        return result
    }

    private fun migrateLegacyItemMaxDamageCalls(source: String): String {
        if (!source.contains(".getMaxDamage()") || !Regex("""\bItem\s+[A-Za-z_$][\w$]*\b""").containsMatchIn(source)) {
            return source
        }
        var result = source
        val itemVariables = Regex("""\bItem\s+([A-Za-z_$][\w$]*)\b""")
            .findAll(source)
            .map { it.groupValues[1] }
            .toSet()
        for (variable in itemVariables) {
            result = Regex("""\b${Regex.escape(variable)}\.getMaxDamage\(\)""")
                .replace(result, "$variable.getDefaultInstance().getMaxDamage()")
        }
        return result
    }

    private fun migrateRecipeHolderIdAndLocalMmlibApi(source: String): String {
        if (!source.contains("RecipeHolder") &&
            !source.contains("RegistryAccess") &&
            !source.contains("trackRecipeExperience") &&
            !source.contains("BuiltInRegistries.RECIPE_SERIALIZER") &&
            !source.contains("recipe.setId(id)") &&
            !source.contains("recipe.getId()")) {
            return source
        }

        var result = source

        if (result.contains("DeferredRegister.create(BuiltInRegistries.RECIPE_SERIALIZER")) {
            result = result.replace(
                "DeferredRegister.create(BuiltInRegistries.RECIPE_SERIALIZER",
                "DeferredRegister.create(Registries.RECIPE_SERIALIZER"
            )
            result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
            if (!Regex("""\bBuiltInRegistries\.""").containsMatchIn(result)) {
                result = removeImport(result, "net.minecraft.core.registries.BuiltInRegistries")
            }
        }

        if (result.contains("getResultItem(RegistryAccess")) {
            result = Regex("""getResultItem\(\s*RegistryAccess\s+([A-Za-z_$][\w$]*)\s*\)""")
                .replace(result) { match -> "getResultItem(HolderLookup.Provider ${match.groupValues[1]})" }
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
            if (!Regex("""\bRegistryAccess\b""").containsMatchIn(removeImport(result, "net.minecraft.core.RegistryAccess"))) {
                result = removeImport(result, "net.minecraft.core.RegistryAccess")
            }
        }

        val holderListVariables = mutableMapOf<String, String>()
        val id = """[A-Za-z_$][\w$]*"""
        val recipeHolderListPattern = Regex(
            """(?s)List<($id)>\s+($id)\s*=\s*([^;]*getRecipesFor\([^;]*\))\.stream\(\)\.map\(RecipeHolder::value\)\.toList\(\);"""
        )
        result = recipeHolderListPattern.replace(result) { match ->
            val recipeType = match.groupValues[1]
            val listName = match.groupValues[2]
            val recipeCall = match.groupValues[3].trim()
            holderListVariables[listName] = recipeType
            "List<RecipeHolder<$recipeType>> $listName = $recipeCall;"
        }
        val directRecipeHolderListPattern = Regex(
            """(?s)List<($id)>\s+($id)\s*=\s*([^;]*getRecipesFor\([^;]*\))\s*;"""
        )
        result = directRecipeHolderListPattern.replace(result) { match ->
            val recipeType = match.groupValues[1]
            if (recipeType == "RecipeHolder" || recipeType == "ItemStack") {
                match.value
            } else {
                val listName = match.groupValues[2]
                val recipeCall = match.groupValues[3].trim()
                holderListVariables[listName] = recipeType
                "List<RecipeHolder<$recipeType>> $listName = $recipeCall;"
            }
        }

        val recipeVariablesInHolderLoops = mutableSetOf<String>()
        for ((listName, recipeType) in holderListVariables) {
            val loopPattern = Regex(
                """(?m)^([ \t]*)for\s*\(\s*$recipeType\s+([A-Za-z_$][\w$]*)\s*:\s*${Regex.escape(listName)}\s*\)\s*\{"""
            )
            result = loopPattern.replace(result) { match ->
                val indent = match.groupValues[1]
                val recipeVar = match.groupValues[2]
                recipeVariablesInHolderLoops.add(recipeVar)
                "${indent}for (RecipeHolder<$recipeType> holder : $listName) {\n${indent}    $recipeType $recipeVar = holder.value();"
            }
        }
        val optionalRecipeToHolderList = mutableMapOf<String, String>()
        for ((listName, recipeType) in holderListVariables) {
            val optionalStreamPattern = Regex(
                """Optional<$recipeType>\s+([A-Za-z_$][\w$]*)\s*=\s*${Regex.escape(listName)}\.stream\(\)(?!\s*\.map\(RecipeHolder::value\))"""
            )
            result = optionalStreamPattern.replace(result) { match ->
                val optionalName = match.groupValues[1]
                optionalRecipeToHolderList[optionalName] = listName
                "Optional<$recipeType> $optionalName = $listName.stream()\n                .map(RecipeHolder::value)"
            }
        }
        for (recipeVar in recipeVariablesInHolderLoops) {
            result = Regex("""lastRecipeID\s*=\s*${Regex.escape(recipeVar)}\.getId\(\)\s*;""")
                .replace(result, "lastRecipeID = holder.id();")
        }
        for ((optionalName, listName) in optionalRecipeToHolderList) {
            result = Regex("""lastRecipeID\s*=\s*${Regex.escape(optionalName)}\.get\(\)\.id\(\)\s*;""")
                .replace(
                    result,
                    "lastRecipeID = $listName.stream()\n                .filter(h -> h.value() == $optionalName.get()).findFirst()\n                .map(RecipeHolder::id).orElse(null);"
                )
        }

        val optionalHolderVariables = mutableSetOf<String>()
        val optionalRecipeHolderPattern = Regex(
            """(?s)Optional<($id)>\s+($id)\s*=\s*([^;]*getRecipeFor\([^;]*\))\.map\(RecipeHolder::value\)\s*;"""
        )
        result = optionalRecipeHolderPattern.replace(result) { match ->
            val recipeType = match.groupValues[1]
            val optionalName = match.groupValues[2]
            optionalHolderVariables.add(optionalName)
            "Optional<RecipeHolder<$recipeType>> $optionalName = ${match.groupValues[3].trim()};"
        }
        for (optionalName in optionalHolderVariables) {
            result = Regex("""return\s+${Regex.escape(optionalName)}\s*;""")
                .replace(result, "return Optional.of($optionalName.get().value());")
        }

        result = Regex("""lastRecipeID\s*=\s*([A-Za-z_$][\w$]*)\.get\(\)\.getId\(\)\s*;""")
            .replace(result) { match -> "lastRecipeID = ${match.groupValues[1]}.get().id();" }
        for ((optionalName, listName) in optionalRecipeToHolderList) {
            result = Regex("""lastRecipeID\s*=\s*${Regex.escape(optionalName)}\.get\(\)\.id\(\)\s*;""")
                .replace(
                    result,
                    "lastRecipeID = $listName.stream()\n                .filter(h -> h.value() == $optionalName.get()).findFirst()\n                .map(RecipeHolder::id).orElse(null);"
                )
        }

        Regex("""Optional<RecipeHolder<[^>]+>>\s+([A-Za-z_$][\w$]*)""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
            .forEach { optionalHolder ->
                result = Regex("""${Regex.escape(optionalHolder)}\.get\(\)\.(assemble|getResultItem)\(""")
                    .replace(result) { match -> "$optionalHolder.get().value().${match.groupValues[1]}(" }
            }

        result = migrateRecipeManagerByKeyHolderAccessSource(result)
        result = migrateLegacyRecipeBuilderResultIds(result)
        result = removeLegacyRecipeInstanceIdMethods(result)
        result = migrateRecipeExperienceTrackingSource(result)

        if (result.contains("RecipeHolder<")) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        }
        return result
    }

    private fun migrateRecipeHolderLoopTypeParameters(source: String): String {
        if (!source.contains("getAllRecipesFor(") || !source.contains("RecipeType<")) return source
        val id = """[A-Za-z_$][\w$]*"""
        var result = source
        var searchStart = 0
        val methodPattern = Regex(
            """<\s*($id)\s+extends\s+($id)\s*>[^{;]*?\([^)]*\bRecipeType\s*<\s*\1\s*>\s+($id)\b[^)]*\)\s*\{"""
        )
        var changed = false
        while (true) {
            val match = methodPattern.find(result, searchStart) ?: break
            val openBrace = match.range.last
            val closeBrace = findMatchingBrace(result, openBrace)
            if (closeBrace < 0) {
                searchStart = match.range.last + 1
                continue
            }

            val typeParam = match.groupValues[1]
            val superParam = match.groupValues[2]
            val recipeTypeVar = match.groupValues[3]
            val body = result.substring(openBrace + 1, closeBrace)
            val loopPattern = Regex(
                """for\s*\(\s*RecipeHolder\s*<\s*${Regex.escape(superParam)}\s*>\s+($id)\s*:\s*([^;\r\n]*getAllRecipesFor\s*\(\s*${Regex.escape(recipeTypeVar)}\s*\)[^;\r\n]*)\)"""
            )
            var migratedBody = loopPattern.replace(body) { loop ->
                "for (RecipeHolder<$typeParam> ${loop.groupValues[1]} : ${loop.groupValues[2]})"
            }
            val directLoopPattern = Regex(
                """(?m)^([ \t]*)for\s*\(\s*${Regex.escape(superParam)}\s+($id)\s*:\s*([^;\r\n]*getAllRecipesFor\s*\(\s*${Regex.escape(recipeTypeVar)}\s*\)[^;\r\n]*)\)\s*\{"""
            )
            migratedBody = directLoopPattern.replace(migratedBody) { loop ->
                val indent = loop.groupValues[1]
                val recipeVar = loop.groupValues[2]
                val recipeCall = loop.groupValues[3]
                "${indent}for (RecipeHolder<$typeParam> ${recipeVar}Holder : $recipeCall) {\n${indent}    $superParam $recipeVar = ${recipeVar}Holder.value();"
            }
            if (migratedBody != body) {
                changed = true
                result = result.substring(0, openBrace + 1) + migratedBody + result.substring(closeBrace)
                searchStart = openBrace + 1 + migratedBody.length
            } else {
                searchStart = closeBrace + 1
            }
        }
        if (changed) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        }
        return result
    }

    private fun migrateRecipeHolderInstanceofGetAllRecipesForLoops(source: String): String {
        if (!source.contains("getAllRecipesFor(") || !source.contains("instanceof")) return source
        val id = """[A-Za-z_$][\w$]*"""
        val loopPattern = Regex(
            """(?m)^([ \t]*)for\s*\(\s*Recipe\s*<\s*\?\s*>\s+($id)\s*:\s*([^;\r\n]*getAllRecipesFor\([^;\r\n]*\))\s*\)\s*\{"""
        )
        var result = source
        var cursor = 0
        var changed = false
        while (true) {
            val loop = loopPattern.find(result, cursor) ?: break
            val openBrace = result.indexOf('{', loop.range.last - 1)
            val closeBrace = if (openBrace >= 0) findMatchingBrace(result, openBrace) else -1
            if (openBrace < 0 || closeBrace < 0) {
                cursor = loop.range.last + 1
                continue
            }

            val recipeVar = loop.groupValues[2]
            val body = result.substring(openBrace + 1, closeBrace)
            val ifPattern = Regex("""(?s)^\s*if\s*\(\s*${Regex.escape(recipeVar)}\s+instanceof\s+($id)\s+($id)\s*\)\s*\{""")
            val ifMatch = ifPattern.find(body)
            if (ifMatch == null) {
                cursor = closeBrace + 1
                continue
            }
            val ifOpenBrace = ifMatch.range.last
            val ifCloseBrace = findMatchingBrace(body, ifOpenBrace)
            if (ifCloseBrace < 0 || body.substring(ifCloseBrace + 1).isNotBlank()) {
                cursor = closeBrace + 1
                continue
            }

            val indent = loop.groupValues[1]
            val recipeCall = loop.groupValues[3].trim()
            val recipeType = ifMatch.groupValues[1]
            val typedVar = ifMatch.groupValues[2]
            val innerBody = body.substring(ifOpenBrace + 1, ifCloseBrace).trimEnd()
            val declarationIndent = Regex("""\r?\n([ \t]*)\S""")
                .find(innerBody)
                ?.groupValues
                ?.get(1)
                ?: "$indent    "
            val replacement = "${indent}for (RecipeHolder<$recipeType> ${typedVar}Holder : $recipeCall) {\n" +
                "${declarationIndent}$recipeType $typedVar = ${typedVar}Holder.value();" +
                innerBody +
                "\n$indent}"
            result = result.substring(0, loop.range.first) + replacement + result.substring(closeBrace + 1)
            cursor = loop.range.first + replacement.length
            changed = true
        }
        if (!changed) return source
        result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
        if (!Regex("""\bRecipe\s*[<\[]""").containsMatchIn(removeImport(result, "net.minecraft.world.item.crafting.Recipe"))) {
            result = removeImport(result, "net.minecraft.world.item.crafting.Recipe")
        }
        return result
    }

    private fun migrateRecipeManagerByKeyHolderAccessSource(source: String): String {
        if (!source.contains(".byKey(") || !source.contains(".get()")) return source
        val id = """[A-Za-z_$][\w$]*"""
        return Regex("""(?s)byKey\(.*?\)\.ifPresent\(\s*($id)\s*->\s*(.*?)\)\s*;""")
            .replace(source) { match ->
                val recipeVar = match.groupValues[1]
                match.value.replace("$recipeVar.get()", "$recipeVar.value()")
            }
    }

    private fun migrateRecipeBookCategoryFinderRecipeHolders(source: String): String {
        if (!source.contains("registerRecipeCategoryFinder(") || !source.contains(" instanceof ")) return source
        val id = """[A-Za-z_$][\w$]*"""
        var changed = false
        val result = rewriteJavaCall(source, "registerRecipeCategoryFinder") { receiver, args ->
            if (args.size < 2) return@rewriteJavaCall null
            val lambda = args[1]
            val lambdaMatch = Regex(
                """(?s)^\s*(?:\(\s*(?:[\w$.\s?<>]+\s+)?($id)\s*\)|($id))\s*->\s*\{(.*)}\s*$"""
            ).find(lambda) ?: return@rewriteJavaCall null
            val recipeParam = (lambdaMatch.groupValues[1].ifBlank { lambdaMatch.groupValues[2] }).trim()
            val body = lambdaMatch.groupValues[3]
            val instanceOfPattern = Regex("""\b${Regex.escape(recipeParam)}\s+instanceof\b""")
            if (!instanceOfPattern.containsMatchIn(body)) return@rewriteJavaCall null
            val valueVarBase = "${recipeParam}Value"
            var valueVar = valueVarBase
            var suffix = 2
            while (Regex("""\b${Regex.escape(valueVar)}\b""").containsMatchIn(body)) {
                valueVar = "$valueVarBase$suffix"
                suffix++
            }
            val bodyIndent = Regex("""\r?\n([ \t]*)\S""")
                .find(body)
                ?.groupValues
                ?.get(1)
                ?: "    "
            val migratedBody = instanceOfPattern.replace(body) { "$valueVar instanceof" }
            val normalizedBody = if (migratedBody.startsWith("\n")) migratedBody else "\n$bodyIndent$migratedBody"
            changed = true
            val migratedLambda = "$recipeParam -> {\n${bodyIndent}var $valueVar = $recipeParam.value();$normalizedBody}"
            val migratedArgs = args.toMutableList()
            migratedArgs[1] = migratedLambda
            "$receiver.registerRecipeCategoryFinder(${migratedArgs.joinToString(", ") { it.trim() }})"
        }
        return if (changed) result else source
    }

    private fun migrateLegacyCraftingRecipeBoundaries(source: String): String {
        if (!source.contains("getRecipeManager()") &&
            !source.contains("CraftingContainer") &&
            !source.contains("Recipe<Container>") &&
            !(source.contains("CraftingInput") && source.contains("RegistryAccess"))) {
            return source
        }

        var result = source
        var needsCraftingInput = false
        var needsRecipeHolder = false
        var needsHolderLookup = false

        result = migrateLegacyRecordShapedCraftingRecipeSource(result)
        result = migrateLegacyGsonRegistryRecipeSerializerSource(result)
        result = migrateRecipeHolderLoopTypeParameters(result)
        result = migrateRecipeHolderInstanceofGetAllRecipesForLoops(result)

        val id = """[A-Za-z_$][\w$]*"""
        val annotations = """(?:@[A-Za-z0-9_.]+(?:\([^)]*\))?\s*)*"""
        result = Regex(
            """assemble\(\s*($annotations)CraftingInput\s+($id)\s*,\s*($annotations)RegistryAccess\s+($id)\s*\)"""
        ).replace(result) { match ->
            needsHolderLookup = true
            "assemble(${match.groupValues[1]}CraftingInput ${match.groupValues[2]}, ${match.groupValues[3]}HolderLookup.Provider ${match.groupValues[4]})"
        }
        if (needsHolderLookup) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
            if (!Regex("""\bRegistryAccess\b""").containsMatchIn(removeImport(result, "net.minecraft.core.RegistryAccess"))) {
                result = removeImport(result, "net.minecraft.core.RegistryAccess")
            }
        }

        if (result.contains("implements CraftingRecipe") && result.contains("CraftingContainer")) {
            result = Regex(
                """matches\(\s*($annotations)CraftingContainer\s+($id)\s*,\s*($annotations)Level\s+($id)\s*\)"""
            ).replace(result) { match ->
                needsCraftingInput = true
                "matches(${match.groupValues[1]}CraftingInput ${match.groupValues[2]}, ${match.groupValues[3]}Level ${match.groupValues[4]})"
            }
            result = Regex(
                """assemble\(\s*($annotations)CraftingContainer\s+($id)\s*,\s*($annotations)(HolderLookup\.Provider|RegistryAccess)\s+($id)\s*\)"""
            ).replace(result) { match ->
                needsCraftingInput = true
                if (match.groupValues[4] == "RegistryAccess") needsHolderLookup = true
                "assemble(${match.groupValues[1]}CraftingInput ${match.groupValues[2]}, ${match.groupValues[3]}HolderLookup.Provider ${match.groupValues[5]})"
            }
        }

        val craftingContainerVariables = Regex("""\bCraftingContainer\s+($id)\b""")
            .findAll(result)
            .map { it.groupValues[1] }
            .toSet()
        fun craftingInputArgument(arg: String): String {
            val trimmed = arg.trim()
            val receiver = trimmed.removePrefix("this.")
            return if (receiver in craftingContainerVariables && !trimmed.endsWith(".asCraftInput()")) {
                "$trimmed.asCraftInput()"
            } else {
                arg
            }
        }
        if (craftingContainerVariables.isNotEmpty()) {
            result = rewriteJavaInvocationArguments(result, "getRecipeFor") { args ->
                if (args.size >= 3 && args[0].trim() == "RecipeType.CRAFTING") {
                    val migrated = args.toMutableList()
                    migrated[1] = craftingInputArgument(args[1])
                    migrated.takeIf { it != args }
                } else {
                    null
                }
            }
            result = rewriteJavaInvocationArguments(result, "getRecipesFor") { args ->
                if (args.size >= 3 && args[0].trim() == "RecipeType.CRAFTING") {
                    val migrated = args.toMutableList()
                    migrated[1] = craftingInputArgument(args[1])
                    migrated.takeIf { it != args }
                } else {
                    null
                }
            }
            result = rewriteJavaInvocationArguments(result, "getRemainingItemsFor") { args ->
                if (args.size >= 3 && args[0].trim() == "RecipeType.CRAFTING") {
                    val migrated = args.toMutableList()
                    migrated[1] = craftingInputArgument(args[1])
                    migrated.takeIf { it != args }
                } else {
                    null
                }
            }
            result = Regex("""for\s*\(\s*Recipe\s*<\s*CraftingContainer\s*>\s+($id)\s*:\s*([^;\r\n]+?getRecipesFor\([^;\r\n]+?\))\s*\)\s*\{""")
                .replace(result) { match ->
                    val recipeVar = match.groupValues[1]
                    needsRecipeHolder = true
                    "for (RecipeHolder<CraftingRecipe> ${recipeVar}Holder : ${match.groupValues[2]}) {\n\t\t\tCraftingRecipe $recipeVar = ${recipeVar}Holder.value();"
                }
        }

        val recipeMatchesHolderVariables = mutableSetOf<String>()
        result = Regex(
            """(?m)(public\s+boolean\s+recipeMatches\s*\()\s*Recipe\s*<\s*\?\s+super\s+CraftingContainer\s*>\s+($id)\s*(\))"""
        ).replace(result) { match ->
            val recipeVar = match.groupValues[2]
            recipeMatchesHolderVariables.add(recipeVar)
            needsRecipeHolder = true
            "${match.groupValues[1]}RecipeHolder<CraftingRecipe> $recipeVar${match.groupValues[3]}"
        }
        for (recipeVar in recipeMatchesHolderVariables) {
            result = rewriteJavaCall(result, "matches") { receiver, args ->
                if (receiver != recipeVar || args.size != 2) return@rewriteJavaCall null
                val migratedInput = craftingInputArgument(args[0])
                if (migratedInput == args[0]) return@rewriteJavaCall null
                needsCraftingInput = true
                "$recipeVar.value().matches(${migratedInput.trim()}, ${args[1].trim()})"
            }
        }

        val recipeHolderLocalAssignments = mutableMapOf<String, String>()
        result = Regex("""(?m)^([ \t]*)CraftingRecipe\s+($id)\s*=\s*($id)\.get\(\)\s*;""")
            .replace(result) { match ->
                val optionalName = match.groupValues[3]
                val optionalHolderPattern = Regex(
                    """\bOptional\s*<\s*RecipeHolder\s*<\s*CraftingRecipe\s*>\s*>\s+${Regex.escape(optionalName)}\b"""
                )
                if (!optionalHolderPattern.containsMatchIn(result)) return@replace match.value
                val indent = match.groupValues[1]
                val recipeVar = match.groupValues[2]
                val holderVar = "${recipeVar}Holder"
                recipeHolderLocalAssignments[recipeVar] = holderVar
                needsRecipeHolder = true
                "${indent}RecipeHolder<CraftingRecipe> $holderVar = $optionalName.get();\n${indent}CraftingRecipe $recipeVar = $holderVar.value();"
            }
        for ((recipeVar, holderVar) in recipeHolderLocalAssignments) {
            result = rewriteJavaInvocationArguments(result, "setRecipeUsed") { args ->
                val migrated = args.map { arg ->
                    if (arg.trim() == recipeVar) holderVar else arg
                }
                migrated.takeIf { it != args }
            }
        }

        val filteredHolderListPattern = Regex(
            """(?s)List<($id)>\s+($id)\s*=\s*([^;]*getAllRecipesFor\([^;]*\))\s*;\s*\2\s*=\s*\2\.stream\(\)\.filter\(\s*($id)\s*->\s*(.*?)\)\s*(?://[^\r\n]*)?\s*\.collect\(Collectors\.toList\(\)\)\s*;"""
        )
        result = filteredHolderListPattern.replace(result) { match ->
            val recipeType = match.groupValues[1]
            val listName = match.groupValues[2]
            val recipeCall = match.groupValues[3].trim()
            val recipeVar = match.groupValues[4]
            val expression = match.groupValues[5]
                .replace("$recipeVar.getId()", "holder.id()")
                .trim()
            needsRecipeHolder = true
            """
List<$recipeType> $listName = $recipeCall.stream()
        .filter(holder -> {
            $recipeType $recipeVar = holder.value();
            return $expression;
        })
        .map(RecipeHolder::value)
        .collect(Collectors.toList());
""".trimEnd()
        }

        result = Regex("""new\s+ArrayList<>\(\s*([^;\r\n]*getAllRecipesFor\([^;\r\n]*\))\s*\)""")
            .replace(result) { match ->
                needsRecipeHolder = true
                "new ArrayList<>(${match.groupValues[1].trim()}.stream().map(RecipeHolder::value).toList())"
            }
        result = Regex("""([A-Za-z_$][\w$]*)\.addAll\(\s*([^;\r\n]*getAllRecipesFor\([^;\r\n]*\))\s*\)\s*;""")
            .replace(result) { match ->
                needsRecipeHolder = true
                "${match.groupValues[1]}.addAll(${match.groupValues[2].trim()}.stream().map(RecipeHolder::value).toList());"
            }
        result = Regex("""(registration\.addRecipes\(\s*[^,]+,\s*)([^;\r\n]*getAllRecipesFor\([^;\r\n]*\))(\s*\))""")
            .replace(result) { match ->
                needsRecipeHolder = true
                "${match.groupValues[1]}${match.groupValues[2].trim()}.stream().map(RecipeHolder::value).toList()${match.groupValues[3]}"
            }
        result = Regex("""(getAllRecipesFor\([^;\r\n]*\))\.forEach\(""")
            .replace(result) { match ->
                needsRecipeHolder = true
                "${match.groupValues[1]}.stream().map(RecipeHolder::value).forEach("
            }

        result = Regex("""for\s*\(\s*Recipe<\?>\s+($id)\s*:\s*([^;\r\n]*getRecipes\(\))\s*\)\s*\{""")
            .replace(result) { match ->
                val recipeVar = match.groupValues[1]
                needsRecipeHolder = true
                "for (RecipeHolder<?> ${recipeVar}Holder : ${match.groupValues[2]}) {\n\t\t\t\tRecipe<?> $recipeVar = ${recipeVar}Holder.value();"
            }
        result = Regex("""for\s*\(\s*($id)\s+($id)\s*:\s*([^;\r\n]*getAllRecipesFor\([^;\r\n]*\))\s*\)\s*\{""")
            .replace(result) { match ->
                val recipeType = match.groupValues[1]
                val recipeVar = match.groupValues[2]
                val recipeCall = match.groupValues[3]
                when (recipeType) {
                    "RecipeHolder" -> match.value
                    "var" -> {
                        needsRecipeHolder = true
                        "for (Object ${recipeVar}Holder : $recipeCall) {\n\t\t\t\tvar $recipeVar = ((RecipeHolder<?>) ${recipeVar}Holder).value();"
                    }
                    else -> {
                        needsRecipeHolder = true
                        "for (RecipeHolder<$recipeType> ${recipeVar}Holder : $recipeCall) {\n\t\t\t\t$recipeType $recipeVar = ${recipeVar}Holder.value();"
                    }
                }
            }
        result = Regex("""\b([A-Za-z_$][\w$]*)\.getId\(\)""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                if (result.contains("${receiver}Holder.value()")) {
                    "${receiver}Holder.id()"
                } else {
                    match.value
                }
            }

        val recipeArraySignature = Regex(
            """(?m)(@SuppressWarnings\([^)]*\)\s*)?private\s+static\s+CraftingRecipe\[\]\s+($id)\s*\(\s*CraftingContainer\s+($id)\s*,\s*Level\s+($id)\s*\)"""
        )
        result = recipeArraySignature.replace(result) { match ->
            needsCraftingInput = true
            needsRecipeHolder = true
            "${match.groupValues[1]}private static java.util.List<RecipeHolder<CraftingRecipe>> ${match.groupValues[2]}(CraftingInput ${match.groupValues[3]}, Level ${match.groupValues[4]})"
        }
        result = Regex("""toArray\(\s*new\s+CraftingRecipe\s*\[\s*0\s*]\s*\)""")
            .replace(result, "toList()")
        result = Regex("""(\bgetRecipeManager\(\)\.getRecipesFor\([^;\r\n]+?\))\.toList\(\)""")
            .replace(result, "$1")
        result = Regex("""(?m)^([ \t]*)private\s+void\s+chooseRecipe\s*\(\s*CraftingContainer\s+($id)\s*\)""")
            .replace(result) { match ->
                needsCraftingInput = true
                "${match.groupValues[1]}private void chooseRecipe(CraftingInput ${match.groupValues[2]})"
            }
        result = Regex("""chooseRecipe\(\s*((?:this\.)?$id)\s*\)""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                if (receiver.endsWith("Matrix") || receiver.endsWith("Container")) {
                    "chooseRecipe($receiver.asCraftInput())"
                } else {
                    match.value
                }
            }
        val chooseRecipeMethod = javaDeclaredMethodText(result, "chooseRecipe") ?: ""
        if (chooseRecipeMethod.contains("CraftingRecipe[] recipes = getRecipesFor(")) {
            val originalChooseRecipeMethod: String = chooseRecipeMethod
            var replacement: String = originalChooseRecipeMethod
            replacement = replacement.replace("CraftingRecipe[] recipes = getRecipesFor(", "java.util.List<RecipeHolder<CraftingRecipe>> recipes = getRecipesFor(")
            replacement = replacement.replace("recipes.length", "recipes.size()")
            replacement = Regex("""recipes\s*\[\s*([^\]]+)\s*]""")
                .replace(replacement) { match -> "recipes.get(${match.groupValues[1].trim()})" }
            replacement = Regex("""CraftingRecipe\s+($id)\s*=\s*recipes\.get\(""")
                .replace(replacement) { match -> "RecipeHolder<CraftingRecipe> ${match.groupValues[1]} = recipes.get(" }
            replacement = Regex("""\b($id)\.isSpecial\(\)""")
                .replace(replacement) { match ->
                    val receiver = match.groupValues[1]
                    if (replacement.contains("RecipeHolder<CraftingRecipe> $receiver")) {
                        "$receiver.value().isSpecial()"
                    } else {
                        match.value
                    }
                }
            replacement = Regex("""\b($id)\.assemble\(\s*($id)\s*,""")
                .replace(replacement) { match ->
                    val receiver = match.groupValues[1]
                    val input = match.groupValues[2]
                    if (replacement.contains("RecipeHolder<CraftingRecipe> $receiver")) {
                        "$receiver.value().assemble($input,"
                    } else {
                        match.value
                    }
                }
            replacement = Regex("""getRecipeBook\(\)\.contains\(\s*($id)\s*\)""")
                .replace(replacement) { match ->
                    val receiver = match.groupValues[1]
                    if (replacement.contains("RecipeHolder<CraftingRecipe> $receiver")) {
                        "getRecipeBook().contains($receiver.id())"
                    } else {
                        match.value
                    }
                }
            result = result.replace(originalChooseRecipeMethod, replacement)
            needsRecipeHolder = true
        }
        result = Regex("""\b($id)\.assemble\(\s*((?:this\.)?$id)\s*,""")
            .replace(result) { match ->
                val receiver = match.groupValues[1]
                val input = match.groupValues[2]
                val migratedInput = craftingInputArgument(input)
                if (migratedInput != input) {
                    needsCraftingInput = true
                    "$receiver.assemble(${migratedInput.trim()},"
                } else {
                    match.value
                }
            }

        result = migrateCraftingInputSizeCallsForDeclaredScopes(result)

        if (needsCraftingInput) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.CraftingInput")
            if (!Regex("""\bCraftingContainer\b""").containsMatchIn(removeImport(result, "net.minecraft.world.inventory.CraftingContainer"))) {
                result = removeImport(result, "net.minecraft.world.inventory.CraftingContainer")
            }
        }
        if (needsRecipeHolder) {
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeHolder")
            result = addImportIfMissing(result, "net.minecraft.world.item.crafting.CraftingRecipe")
            if (!Regex("""\bRecipe\s*<""").containsMatchIn(result)) {
                result = removeImport(result, "net.minecraft.world.item.crafting.Recipe")
            }
        }
        if (needsHolderLookup) {
            result = addImportIfMissing(result, "net.minecraft.core.HolderLookup")
            if (!Regex("""\bRegistryAccess\b""").containsMatchIn(removeImport(result, "net.minecraft.core.RegistryAccess"))) {
                result = removeImport(result, "net.minecraft.core.RegistryAccess")
            }
        }
        return result
    }

    private fun migrateLegacyRecordShapedCraftingRecipeSource(source: String): String {
        if (!source.contains("implements CraftingRecipe, ShapedRecipe") ||
            !source.contains("implements RecipeSerializer<") ||
            !source.contains("fromJson(") ||
            !source.contains("fromNetwork(") ||
            !source.contains("toNetwork(")) {
            return source
        }

        val declaration = Regex(
            """public\s+record\s+([A-Za-z_$][\w$]*)\s*\(\s*ResourceLocation\s+[A-Za-z_$][\w$]*\s*,\s*int\s+cost\s*,\s*int\s+width\s*,\s*int\s+height\s*,\s*Ingredient\s+input\s*,\s*int\s+count\s*,\s*NonNullList<Ingredient>\s+resultItems\s*\)\s+implements\s+CraftingRecipe\s*,\s*ShapedRecipe\s*"""
        ).find(source) ?: return source
        val className = declaration.groupValues[1]
        if (!source.contains("implements RecipeSerializer<$className>")) return source

        val openBrace = source.indexOf('{', declaration.range.last)
        if (openBrace < 0) return source
        val closeBrace = findMatchingBrace(source, openBrace)
        if (closeBrace < 0) return source

        val body = source.substring(openBrace + 1, closeBrace)
        val serializerExpr = Regex("""(?s)public\s+RecipeSerializer<\?>\s+getSerializer\(\)\s*\{\s*return\s+([^;]+);\s*\}""")
            .find(body)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: return source
        val recipeTypeExpr = Regex("""(?s)public\s+RecipeType<\?>\s+getType\(\)\s*\{\s*return\s+([^;]+);\s*\}""")
            .find(body)
            ?.groupValues
            ?.get(1)
            ?.trim()
            ?: return source

        var result = source.substring(0, declaration.range.first) +
            legacyRecordShapedCraftingRecipeClassBody(className, serializerExpr, recipeTypeExpr) +
            source.substring(closeBrace + 1)

        listOf(
            "com.google.common.collect.Maps",
            "com.google.common.collect.Sets",
            "com.google.gson.JsonArray",
            "com.google.gson.JsonElement",
            "com.google.gson.JsonObject",
            "com.google.gson.JsonSyntaxException",
            "net.minecraft.network.FriendlyByteBuf",
            "net.minecraft.resources.ResourceLocation",
            "net.minecraft.util.GsonHelper",
            "org.jetbrains.annotations.Nullable",
            "java.util.Map",
            "java.util.Set",
        ).forEach { result = removeImport(result, it) }
        result = addImportIfMissing(result, "com.mojang.serialization.Codec")
        result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
        result = addImportIfMissing(result, "com.mojang.serialization.codecs.RecordCodecBuilder")
        result = addImportIfMissing(result, "net.minecraft.network.RegistryFriendlyByteBuf")
        result = addImportIfMissing(result, "net.minecraft.network.codec.StreamCodec")
        result = addImportIfMissing(result, "net.minecraft.world.item.crafting.CraftingInput")
        result = addImportIfMissing(result, "net.minecraft.world.item.crafting.ShapedRecipePattern")
        return result
    }

    private fun legacyRecordShapedCraftingRecipeClassBody(
        className: String,
        serializerExpr: String,
        recipeTypeExpr: String
    ): String = """
public class $className extends ShapedRecipe {
    private final int cost;
    private final Ingredient input;
    private final int count;
    private final NonNullList<Ingredient> resultItems;

    public $className(int cost, int width, int height, Ingredient input, int count, NonNullList<Ingredient> resultItems) {
        this(cost, input, count, new ShapedRecipePattern(width, height, resultItems, java.util.Optional.empty()));
    }

    public $className(int cost, Ingredient input, int count, ShapedRecipePattern pattern) {
        super("uncrafting", CraftingBookCategory.MISC, pattern, new ItemStack(Items.AIR, count));
        this.cost = cost;
        this.input = input;
        this.count = count;
        this.resultItems = pattern.ingredients();
    }

    @Override
    public boolean matches(CraftingInput input, Level level) {
        return false;
    }

    @Override
    public ItemStack assemble(CraftingInput input, HolderLookup.Provider access) {
        return ItemStack.EMPTY;
    }

    public boolean isItemStackAnIngredient(ItemStack stack) {
        return java.util.Arrays.stream(this.input.getItems()).anyMatch(i -> stack.is(i.getItem()) && stack.getCount() >= this.count);
    }

    @Override
    public RecipeSerializer<?> getSerializer() {
        return $serializerExpr;
    }

    @Override
    public RecipeType<?> getType() {
        return $recipeTypeExpr;
    }

    @Override
    public NonNullList<Ingredient> getIngredients() {
        return this.resultItems;
    }

    public int cost() {
        return this.cost;
    }

    public int getCost() {
        return this.cost;
    }

    public Ingredient input() {
        return this.input;
    }

    public int count() {
        return this.count;
    }

    public int getCount() {
        return this.count;
    }

    public int width() {
        return this.pattern.width();
    }

    public int height() {
        return this.pattern.height();
    }

    public NonNullList<Ingredient> resultItems() {
        return this.resultItems;
    }

    public static class Serializer implements RecipeSerializer<$className> {
        public static final MapCodec<$className> CODEC = RecordCodecBuilder.mapCodec(instance -> instance.group(
                Codec.INT.optionalFieldOf("cost", -1).forGetter($className::cost),
                Ingredient.CODEC.fieldOf("input").forGetter($className::input),
                Codec.INT.optionalFieldOf("input_count", 1).forGetter($className::count),
                ShapedRecipePattern.MAP_CODEC.forGetter(recipe -> recipe.pattern)
        ).apply(instance, $className::new));

        public static final StreamCodec<RegistryFriendlyByteBuf, $className> STREAM_CODEC = StreamCodec.of(
                Serializer::toNetwork,
                Serializer::fromNetwork
        );

        @Override
        public MapCodec<$className> codec() {
            return CODEC;
        }

        @Override
        public StreamCodec<RegistryFriendlyByteBuf, $className> streamCodec() {
            return STREAM_CODEC;
        }

        private static $className fromNetwork(RegistryFriendlyByteBuf buffer) {
            int cost = buffer.readVarInt();
            Ingredient input = Ingredient.CONTENTS_STREAM_CODEC.decode(buffer);
            int count = buffer.readVarInt();
            ShapedRecipePattern pattern = ShapedRecipePattern.STREAM_CODEC.decode(buffer);
            return new $className(cost, input, count, pattern);
        }

        private static void toNetwork(RegistryFriendlyByteBuf buffer, $className recipe) {
            buffer.writeVarInt(recipe.cost);
            Ingredient.CONTENTS_STREAM_CODEC.encode(buffer, recipe.input);
            buffer.writeVarInt(recipe.count);
            ShapedRecipePattern.STREAM_CODEC.encode(buffer, recipe.pattern);
        }
    }
}
""".trimIndent()

    private data class RecipeComponentSpec(
        val type: String,
        val name: String,
        val localName: String,
        val jsonField: String,
        val registry: String? = null,
        val blockState: Boolean = false,
        val booleanField: Boolean = false
    )

    private fun migrateLegacyGsonRegistryRecipeSerializerSource(source: String): String {
        if (!source.contains("implements Recipe<Container>") ||
            !source.contains("implements RecipeSerializer<") ||
            !source.contains("fromJson(") ||
            !source.contains("fromNetwork(") ||
            !source.contains("toNetwork(")) {
            return source
        }

        val recordMatch = Regex(
            """public\s+record\s+([A-Za-z_$][\w$]*)\s*\(\s*ResourceLocation\s+([A-Za-z_$][\w$]*)\s*,\s*([^)]*?)\s*\)\s+implements\s+Recipe<Container>"""
        ).find(source) ?: return source
        val className = recordMatch.groupValues[1]
        val idComponent = recordMatch.groupValues[2]
        val componentText = recordMatch.groupValues[3].trim()
        if (!source.contains("implements RecipeSerializer<$className>")) return source

        val components = splitTopLevelJavaArgs(componentText).mapNotNull { component ->
            Regex("""(.+?)\s+([A-Za-z_$][\w$]*)$""")
                .find(component.trim())
                ?.let { it.groupValues[2] to it.groupValues[1].trim() }
        }
        if (components.isEmpty()) return source

        val fromJsonMethod = javaMethodText(source, "fromJson") ?: return source
        val fromNetworkMethod = javaMethodText(source, "fromNetwork") ?: return source
        val toNetworkMethod = javaMethodText(source, "toNetwork") ?: return source
        val constructorArgs = constructorArgsForClass(fromJsonMethod, className) ?: return source
        if (constructorArgs.size != components.size + 1) return source

        val jsonRegistryFields = Regex(
            """(?m)\b(Block|EntityType<\?>)\s+([A-Za-z_$][\w$]*)\s*=\s*BuiltInRegistries\.([A-Z_]+)\.get\(\s*ResourceLocation\.tryParse\(\s*GsonHelper\.getAsString\(\s*object\s*,\s*"([^"]+)"\s*\)\s*\)\s*\)\s*;"""
        ).findAll(fromJsonMethod).associateBy { it.groupValues[2] }
        val jsonBooleanFields = Regex(
            """(?m)\bboolean\s+([A-Za-z_$][\w$]*)\s*=\s*GsonHelper\.getAsBoolean\(\s*object\s*,\s*"([^"]+)"\s*\)\s*;"""
        ).findAll(fromJsonMethod).associateBy { it.groupValues[1] }

        val specs = mutableListOf<RecipeComponentSpec>()
        for ((index, component) in components.withIndex()) {
            val constructorArg = constructorArgs[index + 1].trim()
            val componentName = component.first
            val componentType = component.second
            val blockArg = Regex("""^([A-Za-z_$][\w$]*)\.defaultBlockState\(\)$""").find(constructorArg)
            if (blockArg != null && componentType == "BlockState") {
                val local = blockArg.groupValues[1]
                val registryMatch = jsonRegistryFields[local] ?: return source
                if (registryMatch.groupValues[3] != "BLOCK") return source
                specs.add(
                    RecipeComponentSpec(
                        type = componentType,
                        name = componentName,
                        localName = local,
                        jsonField = registryMatch.groupValues[4],
                        registry = "BLOCK",
                        blockState = true
                    )
                )
                continue
            }

            val registryMatch = jsonRegistryFields[constructorArg]
            if (registryMatch != null && componentType.startsWith("EntityType")) {
                specs.add(
                    RecipeComponentSpec(
                        type = componentType,
                        name = componentName,
                        localName = constructorArg,
                        jsonField = registryMatch.groupValues[4],
                        registry = registryMatch.groupValues[3]
                    )
                )
                continue
            }

            val booleanMatch = jsonBooleanFields[constructorArg]
            if (booleanMatch != null && componentType == "boolean") {
                specs.add(
                    RecipeComponentSpec(
                        type = componentType,
                        name = componentName,
                        localName = constructorArg,
                        jsonField = booleanMatch.groupValues[2],
                        booleanField = true
                    )
                )
                continue
            }
            return source
        }

        if (!serializerNetworkMatchesSpecs(fromNetworkMethod, toNetworkMethod, specs)) return source

        var result = source
        result = result.replaceRange(
            recordMatch.range,
            "public record $className($componentText) implements Recipe<RecipeInput>"
        )
        result = removeLegacyRecipeIdMethod(result, idComponent)
        result = removeLeadingRecipeIdConstructorArgument(result, className, components.size + 1)
        result = replaceNestedClass(result, "Serializer", legacyRegistryRecipeSerializerBody(className, specs))

        result = result.replace("matches(Container ", "matches(RecipeInput ")
        result = result.replace("assemble(Container ", "assemble(RecipeInput ")
        result = removeImport(result, "com.google.gson.JsonObject")
        result = removeImport(result, "com.google.gson.JsonParseException")
        result = removeImport(result, "net.minecraft.network.FriendlyByteBuf")
        result = removeImport(result, "net.minecraft.util.GsonHelper")
        result = removeImport(result, "org.jetbrains.annotations.Nullable")
        if (!Regex("""\bContainer\b""").containsMatchIn(removeImport(result, "net.minecraft.world.Container"))) {
            result = removeImport(result, "net.minecraft.world.Container")
        }
        if (!Regex("""\bResourceLocation\b""").containsMatchIn(removeImport(result, "net.minecraft.resources.ResourceLocation"))) {
            result = removeImport(result, "net.minecraft.resources.ResourceLocation")
        }
        result = addImportIfMissing(result, "com.mojang.serialization.MapCodec")
        if (specs.any { it.booleanField }) {
            result = addImportIfMissing(result, "com.mojang.serialization.Codec")
        }
        result = addImportIfMissing(result, "com.mojang.serialization.codecs.RecordCodecBuilder")
        result = addImportIfMissing(result, "net.minecraft.network.RegistryFriendlyByteBuf")
        result = addImportIfMissing(result, "net.minecraft.network.codec.StreamCodec")
        result = addImportIfMissing(result, "net.minecraft.world.item.crafting.RecipeInput")
        result = addImportIfMissing(result, "net.minecraft.core.registries.Registries")
        if (result.contains("BuiltInRegistries.")) {
            result = addImportIfMissing(result, "net.minecraft.core.registries.BuiltInRegistries")
        }
        return result
    }

    private fun constructorArgsForClass(source: String, className: String): List<String>? {
        val pattern = Regex("""new\s+${Regex.escape(className)}\s*\(""")
        val match = pattern.find(source) ?: return null
        val openParen = match.range.last
        val closeParen = findMatchingParen(source, openParen)
        if (closeParen < 0) return null
        return splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
    }

    private fun serializerNetworkMatchesSpecs(fromNetwork: String, toNetwork: String, specs: List<RecipeComponentSpec>): Boolean {
        for (spec in specs) {
            if (spec.blockState) {
                if (!Regex("""\bBlock\s+${Regex.escape(spec.localName)}\s*=\s*buffer\.readRegistryIdUnsafe\(BuiltInRegistries\.BLOCK\)""").containsMatchIn(fromNetwork)) {
                    return false
                }
                if (!Regex("""buffer\.writeRegistryIdUnsafe\(BuiltInRegistries\.BLOCK,\s*recipe\.${Regex.escape(spec.name)}\(\)\.getBlock\(\)\s*\)""").containsMatchIn(toNetwork)) {
                    return false
                }
            } else if (spec.registry == "ENTITY_TYPE") {
                if (!Regex("""\bEntityType<\?>\s+${Regex.escape(spec.localName)}\s*=\s*buffer\.readRegistryIdUnsafe\(BuiltInRegistries\.ENTITY_TYPE\)""").containsMatchIn(fromNetwork)) {
                    return false
                }
                if (!Regex("""buffer\.writeRegistryIdUnsafe\(BuiltInRegistries\.ENTITY_TYPE,\s*recipe\.${Regex.escape(spec.name)}\(\)\s*\)""").containsMatchIn(toNetwork)) {
                    return false
                }
            } else if (spec.booleanField) {
                if (!Regex("""\bboolean\s+${Regex.escape(spec.localName)}\s*=\s*buffer\.readBoolean\(\)""").containsMatchIn(fromNetwork)) {
                    return false
                }
                if (!Regex("""buffer\.writeBoolean\(\s*recipe\.${Regex.escape(spec.name)}\(\)\s*\)""").containsMatchIn(toNetwork)) {
                    return false
                }
            }
        }
        return true
    }

    private fun removeLegacyRecipeIdMethod(source: String, idComponent: String): String =
        Regex(
            """(?s)\s*@Override\s*\r?\n\s*public\s+ResourceLocation\s+getId\(\)\s*\{\s*return\s+this\.${Regex.escape(idComponent)}\s*;\s*\}\s*"""
        ).replace(source, "\n\n")

    private fun removeLeadingRecipeIdConstructorArgument(source: String, className: String, oldArgCount: Int): String {
        val pattern = Regex("""new\s+${Regex.escape(className)}\s*\(""")
        val migrated = StringBuilder()
        var cursor = 0
        var changed = false
        while (cursor < source.length) {
            val match = pattern.find(source, cursor) ?: break
            val openParen = match.range.last
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size == oldArgCount) {
                migrated.append(source, cursor, match.range.first)
                migrated.append("new $className(")
                migrated.append(args.drop(1).joinToString(", ") { it.trim() })
                migrated.append(")")
                cursor = closeParen + 1
                changed = true
            } else {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
            }
        }
        if (!changed) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun legacyRegistryRecipeSerializerBody(className: String, specs: List<RecipeComponentSpec>): String {
        val codecFields = specs.joinToString(",\n") { spec ->
            when {
                spec.blockState ->
                    """                        BuiltInRegistries.BLOCK.byNameCodec().fieldOf("${spec.jsonField}").forGetter(recipe -> recipe.${spec.name}().getBlock())"""
                spec.registry == "ENTITY_TYPE" ->
                    """                        BuiltInRegistries.ENTITY_TYPE.byNameCodec().fieldOf("${spec.jsonField}").forGetter($className::${spec.name})"""
                spec.booleanField ->
                    """                        Codec.BOOL.fieldOf("${spec.jsonField}").forGetter($className::${spec.name})"""
                else -> error("Unsupported recipe component spec: $spec")
            }
        }
        val lambdaArgs = specs.joinToString(", ") { it.localName }
        val constructorArgs = specs.joinToString(", ") { spec ->
            if (spec.blockState) "${spec.localName}.defaultBlockState()" else spec.localName
        }
        val decodeLines = specs.joinToString("\n") { spec ->
            when {
                spec.blockState ->
                    """                    Block ${spec.localName} = net.minecraft.network.codec.ByteBufCodecs.registry(Registries.BLOCK).decode(buffer);"""
                spec.registry == "ENTITY_TYPE" ->
                    """                    EntityType<?> ${spec.localName} = net.minecraft.network.codec.ByteBufCodecs.registry(Registries.ENTITY_TYPE).decode(buffer);"""
                spec.booleanField ->
                    """                    boolean ${spec.localName} = buffer.readBoolean();"""
                else -> error("Unsupported recipe component spec: $spec")
            }
        }
        val encodeLines = specs.joinToString("\n") { spec ->
            when {
                spec.blockState ->
                    """                    net.minecraft.network.codec.ByteBufCodecs.registry(Registries.BLOCK).encode(buffer, recipe.${spec.name}().getBlock());"""
                spec.registry == "ENTITY_TYPE" ->
                    """                    net.minecraft.network.codec.ByteBufCodecs.registry(Registries.ENTITY_TYPE).encode(buffer, recipe.${spec.name}());"""
                spec.booleanField ->
                    """                    buffer.writeBoolean(recipe.${spec.name}());"""
                else -> error("Unsupported recipe component spec: $spec")
            }
        }
        return """
            public static class Serializer implements RecipeSerializer<$className> {
                private static final MapCodec<$className> CODEC = RecordCodecBuilder.mapCodec(instance -> instance.group(
$codecFields
                ).apply(instance, ($lambdaArgs) -> new $className($constructorArgs)));

                private static final StreamCodec<RegistryFriendlyByteBuf, $className> STREAM_CODEC = StreamCodec.of(
                        Serializer::toNetwork,
                        Serializer::fromNetwork
                );

                @Override
                public MapCodec<$className> codec() {
                    return CODEC;
                }

                @Override
                public StreamCodec<RegistryFriendlyByteBuf, $className> streamCodec() {
                    return STREAM_CODEC;
                }

                private static $className fromNetwork(RegistryFriendlyByteBuf buffer) {
$decodeLines
                    return new $className($constructorArgs);
                }

                private static void toNetwork(RegistryFriendlyByteBuf buffer, $className recipe) {
$encodeLines
                }
            }
        """.trimIndent()
    }

    private fun migrateLegacyRecipeBuilderResultIds(source: String): String {
        if (!source.contains("recipe.setId(id)") && !source.contains("recipe.getId()")) return source
        var result = source
        result = result.replace("consumer.accept(result.getId(), result.recipe, null);", "consumer.accept(id, result.recipe, null);")
        result = Regex("""(?m)^([ \t]*)(private\s+final\s+[A-Za-z_$][\w$]*Recipe\s+recipe\s*=\s*new\s+[A-Za-z_$][\w$]*Recipe\(\);\s*)$""")
            .replace(result) { match ->
                val indent = match.groupValues[1]
                if (result.substring(0, match.range.first).takeLast(200).contains("private final ResourceLocation id;")) {
                    match.value
                } else {
                    "${indent}private final ResourceLocation id;\n${match.value}"
                }
            }
        result = result.replace("recipe.setId(id);", "this.id = id;")
        result = result.replace("return recipe.getId();", "return this.id;")
        return result
    }

    private fun removeLegacyRecipeInstanceIdMethods(source: String): String {
        if (!source.contains("extends AbstractRecipe")) return source
        if (!source.contains("getId()") || !source.contains("return this.id;")) return source
        var result = Regex(
            """(?s)\s*@Override\s*\r?\n\s*public\s+ResourceLocation\s+getId\(\)\s*\{\s*return\s+this\.id\s*;\s*\}\s*"""
        ).replace(source, "\n")
        if (!Regex("""\bResourceLocation\b""").containsMatchIn(removeImport(result, "net.minecraft.resources.ResourceLocation"))) {
            result = removeImport(result, "net.minecraft.resources.ResourceLocation")
        }
        return result
    }

    private fun migrateRecipeExperienceTrackingSource(source: String): String {
        if (!source.contains("trackRecipeExperience")) return source
        var result = source
        if (result.contains("lastRecipeID")) {
            result = Regex("""trackRecipeExperience\(\s*([A-Za-z_$][\w$]*)\s*\)\s*;""")
                .replace(result) { match ->
                    if (match.groupValues[1] == "lastRecipeID") {
                        match.value
                    } else {
                        "trackRecipeExperience(lastRecipeID);"
                    }
                }
        }
        result = Regex(
            """(?s)public\s+void\s+trackRecipeExperience\(\s*@Nullable\s+Recipe<\?>\s+recipe\s*\)\s*\{\s*if\s*\(\s*recipe\s*!=\s*null\s*\)\s*\{.*?experienceTracker\.addTo\(\s*recipeID\s*,\s*1\s*\)\s*;\s*\}\s*\}"""
        ).replace(result) {
            """public void trackRecipeExperience(@Nullable ResourceLocation recipeId) {
        if (recipeId != null) {
            experienceTracker.addTo(recipeId, 1);
        }
    }"""
        }
        result = Regex(
            """(?s)public\s+void\s+trackRecipeExperience\(\s*@Nullable\s+Recipe<\?>\s+recipe\s*\)\s*\{\s*if\s*\(\s*recipe\s*!=\s*null\s*\)\s*\{\s*ResourceLocation\s+recipeID\s*=\s*recipe\.getId\(\)\s*;\s*(.*?)\s*\}\s*\}"""
        ).replace(result) { match ->
            val body = match.groupValues[1].replace("recipeID", "recipeId").trimEnd()
            """public void trackRecipeExperience(@Nullable ResourceLocation recipeId) {
        if (recipeId != null) {
            $body
        }
    }"""
        }
        if (!Regex("""\bRecipe\s*<""").containsMatchIn(result)) {
            result = removeImport(result, "net.minecraft.world.item.crafting.Recipe")
        }
        return result
    }

    private fun migrateMerchantOfferItemCosts(source: String): String {
        if (!source.contains("new MerchantOffer(") || !source.contains("ItemStack")) return source

        val stackCosts = mutableMapOf<String, String>()
        val assignmentPattern = Regex("""ItemStack\s+([A-Za-z_$][\w$]*)\s*=\s*new\s+ItemStack\s*\(""")
        assignmentPattern.findAll(source).forEach { match ->
            val openParen = match.range.last
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) return@forEach
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size >= 2) {
                stackCosts[match.groupValues[1]] =
                    "new net.minecraft.world.item.trading.ItemCost(${args[0].trim()}, ${args[1].trim()})"
            }
        }
        if (stackCosts.isEmpty()) return source

        val migrated = StringBuilder()
        var cursor = 0
        val constructorPattern = Regex("""new\s+MerchantOffer\s*\(""")
        while (cursor < source.length) {
            val match = constructorPattern.find(source, cursor) ?: break
            val openParen = match.range.last
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break
            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size == 6 && args[1].trim() == "ItemStack.EMPTY") {
                val firstArg = args[0].trim()
                val cost = stackCosts[firstArg]
                if (cost != null) {
                    migrated.append(source, cursor, match.range.first)
                    migrated.append("new MerchantOffer(")
                    migrated.append(cost)
                    migrated.append(", java.util.Optional.empty(), ")
                    migrated.append(args.drop(2).joinToString(", ") { it.trim() })
                    migrated.append(")")
                    cursor = closeParen + 1
                    continue
                }
            }
            migrated.append(source, cursor, closeParen + 1)
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateCopiedCustomDataWrites(source: String): String {
        if (!source.contains("DataComponents.CUSTOM_DATA") || !source.contains(".copyTag()")) return source
        return Regex(
            """(?m)^([ \t]*)net\.minecraft\.nbt\.CompoundTag\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*)\.getOrDefault\(net\.minecraft\.core\.component\.DataComponents\.CUSTOM_DATA,\s*net\.minecraft\.world\.item\.component\.CustomData\.EMPTY\)\.copyTag\(\);\s*\r?\n\1\2\.put\(([^;]+);\s*(?!\r?\n\1\3\.set\(net\.minecraft\.core\.component\.DataComponents\.CUSTOM_DATA)"""
        ).replace(source) { match ->
            val indent = match.groupValues[1]
            val tag = match.groupValues[2]
            val stack = match.groupValues[3]
            val putArgs = match.groupValues[4].trim().removeSuffix(")")
            "${indent}net.minecraft.nbt.CompoundTag $tag = $stack.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA, net.minecraft.world.item.component.CustomData.EMPTY).copyTag();\n" +
                "$indent$tag.put($putArgs);\n" +
                "$indent$stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA, net.minecraft.world.item.component.CustomData.of($tag));"
        }
    }

    private fun migrateVanillaToolItemConstructors(source: String): String {
        val constructorPattern = Regex("""new\s+((?:net\.minecraft\.world\.item\.)?(?:AxeItem|PickaxeItem|HoeItem|ShovelItem))\s*\(""")
        val migrated = StringBuilder()
        var cursor = 0
        while (cursor < source.length) {
            val match = constructorPattern.find(source, cursor) ?: break
            val openParen = match.range.last
            val closeParen = findMatchingParen(source, openParen)
            if (closeParen < 0) break

            val args = splitTopLevelJavaArgs(source.substring(openParen + 1, closeParen))
            if (args.size != 4) {
                migrated.append(source, cursor, closeParen + 1)
                cursor = closeParen + 1
                continue
            }

            val tier = args[0].trim()
            val attackDamage = args[1].trim()
            val attackSpeed = args[2].trim()
            val properties = args[3].trim()
            migrated.append(source, cursor, match.range.first)
            migrated.append("new ")
            migrated.append(match.groupValues[1])
            migrated.append("(")
            migrated.append(tier)
            migrated.append(", ")
            migrated.append(properties)
            migrated.append(".attributes(net.minecraft.world.item.DiggerItem.createAttributes(")
            migrated.append(tier)
            migrated.append(", ")
            migrated.append(attackDamage)
            migrated.append(", ")
            migrated.append(attackSpeed)
            migrated.append(")))")
            cursor = closeParen + 1
        }
        if (cursor == 0) return source
        migrated.append(source, cursor, source.length)
        return migrated.toString()
    }

    private fun migrateMmlibBlockLootConstructor(source: String): String {
        if (!source.contains("extends AbstartctBlockLoot")) return source
        val className = Regex("""class\s+([A-Za-z_$][\w$]*)\s+extends\s+AbstartctBlockLoot\b""")
            .find(source)
            ?.groupValues
            ?.get(1)
            ?: return source
        if (source.contains("$className(net.minecraft.core.HolderLookup.Provider provider)") ||
            source.contains("$className(HolderLookup.Provider provider)")) {
            return source
        }

        var result = source
        result = Regex(
            """(?s)\s*public\s+${Regex.escape(className)}\s*\(\s*Set\s*<\s*Item\s*>\s+([A-Za-z_$][\w$]*)\s*\)\s*\{\s*super\(\s*\1\s*\);\s*\}\s*"""
        ).replace(result, "\n")
        result = Regex(
            """(?s)\s*public\s+${Regex.escape(className)}\s*\(\s*\)\s*\{\s*super\(\s*Set\.of\(\)\s*\);\s*\}\s*"""
        ).replace(result, "\n")

        val constructor = """

    public $className(net.minecraft.core.HolderLookup.Provider provider) {
        super(provider);
    }
""".trimEnd()
        val classHeaderPattern = Regex("""public\s+class\s+${Regex.escape(className)}\s+extends\s+AbstartctBlockLoot\s*\{\s*""")
        val classHeader = classHeaderPattern.find(result) ?: return result
        result = result.substring(0, classHeader.range.first) +
            classHeader.value.trimEnd() +
            constructor +
            "\n" +
            result.substring(classHeader.range.last + 1)
        if (!result.contains("Set<")) {
            result = removeImport(result, "java.util.Set")
        }
        if (!result.contains(" Item") && !result.contains("<Item>")) {
            result = removeImport(result, "net.minecraft.world.item.Item")
        }
        return result
    }

    private fun findMatchingParen(source: String, openParen: Int): Int {
        var depth = 0
        var inString = false
        var escaped = false
        for (i in openParen until source.length) {
            val ch = source[i]
            if (inString) {
                escaped = ch == '\\' && !escaped
                if (ch == '"' && !escaped) inString = false
                if (ch != '\\') escaped = false
                continue
            }
            when (ch) {
                '"' -> inString = true
                '(' -> depth++
                ')' -> {
                    depth--
                    if (depth == 0) return i
                }
            }
        }
        return -1
    }

    private fun rewriteJavaCall(
        source: String,
        methodName: String,
        transform: (receiver: String, args: List<String>) -> String?
    ): String {
        var result = source
        var cursor = 0
        val token = ".${methodName}("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + methodName.length + 1
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val receiverStart = findExpressionReceiverStart(result, tokenIndex)
            if (receiverStart < 0 || receiverStart >= tokenIndex) {
                cursor = closeParen + 1
                continue
            }
            val receiver = result.substring(receiverStart, tokenIndex).trim()
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val replacement = transform(receiver, args)
            if (replacement == null) {
                cursor = closeParen + 1
                continue
            }
            result = result.substring(0, receiverStart) + replacement + result.substring(closeParen + 1)
            cursor = receiverStart + replacement.length
        }
        return result
    }

    private fun rewriteJavaCallWithOffset(
        source: String,
        methodName: String,
        transform: (receiver: String, args: List<String>, callOffset: Int) -> String?
    ): String {
        var result = source
        var cursor = 0
        val token = ".${methodName}("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + methodName.length + 1
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val receiverStart = findExpressionReceiverStart(result, tokenIndex)
            if (receiverStart < 0 || receiverStart >= tokenIndex) {
                cursor = closeParen + 1
                continue
            }
            val receiver = result.substring(receiverStart, tokenIndex).trim()
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val replacement = transform(receiver, args, tokenIndex)
            if (replacement == null) {
                cursor = closeParen + 1
                continue
            }
            result = result.substring(0, receiverStart) + replacement + result.substring(closeParen + 1)
            cursor = receiverStart + replacement.length
        }
        return result
    }

    private fun rewriteJavaInvocationArguments(
        source: String,
        methodName: String,
        transform: (args: List<String>) -> List<String>?
    ): String {
        var result = source
        var cursor = 0
        val token = "$methodName("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            if (tokenIndex > 0 && (result[tokenIndex - 1].isLetterOrDigit() || result[tokenIndex - 1] == '_' || result[tokenIndex - 1] == '$')) {
                cursor = tokenIndex + token.length
                continue
            }
            val openParen = tokenIndex + methodName.length
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val originalArgsSource = result.substring(openParen + 1, closeParen)
            val args = splitTopLevelJavaArgs(originalArgsSource)
            val migratedArgs = transform(args)
            if (migratedArgs == null || migratedArgs == args) {
                cursor = closeParen + 1
                continue
            }
            val replacementArgs = migratedArgs.joinToString(", ") { it.trim() }
            result = result.substring(0, openParen + 1) + replacementArgs + result.substring(closeParen)
            cursor = openParen + 1 + replacementArgs.length
        }
        return result
    }

    private fun rewriteJavaInvocationArgumentsWithOffset(
        source: String,
        methodName: String,
        transform: (args: List<String>, offset: Int) -> List<String>?
    ): String {
        var result = source
        var cursor = 0
        val token = "$methodName("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            if (tokenIndex > 0 && (result[tokenIndex - 1].isLetterOrDigit() || result[tokenIndex - 1] == '_' || result[tokenIndex - 1] == '$')) {
                cursor = tokenIndex + token.length
                continue
            }
            val openParen = tokenIndex + methodName.length
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val migratedArgs = transform(args, tokenIndex)
            if (migratedArgs == null || migratedArgs == args) {
                cursor = closeParen + 1
                continue
            }
            val replacementArgs = migratedArgs.joinToString(", ") { it.trim() }
            result = result.substring(0, openParen + 1) + replacementArgs + result.substring(closeParen)
            cursor = openParen + 1 + replacementArgs.length
        }
        return result
    }

    private fun rewriteJavaNew(
        source: String,
        className: String,
        transform: (args: List<String>) -> String?
    ): String {
        var result = source
        var cursor = 0
        val token = "new $className("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            val openParen = tokenIndex + token.length - 1
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val replacement = transform(args)
            if (replacement == null) {
                cursor = closeParen + 1
                continue
            }
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            cursor = tokenIndex + replacement.length
        }
        return result
    }

    private fun rewriteSuperConstructorCalls(
        source: String,
        transform: (args: List<String>) -> String?
    ): String {
        var result = source
        var cursor = 0
        val token = "super("
        while (true) {
            val tokenIndex = result.indexOf(token, cursor)
            if (tokenIndex < 0) break
            if (tokenIndex > 0 && (result[tokenIndex - 1].isLetterOrDigit() || result[tokenIndex - 1] == '_' || result[tokenIndex - 1] == '.')) {
                cursor = tokenIndex + token.length
                continue
            }
            val openParen = tokenIndex + token.length - 1
            val closeParen = findMatchingParen(result, openParen)
            if (closeParen < 0) {
                cursor = tokenIndex + token.length
                continue
            }
            val args = splitTopLevelJavaArgs(result.substring(openParen + 1, closeParen))
            val replacement = transform(args)
            if (replacement == null) {
                cursor = closeParen + 1
                continue
            }
            result = result.substring(0, tokenIndex) + replacement + result.substring(closeParen + 1)
            cursor = tokenIndex + replacement.length
        }
        return result
    }

    private fun splitTopLevelJavaArgs(args: String): List<String> {
        val result = mutableListOf<String>()
        var start = 0
        var parenDepth = 0
        var braceDepth = 0
        var bracketDepth = 0
        var angleDepth = 0
        var inString = false
        var escaped = false
        for (i in args.indices) {
            val ch = args[i]
            if (inString) {
                escaped = ch == '\\' && !escaped
                if (ch == '"' && !escaped) inString = false
                if (ch != '\\') escaped = false
                continue
            }
            when (ch) {
                '"' -> inString = true
                '(' -> parenDepth++
                ')' -> parenDepth--
                '{' -> braceDepth++
                '}' -> braceDepth--
                '[' -> bracketDepth++
                ']' -> bracketDepth--
                '<' -> angleDepth++
                '>' -> if (angleDepth > 0) angleDepth--
                ',' -> if (parenDepth == 0 && braceDepth == 0 && bracketDepth == 0 && angleDepth == 0) {
                    result.add(args.substring(start, i))
                    start = i + 1
                }
            }
        }
        result.add(args.substring(start))
        return result.map { it.trim() }.filter { it.isNotEmpty() }
    }

